Global string &ChartStr;
Global string &ChartNum;
Global number &ChartPoints;
Global string &ChartLabel;
Global string &Chart_Flag;


Local ApiObject &MYBC;
Local ApiObject &MYSESSION;


Local string &Chart;
Local Interlink &TstPSChart_1;
Local boolean &RSLT;
Local number &EXECRSLT;
Local string &sImageFileName, &sReturnStatus, &sReturnMsg;
