Function Build_Chart(&Height As number, &Width As number, &NumPoints As number, &NumSets As number, &LabelText As string, &GraphData As string, &GraphTitle As string, &LegendPos As number, &LegendText As string, &GraphType As number, &FontSize As string) Returns string

   /* Instantiate the charting Business Interlink */

   &TstPSChart_1 = GetInterlink(Interlink.CHART_BI);

   /* set the values */


   &TstPSChart_1.AddInputRow("PropertyName", "BackgroundUse", "PropertyValue", "1");
   &TstPSChart_1.AddInputRow("PropertyName", "BackgroundStyle", "PropertyValue", "0");
   &TstPSChart_1.AddInputRow("PropertyName", "Background", "PropertyValue", "15~15~15~15~15~15~15");
   &TstPSChart_1.AddInputRow("PropertyName", "NumSets", "PropertyValue", &NumSets);
   &TstPSChart_1.AddInputRow("PropertyName", "NumPoints", "PropertyValue", &NumPoints);
   &TstPSChart_1.AddInputRow("PropertyName", "GraphTitle", "PropertyValue", &GraphTitle);
   &TstPSChart_1.AddInputRow("PropertyName", "FontUse", "PropertyValue", "0~1~2~3");
   &TstPSChart_1.AddInputRow("PropertyName", "FontSize", "PropertyValue", &FontSize);

   &TstPSChart_1.AddInputRow("PropertyName", "LabelStyle", "PropertyValue", "0");
   &TstPSChart_1.AddInputRow("PropertyName", "LabelText", "PropertyValue", &LabelText);
   &TstPSChart_1.AddInputRow("PropertyName", "LegendPos", "PropertyValue", &LegendPos);
   &TstPSChart_1.AddInputRow("PropertyName", "LegendText", "PropertyValue", &LegendText);
   &TstPSChart_1.AddInputRow("PropertyName", "GraphType", "PropertyValue", &GraphType);
   &TstPSChart_1.AddInputRow("PropertyName", "GraphData", "PropertyValue", &GraphData);
   &TstPSChart_1.AddInputRow("PropertyName", "Height", "PropertyValue", &Height);
   &TstPSChart_1.AddInputRow("PropertyName", "Width", "PropertyValue", &Width);

   /* ===> The following statement executes this instance: */
   &TstPSChart_1.StopAtError = False;
   &EXECRSLT = &TstPSChart_1.Execute();
   If (&EXECRSLT <> 1) Then
      /* The instance failed to execute */
      Hide(ST_LINK_WRK.ST_CHART_LINK);
      &CHART_VALUE = "<font face=Arial size=+1 color=Red>" | MsgGetText(1100, 791, "Charts cannot be loaded.") | "</font>";
      Return &CHART_VALUE;
   Else

      &RSLT = &TstPSChart_1.FetchNextRow("ImageFileName", &sImageFileName, "return_status", &sReturnStatus, "return_status_msg", &sReturnMsg);
      /* ===> Assigns chart imagename to a derived record referenced inside the HTML Area */

      &CHART_VALUE = "<IMG border=0 SRC=" | &sImageFileName | ">" | "</IMG>";
      Return &CHART_VALUE;


   End-If; /* If NOT &RSLT ... */


End-Function;

Function IScript_Chart()




   &numpoints = &ChartPoints;
   &Descrout = &ChartStr;
   &DataIn = &ChartNum;

   If &ChartLabel = "FSA CHART" Then

      &Chart_Flag = "Y"
   End-If;



   If &ChartStr <> "" Then

      &Chart = "<a  border=0 HREF=http://" | %Request.RequestURI | "?ICType=Panel&amp;menu=ROLE_EMPLOYEE&amp;market=GBL&amp;panelGroupName=CHART_COMPONENT>" | Build_Chart(150, 150, &ChartPoints, 1, &Descrout, &DataIn, &ChartLabel, 6, "", 2, "") | "</a><br><font size=1><i>&nbsp;&nbsp;&nbsp;&nbsp;click image for more detail";


      /*   Build_Chart(-150, -150, 3, 1, &Descrout, &DataIn, "Paycheck data", 6, &Descrout, 2, "-200~-150~-95~-150"); */

      %Response.Write("<HTML><TITLE></TITLE><BODY>" | &Chart | "</BODY></HTML>");

   End-If;

End-Function;

