REM ***************************************************************************************;
REM Function: GetPSHome()                                            		         ;
REM Purpose:  Get the path of ps application				                       ;
REM Inputs:   None                                                                          ;
REM Output:   the pathe of ps application without new window or state number               ;
REM ***************************************************************************************;
Function GetPSHome() Returns string
   Local number &pos;
   Local number &Underscore;
   Local number &LastUnderscore;
   Local string &AfterUnderscore;
   REM See if an underscore exists;
   &psHome = %Request.PathInfo;
   &pos = Find("/", &psHome, 2);
   &psHome = Left(&psHome, &pos - 1);
   &Underscore = Find("_", &psHome);

   If &Underscore <> 0 Then
      REM There maybe multiple underscores, find the last one;
      &LastUnderscore = &Underscore;
      &Underscore = Find("_", &psHome, &Underscore + 1);
      While &Underscore <> 0
         &LastUnderscore = &Underscore;
         &Underscore = Find("_", &psHome, &Underscore + 1);
      End-While;

      REM Check if there are any digits after the last underscore;
      &AfterUnderscore = Substring(&psHome, &LastUnderscore + 1, Len(&psHome) - &LastUnderscore);

      If All(&AfterUnderscore) Then
         If IsDigits(&AfterUnderscore) Then
            REM strip out the new win value and rebuild the URI;
            &psHome = Substring(&psHome, 1, &LastUnderscore - 1);
         End-If;
      End-If;
   End-If;
   Return &psHome | "/";
End-Function;

REM ***************************************************************************************;
REM Function: GetExt1()                                            		                ;
REM Purpose:  Get the extension 1 from the cookie PTCTI    	                              ;
REM Inputs:   None                                                                          ;
REM Output:   the extension 1            								  ;
REM ***************************************************************************************;
Function GetExt1() Returns string
   Local string &ext = "";
   Local string &cookiePTCTI;
   Local number &begin;
   Local number &end;
   &cookiePTCTI = %Request.GetCookieValue("PTCTI");
   If All(&cookiePTCTI) Then
      &begin = Find("ext1=", &cookiePTCTI) + 5;
      &end = Find("-ext1type=", &cookiePTCTI);
      If (&begin < &end) Then
         &ext = Substring(&cookiePTCTI, &begin, &end - &begin);
      End-If;
      rem      &ext = (&cookiePTCTI);
   End-If;
   Return &ext;
End-Function;

REM ***************************************************************************************;
REM Function: GetExt1Type()                                            		         ;
REM Purpose:  Get the extension type of extension 1 from cookie	                       ;
REM Inputs:   None                                                                          ;
REM Output:   the extension type of extension 1 					        ;
REM ***************************************************************************************;
Function GetExt1Type() Returns string
   Local string &ext = "";
   Local string &cookiePTCTI;
   Local number &begin;
   Local number &end;
   &cookiePTCTI = %Request.GetCookieValue("PTCTI");
   If All(&cookiePTCTI) Then
      &begin = Find("ext1type=", &cookiePTCTI) + 9;
      &end = Find("-ext2=", &cookiePTCTI);
      If (&begin < &end) Then
         &ext = Substring(&cookiePTCTI, &begin, &end - &begin);
      End-If;
   End-If;
   Return &ext;
End-Function;

