   &HTML = GetHTMLText(@("HTML." | &objHTML), &StyleSheetURL, &disconnectImage, &connectImage, &idleImage, &dialingDIVImage, &connectedImage, &releasedImage, &incomingImage, &answeringImage, &miniFrame, &ringingImage, &onCallImage, &idleImage, &miniConsoleExt, &callID, &confImage, &mTransferImage, &transferImage, &holdImage, &operatorID, &agentID, &noExtentions, &noLinesPerExt, &extention1, &extention2, &extention1queue, &extention2queue, &extention1type, &extention2type, &noConsoleExt, &defaultExt, &tserverHost, &tserverPort, &psHome, &logoutWhenClosed, &isCME, &appname, &apppswd, &appusername, &appuserpswd, &agentPassword, &completeURi, &referenceID, &otherDN, &optionString, &connectionString, &traceLevel, &toolsRel, &serverType, &nowDate, %Portal, %LocalNode, &msgHTML, &descr, &clearImage, &useDefaultURL, EncodeURL(&defaultURL), &modePopupWindow, &topPopupWindow, &leftPopupWindow, &heigthPopupWindow, &widthPopupWindow, &vender, &browser, MsgGetText(162, 520, "Message Not Found"), MsgGetText(162, 521, "Message Not Found"), MsgGetText(162, 522, "Message Not Found"), MsgGetText(162, 523, "Message Not Found"), MsgGetText(162, 524, "Message Not Found"), MsgGetText(162, 525, "Message Not Found"), MsgGetText(162, 516, "Message Not Found"), MsgGetText(162, 517, "Message Not Found"), MsgGetText(162, 518, "Message Not Found"), MsgGetText(162, 519, "Message Not Found"), &labelAgentID, &psDomain, &sTitle, &urlScreenPop, &tagApplet, &disconnectWarning, &urlScreenPopLoader);
