Function IScript_Extension()
   &Request = %Request;
   &Response = %Response;
   &operatorID = %UserId;

   &SQL = CreateSQL("select PT_CTI_RBURL, PT_CTI_ISDPURL, PT_CTI_DPURL from PS_PT_CTI_SYSCONF");
   If (&SQL.Fetch(&redirectURL, &useDefaultURL, &defaultURL)) Then
      &redirectURL = &redirectURL | "?cmd=start&";
   End-If;

   &labelAgentID = MsgGetText(162, 1, "Message Not Found");
   &labelQueue = MsgGetText(162, 2, "Message Not Found");
   &labelExt1 = MsgGetText(162, 3, "Message Not Found");
   &labelExt1Type = MsgGetText(162, 4, "Message Not Found");
   &labelExt2 = MsgGetText(162, 5, "Message Not Found");
   &labelExt2Type = MsgGetText(162, 6, "Message Not Found");
   &labelLine1Type = MsgGetText(162, 7, "Message Not Found");
   &labelLine2Type = MsgGetText(162, 8, "Message Not Found");
   &labelSet = MsgGetText(162, 9, "Message Not Found");
   &textQueue = MsgGetText(162, 527, "Message Not Found");
   &textDN = MsgGetText(162, 528, "Message Not Found");
   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &StyleSheetURL = %Response.GetStyleSheetURL(&strStyleSheetName);


   SQLExec("select PT_CTI_AGENTID, PT_CTI_QUEUE, PT_CTI_CONFIGID from PS_PT_CTI_AGENT A where OPRID = :1 AND EFFDT = (SELECT MAX(EFFDT) FROM PS_PT_CTI_AGENT B WHERE A.OPRID= B.OPRID AND EFFDT <= %CurrentDateIn)", &operatorID, &agentID, &agentQueue, &agentConfigID);


   SQLExec("select TOOLSREL  from PSSTATUS", &toolsRel);
   If &agentID = "" Then
      If (Find("8.4", &toolsRel) > 0) Then
         &Response.Write(MsgGetText(162, 50, "Message Not Found"));
         Return;
      End-If;
      If &redirectURL = "?cmd=start&" Then
         Return;
      End-If;
      REM      &Response.write(MsgGetText(162, 50, "Message Not Found"));
      &HTML = GetHTMLText(HTML.PT_CTI_REDIRECT, &redirectURL);
      &Response.Write(&HTML);
      Return;
   End-If;

   Local string &tagApplet;
   SQLExec("SELECT A.CTIISAPPLET FROM PS_CTICONSOLETYPE A, PS_PT_CTI_AGENT B WHERE B.OPRID=:1 AND B.PT_CTI_CONFIGID = A.PT_CTI_CONFIGID", %UserId, &isApplet);
   If (&isApplet = "N") Then
      SQLExec("select PT_CTI_EXTNUMONCON, PT_CTI_EXTNUM, PT_CTI_LINENUM from PS_CTIREN where PT_CTI_CONFIGID = :1", &agentConfigID, &noConsoleExt, &noExtentions, &noLinesPerExt);
   Else
      SQLExec("select PT_CTI_HOST, PT_CTI_PORT, PT_CTI_EXTNUMONCON, PT_CTI_EXTNUM, PT_CTI_LINENUM, PT_CTI_SWITCHNAME,PT_CTI_VENDER from PS_PT_CTI_CONFIG where PT_CTI_CONFIGID = :1", &agentConfigID, &tserverHost, &tserverPort, &noConsoleExt, &noExtentions, &noLinesPerExt, &switchType, &vendor);
   End-If;


   Evaluate &switchType
   When = "0"
      &switchType = "siemens";
   When = "1"
      &switchType = "lucent";
   When = "2"
      &switchType = "nortel";
   When = "3"
      &switchType = "aspect";
   When = "4"
      &switchType = "ipcc";
   When-Other
      &switchType = "UNKNOWN";
   End-Evaluate;

   Evaluate &vendor
   When = "0"
      &vendor = "cisco";
   When = "1"
      &vendor = "genesys";
   When-Other
      &vendor = "genesys";
   End-Evaluate;

   &extention1 = GetExt1();
   &extention2 = GetExt2();
   &extention1type = GetExt1Type();
   &extention2type = GetExt2Type();

   &msgConsoleExist = MsgGetText(162, 51, "Message Not Found");
   &sTitle = MsgGetText(162, 11, "Message Not Found");

   &SQL = CreateSQL("select PT_CTI_POPMODE,PT_CTI_POPWIND_T,PT_CTI_POPWIND_L,PT_CTI_POPWIND_H,PT_CTI_POPWIND_W,PT_CTI_FLOATCONS_T,PT_CTI_FLOATCONS_L from PS_PT_CTI_AGENTGUI WHERE OPRID = :1", &operatorID);

   If &SQL.Fetch(&modePopupWindow, &topPopupWindow, &leftPopupWindow, &heigthPopupWindow, &widthPopupWindow, &topFloatingConsole, &leftFloatingConsol) Then
   Else
      &modePopupWindow = 1;
      &topPopupWindow = 0;
      &leftPopupWindow = 0;
      &widthPopupWindow = 800;
      &heigthPopupWindow = 600;
      &topFloatingConsole = 0;
      &leftFloatingConsol = 0;
   End-If;
   &SQL.Close();

   &requestURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_SubmitExt");

   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;

   Local number &ver = Value(%Request.BrowserVersion);
   If (&Request.BrowserType = "NETSCAPE" And
         &ver < 5) Then
      &objHTML = HTML.PT_CTI_EXTSETUPNS47;
   Else
      &objHTML = HTML.PT_CTI_EXTSETUP;
   End-If;

   &HTML = GetHTMLText(@("HTML." | &objHTML), &requestURL, &Request.PathInfo, &StyleSheetURL, &agentID, &agentQueue, &extention1, &extention2, &extention1type, &extention2type, &labelAgentID, &labelQueue, &labelExt1, &labelExt1Type, &labelExt2, &labelExt2Type, &labelLine1Type, &labelLine2Type, &noExtentions, &noLinesPerExt, &labelSet, "PIA", &msgConsoleExist, MsgGet(162, 53, "Message Not Found"), &topFloatingConsole, &leftFloatingConsol, &vendor, &textQueue, &textDN, &sTitle, &psDomain);

   &Response.Write(&HTML);
End-Function;

