Function IScript_SubmitExt()
   Local string &extension1;
   Local string &extension2;
   Local string &ext1type;
   Local string &ext2type;
   Local string &cookiePTCTI;
   Local Cookie &cookie;

   &lifetime = 43200 * 360;
   &Response = %Response;
   &Request = %Request;
   &extension1 = &Request.GetParameter("PT_CTI_EXT1");
   &extension2 = &Request.GetParameter("PT_CTI_EXT2");
   &ext1type = &Request.GetParameter("PT_CTI_EXT1TYPE");
   &ext2type = &Request.GetParameter("PT_CTI_EXT2TYPE");

   &cookiePTCTI = "ext1=" | &extension1 | "-ext1type=" | &ext1type | "-ext2=" | &extension2 | "-ext2type=" | &ext2type;
   &cookie = &Response.CreateCookie("PTCTI");
   &cookie.Value = &cookiePTCTI;
   &cookie.Path = "/";
   &cookie.MaxAge = &lifetime;

   &requestURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Main");
   &Response.RedirectURL(&requestURL);

End-Function;

