Function GetJSMCAPI(&renClusterId) Returns string

   Local string &jsmcapi;
   Local string &urlAgentMain, &urlA2A, &urlBase, &urlRen, &renurlRoot, &urlTracer;
   Local number &tunnelRefreshCount;
   /* start of change for debug tracer */
   Local number &numberofallowedmsgs, &numberofsavedmsgs;
   Local string &limitlog;
   /* End of change for debug tracer */


   SQLExec("SELECT MCFREN_BROWSER_URL, REN_CLUS_ROOT_PATH FROM PSMCFRENURLID WHERE MCFREN_URL_ID=:1", &renClusterId, &urlRen, &renurlRoot);


   &urlRen = &urlRen | &renurlRoot | "/?do_method=lib";

   &urlBase = %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort;
   &urlAgentMain = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_AgentMain");
   &urlA2A = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_A2AMain");

   SQLExec("SELECT MCF_LIMITLOG,MCF_NUMSAVEMSGS,MCF_NUMALLOWEDMSGS,MCF_TRACELEVEL, PTMCFTUNNELREFRESH FROM PS_MCF_AGENTMISC WHERE MCFUQAGENTID=:1", %UserId, &limitlog, &numberofsavedmsgs, &numberofallowedmsgs, &traceLevel, &tunnelRefreshCount);

   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");
   &psHome = GetPSHome();
   Local number &MCF_CompatabilityMode;

   &sys = GetJavaClass("java.lang.System");

   try
      &MCF_CompatabilityMode = &sys.getProperty("MCF_CompatabilityMode");
   catch Exception &e
      &MCF_CompatabilityMode = 1;
   end-try;

   &jsmcapi = GetHTMLText(HTML.MCF_JSMCAPI, &urlRen, &psHome, &urlBase, &urlAgentMain, &urlA2A, &urlTracer, "", &numberofallowedmsgs, &numberofsavedmsgs, &limitlog, &traceLevel, &MCF_CompatabilityMode, &tunnelRefreshCount);
   Return &jsmcapi;
End-Function;



/* start of change for CTIMINICONSOLE and DEBUGTRACER */
Function GetCTIJSMCAPI(&renClusterId) Returns string

   Local string &jsmcapi;
   Local string &urlAgentMain, &urlA2A, &urlBase, &urlRen, &renurlRoot, &urlTracer;
   Local number &tunnelRefreshCount;

   Local number &numberofallowedmsgs, &numberofsavedmsgs;
   Local string &limitlog;


   SQLExec("SELECT MCFREN_BROWSER_URL, REN_CLUS_ROOT_PATH FROM PSMCFRENURLID WHERE MCFREN_URL_ID=:1", &renClusterId, &urlRen, &renurlRoot);


   &urlRen = &urlRen | &renurlRoot | "/?do_method=lib";

   &urlBase = %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort;
   &urlAgentMain = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_AgentMain");
   &urlA2A = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_A2AMain");

   SQLExec("SELECT MCF_LIMITLOG,MCF_NUMSAVEMSGS,MCF_NUMALLOWEDMSGS,PT_CTI_TRACELEVEL, PTCTITUNNELREFRESH FROM PS_PT_CTI_AGENT WHERE OPRID=:1", %UserId, &limitlog, &numberofsavedmsgs, &numberofallowedmsgs, &traceLevel, &tunnelRefreshCount);

   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");
   &psHome = GetPSHome();
   Local number &MCF_CompatabilityMode;

   &sys = GetJavaClass("java.lang.System");

   try
      &MCF_CompatabilityMode = &sys.getProperty("MCF_CompatabilityMode");
   catch Exception &e
      &MCF_CompatabilityMode = 1;
   end-try;

   &jsmcapi = GetHTMLText(HTML.MCF_JSMCAPI, &urlRen, &psHome, &urlBase, &urlAgentMain, &urlA2A, &urlTracer, "", &numberofallowedmsgs, &numberofsavedmsgs, &limitlog, &traceLevel, &MCF_CompatabilityMode, &tunnelRefreshCount);
   Return &jsmcapi;
End-Function;

/* End of change for CTIMINICONSOLE and DEBUGTRACER */




Function GetTPJSMCAPI(&renClusterId) Returns string

   Local string &jsmcapi;
   Local string &urlAgentMain, &urlA2A, &urlBase, &urlRen, &renurlRoot, &urlTracer;
   Local number &tunnelRefreshCount;

   /* start of change for debug tracer */
   Local number &numberofallowedmsgs, &numberofsavedmsgs;
   Local string &limitlog;
   /* End of change for debug tracer */


   SQLExec("SELECT MCFREN_BROWSER_URL, REN_CLUS_ROOT_PATH FROM PSMCFRENURLID WHERE MCFREN_URL_ID=:1", &renClusterId, &urlRen, &renurlRoot);


   &urlRen = &urlRen | &renurlRoot | "/?do_method=lib";

   &urlBase = %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort;
   &urlAgentMain = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_TPAgentMain");
   &urlGenericMain = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_GenericMain");
   &urlA2A = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_TPA2AMain");

   SQLExec("SELECT MCF_LIMITLOG,MCF_NUMSAVEMSGS,MCF_NUMALLOWEDMSGS,MCF_TRACELEVEL, PTMCFTUNNELREFRESH FROM PSMCFTPAGNTMISC WHERE MCFUQAGENTID=:1", %UserId, &limitlog, &numberofsavedmsgs, &numberofallowedmsgs, &traceLevel, &tunnelRefreshCount);


   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");
   &psHome = GetPSHome();
   Local number &MCF_CompatabilityMode;

   &sys = GetJavaClass("java.lang.System");

   try
      &MCF_CompatabilityMode = &sys.getProperty("MCF_CompatabilityMode");
   catch Exception &e
      &MCF_CompatabilityMode = 1;
   end-try;

   &jsmcapi = GetHTMLText(HTML.MCF_JSMCAPI, &urlRen, &psHome, &urlBase, &urlAgentMain, &urlA2A, &urlTracer, &urlGenericMain, &numberofallowedmsgs, &numberofsavedmsgs, &limitlog, &traceLevel, &MCF_CompatabilityMode, &tunnelRefreshCount);

   Return &jsmcapi;
End-Function;

Function IScript_Console2()
   Local string &urlCloseSession;
   Local string &urlRensrv;
   Local string &renurlRoot;
   Local string &urlTracer;
   Local string &jsmcapi;
   Local string &renClusterId;

   SQLExec("select TOOLSREL  from PSSTATUS", &toolsRel);
   &operatorID = %UserId;
   &Request = %Request;
   &miniFrame = "";
   &miniFrame = &Request.GetParameter("miniFrame");
   If (&miniFrame = "") Then
      &miniFrame = "false";
   End-If;

   &miniConsoleExt = &Request.GetParameter("extention");
   If (&miniConsoleExt = "") Then
      &miniConsoleExt = "none";
   End-If;

   &callID = &Request.GetParameter("callID");
   If (&callID = "") Then
      &callID = "none";
   End-If;

   &descr = &Request.GetParameter("descr");
   If (&descr = "") Then
      &descr = "none";
   End-If;

   &referenceID = &Request.GetParameter("referenceID");
   If (&referenceID = "") Then
      &referenceID = "none";
   End-If;

   &otherDN = &Request.GetParameter("otherDN");
   If (&otherDN = "") Then
      &otherDN = "none";
   End-If;

   &agentInstrument = GetExt1();

   &connectImage = %Response.GetImageURL(Image.CTI_CONNECT);
   &disconnectImage = %Response.GetImageURL(Image.CTI_DISCONNECT);
   &dialingDIVImage = %Response.GetImageURL(Image.CTI_DIALING);
   &connectedImage = %Response.GetImageURL(Image.CTI_CONNECTED);
   &releasedImage = %Response.GetImageURL(Image.CTI_RELEASED);
   &incomingImage = %Response.GetImageURL(Image.CTI_INCOMING);
   &answeringImage = %Response.GetImageURL(Image.CTI_ANSWERING);
   &ringingImage = %Response.GetImageURL(Image.CTI_RINGING);
   &onCallImage = %Response.GetImageURL(Image.CTI_ONCALL);
   &idleImage = %Response.GetImageURL(Image.CTI_IDLE);
   &confImage = %Response.GetImageURL(Image.CTI_CONFERENCING);
   &mTransferImage = %Response.GetImageURL(Image.CTI_MUTETRANSFER);
   &transferImage = %Response.GetImageURL(Image.CTI_TRANSFERRING);
   &holdImage = %Response.GetImageURL(Image.CTI_HOLD);
   &clearImage = %Response.GetImageURL(Image.PT_PORTAL_CLEAR_DOT);
   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &StyleSheetURL = %Response.GetStyleSheetURL(&strStyleSheetName);

   SQLExec("select PT_CTI_AGENTID, PT_CTI_QUEUE, PT_CTI_CONFIGID,PT_CTI_PASSWORD, PT_CTI_APPUSERNAME, PT_CTI_APPUSERPSWD, PT_CTI_CLIENTSIG,PT_CTI_TRACELEVEL from PS_PT_CTI_AGENT A where OPRID = :1 AND EFFDT = (SELECT MAX(EFFDT) FROM PS_PT_CTI_AGENT B WHERE A.OPRID= B.OPRID AND EFFDT <= %CurrentDateIn)", &operatorID, &agentID, &agentQueue, &agentConfigID, &agentPassword, &appusername, &appuserpswd, &clientSig, &traceLevel);

   SQLExec("select PT_CTI_HOST, PT_CTI_PORT, PT_CTI_EXTNUMONCON, PT_CTI_EXTNUM, PT_CTI_LINENUM, PT_CTI_ISCME,PT_CTI_TSATYPE, PT_CTI_APPNAME, PT_CTI_APPPASSWORD, PT_CTI_SWITCHNAME,PT_CTI_VENDER from PS_PT_CTI_CONFIG where PT_CTI_CONFIGID = :1", &agentConfigID, &tserverHost, &tserverPort, &noConsoleExt, &noExtentions, &noLinesPerExt, &isCME, &typeTServerAddress, &appname, &apppswd, &serverType, &vender);

   /* Select info from CONFIG table while vender is "cisco" */
   SQLExec("select PT_CTI_HOST, PT_CTI_PORT, PT_CTI_HOSTB, PT_CTI_PORTB, PT_CTI_HEARTBEAT, PT_CTI_PERIPHERAL, PT_CTI_SERVICEREQ, PT_CTI_CALLPROG, PT_CTI_AGENTSTATE, PT_CTI_CALLCONTROL, PT_CTI_OTHERFM, PT_CTI_TCSM, PT_CTI_CALLVAR, PT_CTI_PROTOCOL from PS_PT_CTI_CONFIG where PT_CTI_CONFIGID = :1 AND PT_CTI_VENDER = '0'", &agentConfigID, &hostA, &portA, &hostB, &portB, &heartBeat, &peripheralID, &svcReqMask, &callProgressMask, &agentStateMask, &callControlMasks, &otherFeatureMasks, &tranConfSetupMasks, &callVariableMask, &protocolVer);

   SQLExec("select PT_CTI_EXTNUMONCON, PT_CTI_EXTNUM, PT_CTI_LINENUM from PS_CTIREN where PT_CTI_CONFIGID = :1", &agentConfigID, &noConsoleExt, &noExtentions, &noLinesPerExt);

   Evaluate &serverType
   When = "0"
      &serverType = "siemens";
   When = "1"
      &serverType = "lucent";
   When = "2"
      &serverType = "nortel";
   When = "3"
      &serverType = "aspect";
   When = "4"
      &serverType = "ipcc";
   When-Other
      &serverType = "UNKNOWN";
   End-Evaluate;

   If &isCME = "Y" Then
      &isCME = "true";
   Else
      &isCME = "false";
   End-If;

   Evaluate &vender
   When = "0"
      &vender = "cisco";
   When = "1"
      &vender = "genesys";
   When-Other
      &vender = "genesys";
   End-Evaluate;

   If &noExtentions = 1 Then
      &extention1 = GetExt1() | "_0";
      &extention2 = GetExt1() | "_1";
      &extention1type = GetExt1Type();
      &extention2type = GetExt2Type();
      If &extention1type = "QUEUE" Then
         &extention1queue = &agentQueue;
         &extention2queue = "none";
      Else
         &extention1queue = "none";
         &extention2queue = "none";
      End-If;
   Else
      &extention1 = GetExt1();
      &extention2 = GetExt2();
      &extention1type = GetExt1Type();
      &extention2type = GetExt2Type();
      If &extention1type = "QUEUE" Then
         &extention1queue = &agentQueue;
      Else
         &extention1queue = "none";
      End-If;
   End-If;

   rem	&noConsoleExtentions = 2;
   &noConsoleExt = 2;
   &defaultExt = &extention1;
   rem	&connID = "none";

   &completeURi = &Request.Scheme | "://" | &Request.ServerName | ":" | &Request.ServerPort | &Request.RequestURI;
   &completeURi = &Request.FullURI;

   &psHome = GetPSHome();

   If (&vender = "genesys") Then
      &connectionString = "host=" | &tserverHost | ";" | "port=" | &tserverPort | ";" | "isCfgServer=" | &isCME | ";" | "tsaType=" | &typeTServerAddress | ";" | "applName=" | &appname | ";" | "applPW=" | &apppswd | ";" | "applUserName=" | &appusername | ";" | "applUserPW=" | &appuserpswd | ";" | "timeOut=30";
   Else
      &connectionString = "hostA=" | &hostA | ";" | "portA=" | &portA | ";" | "hostB=" | &hostB | ";" | "portB=" | &portB | ";" | "heartBeat=" | &heartBeat | ";" | "peripheralID=" | &peripheralID | ";" | "serviceReqMask=" | &svcReqMask | ";" | "callProgressMask=" | &callProgressMask | ";" | "agentStateMask=" | &agentStateMask | ";" | "callControlMasks=" | &callControlMasks | ";" | "otherFeatureMasks=" | &otherFeatureMasks | ";" | "transferConferenceSetupMasks=" | &tranConfSetupMasks | ";" | "callVariableMask=" | &callVariableMask | ";" | "clientSignature=" | &clientSig | ";" | "agentInstrument=" | &agentInstrument | ";" | "appUserName=" | &appusername | ";" | "appUserPwd=" | &appuserpswd | ";" | "agentID=" | &agentID | ";" | "agentPW=" | &agentPassword | ";" | "protocolVersion=" | &protocolVer;
   End-If;

   &SQL = CreateSQL("select PT_CTI_PHONENUMBER, PT_CTI_PNTYPE, PT_CTI_PNDES from PS_PT_CTI_PBKAGENT WHERE OPRID = :1", &operatorID);
   &optionString = "";
   While &SQL.Fetch(&phoneNumber, &pnType, &pnDes)
      &pnShow = &pnType | "-" | &pnDes | "-" | &phoneNumber;
      &pnShow = Left(&pnShow, 20);
      &optionString = &optionString | GetHTMLText(HTML.PT_CTI_FAVNUM, &phoneNumber, &pnShow);
   End-While;

   &SQL = CreateSQL("select PT_CTI_PHONENUMBER,PT_CTI_PNTYPE,PT_CTI_PNDES from PS_PT_CTI_PBKCTI WHERE PT_CTI_CONFIGID = :1", &agentConfigID);

   While &SQL.Fetch(&phoneNumber, &pnType, &pnDes)
      &pnShow = &pnType | "-" | &pnDes | "-" | &phoneNumber;
      &pnShow = Left(&pnShow, 20);
      &optionString = &optionString | GetHTMLText(HTML.PT_CTI_FAVNUM, &phoneNumber, &pnShow);
   End-While;

   &nowDate = &Request.GetParameter("nowDate");
   If (&nowDate = "") Then
      &nowDate = "none";
   End-If;

   &SQL = CreateSQL("select PT_CTI_RBURL, PT_CTI_ISDPURL, PT_CTI_DPURL from PS_PT_CTI_SYSCONF");
   If (&SQL.Fetch(&redirectURL, &useDefaultURL, &defaultURL)) Then
      If &useDefaultURL = "Y" Then
         &useDefaultURL = "true";
      Else
         &useDefaultURL = "false";
      End-If;
   End-If;
   &SQL.Close();
   If (&useDefaultURL <> "true") Then
      &useDefaultURL = "false";
   End-If;

   &SQL = CreateSQL("select PT_CTI_POPMODE,PT_CTI_POPWIND_T,PT_CTI_POPWIND_L,PT_CTI_POPWIND_H,PT_CTI_POPWIND_W,PT_CTI_FLOATCONS_T,PT_CTI_FLOATCONS_L from PS_PT_CTI_AGENTGUI WHERE OPRID = :1", &operatorID);
   If &SQL.Fetch(&modePopupWindow, &topPopupWindow, &leftPopupWindow, &heigthPopupWindow, &widthPopupWindow, &topFloatingConsole, &leftFloatingConsol) Then
   Else
      &modePopupWindow = 1;
      &topPopupWindow = 0;
      &leftPopupWindow = 0;
      &widthPopupWindow = 800;
      &heigthPopupWindow = 600;
      &topFloatingConsole = 0;
      &leftFloatingConsol = 0;
   End-If;
   &SQL.Close();

   SQLExec("SELECT CTI_AUTOLOGOUT FROM PS_CTI_PERSONAL WHERE OPRID=:1", %UserId, &logoutWhenClosed);
   If (&logoutWhenClosed = "Y") Then
      &logoutWhenClosed = "true";
   Else
      &logoutWhenClosed = "false";
   End-If;

   &labelAgentID = MsgGetText(162, 1, "Message Not Found");
   &sTitle = MsgGetText(162, 10, "Message Not Found");

   &msgHTML = GetHTMLText(HTML.PT_CTI_MSGCONSOLE, MsgGetText(162, 500, "Message Not Found"), MsgGetText(162, 501, "Message Not Found"), MsgGetText(162, 502, "Message Not Found"), MsgGetText(162, 503, "Message Not Found"), MsgGetText(162, 504, "Message Not Found"), MsgGetText(162, 505, "Message Not Found"), MsgGetText(162, 506, "Message Not Found"), MsgGetText(162, 507, "Message Not Found"), MsgGetText(162, 508, "Message Not Found"), MsgGetText(162, 509, "Message Not Found"), MsgGetText(162, 510, "Message Not Found"), MsgGetText(162, 511, "Message Not Found"), MsgGetText(162, 512, "Message Not Found"), MsgGetText(162, 513, "Message Not Found"), MsgGetText(162, 514, "Message Not Found"), MsgGetText(162, 515, "Message Not Found"), MsgGetText(162, 600, "Message Not Found"), MsgGetText(162, 601, "Message Not Found"), MsgGetText(162, 602, "Message Not Found"), MsgGetText(162, 603, "Message Not Found"), MsgGetText(162, 604, "Message Not Found"), MsgGetText(162, 605, "Message Not Found"), MsgGetText(162, 606, "Message Not Found"), MsgGetText(162, 607, "Message Not Found"), MsgGetText(162, 608, "Message Not Found"), MsgGetText(162, 609, "Message Not Found"), MsgGetText(162, 526, "Message Not Found"));

   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;

   &urlCloseSession = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_CloseJSMCAPISession");

   SQLExec("SELECT A.MCFREN_BROWSER_URL, A.REN_CLUS_ROOT_PATH FROM PSMCFRENURLID A, PS_CTIREN B WHERE B.PT_CTI_CONFIGID=:1 AND A.MCFREN_URL_ID=B.MCFREN_URL_ID", &agentConfigID, &urlRensrv, &renurlRoot);

   SQLExec("SELECT MCFREN_URL_ID FROM PS_CTIREN WHERE PT_CTI_CONFIGID=:1 ", &agentConfigID, &renClusterId);

   &urlRensrv = &urlRensrv | &renurlRoot | "/?do_method=lib";

   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");

   &urlScreenPop = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_ScreenPop");
   &disconnectWarning = MsgGetText(162, 55, "Message Not Found");
   &urlScreenPopLoader = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_ScreenPopLoader");

   &jsmcapi = GetCTIJSMCAPI(&renClusterId);

   &HTML = GetHTMLText(HTML.CTI_CONSOLE2, &StyleSheetURL, &disconnectImage, &connectImage, &idleImage, &dialingDIVImage, &connectedImage, &releasedImage, &incomingImage, &answeringImage, &miniFrame, &ringingImage, &onCallImage, &idleImage, &miniConsoleExt, &callID, &confImage, &mTransferImage, &transferImage, &holdImage, &operatorID, &agentID, &noExtentions, &noLinesPerExt, &extention1, &extention2, &extention1queue, &extention2queue, &extention1type, &extention2type, &noConsoleExt, &defaultExt, &tserverHost, &tserverPort, &psHome, &logoutWhenClosed, &isCME, &appname, &apppswd, &appusername, &appuserpswd, &agentPassword, &completeURi, &referenceID, &otherDN, &optionString, &connectionString, &traceLevel, &toolsRel, &serverType, &nowDate, %Portal, %LocalNode, &msgHTML, &descr, &clearImage, &useDefaultURL, EncodeURL(&defaultURL), &modePopupWindow, &topPopupWindow, &leftPopupWindow, &heigthPopupWindow, &widthPopupWindow, &vender, "netscape", MsgGetText(162, 520, "Message Not Found"), MsgGetText(162, 521, "Message Not Found"), MsgGetText(162, 522, "Message Not Found"), MsgGetText(162, 523, "Message Not Found"), MsgGetText(162, 524, "Message Not Found"), MsgGetText(162, 516, "Select Call Action"), MsgGetText(162, 517, "Select Phone Numbers"), MsgGetText(162, 518, "Message Not Found"), MsgGetText(162, 519, "Message Not Found"), &labelAgentID, &psDomain, &sTitle, %Request.RemoteAddr, &urlRensrv, &urlTracer, &urlScreenPop, &disconnectWarning, &jsmcapi, &urlCloseSession, &urlScreenPopLoader);
   %Response.Write(&HTML);
End-Function;

Function IScript_Tracer()
   &sTitle = MsgGetText(162, 12, "Message Not Found");
   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &StyleSheetURL = %Response.GetStyleSheetURL(&strStyleSheetName);
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &HTML = GetHTMLText(HTML.CTI_TRACER, &sTitle, &StyleSheetURL, &psDomain);
   %Response.Write(&HTML);
End-Function;

Function IScript_ScreenPop()
   Local string &urlConsole;
   Local string &extention;
   Local string &tservers;
   Local string &mcf_miniconsole; /* Added for CTI MINICONSOLE */
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &portal = %Request.GetParameter("portal");
   If &portal = "" Then
      &portal = %Portal;
   End-If;
   &node = %Request.GetParameter("node");
   If &node = "" Then
      &node = %Node;
   End-If;
   &menu = %Request.GetParameter("menu");
   &market = %Request.GetParameter("Market");
   &component = %Request.GetParameter("Component");
   &actiontype = "U";

   &urlAppPage = GenerateComponentPortalRelURL(&portal, &node, @("MenuName." | &menu), &market, @("Component." | &component), @("Page." | &page), &actiontype);

   &urlAppPage = &urlAppPage | "&OPRID=QEDMO&PortalKeyStruct=YES";

   &urlConsole = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Main");

   &urlAppPage = %Request.GetParameter("actualURL");
   &urlAppPage = Unencode(&urlAppPage);

   &extention = %Request.GetParameter("extention");
   &modePopupWindow = Value(%Request.GetParameter("modePopupWindow"));

   &urlConsole = &urlConsole | "?&miniFrame=true" | "&extention=" | &extention;

   If (All(&modePopupWindow)) Then

      &urlConsole = &urlConsole | "&modePopupWindow=" | &modePopupWindow;
   End-If;


   /* Start of code for CTI MINICONSOLE */
   SQLExec("SELECT MCF_MINICONSOLE FROM PS_PT_CTI_AGENTGUI WHERE OPRID=:1 ", %UserId, &mcf_miniconsole);
   If (&mcf_miniconsole = "N") Then
      &HTML = GetHTMLText(HTML.CTI_SCREENPOP_NOMINICONSOLE, &sTitle, &psDomain, &urlAppPage);
   Else
      &HTML = GetHTMLText(HTML.CTI_SCREENPOPMAIN, &sTitle, &psDomain, &urlAppPage, &urlConsole);
   End-If;
   /*End of code for CTI MINICONSOLE */

   %Response.Write(&HTML);

End-Function;

Function IScript_Test()
   &URL = GenerateComponentContentRelURL(%Portal, %Node, MenuName.PT_MCF, "GBL", Component.MCF_AGENT_CMP, Page.MCF_AGENT_PG, "U");
   %Response.RedirectURL(&URL | "&MCFUQAGENTID=QEDMO");
End-Function;

Function IScript_ScreenPopLoader()
   &sTitle = MsgGetText(162, 12, "Message Not Found");
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &condText = MsgGetText(162, 608, "Message Not Found");

   &HTML = GetHTMLText(HTML.CTI_SCREENPOPLOADER, &sTitle, &psDomain, &condText);
   %Response.Write(&HTML);
End-Function;

