Function IScript_SampleC()
   Local string &1psDomain, &2psHome;
   Local string &3MainTitle, &4SessionHeader, &5SessionIdLbl, &6SessionMessageTxt, &7StateLbl, &8OpenTxt, &9CloseTxt;

   Local string &10UserHeader, &11UserIdLbl, &12RegisterTxt, &13UnregisterTxt, &14NameLbl, &15PasswordLbl, &16LanguageLbl, &17LanguageTxt;
   Local string &18StatisticsLbl, &19AgentStatTxt;

   Local string &20GroupHeader, &21GroupIdLbl, &22LoginTxt, &23LogoutTxt, &24PresenceLbl, &25MediaTypeLbl, &26TelphoneLbl;
   Local string &27GroupStatTxt;

   Local string &28AddressHeader, &29ExtensionLbl, &30PhoneNumLbl, &31ForwardLbl, &32DNDLbl;
   Local string &33Line1Lbl, &34DialTxt, &35UserDataLbl, &36CallDataLbl, &37CallStatTxt, &38Line2Lbl;

   Local string &39BuddiesHeader;
