   Local string &47GoBtnTxt, &48Name1Txt, &49Value1Txt, &50Name2Txt, &51Value2Txt, &52Name3Txt, &53Value3Txt;
   Local string &54Txt1, &55Txt2, &56ReasonTxt, &57ReasonCodeTxt, &58ReasonDescTxt, &59ErrPrefixTxt;

   Local string &60Dial1Txt, &61AnswerTxt, &62HoldTxt, &63ReleaseTxt, &64RetrieveTxt, &65ReconnectTxt, &66ConferenceTxt;
   Local string &67ConferenceSTxt, &68TransferTxt, &69TransferMTxt, &70ClearTxt, &71CompleteTxt, &72ParkTxt, &73AttachUDataTxt, &74AttachCDataTxt;


   Local string &75ReadyTxt, &76NReadyTxt, &77WReadyTxt, &78WNReadyTxt;
   Local string &79AddressStateErrTxt, &80SessionErrTxt, &81UserErrTxt, &82LineErrTxt, &83LineActionErrTxt, &84GroupErrTxt;
   Local string &85UserLoginErrTxt, &86UserWorkErrTxt, &87BuddyErrTxt, &88PhoneNumErrTxt, &89ExtRegErrTxt, &90UserRegErrTxt;
   Local string &91MediaErrTxt, &92GroupRegErrTxt, &93ExtIdErrTxt, &94UserLoggedErrTxt, &95GroupIdErrTxt, &96AgentIdErrTxt;

   Local string &97UpTxt, &98DownTxt;
   Local string &110SetcallResultDNCTxt, &111SetcallResultRescheduleTxt, &112SetCallResultTxt, &113AlternateTxt, &114SendDTMFTxt, &115RejectTxt, &116CallResultTxt, &117DTMFInfoTxt, &118ReScheduleTimeTxt, &119TimeTxt, &120HoursTxt, &121MinutesTxt, &122TypeTxt, &123CampaignTxt, &124SameTxt, &125DateTxt, &126DateTxt;
