/*  MCF Console Link for Fluid */
Function DisplayMCFConsole Returns string
   Local boolean &isMCFConfigured, &isCTIConfigured;
   Local string &agentID, &agentQueue, &agentConfigID, &MCFRelativeURL, &wType, &wPopMode, &wAcceptMode, &tmpAgentID;
   Local integer &topFloatingConsole = 0;
   Local integer &leftFloatingConsole = 0;
   Local integer &widthFloatingConsole = 1020;
   Local integer &heightFloatingConsole = 150;
   Local string &popUpMode = "M";


   If IsUserInPermissionList("PTPT4700") Then
      /* determine if configured */
      SQLExec("select PT_CTI_AGENTID, PT_CTI_QUEUE, PT_CTI_CONFIGID from PS_PT_CTI_AGENT A where OPRID = :1 AND EFFDT = (SELECT MAX(EFFDT) FROM PS_PT_CTI_AGENT B WHERE A.OPRID= B.OPRID AND EFFDT <= %CurrentDateIn)", %UserId, &agentID, &agentQueue, &agentConfigID);
      &SQL = CreateSQL("select MCFUQAGENTID from PSMCFUQAGENTQ WHERE MCFUQAGENTID = :1", %UserId);
      If (&SQL.Fetch(&tmpAgentID)) Then
         &isMCFConfigured = True;
      Else
         &isMCFConfigured = False;
      End-If;
      &SQL.Close();
      If (&agentID <> "") Then
         &isCTIConfigured = True;
      Else
         &isCTIConfigured = False;
      End-If;

      If Not (&isCTIConfigured) And
            Not (&isMCFConfigured) Then
         Return ""; /*  do not display console link if user is not an agent */
      End-If;

      If &isMCFConfigured Then
         &SQL = CreateSQL("select MCFTOP, MCFLEFT, MCFWIDTH, MCFHEIGHT, MCFPOPUP_MODE from PS_MCFAGENTCUST WHERE MCFUQAGENTID = :1 AND MCFTYPE=:2", %UserId, "M");
         If (&SQL.Fetch(&wTop, &wLeft, &wWidth, &wHeight, &wPopMode)) Then
            &topFloatingConsole = &wTop;
            &leftFloatingConsole = &wLeft;
            &widthFloatingConsole = &wWidth;
            &heightFloatingConsole = &wHeight;
            &popUpMode = &wPopMode;
         End-If;
         &SQL.Close();
      End-If;

      Local string &sMCFJS = "PopupMCFConsole(" | &topFloatingConsole | ", " | &leftFloatingConsole | ", " | &widthFloatingConsole | ", " | &heightFloatingConsole | ", '" | &popUpMode | "')";
      If All(&sMCFJS) Then
         If (&isMCFConfigured) Then
            /* MCF is configured or both MCF and CTI */
            Return &sMCFJS;
         Else
            If &isCTIConfigured Then
               /* CTI console only */
               &SQL = CreateSQL("select PT_CTI_FLOATCONS_T, PT_CTI_FLOATCONS_L from PS_PT_CTI_AGENTGUI WHERE OPRID = :1", %UserId);
               If &SQL.Fetch(&topFloatingConsole, &leftFloatingConsole) Then
               Else
                  &topFloatingConsole = 0;
                  &leftFloatingConsole = 0;
               End-If;
               &SQL.Close();
               &widthFloatingConsole = 1024;
               &heightFloatingConsole = 42;
               &sMCFJS = "PopupCTIConsole(" | &topFloatingConsole | ", " | &leftFloatingConsole | ", " | &widthFloatingConsole | ", " | &heightFloatingConsole | ")";
               Return &sMCFJS;
            End-If; /* CTI config check */
         End-If; /* MCF config check */
      End-If; /* MCF string check */
   End-If; /* Permission list check */

   Return ""; /* no permission */
End-Function; /* DisplayMCFConsole */

/* END MCF Console Link */

