   &returnURL = GenerateComponentContentURL(%Portal, %Node, MenuName.EOAW_APPROVAL_WORKFLOW, "GBL", Component.EOAW_PRCS, "", "U") | "&EOAWPRCS_ID=" | &EOAWPRCS_ID | "&EOAWDEFN_ID=" | &EOAWDEFN_ID | "&EFFDT=" | &EFFDT;
   &html = GetHTMLText(HTML.EOAW_AP_BUILDER_SVG_CALLER, &adobeJavaScript, &svgGenerator, &height, &width, &returnURL, MsgGetText(18081, 16, "Message Not Found"), &EOAWPRCS_IDLabel, &EOAWPRCS_ID, &SETIDLabel, &EOAWDEFN_ID, &EFFDTLabel, &EFFDT, &instrText);
   %Response.Write(&html);
End-Function;

Function IScript_EOAW_BUILDER_SVG
   &EOAWPRCS_ID = %Request.GetParameter("EOAWPRCS_ID");
   &EOAWDEFN_ID = %Request.GetParameter("EOAWDEFN_ID");
   &EFFDT = %Request.GetParameter("EFFDT");
   &newDt = Substitute(&EFFDT, "-", "");
   &builder = create EOAW_AP_BUILDER:SVG_OBJECTS:awBuilder(&EOAWPRCS_ID, &EOAWDEFN_ID, Date(Int(&newDt)));

   &startingStage = %Request.GetParameter("CURRENTSTAGE");
   &startingPath = %Request.GetParameter("CURRENTPATH");
   &startingStep = %Request.GetParameter("CURRENTSTEP");
   &builder.startingStage = Int(&startingStage);
   &builder.startingPath = Int(&startingPath);
   &builder.startingStep = Int(&startingStep);
   &svg = &builder.outputSVG();
   rem &svg = GetHTMLText(HTML.EOAW_SVG_TEST);
   %Response.Write(&svg);
End-Function;

If %Mode = "A" Then
   WEBLIB_EOAW.EOAW_AP_BUILDER.Visible = False;
End-If;

import EOAW_MONITOR:ADHOC_OBJECTS:*;

Declare Function getUserName PeopleCode FUNCLIB_EOAW.STRING_FUNCTIONS FieldFormula;
Declare Function isEven PeopleCode FUNCLIB_EOAW.EOAWNUM_FUNCTIONS FieldFormula;

Global EOAW_MONITOR:ADHOC_OBJECTS:adhocStateObj &adhocStateObj;

Function userIDIsValid()
   If &adhocStateObj.userList <> Null Then
      &uListArray = &adhocStateObj.userList.GetUsers(CreateArrayRept("", 0), &adhocStateObj.adhocPoolThreadRecs [&adhocStateObj.adhocPoolThreadIDs.Find(&adhocStateObj.thread)]);
   Else
      SQLExec("SELECT OPRID FROM PSOPRDEFN WHERE OPRID = :1", &adhocStateObj.oprID, &oprIDTest);
      &uListArray = CreateArray(&oprIDTest)
   End-If;

   If &uListArray.find(&adhocStateObj.oprID) <> 0 Then
      &userNameResolved = getUserName(&adhocStateObj.oprID);
   Else
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Entry") | "?INVALIDOPRID=TRUE";
      %Response.RedirectURL(&URL);
      Exit;
   End-If;
End-Function;

Function IScript_Adhoc_Entry
   &StyleSheetURL = %Response.GetStyleSheetURL(StyleSheet.PSSTYLEDEF_TANGERINE);

   /*If 1st time running script, create adhoc state object*/
   If %Request.GetParameter("START") = "TRUE" Then
      If (&adhocStateObj = Null) Then
         Return;
      End-If;
      rem &adhocStateObj = create EOAW_MONITOR:ADHOC_OBJECTS:adhocStateObj( Null);
      &adhocStateObj.reInit();
      &temp = %Request.GetParameter("STEPTOINSERTBEFORE");
      &adhocStateObj.stepBefore = Value(&temp);
      &temp = %Request.GetParameter("STEPTOINSERTAFTER");
      &adhocStateObj.stepAfter = Value(&temp);
      &adhocStateObj.adhocPosition = %Request.GetParameter("ADHOCPOSITION");
      &adhocStateObj.stage = Value(%Request.GetParameter("STAGE"));
      &adhocStateObj.thread = Value(%Request.GetParameter("THREAD"));
   End-If;

   /*Get threadId from step if threadId did not come from URL*/
   If &adhocStateObj.thread = 0 Then
      &stepToFind = &adhocStateObj.stepBefore;
      If None(&stepToFind) Then
         &stepToFind = &adhocStateObj.stepAfter;
      End-If;
      SQLExec("SELECT EOAWTHREAD_ID FROM PS_EOAW_STEPINST WHERE EOAWSTEP_INSTANCE = :1", &stepToFind, &tempThread);
      &adhocStateObj.thread = &tempThread;
   End-If;

   Evaluate &adhocStateObj.adhocType
   When "approver"
      &approverRadioChecked = "checked";
      &reviewerRadioChecked = "";
   When "reviewer"
      &reviewerRadioChecked = "checked";
      &approverRadioChecked = "";
   When-Other
      &reviewerRadioChecked = "";
      &approverRadioChecked = "";
   End-Evaluate;

   &formActionURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Form_Proc");
   &lookupButtonURL = %Response.GetImageURL(Image.PT_PROMPT_LOOKUP);

   If %Request.AuthTokenDomain <> "" Then
      &html = "<script language=javascript>document.domain = '" | Right(%Request.AuthTokenDomain, Len(%Request.AuthTokenDomain) - 1) | "';</script>";
   End-If;
   &html = &html | "<link rel='stylesheet' type='text/css' href='" | &StyleSheetURL | "' />" | Char(13);
   &html = &html | GetHTMLText(HTML.EOAW_MON_ADHOC_FORM_PROC, "adhocEntry");
   &html = &html | GetHTMLText(HTML.EOAW_PROCESSING_SCRIPT);
   /*&html = &html | "<div id=""processingText"" name=""processingText"" style=""font-size:16pt;color:red;font-family:Arial,Helvetica,sans-serif;position:absolute;right:0;display:none;""><blink>Processing...</blink></div>" | Char(13);*/
   &html = &html | "<div id='processingText' name='processingText' style='position:absolute;right:0;display:none;'><img border='0' src=" | %Response.GetImageURL(Image.PT_PROCESSING) | " alt='" | MsgGetText(124, 173, "Processing, please wait") | "'> </div>" | Char(13);

   Evaluate &adhocStateObj.adhocPosition
   When "serial"
      &pageTitle = MsgGetText(18081, 4057, "Message Not Found - Insert additional approver or reviewer");
   When "parallel"
      &pageTitle = MsgGetText(18081, 4056, "Message Not Found - Start new approval path");
   End-Evaluate;
   &html = &html | "<br /><span class=""PATRANSACTIONTITLE"">" | &pageTitle | "</span>";

   /*Validate oprID on tab out and throw error if not valid*/
   If &adhocStateObj.oprID <> "" And
         %Request.GetParameter("INVALIDOPRID") <> "TRUE" Then
      userIDIsValid();
   End-If;

   &lookupDoneHRef = "javascript:procForm('lookupDone')";
   &html = &html | GetHTMLText(HTML.EOAW_ADHOC_ENTRY_FORM, &formActionURL, &adhocStateObj.oprID, &lookupButtonURL, &approverRadioChecked, &reviewerRadioChecked, MsgGetText(18081, 4053, "Message Not Found - Choose an approver or reviewer to insert"), MsgGetText(18081, 4054, "Message Not Found - User Name"), MsgGetText(124, 133, "Message Not Found - Look Up"), MsgGetText(18081, 4055, "Message Not Found - Insert as"), MsgGetText(18081, 4062, "Message Not Found - Approver"), MsgGetText(18081, 4032, "Message Not Found - Reviewer"), MsgGetText(18081, 4063, "Message Not Found - Insert"), &userNameResolved, &lookupDoneHRef, MsgGetText(18081, 4060, "Message Not Found - Cancel"));


   If %Request.GetParameter("NOOPRID") = "TRUE" Then
      &html = &html | "<br /><br /><center><div class='PAERRORTEXT' style='font-weight:bold;'>" | MsgGetText(18081, 4039, "Message Not Found", "<img src=""" | &lookupButtonURL | """>") | "</div></center>" | Char(13);
   End-If;

   If %Request.GetParameter("INVALIDOPRID") = "TRUE" Then
      &html = &html | "<br /><br /><center><div class='PAERRORTEXT' style='font-weight:bold;'>" | &adhocStateObj.oprID | " " | MsgGetText(18081, 4040, "Message Not Found", "<img src=""" | &lookupButtonURL | """>") | "</div></center>" | Char(13);
   End-If;

   %Response.Write(&html);
End-Function;








Function buildNameSearchArray(&oprNameSrchString As string) Returns array of string
   &oprNameSrchString = RTrim(&oprNameSrchString);
   &oprNameSrchString = LTrim(&oprNameSrchString);
   &oprNameSrchString = Substitute(&oprNameSrchString, ", ", " ");
   &oprNameSrchString = Substitute(&oprNameSrchString, ",", " ");
   &namesArray = CreateArrayRept("", 0);
   If Len(&oprNameSrchString) > 0 Then
      If Find(" ", &oprNameSrchString) <> 0 Then
         &continueLooping = True;
         &startPosition = 1;
         While &continueLooping > 0
            &endPosition = Find(" ", &oprNameSrchString) - 1;
            If &endPosition = - 1 Then
               &endPosition = Len(&oprNameSrchString);
               &continueLooping = False;
            End-If;
            &loopName = Substring(&oprNameSrchString, &startPosition, &endPosition);
            &oprNameSrchString = Substring(&oprNameSrchString, Find(" ", &oprNameSrchString) + 1, Len(&oprNameSrchString));
            &loopName = Substitute(&loopName, "'", "''");
            &namesArray.push(&loopName);
         End-While;
      Else
         &namesArray.push(&oprNameSrchString);
      End-If;
   End-If;
   Return &namesArray;
End-Function;


Function IScript_Adhoc_Lookup
   Local Record &adhocInfoRecord;
   Local string &oprNameSrchString;
   Local string &searchNameContainsChecked, &searchNameBeginsChecked, &searchOprContainsChecked, &searchOprBeginsChecked;

   REM -- changed to 9.2 default style;
   REM &StyleSheetURL = %Response.GetStyleSheetURL(StyleSheet.PSSTYLEDEF_SWAN);
   &StyleSheetURL = %Response.GetStyleSheetURL(StyleSheet.PSSTYLEDEF_TANGERINE);
   &formActionURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Form_Proc");
   /*
   &searchButton = "<a href=""javascript:procForm('lookup');"" title='" | MsgGetText(18081, 4059, "Message Not Found - Search") | "'><img src='" | %Response.GetImageURL(Image.PT_SEARCH) | "' border='0'></a>";
   &clearButton = "<a href=""javascript:document.adhocLookup.oprIDSrchString.value='';document.adhocLookup.oprNameSrchString.value='';procForm('lookup');"" title='" | MsgGetText(18081, 4064, "Message Not Found - Clear") | "'><img src='" | %Response.GetImageURL(Image.PT_CLEAR) | "' border='0'></a>";
   &cancelButton = "<a href=""javascript:procForm('lookupCancel');"" title='" | MsgGetText(18081, 4060, "Message Not Found - Cancel") | "'><img src='" | %Response.GetImageURL(Image.PT_CANCEL) | "' border='0'></a>";
   */
   &searchButton = "<a role=""presentation"" class=""PSPUSHBUTTON Left""><span style=""background-Color: transparent;""><input value=" | MsgGetText(18081, 4059, "Message Not Found - Search") | " class=""PSPUSHBUTTON"" style=""width:44px; "" onclick=""javascript:procForm('lookup');"" type=""button""></span></a>";
   &clearButton = "<a role=""presentation"" class=""PSPUSHBUTTON Left""><span style=""background-Color: transparent;""><input value=" | MsgGetText(18081, 4064, "Message Not Found - Clear") | " class=""PSPUSHBUTTON"" style=""width:44px; "" onclick=""javascript:document.adhocLookup.oprIDSrchString.value='';document.adhocLookup.oprNameSrchString.value='';procForm('lookup');"" type=""button""></span></a>";
   &cancelButton = "<a role=""presentation"" class=""PSPUSHBUTTON Left""><span style=""background-Color: transparent;""><input value=" | MsgGetText(18081, 4060, "Message Not Found - Cancel") | " class=""PSPUSHBUTTON"" style=""width:44px; "" onclick=""avascript:procForm('lookupCancel');"" type=""button""></span></a>";

   Evaluate &adhocStateObj.adhocNameSrchType
   When "contains"
      &searchNameContainsChecked = "selected";
      &searchNameBeginsChecked = "";
   When "begins"
      &searchNameContainsChecked = "";
      &searchNameBeginsChecked = "selected";
   When-Other
      &searchNameContainsChecked = "";
      &searchNameBeginsChecked = "";
   End-Evaluate;

   Evaluate &adhocStateObj.adhocOprSrchType
   When "contains"
      &searchOprContainsChecked = "selected";
      &searchOprBeginsChecked = "";
   When "begins"
      &searchOprContainsChecked = "";
      &searchOprBeginsChecked = "selected";
   When-Other
      &searchOprContainsChecked = "";
      &searchOprBeginsChecked = "";
   End-Evaluate;

   &html = "<html>" | Char(13);
   &html = &html | "<!-- Copyright (c) 2000-2012 Oracle, Inc.  All Rights Reserved. -->" | Char(13);
   &html = &html | "<head>" | Char(13);
   If %Request.AuthTokenDomain <> "" Then
      &html = &html | "<script language=javascript>document.domain = '" | Right(%Request.AuthTokenDomain, Len(%Request.AuthTokenDomain) - 1) | "';</script>";
   End-If;
   &html = &html | "<link rel='stylesheet' type='text/css' href='" | &StyleSheetURL | "' />" | Char(13);
   &html = &html | GetHTMLText(HTML.EOAW_MON_ADHOC_FORM_PROC, "adhocLookup") | Char(13);
   &html = &html | GetHTMLText(HTML.EOAW_PROCESSING_SCRIPT);
   &html = &html | "</head>" | Char(13);
   &html = &html | "<body>" | Char(13);
   /*&html = &html | "<div id=""processingText"" name=""processingText"" style=""font-size:16pt;color:red;font-family:Arial,Helvetica,sans-serif;position:absolute;right:0;display:none;""><blink>Processing...</blink></div>" | Char(13);*/
   &html = &html | "<div id='processingText' name='processingText' style='position:absolute;right:0;display:none;'><img border='0' src=" | %Response.GetImageURL(Image.PT_PROCESSING) | " alt='" | MsgGetText(124, 173, "Processing, please wait") | "'> </div>" | Char(13);
   &html = &html | GetHTMLText(HTML.EOAW_MON_ADHOC_SRCH_FORM, &formActionURL, &adhocStateObj.oprNameSrchString, &adhocStateObj.oprIDSrchString, &searchButton, &clearButton, MsgGetText(18081, 4051, "Message Not Found - Approver/Reviewer Search"), MsgGetText(18081, 4061, "Message Not Found - Name"), MsgGetText(18081, 4052, "Message Not Found - User ID"), &cancelButton, MsgGetText(18081, 4085, "Message Not Found - begins with"), MsgGetText(18081, 4084, "Message Not Found - contains"), &searchNameContainsChecked, &searchNameBeginsChecked, &searchOprContainsChecked, &searchOprBeginsChecked) | Char(13);

   Local string &beginSearch = "";
   If (&adhocStateObj.adhocNameSrchType = "contains") Then
      &beginSearch = "%";
   End-If;
   Local string &nameWhere;
   If &adhocStateObj.oprNameSrchString <> "" Then
      /* bug#21266534: Follow PeopleTools standard method when search User by User Name.
      &oprNameSrchArray = buildNameSearchArray(&adhocStateObj.oprNameSrchString);
      &oprIDInList = "";
      For &searchLoop = 1 To &oprNameSrchArray.len
         &oprNameSrchString = &beginSearch | &oprNameSrchArray [&searchLoop] | "%";
         &nameSrchSQL = ExpandSqlBinds("SELECT OPRID FROM PSOPRDEFN WHERE %Upper(OPRDEFNDESC) LIKE %Upper(:1)", &oprNameSrchString);
         If (&searchLoop > 1) Then
            &nameWhere = &nameWhere | " OR ";
         End-If;
         &nameWhere = &nameWhere | "OPRID in (" | &nameSrchSQL | ")";
      End-For;
      If (None(&nameWhere)) Then
         REM If there are oprIDs found from the name search string, trim the trailing comma, otherwise, create an IN list that will always return an empty list.;
         &oprIDInList = "''";
         &nameWhere = "OPRID IN (" | &oprIDInList | ")";
      End-If;*/
      &nameWhere = ExpandSqlBinds("SELECT OPRID FROM PSOPRDEFN WHERE %Upper(OPRDEFNDESC) LIKE %Upper(:1)", &beginSearch | &adhocStateObj.oprNameSrchString | "%");
      &nameWhere = "OPRID IN (" | &nameWhere | ")";
   End-If;

   If (&adhocStateObj.adhocOprSrchType = "contains") Then
      &beginSearch = "%";
   Else
      &beginSearch = "";
   End-If;
   If &adhocStateObj.oprIDSrchString <> "" Then
      &whereClause = "WHERE %Upper(OPRID) like '" | &beginSearch | Substitute(Upper(&adhocStateObj.oprIDSrchString), "'", "''") | "%'";
      If All(&nameWhere) Then
         &whereClause = &whereClause | "and (" | &nameWhere | ")";
      End-If;
   Else
      If All(&nameWhere) Then
         &whereClause = "WHERE " | &nameWhere;
      Else
         &whereClause = "";
      End-If;
   End-If;

   /*Add IN statement to where clause to ensure only users in the UserList for this thread are returned*/
   /*Get List of available approvers for the current thread*/
   Local array of string &aryUserInClause = CreateArrayRept("", 0);
   If &adhocStateObj.userList <> Null Then
      &apprListArray = &adhocStateObj.userList.GetUsers(CreateArrayRept("", 0), &adhocStateObj.adhocPoolThreadRecs [&adhocStateObj.adhocPoolThreadIDs.Find(&adhocStateObj.thread)]);
      Local number &fetchConst = 900;
      If (&apprListArray.len <= &fetchConst) Then
         For &i = 1 To &apprListArray.len
            If All(&UserListInClause) Then
               &UserListInClause = &UserListInClause | "','";
            End-If;
            &UserListInClause = &UserListInClause | Substitute(&apprListArray [&i], "'", "''");
         End-For;
         rem &UserListInClause = "OPRID IN ('" | &UserListInClause | "')";
         &aryUserInClause.Push("'" | &UserListInClause | "'");
      Else
         Local number &multiplier = 1;
         Local number &max = &fetchConst;
         Local number &previous_max = 1;
         While (&max < &apprListArray.len)
            &max = &fetchConst * &multiplier;
            If (&max > &apprListArray.len) Then
               &max = &apprListArray.len;
            End-If;
            Local string &tempInClause = "";
            For &i = &previous_max To &max
               If All(&tempInClause) Then
                  &tempInClause = &tempInClause | "','";
               End-If;
               &tempInClause = &tempInClause | Substitute(&apprListArray [&i], "'", "''");
            End-For;

            /*  If All(&UserListInClause) Then
               &UserListInClause = &UserListInClause | " or OPRID IN ('" | &tempInClause | "')";
            Else
               &UserListInClause = "OPRID IN ('" | &tempInClause | "')";
            End-If; */
            &aryUserInClause.Push("'" | &tempInClause | "'");
            &previous_max = &max + 1;
            &multiplier = &multiplier + 1;
         End-While;
      End-If;

      /*      If All(&whereClause) Then
         &whereClause = &whereClause | " AND " | &UserListInClause;
      Else
         &whereClause = "WHERE " | &UserListInClause;
      End-If; */
      If (All(&whereClause)) Then
         &whereClause = &whereClause | " AND ";
      Else
         &whereClause = "WHERE ";
      End-If;
   End-If;


   If (&aryUserInClause.Len = 0) Then
      &adhocStateObj.adhocRS.Fill(&whereClause);
   Else
      Local number &aryCount;
      Local string &innerWhere = &whereClause | "OPRID in ( " | &aryUserInClause [1] | ")";
      &adhocStateObj.adhocRS.Fill(&innerWhere);
      For &aryCount = 2 To &aryUserInClause.Len
         &innerWhere = &whereClause | "OPRID in ( " | &aryUserInClause [&aryCount] | ")";
         &adhocStateObj.adhocRS.FillAppend(&innerWhere)
      End-For;
   End-If;
   If &adhocStateObj.adhocSearchChunkEnd > &adhocStateObj.adhocRS.ActiveRowCount Then
      &adhocStateObj.adhocSearchChunkEnd = &adhocStateObj.adhocRS.ActiveRowCount;
   End-If;

   If LTrim(RTrim(&adhocStateObj.adhocRS.GetRow(1).EOAW_ADHOC_VW.OPRID.Value)) <> "" Then

      /*Create chunking HTML*/
      &chunkingHTML = "<table border='0' cellpadding='0' cellspacing='0'><tr>";
      If &adhocStateObj.adhocSearchChunkStart = 1 Then
         &chunkingHTML = &chunkingHTML | "<td valign='middle'><img src='" | %Response.GetImageURL(Image.PT_PREVIOUSROW_D) | "' border='0' alt='" | MsgGetText(18081, 4071, "Message Not Found - 18081,4071,'Previous rows'") | "'/></td>";
      Else
         &chunkingHTML = &chunkingHTML | "<td valign='middle'><a href=""javascript:procForm('lookupPrevChunk');"" title='" | MsgGetText(18081, 4071, "Message Not Found - 18081,4071,'Previous rows'") | "'><img src='" | %Response.GetImageURL(Image.PT_PREVIOUSROW) | "' border='0'/></a></td>";
      End-If;
      &chunkingHTML = &chunkingHTML | "<td valign='middle' class='PSSRCHRESULTSHYPERLINKD'>&nbsp;&nbsp;" | &adhocStateObj.adhocSearchChunkStart | " - " | &adhocStateObj.adhocSearchChunkEnd | " " | MsgGetText(18081, 4070, "Message Not Found - 18081,4070,'of'") | " " | &adhocStateObj.adhocRS.ActiveRowCount | "&nbsp;&nbsp;</td>";
      If &adhocStateObj.adhocSearchChunkEnd = &adhocStateObj.adhocRS.ActiveRowCount Then
         &chunkingHTML = &chunkingHTML | "<td valign='middle'><img src='" | %Response.GetImageURL(Image.PT_NEXTROW_D) | "' border='0' alt='" | MsgGetText(18081, 4072, "Message Not Found - 18081,4072,'Next rows'") | "'/></td>";
      Else
         &chunkingHTML = &chunkingHTML | "<td valign='middle'><a href=""javascript:procForm('lookupNextChunk');"" title='" | MsgGetText(18081, 4072, "Message Not Found - 18081,4072,'Next rows'") | "'><img src='" | %Response.GetImageURL(Image.PT_NEXTROW) | "' border='0'/></a></td>";
      End-If;
      &chunkingHTML = &chunkingHTML | "<td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td></tr></table>";
      /*bug 11573263--begin*/
      &text = MsgGetText(18081, 5502, "Search Results");
      &html = &html | "<span class='PSSRCHSUBTITLE'>" | &text | "</span>" | Char(13);
      /*bug 11573263--end*/
      &html = &html | "<table border='0' cellpadding='0' cellspacing='0' width='100%'  class='PSSRCHRESULTSTITLE'>" | Char(13);
      &html = &html | "   <tr>" | Char(13);
      &html = &html | "      <td colspan='2' align='right'>" | &chunkingHTML | "</td>" | Char(13);
      &html = &html | "   <tr>" | Char(13);

      &html = &html | "   <tr align='left'>" | Char(13);
      &html = &html | "      <th scope='col' class='PSSRCHRESULTSHDR'><a style='text-decoration:none;cursor:arrow;' href='javascript:void(0);'class='PSSRCHRESULTSHDR'>" | MsgGetText(18081, 4052, "Message Not Found - User ID") | "</a></td>" | Char(13);
      &html = &html | "      <th scope='col' class='PSSRCHRESULTSHDR'><a style='text-decoration:none;cursor:arrow;' href='javascript:void(0);' class='PSSRCHRESULTSHDR'>" | MsgGetText(18081, 4061, "Message Not Found - Name") | "</a></td>" | Char(13);
      &html = &html | "   </tr>" | Char(13);

      For &i = &adhocStateObj.adhocSearchChunkStart To &adhocStateObj.adhocSearchChunkEnd
         If isEven(&i) Then
            &rowClass = "PSSRCHRESULTSEVENROW";
         Else
            &rowClass = "PSSRCHRESULTSODDROW";
         End-If;
         &oprID = &adhocStateObj.adhocRS.GetRow(&i).EOAW_ADHOC_VW.OPRID.Value;
         &displayName = getUserName(&oprID);
         &lookupDoneHRef = "javascript:document.adhocLookup.oprID.value='" | &oprID | "';procForm('lookupDone')";
         &html = &html | "   <tr>" | Char(13);
         &html = &html | "      <td class='" | &rowClass | "'><a href=""" | &lookupDoneHRef | """ class='PSHYPERLINK'>" | &oprID | "</a></td>" | Char(13);
         &html = &html | "      <td class='" | &rowClass | "'><a href=""" | &lookupDoneHRef | """ class='PSHYPERLINK'>" | &displayName | "</a></td>" | Char(13);
         &html = &html | "   </tr>" | Char(13);
      End-For;
      &html = &html | "</table>" | Char(13);
   Else
      &html = &html | "<span class='PSSRCHINSTRUCTIONS'>" | MsgGetText(124, 38, "Message Not Found - No matching values found") | "</span>" | Char(13)
   End-If;

   &html = &html | "</body>" | Char(13);
   &html = &html | "</html>" | Char(13);

   %Response.Write(&html);
End-Function;

















Function IScript_Adhoc_Form_Proc
   /*Retrieve all possible parameters from form submit*/
   &action = %Request.GetParameter("formAction");
   &oprID = %Request.GetParameter("oprID");
   &oprIDSrchString = %Request.GetParameter("oprIDSrchString");
   &oprName = %Request.GetParameter("oprName");
   &oprNameSrchString = %Request.GetParameter("oprNameSrchString");
   &adhocType = %Request.GetParameter("adhocType");
   &originalOprIDSrchString = %Request.GetParameter("originalOprIDSrchString");
   &adhocNameSrchType = %Request.GetParameter("adhocNameSrchType");
   &adhocOprSrchType = %Request.GetParameter("adhocOprSrchType");


   /*Update State Object with form parameters*/
   &adhocStateObj.oprIDSrchString = &oprIDSrchString;
   &adhocStateObj.oprID = &oprID;
   &adhocStateObj.oprName = &oprName;
   &adhocStateObj.oprNameSrchString = &oprNameSrchString;
   If All(&adhocType) Then
      &adhocStateObj.adhocType = &adhocType;
   End-If;
   If All(&adhocNameSrchType) Then
      &adhocStateObj.adhocNameSrchType = &adhocNameSrchType;
   End-If;
   If All(&adhocOprSrchType) Then
      &adhocStateObj.adhocOprSrchType = &adhocOprSrchType;
   End-If;
   If All(&originalOprIDSrchString) Then
      &adhocStateObj.originalOprIDSrchString = &originalOprIDSrchString;
   End-If;

   If %Request.AuthTokenDomain <> "" Then
      &authTokenScript = "<script language=javascript>document.domain = '" | Right(%Request.AuthTokenDomain, Len(%Request.AuthTokenDomain) - 1) | "';</script>" | Char(13);
   End-If;

   /*Determine destination page and redirect*/
   Evaluate &action
   When "lookup"
      &adhocStateObj.initChunkState();
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Lookup");
   When "lookupNextChunk"
      &adhocStateObj.incrementChunkState();
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Lookup");
   When "lookupPrevChunk"
      &adhocStateObj.decrementChunkState();
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Lookup");
   When "lookupSearch"
   When "lookupDone"
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Entry");
   When "lookupCancel"
      &adhocStateObj.oprID = &adhocStateObj.originalOprIDSrchString;
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Entry");
   When "submit"
      If &adhocStateObj.oprID = "" Then
         &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC, "FieldFormula", "IScript_Adhoc_Entry") | "?NOOPRID=TRUE";
         %Response.RedirectURL(&URL)
      Else
         userIDIsValid();
         %Response.Write(&authTokenScript | "<script language='JavaScript'>window.opener.modalRelay('insert:');window.close();</script>");
      End-If;
   When "cancel"
      rem &adhocStateObj = Null;
      &html = &authTokenScript | "<script language='JavaScript'>window.close()</script>";
      %Response.Write(&html);
   End-Evaluate;

   %Response.RedirectURL(&URL);
End-Function;

import EOAW_MONITOR:ADHOC_OBJECTS:*;
