Declare Function isEven PeopleCode FUNCLIB_EOAW.EOAWNUM_FUNCTIONS FieldFormula;

Global EOAW_MONITOR:ADHOC_OBJECTS:adhocStateObj &adhocStateObj;


Function userIDIsValid()
   If &adhocStateObj.userList <> Null Then
      &uListArray = &adhocStateObj.userList.GetUsers(CreateArrayRept("", 0), &adhocStateObj.adhocPoolThreadRecs [&adhocStateObj.adhocPoolThreadIDs.Find(&adhocStateObj.thread)]);
   Else
      &remoteHandler = create EOAW_APPROVAL_MM_FL:integration:outboundHandler();

      Local Rowset &rs = &remoteHandler.buildApproverChunkList(&adhocStateObj.procId, &adhocStateObj.thread, "contains", "contains", "", &adhocStateObj.oprID);

      &uListArray = CreateArrayRept("", 0);
      If &rs.ActiveRowCount > 0 Then
         For &i = 1 To &rs.ActiveRowCount
            &uListArray.push(&rs.GetRow(&i).EOAWMAPPROVERVW.OPRID.Value);
         End-For;
      End-If;

   End-If;

   If &uListArray.find(&adhocStateObj.oprID) <> 0 Then
      &userNameResolved = getUserName(&adhocStateObj.oprID);
   Else
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Entry") | "?INVALIDOPRID=TRUE";
      %Response.RedirectURL(&URL);
      Exit;
   End-If;
End-Function;


Function IScript_Adhoc_Entry
   &StyleSheetURL = %Response.GetStyleSheetURL(StyleSheet.PSSTYLEDEF_FMODE);

   /*If 1st time running script, create adhoc state object*/
   If %Request.GetParameter("START") = "TRUE" Then
      If (&adhocStateObj = Null) Then
         &adhocStateObj = create EOAW_MONITOR:ADHOC_OBJECTS:adhocStateObj( Null);
      End-If;
      rem &adhocStateObj = create EOAW_MONITOR:ADHOC_OBJECTS:adhocStateObj( Null);
      &adhocStateObj.reInit();
      &adhocStateObj.adhocRS = CreateRowset(Record.EOAWMAPPROVERVW);
      &adhocStateObj.initChunkState();
      &temp = %Request.GetParameter("STEPTOINSERTBEFORE");
      &adhocStateObj.stepBefore = Value(&temp);
      &temp = %Request.GetParameter("STEPTOINSERTAFTER");
      &adhocStateObj.stepAfter = Value(&temp);
      &adhocStateObj.adhocPosition = %Request.GetParameter("TYPE");
      &adhocStateObj.procId = %Request.GetParameter("PROCESSID");
      rem %Request.GetParameter("ADHOCPOSITION");
      &adhocStateObj.stage = Value(%Request.GetParameter("STAGE"));
      &adhocStateObj.thread = Value(%Request.GetParameter("THREAD"));
   End-If;


   /*Get threadId from step if threadId did not come from URL*/
   If &adhocStateObj.thread = 0 Then
      &stepToFind = &adhocStateObj.stepBefore;
      If None(&stepToFind) Then
         &stepToFind = &adhocStateObj.stepAfter;
      End-If;
      SQLExec("SELECT EOAWTHREAD_ID FROM PS_EOAW_STEPINST WHERE EOAWSTEP_INSTANCE = :1", &stepToFind, &tempThread);
      &adhocStateObj.thread = &tempThread;
   End-If;

   Evaluate &adhocStateObj.adhocType
   When "approver"
      &approverRadioChecked = "checked";
      &reviewerRadioChecked = "";
   When "reviewer"
      &reviewerRadioChecked = "checked";
      &approverRadioChecked = "";
   When-Other
      &reviewerRadioChecked = "";
      &approverRadioChecked = "";
   End-Evaluate;

   &formActionURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Form_Proc");
   &lookupButtonURL = %Response.GetImageURL(Image.PT_PROMPT_LOOKUP);

   If %Request.AuthTokenDomain <> "" Then
      &html = "<script language=javascript>document.domain = '" | Right(%Request.AuthTokenDomain, Len(%Request.AuthTokenDomain) - 1) | "';</script>";
   End-If;
   &html = &html | "<link rel='stylesheet' type='text/css' href='" | &StyleSheetURL | "' />" | Char(13);
   &html = &html | GetHTMLText(HTML.EOAW_MON_ADHOC_FORM_PROC_NUI, "adhocEntry");
   &html = &html | GetHTMLText(HTML.EOAW_PROCESSING_SCRIPT);
   &html = &html | "<div id='processingText' name='processingText' style='position:absolute;right:0;display:none;'><img border='0' src=" | %Response.GetImageURL(Image.PT_PROCESSING) | " alt='" | MsgGetText(124, 173, "Processing, please wait") | "'> </div>" | Char(13);

   Evaluate &adhocStateObj.adhocPosition
   When "serial"
      &pageTitle = MsgGetText(18081, 4057, "Message Not Found - Insert additional approver or reviewer");
   When "parallel"
      &pageTitle = MsgGetText(18081, 4056, "Message Not Found - Start new approval path");
   End-Evaluate;

   /*Validate oprID on tab out and throw error if not valid*/
   If &adhocStateObj.oprID <> "" And
         %Request.GetParameter("INVALIDOPRID") <> "TRUE" Then
      userIDIsValid();
   End-If;

   &closeImg = %Response.GetImageURL(Image.PT_MODAL_CLOSE_NUI);
   &lookupImg = %Response.GetImageURL(Image.PT_PROMPT_LOOKUP);
   &lookupDoneHRef = "javascript:procForm('lookupDone')";


   If %Request.GetParameter("NOOPRID") <> "TRUE" And
         %Request.GetParameter("INVALIDOPRID") <> "TRUE" Then
      &html = &html | GetHTMLText(HTML.EOAW_ADHOC_ENTRY_FORM_NUI, &formActionURL, &adhocStateObj.oprID, &lookupButtonURL, &approverRadioChecked, &reviewerRadioChecked, MsgGetText(18081, 4053, "Message Not Found - Choose an approver or reviewer to insert"), MsgGetText(18081, 4054, "Message Not Found - User Name"), MsgGetText(124, 133, "Message Not Found - Look Up"), MsgGetText(18081, 4055, "Message Not Found - Insert as"), MsgGetText(18081, 4062, "Message Not Found - Approver"), MsgGetText(18081, 4032, "Message Not Found - Reviewer"), MsgGetText(18081, 4063, "Message Not Found - Insert"), &userNameResolved, &lookupDoneHRef, MsgGetText(18081, 4060, "Message Not Found - Cancel"), &pageTitle, &closeImg, &lookupImg, "");
   End-If;

   If %Request.GetParameter("NOOPRID") = "TRUE" Then
      &html = &html | GetHTMLText(HTML.EOAW_ADHOC_ENTRY_FORM_NUI, &formActionURL, &adhocStateObj.oprID, &lookupButtonURL, &approverRadioChecked, &reviewerRadioChecked, MsgGetText(18081, 4053, "Message Not Found - Choose an approver or reviewer to insert"), MsgGetText(18081, 4054, "Message Not Found - User Name"), MsgGetText(124, 133, "Message Not Found - Look Up"), MsgGetText(18081, 4055, "Message Not Found - Insert as"), MsgGetText(18081, 4062, "Message Not Found - Approver"), MsgGetText(18081, 4032, "Message Not Found - Reviewer"), MsgGetText(18081, 4063, "Message Not Found - Insert"), &userNameResolved, &lookupDoneHRef, MsgGetText(18081, 4060, "Message Not Found - Cancel"), &pageTitle, &closeImg, &lookupImg, MsgGetText(18081, 4039, "Message Not Found", "<img src=""" | &lookupButtonURL | """>"));
      <*&html = &html | "<center><div class='PAERRORTEXT' style='font-weight:bold;'>" | MsgGetText(18081, 4039, "Message Not Found", "<img src=""" | &lookupButtonURL | """>") | "</div></center>" | Char(13);*>
   End-If;

   If %Request.GetParameter("INVALIDOPRID") = "TRUE" Then
      &html = &html | GetHTMLText(HTML.EOAW_ADHOC_ENTRY_FORM_NUI, &formActionURL, &adhocStateObj.oprID, &lookupButtonURL, &approverRadioChecked, &reviewerRadioChecked, MsgGetText(18081, 4053, "Message Not Found - Choose an approver or reviewer to insert"), MsgGetText(18081, 4054, "Message Not Found - User Name"), MsgGetText(124, 133, "Message Not Found - Look Up"), MsgGetText(18081, 4055, "Message Not Found - Insert as"), MsgGetText(18081, 4062, "Message Not Found - Approver"), MsgGetText(18081, 4032, "Message Not Found - Reviewer"), MsgGetText(18081, 4063, "Message Not Found - Insert"), &userNameResolved, &lookupDoneHRef, MsgGetText(18081, 4060, "Message Not Found - Cancel"), &pageTitle, &closeImg, &lookupImg, &adhocStateObj.oprID | " " | MsgGetText(18081, 4040, "Message Not Found", "<img src=""" | &lookupButtonURL | """>"));

      <* &html = &html | "<center><div class='PAERRORTEXT' style='font-weight:bold;'>" | &adhocStateObj.oprID | " " | MsgGetText(18081, 4040, "Message Not Found", "<img src=""" | &lookupButtonURL | """>") | "</div></center>" | Char(13);*>
   End-If;

   %Response.Write(&html);
End-Function;


Function IScript_Adhoc_Delete
   /*If 1st time running script, create adhoc state object*/
   /* If %Request.GetParameter("START") = "TRUE" Then*/

   If %Request.AuthTokenDomain <> "" Then
      &authTokenScript = "<script language=javascript>document.domain = '" | Right(%Request.AuthTokenDomain, Len(%Request.AuthTokenDomain) - 1) | "';</script>" | Char(13);
   End-If;

   If (&adhocStateObj = Null) Then
      Return;
   End-If;
   rem &adhocStateObj = create EOAW_MONITOR:ADHOC_OBJECTS:adhocStateObj( Null);
   &adhocStateObj.reInit();
   &temp = %Request.GetParameter("STEPTOINSERTBEFORE");
   &adhocStateObj.stepBefore = Value(&temp);
   &temp = %Request.GetParameter("STEPTOINSERTAFTER");
   &adhocStateObj.stepAfter = Value(&temp);
   &adhocStateObj.adhocPosition = %Request.GetParameter("TYPE");
   &adhocStateObj.procId = %Request.GetParameter("PROCESSID");
   rem %Request.GetParameter("ADHOCPOSITION");
   &adhocStateObj.stage = Value(%Request.GetParameter("STAGE"));
   &adhocStateObj.thread = Value(%Request.GetParameter("THREAD"));
   rem  End-If;
   &remoteboundHandler = create EOAW_APPROVAL_MM_FL:integration:outboundHandler();
   Local boolean &isApprover = False;
   If &adhocStateObj.adhocType = "approver" Then
      &isApprover = True;
   End-If;

   If &adhocStateObj.adhocType = "reviewer" Then
      &isApprover = False
   End-If;

   &para = &remoteboundHandler.takeAdhocAction(&adhocStateObj.adhocPosition, &adhocStateObj.procId, &adhocStateObj.thread, &adhocStateObj.oprID, &isApprover, &adhocStateObj.stepAfter, &adhocStateObj.stage);

   &html = &authTokenScript | "<script language='JavaScript'>window.parent.modalRelay(" | &para | ", 4);</script>";

   rem %Response.SetContentType("application/json");

   %Response.Write(&html);

End-Function;


Function IScript_Adhoc_Lookup
   Local Record &adhocInfoRecord;
   Local string &oprNameSrchString;
   Local string &searchNameContainsChecked, &searchNameBeginsChecked, &searchOprContainsChecked, &searchOprBeginsChecked;


   &StyleSheetURL = %Response.GetStyleSheetURL(StyleSheet.PSSTYLEDEF_FMODE);

   &formActionURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Form_Proc");


   &searchButton = "<a href=""javascript:procForm('lookup');"" title='" | MsgGetText(18081, 4059, "Message Not Found - Search") | "'><img src='" | %Response.GetImageURL(Image.PT_SEARCH) | "' border='0'></a>";
   &clearButton = "<a href=""javascript:document.adhocLookup.oprIDSrchString.value='';document.adhocLookup.oprNameSrchString.value='';procForm('lookup');"" title='" | MsgGetText(18081, 4064, "Message Not Found - Clear") | "'><img src='" | %Response.GetImageURL(Image.PT_CLEAR) | "' border='0'></a>";
   &cancelButton = "<a href=""javascript:procForm('lookupCancel');"" title='" | MsgGetText(18081, 4060, "Message Not Found - Cancel") | "'><img src='" | %Response.GetImageURL(Image.PT_CANCEL) | "' border='0'></a>";


   &searchButtonHref = "javascript:procForm('lookup');";
   &clearButtonHref = "javascript:document.adhocLookup.oprIDSrchString.value='';document.adhocLookup.oprNameSrchString.value='';procForm('lookup');";
   /*  Evaluate &adhocStateObj.adhocNameSrchType
   When "contains"
      &searchNameContainsChecked = "selected";
      &searchNameBeginsChecked = "";
   When "begins"*/
   &searchNameContainsChecked = "";
   &searchNameBeginsChecked = "selected";
   /*When-Other
      &searchNameContainsChecked = "";
      &searchNameBeginsChecked = "";
   End-Evaluate;

   Evaluate &adhocStateObj.adhocOprSrchType
   When "contains"
      &searchOprContainsChecked = "selected";
      &searchOprBeginsChecked = "";
   When "begins"*/
   &searchOprContainsChecked = "";
   &searchOprBeginsChecked = "selected";
   /*When-Other
      &searchOprContainsChecked = "";
      &searchOprBeginsChecked = "";
   End-Evaluate;*/

   &html = "<html>" | Char(13);
   &html = &html | "<!-- Copyright (c) 2000-2012 Oracle, Inc.  All Rights Reserved. -->" | Char(13);
   &html = &html | "<head>" | Char(13);
   If %Request.AuthTokenDomain <> "" Then
      &html = &html | "<script language=javascript>document.domain = '" | Right(%Request.AuthTokenDomain, Len(%Request.AuthTokenDomain) - 1) | "';</script>";
   End-If;
   &html = &html | "<link rel='stylesheet' type='text/css' href='" | &StyleSheetURL | "' />" | Char(13);

   &html = &html | GetHTMLText(HTML.EOAW_MON_ADHOC_FORM_PROC_NUI, "adhocLookup") | Char(13);
   &html = &html | GetHTMLText(HTML.EOAW_PROCESSING_SCRIPT);
   &html = &html | "</head>" | Char(13);
   &html = &html | "<body>" | Char(13);
   /*&html = &html | "<div id=""processingText"" name=""processingText"" style=""font-size:16pt;color:red;font-family:Arial,Helvetica,sans-serif;position:absolute;right:0;display:none;""><blink>Processing...</blink></div>" | Char(13);*/
   &html = &html | "<div id='processingText' name='processingText' style='position:absolute;right:0;display:none;'><img border='0' src=" | %Response.GetImageURL(Image.PT_PROCESSING) | " alt='" | MsgGetText(124, 173, "Processing, please wait") | "'> </div>" | Char(13);
   &html = &html | GetHTMLText(HTML.EOAW_MON_ADHOC_SRCH_FORM_NUI, &formActionURL, &adhocStateObj.oprNameSrchString, &adhocStateObj.oprIDSrchString, &searchButtonHref, &clearButtonHref, MsgGetText(18081, 4051, "Message Not Found - Approver/Reviewer Search"), MsgGetText(18081, 4061, "Message Not Found - Name"), MsgGetText(18081, 4052, "Message Not Found - User ID"), &cancelButton, MsgGetText(18081, 4085, "Message Not Found - begins with"), MsgGetText(18081, 4084, "Message Not Found - contains"), &searchNameContainsChecked, &searchNameBeginsChecked, &searchOprContainsChecked, &searchOprBeginsChecked) | Char(13);

   /* Get all the retrieved data for the first time */
   If &adhocStateObj.adhocSearchChunkStart = 1 Then
      &remoteHandler = create EOAW_APPROVAL_MM_FL:integration:outboundHandler();
      &adhocStateObj.adhocRS = &remoteHandler.buildApproverChunkList(&adhocStateObj.procId, &adhocStateObj.thread, &adhocStateObj.adhocNameSrchType, &adhocStateObj.adhocOprSrchType, &adhocStateObj.oprNameSrchString, &adhocStateObj.oprIDSrchString);
   End-If;

   If &adhocStateObj.adhocSearchChunkEnd > &adhocStateObj.adhocRS.ActiveRowCount Then
      &adhocStateObj.adhocSearchChunkEnd = &adhocStateObj.adhocRS.ActiveRowCount;
   End-If;


   REM    &cMonData.buildApproverChunkList();

   <* Local string &beginSearch = "";
   If (&adhocStateObj.adhocNameSrchType = "contains") Then
      &beginSearch = "%";
   End-If;
   If &adhocStateObj.oprNameSrchString <> "" Then
      &oprNameSrchArray = buildNameSearchArray(&adhocStateObj.oprNameSrchString);
      &oprIDInList = "";
      For &searchLoop = 1 To &oprNameSrchArray.len
         &oprNameSrchString = &beginSearch | &oprNameSrchArray [&searchLoop] | "%";
         &nameSrchSQL = ExpandSqlBinds("SELECT OPRID FROM PSOPRDEFN WHERE %Upper(OPRDEFNDESC) LIKE %Upper(:1)", &oprNameSrchString);
         If (&searchLoop > 1) Then
            &nameWhere = &nameWhere | " OR ";
         End-If;
         &nameWhere = &nameWhere | "OPRID in (" | &nameSrchSQL | ")";
      End-For;
      If (None(&nameWhere)) Then
         /*If there are oprIDs found from the name search string, trim the trailing comma, otherwise, create an IN list that will always return an empty list.*/
         &oprIDInList = "''";
         &nameWhere = "OPRID IN (" | &oprIDInList | ")";
      End-If;
      &nameWhere = "(" | &nameWhere | ")";
   End-If;

   If (&adhocStateObj.adhocOprSrchType = "contains") Then
      &beginSearch = "%";
   Else
      &beginSearch = "";
   End-If;
   If &adhocStateObj.oprIDSrchString <> "" Then
      &whereClause = "WHERE %Upper(OPRID) like '" | &beginSearch | Substitute(Upper(&adhocStateObj.oprIDSrchString), "'", "''") | "%'";
      If All(&nameWhere) Then
         &whereClause = &whereClause | "and (" | &nameWhere | ")";
      End-If;
   Else
      If All(&nameWhere) Then
         &whereClause = "WHERE " | &nameWhere;
      Else
         &whereClause = "";
      End-If;
   End-If;

   /*Add IN statement to where clause to ensure only users in the UserList for this thread are returned*/
   /*Get List of available approvers for the current thread*/
   Local array of string &aryUserInClause = CreateArrayRept("", 0);
   If &adhocStateObj.userList <> Null Then
      &apprListArray = &adhocStateObj.userList.GetUsers(CreateArrayRept("", 0), &adhocStateObj.adhocPoolThreadRecs [&adhocStateObj.adhocPoolThreadIDs.Find(&adhocStateObj.thread)]);
      Local number &fetchConst = 900;
      If (&apprListArray.len <= &fetchConst) Then
         For &i = 1 To &apprListArray.len
            If All(&UserListInClause) Then
               &UserListInClause = &UserListInClause | "','";
            End-If;
            &UserListInClause = &UserListInClause | Substitute(&apprListArray [&i], "'", "''");
         End-For;
         rem &UserListInClause = "OPRID IN ('" | &UserListInClause | "')";
         &aryUserInClause.Push("'" | &UserListInClause | "'");
      Else
         Local number &multiplier = 1;
         Local number &max = &fetchConst;
         Local number &previous_max = 1;
         While (&max < &apprListArray.len)
            &max = &fetchConst * &multiplier;
            If (&max > &apprListArray.len) Then
               &max = &apprListArray.len;
            End-If;
            Local string &tempInClause = "";
            For &i = &previous_max To &max
               If All(&tempInClause) Then
                  &tempInClause = &tempInClause | "','";
               End-If;
               &tempInClause = &tempInClause | Substitute(&apprListArray [&i], "'", "''");
            End-For;

            /*  If All(&UserListInClause) Then
               &UserListInClause = &UserListInClause | " or OPRID IN ('" | &tempInClause | "')";
            Else
               &UserListInClause = "OPRID IN ('" | &tempInClause | "')";
            End-If; */
            &aryUserInClause.Push("'" | &tempInClause | "'");
            &previous_max = &max + 1;
            &multiplier = &multiplier + 1;
         End-While;
      End-If;

      /*      If All(&whereClause) Then
         &whereClause = &whereClause | " AND " | &UserListInClause;
      Else
         &whereClause = "WHERE " | &UserListInClause;
      End-If; */
      If (All(&whereClause)) Then
         &whereClause = &whereClause | " AND ";
      Else
         &whereClause = "WHERE ";
      End-If;
   End-If;


   If (&aryUserInClause.Len = 0) Then
      &adhocStateObj.adhocRS.Fill(&whereClause);
   Else
      Local number &aryCount;
      Local string &innerWhere = &whereClause | "OPRID in ( " | &aryUserInClause [1] | ")";
      &adhocStateObj.adhocRS.Fill(&innerWhere);
      For &aryCount = 2 To &aryUserInClause.Len
         &innerWhere = &whereClause | "OPRID in ( " | &aryUserInClause [&aryCount] | ")";
         &adhocStateObj.adhocRS.FillAppend(&innerWhere)
      End-For;
   End-If;
   If &adhocStateObj.adhocSearchChunkEnd > &adhocStateObj.adhocRS.ActiveRowCount Then
      &adhocStateObj.adhocSearchChunkEnd = &adhocStateObj.adhocRS.ActiveRowCount;
   End-If;
   *>
   If LTrim(RTrim(&adhocStateObj.adhocRS.GetRow(1).EOAWMAPPROVERVW.OPRID.Value)) <> "" Then

      /*Create chunking HTML*/
      /* &chunkingHTML = "<table border='0' class='ps_grid-flex-head' style='margin-left: 0px'; width: 1010px;><tr>"; */
      If &adhocStateObj.adhocSearchChunkStart = 1 Then
         &chunkingHTML = &chunkingHTML | "<div align='right'><img src='" | %Response.GetImageURL(Image.PT_PREVIOUSROW_D) | "' border='0' alt='" | MsgGetText(18081, 4071, "Message Not Found - 18081,4071,'Previous rows'") | "'/>";
      Else
         &chunkingHTML = &chunkingHTML | "<a href=""javascript:procForm('lookupPrevChunk');"" title='" | MsgGetText(18081, 4071, "Message Not Found - 18081,4071,'Previous rows'") | "'><img src='" | %Response.GetImageURL(Image.PT_PREVIOUSROW) | "' border='0'/></a>";
      End-If;
      &chunkingHTML = &chunkingHTML | "<span class='PSSRCHRESULTSHYPERLINKD'>&nbsp;&nbsp;" | &adhocStateObj.adhocSearchChunkStart | " - " | &adhocStateObj.adhocSearchChunkEnd | " " | MsgGetText(18081, 4070, "Message Not Found - 18081,4070,'of'") | " " | &adhocStateObj.adhocRS.ActiveRowCount | "&nbsp;&nbsp;";
      If &adhocStateObj.adhocSearchChunkEnd = &adhocStateObj.adhocRS.ActiveRowCount Then
         &chunkingHTML = &chunkingHTML | "<img src='" | %Response.GetImageURL(Image.PT_NEXTROW_D) | "' border='0' alt='" | MsgGetText(18081, 4072, "Message Not Found - 18081,4072,'Next rows'") | "'/>";
      Else
         &chunkingHTML = &chunkingHTML | "<a href=""javascript:procForm('lookupNextChunk');"" title='" | MsgGetText(18081, 4072, "Message Not Found - 18081,4072,'Next rows'") | "'><img src='" | %Response.GetImageURL(Image.PT_NEXTROW) | "' border='0'/></a></div>";
      End-If;


      &html = &html | "<div class='ps_box-group ps_prompt-resultswrapper' id='win0divDERIVEDNUI_SRCH_GROUPBOX1' style='height: 20%;'>";
      /* style='height: 20%;'>";*/
      &html = &html | "<h2 class='ps_header-group'>";
      &html = &html | "<a class='ps-link' id='DERIVEDNUI_SRCH_GROUPBOX1' onclick='javascript:cancelBubble(event);' href='javascript:toggleGroup('win0divDERIVEDNUI_SRCH_GROUPBOX1','DERIVEDNUI_SRCH_GROUPBOX1');'>Search Results</a></h2>";

      rem &html = &html | "   <div>" | Char(13);


      &html = &html | "      <table class='ps_grid-flex'> <tr align = 'right'><div class='ps_box-group' align='right'>" | &chunkingHTML | "</div></tr></table>" | Char(13);


      /* &html = &html | "   <tr>" | Char(13);

      &html = &html | "   <tr align='left'>" | Char(13);
      &html = &html | "      <th scope='col' class='PSSRCHRESULTSHDR'><a style='text-decoration:none;cursor:arrow;' href='javascript:void(0);'class='PSSRCHRESULTSHDR'>" | MsgGetText(18081, 4052, "Message Not Found - User ID") | "</a></td>" | Char(13);
      &html = &html | "      <th scope='col' class='PSSRCHRESULTSHDR'><a style='text-decoration:none;cursor:arrow;' href='javascript:void(0);' class='PSSRCHRESULTSHDR'>" | MsgGetText(18081, 4061, "Message Not Found - Name") | "</a></td>" | Char(13);*/
      rem &html = &html | "   </th>" | Char(13);

      &html = &html | GetHTMLText(HTML.EOAW_MON_ADHOC_SRCH_RSLT1);

      &html = &html | "<tbody class='ps_grid-body'>" | Char(13);


      For &i = &adhocStateObj.adhocSearchChunkStart To &adhocStateObj.adhocSearchChunkEnd

         &oprID = &adhocStateObj.adhocRS.GetRow(&i).EOAWMAPPROVERVW.OPRID.Value;
         &displayName = &adhocStateObj.adhocRS.GetRow(&i).EOAWMAPPROVERVW.OPRDEFNDESC.Value;
         REM getUserName(&oprID);
         /* document.adhocLookup.oprID.value='" | &oprID | "'; */
         &lookupDoneHRef = "javascript:document.adhocLookup.oprID.value='" | &oprID | "';javascript:procForm('lookupDone')";

         &html = &html | "   <tr class='ps_grid-row psc_rowact' id='DERIVEDNUI_SRCH$0_row_0' tabindex='0' role='button' onclick=""" | &lookupDoneHRef | "; cancelBubble(event);""/>" | Char(13);
         &html = &html | "   <td class='ps_grid-cell NUI_SRCH0'><div id='win0divNUI_SRCH0$0' class='ps_box-edit psc_disabled psc_wrappable'><span class='ps_box-value' id='NUI_SRCH0$0'>" | &oprID | "</span><!-- NUI_SRCH0$0 --></div></td>";
         &html = &html | "   <td class='ps_grid-cell NUI_SRCH1'><div id='win0divNUI_SRCH1$0' class='ps_box-edit psc_disabled psc_wrappable'><span class='ps_box-value' id='NUI_SRCH1$0'>" | &displayName | "</span><!-- NUI_SRCH1$0 --></div></td>";
         &html = &html | "   </tr>" | Char(13);


      End-For;
      &html = &html | "</thead>" | Char(13);
      &html = &html | "</tbody>" | Char(13);
      &html = &html | "</table>" | Char(13);

   Else
      &html = &html | "</div><div class='ps_box-group ps_prompt-resultswrapper' id='win0divDERIVEDNUI_SRCH_GROUPBOX1' >";
      &html = &html | "<span class='PSSRCHINSTRUCTIONS'>" | MsgGetText(124, 38, "Message Not Found - No matching values found") | "</span>" | Char(13);
      &html = &html | "</div>";
   End-If;

   /*  &html = &html | "</body>" | Char(13);
   &html = &html | "</html>" | Char(13);*/

   %Response.Write(&html);
End-Function;


Function IScript_Adhoc_Form_Proc
   /*Retrieve all possible parameters from form submit*/
   &action = %Request.GetParameter("formAction");
   &oprID = %Request.GetParameter("oprID");
   &oprIDSrchString = %Request.GetParameter("oprIDSrchString");
   &oprName = %Request.GetParameter("oprName");
   &oprNameSrchString = %Request.GetParameter("oprNameSrchString");
   &adhocType = %Request.GetParameter("adhocType");
   &originalOprIDSrchString = %Request.GetParameter("originalOprIDSrchString");
   &adhocNameSrchType = %Request.GetParameter("adhocNameSrchType");
   &adhocOprSrchType = %Request.GetParameter("adhocOprSrchType");


   /*Update State Object with form parameters*/
   &adhocStateObj.oprIDSrchString = &oprIDSrchString;
   &adhocStateObj.oprID = &oprID;
   &adhocStateObj.oprName = &oprName;
   &adhocStateObj.oprNameSrchString = &oprNameSrchString;
   If All(&adhocType) Then
      &adhocStateObj.adhocType = &adhocType;
   End-If;
   If All(&adhocNameSrchType) Then
      &adhocStateObj.adhocNameSrchType = &adhocNameSrchType;
   End-If;
   If All(&adhocOprSrchType) Then
      &adhocStateObj.adhocOprSrchType = &adhocOprSrchType;
   End-If;
   If All(&originalOprIDSrchString) Then
      &adhocStateObj.originalOprIDSrchString = &originalOprIDSrchString;
   End-If;

   If %Request.AuthTokenDomain <> "" Then
      &authTokenScript = "<script language=javascript>document.domain = '" | Right(%Request.AuthTokenDomain, Len(%Request.AuthTokenDomain) - 1) | "';</script>" | Char(13);
   End-If;

   /*Determine destination page and redirect*/
   Evaluate &action
   When "lookup"
      &adhocStateObj.initChunkState();
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Lookup");
   When "lookupNextChunk"
      &adhocStateObj.incrementChunkState();
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Lookup");
   When "lookupPrevChunk"
      &adhocStateObj.decrementChunkState();
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Lookup");
   When "lookupSearch"
   When "lookupDone"

      &html = &authTokenScript | "<script language='JavaScript'>window.parent.lookupDone(5,'" | &oprID | "');</script>";
      %Response.Write(&html);
      rem   &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Entry");
   When "lookupCancel"
      &adhocStateObj.oprID = &adhocStateObj.originalOprIDSrchString;
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Entry");
   When "submit"
      If &adhocStateObj.oprID = "" Then
         &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOAW, Field.EOAW_MON_ADHOC_NUI, "FieldFormula", "IScript_Adhoc_Entry") | "?NOOPRID=TRUE";
         %Response.RedirectURL(&URL)
      Else
         userIDIsValid();

         If &adhocStateObj.adhocType = "approver" Then
            &isApprover = True;
         Else
            &isApprover = False;
         End-If;

         &remoteboundHandler = create EOAW_APPROVAL_MM_FL:integration:outboundHandler();
         &para = &remoteboundHandler.takeAdhocAction(&adhocStateObj.adhocPosition, &adhocStateObj.procId, &adhocStateObj.thread, &adhocStateObj.oprID, &isApprover, &adhocStateObj.stepAfter, &adhocStateObj.stage);
         &html = &authTokenScript | "<script language='JavaScript'>window.parent.modalRelay(" | &para | ", 4);;</script>";
         %Response.Write(&html);

      End-If;
   When "cancel"
      rem &adhocStateObj = Null;
      &html = &authTokenScript | "<script language='JavaScript'>window.close()</script>";
      %Response.Write(&html);
   End-Evaluate;

   %Response.RedirectURL(&URL);
End-Function;

