Function IScript_approverInfoLookup()
   Local Rowset &approverInfoRS;
   Local Record &approverViewRecord;

   Local array of string &oprIDs = CreateArrayRept("", 0);
   Local array of string &oprIDStringArray = %Request.GetParameterValues("OPRID");
   Local string &oprIDString;
   Local string &approverViewName = %Request.GetParameter("APPROVERVIEW");
   &approverViewName = Substitute(&approverViewName, " ", "+");
   &approverViewName = Decrypt("", &approverViewName);

   Local string &awprcs_id = %Request.GetParameter("EOAWPRCS_ID");
   Local string &adhocAccessLogicPath;
   Local string &adhocAccessPackageName;
   Local string &threadDescrLogicPath;
   Local string &threadDescrPackageName;
   Local string &viewName;
   Local string &poolListName;
   Local string &validParameter;

   &approverViewName = Substring(&approverViewName, 1, CreateRecord(Record.PSRECDEFN).RECNAME.FieldLength);
   SQLExec("SELECT 'X' FROM PSRECDEFN WHERE RECNAME = :1", &approverViewName, &validParameter);

   If All(&validParameter) Then
      SQLExec(SQL.EOAW_MON_TXN_PARMS, &awprcs_id, &viewName, &poolListName, &adhocAccessLogicPath, &adhocAccessPackageName, &threadDescrPackageName, &threadDescrLogicPath);
      Local EOAW_monitor:monitor:threadDescrBase &threadDescr;
      If None(&threadDescrPackageName) Or
            None(&threadDescrLogicPath) Then
         &threadDescr = create EOAW_MONITOR:MONITOR:threadDescrBase();
      Else
         &threadDescr = CreateObject(&threadDescrPackageName | ":" | &threadDescrLogicPath);
      End-If;

      &StyleSheetURL = PTGetStyleSheetURL();
      &StyleSheetURL1 = getThemeStyleSheets();

      &HTML = "<link rel='stylesheet' type='text/css' href='" | &StyleSheetURL | "' />" | Char(13);
      &HTML = &HTML | &StyleSheetURL1;

      &PageTitle = "<font class='PAPAGETITLE'>" | MsgGetText(18081, 4065, "Message Not Found - Approver Contact Information") | "</font><br /><br />";

      &approverViewRecord = CreateRecord(@("Record." | &approverViewName));

      Local number &oprArray;
      For &oprArray = 1 To &oprIDStringArray.Len
         &oprIDString = &oprIDStringArray [&oprArray];
         &oprIDString = Substitute(&oprIDString, " ", "+");
         &oprIDString = Decrypt("", &oprIDString);
         &oprIDs.Push(Split(&oprIDString, ","));
      End-For;
      /*    Local number &index;
   Local string &idTemp;
While (Len(&oprIDString) > 2)
      &index = Find(",", &oprIDString);
      &idTemp = Substring(&oprIDString, 1, &index - 1);
      &oprIDs.Push(&idTemp);
      If (Len(&oprIDString) <= (&index + 1)) Then
         Break;
      End-If;
      &oprIDString = Substring(&oprIDString, &index + 1, Len(&oprIDString) - &index)
   End-While; */


      For &i = 1 To &oprIDs.Len
         &oprID = &oprIDs [&i];

         /*Set label for approver info groupbox*/
         If &oprIDs.Len = 1 Then
            &grpBoxLabel = MsgGetText(18081, 4073, "Message Not Found - 18081,4073,'Approver Information'");
         Else
            &grpBoxLabel = MsgGetText(18081, 4074, "Message Not Found - 18081,4074,'Approver #'") | &i;
         End-If;
         &grpBoxHdrHTML = GetHTMLText(HTML.EOAW_MON_APPR_INFO_HDR, &grpBoxLabel);

         /*Field #1 of the approver info view should always be OPRID*/
         rem &displayName = EscapeHTML(EscapeJavascriptString(&threadDescr.getUserName(&oprID)));
         &displayName = EscapeHTML(&threadDescr.getUserName(&oprID));
         &grpBoxRowsHTML = GetHTMLText(HTML.EOAW_MON_APPR_INFO_ROW, MsgGetText(18081, 4061, "Message Not Found - 18081,4061,'Name'") | ":", &displayName);

         /*Create and populate rowset with information about current approver using record defined by applications in transaction registry*/
         &approverInfoRS = CreateRowset(@("Record." | &approverViewName));
         &approverInfoRS.Fill("WHERE OPRID = :1", &oprID);

         /*Loop through remaining fields and display them*/
         For &j = 2 To &approverViewRecord.FieldCount
            &approverInfoField = &approverViewRecord.GetField(&j);
            rem &approverInfoFieldValue = EscapeHTML(EscapeJavascriptString(&approverInfoRS(1).GetRecord(@("Record." | &approverViewName)).GetField(@("Field." | &approverInfoField.name)).Value));
            &approverInfoFieldValue = EscapeHTML(&approverInfoRS(1).GetRecord(@("Record." | &approverViewName)).GetField(@("Field." | &approverInfoField.name)).Value);
            /*Code for lanugage sensitivity*/
            If %Language = %Language_Base Or
                  %Language = "" Then
               SQLExec("SELECT LONGNAME FROM PSDBFLDLABL_VW WHERE FIELDNAME = :1", &approverInfoField.name, &approverInfoFieldLabel);
            Else
               SQLExec("SELECT LONGNAME FROM PSDBFLDLBLLNG_V WHERE FIELDNAME = :1 AND LANGUAGE_CD = :2", &approverInfoField.name, %Language, &approverInfoFieldLabel);
               /* Default back to the base language in the event %language is not available */
               If (None(&approverInfoFieldLabel)) Then
                  SQLExec("SELECT LONGNAME FROM PSDBFLDLABL_VW WHERE FIELDNAME = :1", &approverInfoField.name, &approverInfoFieldLabel);
               End-If;
            End-If;
            &grpBoxRowsHTML = &grpBoxRowsHTML | GetHTMLText(HTML.EOAW_MON_APPR_INFO_ROW, &approverInfoFieldLabel | ":", &approverInfoFieldValue);
         End-For;

         Local string &grpBoxContentHTML = &grpBoxHdrHTML | &grpBoxRowsHTML;

         &HTML = &HTML | GetHTMLText(HTML.EOAW_MON_APPR_INFO_TBL, &grpBoxContentHTML);
      End-For;
   Else

      &HTML = &HTML | "<br /><center><span>" | MsgGetText(18081, 4086, "Message Not Found") | "</span></center>";


   End-If;

   &HTML = &HTML | "<br /><center class='pt_classic_plus'><a  class='PSPUSHBUTTONTB Left'><input type='button' onClick='window.close()' value='" | MsgGetText(18081, 4068, "Message Not Found") | "' class='PSPUSHBUTTON'></a></center>";
   %Response.Write(&HTML);
End-Function;

