   rem Local EOAW_EMC:API:emailFormManager &efm;
   Local Rowset &appRS = &utils.getAppRS(&msg.GetRowset());
   &appRS = populateRowsetWithSampleValues(&appRS);
   &msg.CopyRowset(&appRS);
   rem &efm = create EOAW_EMC:API:emailFormManager(&msg, %Language);

   Local EOAW_EMC:API:layoutCacheManager &layoutCacheMgr_ = create EOAW_EMC:API:layoutCacheManager();
   Local EOAW_EMC:MODEL_OBJECTS:formLayout &layout_ = &layoutCacheMgr_.getLayout(&msg, %Language);
   Local EOAW_EMC:MODEL_OBJECTS:formLayoutHTML &layoutHTML = &layoutCacheMgr_.getLayoutHTMLObj(&layout, "I");
   Local string &html = &layoutHTML.inlineHTML_;
   %Response.Write(GetHTMLText(HTML.EOAWEMC_PREVIEW_SKEL, &html, MsgGetText(18130, 5658, "Message Not Found - Close")));
   rem %Response.Write(GetHTMLText(HTML.EOAWEMC_PREVIEW_SKEL, &efm.genHTMLString(&layout), MsgGetText(18130, 5658, "Message Not Found - Close")));

   &layoutElements = Null;
   &layoutMsgName = "";
End-Function;

