import EOEW_ETLSRC:ETLSrcCriteriaDisplay;
import EOEW_ETLSRC:ETLSourceUI;

Component EOEW_ETLSRC:ETLSourceUI &mySdo;

Function IScript_CriteriaActionTaken()
   Local number &i;
   Local string &Val;
   Local Rowset &joCriteriaRS;
   Local EOEW_ETLSRC:ETLSrcCriteriaDisplay &joCriteriaDisplay;


   &joCriteriaDisplay = &mySdo.CriteriaDisplay;
   &joCriteriaRS = &joCriteriaDisplay.getNewRowset();

   &Val = %Request.GetParameter("EOEW_ACTIONROW");
   &joCriteriaDisplay.ActionRow = Value(&Val);

   /*
   &Val = %Request.GetParameter("EOEW_ACTIONVALUE");
   &joCriteriaDisplay.ActionValue = &Val;
   */

   /* Get action value from query manager, so external commands, like Search, can be handled*/
   &joCriteriaDisplay.ActionValue = &mySdo.ActionValue;


   &Val = %Request.GetParameter("EOEW_ROWCOUNT");
   &joCriteriaDisplay.RowCount = Value(&Val);

   /***
   &Val = %Request.GetParameter("EOEW_QUERYNAME");
   &joCriteriaDisplay.QueryName = &Val;
   ***/
   &joCriteriaDisplay.QueryName = EOEW_SRCDO.EOEW_SRCDONAME;

   For &i = 1 To &joCriteriaDisplay.RowCount

      If &i <> 1 Then
         &joCriteriaRS.InsertRow(&i - 1);
      End-If;

      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EOEW_SRCDONAME).Value = EOEW_SRCDO.EOEW_SRCDONAME;

      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EOEW_SRCTABLE).Value = %Request.GetParameter("EOEW_TABLE" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EOEW_SRCCOL).Value = %Request.GetParameter("EOEW_COLUMN" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.SEQ_NUM).Value = &i;
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EOEW_SRC_OPLOGICAL).Value = %Request.GetParameter("EOEW_OPLOGICAL" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EOEW_SRC_OPERATOR).Value = %Request.GetParameter("EOEW_OPERATOR" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EO_VALUE).Value = %Request.GetParameter("EOEW_VALUE" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EOEW_SRC_INDENTLVL).Value = %Request.GetParameter("EOEW_INDENTLVL" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EOEW_SRC_GRPSTART).Value = %Request.GetParameter("EOEW_GRPSTART" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EOEW_SRC_ENDPARENS).Value = %Request.GetParameter("EOEW_ENDPARENS" | &i);
      /* Set Tracking Fields */
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.CREATEDTTM).Value = %Datetime;
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.LASTUPDDTTM).Value = %Datetime;
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.LASTUPDOPRID).Value = %UserId;
   End-For;

   &joCriteriaDisplay.SetCriteriaRowset(&joCriteriaRS);
End-Function;

