End-Function;

Declare Function PortalOpen PeopleCode FUNCLIB_EOPP.EOPP_PORTALR FieldFormula;
Declare Function SpecifyPortalOpen PeopleCode FUNCLIB_EOPP.EOPP_PORTALR FieldFormula;

Local Rowset &rsBreadcrumbs;
Local ApiObject &Portal;

REM *******************************************************************;
REM Function:  LoadBreadcrumbRow                                       ;
REM Purpose:   Loads the Breadcrumb link into the Breadcrumb rowset    ;
REM            The Breadcrumbs display the current folder as a link.   ;
REM Inputs:    URL type (PSP/PSC), Indiv Link Style, Frame break (Y/N) ;
REM Output:    HTML for hrefs separated by a delimiter                 ;
REM *******************************************************************;
Function LoadBreadcrumbRow(&nCOLLPOS As number, &FREFPORTAL As string, &FREFNAME As string, &FREFLABEL As string, &SCNAME As string, &SECONDARY As string, &ISVIRTUAL As string, &PTFNAME As string, &PTCNAME As string, &BCACTION As string);

   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION.Value = &nCOLLPOS;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCFREFPRTL.Value = &FREFPORTAL;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCFREFNAME.Value = &FREFNAME;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCFREFLABEL.Value = &FREFLABEL;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCCOLLNAME.Value = &SCNAME;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCSECONDARY.Value = &SECONDARY;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCVIRTUAL.Value = &ISVIRTUAL;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCPTFNAME.Value = &PTFNAME;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCPTCNAME.Value = &PTCNAME;
   &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCACTION.Value = &BCACTION;

End-Function;

REM *******************************************************************;
REM Function:  LoadIAPath                                              ;
REM Purpose:   Loads IA folder path for the RefName into the BC Rowset ;
REM Inputs:    Portal Api, RefType, ObjName, scName, pt_fname, pt_cname;
REM Output:    none                                                    ;
REM *******************************************************************;
Function LoadIAPath(&refTYPE As string, &refNAME As string, &refSCNAME As string, &refSCLABEL As string, &refPTFNAME As string, &refPTCNAME As string, &SHOW_MAIN_MENU As string, &MAIN_MENU_NAME As string, &MAIN_MENU_LABEL, &MAIN_MENU_COUNT As number);

   Local string &PATH, &refLABEL, &PATHNAME, &PATHLABEL, &QSFNAME, &BCLABEL, &QSTARGPORTAL, &QSSECONDARY, &QSBCACTION, &QSISVIRTUAL, &QSSCNAME, &QSPTFNAME, &QSPTCNAME;
   Local number &StartPos, &LeftParenPos, &RightParenPos, &nCOLLPOS, &I;
   Local ApiObject &refObj, &pathObj;

   REM Initialize values;
   &QSTARGPORTAL = "";
   &QSISVIRTUAL = "";
   &QSBCACTION = "";
   &nCOLLPOS = 0;

   /* Don't Show Main Menu Folder Twice when CFAN = Main Menu */
   If &MAIN_MENU_COUNT > 1 And
         &refSCNAME = &MAIN_MENU_NAME And
         &refTYPE = "C" Then /* Picks up the Main Menu from the Collection Link */
      &SHOW_MAIN_MENU = "N";
   End-If;

   /* Don't show Main Menu Folder Thrice when CFAN = Main Menu */
   If &MAIN_MENU_COUNT = 1 And
         &refSCNAME = &MAIN_MENU_NAME And
         &refTYPE = "C" Then /* Do not load IA, Main Menu shows from Collection Link */
   Else

      /* Get the IA path of the Reference Object Name */
      Evaluate &refTYPE
      When = "C"
         &refObj = &Portal.FindCrefByName(&refNAME);
         If &refObj <> Null Then
            &PATH = &refObj.Path;
            &refLABEL = &refObj.Label;
         End-If;
      When = "F"
         &refObj = &Portal.FindFolderByName(&refNAME);
         If &refObj <> Null Then
            &PATH = &refObj.Path;
            &refLABEL = &refObj.Label;
         End-If;
      End-Evaluate;

      /* Parse the path for the Folder Label and Folder Object Name */
      /* Example: "Root{PORTAL_ROOT_OBJECT}.SA{STUDENT_ADMIN}.Student Records{STUDENT_RECS}" */
      &StartPos = 1;
      &LeftParenPos = Find("{", &PATH, &StartPos);
      While &LeftParenPos <> 0;
         &PATHLABEL = Substring(&PATH, &StartPos, &LeftParenPos - &StartPos);
         &RightParenPos = Find("}", &PATH, &StartPos);
         &PATHNAME = Substring(&PATH, &LeftParenPos + 1, &RightParenPos - (&LeftParenPos + 1));
         &StartPos = Find("}.", &PATH, &StartPos);
         If &StartPos > 0 Then
            &StartPos = &StartPos + 2;
            &LeftParenPos = Find("{", &PATH, &StartPos);
         Else
            &LeftParenPos = 0;
         End-If;

         If &PATHNAME = "PORTAL_ROOT_OBJECT" Then
            If &SHOW_MAIN_MENU = "Y" Then

               /* For IAPath Breadcrumb Links, always switch to DFAN mode */
               &QSPTFNAME = &MAIN_MENU_NAME;
               &QSPTCNAME = "";

               /* Set Rowset Values */
               &nCOLLPOS = &nCOLLPOS + 1;

               If &nCOLLPOS > 1 Then /* Not first Breadcrumb */
                  &rsBreadcrumbs.InsertRow(&nCOLLPOS - 1);
                  &QSSCNAME = &MAIN_MENU_NAME;
                  &QSFNAME = &MAIN_MENU_NAME;
                  &BCLABEL = &MAIN_MENU_LABEL;
                  &QSSECONDARY = "true";

               Else /* First Breadcrumb */
                  &QSSCNAME = &MAIN_MENU_NAME;
                  &QSFNAME = "";
                  &BCLABEL = &MAIN_MENU_LABEL;
                  &QSSECONDARY = "";
               End-If;

               LoadBreadcrumbRow(&nCOLLPOS, &QSTARGPORTAL, &QSFNAME, &BCLABEL, &QSSCNAME, &QSSECONDARY, &QSISVIRTUAL, &QSPTFNAME, &QSPTCNAME, &QSBCACTION);
            End-If;

         Else
            /* Check that Nav folder is available */
            &pathObj = &Portal.FindFolderByName(&PATHNAME);
            If &pathObj <> Null Then
               If &pathObj.authorized And
                     &pathObj.isVisible Then
                  If &pathObj.validfrom <= %Date And
                        (&pathObj.validto >= %Date Or
                           &pathObj.validto = "") Then

                     REM - For IAPath Breadcrumb Links, always switch to DFAN mode;
                     &QSPTFNAME = &PATHNAME;
                     &QSPTCNAME = "";

                     /* Set Rowset Values */
                     &nCOLLPOS = &nCOLLPOS + 1;

                     If &nCOLLPOS > 1 Then /* Not first Breadcrumb */
                        &rsBreadcrumbs.InsertRow(&nCOLLPOS - 1);
                        &QSSCNAME = &PATHNAME;
                        &QSFNAME = &PATHNAME;
                        &BCLABEL = &PATHLABEL;
                        &QSSECONDARY = "true";

                     Else /* First Breadcrumb */
                        &QSSCNAME = &PATHNAME;
                        &QSFNAME = "";
                        &BCLABEL = &PATHLABEL;
                        &QSSECONDARY = "";
                     End-If;

                     LoadBreadcrumbRow(&nCOLLPOS, &QSTARGPORTAL, &QSFNAME, &BCLABEL, &QSSCNAME, &QSSECONDARY, &QSISVIRTUAL, &QSPTFNAME, &QSPTCNAME, &QSBCACTION);
                  End-If;
               End-If;
            End-If;
         End-If;
      End-While;

      REM - Include IA RefObject to rowset;

      REM - Retain collection origin;
      If All(&refPTCNAME) Then
         &QSPTCNAME = &refPTCNAME;
      Else
         &QSPTFNAME = &PATHNAME;
      End-If;

      REM - Set Rowset Values;
      &nCOLLPOS = &nCOLLPOS + 1;
      If &nCOLLPOS > 1 Then /* Not first Breadcrumb */
         &rsBreadcrumbs.InsertRow(&nCOLLPOS - 1);

         If &refTYPE = "C" Then /* Create CFAN Breadcrumb (> Collection Name >) */
            &QSSCNAME = &refSCNAME;
            &QSFNAME = &refSCNAME;
            &BCLABEL = &refSCLABEL;
            &QSSECONDARY = "true";
         Else /* Create DFAN Breadcrumb (> Folder Name >) */
            &QSSCNAME = &refSCNAME;
            &QSFNAME = &refNAME;
            &BCLABEL = &refLABEL;
            &QSSECONDARY = "true";
         End-If;

      Else /* First Breadcrumb */
         If &refTYPE = "C" Then /* Create CFAN Breadcrumb ( Collection Name > ) */
            &QSSCNAME = &refSCNAME;
            &QSFNAME = "";
            &BCLABEL = &refSCLABEL;
            &QSSECONDARY = "";
         Else /* Create DFAN Breadcrumb ( Folder Name > ) */
            &QSSCNAME = &refSCNAME;
            &QSFNAME = "";
            &BCLABEL = &refLABEL;
            &QSSECONDARY = "";
         End-If;
      End-If;

      LoadBreadcrumbRow(&nCOLLPOS, &QSTARGPORTAL, &QSFNAME, &BCLABEL, &QSSCNAME, &QSSECONDARY, &QSISVIRTUAL, &QSPTFNAME, &QSPTCNAME, &QSBCACTION);

   End-If;
End-Function;

REM *******************************************************************;
REM Function:  LoadCollPath                                            ;
REM Purpose:   Loads CFAN Navigation path into the BC Rowset           ;
REM Inputs:    Portal Api, RefType, ObjName, scName, pt_fname, pt_cname;
REM Output:    none                                                    ;
REM *******************************************************************;
Function LoadCollPath(&refFNAME As string, &refTARGPORTAL As string, &refSCNAME As string, &refSCLABEL As string, &refPTCNAME As string, &SHOW_MAIN_MENU, &MAIN_MENU_NAME);

   Local ApiObject &fnamePortal, &fnameObj, &fnamePathLinkObj, &collLinkObj, &collLinkPathFolderObj, &virtNavPathFolderObj;
   Local boolean &bfnamePortalIsOpen, &bAddToRowset, &bStopProcessing;
   Local SQL &getFolderLinks;

   Local number &nCOLLPOS;
   Local number &fnamePathStartPos, &fnamePathLeftPos, &fnamePathRightPos;
   Local number &fnamePathLinkPathStartPos, &fnamePathLinkPathLeftPos, &fnamePathLinkPathRightPos;
   Local number &collLinkPathStartPos, &collLinkPathLeftPos, &collLinkPathRightPos;
   Local number &virtNavPathStartPos, &virtNavPathLeftPos, &virtNavPathRightPos;

   Local string &fnamePortalName, &fnameTargPortalName, &fnameLabel;
   Local string &collLink, &collLinkLabel, &virtNavFolder, &fnamePathLink;
   Local string &fnamePath, &fnamePathFolder, &fnamePathLabel;
   Local string &fnamePathLinkPath, &fnamePathLinkPathFolder, &fnamePathLinkPathLabel;
   Local string &collLinkPath, &collLinkPathFolder, &collLinkPathLabel;
   Local string &virtNavPath, &virtNavPathFolder, &virtNavPathLabel;
   Local string &QSFNAME, &BCLABEL, &QSTARGPORTAL, &QSSECONDARY, &QSBCACTION, &QSISVIRTUAL, &QSSCNAME, &QSPTFNAME, &QSPTCNAME;

   REM - Is always CFAN mode;

   &QSSCNAME = &refSCNAME;
   &QSPTFNAME = "";
   &QSPTCNAME = &refPTCNAME;
   &QSISVIRTUAL = "";
   &QSBCACTION = "";

   If All(&refTARGPORTAL) Then
      &fnamePortalName = &refTARGPORTAL;

      If &refTARGPORTAL = "LOCAL_PORTAL" Then
         &fnameTargPortalName = %Portal;
      Else
         &fnameTargPortalName = &refTARGPORTAL;
      End-If;

      If &fnameTargPortalName <> %Portal Then
         &fnamePortal = SpecifyPortalOpen(&fnameTargPortalName);
         &bfnamePortalIsOpen = True;
      Else
         &fnamePortal = &Portal;
         &bfnamePortalIsOpen = False;
      End-If;
   Else
      &fnamePortal = &Portal;
      &fnamePortalName = %Portal;
   End-If;

   &fnameObj = &fnamePortal.FindFolderByName(&refFNAME);
   If &fnameObj <> Null Then
      If &fnameObj.authorized Then
         &fnameLabel = &fnameObj.Label;

         REM - Initilize Collection Link and Virtual Nav Folder;
         &collLink = "";
         &collLinkObj = Null;
         &virtNavFolder = "";

         If &fnameObj.Product <> "CFAN" Then /* fname is not defined in a collection */

            /*
             # Find the collection link and Virtual Nav Folder (link's target object),
             # up the path, that IS defined in THIS collection
            */

            REM - Find the parent of the fname that is in THIS collection;
            &fnamePath = &fnameObj.Path;

            REM Parse the path for fname object;
            &fnamePathStartPos = 1;
            &fnamePathLeftPos = Find("{", &fnamePath, &fnamePathStartPos);
            While &fnamePathLeftPos <> 0;
               &fnamePathLabel = Substring(&fnamePath, &fnamePathStartPos, &fnamePathLeftPos - &fnamePathStartPos);
               &fnamePathRightPos = Find("}", &fnamePath, &fnamePathStartPos);
               &fnamePathFolder = Substring(&fnamePath, &fnamePathLeftPos + 1, &fnamePathRightPos - (&fnamePathLeftPos + 1));
               &fnamePathStartPos = Find("}.", &fnamePath, &fnamePathStartPos);
               If &fnamePathStartPos > 0 Then
                  &fnamePathStartPos = &fnamePathStartPos + 2;
                  &fnamePathLeftPos = Find("{", &fnamePath, &fnamePathStartPos);
               Else
                  &fnamePathLeftPos = 0;
               End-If;

               REM - Loop through all collection objects that have the fnamePathFolder as a link;
               &getFolderLinks = GetSQL(SQL.EOPP_SCBCGETFOLDERLINKS, &Portal.Name, &fnamePathFolder, &fnamePortalName);

               While &getFolderLinks.Fetch(&fnamePathLink)
                  If &bStopProcessing = False Then
                     &fnamePathLinkObj = &Portal.FindFolderByName(&fnamePathLink);
                     If &fnamePathLinkObj <> Null Then
                        If &fnamePathLinkObj.authorized Then

                           REM - Check if the fnamePathLink is in THIS collection;
                           &fnamePathLinkPath = &fnamePathLinkObj.Path;

                           REM Parse the path for fnamePathLinkPath object;
                           &fnamePathLinkPathStartPos = 1;
                           &fnamePathLinkPathLeftPos = Find("{", &fnamePathLinkPath, &fnamePathLinkPathStartPos);
                           While &fnamePathLinkPathLeftPos <> 0;
                              &fnamePathLinkPathLabel = Substring(&fnamePathLinkPath, &fnamePathLinkPathStartPos, &fnamePathLinkPathLeftPos - &fnamePathLinkPathStartPos);
                              &fnamePathLinkPathRightPos = Find("}", &fnamePathLinkPath, &fnamePathLinkPathStartPos);
                              &fnamePathLinkPathFolder = Substring(&fnamePathLinkPath, &fnamePathLinkPathLeftPos + 1, &fnamePathLinkPathRightPos - (&fnamePathLinkPathLeftPos + 1));
                              &fnamePathLinkPathStartPos = Find("}.", &fnamePathLinkPath, &fnamePathLinkPathStartPos);
                              If &fnamePathLinkPathStartPos > 0 Then
                                 &fnamePathLinkPathStartPos = &fnamePathLinkPathStartPos + 2;
                                 &fnamePathLinkPathLeftPos = Find("{", &fnamePathLinkPath, &fnamePathLinkPathStartPos);
                              Else
                                 &fnamePathLinkPathLeftPos = 0;
                              End-If;

                              If &fnamePathLinkPathFolder = &refSCNAME Then

                                 REM - The fnamePathLink is in THIS collection;
                                 &collLinkObj = &fnamePathLinkObj;
                                 &collLink = &fnamePathLink;
                                 &collLinkLabel = &fnamePathLinkObj.Label;
                                 &virtNavFolder = &fnamePathFolder;

                                 REM - Stop Processing;
                                 &fnamePathLinkPathLeftPos = 0;
                                 &fnamePathLeftPos = 0;
                                 &bStopProcessing = True;

                              End-If;
                           End-While;
                        End-If;
                     End-If;
                  End-If;
               End-While;
               &getFolderLinks.Close();
            End-While;

         Else /* fname IS defined in THIS collection (product = "CFAN") */
            &collLinkObj = &fnameObj;
            &collLink = &refFNAME;
            &collLinkLabel = &fnameObj.Label;
            &virtNavFolder = "";

         End-If;

         /*
          # Add Collection Path to Breadcrumbs.
          # Collection Link is in the collection's portal = current portal = &Portal.
          # Find Path between Collection Name and Collection Link.
          # Do not include Collection Name in rowset (is present from IA Path).
          # Include Collection Link in rowset.
         */

         If All(&collLink) Then

            If &collLink <> &refSCNAME Then /* Skip if =, since Collection Name already exists from IA path*/

               &refSCNAMEObj = &Portal.FindFolderByName(&refSCNAME);
               If &refSCNAMEObj <> Null Then
                  &refSCNAMECount = &refSCNAMEObj.Folders.Count + &refSCNAMEObj.ContentRefs.Count
               End-If;

               REM - Sort the rowset to get the greatest link position;
               &rsBreadcrumbs.Sort(EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION, "A");
               &nCOLLPOS = &rsBreadcrumbs(&rsBreadcrumbs.ActiveRowCount).EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION.Value;

               If (&collLinkObj.ParentName = &refSCNAME) And
                     (&refSCNAMECount = 1) And
                     &nCOLLPOS > 0 And
                     &refSCNAME <> &MAIN_MENU_NAME Then

                  /* 
                   # Don't go through regular process if Collection Name count = 1,
                   # and the Collection Link's parent is the Collection Name,
                   # and Collection Name is not Main Menu (need process, since skipped IA).
                   # Since Collection Count = 1, the Collection Link IS the only Collection path 
                   # Instead of showing > Collection Name > Collection Link >, allow autoexpand
                   # to only show Collection Name, but with Collection Link fname.
                   # Update the existing Collection Name breadcrumb row in the rowset.
                  */

                  &rsBreadcrumbs(&nCOLLPOS).EOPP_SCBCFL_DVW.EOPP_SCBCFREFNAME.Value = &collLink;

               Else

                  &QSTARGPORTAL = "";

                  &bAddToRowset = False; /* Skip until after hit the Collection Folder */
                  &collLinkPath = &collLinkObj.Path;

                  REM Parse the path for fname object;
                  &collLinkPathStartPos = 1;
                  &collLinkPathLeftPos = Find("{", &collLinkPath, &collLinkPathStartPos);
                  While &collLinkPathLeftPos <> 0;
                     &collLinkPathLabel = Substring(&collLinkPath, &collLinkPathStartPos, &collLinkPathLeftPos - &collLinkPathStartPos);
                     &collLinkPathRightPos = Find("}", &collLinkPath, &collLinkPathStartPos);
                     &collLinkPathFolder = Substring(&collLinkPath, &collLinkPathLeftPos + 1, &collLinkPathRightPos - (&collLinkPathLeftPos + 1));
                     &collLinkPathStartPos = Find("}.", &collLinkPath, &collLinkPathStartPos);
                     If &collLinkPathStartPos > 0 Then
                        &collLinkPathStartPos = &collLinkPathStartPos + 2;
                        &collLinkPathLeftPos = Find("{", &collLinkPath, &collLinkPathStartPos);
                     Else
                        &collLinkPathLeftPos = 0;
                     End-If;

                     If &bAddToRowset Then
                        REM - Check that Collection Link Path folder is available;
                        &collLinkPathFolderObj = &Portal.FindFolderByName(&collLinkPathFolder);
                        If &collLinkPathFolderObj <> Null Then
                           If &collLinkPathFolderObj.authorized And
                                 &collLinkPathFolderObj.isVisible Then
                              If &collLinkPathFolderObj.validfrom <= %Date And
                                    (&collLinkPathFolderObj.validto >= %Date Or
                                       &collLinkPathFolderObj.validto = "") Then

                                 REM - Set Rowset Values;
                                 &nCOLLPOS = &nCOLLPOS + 1;

                                 If &nCOLLPOS > 1 Then
                                    &rsBreadcrumbs.InsertRow(&nCOLLPOS - 1);
                                 End-If;

                                 &QSFNAME = &collLinkPathFolder;
                                 &BCLABEL = &collLinkPathLabel;
                                 &QSSECONDARY = "true";

                                 LoadBreadcrumbRow(&nCOLLPOS, &QSTARGPORTAL, &QSFNAME, &BCLABEL, &QSSCNAME, &QSSECONDARY, &QSISVIRTUAL, &QSPTFNAME, &QSPTCNAME, &QSBCACTION);

                              End-If;
                           End-If;
                        End-If;
                     End-If;

                     If &collLinkPathFolder = &refSCNAME Then
                        REM - Include the next iteration;
                        &bAddToRowset = True;

                        REM - Sort the rowset to get the greatest link position;
                        &rsBreadcrumbs.Sort(EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION, "A");
                        &nCOLLPOS = &rsBreadcrumbs(&rsBreadcrumbs.ActiveRowCount).EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION.Value;

                     End-If;
                  End-While;

                  REM - Include Collection Link in rowset;

                  REM - Sort the rowset to get the greatest link position;
                  &rsBreadcrumbs.Sort(EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION, "A");
                  &nCOLLPOS = &rsBreadcrumbs(&rsBreadcrumbs.ActiveRowCount).EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION.Value;

                  REM - Set Rowset Values;
                  &nCOLLPOS = &nCOLLPOS + 1;

                  If &nCOLLPOS > 1 Then /* Not first Breadcrumb */
                     &rsBreadcrumbs.InsertRow(&nCOLLPOS - 1);
                     &QSFNAME = &collLink;
                     &BCLABEL = &collLinkLabel;
                     &QSSECONDARY = "true";

                  Else /* First Breadcrumb */
                     &QSFNAME = "";
                     &BCLABEL = &collLinkLabel;
                     &QSSECONDARY = "";

                     If &refSCNAME = &MAIN_MENU_NAME Then
                        &QSPTFNAME = &MAIN_MENU_NAME;
                        &QSPTCNAME = "";
                        &BCLABEL = &MAIN_MENU_LABEL;
                     End-If;

                  End-If;


                  LoadBreadcrumbRow(&nCOLLPOS, &QSTARGPORTAL, &QSFNAME, &BCLABEL, &QSSCNAME, &QSSECONDARY, &QSISVIRTUAL, &QSPTFNAME, &QSPTCNAME, &QSBCACTION);

               End-If;
            End-If;
         End-If;

         /*
          # Add Virtual Navigation Path to Breadcrumbs.
          # Virtual Navigation Folder is in the targetportal, i.e. &fnamePortal.
          # Find Path between Virtual Navigation Folder and fname.
          # Do not include Virtual Navigation folder in rowset (is present as collLink).
          # Include fname in rowset.
         */

         If All(&virtNavFolder) Then

            &QSTARGPORTAL = &refTARGPORTAL;

            &bAddToRowset = False; /* Skip until after hit the Virtual Nav Folder */
            &virtNavPath = &fnamePath; /* Already have this path, use again */

            REM Parse the path for fname object;
            &virtNavPathStartPos = 1;
            &virtNavPathLeftPos = Find("{", &virtNavPath, &virtNavPathStartPos);
            While &virtNavPathLeftPos <> 0;
               &virtNavPathLabel = Substring(&virtNavPath, &virtNavPathStartPos, &virtNavPathLeftPos - &virtNavPathStartPos);
               &virtNavPathRightPos = Find("}", &virtNavPath, &virtNavPathStartPos);
               &virtNavPathFolder = Substring(&virtNavPath, &virtNavPathLeftPos + 1, &virtNavPathRightPos - (&virtNavPathLeftPos + 1));
               &virtNavPathStartPos = Find("}.", &virtNavPath, &virtNavPathStartPos);
               If &virtNavPathStartPos > 0 Then
                  &virtNavPathStartPos = &virtNavPathStartPos + 2;
                  &virtNavPathLeftPos = Find("{", &virtNavPath, &virtNavPathStartPos);
               Else
                  &virtNavPathLeftPos = 0;
               End-If;

               If &bAddToRowset Then
                  REM - Check that Nav Virtual Path folder is available;
                  &virtNavPathFolderObj = &fnamePortal.FindFolderByName(&virtNavPathFolder);
                  If &virtNavPathFolderObj <> Null Then
                     If &virtNavPathFolderObj.authorized And
                           &virtNavPathFolderObj.isVisible Then
                        If &virtNavPathFolderObj.validfrom <= %Date And
                              (&virtNavPathFolderObj.validto >= %Date Or
                                 &virtNavPathFolderObj.validto = "") Then

                           REM - Set Rowset Values;
                           &nCOLLPOS = &nCOLLPOS + 1;

                           If &nCOLLPOS > 1 Then
                              &rsBreadcrumbs.InsertRow(&nCOLLPOS - 1);
                           End-If;

                           &QSFNAME = &virtNavPathFolder;
                           &BCLABEL = &virtNavPathLabel;
                           &QSSECONDARY = "true";

                           LoadBreadcrumbRow(&nCOLLPOS, &QSTARGPORTAL, &QSFNAME, &BCLABEL, &QSSCNAME, &QSSECONDARY, &QSISVIRTUAL, &QSPTFNAME, &QSPTCNAME, &QSBCACTION);

                        End-If;
                     End-If;
                  End-If;
               End-If;

               If &virtNavPathFolder = &virtNavFolder Then
                  REM - Include the next iteration;
                  &bAddToRowset = True;

                  REM - Sort the rowset to get the greatest link position;
                  &rsBreadcrumbs.Sort(EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION, "A");
                  &nCOLLPOS = &rsBreadcrumbs(&rsBreadcrumbs.ActiveRowCount).EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION.Value;

               End-If;
            End-While;

            REM - Include fname in rowset;

            REM - Sort the rowset to get the greatest link position;
            &rsBreadcrumbs.Sort(EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION, "A");
            &nCOLLPOS = &rsBreadcrumbs(&rsBreadcrumbs.ActiveRowCount).EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION.Value;

            REM - Set Rowset Values;
            &nCOLLPOS = &nCOLLPOS + 1;

            If &nCOLLPOS > 1 Then
               &rsBreadcrumbs.InsertRow(&nCOLLPOS - 1);
            End-If;

            &QSFNAME = &refFNAME;
            &BCLABEL = &fnameLabel;
            &QSSECONDARY = "true";

            LoadBreadcrumbRow(&nCOLLPOS, &QSTARGPORTAL, &QSFNAME, &BCLABEL, &QSSCNAME, &QSSECONDARY, &QSISVIRTUAL, &QSPTFNAME, &QSPTCNAME, &QSBCACTION);

         End-If;
      End-If;
   End-If;

   If &bfnamePortalIsOpen Then
      &fnamePortal.Close();
   End-If;

End-Function;

REM *******************************************************************;
REM Function:  BuildBCLink                                             ;
REM Purpose:   Builds the HTML href for the Breadcrumb folder hyperlink;
REM Inputs:    Folder Portal Name, Folder Object Name, Folder Label    ;
REM            Shortcut Collection, Virtual (True=not FRef in coll),   ;
REM            Secondary (true=show breadcrumbs), URL type (psc/psp),  ;
REM            Indiv Link StyleClass, Frame break (Y/N),               ;
REM            Folder Breacrumb Action (' '/A/D/C)                     ;
REM Output:    Single HTML href hyperlink                              ;
REM *******************************************************************;
Function BuildBCLink(&FREFPORTAL As string, &FREFNAME As string, &FREFLABEL As string, &SCNAME As string, &ISVIRTUAL As string, &SECONDARY As string, &URLTYPE As string, &BCLINKCLASS As string, &TOP As string, &PTFNAME As string, &PTCNAME As string, &BCACTION As string, &DELIMITER As string, &CACHEVALUE As string) Returns string;

   Local string &LOCATION, &URL, &LINKHTML;

   Evaluate Upper(&URLTYPE)
   When = "PSC"
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", "IScript_AppHP");
   When = "PSP"
      &URL = GenerateScriptPortalURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", "IScript_AppHP");
   When-Other
      &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", "IScript_AppHP");
   End-Evaluate;

   &URL = &URL | "?scname=" | &SCNAME;
   If All(&SECONDARY) Then
      &URL = &URL | "&secondary=" | &SECONDARY;
   End-If;
   If All(&FREFNAME) Then
      &URL = &URL | "&fname=" | &FREFNAME;
   End-If;
   If All(&PTCNAME) Then
      &URL = &URL | "&PORTALPARAM_PTCNAV=" | &PTCNAME;
   Else
      If All(&PTFNAME) Then
         &URL = &URL | "&pt_fname=" | &PTFNAME;
      End-If;
   End-If;
   If All(&FREFPORTAL) Then
      &URL = &URL | "&targetportal=" | &FREFPORTAL;
   End-If;
   If Upper(&ISVIRTUAL) = "TRUE" Then
      &URL = &URL | "&isvirtual=" | &ISVIRTUAL;
   End-If;
   If All(&BCACTION) Then
      &URL = &URL | "&eoppbc=" | &BCACTION;
   End-If;

   If All(&CACHEVALUE) And
         Upper(&URLTYPE) = "PSC" Then
      &URL = &URL | "&PortalCacheContent=true&PSCache-Control=" | EncodeURLForQueryString(&CACHEVALUE);
   End-If;

   If None(&BCLINKCLASS) Then
      &BCLINKCLASS = "PSHYPERLINK";
   End-If;
   If Upper(&TOP) = "Y" Then
      &LINKHTML = GetHTMLText(HTML.EOPP_HYPERLINK_TARGET, &URL, &BCLINKCLASS, &FREFLABEL, "_parent");
   Else
      &LINKHTML = GetHTMLText(HTML.EOPP_HYPERLINK, &URL, &BCLINKCLASS, &FREFLABEL);
   End-If;
   If All(&DELIMITER) Then
      &LINKHTML = &LINKHTML | "&nbsp" | &DELIMITER | "&nbsp";
   End-If;

   Return &LINKHTML;
End-Function;

REM *******************************************************************;
REM Function:  BuildBCHTML                                             ;
REM Purpose:   Builds the BC Links from the rowset for a NavPage.  The ;
REM            Breadcrumbs do NOT display the current folder as a link.;
REM Inputs:    URL type (PSP/PSC), Indiv Link Style, Frame break (Y/N) ;
REM Output:    HTML for hrefs separated by a delimiter                 ;
REM *******************************************************************;
Function BuildBCHTML(&URLTYPE As string, &BCLINKCLASS As string, &TOP As string, &DELIMITER As string, &CACHEVALUE As string) Returns string;
   Local string &FREFNAME, &FREFLABEL, &FREFPORTAL, &BCLINKHTML, &BREADCRUMBHTML, &SECONDARY, &PTFNAME, &PTCNAME, &BCACTION, &ISVIRTUAL, &SCNAME;
   Local number &I;

   REM - The current folder is retained, but not diplayed in breadcrumbs, hence the '- 1';
   &rsBreadcrumbs.Sort(EOPP_SCBCFL_DVW.EOPP_SCBCPOSITION, "A");
   For &I = 1 To &rsBreadcrumbs.ActiveRowCount - 1
      &FREFPORTAL = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCFREFPRTL.Value;
      &FREFNAME = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCFREFNAME.Value;
      &FREFLABEL = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCFREFLABEL.Value;
      &SCNAME = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCCOLLNAME.Value;
      &ISVIRTUAL = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCVIRTUAL.Value;
      &SECONDARY = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCSECONDARY.Value;
      &PTFNAME = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCPTFNAME.Value;
      &PTCNAME = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCPTCNAME.Value;
      &BCACTION = &rsBreadcrumbs(&I).EOPP_SCBCFL_DVW.EOPP_SCBCACTION.Value;
      &BCLINKHTML = &BCLINKHTML | BuildBCLink(&FREFPORTAL, &FREFNAME, &FREFLABEL, &SCNAME, &ISVIRTUAL, &SECONDARY, &URLTYPE, &BCLINKCLASS, &TOP, &PTFNAME, &PTCNAME, &BCACTION, &DELIMITER, &CACHEVALUE);
   End-For;

   Return &BCLINKHTML;
End-Function;

REM *******************************************************************;
REM Function:  BuildBreadcrumbs                                        ;
REM Purpose:   Builds the HTML Cell for the Folder Breadcrumbs.        ;
REM            Only initializes Content Target Crefs. For NavPages,    ;
REM            assumes the non-secondary page initialized the rowset.  ;
REM Inputs:    Shortcut Collection, Shortcut Label, Site Type(HTML/'') ;
REM            URL type (psc/psp), Entire Breadcrumb Cell StyleClass,  ;
REM            Individual Link Style, Frame break (Y/N)                ;
REM Output:    HTML Breadcrumb Cell                                    ;
REM Note:      isvirtual=True --> folder is not explicit in collection ;
REM            secondary=True --> no parent - do not show breadcrumbs  ;
REM *******************************************************************;
Function BuildBreadcrumbs(&SCNAME As string, &SCLABEL, &URLTYPE As string, &SITETYPE As string, &TOP As string, &PTFNAME As string, &PTCNAME As string, &CACHEVALUE As string) Returns string;

   Local string &SHOW_MAIN_MENU, &MAIN_MENU_NAME, &MainMenuName, &MainMenuLabel, &rqfname, &rqpgltsc, &rqtargetportal, &rqsecondary, &rqisvirtual, &rqeoppbc, &BCLINKCLASS, &BCCELLCLASS, &DELIMITER, &BCLINKHTML, &BREADCRUMBHTML;
   Local number &nCOLLPOS, &MainMenuFldrCount;
   Local ApiObject &MainMenuObj;

   &BCLINKCLASS = "EOPP_SCBREADCRUMBSECTION";
   &BCCELLCLASS = "EOPP_SCBREADCRUMBSECTION";
   &DELIMITER = ">";

   REM - Get the qstring values for the clicked link;
   &rqpgltsc = %Request.GetParameter("pgltsc");
   &rqtargetportal = %Request.GetParameter("targetportal");
   &rqfname = %Request.GetParameter("fname");
   &rqisvirtual = %Request.GetParameter("isvirtual");
   &rqsecondary = %Request.GetParameter("secondary");
   &rqeoppbc = %Request.GetParameter("eoppbc");

   &Portal = PortalOpen();
   &rsBreadcrumbs = CreateRowset(Record.EOPP_SCBCFL_DVW);

   REM - Initialize Main Menu Info;
   &MainMenuFldrCount = 0;
   &MainMenuLabel = "";
   &MainMenuName = "";
   &SHOW_MAIN_MENU = "";

   REM - Get Main Menu Info;
   SQLExec(SQL.EOPP_SCBCGETSITEROOT, %Portal, &SHOW_MAIN_MENU, &MAIN_MENU_NAME);
   If None(&SHOW_MAIN_MENU) Then
      SQLExec(SQL.EOPP_SCBCGETSYSROOT, &SHOW_MAIN_MENU, &MAIN_MENU_NAME);
      If None(&SHOW_MAIN_MENU) Then
         &SHOW_MAIN_MENU = "N"
      End-If;
   End-If;

   &MainMenuObj = &Portal.FindFolderByName(&MAIN_MENU_NAME);
   If &MainMenuObj <> Null Then

      REM - Check the Main Menu collection access;
      If &MainMenuObj.authorized Then
         &MainMenuFldrCount = &MainMenuObj.Folders.Count + &MainMenuObj.ContentRefs.Count;
         &MainMenuLabel = &MainMenuObj.Label;
         &MainMenuName = &MainMenuObj.Name;

         If &MainMenuObj.validfrom <= %Date And
               (&MainMenuObj.validto >= %Date Or
                  &MainMenuObj.validto = "") Then
         Else
            &SHOW_MAIN_MENU = "N";
         End-If;
      Else
         &SHOW_MAIN_MENU = "N";
      End-If;
   Else
      &SHOW_MAIN_MENU = "N";
   End-If;

   If &SHOW_MAIN_MENU = "N" Then
      &MainMenuName = "";
      &MainMenuLabel = "";
      &MainMenuFldrCount = 0;
   End-If;

   If All(&PTFNAME) Then /* Originated from DFAN folder */
      REM - Load LeftNav IA Breadcrumbs;
      LoadIAPath("F", &PTFNAME, &SCNAME, &SCLABEL, &PTFNAME, &PTCNAME, &SHOW_MAIN_MENU, &MainMenuName, &MainMenuLabel, &MainMenuFldrCount);

   Else
      If All(&PTCNAME) Then /* Originated from CFAN content */
         REM - Load LeftNav IA Breadcrumbs;
         LoadIAPath("C", &PTCNAME, &SCNAME, &SCLABEL, &PTFNAME, &PTCNAME, &SHOW_MAIN_MENU, &MainMenuName, &MainMenuLabel, &MainMenuFldrCount);

         If All(&rqfname) Then /* Clicked folder link in CFAN NavPage */
            REM - Load Collection Navigation Breadcrumbs;
            LoadCollPath(&rqfname, &rqtargetportal, &SCNAME, &SCLABEL, &PTCNAME, &SHOW_MAIN_MENU, &MainMenuName);

         End-If;
      End-If;
   End-If;

   &Portal.Close();

   REM - Build Breadcrumb Links from Rowset;
   &BCLINKHTML = BuildBCHTML(&URLTYPE, &BCLINKCLASS, &TOP, &DELIMITER, &CACHEVALUE);

   If &BCLINKHTML <> "" Then
      &BREADCRUMBHTML = (GetHTMLText(HTML.EOPP_SCBREADCRUMB_CELL, &BCLINKHTML, &BCCELLCLASS));
   Else
      &BREADCRUMBHTML = "";
   End-If;

   Return &BREADCRUMBHTML;
End-Function;


REM *******************************************************************;
REM Function:  ReturnToSelectFAN                                       ;
REM Purpose:   This call returns the HTML area value for a link that   ;
REM            when clicked will display the FAN page for the given    ;
REM            folder name or collection name.                         ;
REM Inputs:    Link Styleclass (optional), delimiter (shows after link);
REM            Collection or folder name                               ;
REM Output:    HTML text for Hyperlink to a given FAN page             ;
REM Format:    &HTML = ReturnToSelectFAN("", "", &NAME)                ;
REM            <RECORD>.<HTMLFIELD>.Value = &HTML                      ;
REM *******************************************************************;
Function ReturnToSelectFAN(&CLASS As string, &DELIMITER As string, &NAME As string) Returns string;
   Local string &FANLINKHTML, &OBJLABEL, &LINKLABEL;
   Local ApiObject &OBJName;

   &Portal = PortalOpen();
   REM - Get the specified folder or collection;
   &OBJName = &Portal.FindFolderByName(&NAME);
   If &OBJName <> Null Then
      If &OBJName.Authorized Then
         &OBJLABEL = &OBJName.Label;
         &LINKLABEL = MsgGetText(18026, 1083, "Msg not found - Return to %1", &OBJLABEL);
         &FANLINKHTML = BuildBCLink("", "", &LINKLABEL, &NAME, "", "", "PSC", &CLASS, "N", "", "", "", &DELIMITER, "");
      End-If;
   End-If;
   &Portal.Close();

   Return &FANLINKHTML;
End-Function;

REM *******************************************************************;
REM Function:  GetFANURL                                               ;
REM Purpose:   This call returns the Absolute URL value to display the ;
REM            FAN page for the given folder name or collection name.  ;
REM Inputs:    Collection or folder name, URLType (PSP, PSC, or "").   ;
REM Output:    URL string to a given FAN page (or an empty string).    ;
REM Format:    &URL = GetFANURL("MY_FAN_COLLECTION", "")               ;
REM            If All(&URL) Then                                       ;
REM               %Response.RedirectURL(&URL)                          ;
REM            End-if                                                  ;
REM *******************************************************************;
Function GetFANURL(&NAME As string, &URLType As string) Returns string;
   Local string &FANURL;
   Local ApiObject &OBJName;
   Local string &RenderRecname;

   &Portal = PortalOpen();
   /* Get the specified folder or collection */
   &OBJName = &Portal.FindFolderByName(&NAME);
   If &OBJName <> Null Then
      If &OBJName.Authorized Then

         Evaluate Upper(&URLType)
         When = "PSC"
            &FANURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", "IScript_AppHP");
            Break;
         When = "PSP"
            &FANURL = GenerateScriptPortalURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", "IScript_AppHP");
            Break;
         When-Other
            &FANURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", "IScript_AppHP");
         End-Evaluate;
         &FANURL = &FANURL | "?scname=" | &NAME;
      End-If;
   End-If;
   &Portal.Close();

   Return &FANURL;
End-Function;

