Declare Function BuildBreadcrumbs PeopleCode WEBLIB_EOPP_SC.EOPP_SCBCISCRIPT FieldFormula;
Declare Function PortalOpen PeopleCode FUNCLIB_EOPP.EOPP_PORTALR FieldFormula;
Declare Function RenderAppNav PeopleCode WEBLIB_PTPP_SC.HOMEPAGE FieldFormula;

Local string &add_pt_cname;
Local string &pageCacheValue;
Local string &pageLabel;

Function AppendQueryParam(&url, &param) Returns string

   If Find("?", &url) > 0 Then
      &url = &url | "&" | &param;
   Else
      &url = &url | "?" | &param;
   End-If;

   Return &url;

End-Function;

Function TargetReturnQS(&sColl, &RenderCref) Returns string;
   Local string &pageCrefName;
   Local string &TargetQS;
   Local string &pageFName = %Request.GetParameter("fname");
   Local string &pageTargPortal;
   Local string &pageSecondary = %Request.GetParameter("secondary");
   Local string &pageVirtual = %Request.GetParameter("isvirtual");
   Local string &pagePTfname = %Request.GetParameter("pt_fname");

   If &RenderCref.TargetPortal <> %Portal Then
      &pageTargPortal = &RenderCref.TargetPortal;
   End-If;

   If &RenderCref.IsLink Then
      &pageCrefName = &RenderCref.LinksObjectName;
   Else
      &pageCrefName = &RenderCref.Name;
   End-If;

   &TargetQS = "PORTALPARAM_PTCNAV=" | &pageCrefName;
   &TargetQS = &TargetQS | "&EOPP.SCNode=" | %Node;
   &TargetQS = &TargetQS | "&EOPP.SCPortal=" | %Portal;
   &TargetQS = &TargetQS | "&EOPP.SCName=" | &sColl.Name;
   rem &TargetQS = &TargetQS | "&EOPP.SCLabel=" | EncodeURLForQueryString(&sColl.Label);
   &TargetQS = &TargetQS | "&EOPP.SCLabel=" | EncodeURLForQueryString(&pageLabel);

   If All(&pageFName) Then
      &TargetQS = &TargetQS | "&EOPP.SCFName=" | &pageFName;
   End-If;
   If All(&pageTargPortal) Then
      &TargetQS = &TargetQS | "&EOPP.SCTargPortal=" | &pageTargPortal;
   End-If;
   If All(&pageSecondary) Then
      &TargetQS = &TargetQS | "&EOPP.SCSecondary=" | &pageSecondary;
   End-If;
   If All(&pageVirtual) Then
      &TargetQS = &TargetQS | "&EOPP.SCVirtual=" | &pageVirtual;
   End-If;

   If All(&add_pt_cname) Then
      &TargetQS = &TargetQS | "&EOPP.SCPTcname=" | &add_pt_cname;
   Else
      If All(&pagePTfname) Then
         &TargetQS = &TargetQS | "&EOPP.SCPTfname=" | &pagePTfname;
      End-If;
   End-If;

   Return &TargetQS;
End-Function;

Function TargetFolderQS(&sColl, &targetFolder, &renderType, &targetPortal) Returns string
   Local string &folderQS;

   &folderQS = "scname=" | &sColl.Name;
   &folderQS = &folderQS | "&secondary=true";
   &folderQS = &folderQS | "&fname=" | &targetFolder.Name;

   If None(&add_pt_cname) Then
      &folderQS = &folderQS | "&pt_fname=" | &targetFolder.Name;
   Else
      &folderQS = &folderQS | "&PORTALPARAM_PTCNAV=" | &add_pt_cname;
   End-If;

   If All(&targetPortal) Then
      &folderQS = &folderQS | "&targetportal=" | &targetPortal;
   End-If;

   If All(&pageCacheValue) Then
      &folderQS = &folderQS | "&PortalCacheContent=true&PSCache-Control=" | EncodeURLForQueryString(&pageCacheValue);
   End-If;

   Return &folderQS;
End-Function;

/*
 * Renders a child folder hyperlink under a section in a shortcut collection
 */

Function RenderChildFolder(&subFolder, &sColl, &showIcns, &smFolderIcon, &renderType, &secondary, &portalHostNode) Returns string;
   Local string &linkHtml;
   Local string &url, &onClick, &href, &qs;
   Local string &subFolderImage = "";

   Local string &iScriptName = "IScript_AppHP";
   Local string &targetParent = "";

   If &renderType = "HTML" Then
      &iScriptName = "IScript_AppHtml";
   End-If;

   /*
    * If the portal host node is blank, or equals the current portal
    * node, a PSC call can be made, keeping the folder navigation within
    * the current TargetContent frame.
    * Otherwise, a PSP call must be made so that the portal will
    * propagate the %PortalHostNode system variable (it will be lost on a
    * PSC call.
    */

   If &renderType <> "HTML" And
         &renderType <> "PAGELET" And
         (LTrim(RTrim(&portalHostNode)) = "" Or
            &portalHostNode = %Node) Then
      &url = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", &iScriptName);
   Else
      &url = GenerateScriptPortalURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", &iScriptName);
      &targetParent = "target=""_parent""";
   End-If;

   If &subFolder.TargetPortal <> %Portal Then
      &qs = TargetFolderQS(&sColl, &subFolder, &renderType, &subFolder.TargetPortal);
   Else
      &qs = TargetFolderQS(&sColl, &subFolder, &renderType, "");
   End-If;

   &href = AppendQueryParam(&url, &qs);

   &linkHtml = GetHTMLText(HTML.EOPP_SC_GENERIC_ANCHOR, &href, "EOPP_SCCHILDFOLDERLINK", &subFolder.Description, &targetParent, "nowrap", &subFolder.Label);

   /*
    * [A]lways, [N]ever, or [D]efined images only (no defaults)
    */

   If &showIcns = "A" Then
      &subFolderImage = GetHTMLText(HTML.EOPP_SC_GENERIC_ANCHOR, &href, "EOPP_SCCHILDFOLDERLINK", &subFolder.Description, "", "", GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, %Response.GetImageURL(@"Image." | &smFolderIcon), "0"));
   End-If;

   Return GetHTMLText(HTML.EOPP_SC_CHILD_LINK_ROW, &subFolderImage, &linkHtml);

End-Function;

/*
##
## Renders a child shortcut under a section in a shortcut collection
##
*/

Function RenderChildShortcut(&subShortcut, &sColl, &showIcns, &smContentIcon, &smCollectionIcon, &renderType, &portalHostNode) Returns string;
   Local string &subShortcutImage = "";
   Local string &newWinUrl;
   Local string &linkHtml;

   Local string &pageTargetQS;

   &pageTargetQS = TargetReturnQS(&sColl, &subShortcut);

   If &subShortcut.IsNewWindow Then
      &newWinUrl = "eopp_sc_submit_" | &sColl.Name | "('eopp_sc_form_" | &sColl.Name | "','" | &subShortcut.AbsolutePortalURL | "', '" | &pageTargetQS | "', true, true); return(false);";
   Else
      &newWinUrl = "eopp_sc_submit_" | &sColl.Name | "('eopp_sc_form_" | &sColl.Name | "','" | &subShortcut.AbsolutePortalURL | "', '" | &pageTargetQS | "', true, false); return(false);";
   End-If;

   &linkHtml = GetHTMLText(HTML.EOPP_SC_ONCLICK_ANCHOR, &newWinUrl, "EOPP_SCCHILDCONTENTLINK", &subShortcut.Description, "target=""_parent""", "", &subShortcut.Label);

   /*
   ## [A]lways, [N]ever, or [D]efined images only (no defaults)
   */

   If &showIcns = "A" Then
      If &subShortcut.TargetIsCollection = True Then
         &subShortcutImage = GetHTMLText(HTML.EOPP_SC_ONCLICK_ANCHOR, &newWinUrl, "EOPP_SCCHILDCONTENTLINK", &subShortcut.Description, "target=""_parent""", "", GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, %Response.GetImageURL(@"Image." | &smCollectionIcon), "0"));
      Else
         &subShortcutImage = GetHTMLText(HTML.EOPP_SC_ONCLICK_ANCHOR, &newWinUrl, "EOPP_SCCHILDCONTENTLINK", &subShortcut.Description, "target=""_parent""", "", GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, %Response.GetImageURL(@"Image." | &smContentIcon), "0"));
      End-If;
   End-If;

   Return GetHTMLText(HTML.EOPP_SC_CHILD_LINK_ROW, &subShortcutImage, &linkHtml);

End-Function;

/*
##
## Renders the child hyperlinks (folders and shortcuts) of the specified
## parent folder.
##
*/

Function RenderSectionChildren(&folder, &sColl, &maxLinks, &showIcns, &smFolderIcon, &smContentIcon, &smCollectionIcon, &renderType, &secondary, &url, &portalHostNode, &overrideMoreLink) Returns string

   Local string &hyperlinks = "";
   Local number &numShown = 0;
   Local number &numLinksNotShown = 0;
   Local boolean &needMoreLink = False;
   Local boolean &looping = True;
   Local number &prevSequenceNumber = 0;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:Folders &subFolders = Null;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:Folder &subFolder = Null;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:Shortcuts &subShortcuts;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:Shortcut &subShortcut;

   &subFolders = &folder.Folders;

   If &subFolders <> Null Then
      &subFolder = &subFolders.First();
   End-If;

   &subShortcuts = &folder.Shortcuts;

   If &subShortcuts <> Null Then
      &subShortcut = &subShortcuts.First();
   End-If;

   While &looping = True

      /*
      ## If we're out of sub-objects to process, break out.
      */

      If &subFolder = Null And
            &subShortcut = Null Then
         &looping = False;
         Break;
      End-If;

      /*
      ## If we're NOT out of sub-objects to process, but we've hit our
      ## max viewable number, set 'More...' link indicator and 
      ## break out.
      ##
      ## Note: The 'More' link counts toward the max links limit, so
      ## if we ensure that that the sub-folders count plus the sub-shortcuts
      ## count is indeed over the limit, we must check for (maxLinks - 1) when
      ## determining when to draw the 'More' link.
      */

      If &overrideMoreLink = False Then

         If &subFolders.Count + &subShortcuts.Count > &maxLinks Then

            If &numShown >= (&maxLinks - 1) Then
               &looping = False;
               &needMoreLink = True;
               Break;
            End-If;

         End-If;

      End-If;

      /*
      ## Figure out which object is up for rendering next and handle appropriately
      */

      If &subFolder <> Null And
            &subShortcut <> Null Then

         If Value(&subFolder.SequenceNumber) <= Value(&subShortcut.SequenceNumber) Then
            &hyperlinks = &hyperlinks | RenderChildFolder(&subFolder, &sColl, &showIcns, &smFolderIcon, &renderType, &secondary, &portalHostNode);
            &subFolder = &subFolders.Next();
         Else
            &hyperlinks = &hyperlinks | RenderChildShortcut(&subShortcut, &sColl, &showIcns, &smContentIcon, &smCollectionIcon, &renderType, &portalHostNode);
            &subShortcut = &subShortcuts.Next();
         End-If;

      Else

         If &subFolder <> Null Then
            &hyperlinks = &hyperlinks | RenderChildFolder(&subFolder, &sColl, &showIcns, &smFolderIcon, &renderType, &secondary, &portalHostNode);
            &subFolder = &subFolders.Next();
         End-If;

         If &subShortcut <> Null Then
            &hyperlinks = &hyperlinks | RenderChildShortcut(&subShortcut, &sColl, &showIcns, &smContentIcon, &smCollectionIcon, &renderType, &portalHostNode);
            &subShortcut = &subShortcuts.Next();
         End-If;

      End-If;

      &numShown = &numShown + 1;

   End-While;

   /*
   ## Always use &Folder.Name for the folder name.  If the folder is not virtual,
   ## &Folder.Name will be the name of the collection folder.  If the folder is
   ## virtual, it will be the registry folder's name.
   */

   If &needMoreLink Then

      &numLinksNotShown = (&subFolders.Count + &subShortcuts.Count) - &numShown;

      If (LTrim(RTrim(&portalHostNode)) = "" Or
            &portalHostNode = %Node) Then

         &hyperlinks = &hyperlinks | GetHTMLText(HTML.EOPP_SC_MORE_LINK, &url, "EOPP_SCMORELINK", MsgGetExplainText(18026, 1080, "Message Not Found"), MsgGetText(18026, 1080, "Message Not Found", &numLinksNotShown), "");

      Else

         &hyperlinks = &hyperlinks | GetHTMLText(HTML.EOPP_SC_MORE_LINK, &url, "EOPP_SCMORELINK", MsgGetExplainText(18026, 1080, "Message Not Found"), MsgGetText(18026, 1080, "Message Not Found", &numLinksNotShown), "target=""_parent""");

      End-If;

   End-If;

   Return GetHTMLText(HTML.EOPP_SC_CHILD_LINK_BLOCK, &hyperlinks);

End-Function;

/*
##
## Renders a section header for a folder
##
*/

Function RenderSectionFolder(&folder, &sColl, &maxLinks, &showIcns, &lgFolderIcon, &smFolderIcon, &smContentIcon, &smCollectionIcon, &renderType, &secondary, &portalHostNode, &overrideMoreLink) Returns string
   Local string &hyperlinks;
   Local string &sectionTitle, &sectionDescr, &sectionImage, &sectionBind;
   Local string &folderDescription = "";

   Local string &linkHtml;
   Local string &url, &onClick, &href, &qs;
   Local string &imageLink = "";

   Local string &iScriptName = "IScript_AppHP";
   Local string &targetParent = "";

   If &renderType = "HTML" Then
      &iScriptName = "IScript_AppHtml";
   End-If;

   /*
    * If the portal host node is blank, or equals the current portal
    * node, a PSC call can be made, keeping the folder navigation within
    * the current TargetContent frame.
    * Otherwise, a PSP call must be made so that the portal will
    * propagate the %PortalHostNode system variable (it will be lost on a
    * PSC call.
    */

   If &renderType <> "HTML" And
         &renderType <> "PAGELET" And
         (LTrim(RTrim(&portalHostNode)) = "" Or
            &portalHostNode = %Node) Then
      &url = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", &iScriptName);
   Else
      &url = GenerateScriptPortalURL(%Portal, %Node, Record.WEBLIB_EOPP_SC, Field.HOMEPAGE, "FieldFormula", &iScriptName);
      &targetParent = "target=""_parent""";
   End-If;

   If &folder.TargetPortal <> %Portal Then
      &qs = TargetFolderQS(&sColl, &folder, &renderType, &folder.TargetPortal);
   Else
      &qs = TargetFolderQS(&sColl, &folder, &renderType, "");
   End-If;

   &href = AppendQueryParam(&url, &qs);

   &linkHtml = GetHTMLText(HTML.EOPP_SC_GENERIC_ANCHOR, &href, "EOPP_SCSECTIONFOLDERLINK", &folder.Description, &targetParent, "nowrap", &folder.Label);

   /*
    * [A]lways, [N]ever, or [D]efined images only (no defaults)
    */

   If &showIcns <> "N" Then

      If &folder.ImageURL <> "" Then
         &imageLink = GetHTMLText(HTML.EOPP_SC_GENERIC_ANCHOR, &href, "EOPP_SCSECTIONLEFT", &folder.Description, &targetParent, "", GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, &folder.ImageURL, "0"));

      Else

         If &showIcns <> "D" Then
            &imageLink = GetHTMLText(HTML.EOPP_SC_GENERIC_ANCHOR, &href, "EOPP_SCSECTIONLEFT", &folder.Description, "", "", GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, %Response.GetImageURL(@"Image." | &lgFolderIcon), "0"));

         End-If;

      End-If;

   End-If;

   &hyperlinks = RenderSectionChildren(&folder, &sColl, &maxLinks, &showIcns, &smFolderIcon, &smContentIcon, &smCollectionIcon, &renderType, &secondary, &href, &portalHostNode, &overrideMoreLink);

   /*
    * Now create Section HTML for this folder (hyperlinks build prior will be appended).
    */

   If LTrim(RTrim(&folder.Description)) <> "" Then
      &folderDescription = "<br>" | &folder.Description | "<br>";
   End-If;

   Return GetHTMLText(HTML.EOPP_SC_SECTION_FOLDER, &imageLink, &linkHtml, &folderDescription, &hyperlinks);

End-Function;

/*
## Renders a section header for a shortcut
*/

Function RenderSectionShortcut(&shortcut, &sColl, &maxLinks, &showIcns, &lgFolderIcon, &lgContentIcon, &lgCollectionIcon, &smFolderIcon, &smContentIcon, &smCollectionIcon, &renderType, &secondary, &portalHostNode) Returns string
   Local string &newWinUrl;
   Local string &linkHtml, &linkImage;
   Local string &shortcutDescription = "";

   Local string &pageTargetQS;

   &pageTargetQS = TargetReturnQS(&sColl, &shortcut);

   If &shortcut.IsNewWindow Then
      &newWinUrl = "eopp_sc_submit_" | &sColl.Name | "('eopp_sc_form_" | &sColl.Name | "','" | &shortcut.AbsolutePortalURL | "', '" | &pageTargetQS | "', true, true); return(false);";
   Else
      &newWinUrl = "eopp_sc_submit_" | &sColl.Name | "('eopp_sc_form_" | &sColl.Name | "','" | &shortcut.AbsolutePortalURL | "', '" | &pageTargetQS | "', true, false); return(false);";
   End-If;

   /*
   ## [A]lways, [N]ever, or [D]efined images only (no defaults)
   */

   If &showIcns <> "N" Then

      If &shortcut.ImageURL <> "" Then

         &linkImage = GetHTMLText(HTML.EOPP_SC_ONCLICK_ANCHOR, &newWinUrl, "EOPP_SCSECTIONLEFT", &shortcut.Description, "target=""_parent""", "", GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, &shortcut.ImageUrl, "0"));

      Else

         If &showIcns <> "D" Then

            If &shortcut.TargetIsCollection = True Then
               &linkImage = GetHTMLText(HTML.EOPP_SC_ONCLICK_ANCHOR, &newWinUrl, "EOPP_SCSECTIONLEFT", &shortcut.Description, "target=""_parent""", "", GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, %Response.GetImageURL(@"Image." | &lgCollectionIcon), "0"));
            Else
               &linkImage = GetHTMLText(HTML.EOPP_SC_ONCLICK_ANCHOR, &newWinUrl, "EOPP_SCSECTIONLEFT", &shortcut.Description, "target=""_parent""", "", GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, %Response.GetImageURL(@"Image." | &lgContentIcon), "0"));
            End-If;

         End-If;

      End-If;

   End-If;

   &linkHtml = GetHTMLText(HTML.EOPP_SC_ONCLICK_ANCHOR, &newWinUrl, "EOPP_SCSECTIONCONTENTLINK", &shortcut.Description, "target=""_parent""", "", &shortcut.Label);

   If LTrim(RTrim(&shortcut.Description)) <> "" Then
      &shortcutDescription = "<br>" | &shortcut.Description | "<br>";
   End-If;

   Return GetHTMLText(HTML.EOPP_SC_SECTION_SHORTCUT, &linkImage, &linkHtml, &shortcutDescription);

End-Function;

/*
##
## Main IScript section for rendering a shortcut collection.
##
*/

Function NavCollHTML(&numColumns, &renderType) Returns string
   Local boolean &mainLoop = True;
   Local string &scName;
   Local string &secondary;
   Local string &parentFolderName;
   Local string &ptFName;
   Local string &styleSheetName;
   Local string &styleSheetUrl;

   Local number &maxLinks = 5;
   Local number &maxCols = 3;
   Local string &showIcons = "Y";
   Local string &largeFolderIcon, &largeContentIcon, &largeCollectionIcon, &smallFolderIcon, &smallContentIcon, &smallCollectionIcon;
   Local string &showBCs = "Y";
   Local string &enableCache = "N";

   Local EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollection &sColl;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:Folder &folder, &parentFolder;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:Folders &folders;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:Shortcut &shortcut;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:Shortcuts &shortcuts;

   Local number &col = 1;
   Local string &portalName, &altTargetPortal;
   Local string &html = "";
   Local string &parentFolderImage;
   Local string &breadCrumbCell = "";
   Local string &headerTitle, &headerDescription;
   Local string &styleSheet = "EOPP_SCSTYLEDEF";
   Local string &defaultCollection = "EOPP_PORTAL_ROOT";
   Local string &width;
   Local string &npgtEnabled;

   Local Record &EOPP_OPTIONS;
   Local Record &EOPP_SITE_OPT;
   Local Record &EOPP_PUB_OPT;

   Local string &portalHostNode = %Request.GetParameter("PortalHostNode");

   Local boolean &overrideMoreLink = False;

   Local time &perfStartTime = %PerfTime;

   &scName = %Request.GetParameter("scname");

   /*
    * Make sure that system has Enterprise Portal or a Portal Pack installed (licensed)
    * by checking PS_EOPP_PUB_OPT table for a 'Y' value in the 'ENABLED' property of the
    * 'NPGT' pub type. Use PAPAGEINSTRUCTIONS Style class.
    */

   If &renderType = "PAGELET" And
         Not &scName = "EOPP_PORTAL_ROOT" Then

      &npgtEnabled = "N"; /* Default to NOT enabled */

      &EOPP_PUB_OPT = CreateRecord(Record.EOPP_PUB_OPT);
      &EOPP_PUB_OPT.EOPP_PUB_TYPE.Value = "NPGT";
      &EOPP_PUB_OPT.EOPP_ATTRNAME.Value = "ENABLED";
      If &EOPP_PUB_OPT.SelectByKey() = True Then
         &npgtEnabled = LTrim(&EOPP_PUB_OPT.EOPP_ATTRVAL.Value);
      End-If;

      If Not &npgtEnabled = "Y" Then
         Return "<font style=""PAPAGEINSTRUCTIONS"">" | MsgGetExplainText(18026, 1088, "Message Not Found (18026, 1088)") | "</font>";
      End-If;

   End-If;

   /*
   ## Get SITE options from EOPP_SITE_OPT record.
   */

   &EOPP_SITE_OPT = CreateRecord(Record.EOPP_SITE_OPT);
   &EOPP_SITE_OPT.PORTAL_NAME.Value = %Portal;
   If &EOPP_SITE_OPT.SelectByKey() = True Then

      &maxLinks = &EOPP_SITE_OPT.EOPP_SCMAXLINKS.Value;
      &maxCols = &EOPP_SITE_OPT.EOPP_SCMAXCOLS.Value;
      &showIcons = LTrim(&EOPP_SITE_OPT.EOPP_SCSHOWICN.Value);
      &showBCs = LTrim(&EOPP_SITE_OPT.EOPP_SCSHOWBC.Value);
      &largeFolderIcon = LTrim(&EOPP_SITE_OPT.EOPP_SCLGFLDICN.Value);
      &largeContentIcon = LTrim(&EOPP_SITE_OPT.EOPP_SCLGCNTICN.Value);
      &largeCollectionIcon = LTrim(&EOPP_SITE_OPT.EOPP_SCLGCOLLICN.Value);
      &smallFolderIcon = LTrim(&EOPP_SITE_OPT.EOPP_SCSMFLDICN.Value);
      &smallContentIcon = LTrim(&EOPP_SITE_OPT.EOPP_SCSMCNTICN.Value);
      &smallCollectionIcon = LTrim(&EOPP_SITE_OPT.EOPP_SCSMCOLLICN.Value);
      &styleSheet = LTrim(&EOPP_SITE_OPT.EOPP_STYLESHEET.Value);
      &defaultCollection = LTrim(&EOPP_SITE_OPT.EOPP_SCCOLLNAME.Value);

   Else

      /*
      ## If no SITE options have been defined, get user options from EOPP_OPTIONS record.
      */

      &EOPP_OPTIONS = CreateRecord(Record.EOPP_OPTIONS);
      If &EOPP_OPTIONS.SelectByKey() = True Then

         &maxLinks = &EOPP_OPTIONS.EOPP_SCMAXLINKS.Value;
         &maxCols = &EOPP_OPTIONS.EOPP_SCMAXCOLS.Value;
         &showIcons = LTrim(&EOPP_OPTIONS.EOPP_SCSHOWICN.Value);
         &showBCs = LTrim(&EOPP_OPTIONS.EOPP_SCSHOWBC.Value);
         &largeFolderIcon = LTrim(&EOPP_OPTIONS.EOPP_SCLGFLDICN.Value);
         &largeContentIcon = LTrim(&EOPP_OPTIONS.EOPP_SCLGCNTICN.Value);
         &largeCollectionIcon = LTrim(&EOPP_OPTIONS.EOPP_SCLGCOLLICN.Value);
         &smallFolderIcon = LTrim(&EOPP_OPTIONS.EOPP_SCSMFLDICN.Value);
         &smallContentIcon = LTrim(&EOPP_OPTIONS.EOPP_SCSMCNTICN.Value);
         &smallCollectionIcon = LTrim(&EOPP_OPTIONS.EOPP_SCSMCOLLICN.Value);
         &styleSheet = LTrim(&EOPP_OPTIONS.EOPP_STYLESHEET.Value);
         &defaultCollection = LTrim(&EOPP_OPTIONS.EOPP_SCCOLLNAME.Value);

      End-If;

   End-If;

   If &numColumns = 0 Then
      &numColumns = &maxCols;
   End-If;

   If &numColumns = 0 Then
      &numColumns = 3; /* Do not allow a zero value */
   End-If;

   &width = String(Round(100 / &numColumns, 0)) | "%";

   &secondary = %Request.GetParameter("secondary");
   &parentFolderName = %Request.GetParameter("fname");
   &ptFName = %Request.GetParameter("pt_fname");
   &altTargetPortal = %Request.GetParameter("targetportal");
   &add_pt_cname = "";

   Local ApiObject &currObj, &currPortal, &currObjAttColl, &currObjNavPage, &navPageObj;;

   If &renderType <> "PAGELET" Then

      If All(&ptFName) Then
         &add_pt_cname = "";
      Else
         &add_pt_cname = %Request.GetParameter("PORTALPARAM_PTCNAV");

         If None(&add_pt_cname) Then
            &currPortal = PortalOpen();

            &currObj = &currPortal.FindCRefByURL(%Request.GetParameter("PortalContentURL"));

            If &currObj <> Null Then
               &add_pt_cname = &currObj.Name;
            End-If;

            &currPortal.close();
         End-If;
      End-If;
   End-If;

   If &renderType = "PAGELET" Then

      /* 
      ## Find Pagelet Collection's counterpart NavPage
      */

      &add_pt_cname = "EOPP_SCFNAV_BASEPAGE_SCR"; /* Set default NavPage */
      &ptFName = "";

      &currPortal = PortalOpen();
      &currObj = &currPortal.FindFolderByName(&scName);

      If &currObj <> Null Then
         &currObjAttColl = &currObj.Attributes;
         &currObjNavPage = &currObjAttColl.ItemByName("EPPSC_HP_OBJNAME");
         If &currObjNavPage <> Null Then
            &navPageObj = &currPortal.FindCrefByName(&currObjNavPage.Value);
            If &navPageObj <> Null Then
               If &navPageObj.authorized And
                     &navPageObj.isVisible Then
                  If &navPageObj.validfrom <= %Date And
                        (&navPageObj.validto >= %Date Or
                           &navPageObj.validto = "") Then
                     &add_pt_cname = &navPageObj.Name;
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;

      &currPortal.close();
   End-If;

   /*
   ## Navigation Pages that use a psc call don't go through the portalservlet.
   ## Check the option, and URL Type.  For Enabled, and psc, append the 
   ## cache querystrings on the folder link URLs.
   */

   SQLExec(SQL.EOPP_SCGETCACHEOPTION, &enableCache);
   If &enableCache = "Y" And
         &renderType <> "HTML" And
         &renderType <> "PAGELET" And
         (LTrim(RTrim(&portalHostNode)) = "" Or
            &portalHostNode = %Node) Then
      SQLExec(SQL.EOPP_SCGETCACHEVALUE, &pageCacheValue);
   Else
      &pageCacheValue = "";
   End-If;

   /*
   ## If the scname parameter was not specified, use the value specified
   ## for the fname parameter. If no fname value was supplied, default to
   ## PORTAL_ROOT_OBJECT.
   */

   If &scName = "" Then
      If &parentFolderName = "" Then

         If &ptFName = "" Then
            &scName = &defaultCollection;
         Else
            &scName = &ptFName;
         End-If;

      Else
         &scName = &parentFolderName;
      End-If;
   End-If;

   try

      &sColl = create EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollection(%Portal, &scName);

      If &sColl <> Null And
            &sColl.IsValid Then

         /*
         ## Capture per-collection override values
         */

         If &sColl.ShowIcons <> "" Then
            &showIcons = &sColl.ShowIcons;
         End-If;

         If &sColl.MaxChildLinks <> "" Then
            &maxLinks = Value(&sColl.MaxChildLinks);
         End-If;

         If Lower(&secondary) <> "true" Then

            &folders = &sColl.Folders;
            &shortcuts = &sColl.Shortcuts;

         Else
            If All(&altTargetPortal) Then
               &parentFolder = create EOPP_SC_SHORTCUT_COLLECTIONS:Folder(&altTargetPortal, &parentFolderName);
            Else
               &parentFolder = create EOPP_SC_SHORTCUT_COLLECTIONS:Folder(%Portal, &parentFolderName);
            End-If;

            If &parentFolder <> Null Then
               &folders = &parentFolder.Folders;
               &shortcuts = &parentFolder.Shortcuts;
            Else
               &secondary = "false";

               &folders = &sColl.Folders;
               &shortcuts = &sColl.Shortcuts;
            End-If;

         End-If;

         /*
         ## If the combined number of actual folders an shortcuts is less than the
         ## requested number of columns, adjust the column count to make the most
         ## use of that row (for example, if a three column table was requested,
         ## but there are only two items to display, adjust to a two column table).
         */

         If (&folders.Count + &shortcuts.Count) < &numColumns Then
            &numColumns = &folders.Count + &shortcuts.Count;

            If &numColumns = 0 Then
               &numColumns = 1
            End-If;

            &width = String(Round(100 / &numColumns, 0)) | "%";
         End-If;

         If (&folders.Count + &shortcuts.Count) <= &numColumns Then
            &overrideMoreLink = True;
         Else
            &overrideMoreLink = False;
         End-If;

         /*
         ## Construct HTML for stylesheet inclusion
         */

         If &renderType = "PAGELET" Then

            &styleSheetName = &styleSheet;

         Else

            If &sColl.StyleSheet = "" Then
               &styleSheetName = &styleSheet;
            Else
               &styleSheetName = &sColl.StyleSheet;
            End-If;

         End-If;

         &styleSheetUrl = %Response.GetStyleSheetURL(&styleSheetName);

         /*
         ## Construct HTML for title area at top of page, as appropriate for
         ## primary or secondary pages. For primary pages, simply display a collection/folder
         ## label with a description underneath. For secondary pages, show the parent folder's 
         ## icon and label, followed by the current folder's label and description. Omit the
         ## parent folder's icon if icons have been suppressed.
         ##
         ## If we're rendering this for a homepage pagelet, suppress all title information.
         */

         If &renderType <> "PAGELET" Then

            If &showBCs = "Y" Then
               If (LTrim(RTrim(&portalHostNode)) = "" Or
                     &portalHostNode = %Node) Then
                  &breadCrumbCell = BuildBreadcrumbs(&scName, &sColl.Label, "PSC", &renderType, "N", &ptFName, &add_pt_cname, &pageCacheValue);
               Else
                  &breadCrumbCell = BuildBreadcrumbs(&scName, &sColl.Label, "PSP", &renderType, "Y", &ptFName, &add_pt_cname, &pageCacheValue);
               End-If;
            End-If;

            If &breadCrumbCell = "" Then
               &breadCrumbCell = "<td class=""EOPP_SCBREADCRUMBSECTION"" width=""100%"">" | &sColl.Label | "</td>";
            End-If;

            If &showIcons <> "N" Then
               If Lower(&secondary) = "true" Then
                  If &parentFolder <> Null And
                        &parentFolder.ImageURL <> "" Then
                     &parentFolderImage = GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, &parentFolder.ImageURL, "0");
                  Else
                     If &showIcons <> "D" Then
                        &parentFolderImage = GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, %Response.GetImageURL(@"Image." | &largeFolderIcon), "0");
                     End-If;
                  End-If;
               Else
                  If &sColl.ImageURL <> "" Then
                     &parentFolderImage = GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, &sColl.ImageURL, "0");
                  Else
                     If &showIcons <> "D" Then
                        &parentFolderImage = GetHTMLText(HTML.EOPP_SC_GENERIC_IMAGE, %Response.GetImageURL(@"Image." | &largeFolderIcon), "0");
                     End-If;
                  End-If;
               End-If;
            End-If;

            If Lower(&secondary) = "true" Then

               &headerTitle = &parentFolder.Label;
               &headerDescription = &parentFolder.Description;

            Else

               &headerTitle = &sColl.Label;
               &headerDescription = &sColl.Description;

            End-If;

            &pageLabel = &headerTitle;

         End-If;

         &folder = &folders.First();
         &shortcut = &shortcuts.First();

         While &mainLoop = True
            /*
            ## If we're out of objects to process, break out.
            */

            If &folder = Null And
                  &shortcut = Null Then
               &mainLoop = False;
               Break;
            End-If;

            If &col = 1 Then
               &html = &html | "<tr>";
               &col = &col + 1;
            Else
               If &col > &numColumns Then
                  &html = &html | "</tr><tr>";
                  &col = 2;
               Else
                  &col = &col + 1;
               End-If;
            End-If;

            /* 
            ## Figure out which object is up for rendering next and handle appropriately
            */

            If &folder <> Null And
                  &shortcut <> Null Then

               If Value(&folder.SequenceNumber) <= Value(&shortcut.SequenceNumber) Then
                  &html = &html | "<td valign=""top"" width=""" | &width | """ height=""100%"">" | RenderSectionFolder(&folder, &sColl, &maxLinks, &showIcons, &largeFolderIcon, &smallFolderIcon, &smallContentIcon, &smallCollectionIcon, &renderType, &secondary, &portalHostNode, &overrideMoreLink) | "</td>";
                  &folder = &folders.Next();
               Else
                  &html = &html | "<td valign=""top"" width=""" | &width | """ height=""100%"">" | RenderSectionShortcut(&shortcut, &sColl, &maxLinks, &showIcons, &largeFolderIcon, &largeContentIcon, &largeCollectionIcon, &smallFolderIcon, &smallContentIcon, &smallCollectionIcon, &renderType, &secondary, &portalHostNode) | "</td>";
                  &shortcut = &shortcuts.Next();
               End-If;

            Else

               If &folder <> Null Then
                  &html = &html | "<td valign=""top"" width=""" | &width | """ height=""100%"">" | RenderSectionFolder(&folder, &sColl, &maxLinks, &showIcons, &largeFolderIcon, &smallFolderIcon, &smallContentIcon, &smallCollectionIcon, &renderType, &secondary, &portalHostNode, &overrideMoreLink) | "</td>";
                  &folder = &folders.Next();
               End-If;

               If &shortcut <> Null Then
                  &html = &html | "<td valign=""top"" width=""" | &width | """ height=""100%"">" | RenderSectionShortcut(&shortcut, &sColl, &maxLinks, &showIcons, &largeFolderIcon, &largeContentIcon, &largeCollectionIcon, &smallFolderIcon, &smallContentIcon, &smallCollectionIcon, &renderType, &secondary, &portalHostNode) | "</td>";
                  &shortcut = &shortcuts.Next();
               End-If;

            End-If;

         End-While;

         While &col <= &numColumns
            &html = &html | "<td class=""EOPP_SCSECTIONCONTENT"" width=""" | &width | """>&nbsp;</td>";
            &col = &col + 1;
         End-While;

         &html = &html | "</tr>";

      Else

         /* 
         ## Shortcut Collection can not be found 
         */

         &styleSheetUrl = %Response.GetStyleSheetURL(&styleSheet);
         &headerTitle = MsgGetText(18026, 1051, "Message Not Found");
         &headerDescription = MsgGetExplainText(18026, 1051, "Message Not Found");

      End-If;

   catch Exception &ex
      &html = "<tr><td>" | &ex.ToString() | "</td></tr>";
   end-try;

   If &renderType = "PAGELET" Then

      &html = GetHTMLText(HTML.EOPP_SC_APPNAV_PAGELET, &styleSheetUrl, &parentFolderImage, &breadCrumbCell, &headerTitle, &headerDescription, &html, "", GetHTMLText(HTML.EOPP_SC_JSCRIPT1, &sColl.Name), GetHTMLText(HTML.EOPP_SC_JSCRIPT2, &sColl.Name), GetHTMLText(HTML.EOPP_SC_JSCRIPT3));

   Else

      If &parentFolder <> Null Then
         &html = GetHTMLText(HTML.EOPP_SC_APPNAV_PAGE, &styleSheetUrl, &parentFolderImage, &breadCrumbCell, &headerTitle, &headerDescription, &html, &sColl.generateEditLink(&parentFolderName, True), GetHTMLText(HTML.EOPP_SC_JSCRIPT1, &sColl.Name), GetHTMLText(HTML.EOPP_SC_JSCRIPT2, &sColl.Name), GetHTMLText(HTML.EOPP_SC_JSCRIPT3));
      Else
         &html = GetHTMLText(HTML.EOPP_SC_APPNAV_PAGE, &styleSheetUrl, &parentFolderImage, &breadCrumbCell, &headerTitle, &headerDescription, &html, &sColl.generateEditLink(&sColl.Name, True), GetHTMLText(HTML.EOPP_SC_JSCRIPT1, &sColl.Name), GetHTMLText(HTML.EOPP_SC_JSCRIPT2, &sColl.Name), GetHTMLText(HTML.EOPP_SC_JSCRIPT3));
      End-If;

   End-If;

   Return &html;
End-Function;

