import EOPP_SC_SHORTCUT_COLLECTIONS:*;

/********************************************************************/
/* FOLDING TREE PAGELET: Used by IScript_SCPagelet                  */
/********************************************************************/
Function FoldingTreePagelet(&SCollname As string, &TargetWindow As string, &Type As string) Returns string;
   Local string &targetURL, &target, &xml, &xsl, &html;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollections &sColls = create EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollections();
   Local EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollection &sColl = &sColls.ItemByName(&SCollname);

   If &Type = "cxm" Then
      &targetURL = "AbsoluteContentURL";
      &target = "TargetContent";
   Else
      &targetURL = "AbsolutePortalURL";
      &target = "_self";
   End-If;
   &xml = &sColl.GenFormattedXMLString( - 1);
   &xsl = GetHTMLText(HTML.EOPP_SCNAV_XSL, &targetURL, &target);
   &html = TransformEx(&xml, &xsl);

   /* Begin: Extract contents out of a CDATA */
   Local XmlDoc &XMLDoc = CreateXmlDoc(&html);
   Local XmlNode &RootNode = &XMLDoc.DocumentElement;
   Local string &CDataVal = &RootNode.GetCDataValue();
   If All(&CDataVal) Then
      &html = &CDataVal;
   End-If;
   &html = Substitute(&html, "&apos;", "'");
   /* End: Extract contents out of a CDATA */

   Return &html;
End-Function;

/********************************************************************/
/* FOLDING TREE PAGELET: Used by IScript_SCPagelet                  */
/********************************************************************/
Function ExpandedTreePagelet(&SCollname As string, &TargetWindow As string, &Type As string) Returns string;
   Local string &targetURL, &target, &xml, &xsl, &html;
