   Local EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollection &sColl = &sColls.ItemByName(&SCollname);

   If &Type = "cxm" Then
      &targetURL = "AbsoluteContentURL";
      &target = "TargetContent";
   Else
      &targetURL = "AbsolutePortalURL";
