   End-If;
   &xml = &sColl.GenFormattedXMLString( - 1);
   &xsl = GetHTMLText(HTML.EOPP_SCPGLT_EXPANDEDTREE_XSL, &targetURL, &target);
   &html = TransformEx(&xml, &xsl);

   /* Begin: Extract contents out of a CDATA */
   Local XmlDoc &XMLDoc = CreateXmlDoc(&html);
   Local XmlNode &RootNode = &XMLDoc.DocumentElement;
   Local string &CDataVal = &RootNode.GetCDataValue();
   If All(&CDataVal) Then
      &html = &CDataVal;
   End-If;
   &html = Substitute(&html, "&apos;", "'");
   /* End: Extract contents out of a CDATA */

