End-Function;


/********************************************************************/
/* FOLDER SHORTCUT VIEW PAGELET: Used by IScript_SCPagelet          */
/********************************************************************/
Function FolderShortcutView(&SCollName As string) Returns string
   Local string &xml, &xsl, &html;
   Local EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollection &scColl = create EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollection(%Portal, &SCollName);

   &xml = &scColl.GenXMLStringWellFormed(2);
   &xsl = GetHTMLText(HTML.EOPP_SCPGLT_FOLDERTREE_XSL);
   &html = TransformEx(&xml, &xsl);

   /* Begin: Extract contents out of a CDATA */
   Local XmlDoc &XMLDoc = CreateXmlDoc(&html);
   Local XmlNode &RootNode = &XMLDoc.DocumentElement;
   Local string &CDataVal = &RootNode.GetCDataValue();
   If All(&CDataVal) Then
      &html = &CDataVal;
   End-If;
   &html = Substitute(&html, "&apos;", "'");
   /* End: Extract contents out of a CDATA */

   Return &html;
End-Function;

/********************************************************************/
/* SHORTCUT COLLECTION XML: Outputs an XML version of a shortcut    */
/*                          collection... can be used for third     */
/*                          party integration                       */
/* INPUT REQUIRED: Query parameter called "key" specifying the name */
/*                 of the shortcut collection needed                */
/********************************************************************/
Function IScript_SCcollXML
   Local string &sCollName;
   Local string &strDepth;
   Local number &depth;

   &sCollName = %Request.GetParameter("key");
   &strDepth = %Request.GetParameter("depth");

   If &strDepth = "" Then
      &depth = - 1
   Else
      &depth = Value(&strDepth);
   End-If;

   If None(&sCollName) Then
      &respText = "Please provide the name of a shortcut collection.  Use the querystring parameter, ""key"".";
   Else
      &sColls = create EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollections();

      &sColl = &sColls.ItemByName(&sCollName);
      &respText = &sColl.GenFormattedXMLString(&depth);
   End-If;

   %Response.Write(&respText);
End-Function;

/********************************************************************/
/* SHORTCUT COLLECTIONS XML: Outputs an XML version of all shortcut */
/*                           collections... can be used for third   */
/*                           party integration                      */
/********************************************************************/
Function IScript_AllSCcollXML
   Local string &strDepth;
   Local number &depth;

   &strDepth = %Request.GetParameter("depth");

   If &strDepth = "" Then
      &depth = - 1
   Else
      &depth = Value(&strDepth);
   End-If;

   &sColls = create EOPP_SC_SHORTCUT_COLLECTIONS:ShortcutCollections();
   &respText = &sColls.GenFormattedXMLString(&depth);

   %Response.Write(&respText);
End-Function;

/********************************************************************/
/* SHORTCUT COLLECTIONS PAGELET: These are the two standard pagelets*/
/*                               created by the shortcut collection */
/*                               publish page                       */
/********************************************************************/
Function IScript_SCPagelet
   Local string &html;
   Local Request &request = %Request;
   Local string &type = &request.GetParameter("type");
   Local string &appearance = &request.GetParameter("appearance");
   Local string &SCollName = %Request.GetParameter("key");
   Local string &targetWindow = %Request.GetParameter("TargetWindow");

   If &appearance = "1" Then /* Folding Tree */
      If (%Request.BrowserType = "IE") Then
         &html = FoldingTreePagelet(&SCollName, &targetWindow, &type);
      Else
         &html = ExpandedTreePagelet(&SCollName, &targetWindow, &type);
      End-If;
   Else /* Two-Level Folder/Shortcut View */
      &html = FolderShortcutView(&SCollName);
   End-If;
   %Response.Write(&html);
End-Function;

Global Record &EP_GBLKEYS_WRK;
Global boolean &bPivotRelAction;
Declare Function WorkCenter_Transfer PeopleCode FUNCLIB_EP.EP_WC_TRANSFER FieldFormula;


Function IScript_execute

   Local string &queryString_Rel, &queryString_DocID;
   Local Record &apprRecord, &revwRecord;


   &queryString_Rel = %Request.GetParameter("RELACTION");
   If &queryString_Rel = "OPEN_DOCUMENT" Then
      &bPivotRelAction = True;
      &EP_GBLKEYS_WRK = CreateRecord(Record.EP_GBLKEYS_WRK);
      &queryString_DocID = %Request.GetParameter("EP_APPRAISAL_ID");
      &EP_GBLKEYS_WRK.EP_APPRAISAL_ID.Value = &queryString_DocID;

      REM Get the required fields;
      &apprRecord = CreateRecord(Record.EP_APPR);
      &apprRecord.EP_APPRAISAL_ID.Value = &EP_GBLKEYS_WRK.EP_APPRAISAL_ID.Value;
      &apprRecord.SelectByKey();

      &revwRecord = CreateRecord(Record.EP_REVW_TYP_TBL);
      &revwRecord.EP_REVIEW_TYPE.Value = &apprRecord.EP_REVIEW_TYPE.Value;
      &revwRecord.SelectByKeyEffDt(%Date);

      &EP_GBLKEYS_WRK.EMPLID.Value = &apprRecord.EMPLID.Value;
      &EP_GBLKEYS_WRK.EP_DOC_USAGE_IND.Value = &revwRecord.EP_DOC_USAGE_IND.Value;
      &EP_GBLKEYS_WRK.EP_ROLE.Value = "M";
      &EP_GBLKEYS_WRK.EP_REVIEWER_ID.Value = %EmployeeId;
      &EP_GBLKEYS_WRK.EP_SECTION_TYPE.SetDefault();

      /* Display all CO & CA doc and if you are not MGR on doc in view-only mode */
      If (&apprRecord.EP_REVIEW_STATUS.Value = "CA" Or
            &apprRecord.EP_REVIEW_STATUS.Value = "CO") Or
            (&apprRecord.EP_MANAGER_ID.Value <> %EmployeeId) Then
         &EP_GBLKEYS_WRK.EP_DOC_SELECT_IND.Value = "V";
         &EP_GBLKEYS_WRK.EP_USER_ROLE.Value = "V";
      Else
         &EP_GBLKEYS_WRK.EP_DOC_SELECT_IND.Value = "C";
         &EP_GBLKEYS_WRK.EP_USER_ROLE.Value = "M";
      End-If;
      WorkCenter_Transfer();
   End-If;

End-Function;

