import EQRY_CLASSES:*;

Component EQRY_CLASSES:eQueryManager &coQueryManager;
Component string &csResultsHTML;

Global EQRY_CLASSES:eQueryCommunicator &goQueryCommunicator;

Function IScript_CriteriaActionTaken()
   Local string &Val;
   Local number &i;

   Local Rowset &joCriteriaRS;
   Local EQRY_CLASSES:eQueryDisplay &joEQryDisplay;

   &joEQryDisplay = &coQueryManager.CriteriaDisplay;
   &joCriteriaRS = &joEQryDisplay.getNewRowset();

   &Val = %Request.GetParameter("EQRY_ACTIONROW");
   &joEQryDisplay.ActionRow = Value(&Val);

   /*
   &Val = %Request.GetParameter("EQRY_ACTIONVALUE");
   &joEQryDisplay.ActionValue = &Val;
   */

   /* Get action value from query manager, so external commands, like Search, can be handled*/
   &joEQryDisplay.ActionValue = &coQueryManager.ActionValue;

   &coQueryManager.effectiveDate = %Request.GetParameter("EQRY_SEARCHDATE");

   &Val = %Request.GetParameter("EQRY_ROWCOUNT");
   &joEQryDisplay.RowCount = Value(&Val);

   &Val = %Request.GetParameter("EQRY_QUERYNAME");
   &joEQryDisplay.QueryName = &Val;

   For &i = 1 To &joEQryDisplay.RowCount

      If &i <> 1 Then
         &joCriteriaRS.InsertRow(&i - 1);
      End-If;

      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_NAME).Value = &joEQryDisplay.QueryName;
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_CRIT_ID).Value = &i;
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_SEQNUM).Value = &i;
      /*
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_OBJ_TYPE).Value = %Request.GetParameter("EQRY_TARGET_OBJ" | &i);
      */
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_LOGICAL).Value = %Request.GetParameter("EQRY_LOGICAL" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_OPERATOR).Value = %Request.GetParameter("EQRY_OPERATOR" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_VALUE).Value = %Request.GetParameter("EQRY_VALUE" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_INDENTLEVEL).Value = %Request.GetParameter("EQRY_INDENTLEVEL" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_GROUPSTARTER).Value = %Request.GetParameter("EQRY_GROUPSTARTER" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_ENDPARENS).Value = %Request.GetParameter("EQRY_ENDPARENS" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.HCMD_CLASSID).Value = %Request.GetParameter("HCMD_CLASSID" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.HCMD_ATTRIBID).Value = %Request.GetParameter("HCMD_ATTRIBID" | &i);
      &joCriteriaRS.GetRow(&i).GetRecord(1).GetField(Field.EQRY_ROW_LOCKED).Value = %Request.GetParameter("EQRY_ROW_LOCKED" | &i);
   End-For;

   &joEQryDisplay.SetCriteriaRowset(&joCriteriaRS);

End-Function;

Function IScript_OutputActionTaken()
   Local string &Val;
   Local number &i;

   Local Rowset &joOutputRS;
   Local EQRY_CLASSES:eQueryOutputDisplay &joEQryOutputDisplay;

   &joEQryOutputDisplay = &coQueryManager.OutputDisplay;
