   try

      If &coQueryManager.ActionValue = "SORT" Then
         &csResultsHTML = &coQueryManager.getCurrentResultsObject_UI().sortColumn(%Request);
      Else
         /*Rebuild after page selction (First, Last, ViewAll, etc.)*/
         &csResultsHTML = &coQueryManager.getCurrentResultsObject_UI().rebuildHTML(%Request);

      End-If;

   catch Exception &e;
      &csResultsHTML = &e.ToString();
   end-try;

End-Function;

Function IScript_ResultActionTaken()

   If &coQueryManager.ActionValue = "ASSIGN" Then

      Local EQRY_CLASSES:eQueryAssign &joAssign;

      &joAssign = create EQRY_CLASSES:eQueryAssign(&goQueryCommunicator, %Request, &coQueryManager);

      EndModalComponent(1);

   Else

      Local EQRY_CLASSES:eQueryNav &joNav;

      &joNav = create EQRY_CLASSES:eQueryNav(&coQueryManager);

      &joNav.openEditComponent(%Request);

   End-If;

End-Function;

