   End-If;

   Local EQRY_CLASSES:eQueryResults_UI &joResults;

   &joResults = create EQRY_CLASSES:eQueryResults_UI( Null, Null);

   /*%Response.Write("<title>" | &QryName | "</title></head>");*/

   %Response.Write(&joResults.ToExcel(%Request));
   %Response.Write("</html>");

End-Function;

Function IScript_FileAttach()
   &Response = %Response;
   &Request = %Request;
   &idx = EscapeHTML(&Request.GetParameter("idx"));
   &formname = EscapeHTML(&Request.GetParameter("fname"));

   Local string &MYHTML = GetHTMLText(HTML.PT_FILEATT_IFRAME);
   Local string &HEAD = "";

   &HEAD = "<html><head>";

   If %Request.AuthTokenDomain <> "" Then
      &HEAD = &HEAD | "<script language=javascript>document.domain = '" | Right(%Request.AuthTokenDomain, Len(%Request.AuthTokenDomain) - 1) | "';</script>";
   End-If;

   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   If All(&strStyleSheetName) Then
      &HEAD = &HEAD | "<link rel=stylesheet type='text/css' href='" | %Response.GetStyleSheetURL(@("StyleSheet." | &strStyleSheetName)) | "' />";
   End-If;
   &HEAD = &HEAD | "</head>";

   &MYHTML = &HEAD | &MYHTML;
   &MYHTML = Substitute(&MYHTML, "%1", &idx);
   &MYHTML = Substitute(&MYHTML, "%2", &formname);
   &MYHTML = &MYHTML | "</html>";

   &Response.Write(&MYHTML);
End-Function;

import PTFILE_HTTP:Utils;

Function IScript_GetAttachment()
   Local any &data;
   Local string &attachfile_name, &attachrec_name, &url_id, &url_id_content, &content_type, &file_extn;
   Local Rowset &attachrs;
   Local number &row_count, &ret_code, &contentlength;
   Local PTFILE_HTTP:Utils &filehttputilsobject;


   &filehttputilsobject = create PTFILE_HTTP:Utils();
   &ret_code = 0;

   /*Authorize the user*/
   If (IsUserInRole("Search Server")) Then
      /*Read and validate the request*/
      &url_id = %Request.GetParameter("urlid");
      &attachfile_name = Unencode(%Request.GetParameter("filename"));
      If (&url_id <> "") Then
         &url_id_content = GetURL(@("URL." | &url_id));
         If (Lower(Substring(&url_id_content, 1, 9)) = "record://") Then
            &attachrec_name = Substring(&url_id_content, 10, (Len(&url_id_content) - 8));
            &ret_code = &filehttputilsobject.ValidateRequest(&attachrec_name, &attachfile_name);
         Else
            &ret_code = 4;
         End-If;
      Else
         &ret_code = 5;
      End-If;


      Evaluate &ret_code
      When 0
         /*Determine attachment recordname and filename*/
         &attachrs = CreateRowset(@("Record." | Upper(&attachrec_name)));
         &attachrs.Fill("WHERE ATTACHSYSFILENAME = :1 ORDER BY FILE_SEQ", &attachfile_name);

         /*Determine File extenstion and content-type*/
         &file_extn = &filehttputilsobject.GetFileExtension(&attachfile_name);
         &content_type = &filehttputilsobject.GetContentType(&file_extn);

         /*Read the file BLOB from database record and write to response*/
         For &row_count = 1 To &attachrs.ActiveRowCount
            try
               %Response.WriteBinary(&attachrs(&row_count).GetRecord(@("Record." | Upper(&attachrec_name))).FILE_DATA.Value);
            catch Exception &ex
               %Response.SetContentType("text/plain");
               %Response.Write(MsgGetText(137, 182, "Exception in writing binary file data from database" | " " | &ex.ToString()));
            end-try;
         End-For;

         /*Set the response headers*/
         If (&content_type = "") Then
            &content_type = "application/octet-stream";
         End-If;

         %Response.SetHeader("Content-Disposition", "attachment;filename=" | EncodeURL(&attachfile_name));
         %Response.SetContentType(&content_type);

         /* For SES crawlling requests spawn accross IB and PIA file attachment iscript
		   The IScript uses session and if the session is valid skips validating PS+TOKEN
		   Where as IB requests do not have a session and always validate PS_TOKEN 
		   In both the cases SES send basic auth information on every requests , so requests should never fail
		   This code deletes the PS_TOKEN so that basic auth takes over when needed 
           For now doing this only when the user agent is SES , but if other product areas see similar issue 
			we might have to come up with a generic soution
		*/
         Local string &pstoken = %Request.GetCookieValue("PS_TOKEN");
         Local string &userAgent = %Request.GetHeader("User-Agent");
         If All(&pstoken) And
               &userAgent = "Oracle Secure Enterprise Search" Then
            &Cookie = %Response.CreateCookie("PS_TOKEN");
            &Cookie.Value = "delete";
            &Cookie.MaxAge = 0;
            &Cookie.path = "/";
            &authTokenDomain = (%Request.AuthTokenDomain);

            If (All(&authTokenDomain) And
                  &authTokenDomain <> "") Then
               &Cookie.Domain = %Request.AuthTokenDomain;
            End-If;
         End-If;

         Break;


         /*Handle errors in request*/
      When 1
         %Response.SetContentType("text/plain");
         %Response.Write(MsgGetText(137, 183, "Record referenced by URL Identifier %1 in request is empty.", &url_id));
         Break;

      When 2
         %Response.SetContentType("text/plain");
         %Response.Write(MsgGetText(137, 184, "File name field in URL request is empty."));
         Break;

      When 3
         %Response.SetContentType("text/plain");
         %Response.Write(MsgGetText(137, 186, "Requested file attachment %1 is not available in database record %2", EncodeURL(&attachfile_name), Upper(&attachrec_name)));
         Break;

      When 4
         %Response.SetContentType("text/plain");
         %Response.Write(MsgGetText(137, 187, "URL Identifier %1 in request is not of record type", &url_id));
         Break;

      When 5
         %Response.SetContentType("text/plain");
         %Response.Write(MsgGetText(137, 181, "URL Identifier is missing in request."));
         Break
      End-Evaluate;

   Else
      %Response.SetContentType("text/plain");
      %Response.Write(MsgGetText(137, 185, "User %1 is not authorized for viewing attachments from database via HTTP", %UserId));
   End-If;


End-Function;


Function IScript_ViewAttachment()

   Local any &data;
   Local string &attachId, &attachfile_name, &attachrec_name, &url_id, &url_id_content, &content_type, &file_extn;
   Local Rowset &attachrs;
   Local number &row_count, &ret_code, &contentlength;
   Local PTFILE_HTTP:Utils &filehttputilsobject;
   Local string &msgdata;

   &filehttputilsobject = create PTFILE_HTTP:Utils();
   &ret_code = 0;

   /*Authorize the user*/

   /*Read and validate the request*/
   &attachId = %Request.GetParameter("attachid");

   If (&attachId <> "") Then
      &ret_code = &filehttputilsobject.ValidateAttachment(&attachId);
   Else
      &ret_code = 1;
   End-If;


   Evaluate &ret_code
   When 0
      /*Determine attachment recordname and filename*/
      &attachrs = CreateRowset(@("Record.PSPTFILE_PRCS"));
      &attachrs.Fill("WHERE GUID = :1 ORDER BY FILE_SEQ", &attachId);

      /*Determine File extenstion and content-type*/
      If (&attachrs.ActiveRowCount > 0) Then
         &attachfile_name = &attachrs(1).GetRecord(@("Record.PSPTFILE_PRCS")).ATTACHSYSFILENAME.Value;
         &file_extn = &filehttputilsobject.GetFileExtension(&attachfile_name);
         &content_type = &filehttputilsobject.GetContentType(&file_extn);
      End-If;

      /*Read the file BLOB from database record and write to response*/
      For &row_count = 1 To &attachrs.ActiveRowCount

         try
            %Response.WriteBinary(&attachrs(&row_count).GetRecord(@("Record.PSPTFILE_PRCS")).FILE_DATA.Value);
         catch Exception &ex
            %Response.SetContentType("text/plain");
            %Response.Write(MsgGetText(137, 182, "Exception in writing binary file data from database" | " " | &ex.ToString()));
         end-try;
      End-For;

      /*Set the response headers*/
      If (&content_type = "") Then
         &content_type = "application/octet-stream";
      End-If;

      %Response.SetHeader("Content-Disposition", "attachment;filename=" | EncodeURL(&attachfile_name));
      %Response.SetContentType(&content_type);

      Break;


      /*Handle errors in request*/
   When 1
      %Response.SetContentType("text/plain");
      %Response.Write(MsgGetText(137, 194, "Invalid request.", &msgdata));
      Break;

   When 2
      %Response.SetContentType("text/plain");
      %Response.Write(MsgGetText(137, 195, "Attachment is either not available or expired."));
      Break;
   When 3
      %Response.SetContentType("text/plain");
      %Response.Write(MsgGetText(137, 196, "Authentication failure."));
      Break;
   End-Evaluate;

End-Function;



Function IScript_ViewFile()

   Local any &data;
   Local string &attachId, &attachfile_name, &attachrec_name, &url_id, &url_id_content, &content_type, &file_extn;
   Local Rowset &attachrs;
   Local number &row_count, &ret_code, &contentlength;
   Local PTFILE_HTTP:Utils &filehttputilsobject;
   Local string &msgdata;

   &filehttputilsobject = create PTFILE_HTTP:Utils();
   &ret_code = 0;

   /*Authorize the user*/

   /*Read and validate the request*/
   &attachId = %Request.GetParameter("attachid");

   If (&attachId <> "") Then
      &ret_code = &filehttputilsobject.ValidateAttachment(&attachId);
   Else
      &ret_code = 1;
   End-If;


   Evaluate &ret_code
   When 0
      /*Determine attachment recordname and filename*/
      &attachrs = CreateRowset(@("RECORD.PTNC_TEXTATTACH"));
      &rowcount = &attachrs.Fill("WHERE GUID = :1", &attachId);

      /*Determine File extenstion and content-type*/
      If (&rowcount = 1) Then
         &attachfile_name = &attachrs(1).GetRecord(@("Record.PTNC_TEXTATTACH")).ATTACHMENTNAME.Value;
         &urlid = &attachrs(1).GetRecord(@("Record.PTNC_TEXTATTACH")).URL_ID.Value;
         &file_extn = &filehttputilsobject.GetFileExtension(&attachfile_name);
         &content_type = &filehttputilsobject.GetContentType(&file_extn);
      Else

      End-If;

      Local string &PS_SERVDIR = GetEnv("PS_SERVDIR");
      If Find("/", &PS_SERVDIR) = 0 Then
         &tempdir = GetEnv("PS_SERVDIR") | "\files\";
      Else
         &tempdir = GetEnv("PS_SERVDIR") | "/files/";
      End-If;

      &urlid = "URL." | &urlid;
      &RESULT = GetAttachment(@(&urlid), &attachfile_name, &tempdir | &attachfile_name);

      &RESULT = PutAttachment("record://PSFILE_ATTDET", &attachfile_name, &tempdir | &attachfile_name);

      &attachrs = CreateRowset(@("Record.PSFILE_ATTDET"));
      &attachrs.Fill("WHERE ATTACHSYSFILENAME = :1 ORDER BY FILE_SEQ", &attachfile_name);

      /*Determine File extenstion and content-type*/
      If (&attachrs.ActiveRowCount > 0) Then
         &attachfile_name = &attachrs(1).GetRecord(@("Record.PSFILE_ATTDET")).ATTACHSYSFILENAME.Value;
         &file_extn = &filehttputilsobject.GetFileExtension(&attachfile_name);
         &content_type = &filehttputilsobject.GetContentType(&file_extn);
      End-If;

      /*Read the file BLOB from database record and write to response*/
      For &row_count = 1 To &attachrs.ActiveRowCount

         try
            %Response.WriteBinary(&attachrs(&row_count).GetRecord(@("Record.PSFILE_ATTDET")).FILE_DATA.Value);
         catch Exception &ex
            %Response.SetContentType("text/plain");
            %Response.Write(MsgGetText(137, 182, "Exception in writing binary file data from database" | " " | &ex.ToString()));
         end-try;
      End-For;



      /*Set the response headers*/
      If (&content_type = "") Then
         &content_type = "application/octet-stream";
      End-If;

      %Response.SetHeader("Content-Disposition", "attachment;filename=" | EncodeURL(&attachfile_name));
      %Response.SetContentType(&content_type);

      Break;


      /*Handle errors in request*/
   When 1
      %Response.SetContentType("text/plain");
      %Response.Write(MsgGetText(137, 194, "Invalid request.", &msgdata));
      Break;

   When 2
      %Response.SetContentType("text/plain");
      %Response.Write(MsgGetText(137, 195, "Attachment is either not available or expired."));
      Break;
   When 3
      %Response.SetContentType("text/plain");
      %Response.Write(MsgGetText(137, 196, "Authentication failure."));
      Break;
   End-Evaluate;

End-Function;

