import G3TOKEN:TokenMethods;
import G3DEBUG:DebugMethods;

Global string &G3TOKEN;
Global any &GDBG;
Component G3FORM:Form &G3FRM;

Function IScript_Token;
   If None(&GDBG) Then
      &GDBG = create G3DEBUG:DebugMethods();
   End-If;
   Local G3TOKEN:TokenMethods &TKM = create G3TOKEN:TokenMethods();
   Local string &TokenGUID = &TKM.FindTokenGUID();
   Local G3TOKEN:Token &Token = create G3TOKEN:Token();
   &GDBG.Log(&GDBG._INFO, "&TokenGUID=" | &TokenGUID);
   If All(&TokenGUID) Then
      &G3TOKEN = &TokenGUID;
      If &Token.Load(&TokenGUID) Then
         &GDBG.Log(&GDBG._INFO, "GetTokenNextURL:" | &Token.GetTokenNextURL());
         If &Token.Validated Then
            /*||| Scott L. Token Framework Mods 10/01/20 START |||*/
            &Token.Process();
            &Token.Navigate();
            rem %Response.RedirectURL(&Token.GetTokenNextURL());
         Else
            %Response.Write(&TKM.FormatResponseHTML("ACCESS TOKEN EXPIRED. PLEASE REQUEST ACCESS AGAIN."));
         End-If;
      Else
         %Response.Write(&TKM.FormatResponseHTML("ACCESS TOKEN FAILED TO LOAD. TOKEN:" | &TokenGUID));
      End-If;
   Else
      %Response.Write(&TKM.FormatResponseHTML("NO TOKEN DETECTED."));
      /*||| Scott L. Token Framework Mods 10/01/20 END |||*/
   End-If;
End-Function;

