   Local string &ResultIScriptURL;

   /* CSS */
   Local string &CSS_Includes = "";
   &CSS_Includes = "<link rel=""stylesheet"" type=""text/css"" href=" | %Response.GetStyleSheetURL(StyleSheet.PSSTYLEDEF_SWAN) | " />";
   &CSS_Includes = &CSS_Includes | "<link rel=""stylesheet"" type=""text/css"" href=" | %Response.GetStyleSheetURL(StyleSheet.PSSTYLEREQ) | " />";

   /* JavaScript */
   Local string &JS_Includes = "";
   &JS_Includes = &JS_Includes | "<script type=""text/javascript"" src=" | %Response.GetJavaScriptURL(HTML.PT_COMMON) | "></script>";
   &JS_Includes = &JS_Includes | "<script type=""text/javascript"" src=""/psc/ps/EMPLOYEE/EMPL/s/WEBLIB_PTBR.ISCRIPT1.FieldFormula.IScript_GET_JS?ID=PT_JQUERY_1_6_2_JS""></script>";

   &JS_Includes = &JS_Includes | "<script type=""text/javascript"" src=" | %Response.GetJavaScriptURL(HTML.G_SEARCH_JS) | "></script>";

   /* Create the URL for the search results iScript, it will be inserted into a hidden div and used by an ajax call when the search button is pressed */
   If &Task = "ADD" Then
      If All(&Type) Then
         Local Record &FormTypeRec = CreateRecord(Record.G3FORM_TYPE_TBL);
         &FormTypeRec.G3FORM_TYPE.Value = &Type;
         &FormTypeRec.SelectByKey();

         &FormTypeRec.DESCRSHORT.Value = "Testing Testing Testing";

         If All(&FormTypeRec.DESCRSHORT.Value) Then
            If All(&SearchRec) Then
               &Search_Title = "Create a " | &FormTypeRec.DESCRSHORT.Value | " eForm";
               &ResultIScriptURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_G3TOOLS, Field.ISCRIPT1, "FieldFormula", "IScript_GT_SearchResults");
               &ResultIScriptURL = &ResultIScriptURL | "?G3SEARCH_REC=" | &SearchRec | "&G3FORM_TYPE=" | &Type | "&G3FORM_TASK=ADD";
               If All(&Condition) Then
                  &ResultIScriptURL = &ResultIScriptURL | "&G3FORM_CONDITION=" | &Condition;
               End-If;
            Else
               /* There was no search record passed in so we assume we don't need one (this happens when all we need is a new FormID) */
               Local string &CreateRedirect = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_G3TOOLS, Field.ISCRIPT1, "FieldFormula", "IScript_LaunchAddFormWithoutSearch");
               &CreateRedirect = &CreateRedirect | "?G3FORM_TYPE=" | &Type | "&G3FORM_TASK=ADD";
               If All(&Condition) Then
                  &CreateRedirect = &CreateRedirect | "&G3FORM_CONDITION=" | &Condition;
               End-If;
               %Response.RedirectURL(&CreateRedirect);
            End-If;
         Else
            Error "The Create eForm link you just clicked is not configured correctly.  The Form Type it passed in could not be found.";
         End-If;
      Else
         Error "The Create eForm link you just clicked is not configured correctly.  It must pass in the Form Type.";
      End-If;
   Else
      If All(&Family) Then
         Local Record &FamilyRec = CreateRecord(Record.G3FAMILY_TBL);
         &FamilyRec.G3FORM_FAMILY.Value = &Family;
         &FamilyRec.SelectByKey();
         If All(&FamilyRec.DESCRSHORT.Value) Then
            &ResultIScriptURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_G3TOOLS, Field.ISCRIPT1, "FieldFormula", "IScript_GT_SearchResults");
            &ResultIScriptURL = &ResultIScriptURL | "?G3FORM_FAMILY=" | &Family | "&G3FORM_TASK=" | &Task;
            If All(&SearchRec) Then
               &ResultIScriptURL = &ResultIScriptURL | "&G3SEARCH_REC=" | &SearchRec;
            End-If;

            Evaluate &Task
            When "UPD"
               &Search_Title = "Update a " | &FamilyRec.DESCRSHORT.Value | " eForm";
            When "EVL"
               &Search_Title = "Evaluate a " | &FamilyRec.DESCRSHORT.Value | " eForm";
            When "VWS"
               &Search_Title = "View a " | &FamilyRec.DESCRSHORT.Value | " eForm";
            End-Evaluate;

         Else
            Error "The Search link you just clicked is not configured correctly.  The Form Family it passed in could not be found.";
         End-If;
      Else
         Error "No Family specified.  At this time we can only do Family level Searches for " | &Task;
      End-If;
   End-If;

   /* Create the search fields and search options */
   Local array of array of string &fieldArray;
   &fieldArray = CreateArrayRept(CreateArrayRept("", 0), 0);

   If All(&SearchRec) Then
      /* If a custom search record name was passed in, it gets priority */
      &fieldArray = &GenericSearchHelpers.GenerateSearchFieldsFromRecord(&SearchRec)
   Else
      If All(&Family) Then
         /* Generic Family Search gets second priority */
         &fieldArray = &GenericSearchHelpers.GenerateFamilySearchFields(&Family);
      End-If;
   End-If;

   Local string &SearchFields_HTML = &GenericSearchHelpers.GenerateSearchFieldsHTML(&fieldArray);

   %Response.Write(GetHTMLText(HTML.G3SEARCH_HTML, &CSS_Includes, &JS_Includes, &ResultIScriptURL, &Search_Title, &SearchFields_HTML));

End-Function;

Function IScript_GT_SearchResults
   Local string &Task = %Request.GetParameter("G3FORM_TASK");
   Local string &Family = %Request.GetParameter("G3FORM_FAMILY");
   Local string &Type = %Request.GetParameter("G3FORM_TYPE");
   Local string &Condition = %Request.GetParameter("G3FORM_CONDITION");
   Local string &SearchRec = %Request.GetParameter("G3SEARCH_REC");
   Local string &SearchSQL;
   Local string &filterApplication;
   Local Record &OUTPUTREC;
   Local string &HTML_HeaderRow;
   Local string &HTML_ResultRows;

   Evaluate &Task
   When = "ADD"
      If None(&SearchRec) Then
         /* It really should not be possible to get here unless changes are made to IScript_GT_Search. */
         Error "In the Add task, you must pass a Search Record Name for displaying the results.";
      End-If;
   When = "EVL"
      If None(&SearchRec) Then
         &SearchRec = "G3ALLE_SRCH";
      End-If;
   When = "UPD"
      If None(&SearchRec) Then
         &SearchRec = "G3ALLU_SRCH";
      End-If;
   When = "VWS"
      If None(&SearchRec) Then
         &SearchRec = "G3ALLV_SRCH";
      End-If;
   End-Evaluate;

   &SearchSQL = "Select * From %Table(" | &SearchRec | ")";
   &OUTPUTREC = CreateRecord(@("Record." | &SearchRec));
   &SearchSQL = &SearchSQL | &GenericSearchHelpers.RetrieveSearchCriteriaAsWhere(&Family);
   &HTML_HeaderRow = &GenericSearchHelpers.GenerateHeaderRowHTML(&OUTPUTREC);

   Evaluate &Task
   When = "EVL"
      /* Can't eval your own forms by default*/
      &SearchSQL = &SearchSQL | " And G3ORIGINAL_OPRID <> '" | %UserId | "'";
      &filterApplication = "current";
   When = "UPD"
      /* Update needs OPRID added */
      &SearchSQL = &SearchSQL | " And OPRID = '" | %UserId | "' AND G3FORM_TASK = 'UPD'";
      &filterApplication = "none";
   When = "VWS"
      &filterApplication = "all";
   End-Evaluate;

   If &Task = "ADD" Then
      &HTML_ResultRows = &GenericSearchHelpers.GenerateResultRowsForAddHTML(&SearchSQL, &OUTPUTREC, &Type, &Condition, &SearchRec);
   Else
      &HTML_ResultRows = &GenericSearchHelpers.GenerateResultRowsHTML(&SearchSQL, &OUTPUTREC, &filterApplication, &Task);
   End-If;

   %Response.Write(GetHTMLText(HTML.G3SEARCH_RESULT_HTML, &HTML_HeaderRow, &HTML_ResultRows));

End-Function;


Function Iscript_VisualIfHover
   Local string &visifId = %Request.GetParameter("VisifID");

   Local G3LOGIC:VisualIfFactory &fac = create G3LOGIC:VisualIfFactory( Null);
   Local G3LOGIC:VisualIf &visif = create G3LOGIC:VisualIf(&visifId, &fac);

   If (None(&visifId)) Then
      Return;
   End-If;

   Local string &visualizer = &visif.getVisualizer( False, False, "G3VIS_STYLE_HOVER", False);

   %Response.Write(&visualizer);

End-Function;


