/* Stephen Phillips  12/28/2016  J1372   New way to download */
Function IScript_ViewLogFile

   Local string &LINE;
   Local File &FILE;
   Local number &index1, &index2;
   Local string &outFilename;

   /* Get the name */
   &index1 = Find("/", &FileToDownload);
   If &index1 = 0 Then;
      &index1 = Find("\\", &FileToDownload);
   End-If;
   &index2 = &index1;
   While &index1 > 0
      &index1 = Find("/", &FileToDownload, &index2 + 1);
      If &index1 = 0 Then;
         &index1 = Find("\\", &FileToDownload, &index2 + 1);
      End-If;
      If &index1 > 0 Then;
         &index2 = &index1;
      End-If;
   End-While;
   If &index2 = 0 Then;
      &outFilename = &FileToDownload;
   Else;
      &outFilename = Substring(&FileToDownload, &index2 + 1, Len(&FileToDownload));
   End-If;

   %Response.SetContentType("text/plain");
   %Response.SetHeader("Content-Disposition", "attachment; filename=""" | &outFilename | """");
   rem %Response.SetHeader("filename", &FileToDownload);
   %Response.UseSimpleURL( False);
   &FILE = GetFile(&FileToDownload, "R", %FilePath_Absolute);
   If &FILE.IsOpen Then
      /* Paul T. GTC-2233 02/11/2020 Test faster download BEGIN */
      /*||| Mike G. GTC-2369 05/21/2020 - Revert 2233 BEGIN |||*/
      While &FILE.ReadLine(&LINE)
         %Response.Write(&LINE | Char(13) | Char(10));
      End-While;
      rem %Response.Write(&FILE.GetString( False));
      /*||| Mike G. GTC-2369 05/21/2020 Test faster download END |||*/
      /* Paul T. GTC-2233 02/11/2020 - Revert 2233  END */
   End-If;
   &FILE.Close();

End-Function;

