Declare Function UpdateXMLString PeopleCode GPCH_FM_FUNCLIB.GPCH_FM_FORM_ID FieldFormula;
Local SQL &SQL;
Local Record &REC;
Local string &Parameter;
Local number &pos;
Local array of string &StringArray, &ParameterArray, &FieldNames, &FieldValues;



Function IScript_GPCH_FM_Submit()
   &REQUEST = %Request;
   &RESPONSE = %Response;

   &FieldNames = CreateArrayRept("", 0);

   &FieldValues = CreateArrayRept("", 0);

   &ParameterArray = %Request.GetParameterNames();
   %Response.Write("<HTML><BODY> Page Created by IScript GPCH_FM_Submit <TABLE BORDER=1 CELLPADDING=1 CELLSPACING=1>");
   %Response.Write("<TD><B>");
   %Response.Write("FIELD NAME");
   %Response.Write("</B></TD>");
   %Response.Write("<TD><B>");
   %Response.Write("FIELD VALUE");
   %Response.Write("</B></TD>");
   For &t = 1 To &ParameterArray.Len
      &StringArray = %Request.GetParameterValues(&ParameterArray [&t]);
      &Parameter = &ParameterArray [&t];
      &String = "";
      For &i = 1 To &StringArray.Len
         &String = &String | &StringArray [&i];
      End-For;

      %Response.Write("<TR>");
      %Response.Write("<TD>");
      %Response.Write(LTrim(String(&Parameter)));
      %Response.Write("</TD>");
      %Response.Write("<TD>");
      %Response.Write(LTrim(String(&String)));
      %Response.Write("</TD>");
      %Response.Write("</TR>");

      &FieldNames.Push(LTrim(String(&Parameter)));
      &FieldValues.Push(LTrim(String(&String)));


      Evaluate LTrim(String(&Parameter))
      When "PS_EMPLID"
         &EMPLID = LTrim(String(&String));
         Break;
      When "PS_EMPL_RCD"
         &EMPL_RCD = Value(LTrim(String(&String)));
         Break;
      When "PS_BEGIN_DT"
         &BEGIN_DT = Date(LTrim(String(&String)));
         Break;
      When "PS_END_DT"
         &END_DT = Date(LTrim(String(&String)));
         Break;
      When "PS_COMPANY"
         &COMPANY = LTrim(String(&String));
         Break;
      When "PS_GPCH_IF_VER"
         &GPCH_IF_VER = Value(LTrim(String(&String)));
         Break;
      When "PSReportID"
         &PSReportID = (LTrim(String(&String)));
         Break;
      When "PSLanguageCD"
         &PSLanguageCD = (LTrim(String(&String)));
         Break;
      When "PSStartDate"
         &String = Substitute(LTrim(String(&String)), "-", "");
         &PSStartDate = Date(Value(&String));
         Break;
      End-Evaluate;
   End-For;


   SQLExec("SELECT GPCH_RP_TX7_DATA FROM PS_GPCH_IF_TX07 WHERE EMPLID = :1 AND EMPL_RCD = :2 AND BEGIN_DT = %DateIn(:3) AND END_DT = %DateIn(:4) AND COMPANY = :5 AND GPCH_IF_VER = :6", &EMPLID, &EMPL_RCD, &BEGIN_DT, &END_DT, &COMPANY, &GPCH_IF_VER, &XMLString);

   %Response.Write("<TR>");
   %Response.Write("<TD>");
   %Response.Write(&EMPLID | String(&EMPL_RCD) | String(&BEGIN_DT) | String(&END_DT) | &COMPANY | String(&GPCH_IF_VER));
   %Response.Write("</TD>");
   %Response.Write("<TD>");
   %Response.Write(Substring(&XMLString, 1, Len(&XMLString)));
   %Response.Write("</TD>");
   %Response.Write("</TR>");

   &XMLString = UpdateXMLString(&XMLString, &PSReportID, &PSStartDate, &PSLanguageCD, &FieldNames, &FieldValues);



   %Response.Write("<TR>");
   %Response.Write("<TD>");
   %Response.Write(&EMPLID | String(&EMPL_RCD) | String(Substitute(&BEGIN_DT, "-", "")) | String(&END_DT) | &COMPANY | String(&GPCH_IF_VER));
   %Response.Write("</TD>");
   %Response.Write("<TD>");
   %Response.Write(Substring(&XMLString, 1, Len(&XMLString)));
   %Response.Write("</TD>");
   %Response.Write("</TR>");

   SQLExec("UPDATE PS_GPCH_IF_TX07 SET GPCH_RP_TX7_DATA = %TEXTIN(:7) WHERE EMPLID = :1 AND EMPL_RCD = :2 AND BEGIN_DT = %DateIn(:3) AND END_DT = %DateIn(:4) AND COMPANY = :5 AND GPCH_IF_VER = :6", &EMPLID, &EMPL_RCD, &BEGIN_DT, &END_DT, &COMPANY, &GPCH_IF_VER, &XMLString);



   %Response.Write("</TABLE></BODY></HTML>");
   Return;
End-Function;

