Function XSLTransform();


   &XMLInOut = TransformEx(&XMLInOut, GetHTMLText(@("HTML." | &StyleIn)));

End-Function;


Function CollapsTaxSalaries();
   /* Remove empty TAGS from &Tax_XML using Stylesheet GPCH_LAW_COLLAPS */
   &StyleIn = "GPCH_LAW_COLLAPS";
   &XMLInOut = &Tax_XML;

   XSLTransform();

   &Pos1 = Find("<TaxSalary>", &XMLInOut);
   &Pos2 = Find("</TaxSalaries>", &XMLInOut);
   /* Cut starting attributes as returned by transformation through GPCH_LAW_MASTER */
   &Tax_XML = "<TaxSalaries>" | Substring(&XMLInOut, &Pos1, &Pos2 - &Pos1 + 14);
End-Function;


Function ExplodeTaxSalaries();
   /* Fill &Tax_XML with all possible TAGs using Stylesheet GPCH_LAW_MASTER */
   &StyleIn = "GPCH_LAW_MASTER";
   &XMLInOut = &Tax_XML;

   XSLTransform();

   &Pos1 = Find("<TaxSalary>", &XMLInOut);
   &Pos2 = Find("</TaxSalaries>", &XMLInOut);
   /* Cut starting attributes as returned by transformation through GPCH_LAW_MASTER */
   &Tax_XML = "<TaxSalaries>" | Substring(&XMLInOut, &Pos1, &Pos2 - &Pos1 + 14);
End-Function;

Function ExplodeParticulars(); /* Fill &Tax_XML with all possible TAGs using Stylesheet GPCH_LAW_Identify */
   &StyleIn = "GPCH_LAW_IDENTIFY";
   &Identify_XML = "<?xml version=""1.0""?> <ROOT>" | &Identify_XML | "</ROOT>";
   &XMLInOut = &Identify_XML;
   XSLTransform();
   &Pos1 = Find("<Particulars>", &XMLInOut);
   &Pos2 = Find("</Work>", &XMLInOut); /* Cut starting attributes as returned by transformation through GPCH_LAW_IDENTIFY*/
   &Identify_XML = Substring(&XMLInOut, &Pos1, &Pos2 - &Pos1 + 7);
End-Function;

Function CollapsParticulars(); /* Remove empty TAGS from &Tax_XML using Stylesheet GPCH_LAW_COLLAPS */
   &StyleIn = "GPCH_LAW_COLLAPS";
   &XMLInOut = &Identify_XML;
   XSLTransform();
   &Pos1 = Find("<Particulars>", &XMLInOut);
   &Pos2 = Find("</Work>", &XMLInOut); /* Cut starting attributes as returned by transformation through GPCH_LAW_IDENTIFY*/
   &Identify_XML = Substring(&XMLInOut, &Pos1, &Pos2 - &Pos1 + 7);
End-Function;

Function ExplodeAdditional(); /* Fill &Tax_XML with all possible TAGs using Stylesheet GPCH_LAW_Additional */
   &StyleIn = "GPCH_LAW_ADDITIONAL";
   &Additional_XML = "<?xml version=""1.0""?>" | &Additional_XML;
   &XMLInOut = &Additional_XML;
   XSLTransform();
   &Pos1 = Find("<Additional>", &XMLInOut);
   &Pos2 = Find("</Additional>", &XMLInOut); /* Cut starting attributes as returned by transformation through GPCH_LAW_Additional*/
   &Additional_XML = Substring(&XMLInOut, &Pos1, &Pos2 - &Pos1 + 13);
End-Function;



Function IScript_GPCH_FM_Submit()
   &REQUEST = %Request;
   &RESPONSE = %Response;

   &FieldNames = CreateArrayRept("", 0);

   &FieldValues = CreateArrayRept("", 0);

   &ParameterArray = %Request.GetParameterNames();

   For &t = 1 To &ParameterArray.Len
      &StringArray = %Request.GetParameterValues(&ParameterArray [&t]);
      &Parameter = &ParameterArray [&t];
      &String = "";
      For &i = 1 To &StringArray.Len
         &String = &String | &StringArray [&i];
      End-For;



      &FieldNames.Push(LTrim(String(&Parameter)));
      &FieldValues.Push(LTrim(String(&String)));


      Evaluate LTrim(String(&Parameter))
      When "PS_EMPLID"
         &EMPLID = LTrim(String(&String));
         Break;
      When "PS_EMPL_RCD"
         &EMPL_RCD = Value(LTrim(String(&String)));
         Break;
      When "PS_BEGIN_DT"
         &BEGIN_DT = Date(LTrim(String(&String)));
         Break;
      When "PS_END_DT"
         &END_DT = Date(LTrim(String(&String)));
         Break;
      When "PS_COMPANY"
         &COMPANY = LTrim(String(&String));
         Break;
      When "PS_GPCH_IF_VER"
         &GPCH_IF_VER = Value(LTrim(String(&String)));
         Break;

      When "PS_GPCH_EG_DOMAINID"
         &GPCH_EG_DOMAINID = Value(LTrim(String(&String)));
         Break;
      When "PSReportID"
         &PSReportID = (LTrim(String(&String)));
         Break;
      When "PSLanguageCD"
         &PSLanguageCD = (LTrim(String(&String)));
         Break;
      When "PSStartDate"
         &String = Substitute(LTrim(String(&String)), "-", "");
         &PSStartDate = Date(Value(&String));
         Break;
      End-Evaluate;
   End-For;







   SQLExec(SQL.GPCH_GET_PERSON_XML, &COMPANY, &EMPLID, &EMPL_RCD, &BEGIN_DT, &END_DT, &GPCH_IF_VER, &GPCH_EG_DOMAINID, "0", "8", &Identify_XML, &Tax_XML);

   /* FMB 20090115 */
   SQLExec("Select GPCH_RP_TX7_DATA from PS_GPCH_IF_TX07  WHERE EMPLID = :1 AND EMPL_RCD = :2 AND BEGIN_DT = %DateIn(:3) AND END_DT = %DateIn(:4) AND COMPANY = :5 AND GPCH_IF_VER = :6 AND GPCH_EG_DOMAINID=:7", &EMPLID, &EMPL_RCD, &BEGIN_DT, &END_DT, &COMPANY, &GPCH_IF_VER, &GPCH_EG_DOMAINID, &Additional_XML);

   &Tax_XML = "<?xml version=""1.0""?>" | &Tax_XML;
   ExplodeTaxSalaries();
   ExplodeParticulars(); /* FMB */
   &LAW_XML = "<?xml version=""1.0""?><ROOT>" | &Identify_XML | &Tax_XML | &Additional_XML | "</ROOT>";


   &XMLString = UpdateXMLString(&LAW_XML, &PSReportID, &PSStartDate, &PSLanguageCD, &FieldNames, &FieldValues);


   &Pos1 = Find("<TaxSalaries>", &XMLString);
   &Pos2 = Find("</TaxSalaries>", &XMLString);


   &Tax_XML = Substring(&XMLString, &Pos1, &Pos2 - &Pos1 + 14);

   &Tax_XML = "<?xml version=""1.0""?>" | &Tax_XML;

   CollapsTaxSalaries();

   /* FMB 20090115 */
   &Tax_XML = Substitute(&Tax_XML, "<FreeTransport>X</FreeTransport>", "<FreeTransport></FreeTransport>");
   &Tax_XML = Substitute(&Tax_XML, "<CanteenLunchCheck>X</CanteenLunchCheck>", "<CanteenLunchCheck></CanteenLunchCheck>");
   &Tax_XML = Substitute(&Tax_XML, "<Guidance>X</Guidance>", "<Guidance></Guidance>");
   /* FMB for check box 'child allowance Geneve (set to 'YES' by PDF) */
   &Tax_XML = Substitute(&Tax_XML, "<ChildAllowancePerAHV-AVS>Yes</ChildAllowancePerAHV-AVS>", "<ChildAllowancePerAHV-AVS></ChildAllowancePerAHV-AVS>");

   &Pos1 = Find("<Particulars>", &XMLString);
   &Pos2 = Find("</Work>", &XMLString);
   rem syed &Identify_XML = "<?xml version=""1.0""?> <ROOT>" | Substring(&XMLString, &Pos1, &Pos2 - &Pos1 + 7) | "</ROOT>";
   rem FMB &Identify_XML = Substring(&XMLString, &Pos1, &Pos2 - &Pos1 + 7);
   &Identify_XML = "<?xml version=""1.0""?> <ROOT>" | Substring(&XMLString, &Pos1, &Pos2 - &Pos1 + 7) | "</ROOT>";


   /* CollapsParticulars();  */
   CollapsParticulars();

   &Pos1 = Find("<Additional>", &XMLString);
   &Pos2 = Find("</Additional>", &XMLString);
   &Additional_XML = Substring(&XMLString, &Pos1, &Pos2 - &Pos1 + 13);

   /*   CollapsParticulars();   */
   SQLExec("UPDATE PS_GPCH_EG_PERSON SET GPCH_EG_PRSN_XML = %TEXTIN(:6) WHERE EMPLID = :1 AND EMPL_RCD = :2 AND GPCH_RC_PAY_YEAR = :3 AND COMPANY = :4 AND GPCH_IF_VER = :5 AND GPCH_SI_PROV_TYPE=:7 AND GPCH_EG_DOMAINID=:8", &EMPLID, &EMPL_RCD, Year(&BEGIN_DT), &COMPANY, &GPCH_IF_VER, &Identify_XML, "0", &GPCH_EG_DOMAINID);
   SQLExec("UPDATE PS_GPCH_IF_TX07 SET GPCH_RP_TX7_DATA = %TEXTIN(:7) WHERE EMPLID = :1 AND EMPL_RCD = :2 AND BEGIN_DT = %DateIn(:3) AND END_DT = %DateIn(:4) AND COMPANY = :5 AND GPCH_IF_VER = :6 AND GPCH_EG_DOMAINID=:8", &EMPLID, &EMPL_RCD, &BEGIN_DT, &END_DT, &COMPANY, &GPCH_IF_VER, &Additional_XML, &GPCH_EG_DOMAINID);

   /* FMB 20090115 End */



   SQLExec("UPDATE PS_GPCH_EG_PERSON SET GPCH_EG_PRSN_XML = %TEXTIN(:7) WHERE EMPLID = :1 AND EMPL_RCD = :2 AND BEGIN_DT = %DateIn(:3) AND END_DT = %DateIn(:4) AND COMPANY = :5 AND GPCH_IF_VER = :6 AND GPCH_SI_PROV_TYPE=:8 AND GPCH_EG_DOMAINID=:9", &EMPLID, &EMPL_RCD, &BEGIN_DT, &END_DT, &COMPANY, &GPCH_IF_VER, &Tax_XML, "8", &GPCH_EG_DOMAINID);


   Local Record &recE;
