Function Iscript_GPDE_GenXML
   Local Record &recELSTERfile = CreateRecord(Record.GPDE_TX_XMLFILE);
   Local string &Ticket = %Request.GetParameter("GPDE_ELSTER_TKT");
   If All(&Ticket) Then
      Local boolean &EmployeeData = False;
      &recELSTERfile.GPDE_ELSTER_TKT.Value = &Ticket;
      &recELSTERfile.SEQ_NUM.Value = Value(%Request.GetParameter("SEQ_NUM"));
   Else
      /* called from Employee */
      &recELSTERfile = CreateRecord(Record.GPDE_TX_DATA);
      &recELSTERfile.EMPLID.Value = %Request.GetParameter("EMPLID");
      &recELSTERfile.EMPL_RCD.Value = %Request.GetParameter("EMPL_RCD");
      &recELSTERfile.EFFDT.Value = %Request.GetParameter("EFFDT");
      &EmployeeData = True;
   End-If;
   If &recELSTERfile.SelectByKey() Then
      Local string &xml = &recELSTERfile.GPDE_XML_TAX_INFO.Value;
      If &EmployeeData Then
         &xml = Substitute(&xml, "<?xml version=" | Char(34) | "1.0" | Char(34) | "?>", "<?xml version=" | Char(34) | "1.0" | Char(34) | "?><Elster>");
         &xml = &xml | "</Elster>";
      Else
         Local GPDE_EGOV_XML:XMLDataCompressor &Zip = create GPDE_EGOV_XML:XMLDataCompressor();
         &xml = &Zip.UnzipifZipped(&xml);
      End-If;
      %Response.SetContentType("text/xml");
      %Response.Write(&xml);
   End-If;
   Return;
End-Function;

import GPDE_FM:FormHttpRequest;
import GPDE_FM_PS:*;
import GPDE_CT:*;
import GPDE_UTILITIES:XMLUtil;


Function ProcessIt(&submit)

   Local GPDE_FM:FormHttpRequest &req = create GPDE_FM:FormHttpRequest(%Request);
   Local GPDE_CT:CTCreateXML &xml;
   Local GPDE_UTILITIES:XMLUtil &xmlUti;
   Local array of string &ParameterArray;
   Local array of string &FieldNames, &FieldValues;
   Local string &XMLSTring;
   Local string &parsed;
   Local number &i;

   &xmlUti = create GPDE_UTILITIES:XMLUtil();

   &REQUEST = %Request;
   &RESPONSE = %Response;
   &ParameterArray = %Request.GetParameterNames();

   &FieldNames = CreateArrayRept("", 0);
   &FieldValues = CreateArrayRept("", 0);
   &FieldNames = &req.Names;
   &FieldValues = &req.Values;



   For &i = 1 To &FieldValues.Len

      &parsed = &xmlUti.getParsed(&FieldValues [&i]);
      &FieldValues [&i] = &parsed;


   End-For;



   &xml = create GPDE_CT:CTCreateXML(&FieldNames, &FieldValues);


   /*get and store parameter data from forms*/
   &EMPLID = LTrim(RTrim(&xml.getParam("PS_EMPLID")));
   &EMPL_RCD = Value(LTrim(RTrim(&xml.getParam("PS_EMPL_RCD"))));
   &GPDE_FM_FORM_ID = LTrim(RTrim(&xml.getParam("PS_GPDE_FM_FORM_ID")));
   &EFFDT = Date(LTrim(RTrim(&xml.getParam("PS_EFFDT"))));
   &GPDE_FM_LANG_CD = LTrim(RTrim(&xml.getParam("PS_GPDE_FM_LANG_CD")));
   &GPDE_CT_VERSION = Value(LTrim(RTrim(&xml.getParam("PS_GPDE_CT_VERSION"))));
   &GPDE_CT_OPRNAME = LTrim(RTrim(&xml.getParam("PS_GPDE_CT_OPRNAME")));
   &LAST_UPDATE_DTTM = LTrim(RTrim(&xml.getParam("PS_LAST_UPDATE_DTTM")));

   If All(&EMPLID) Then

      Local array of GPDE_FM_PS:PSFormField &PSFormFields;
      If &submit Then
         &Form = create GPDE_FM_PS:PSForm(LTrim(&GPDE_FM_FORM_ID), LTrim(&GPDE_FM_LANG_CD), Date(&EFFDT));
         &PSFormFields = &Form.PSFields;

         For &i = 1 To &PSFormFields.Len

            &index = &FieldNames.Find(&PSFormFields [&i].ID);
            If &index > 0 Then
               &xml.setTag(&index, &PSFormFields [&i].ID);

               If &PSFormFields [&i].XMLTag <> "" Then
                  &xml.setTag(&index, &PSFormFields [&i].XMLTag);
               End-If;
            End-If;
         End-For;

         &XMLSTring = &xml.getCTXMLString();
         &xml.UpdateData(&EMPLID, &EMPL_RCD, &GPDE_FM_FORM_ID, &EFFDT, &GPDE_FM_LANG_CD, &GPDE_CT_VERSION, &GPDE_CT_OPRNAME, &LAST_UPDATE_DTTM, &XMLSTring);
      End-If;
      &MyCompURL = GenerateComponentContentURL(%Portal, %Node, MenuName.GPDE_MAINTAIN_PAYROLL_DATA, "GBL", Component.GPDE_CT_MAIN, Page.GPDE_CT_HIST, "U") | "&EMPLID=" | EncodeURL(&EMPLID) | "&EMPL_RCD=" | EncodeURL(&EMPL_RCD);
   Else
      &MyCompURL = GenerateComponentContentURL(%Portal, %Node, MenuName.GPDE_MANAGE_PAYROLL_PROCESS, "GBL", Component.GPDE_FM_DEF, Page.GPDE_FM_OK, "U") | "&GPDE_FM_FORM_ID=" | EncodeURL(&GPDE_FM_FORM_ID);

   End-If;


   &RESPONSE.RedirectURL(EncodeURL(&MyCompURL));

   Return;

End-Function;

Function IScript_GPDE_FM_Cancel()

   /* cancel processing, modifications will not be saved */
   &submit = False;
   ProcessIt(&submit);

End-Function;

Function IScript_GPDE_FM_SubmitTest()
   /* submit changes for saving*/
   &submit = True;
   ProcessIt(&submit);
End-Function;

Function IScript_ShowXML()

   /*** Verify that information requested, belongs to User that call IScript ***/
   If %EmployeeId = %Request.GetParameter("EMPLID") Then
      try

         Local string &Emplid, &Cal_Run_id, &GP_PAYGROUP, &Cal_id, &Orig_Cal_Run_id, &XMLData;
         Local number &Empl_rcd, &Rslt_Seg_Num;

         &Emplid = %Request.GetParameter("EMPLID");
         &Cal_Run_id = %Request.GetParameter("CAL_RUN_ID");
         SQLExec("SELECT GPMX_XML_PAYSLIP FROM PS_GPMX_SS_XML_VW WHERE EMPLID = :1 AND CAL_RUN_ID = :2", &Emplid, &Cal_Run_id, &XMLData);
         If All(&XMLData) Then
            %Response.SetContentType("application/xml");
            %Response.WriteLine(&XMLData);
         Else
            %Response.SetContentType("text/plain");
            %Response.WriteLine(MsgGetText(17240, 129, "No information found."));
         End-If;
      catch Exception &err
         %Response.SetContentType("text/plain");
         %Response.WriteLine(MsgGetText(17240, 128, "An error has occurred. Please contact your system administrator"));
      end-try;

   Else
      %Response.SetContentType("text/plain");
      %Response.WriteLine(MsgGetText(17240, 129, "No information found."));
   End-If;
   Return;
End-Function;

import GS_TELEPHONY:Conversation:TwilioSignature;

rem import GS_TELEPHONY:Conversation:Listener;
/*
Twilio will read "123456" as 
one hundred twenty three thousand, four hundred fifty six
so we put spaces between the digits to get 
each one read properly
*/
Function ReadablePIN(&pin As string) Returns string
   Local string &readable = "";
   Local integer &i;
   For &i = 1 To Len(&pin)
      If &i > 1 Then
         &readable = &readable | ",";
         <* Change - twilio say , and . are natural pauses - this was a space *>
      End-If;
      &readable = &readable | Substring(&pin, &i, 1);
   End-For;
   Return &readable;
End-Function;

Function iScript_TwilioRequest()
   /* for this to work, do not include &postDataBin parameter on the iScript. */
   Local string &callID = %Request.GetParameter("CallSid");
   rem &callID = "CA3d68ad25b255aabb07b1e5683426163d";
   /* X-Twilio-Signature validation */
   Local string &xsig = %Request.GetHeader("X-Twilio-Signature");
   Local object &xresponse = %Response;
   Local object &xrequest = %Request;
   Local GS_TELEPHONY:Conversation:TwilioSignature &X_Twilio = create GS_TELEPHONY:Conversation:TwilioSignature(&xrequest, &xresponse);
   rem Local GS_TELEPHONY:Conversation:Listener &X_Twilio = create GS_TELEPHONY:Conversation:Listener(&xrequest, &xresponse);
   /*End check */
   &X_Twilio.Process();
   If None(&callID) Then
      Error ("Can't find Callsid");
   End-If;

   Local Record &call = CreateRecord(Record.GS_2FA_CALL_HDR);
   &call.GetField(Field.GS_TEL_CALL_ID).Value = &callID;
   If Not &call.SelectByKey() Then
      Error ("Can't retrieve callsid");
   End-If;

   Local Record &call2 = CreateRecord(Record.GS_CHALLENG_TBL);
   &call2.GetField(Field.OPRID).Value = &call.GetField(Field.OPRID).Value;
   If Not &call2.SelectByKey() Then
      Error ("Can't find pin");
   End-If;

   Local string &pin = ReadablePIN(&call2.GetField(Field.GS_PIN).Value);
   Local string &msg = "Thank you. ";
   &msg = &msg | "Your Pin number is " | &pin;
   &msg = &msg | ", Your Pin number is " | &pin;

   %Response.SetHeader("X-GS-Product", "ERPFirewall");
   %Response.SetContentType("application/xml");

   Local string &res = "";
   Local XmlDoc &xmlResponse = CreateXmlDoc("");
   Local XmlNode &responseNode = &xmlResponse.CreateDocumentElement("Response");
   Local XmlNode &sayNode = &responseNode.AddElement("Say");

   Local XmlNode &pinMsgNode = &sayNode.AddText(&msg);
   /* Pass back completed XML */
   %Response.Write(&xmlResponse.GenXmlString());
End-Function;

