Function iScript_FieldMask_TOTP()

   Local string &userid = %Request.GetParameter("oprid");
   Local string &sessionid = %Request.GetParameter("sessionIdentifier");
   Local string &ruleName = %Request.GetParameter("ruleName");
   Local array of string &tokens = Split(&sessionid, "!");
   &sessionid = &tokens [1];

   Local string &sReturnURL = %Request.QueryString;
   Local number &n = Find("returnUrl", &sReturnURL);
   If &n > 0 Then
      &sReturnURL = Substring(&sReturnURL, &n + 10, Len(&sReturnURL));
   End-If;

   Local Record &ChallengeData = CreateRecord(Record.GS_OTP_CHAL_TBL);
   &ChallengeData.OPRID.Value = &userid;
   &ChallengeData.GS_WEBSESS_ID.Value = &sessionid;
   &ChallengeData.GS_FW_RULE_ID.Value = &ruleName;

   Local boolean &haveRow = &ChallengeData.SelectByKey();
   If &haveRow Then
      Local boolean &passed = (&ChallengeData.GS_PASSED_CHALLENG.Value = "Y");
      If &passed Then
         Local datetime &expireDttm = &ChallengeData.GS_EXP_DTTM.Value;
         Local boolean &expired = (All(&expireDttm) And
            (&expireDttm < %Datetime));
         If Not &expired Then
            &needsChallenge = False;
            &ChallengeData.GS_RQST_URL.Value = &sReturnURL;
         Else
            &ChallengeData.GS_RQST_URL.Value = &sReturnURL;
         End-If;
      Else
         &ChallengeData.GS_RQST_URL.Value = &sReturnURL;
      End-If;
   Else
      REM Have to reset keys after failed .SelectByKey();
      &ChallengeData.OPRID.Value = &userid;
      &ChallengeData.GS_WEBSESS_ID.Value = &sessionid;
      &ChallengeData.GS_FW_RULE_ID.Value = &ruleName;
      &ChallengeData.GS_RQST_URL.Value = &sReturnURL;
      &ChallengeData.GS_PASSED_CHALLENG.Value = "N";
      &ChallengeData.GS_OTP_FAIL_COUNT.Value = 0;
   End-If;

   &ChallengeData.GS_OTP_CHAL_COUNT.Value = &ChallengeData.GS_OTP_CHAL_COUNT.Value + 1;
   &ChallengeData.GS_OTP_UPD_DTTM.Value = %Datetime;
   Local boolean &saved;

   If &haveRow Then
      &saved = &ChallengeData.Update();
   Else
      &saved = &ChallengeData.Save();
   End-If;

   &redURL = GenerateComponentContentRelURL(%Portal, %Node, MenuName.GS_OTP, %Market, Component.GS_CHALLNG_OTP, "", "U");
   %Response.RedirectURL(&redURL | "&ruleName=" | &ruleName);
End-Function;

