REM extract the remote IP address from request;
Function getIPFromRequest(&req) Returns string
   Local string &ipaddr = "";
   Local string &xforward = &req.GetHeader("X-Forwarded-For");
   Local array of string &fwds;
   /* pick the last ip address in the X-Forwarded-For list */
   If All(&xforward) Then
      &fwds = Split(&xforward, ",");
      &ipaddr = &fwds [&fwds.Len - 1];
   Else
      &ipaddr = &req.RemoteAddr;
   End-If;
   Return &ipaddr;
End-Function;

