Function getActionClass(&action As string) Returns string
   Evaluate &action
   When "RED"
      Return "RedirectAction";
      Break;
   When "LOG"
      Return "LogAction";
      Break;
   When "LDB"
      Return "LogActionDB";
      Break;
   When "ALW"
      Return "AllowAction";
      Break;
   When "BLG"
      Return "BrowserLogAction";
      Break;
   When "BLK"
      Return "BlockAction";
      Break;
   When "SET"
      Return "SetSessionValueAction";
      Break;
   When "DEL"
      Return "DeleteSessionValueAction";
      Break;
   When "NSS"
      Return "NoSSOAction";
      Break;
   When "MOB"
      Return "MarkMobileAction";
      Break;
   When "NMB"
      Return "MarkNotMobileAction";
      Break;
   When "MBR"
      Return "MarkMobileRequestAction";
      Break;
   When "NMR"
      Return "MarkNotMobileRequestAction";
      Break;
   When "GST"
      Return "GuestAccountAction";
      Break;
   When "STI"
      Return "SessionTimeoutAction";
      Break;
   When "RQH"
      Return "SetRequestHeaderAction";
      Break;
   When "RSH"
      Return "SetResponseHeaderAction";
      Break;
   When "PFR"
      Return "PageFieldAction";
      Break;
   When "QFR"
      Return "QueryFieldAction";
      Break;
   When "SFR"
      Return "SearchFieldAction";
      Break;
   When "RPP"
      Return "MarkRequestProfileAction";
      Break;
   When "2FA"
      Return "TwoFactorChallengeAction";
      Break;
   When "SML"
      Return "SAMLAuthenticationAction";
      Break;
   When "JWT"
      Return "OIDCAuthenticationAction";
      Break;
   When "KRB"
      Return "KerberosAuthenticationAction";
      Break;
   When "DSA"
      Return "DisableSessionAccessibilityAction";
      Break;
   When "SLO"
      Return "SAMLLogoutAction";
      Break;
   When "HAO"
      Return "HtmlAddOnAction";
      Break;
   When "NPS" /* Nested Policy Set*/
      rem WinMessage("RulesetEvaluationAction");
