      Break;
   When "FHPNAME"
      &sClassName = "FluidHomePageNameCondition";
      Break;
   When "FLUIDCOMP"
      &sClassName = "FluidComponentCondition";
      Break;
   When "SESSVAR"
      &sClassName = "SessionValueCondition";
      Break;
   When "SESSEXISTS"
      &sClassName = "SessionValueExistsCondition";
      Break;
   When "SESSESTAB"
      &sClassName = "SessionEstablishedCondition";
      Break;
   When "POSTLOGIN"
      &sClassName = "PostLoginCondition";
      Break;
   When "ISPSTLOGIN"
      &sClassName = "PostLoggedInCondition";
      Break;
   When "NAVOBJECT"
      &sClassName = "NavObjectCondition";
      Break;
   When "WEBPROFILE"
      &sClassName = "WebProfileCondition";
      Break;
   When "URLPARM"
      &sClassName = "UrlParameterCondition";
      Break;
   When "FORMPARM"
      &sClassName = "FormParameterCondition";
      Break;
   When "SAMLASRT"
      &sClassName = "SAMLAssertionValueCondition";
      Break;
   When "HTTPHEADER"
   When "HTTPHDRQST"
      &sClassName = "HttpHeaderRequestValueCondition";
      Break;
   When "HTTPHDRESP"
      &sClassName = "HttpHeaderResponseValueCondition";
      Break;
   When "HTTPCODE"
      &sClassName = "HttpResponseCodeCondition";
      Break;
   When "COOKIE"
   When "COOKIERQST"
      &sClassName = "RequestCookieValueCondition";
      Break;
   When "COOKIERESP"
      &sClassName = "ResponseCookieValueCondition";
      Break;
   When "SEARCHPAGE"
      &sClassName = "SearchPageCondition";
      Break;
   When "RQST_PHASE"
      &sClassName = "RequestPhaseCondition";
      Break;
   When "RESP_PHASE"
      &sClassName = "ResponsePhaseCondition";
      Break;
   When "FIELD"
      &sClassName = "PageFieldFieldCondition";
      Break;
   When "QUERYFIELD"
      &sClassName = "QueryFieldFieldCondition";
      Break;
   When "SRCHFIELD"
      &sClassName = "SearchFieldFieldCondition";
      Break;
   When "RECORD"
      &sClassName = "PageFieldRecordCondition";
      Break;
   When "RECFIELD"
      &sClassName = "PageFieldRecFieldCondition";
      Break;
   When "SWITCHUSER"
      &sClassName = "SwitchUserCondition";
      Break;
   When "QUERYNAME"
      &sClassName = "QueryNameCondition";
      Break;
   When "BLANKPAGE"
      &sClassName = "BlankPageCondition";
      Break;
   When "SESSKICKED"
      &sClassName = "PsftSessionKickedOutCondition";
      Break;
   When "MALFORMURL"
      &sClassName = "MalformedURLCondition";
      Break;
   When "SAMLPRINC"
      &sClassName = "SAMLPrincipalCondition";
      Break;
   When "HTTPATTR"
      &sClassName = "HttpSessionAttributeExistsCondition";
      Break;
   When "DATETIME"
      &sClassName = "DateTimeCondition";
      Break;
   When "SUBMITBTN"
      &sClassName = "SubmitButtonParameterCondition";
      Break;
   When-Other
      &sClassName = Proper(&condition) | "Condition";
      Break;
   End-Evaluate;
   Return &sClassName;
End-Function;

/*
  Function to insert the non nps actions associated with a rule based on the id passed. 
*/
Function addNonNPSAction(&rsActions As Rowset, &ruleNode As XmlNode, &ruleId As string, &nCurrent As integer) Returns boolean

   Local string &action, &actionId, &logId, &logName, &redirectUrl, &parmName;
   Local XmlNode &actionNode, &paramNode, &textNode;

   &actionNode = &ruleNode.AddElement("action");
   Local Record &rAction = &rsActions(&nCurrent).GetRecord(1);
   &actionId = &rAction.GetField(Field.GS_ACTION_ID).Value;
   &action = &rAction.GetField(Field.GS_FW_ACTION).Value;

   &actionNode.AddAttribute("name", &actionId);
   &actionNode.AddAttribute("rulename", &ruleId);
   &actionNode.AddAttribute("descr", &rAction.GetField(Field.DESCR).Value);

   REM Note that some actions override the class name, 
          so we don't set the node class attribute yet;
   Local string &clsName = getActionClass(&action);

   Evaluate &action
   When "RED"
      /*Rebuilding the splitted long field value */
      &redirectUrl = RebuildFWActValue(&actionId);
      If None(&redirectUrl) Then
         &redirectUrl = &rAction.GetField(Field.GS_MSG_DESCR).Value;
      End-If;
      If All(&redirectUrl) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "URL");
         &textNode = &paramNode.AddText(&redirectUrl);
      End-If;
      Break;
   When "BLG"
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      Local string &logToBrowser = &rAction.GetField(Field.PARAM_NAME).Value;
      &textNode = &paramNode.AddText(&logToBrowser);
      Break;
   When "BLK"
      /*Rebuilding the splitted long field value */
      Local string &blkMsg = RebuildFWActValue(&actionId);
      If None(&blkMsg) Then
         &blkMsg = &rAction.GetField(Field.GS_MSG_DESCR).Value;
      End-If;

      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&blkMsg);

      Local string &statusCode = &rAction.GetField(Field.GS_FW_HTTP_CODE).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&statusCode);
      Break;
   When "LOG"
      &logId = &rAction.GetField(Field.GS_LOG_ID).Value;
      &logName = &rAction.GetField(Field.GS_LOG_FILENAME).Value;
      If All(&logId) Or
            All(&logName) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("class", "String");
         &textNode = &paramNode.AddText(&logId);

         If All(&logName) Then
            Local string &logPattern = &rAction.GetField(Field.GS_LOG_PATTERN).Value;

            &paramNode = &actionNode.AddElement("parameter");
            &paramNode.AddAttribute("class", "String");
            &textNode = &paramNode.AddText(&logName);

            &paramNode = &actionNode.AddElement("parameter");
            &paramNode.AddAttribute("class", "String");
            &textNode = &paramNode.AddText(&logPattern);

            Local string &logRoll = &rAction.GetField(Field.GS_LOG_ROLL_OPT).Value;
            &paramNode = &actionNode.AddElement("parameter");
            &paramNode.AddAttribute("class", "String");
            &textNode = &paramNode.AddText(&logRoll);
            Local string &logDisableRollOverMessage = &rAction.GetField(Field.GS_DIS_ROLL_MSG).Value;
            &paramNode = &actionNode.AddElement("parameter");
            &paramNode.AddAttribute("class", "String");
            &textNode = &paramNode.AddText(&logDisableRollOverMessage);
         End-If;

         Local Rowset &rsAppenders = CreateRowset(Record.GS_FW_APNDR_TBL);
         Local integer &nCntAppenders, &nCurrAppender;
         &nCntAppenders = &rsAppenders.Fill("WHERE GS_ACTION_ID=:1", &actionId);

         For &nCurrAppender = 1 To &nCntAppenders
            Local XmlNode &appendersNode = &actionNode.AddElement("appenders");
            Local Record &rAppender = &rsAppenders(&nCurrAppender).GetRecord(1);
            Local string &appenderCfg = &rAppender.GetField(Field.GS_LOG_APPNDER_XML).Value;
            Local string &appenderName = &actionId | "_appender_" | &nCurrAppender;
            &appendersNode.AddAttribute("name", &appenderName);
            &appendersNode.AddAttribute("class", "String");
            &textNode = &appendersNode.AddText(&appenderCfg);
         End-For;

      End-If;
      Break;
   When "SET"
      &parmName = &rAction.GetField(Field.PARAM_NAME).Value;
      &logId = &rAction.GetField(Field.GS_LOG_ID).Value;

      rem request paramaeter;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&parmName);
      rem session variable name;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&logId);
      Break;
   When "DEL"
      &parmName = &rAction.GetField(Field.PARAM_NAME).Value;

      rem session variable name;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&parmName);
      Break;
   When "GST"
      Local string &user = &rAction.GetField(Field.OPRID).Value;
      Local string &pswd = &rAction.GetField(Field.OPERPSWD).Value;
      If None(&pswd) Then
         &pswd = Decrypt("", &rAction.GetField(Field.GS_OPER_PSWD).Value);
      End-If;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&user);

      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&pswd);
      Break;
   When "RQH"
   When "RSH"
      Local Record &fwHdr = CreateRecord(Record.GS_FW_ACT_HDR);
      &fwHdr.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &fwHdr.SelectByKey() Then

         LogIt("No HTTP Header row found for action " | &actionId);

         rem Continue;
         Return False;
      End-If;

      If &fwHdr.GetField(Field.GS_FW_HDR_TYPE).Value = "C" Then
         If &action = "RQH" Then
            &clsName = "SetRequestCookieAction";
         Else
            &clsName = "SetResponseCookieAction";
         End-If;
      End-If;

      Local string &hdrName = &fwHdr.GetField(Field.GS_FW_HDR_NAME).Value;
      /* Rebuilding the splitted long field value */
      Local string &hdrVal = RebuildFWActValue(&actionId);
      If None(&hdrVal) Then
         &hdrVal = &fwHdr.GetField(Field.GS_FW_HDR_VALUE).Value;
      End-If;

      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&hdrName);

      Local boolean &suppressHeader = (&fwHdr.GetField(Field.GS_FW_HDR_DEL).Value = "Y");
      If Not &suppressHeader Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("class", "String");
         &textNode = &paramNode.AddText(&hdrVal);

         Local boolean &overwrite = (&fwHdr.GetField(Field.GS_FW_HDR_EDIT).Value = "Y");
         &paramNode.AddAttribute("overwrite", String(&overwrite));
      End-If;
      Break;
   When "SRV" /*Save Response Value*/
      Local Record &SRVRec = CreateRecord(Record.GS_FW_ACT_SRV);
      &SRVRec.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &SRVRec.SelectByKey() Then
         LogIt("No Save Response Value row found for action " | &actionId);
         Return False;
      End-If;

      Local string &SRVType = &SRVRec.GetField(Field.GS_SRV_TYPE).Value;
      Local string &SRVClassName = &SRVRec.GetField(Field.GS_CLASS_NAME).Value;
      Local string &SRVElemName = &SRVRec.GetField(Field.GS_ELEM_NAME).Value;
      Local string &SRVFilePath = &SRVRec.GetField(Field.GS_RSA_FILEPATH).Value;
      Local string &SRVAttrName = &SRVRec.GetField(Field.GS_UM_ATTRNAME).Value;
      Local string &SRVElemtValue = &SRVRec.GetField(Field.GS_ELEMT_VALUE).Value;
      Local string &SRVURL = &SRVRec.GetField(Field.GS_SAML_URL).Value;

      If All(&SRVType) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "SRVType");
         &textNode = &paramNode.AddText(&SRVType);
      End-If;

      If All(&SRVClassName) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "ParentClassName");
         &textNode = &paramNode.AddText(&SRVClassName);
      End-If;

      If All(&SRVElemName) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "ParentElementName");
         &textNode = &paramNode.AddText(&SRVElemName);
      End-If;

      If All(&SRVFilePath) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "AttributePath");
         &textNode = &paramNode.AddText(&SRVFilePath);
      End-If;

      If All(&SRVAttrName) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "AttributeName");
         &textNode = &paramNode.AddText(&SRVAttrName);
      End-If;

      If All(&SRVElemtValue) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "ElementValue");
         &textNode = &paramNode.AddText(&SRVElemtValue);
      End-If;

      If All(&SRVURL) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "ReturnURL");
         &textNode = &paramNode.AddText(&SRVURL);
      End-If;
      Break;
   When "SRP" /*Save Request Parameters*/
      Local Record &SRPRec = CreateRecord(Record.GS_FW_ACT_SRPA);
      &SRPRec.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &SRPRec.SelectByKey() Then
         LogIt("No Save Request Parameters row found for action " | &actionId);
         Return False;
      End-If;

      Local string &SRPFormParams = &SRPRec.GetField(Field.GS_FORM_PARAMS).Value;
      Local string &SRPURLParams = &SRPRec.GetField(Field.GS_URL_PARAMS).Value;
      Local string &SRPHeaderNames = &SRPRec.GetField(Field.GS_HEADER_NAMES).Value;
      Local string &SRPSaveFormParams = &SRPRec.GetField(Field.GS_SAVE_FORMPARAMS).Value;
      Local string &SRPSaveURLParams = &SRPRec.GetField(Field.GS_SAVE_URL_PARAMS).Value;
      Local string &SRPSaveHeaders = &SRPRec.GetField(Field.GS_SAVE_HEADERS).Value;
      Local string &SRPExcludeFormParams = &SRPRec.GetField(Field.GS_EXC_FORM_PARMS).Value;
      Local string &SRPExcludeURLParams = &SRPRec.GetField(Field.GS_EXC_URL_PARMS).Value;
      Local string &SRPExcludeHeaders = &SRPRec.GetField(Field.GS_EXC_HEADERS).Value;
      Local string &SRPSaveAll = &SRPRec.GetField(Field.GS_SAVE_ALL).Value;

      If All(&SRPFormParams) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "FormParameterNames");
         &textNode = &paramNode.AddText(&SRPFormParams);
      End-If;

      If All(&SRPURLParams) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "URLParameterNames");
         &textNode = &paramNode.AddText(&SRPURLParams);
      End-If;

      If All(&SRPHeaderNames) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "HeaderNames");
         &textNode = &paramNode.AddText(&SRPHeaderNames);
      End-If;

      If All(&SRPSaveFormParams) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "SaveAllFormParameters");
         &textNode = &paramNode.AddText(&SRPSaveFormParams);
      End-If;

      If All(&SRPSaveURLParams) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "SaveAllURLParameters");
         &textNode = &paramNode.AddText(&SRPSaveURLParams);
      End-If;

      If All(&SRPSaveHeaders) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "SaveAllHeaders");
         &textNode = &paramNode.AddText(&SRPSaveHeaders);
      End-If;

      If All(&SRPExcludeFormParams) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "ExcludeFormParameters");
         &textNode = &paramNode.AddText(&SRPExcludeFormParams);
      End-If;

      If All(&SRPExcludeURLParams) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "ExcludeURLParameters");
         &textNode = &paramNode.AddText(&SRPExcludeURLParams);
      End-If;

      If All(&SRPExcludeHeaders) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "ExcludeHeaders");
         &textNode = &paramNode.AddText(&SRPExcludeHeaders);
      End-If;

      If All(&SRPSaveAll) Then
         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("name", "SaveAllFields");
         &textNode = &paramNode.AddText(&SRPSaveAll);
      End-If;

      Break;
   When "PFR"
      /*Rebuilding the splitted long field value */
      Local string &replaceTxt = RebuildFWActValue(&actionId);
      If None(&replaceTxt) Then
         &replaceTxt = &rAction.GetField(Field.GS_MSG_DESCR).Value;
      End-If;

      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&replaceTxt);
      Break;
   When "QFR"
      /*Rebuilding the splitted long field value */
      Local string &qryReplaceTxt = RebuildFWActValue(&actionId);
      If None(&qryReplaceTxt) Then
         &qryReplaceTxt = &rAction.GetField(Field.GS_MSG_DESCR).Value;
      End-If;

      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&qryReplaceTxt);
      Break;
   When "SFR" /* Added for Search Field Masking */
      /*Rebuilding the splitted long field value */
      Local string &srcReplaceTxt = RebuildFWActValue(&actionId);
      If None(&srcReplaceTxt) Then
         &srcReplaceTxt = &rAction.GetField(Field.GS_MSG_DESCR).Value;
      End-If;

      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&srcReplaceTxt);
      Break;
   When "RPP"
      Local string &rqstProfileID = &rAction.GetField(Field.PARAM_NAME).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&rqstProfileID);
      Break;
   When "2FA"
      Local Record &twoFArec = CreateRecord(Record.GS_FW_ACT_2FA);
      &twoFArec.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &twoFArec.SelectByKey() Then

         LogIt("No MFA row found for action " | &actionId);

         Return False;
      End-If;

      Local string &twoFAProv = &twoFArec.GetField(Field.GS_FW_2FA_PROV).Value;
      Local string &twoFAAppID = &twoFArec.GetField(Field.GS_FW_2FA_PROV_ID).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&twoFAProv);
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&twoFAAppID);
      Break;
   When "SML"
      Local Record &samlRec = CreateRecord(Record.GS_FW_ACT_SAML);
      &samlRec.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &samlRec.SelectByKey() Then

         LogIt("No SAML/ADFS row found for action " | &actionId);

         Return False;
      End-If;

      Local string &samlID = &samlRec.GetField(Field.GS_SAML_IDP_ID).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&samlID);

      Local string &logoutURL = "";
      SQLExec("SELECT GS_SAML_LGO_URL FROM PS_GS_SAML_IDP_TBL WHERE GS_SAML_IDP_ID = :1", &samlID, &logoutURL);
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&logoutURL);

      Local string &failedMappingURL = "";
      Local string &failedMappingType = "FLM";
      SQLExec("SELECT GS_SAML_URL FROM PS_GS_SAML_URL_TBL WHERE GS_SAML_IDP_ID = :1 AND GS_SAML_URL_TYPE = :2", &samlID, &failedMappingType, &failedMappingURL);

      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&failedMappingURL);

      Break;
   When "SLO" /* SAML Logout Action */
      Local Record &sloRec = CreateRecord(Record.GS_FW_ACT_SAML);
      &sloRec.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &sloRec.SelectByKey() Then

         LogIt("No SAML/ADFS row found for action " | &actionId);

         Return False;
      End-If;

      Local string &sloID = &sloRec.GetField(Field.GS_SAML_IDP_ID).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&sloID);

      Local string &sloURL = "";
      SQLExec("SELECT GS_SAML_LGO_URL FROM PS_GS_SAML_IDP_TBL WHERE GS_SAML_IDP_ID = :1", &sloID, &sloURL);
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&sloURL);

      Break;

   When "JWT" /* OIDC Authentication Action */
      Local Record &oidcRec = CreateRecord(Record.GS_FW_ACT_JWT);
      &oidcRec.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &oidcRec.SelectByKey() Then
         LogIt("No OIDC row found for action " | &actionId);
         Return False;
      End-If;

      Local string &oidcID = &oidcRec.GetField(Field.GS_OIDC_IDP_ID).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&oidcID);

      Local string &oidcLogoutURL = "";
      SQLExec("SELECT GS_OIDC_LOGOUT_URL FROM PS_GS_OIDC_IDP_CFG WHERE GS_OIDC_IDP_ID = :1", &oidcID, &oidcLogoutURL);
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&oidcLogoutURL);

      Local string &oidcFailedMappingURL = "";
      Local string &oidcFailedMappingType = "FLM";
      SQLExec("SELECT GS_OIDC_URL FROM PS_GS_OIDC_URL_TBL WHERE GS_OIDC_IDP_ID = :1 AND GS_OIDC_URL_TYPE = :2", &oidcID, &oidcFailedMappingType, &oidcFailedMappingURL);

      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&oidcFailedMappingURL);

      Break;

   When "KRB"
      Local Record &kerbRec = CreateRecord(Record.GS_FW_ACT_KERB);
      &kerbRec.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &kerbRec.SelectByKey() Then

         LogIt("No Kerberos row found for action " | &actionId);

         Return False;
      End-If;

      Local string &kerbCfgID = &kerbRec.GetField(Field.GS_KERB_CFG_ID).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&kerbCfgID);

      Local string &kerbLogoutURL = "";
      SQLExec("SELECT GS_KERB_LGO_URL FROM PS_GS_KERB_CFG_TBL WHERE GS_KERB_CFG_ID = :1", &kerbCfgID, &kerbLogoutURL);
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&kerbLogoutURL);

      Local string &kerbFailedMappingURL = "";
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&failedMappingURL);

      Break;
   When "STI"
      Local Record &timeoutsRec = CreateRecord(Record.GS_FW_TIMEOUTS);
      &timeoutsRec.GetField(Field.GS_ACTION_ID).Value = &actionId;
      If Not &timeoutsRec.SelectByKey() Then

         LogIt("No session timeout row found for action " | &actionId);

         Return False;
      End-If;

      Local string &sessTimeout = &timeoutsRec.GetField(Field.GS_FW_SESS_TIMEOUT).Value;
      Local string &warnTimeout = &timeoutsRec.GetField(Field.GS_FW_WARN_TIMEOUT).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&sessTimeout);
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&warnTimeout);
      Break;
   When "HAO" /* Added for HTML Add-on Action */
      /*Rebuilding the splitted long field value */
      Local string &htmlAddOnReplaceTxt = RebuildFWActValue(&actionId);
      If None(&htmlAddOnReplaceTxt) Then
         &htmlAddOnReplaceTxt = &rAction.GetField(Field.GS_MSG_DESCR).Value;
      End-If;

      Local string &htmlActionLoc = &rAction.GetField(Field.GS_ACTION_LOCATION).Value;
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&htmlAddOnReplaceTxt);
      &paramNode = &actionNode.AddElement("parameter");
      &paramNode.AddAttribute("class", "String");
      &textNode = &paramNode.AddText(&htmlActionLoc);

      Break;
   When "LDB"
      Local string &logRecName = &rAction.GetField(Field.GS_RECNAME).Value;
      If All(&logRecName) Then
         &logPattern = &rAction.GetField(Field.GS_LOG_PATTERN).Value;
         &sDBConfigID = &rAction.GetField(Field.GS_DBCNFG_ID).Value;

         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("class", "String");
         &textNode = &paramNode.AddText(&logRecName);

         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("class", "String");
         &textNode = &paramNode.AddText(&logPattern);

         &paramNode = &actionNode.AddElement("parameter");
         &paramNode.AddAttribute("class", "String");
         &textNode = &paramNode.AddText(&sDBConfigID);
      End-If;
      Break;
   End-Evaluate;

   &actionNode.AddAttribute("class", &clsName);

   Return True;
End-Function;

Function makeGroupNode(&ruleNode As XmlNode, &oper As string, &group As string, &descr As string) Returns XmlNode
   Local XmlNode &groupNode = &ruleNode.AddElement("group");
   If &oper = "NOT" Then
      &groupNode.AddAttribute("class", "AND");
      &groupNode.AddAttribute("name", &group | "_EX");
   Else
      &groupNode.AddAttribute("class", "OR");
      &groupNode.AddAttribute("name", &group);
   End-If;
   &groupNode.AddAttribute("descr", &descr);
   Return &groupNode;
End-Function;

Function makeParameterNode(&parentNode As XmlNode, &cls As string, &txt As string) Returns XmlNode
   Local XmlNode &paramNode = &parentNode.AddElement("parameter");
   &paramNode.AddAttribute("class", &cls);

   Local XmlNode &textNode = &paramNode.AddText(&txt);
   Return &paramNode;
End-Function;

Function makeListParameter(&oper As string) Returns string
   If &oper = "NOT" Then
      Return "NOTINLIST";
   Else
      Return "INLIST";
   End-If;
End-Function;

Function makeRangeParameter(&oper As string) Returns string
   If &oper = "NOT" Then
      Return "NOTBETWEEN";
   Else
      Return "BETWEEN";
   End-If;
End-Function;

Function makeConditionNode(&groupNode As XmlNode, &cls As string, &id As string, &listOrRange As string) Returns XmlNode
   Local XmlNode &conditionNode = &groupNode.AddElement("condition");
   &conditionNode.AddAttribute("class", &cls);
   &conditionNode.AddAttribute("id", &id);
   Local string &parmCls = "ConditionOperator";
   Local XmlNode &paramNode = makeParameterNode(&conditionNode, &parmCls, &listOrRange);
   Return &conditionNode;
End-Function;

Function makeListConditionNode(&groupNode As XmlNode, &cls As string, &id As string, &oper As string) Returns XmlNode
   Return makeConditionNode(&groupNode, &cls, &id, makeListParameter(&oper));
End-Function;

Function makeRangeConditionNode(&groupNode As XmlNode, &cls As string, &id As string, &oper As string) Returns XmlNode
   Return makeConditionNode(&groupNode, &cls, &id, makeRangeParameter(&oper));
End-Function;

Function addCondition(&ruleNode As XmlNode, &condGrp As string, &condDescr As string)
   Local Rowset &rsConditions = CreateRowset(Record.GS_CONTGRP_ITEM);
   Local XmlNode &conditionNode, &paramNode, &textNode, &groupNode;
   Local integer &nCnt, &nCurrent;
   Local Record &rCond;
   Local string &lastType, &lastOper;
   Local string &currentType, &currentOper;
   Local boolean &isDayOfWeekCondition;

   Local string &grpHdrContType;
   SQLExec("SELECT GS_CONTENT_TYPE FROM PS_GS_CONTGRP_HDR WHERE GS_CONTENT_GRP = :1", &condGrp, &grpHdrContType);

   &nCnt = &rsConditions.Fill("WHERE GS_CONTENT_GRP=:1 ORDER BY GS_FW_COND_OPER, GS_ITEM_TYPE", &condGrp);
   For &nCurrent = 1 To &nCnt
      &rCond = &rsConditions(&nCurrent).GetRecord(1);

      &currentOper = &rCond.GS_FW_COND_OPER.Value;
      If &currentOper <> &lastOper Then
         &groupNode = makeGroupNode(&ruleNode, &currentOper, &condGrp, &condDescr);
         &lastOper = &currentOper;
      End-If;

      &currentType = &rCond.GS_ITEM_TYPE.Value;
      If &currentType <> &lastType Then
         Local string &condClass = getConditionClass(&currentType);
         If &condClass = "DayOfWeekCondition" Then
            &isDayOfWeekCondition = True;
         End-If;

         &conditionNode = makeListConditionNode(&groupNode, &condClass, &condGrp, &currentOper);

         Local boolean &isBrowserURL = (&currentType = "MENU_BRW" Or
            &currentType = "COMP_BRW" Or
            &currentType = "PAGE_BRW");
         If &isBrowserURL Then
            &conditionNode.AddAttribute("browserurl", "true");
         End-If;

         &lastType = &currentType;
      End-If;

      Local string &parmCls = "String";
      If &isDayOfWeekCondition Then
         &parmCls = "DayOfWeek";
      End-If;

      Local string &parmVal = &rCond.GS_ITEM_VALUE.Value;
      &paramNode = makeParameterNode(&conditionNode, &parmCls, &parmVal);

      Local string &longValue = &rCond.GS_FW_COND_LONG.Value;
      /*Rebuilding the splitted long field value */
      Local string &retSpltCondVal;
      If &grpHdrContType = "HTP" And
            All(&longValue) Then
         &retSpltCondVal = RebuildFwHttpHdrCondValue(&condGrp, &currentType, &parmVal);
         If All(&retSpltCondVal) Then
            &longValue = &retSpltCondVal;
         End-If;
      End-If;
      If All(&longValue) Then
         &paramNode = makeParameterNode(&conditionNode, &parmCls, &longValue);
      End-If;

   End-For;
End-Function;

Function addTwoFactorCondition(&ruleNode As XmlNode, &provType As string, &provID As string, &provDesc As string)
   Local string &condClass;
   Local Record &twoFARec;
   Local Field &provFld;

   Evaluate &provType
   When "DUO"
      &condClass = "DuoChallengeRequiredCondition";
      &twoFARec = CreateRecord(Record.GS_DUO_APP_TBL);
      &provFld = &twoFARec.GetField(Field.GS_DUO_APP_ID);
      Break;
   When-Other

      Error ("Invalid MFA provider type: " | &provType);

   End-Evaluate;

   &provFld.Value = &provID;
   &twoFARec.SelectByKey();

   Local string &condOper = "EQ";
   Local XmlNode &groupNode = makeGroupNode(&ruleNode, &condOper, &provID, &provDescr);

   Local XmlNode &conditionNode = makeListConditionNode(&groupNode, &condClass, &provID, &condOper);

   Local string &parmCls = "String";
   Local XmlNode &paramNode = makeParameterNode(&conditionNode, &parmCls, &provType);

   &paramNode = makeParameterNode(&conditionNode, &parmCls, &provID);
End-Function;

Function addIScriptCondition(&ruleNode As XmlNode, &condGrp As string, &condDescr As string)
   Local Rowset &rsConditions = CreateRowset(Record.GS_ISCRIPT_GRP);
   Local XmlNode &conditionNode, &paramNode, &groupNode;
   Local integer &nCnt, &nCurrent;
   Local Record &rCond;
   Local string &lastType, &lastOper;
   Local string &currentType, &currentOper;
   Local string &condClass = "IScriptCondition";

   &nCnt = &rsConditions.Fill("WHERE GS_CONTENT_GRP=:1 ORDER BY GS_FW_COND_OPER, GS_ITEM_TYPE", &condGrp);
   For &nCurrent = 1 To &nCnt
      &rCond = &rsConditions(&nCurrent).GetRecord(1);

      &currentOper = &rCond.GS_FW_COND_OPER.Value;
      If &currentOper <> &lastOper Then
         &groupNode = makeGroupNode(&ruleNode, &currentOper, &condGrp, &condDescr);
         &lastOper = &currentOper;
      End-If;

      &currentType = &rCond.GS_ITEM_TYPE.Value;
      If &currentType <> &lastType Then
         &conditionNode = makeListConditionNode(&groupNode, &condClass, &condGrp, &currentOper);
         &lastType = &currentType;
      End-If;

      Local string &parmCls = "RecordFieldEventFunction";
      Local string &parmVal = &rCond.MENUNAME.Value | "." | &rCond.GS_WEBLIB_FUNCTION.Value;
      &paramNode = makeParameterNode(&conditionNode, &parmCls, &parmVal);
   End-For;
End-Function;

Function addIPAddressCondition(&ruleNode, &condGrp, &condDescr)
   Local Rowset &rsConditions = CreateRowset(Record.GS_IPADDR_GRP);
   Local XmlNode &conditionNode, &paramNode, &textNode, &groupNode;
   Local integer &nCnt, &nCurrent;
   Local number &nIPAddrValFrom, &nIPAddrValTo;
   Local string &nHEXAddrValFrom, &nHEXAddrValTo;
   Local Record &rCond;
   Local string &lastOper;
   Local string &currentOper;
   Local string &condClass = "IPRangeCondition";
   Local string &parmCls = "InetAddressRange";
   Local string &parmVal;

   &nCnt = &rsConditions.Fill("WHERE GS_CONTENT_GRP=:1 ORDER BY GS_FW_COND_OPER, GS_ITEM_TYPE", &condGrp);
   For &nCurrent = 1 To &nCnt
      &rCond = &rsConditions(&nCurrent).GetRecord(1);

      &currentOper = &rCond.GS_FW_COND_OPER.Value;
      If &currentOper <> &lastOper Then
         &groupNode = makeGroupNode(&ruleNode, &currentOper, &condGrp, &condDescr);
         &lastOper = &currentOper;
      End-If;

      Local boolean &isRange;
      If &rCond.GS_IP_ADDR_TYPE.Value = "V4" Then /*IPv4*/
         &nIPAddrValFrom = &rCond.GS_IPADDR_INTEGER.Value;
         &nIPAddrValTo = &rCond.GS_IPADDR_INT_TO.Value;
         &isRange = (&nIPAddrValFrom <> &nIPAddrValTo);
      Else /*IPv6*/
         &nHEXAddrValFrom = &rCond.GS_HEX_ADDR.Value;
         &nHEXAddrValTo = &rCond.GS_HEX_ADDR_TO.Value;
         &isRange = (&nHEXAddrValFrom <> &nHEXAddrValTo);
      End-If;

      If &isRange Then
         &conditionNode = makeRangeConditionNode(&groupNode, &condClass, &condGrp, &currentOper);
         If &rCond.GS_IP_ADDR_TYPE.Value = "V4" Then /*IPv4*/
            &parmVal = &rCond.GS_IPADDR_INTEGER.Value | "/" | &rCond.GS_IPADDR_INT_TO.Value;
         Else /*IPv6*/
            &parmVal = &rCond.GS_HEX_ADDR.Value | "/" | &rCond.GS_HEX_ADDR_TO.Value;
         End-If;
      Else
         &conditionNode = makeListConditionNode(&groupNode, &condClass, &condGrp, &currentOper);
         If &rCond.GS_IP_ADDR_TYPE.Value = "V4" Then /*IPv4*/
            &parmVal = &rCond.GS_IPADDR_INTEGER.Value;
         Else /*IPv6*/
            &parmVal = &rCond.GS_HEX_ADDR.Value;
         End-If;
      End-If;
      If &rCond.GS_IP_ADDR_TYPE.Value = "V6" Then /*IPv6*/
         &parmCls = "Inet6AddressRange";
      End-If;
      &paramNode = makeParameterNode(&conditionNode, &parmCls, &parmVal);

   End-For;
End-Function;

Function makeAppClass(&rCond As Record) Returns string
   Local string &appClass = &rCond.PACKAGEROOT.Value | ":";
   If All(&rCond.QUALIFYPATH.Value) Then
      &appClass = &appClass | &rCond.QUALIFYPATH.Value | ":";
   End-If;
   Return &appClass | &rCond.GS_APPCLASSID.Value;
End-Function;

Function addUserDataCondition(&ruleNode As XmlNode, &condGrp As string, &condDescr As string)
   Local Rowset &rsConditions = CreateRowset(Record.GS_DATCOND_ITMS);
   Local XmlNode &conditionNode, &paramNode, &textNode, &groupNode;
   Local string &sPackage, &sPath, &sClass;
   Local integer &nCnt, &nCurrent;
   Local Record &rCond;
   Local string &lastType, &lastOper;
   Local string &currentType, &currentOper, &condClass;
   Local boolean &isSystemCond;

   &nCnt = &rsConditions.Fill("WHERE GS_CONTENT_GRP=:1 ORDER BY GS_FW_COND_OPER, GS_ITEM_TYPE", &condGrp);
   For &nCurrent = 1 To &nCnt
      &rCond = &rsConditions(&nCurrent).GetRecord(1);

      &isSystemCond = (&rCond.GS_FW_DCSCOPE.Value = "S");
      If &isSystemCond Then
         &condClass = "SystemDataCondition";
      Else
         &condClass = "UserDataCondition";
      End-If;

      &currentOper = &rCond.GS_FW_COND_OPER.Value;
      If &currentOper <> &lastOper Then
         &groupNode = makeGroupNode(&ruleNode, &currentOper, &condGrp, &condDescr);
         &lastOper = &currentOper;
      End-If;

      &currentType = &rCond.GS_ITEM_TYPE.Value;
      If &currentType <> &lastType Then
         &conditionNode = makeListConditionNode(&groupNode, &condClass, &condGrp, &currentOper);
         &lastType = &currentType;
      End-If;

      Local string &appClass = makeAppClass(&rCond);
      Local string &parmCls = "String";
      &paramNode = makeParameterNode(&conditionNode, &parmCls, &appClass);

   End-For;
End-Function;

Function checkForRulesetAddOn(&ruleId As string) Returns Rowset

   Local Rowset &rsRules;
   Local string &addOnCheck;
   SQLExec("SELECT 'X' FROM PS_GS_RULESET_ADON WHERE  GS_RULESET_ID =:1 AND GS_ACTIVE_FLG  = 'Y'", &ruleId, &addOnCheck);
   Local boolean &addOnExists = (&addOnCheck = "X");

   If Not &addOnExists Then
      &rsRules = CreateRowset(Record.GS_FW_ITEMS);
   Else
      &rsRules = CreateRowset(Record.GS_ITMS_ADON_VW);
   End-If;

   Return &rsRules;

End-Function;

Function checkForAddOns(&rsConditions As Rowset, &rsFieldConditions As Rowset, &fldCondRecord As string, &condGrp As string, &nFldCount As integer)

   Local string &addOnCheck;
   SQLExec("SELECT 'X' FROM PS_GS_COND_ADDON WHERE  GS_CONTENT_GRP =:1 AND GS_ACTIVE_FLG  = 'Y'", &condGrp, &addOnCheck);
   Local boolean &addOnExists = (&addOnCheck = "X");

   If Not &addOnExists Then
      &rsConditions = CreateRowset(Record.GS_CONTGRP_ITEM);
      &rsFieldConditions = CreateRowset(@("RECORD." | &fldCondRecord));
      &nFldCount = &rsFieldConditions.Fill(FetchSQL(SQL.GS_FW_FIELD_COND_WHERE), &condGrp);
   Else
      &rsConditions = CreateRowset(Record.GS_CND_ADON_VW);
      &rsFieldConditions = CreateRowset(Record.GS_CND_FLD_ADON);
      &nFldCount = &rsFieldConditions.Fill("WHERE GS_CONTENT_GRP = :1 AND GS_FW_COND_LONG IS NOT NULL AND GS_ACTIVE_FLG = 'N'", &condGrp);
   End-If;

End-Function;

Function addPageFieldCondition(&ruleNode As XmlNode, &condGrp As string, &condDescr As string)

   Local Rowset &rsConditions, &rsFieldConditions;
   Local XmlNode &conditionNode, &paramNode, &groupNode;
   Local integer &nCnt, &nCurrent, &nFldCount;
   Local Record &rCond;
   Local string &lastType, &lastOper;
   Local string &currentType, &currentOper;
   Local string &condClass;
   Local string &parmCls = "String";
   Local string &parmVal, &longVal;

   rem field condition to data to match against;
   checkForAddOns(&rsConditions, &rsFieldConditions, "GS_FLDCOND_ITMS", &condGrp, &nFldCount);
   &nCnt = &rsConditions.Fill("WHERE GS_CONTENT_GRP = :1 ORDER BY GS_FW_COND_OPER, GS_ITEM_TYPE", &condGrp);

   For &nCurrent = 1 To &nCnt
      &rCond = &rsConditions(&nCurrent).GetRecord(1);

      &currentOper = &rCond.GS_FW_COND_OPER.Value;
      If &currentOper <> &lastOper Then
         &groupNode = makeGroupNode(&ruleNode, &currentOper, &condGrp, &condDescr);
         &lastOper = &currentOper;
      End-If;

      &currentType = &rCond.GS_ITEM_TYPE.Value;
      If &currentType <> &lastType Then
         &condClass = getConditionClass(&currentType);
         &conditionNode = makeListConditionNode(&groupNode, &condClass, &condGrp, &currentOper);
         &lastType = &currentType;
      End-If;

      &parmVal = &rCond.GS_ITEM_VALUE.Value;
      &paramNode = makeParameterNode(&conditionNode, &parmCls, &parmVal);

      If &nFldCount >= &nCurrent Then
         &rCond = &rsFieldConditions(&nCurrent).GetRecord(1);
         &longVal = &rCond.GS_FW_COND_LONG.Value;
         If All(&longVal) Then
            &paramNode = makeParameterNode(&conditionNode, &parmCls, &longVal);

            rem let the server code know we have a field value we're matching against;
            &paramNode.AddAttribute("datamatchvalue", "true");
         End-If;
      End-If;
   End-For;
End-Function;

