Function addDateTimeCondition(&ruleNode, &condGrp, &condDescr)
   Local Rowset &rsConditions = CreateRowset(Record.GS_DTTMCOND_GRP);
   Local XmlNode &conditionNode, &paramNode, &textNode, &groupNode;
   Local integer &nCnt, &nCurrent;
   Local string &sDttmValFrom, &sDttmValTo;
   Local Record &rCond;
   Local string &lastOper;
   Local string &currentOper;

   Local string &condClass = "DateTimeCondition";
   Local string &parmCls = "DateTime";
   Local string &parmVal;

   &nCnt = &rsConditions.Fill("WHERE GS_CONTENT_GRP=:1 ORDER BY GS_FW_COND_OPER, GS_ITEM_TYPE", &condGrp);


   For &nCurrent = 1 To &nCnt
      &rCond = &rsConditions(&nCurrent).GetRecord(1);

      &currentOper = &rCond.GS_FW_COND_OPER.Value;
      If &currentOper <> &lastOper Then
         &groupNode = makeGroupNode(&ruleNode, &currentOper, &condGrp, &condDescr);
         &lastOper = &currentOper;
      End-If;
      REM  &sDttmValFrom = DateTimeToLocalizedString(&rCond.FROM_DTTM.Value, "dd/MM/yyyy hh:mm:ss aaa");
      REM   &sDttmValTo = DateTimeToLocalizedString(&rCond.TO_DTTM.Value, "dd/MM/yyyy hh:mm:ss aaa");

      &sDttmValFrom = DateTimeToLocalizedString(DateTime6(Year(&rCond.FROM_DT.Value), Month(&rCond.FROM_DT.Value), Day(&rCond.FROM_DT.Value), &rCond.GS_FROM_TIME_HRS.Value, &rCond.GS_FROM_TIME_MIN.Value, 0), "dd/MM/yyyy hh:mm:ss aaa");
      &sDttmValTo = DateTimeToLocalizedString(DateTime6(Year(&rCond.TO_DT.Value), Month(&rCond.TO_DT.Value), Day(&rCond.TO_DT.Value), &rCond.GS_TO_TIME_HRS.Value, &rCond.GS_TO_TIME_MIN.Value, 0), "dd/MM/yyyy hh:mm:ss aaa");


      Local boolean &isRange = (&sDttmValFrom <> &sDttmValTo);

      If &isRange Then
         &conditionNode = makeRangeConditionNode(&groupNode, &condClass, &condGrp, &currentOper);
         &parmVal = &sDttmValFrom | "-" | &sDttmValTo;
      Else
         &conditionNode = makeListConditionNode(&groupNode, &condClass, &condGrp, &currentOper);
         &parmVal = &sDttmValFrom;
      End-If;
      &paramNode = makeParameterNode(&conditionNode, &parmCls, &parmVal);

   End-For;
End-Function;

Function addConditions(&rsRules As Rowset, &ruleNode As XmlNode, &id As string)
   Local Rowset &rsConditions = CreateRowset(Record.GS_RULE_COND_VW);
   Local Record &rCond;
   Local string &condGrp, &condType, &condDescr;
   Local integer &nCntConds, &nCurCond;
   &nCntConds = &rsConditions.Fill("WHERE GS_FW_RULE_ID = :1", &id);
   For &nCurCond = 1 To &nCntConds
      &rCond = &rsConditions(&nCurCond).GetRecord(1);
      &condGrp = &rCond.GetField(Field.GS_CONTENT_GRP).Value;
      &condType = &rCond.GetField(Field.GS_CONTENT_TYPE).Value;
      &condDescr = &rCond.GetField(Field.DESCR).Value;
      Evaluate &condType
      When "PG"
      When "HTP"
      When "SML"
      When "SMP"
      When "URL"
      When "USR"
      When "SUB"
      When "NV"
         addCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "FLD"
         addPageFieldCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "QRY"
         addQueryFieldCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "SRC"
         addSearchFieldCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "ISC"
         addIScriptCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "IP"
         addIPAddressCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "DAT"
         addUserDataCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "TXT"
         addResponseTextCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "DTM"
         addDateTimeCondition(&ruleNode, &condGrp, &condDescr);
         Break;
      When "DUO"
      When "RSA"
      When "SFN"
         addTwoFactorCondition(&ruleNode, &condType, &condGrp, &condDescr);
         Break;
      End-Evaluate;
   End-For;
End-Function;

