/*This function is adding the header in the rules tag, like ruleset attribute*/
/*Function addPolicySetHeader(&rsNode As XmlNode, &isNested As boolean, &recRuleset As Record, &ruleId As string)*/
Function addPolicySetHeader(&rsNode As XmlNode, &strPolSetType As string, &recRuleset As Record, &ruleId As string)
   Evaluate &strPolSetType
   When "M"
      &rsNode.AddAttribute("default", &recRuleset.GetField(Field.GS_FW_ACTION).Value);
      &rsNode.AddAttribute("default_html", &recRuleset.GetField(Field.GS_LOG_ID).Value);
      &rsNode.AddAttribute("ruleset", &ruleId);
      &rsNode.AddAttribute("policysettype", "master");
      Break;
   When "N"
      &rsNode.AddAttribute("ruleset", &ruleId);
      &rsNode.AddAttribute("policysettype", "nested");
      &rsNode.AddAttribute("producttype", &recRuleset.GetField(Field.GS_POLICYSET_TYPE).Value);
      Break;
   End-Evaluate;
End-Function;

/*
  Function to insert the Nested Policy Set actions associated with a rule based on the id passed. 
This fubnction is exactly replica of the addAction() function except the NPS part of the addAction().
*/
Function addNPSAction(&ruleNode As XmlNode, &ruleId As string)
   Local Rowset &rsActions = CreateRowset(Record.GS_FW_ACTION_VW);
   Local string &action, &actionId, &logId, &logName, &redirectUrl, &parmName;
   Local XmlNode &actionNode, &paramNode, &textNode;
   Local integer &nCntAction, &nCurrent;
   &nCntAction = &rsActions.Fill("WHERE GS_FW_RULE_ID=:1", &ruleId);
   For &nCurrent = 1 To &nCntAction
      If False = addNonNPSAction(&rsActions, &ruleNode, &ruleId, &nCurrent) Then
         Continue;
      End-If;
   End-For;
End-Function;

/*
This function is to add the external configuration which is saved in the GS_FW_EXT_CONF record.
This is received from the external application like A360.
This would be either a Policy having action, NPS, conditions and actions or 
a NPS having conditions and actions.
Parameter 4: should be null when invoked 1st parameter is rule noe.
*/
Function addExtConfData(&rsNode As XmlNode, &id As string, &chldNodeName As string, &removeChldNode As XmlNode) Returns boolean
   Local Rowset &rsExtConfig = CreateRowset(Record.GS_FW_EXT_CONF);
   Local string &idType = "P";
   If &removeChldNode <> Null Then
      &idType = "S";
   End-If;
   If &rsExtConfig.Fill("WHERE (GS_FW_CONF_ID = :1  AND GS_FW_CONF_TYPE = :2) AND GS_SEQNUM = (SELECT MAX(GS_SEQNUM) FROM PS_GS_FW_EXT_CONF WHERE GS_FW_CONF_ID = :3)", &id, &idType, &id) > 0 Then
      If &chldNodeName = "action" And
            Not &removeChldNode.IsNull Then
         &removeChldNode = &rsNode.RemoveChildNode(&removeChldNode);
      End-If;
      Local Record &recExtConfig = &rsExtConfig(1).GetRecord(1);
      Local string &confData = &recExtConfig.GetField(Field.GS_FW_CONF_DATA).Value;

      Local string &string1 = Char(65533);
      &confData = Substitute(&confData, &string1, "");

      Local XmlDoc &inXMLDoc = CreateXmlDoc("");
      Local boolean &ret = &inXMLDoc.ParseXmlString(&confData);
      Local array of XmlNode &chldNode = &inXMLDoc.GetElementsByTagName(&chldNodeName);

      &rsNode.AddNode(&chldNode [1]);
      Return True;
   Else
      Return False;
   End-If;
End-Function;

/*
  Function to insert the actions associated with a rule based on the id passed. 
This function is exact replica of the addRuleset() except calling a noither function in place of addAction().
This is to be done to remove the cyclic dependancy between addRuleset() and addAction().
*/
Function addNPSRuleset(&rsNode As XmlNode, &rulesetID As string)
   Local XmlNode &ruleNode;
   Local string &id, &condGrp, &condType, &condDescr;
   Local integer &nCurrent, &nCount, &nCntConds, &nCurCond;
   Local Rowset &rsRuleset = CreateRowset(Record.GS_RULESET_DEFN);
   If &rsRuleset.Fill("WHERE GS_RULESET_ID = :1", &rulesetID) > 0 Then
      Local Record &recRuleset = &rsRuleset(1).GetRecord(1);
      Local string &ruleId = &recRuleset.GetField(Field.GS_RULESET_ID).Value;
      Local string &strPolicySetType = &recRuleset.GetField(Field.GS_NEST_POLSET_FLG).Value;

      addPolicySetHeader(&rsNode, &strPolicySetType, &recRuleset, &ruleId);

      /* this is the collection node. all rules are encapsulated here */
      /* for each rule id in the collection, add a new node */
      Local Rowset &rsRules = checkForRulesetAddOn(&ruleId);
      Local Rowset &rsConditions = CreateRowset(Record.GS_RULE_COND_VW);
      Local Record &rCond;
      &nCount = &rsRules.Fill("WHERE GS_RULESET_ID = :1 AND GS_FW_POLICY_DISAB <> 'D' ORDER BY SEQNUM", &ruleId);
      Local string &lastRule;
      For &nCurrent = 1 To &nCount
         &id = &rsRules(&nCurrent).GetRecord(1).GetField(Field.GS_FW_RULE_ID).Value;
         &ruleNode = &rsNode.AddElement("rule");
         &ruleNode.AddAttribute("name", &id);
         addConditions(&rsRules, &ruleNode, &id);
         addNPSAction(&ruleNode, &id);
      End-For;
   Else
      LogIt("Policy Set " | &rulesetID | " was not found.");
   End-If;
End-Function;

/*
  Function to insert the actions associated with a rule based on the id passed. 
*/
Function addAction(&ruleNode As XmlNode, &ruleId As string)
   Local Rowset &rsActions = CreateRowset(Record.GS_FW_ACTION_VW);
   Local integer &nCntAction, &nCurrent;
   Local XmlNode &actionNode, &paramNode, &textNode;
   &nCntAction = &rsActions.Fill("WHERE GS_FW_RULE_ID=:1", &ruleId);
   rem;
   For &nCurrent = 1 To &nCntAction
      If False = addNonNPSAction(&rsActions, &ruleNode, &ruleId, &nCurrent) Then
         Continue;
      End-If;

      &actionNode = &ruleNode.FindNode("action");
      Local Record &rAction = &rsActions(&nCurrent).GetRecord(1);
      &actionId = &rAction.GetField(Field.GS_ACTION_ID).Value;
      &action = &rAction.GetField(Field.GS_FW_ACTION).Value;
      Evaluate &action
      When "NPS" /*Nested Policy Set */
         Local string &polSetID;
         SQLExec("SELECT GS_RULESET_ID FROM %Table(GS_RULESET_ACT) WHERE GS_ACTION_ID = :1", &actionId, &polSetID);
         If None(&polSetID) Then
            LogIt("No Policy Set Action row found for action " | &actionId);
            Continue;
         End-If;
         If addExtConfData(&ruleNode, &polSetID, "action", &actionNode) = False Then
            &paramNode = &actionNode.AddElement("parameter");
            &paramNode.AddAttribute("class", "String");
            &textNode = &paramNode.AddText(&polSetID);
            addNPSRuleset(&actionNode, &polSetID);
         End-If;
         Break;
      End-Evaluate;
   End-For;
End-Function;

Function addActionAddOn(&ruleNode As XmlNode, &ruleId As string)
   Local Rowset &rsActions = CreateRowset(Record.GS_RLATN_ADON_V);
   Local integer &nCntAction, &nCurrent;
   Local XmlNode &actionNode, &paramNode, &textNode;
   &nCntAction = &rsActions.Fill("WHERE GS_FW_RULE_ID=:1", &ruleId);
   rem;
   For &nCurrent = 1 To &nCntAction
      If False = addNonNPSAction(&rsActions, &ruleNode, &ruleId, &nCurrent) Then
         Continue;
      End-If;

      &actionNode = &ruleNode.FindNode("action");
      Local Record &rAction = &rsActions(&nCurrent).GetRecord(1);
      &actionId = &rAction.GetField(Field.GS_ACTION_ID).Value;
      &action = &rAction.GetField(Field.GS_FW_ACTION).Value;
      Evaluate &action
      When "NPS" /*Nested Policy Set */
         Local string &polSetID;
         SQLExec("SELECT GS_RULESET_ID FROM %Table(GS_RULESET_ACT) WHERE GS_ACTION_ID = :1", &actionId, &polSetID);
         If None(&polSetID) Then
            LogIt("No Policy Set Action row found for action " | &actionId);
            Continue;
         End-If;
         If addExtConfData(&ruleNode, &polSetID, "action", &actionNode) = False Then
            &paramNode = &actionNode.AddElement("parameter");
            &paramNode.AddAttribute("class", "String");
            &textNode = &paramNode.AddText(&polSetID);
            addNPSRuleset(&actionNode, &polSetID);
         End-If;
         Break;
      End-Evaluate;
   End-For;
End-Function;

Function addRuleset(&rsNode As XmlNode, &rulesetID As string, &isNested As boolean)
   Local XmlNode &ruleNode;
   Local string &id, &condGrp, &condType, &condDescr;
   Local integer &nCurrent, &nCount, &nCntConds, &nCurCond;

   Local Rowset &rsRuleset = CreateRowset(Record.GS_RULESET_DEFN);
   If &rsRuleset.Fill("WHERE GS_RULESET_ID = :1 ", &rulesetID) > 0 Then
      Local Record &recRuleset = &rsRuleset(1).GetRecord(1);
      Local string &ruleId = &recRuleset.GetField(Field.GS_RULESET_ID).Value;
      Local string &strPolSetType = &recRuleset.GetField(Field.GS_NEST_POLSET_FLG).Value;

      addPolicySetHeader(&rsNode, &strPolSetType, &recRuleset, &ruleId);

      /* this is the collection node. all rules are encapsulated here */
      /* for each rule id in the collection, add a new node */
      Local Rowset &rsRules = checkForRulesetAddOn(&ruleId);
      Local Rowset &rsConditions = CreateRowset(Record.GS_RULE_COND_VW);
      Local Record &rCond;
      &nCount = &rsRules.Fill("WHERE GS_RULESET_ID = :1 AND GS_FW_POLICY_DISAB <> 'D' ORDER BY SEQNUM", &ruleId);
      Local string &lastRule;
      For &nCurrent = 1 To &nCount
         &id = &rsRules(&nCurrent).GetRecord(1).GetField(Field.GS_FW_RULE_ID).Value;
         If addExtConfData(&rsNode, &id, "rule", Null) = False Then
            &ruleNode = &rsNode.AddElement("rule");
            &ruleNode.AddAttribute("name", &id);
            SQLExec("SELECT 'X' FROM PS_GS_RUL_HDR_ADON WHERE GS_FW_RULE_ID = :1 AND GS_ACTIVE_FLG = 'Y'", &id, &addOnExist);
            If &addOnExist = "X" Then
               addConditionsAddOn(&rsRules, &ruleNode, &id);
               addActionAddOn(&ruleNode, &id);
            Else
               addConditions(&rsRules, &ruleNode, &id);
               addAction(&ruleNode, &id);
            End-If;
         End-If;
      End-For;
   Else

      LogIt("Policy Set " | &rulesetID | " was not found.");

   End-If;

End-Function;

Function addDataModelTokens(&rsNode As XmlNode)
   Local Rowset &rsRedirectTokens = CreateRowset(Record.GS_REDTOKEN_TBL);
   Local integer &tokenCount = &rsRedirectTokens.Fill();
   Local integer &curToken;

   For &curToken = 1 To &tokenCount
      Local Record &recRedirectToken = &rsRedirectTokens(&curToken).GetRecord(1);

      Local Rowset &RecList = CreateRowset(Record.GS_REDTOKN_LIST);
      &lstcnt = &RecList.Fill("WHERE GS_RED_TOKEN_NAME=:1", &recRedirectToken.GetField(Field.GS_RED_TOKEN_NAME).Value);
      If All(&recRedirectToken.GetField(Field.GS_RED_TOKEN_NAME).Value) Then
         Local XmlNode &tokenNode = &rsNode.AddElement("datamodel");
         Local XmlNode &tokentypeNode = &tokenNode.AddElement("type");
         Local string &tokentypeName = &recRedirectToken.GetField(Field.GS_TOKEN_TYPE).Value;
         Local XmlNode &XMLtokentypeNode = &tokentypeNode.AddText(&tokentypeName);
         Local XmlNode &tokenaddonNode = &tokenNode.AddElement("addonurl");
         Local string &tokenaddonName = &recRedirectToken.GetField(Field.GS_ADDON_URL).Value;
         Local XmlNode &XMLtokenaddonNode = &tokenaddonNode.AddText(&tokenaddonName);
         Local XmlNode &tokenNameNode = &tokenNode.AddElement("name");
         Local string &tokenName = &recRedirectToken.GetField(Field.GS_RED_TOKEN_NAME).Value;
         Local XmlNode &textNode = &tokenNameNode.AddText(&tokenName);
         For &lstcnt = 1 To &RecList.ActiveRowCount

            Local XmlNode &tokenValueNode = &tokenNode.AddElement("value");
            Local string &tokenValue = &RecList(&lstcnt).GetRecord(1).GetField(Field.GS_RED_TOKEN_VALUE).Value;
            &textNode = &tokenValueNode.AddText(&tokenValue);
         End-For;
      End-If;
   End-For;
End-Function;

/*
* Firewall 
*/
Function LoadFirewallCfg(&rulesetID As string) Returns XmlDoc

   Local XmlDoc &xmlResponse;
   Local XmlNode &docNode;

   &xmlResponse = CreateXmlDoc("");
   Local string &docTypeText = "rules[<!ELEMENT rules (rule+)><!ELEMENT rule ((condition|group)+,action+)><!ELEMENT group (condition+)><!ELEMENT condition (parameter)><!ELEMENT action (parameter)>]";
   Local XmlNode &docType = &xmlResponse.CreateDocumentType(&docTypeText, "", "");

   &docNode = &xmlResponse.CreateDocumentElement("rules", "", &docType);
   Local Rowset &rsLicense = CreateRowset(Record.GS_FW_SYSTEM);

   If &rsLicense.Fill("where GS_ASP_SETUP_ID = 'DEFAULT'") > 0 Then
      &docNode.AddAttribute("license", &rsLicense(1).GetRecord(1).GetField(Field.GS_LICENSE_CODE).Value);

      REM Add product licenses;
      Local XmlNode &prodLicNode = &docNode.AddElement("products");
      Local XmlNode &prodLicNodeOne, &textNode;
      Local Rowset &rsProdLic = CreateRowset(Record.GS_PROD_LICENSE);
      Local string &prodlic;
      If &rsProdLic.Fill() > 0 Then
         For &licnum = 1 To &rsProdLic.ActiveRowCount
            &prodlic = &rsProdLic.GetRow(&licnum).GS_PROD_LICENSE.GS_LICENSE_CODE.Value;
            &prodLicNodeOne = &prodLicNode.AddElement("license");
            &textNode = &prodLicNodeOne.AddText(&prodlic);
         End-For;
      End-If;

      Local boolean &isNested = False;
      addRuleset(&docNode, &rulesetID, &isNested);
      addDataModelTokens(&docNode);
   Else
      LogIt("No general system settings set. Please run the GS_FW_LOAD App Engine program.");
   End-If;

   Return &xmlResponse;

End-Function;

Function LoadCurrentFirewallCfg() Returns XmlDoc
   Local string &rulesetID = "INITIAL";
   Return LoadFirewallCfg(&rulesetID);
End-Function;

Function iScript_FirewallCfg()

   REM Sanity check header for the web server code;
   %Response.SetHeader("Content-Type", "application/xml");
   SetResponseSuccess( True);

   Local XmlDoc &fwCfg = LoadCurrentFirewallCfg();

   /* Write out the response */
   %Response.Write(&fwCfg.GenFormattedXmlString());

End-Function;


Function javaScriptHideLinks()
   %Response.WriteLine(GetHTMLText(HTML.GS_FW_NAVLINKS_JS));
End-Function;

Function iScript_StaticNavScript()
   %Response.SetHeader("Content-Type", "text/javascript");
   javaScriptHideLinks();
   SetResponseSuccess( True);
End-Function;

Function iScript_HideNavLinks()
   Local GS_ERP_FIREWALL:NavLinksParms &nlParms = create GS_ERP_FIREWALL:NavLinksParms();
   &nlParms.initFromRequest();
   Local GS_ERP_FIREWALL:NavLinks &navLinks = create GS_ERP_FIREWALL:NavLinks(&nlParms);
   &navLinks.GenerateNavLinkData();

   Local string &result = "";
   Local string &callback = %Request.GetParameter("callback");
   If All(&callback) Then
      &result = &navLinks.GetResultsAsJSONP(&callback);
   Else
      &result = &navLinks.GetResultsAsJavaScript();
   End-If;
   %Response.SetContentType("text/javascript");

   %Response.SetHeader("Cache-Control", "no-cache");
   %Response.Write(&result);
   &navLinks.CleanTempData();
   SetResponseSuccess( True);
End-Function;

Function iScript_ExecuteAppClass()
   Local string &sAppClassName = %Request.GetParameter("class");
   If All(&sAppClassName) Then
      &sAppClassName = Substitute(&sAppClassName, "::", ":");
      try
         Local object &oCondClass = CreateObject(&sAppClassName);
         Local object &req = %Request;
         Local object &resp = %Response;
         &oCondClass.SetProperties(&req);

         Local boolean &matched = &oCondClass.DataConditionMatches();

         Local number &cacheSecs = &oCondClass.cacheSeconds;
         If &cacheSecs <> &oCondClass.DO_NOT_CACHE Then
            &resp.SetHeader("Cache-Control", "max-age=" | &cacheSecs);
         End-If;

         %Response.Write(String(&matched));

         &oCondClass.SetResponseHeaders(&resp);

      catch Exception &e

         %Response.WriteLine(&e.ToString());

      end-try;
   Else
      %Response.WriteLine("<html><body><H2>No Application Class</H2></body></html>");
   End-If;

   SetResponseSuccess( True);
End-Function;

/**
   processes incoming iScript requests based on a handler base object
*/
Function iScript_RequestHandler()

   Local Request &req = %Request;
   Local Response &resp = %Response;
   Local string &responseOutput = "There is no defined request handler.";
   Local string &handler = Unencode(&req.GetParameter("handler"));


   If All(&handler) Then
      /* maybe just show the PeopleCode error. catch the execption and send back a response indicating an error occurred */
      Local GS_ERP_FIREWALL:Request:Handler &h = CreateObject(&handler);
      &responseOutput = &h.run();
   End-If;

   &resp.Write(&responseOutput);

End-Function;


Function getPolicyXMLStr(&id As string) Returns string
   Local XmlDoc &xmlResponse;
   Local XmlNode &ruleNode;

   &xmlResponse = CreateXmlDoc("<?xml version='1.0'?><rules/>");
   &ruleNode = &xmlResponse.DocumentElement.AddElement("rule");
   &ruleNode.AddAttribute("name", &id);
   SQLExec("SELECT 'X' FROM PS_GS_RUL_HDR_ADON WHERE GS_FW_RULE_ID = :1 AND GS_ACTIVE_FLG = 'Y'", &id, &addOnExist);
   If &addOnExist = "X" Then
      addConditionsAddOn( Null, &ruleNode, &id);
      addActionAddOn(&ruleNode, &id);
   Else
      addConditions( Null, &ruleNode, &id);
      addAction(&ruleNode, &id);
   End-If;

   Return &xmlResponse.GenFormattedXmlString();
End-Function;

Function IScript_IB_Clients


   Local string &soapMessage;
   Local integer &startPos;
   Local integer &endPos;
   Local string &soapBody;
   Local File &file;
   Local string &filePath;
   Local string &incoming_msg;
   Local string &appServerDir, &logFilePath;
   Local boolean &voucherMsg = False;
   Local boolean &depositMsg = False;
   Local boolean &billingMsg = False;
   Local string &containerTag;
   &appServerDir = GetEnv("PS_SERVDIR");
   &logFilePath = &appServerDir | "/LOGS/EXCEL_IB_CLIENTS.txt";
   /* Create a file object */
   &file = GetFile(&logFilePath, "W", %FilePath_Absolute);
   &file.WriteLine("Server Dir Path " | &appServerDir | " *****");

   &soapMessage = %Request.GetParameter("GSXML");
   &file.WriteLine("Soap Message " | &soapMessage | " *****");

   If Find("<VOUCHER_BUILD_EXCEL_C>", &soapMessage, 1) > 0 Then
      &voucherMsg = True;
      &containerTag = "<VOUCHER_BUILD_EXCEL_C>";
      &file.WriteLine("Voucher Message " | " *****");
   End-If;
   If Find("<AR_DEPOSIT_BUILD_EXCEL_C>", &soapMessage, 1) > 0 Then
      &depositMsg = True;
      &containerTag = "<AR_DEPOSIT_BUILD_EXCEL_C>";
      &file.WriteLine("Deposit Message " | " *****");
   End-If;
   If Find("<BILLING_BUILD_EXCEL_C>", &soapMessage, 1) > 0 Then
      &billingMsg = True;
      &containerTag = "<BILLING_BUILD_EXCEL_C>";
      &file.WriteLine("Billing Message " | " *****");
   End-If;

   &startPos = Find(&containerTag, &soapMessage, 1);
   &file.WriteLine("Start Pos " | &startPos | " *****");
   If &startPos > 0 Then
      /* Find the end position of </soapenv:Body> */
      &endPos = Find("</soapenv:Body>", &soapMessage, &startPos);
      &file.WriteLine("End Pos " | &endPos | " *****");
      If &endPos > 0 Then
         /* Extract the SOAP body */
         &soapBody = Substring(&soapMessage, &startPos, &endPos - &startPos);
         &file.WriteLine("Substring1 " | &soapBody | " *****");

         /* Process the SOAP body */
         /* You can further manipulate &soapBody as needed */
         /* For example, you can parse it as XML or perform other operations */
      End-If;

      &file.WriteLine("Soap Body " | &soapBody | " *****");
   End-If;

   Local object &oMsgReq;
   Local object &oMsgResp;
   Local string &sXmlRequest;
   Local string &sOutput;
   Local Message &requestMsg;
   Local XmlDoc &xmlDoc;


   /* Construct your XML request */
   &sXmlRequest = "<?xml version='1.0'?>" | &soapBody;

   &xmlDoc = CreateXmlDoc(&sXmlRequest);
   &file.WriteLine("Request Message " | &sXmlRequest | " *****");
   /* Create a request message */
   If &voucherMsg = True Then
      &requestMsg = CreateMessage(Operation.EXCELUPLOADFORVOUCHER, %IntBroker_Request);
      /*&requestMsg = CreateMessage(Operation.EXCELUPLOADFORBILLING, %IntBroker_Request);*/
   End-If;
   If &depositMsg = True Then
      &requestMsg = CreateMessage(Operation.EXCELUPLOADFORDEPOSITS, %IntBroker_Request);
   End-If;
   If &billingMsg = True Then
      &requestMsg = CreateMessage(Operation.EXCELUPLOADFORBILLING, %IntBroker_Request);
      &file.WriteLine("Billing Message Created " | " *****");
      /*&requestMsg = CreateMessage(Operation.EXCELUPLOADFORVOUCHER, %IntBroker_Request);*/
   End-If;

   &file.WriteLine("Message Name " | &requestMsg.Name | " *****");
   &file.WriteLine("Message Created " | " *****");
   /* Set the content of the message to your XML request */
   Local string &xmlString = &xmlDoc.GenXmlString();
   &requestMsg.LoadXMLPartString(1, &xmlString);
   Local Rowset &rsMsg = &requestMsg.GetPartRowset(1);
   For &ii = 1 To &rsMsg.ActiveRowCount
      &file.WriteLine("Rowset Row Name " | &rsMsg.Name | " *****");
   End-For;
   &file.WriteLine("Gen String " | &requestMsg.GenXMLString() | " *****");

   &file.WriteLine("Before Sync Request " | " *****");
   Local Message &responseMsg = %IntBroker.SyncRequest(&requestMsg);
   &file.WriteLine("After Sync Request " | " *****");
   If &responseMsg.ResponseStatus = %IB_Status_Success Then

      /* Retrieve and process the response */
      &sOutput = &responseMsg.GetContentString();
      &file.WriteLine("Response Message " | &sOutput | " *****");
      %Response.Write(&sOutput);
   Else
      %Response.Write("Import Failed");
   End-If;


   /* Process the output */
   /* Do something with &sOutput */
End-Function;

Function setDataInDocElement(&docElement, &docValue, &k)

   Evaluate &docElement.GetPropertyByIndex(&k).primitivetype
   When = %Document_Integer
   When = 4
      &docElement.GetPropertyByIndex(&k).value = Integer(&docValue);
      Break;

   When = %Document_Decimal
   When = 6
      &docElement.GetPropertyByIndex(&k).value = Value(&docValue);
      Break;

   When = %Document_Date
   When = 7
      &docElement.GetPropertyByIndex(&k).value = Date(&docValue);
      Break;

   When = %Document_Time
   When = 8
      &docElement.GetPropertyByIndex(&k).value = Time(&docValue);
      Break;

   When = %Document_DateTime
   When = 9
      &docElement.GetPropertyByIndex(&k).value = DateTimeValue(&docValue);
      Break;

   When-Other
      &docElement.GetPropertyByIndex(&k).value = &docValue;
   End-Evaluate;

End-Function;

Function IScript_JournalUpload_WS
   Local boolean &nRet, &otpValid;
   Local string &CR = Char(13) | Char(10);
   Local File &file;
   Local string &filePath;
   Local string &appServerDir, &logFilePath;
   Local Collection &HDR_COL, &LN_COL, &COll_ITEMS;
   Local Compound &PRCS_ITEM, &HDR_ITEM, &LN_ITEM, &COM_ITEM;


   /*prepare service operation message*/
   &requestMsg = CreateMessage(Operation."GL_JRNL_IMP", %IntBroker_Request);
   Local Document &doc = &requestMsg.GetDocument();
   &COM = &doc.DocumentElement;

   &appServerDir = GetEnv("PS_SERVDIR");
   &logFilePath = &appServerDir | "/LOGS/GS_JRNL_UPLOAD.txt";
   /* Create a file object */
   &file = GetFile(&logFilePath, "W", %FilePath_Absolute);
   &file.WriteLine("Server Dir Path " | &appServerDir | " *****");
   &incomingXML = %Request.GetParameter("GSXML");
   &file.WriteLine("Incoming Request " | &incomingXML | " *****");

   &inXMLDoc = CreateXmlDoc(String(&incomingXML));
   &processXmlDocElement = "PROCESS_OPTION";
   &jrnlHdrXmlElement = "JRNL_HDR_STG";
   &jrnlHdrDocElement = "JRNL_HDR";
   &jrnlLineXmlElement = "JRNL_LN_STG";
   &jrnlLineDocElement = "JRNL_LN";

   &processOption = &inXMLDoc.DocumentElement.GetElementsByTagName(&processXmlDocElement);
   If &processOption.len = 0 Then
      /*invalid incoming XML*/
   Else
      /*Set document with PROCESS_OPTION element */
      &PRCS_ITEM = &COM.GetPropertyByName(&processXmlDocElement);
      &file.WriteLine("***** " | &processXmlDocElement | " *****");
      For &i = 1 To &processOption.len

         /*Loop all the child nodes of PROCESS_OPTION XML. Verify if child nodes exists in document and set child elements in document*/
         For &j = 1 To &processOption [&i].ChildNodeCount
            For &K = 1 To &PRCS_ITEM.PropertyCount
               If &processOption [&i].GetChildNode(&j).NodeName = &PRCS_ITEM.GetPropertyByIndex(&K).name Then
                  &nodeVal = &processOption [&i].GetChildNode(&j).nodevalue;
                  If None(&nodeVal) Then
                     &nodeVal = &processOption [&i].GetChildNode(&j).GetCDataValue();
                  End-If;

                  &file.WriteLine("XML Node= " | &processOption [&i].GetChildNode(&j).NodeName | " - " | &nodeVal);
                  setDataInDocElement(&PRCS_ITEM, &nodeVal, &K);
                  &file.WriteLine("Doc Element= " | &PRCS_ITEM.GetPropertyByIndex(&K).name | " - " | &PRCS_ITEM.GetPropertyByIndex(&K).value);
               End-If;
            End-For;
         End-For;
      End-For;
   End-If;

   &jrnlHdr = &inXMLDoc.DocumentElement.GetElementsByTagName(&jrnlHdrXmlElement);
   If &jrnlHdr.len = 0 Then
      /*invalid incoming XML*/
   Else
      /*Set document with JRNL_HDR element */
      &HDR_COL = &COM.GetPropertyByName(&jrnlHdrDocElement);
      &file.WriteLine(&CR | "***** " | &jrnlHdrDocElement | " *****");
      For &i = 1 To &jrnlHdr.len
         &HDR_ITEM = &HDR_COL.CreateItem();
         /*Loop all the child nodes of JRNL_HDR_STG XML. Verify if child nodes exists in document and set child elements in document*/
         For &j = 1 To &jrnlHdr [&i].ChildNodeCount
            For &K = 1 To &HDR_ITEM.PropertyCount
               If &jrnlHdr [&i].GetChildNode(&j).NodeName = &HDR_ITEM.GetPropertyByIndex(&K).name Then
                  &nodeVal = &jrnlHdr [&i].GetChildNode(&j).nodevalue;
                  If None(&nodeVal) Then
                     &nodeVal = &jrnlHdr [&i].GetChildNode(&j).GetCDataValue();
                  End-If;

                  &file.WriteLine("XML Node= " | &jrnlHdr [&i].GetChildNode(&j).NodeName | " - " | &nodeVal);
                  setDataInDocElement(&HDR_ITEM, &nodeVal, &K);
                  &file.WriteLine("Doc Element= " | &HDR_ITEM.GetPropertyByIndex(&K).name | " - " | &HDR_ITEM.GetPropertyByIndex(&K).value);
               End-If;
            End-For;
         End-For;
         &nRet = &HDR_COL.AppendItem(&HDR_ITEM);

         &jrnlLine = &inXMLDoc.DocumentElement.GetElementsByTagName(&jrnlLineXmlElement);
         If &jrnlLine.len = 0 Then
            /*invalid incoming XML*/
         Else
            /*Set document with JRNL_LN element */
            &LN_COL = &HDR_ITEM.GetPropertyByName(&jrnlLineDocElement);
            &file.WriteLine(&CR | "***** " | &jrnlLineDocElement | " *****");
            For &m = 1 To &jrnlLine.len
               &LN_ITEM = &LN_COL.CreateItem();
               /*Loop all the child nodes of JRNL_LN_STG XML. Verify if child nodes exists in document and set child elements in document*/
               For &n = 1 To &jrnlLine [&m].ChildNodeCount
                  For &o = 1 To &LN_ITEM.PropertyCount
                     If &jrnlLine [&m].GetChildNode(&n).NodeName = &LN_ITEM.GetPropertyByIndex(&o).name Then
                        &nodeVal = &jrnlLine [&m].GetChildNode(&n).nodevalue;
                        If None(&nodeVal) Then
                           &nodeVal = &jrnlLine [&m].GetChildNode(&n).GetCDataValue();
                        End-If;

                        &file.WriteLine("XML Node= " | &jrnlLine [&m].GetChildNode(&n).NodeName | " - " | &nodeVal);
                        setDataInDocElement(&LN_ITEM, &nodeVal, &o);
                        &file.WriteLine("Doc Element= " | &LN_ITEM.GetPropertyByIndex(&o).name | " - " | &LN_ITEM.GetPropertyByIndex(&o).value);
                     End-If;
                  End-For;
               End-For;
               &nRet = &LN_COL.AppendItem(&LN_ITEM);
            End-For;
         End-If;
      End-For;
   End-If;

   Local Message &responseMsg = %IntBroker.SyncRequest(&requestMsg);
   If &responseMsg.ResponseStatus = %IB_Status_Success Then

      Local string &soapRes = "<?xml version=""1.0"" encoding=""UTF-8""?>";
      &soapRes = &soapRes | "<POSTRESPONSE>";
      Local Document &responseDoc = &responseMsg.GetDocument();
      &COM1 = &responseDoc.DocumentElement;
      Local Collection &COll_IMPRT, &COll_UPDT, &COll_ERROR;
      &COll_IMPRT = &COM1.GetPropertyByName("IMPORT");
      &COll_UPDT = &COM1.GetPropertyByName("UPDATE");
      &COll_ERROR = &COM1.GetPropertyByName("ERRORS");
      For &i = 1 To &COll_IMPRT.Count
         &COM_ITEM = &COll_IMPRT.GetItem(&i);

         &soapRes = &soapRes | "<IMPORTED>";
         &soapRes = &soapRes | &COM_ITEM.GetPropertyByName("IMPORTED").Value;
         &soapRes = &soapRes | "</IMPORTED>";
      End-For;
      For &i = 1 To &COll_UPDT.Count
         &COM_ITEM = &COll_UPDT.GetItem(&i);

         &soapRes = &soapRes | "<UPDATED>";
         &soapRes = &soapRes | &COM_ITEM.GetPropertyByName("UPDATED").Value;
         &soapRes = &soapRes | "</UPDATED>";
      End-For;
      For &i = 1 To &COll_ERROR.Count
         &COM_ITEM = &COll_ERROR.GetItem(&i);

         &soapRes = &soapRes | "<ERROR>";
         &soapRes = &soapRes | &COM_ITEM.GetPropertyByName("ERROR").Value;
         &soapRes = &soapRes | "</ERROR>";
      End-For;
      &soapRes = &soapRes | "</POSTRESPONSE>";

      &file.WriteLine("Response Message " | &soapRes);
      %Response.Write(&soapRes);

   Else
      &file.WriteLine("Import Failed");
      %Response.Write("Import Failed");
   End-If;


End-Function;

Function getQueryFieldResponse(&formNum As integer) Returns string

   Return "submitAction_win" | &formNum | "(document.win" | &formNum | ", '#ICOK');";

End-Function;


Function getPageFieldResponse(&formNum As integer, &ptVersionParam As string, &icaction As string) Returns string

   Local string &closeKeyCode = "#KEYCJ"; /*default to Ctrl+J */
   Local number &ptVersionNum;
   If &ptVersionParam <> "" Then
      &ptVersionNum = Value(&ptVersionParam);
      If &ptVersionNum < 8.52 Then
         &closeKeyCode = "#ICKEYA0"; /* Alt+0 */
      End-If;
   End-If;

   Local string &respJS = "if(window.parent.isAnyModal() && window.parent.isFModeLayout() ){if('" | &icaction | "'){window.parent.document.getElementById('" | &icaction | "').click();}} else {";
   &respJS = &respJS | "if (!!window.net2 && !!!window.net2.wrapped_ContentLoader) {";
   &respJS = &respJS | "    if (typeof bAccessibility_win" | &formNum | " !== 'undefined' && bAccessibility_win" | &formNum | ") {";
   &respJS = &respJS | "        submitAction_win" | &formNum | "(document.win" | &formNum | ", '#ICContinue');";
   &respJS = &respJS | "    }";
   &respJS = &respJS | "    window.net2.wrapped_ContentLoader = function() { ";
   &respJS = &respJS | "        var self = this,";
   &respJS = &respJS | "            getStyleDiv = function() {";
   &respJS = &respJS | "                var div = document.createElement('div');";
   &respJS = &respJS | "                div.innerHTML = '<style>#win" | &formNum | "divPAGECONTAINER{display:none;}</style>';";
   &respJS = &respJS | "                return div;";
   &respJS = &respJS | "            },";
   &respJS = &respJS | "            getPCDiv = function() {";
   &respJS = &respJS | "                var pcDiv;";
   &respJS = &respJS | "                if (typeof document.querySelector !== 'undefined') {";
   &respJS = &respJS | "                    pcDiv = document.querySelector('#win" | &formNum | "divPAGECONTAINER');";
   &respJS = &respJS | "                }";
   &respJS = &respJS | "                else {";
   &respJS = &respJS | "                    pcDiv = document.getElementById('#win" | &formNum | "divPAGECONTAINER');";
   &respJS = &respJS | "                }";
   &respJS = &respJS | "                return pcDiv;";
   &respJS = &respJS | "            };";
   &respJS = &respJS | "        self.real_processXML = self.processXML;";
   &respJS = &respJS | "        self.processXML = function () {";
   &respJS = &respJS | "            self.real_processXML.apply(self, arguments);";
   &respJS = &respJS | "            if (!!window.ghRedraw) {";
   &respJS = &respJS | "                window.ghRedraw = false;";
   &respJS = &respJS | "                var pcDiv = getPCDiv(), styleDiv = getStyleDiv();";
   &respJS = &respJS | "                try {";
   &respJS = &respJS | "                    styleDiv = pcDiv.appendChild(styleDiv);";
   &respJS = &respJS | "                } catch (ex) {}";
   &respJS = &respJS | "                submitAction_win" | &formNum | "(document.win" | &formNum | ", '#ICContinue');";
   &respJS = &respJS | "                if (typeof isFModeLayout !== 'undefined' && typeof MTop().modId !== 'undefined' && MTop().modId !== -1) {";
   &respJS = &respJS | "                    if (isFModeLayout()) {";
   &respJS = &respJS | "                        doCloseModal(MTop().modId);";
   &respJS = &respJS | "                        try {";
   &respJS = &respJS | "                            pcDiv.removeChild(styleDiv);";
   &respJS = &respJS | "                        } catch (ex) {}";
   &respJS = &respJS | "                    }";
   &respJS = &respJS | "                }";
   &respJS = &respJS | "            }";
   &respJS = &respJS | "        };";
   &respJS = &respJS | "        return window.net2.real_ContentLoader.apply(self, arguments);";
   &respJS = &respJS | "    };";
   &respJS = &respJS | "    window.net2.wrapped_ContentLoader.prototype = window.net2.ContentLoader.prototype;";
   &respJS = &respJS | "    window.net2.real_ContentLoader = window.net2.ContentLoader;";
   &respJS = &respJS | "    window.net2.ContentLoader = window.net2.wrapped_ContentLoader;";
   &respJS = &respJS | "}";
   &respJS = &respJS | "window.ghRedraw = true; submitAction_win" | &formNum | "(document.win" | &formNum | ", '" | &closeKeyCode | "');";
   &respJS = &respJS | "}";

   Return &respJS;

End-Function;


Function iScript_FieldMask()

   Local Request &req = %Request;
   Local Response &resp = %Response;
   Local integer &seconds;
   Local string &ruleId = &req.GetParameter("rule");
   Local string &keys = &req.GetParameter("keys");
   Local string &queryField = &req.GetParameter("qfield");
   Local string &ptVersionParam = &req.GetParameter("ptver");
   Local string &icaction = &req.GetParameter("ghICAction");

   rem we can only accept up to 254 characters for the key values;
   If &keys <> "" And
         Len(&keys) > 254 Then
      &keys = Substring(&keys, 1, 254);
   End-If;

   rem get the number of seconds to cache the unmasked field;
   SQLExec("SELECT GS_CACHE_SECONDS FROM PS_GS_MASK_CHA_TBL WHERE GS_USER_ID = :1", %UserId, &seconds);

   rem set the expiration number of seconds to add to the current datetime;
   Local datetime &dttm = AddToDateTime(%Datetime, 0, 0, 0, 0, 0, &seconds);

   rem update the specific field;
   If &ruleId <> "" Then
      SQLExec("UPDATE PS_GS_MASK_CHA_TBL SET GS_PASSED_CHALLENG = 'Y', GS_EXP_DTTM = %DateTimeIn(:1) WHERE GS_USER_ID = :2 AND GS_FW_RULE_ID = :3 AND GS_RQST_URL_PARAM = :4", &dttm, %UserId, &ruleId, &keys);
   Else
      rem update all fields;
      SQLExec("UPDATE PS_GS_MASK_CHA_TBL SET GS_PASSED_CHALLENG = 'Y', GS_EXP_DTTM = %DateTimeIn(:1) WHERE GS_USER_ID = :2 AND GS_RQST_URL_PARAM = :3", &dttm, %UserId, &keys);
   End-If;

   rem formNum defaults to 0 so we'll use that if there is no query string parameter;
   Local integer &formNum;
   Local string &formNumParam = %Request.GetParameter("formnum");
   If &formNumParam <> "" Then
      &formNum = Value(&formNumParam);
   End-If;

   Local string &respJS;
   If &queryField <> "" Then
      &respJS = getQueryFieldResponse(&formNum);
   Else
      &respJS = getPageFieldResponse(&formNum, &ptVersionParam, &icaction);
   End-If;

   &resp.SetContentType("text/javascript");
   &resp.SetHeader("Cache-Control", "no-cache");
   &resp.Write(&respJS);

End-Function;

