Function GetReqQryParameters()

   Local string &QueryStr = Unencode(%Request.QueryString);
   Local array of string &QueryStrArr = Split(&QueryStr, "&");
   &QueryParamArr = CreateArrayRept(CreateArrayRept(" ", 0), 0);
   For &i = 1 To &QueryStrArr.Len
      &temp = Split(&QueryStrArr [&i], "=");
      &QueryParamArr.Push(&temp);
   End-For;

   /* For &i = 1 To &QueryParamArr.Len
      %Response.WriteLine("Query Param [" | &i | "] - " | &QueryParamArr [&i][1] | " - " | &QueryParamArr [&i][2]);
   End-For;*/
End-Function;

Function GetReqParam(&Name As string) Returns string;
   Local string &retString = "";
   If &QueryParamArr <> Null Then
      Local integer &ind = &QueryParamArr.Find(&Name);
      If &ind > 0 And
            All(&QueryParamArr [&ind][2]) Then;
         &retString = &QueryParamArr [&ind][2];
      End-If;
   End-If;
   Return &retString;
End-Function;

Function MaskOutputFields(&qryRowSet As Rowset, &QryObj As ApiObject, &QueryMaskFldArr As array of string)
   Local integer &Rowcount, &RecCount;

   If &qryRowSet <> Null Then
      Local ApiObject &QryFields;
      &QryFields = &QryObj.QuerySelect.QueryOutputFields;

      For &Rowcount = 1 To &qryRowSet.ActiveRowCount
         &QryFields = &QryObj.QuerySelect.QueryOutputFields;
         Local Row &rowObj = &qryRowSet.GetRow(&Rowcount);
         For &RecCount = 1 To &rowObj.RecordCount
            For &FldCount = 1 To &rowObj.GetRecord(&RecCount).FieldCount
               &QryFld = &QryFields.Item(&FldCount);
               /* If &QueryMaskFldArr.Find(&QryFld.Name) > 0 And
                     &QryFld.ExpNum = 0 Then*/
               If &QueryMaskFldArr.Find(&QryFld.Name) > 0 Then
                  Evaluate &QryFld.Type
                  When %FieldType_Number
                  When %FieldType_SignedNumber
                     Local number &defaultNum;
                     &qryRowSet.GetRow(&Rowcount).GetRecord(&RecCount).GetField(&FldCount).Value = &defaultNum;
                     Break;

                  When %FieldType_Date
                     Local date &nullDate;
                     &qryRowSet.GetRow(&Rowcount).GetRecord(&RecCount).GetField(&FldCount).Value = Date(19000101);

                     Break;
                  When %FieldType_Time
                     Local time &nullTime;
                     &qryRowSet.GetRow(&Rowcount).GetRecord(&RecCount).GetField(&FldCount).Value = &nullTime;

                     Break;
                  When %FieldType_DateTime
                     Local datetime &nullDTTime;
                     &qryRowSet.GetRow(&Rowcount).GetRecord(&RecCount).GetField(&FldCount).Value = DateTime6(1900, 1, 1, 0, 0, 0);

                     Break;
                  When-Other
                     &qryRowSet.GetRow(&Rowcount).GetRecord(&RecCount).GetField(&FldCount).Value = Rept("X", &QryFld.Length);
                     Break;

                  End-Evaluate;
               End-If;
            End-For;
         End-For;
      End-For;

   End-If;

End-Function;

