Function iScript_CSConfig()

   Local string &CR = Char(13) | Char(10);
   %Response.SetContentType("text/plain");
   %Response.SetHeader("CacheControl", "no-cache");
   %Response.SetHeader("Pragma", "no-cache");
   %Response.SetHeader("Expires", "-1");

   Local boolean &isLogin = (%Request.GetParameter("action") = "login");

   If Not &isLogin Then
      %Response.Write("Grey Sparling Desktop Single Signon - Client Server");
      Return;
   End-If;

   Local string &HTML;

   /* Build the HTML content */
   &HTML = "<!DOCTYPE html>";
   &HTML = &HTML | "<html><head>";
   &HTML = &HTML | "<meta charset='UTF-8'>";
   &HTML = &HTML | "<title>WEBLIB_GS_SSO_ISCRIPT1</title>"; /* Add Title Here */
   &HTML = &HTML | "</head><body>";
   /* Write the HTML content to the response */
   %Response.SetContentType("text/html");
   %Response.Write(&HTML);
   %Response.Write("[psuser]" | &CR);

   Local boolean &threeTier = (%Request.GetParameter("threetier") = "1");
   Local boolean &getOneTimePassword = (%Request.GetParameter("otp") = "1");

   If &getOneTimePassword Then

      Local integer &i;
      Local array of string &chars = CreateArrayRept("", 0);
      For &i = 65 To 90
         &chars.Push(Char(&i));
      End-For;
      For &i = 97 To 122
         &chars.Push(Char(&i));
      End-For;

      Local string &oneTimePswd = "";
      For &i = 1 To 20
         &oneTimePswd = &oneTimePswd | &chars [Int(Rand() * &chars.Len) + 1];
      End-For;

      &oneTimePswd = Hash(&oneTimePswd);
      %Response.Write("OprId=" | %UserId | &CR);
      %Response.Write("OprPswd=" | &oneTimePswd | &CR);


      Local Record &recPasswordShadow = CreateRecord(Record.GS_SSO_SHDW);
      &recPasswordShadow.GetField(Field.GS_OTU_SSO_CLIENT).Value = %UserId;
      Local boolean &exists = &recPasswordShadow.SelectByKey();

      REM How long is the one time password good for? Not too long, not too short;


      Local string &expireSecs = %Request.GetParameter("expireSecs");
      If &expireSecs = "" Then
         &expireSecs = "90";
      End-If;
      Local integer &IntexpireSecs;
      &IntexpireSecs = Integer(&expireSecs);
      Local datetime &expires = AddToDateTime(%Datetime, 0, 0, 0, 0, 0, &IntexpireSecs);
      &recPasswordShadow.GetField(Field.GS_OTU_SSO_CLIENT).Value = %UserId;
      &recPasswordShadow.GetField(Field.LOGINDTTM).Value = &expires;

      &pswd_nosalt = Hash(&oneTimePswd);
      &recPasswordShadow.GetField(Field.GS_OTP_SSO_CLIENT).Value = &oneTimePswd;
      REM Local string &otp1 = "GKk66AvB2t8F";
      REM &recPasswordShadow.GetField(Field.OTP).Value = &otp1;

      If &exists Then
         &recPasswordShadow.Update();
      Else
         &recPasswordShadow.Insert();
      End-If;

      If &threeTier Then
         %Response.Write("DBType=APPSRV" | &CR);
         REM FIXME - connectivity info;
         Local string &appserv = %Request.GetParameter("appserver");
         If All(&appserv) Then
            %Response.Write("AppName=" | &appserv | &CR);
         End-If;
      Else
         %Response.Write("DBType=" | %DbType | &CR);
         If %DbType = "SYBASE" Or
               %DbType = "INFORMIX" Then
            %Response.Write("ServerName=" | %DbServerName | &CR);
         End-If;
         %Response.Write("DBName=" | %DbName | &CR);
      End-If;
      %Response.Write("SignOnId=" | %SignonUserId | &CR);

      %Response.Write("SignOnPswd=" | %SignonUserPswd | &CR);
      %Response.Write("OprId=" | %UserId | &CR);
      REM %Response.Write("OprPswd=" | &oneTimePswd | &CR);
      REM %Response.Write("OprPswd=" | &pswd_nosalt | &CR);
      %Response.Write("GoodUntil=" | &expires | &CR);
      Local string &hashSignature;
      Local string &hashSignatureWithSalt;
      Local string &saltVal = "kjxnzLQB0UbOMoEtvYbzNg==";
      Local string &pwd = "GKk66AvB2t8F";
      &hashSignature = Hash(&pwd);
      %Response.Write("Hash=" | &hashSignature | &CR);
      &hashSignatureWithSalt = HashWithSalt(&pwd, &saltVal);
      %Response.Write("HashWithSalt=" | &hashSignatureWithSalt | &CR);

      /*Local string &license;
      SQLExec("SELECT GS_LICENSE_CODE FROM PS_GS_SS_SYSTEM", &license);
      If All(&license) Then
         Local array of string &lines = Split(&license, &CR);
         For &i = 1 To &lines.Len
            If Substring(&lines [&i], 1, 1) <> "#" Then
               %Response.Write("license=" | &license | &CR);
               Break;
            End-If;
         End-For;
      End-If*/
   End-If;
   %Response.Write("</body></html>" | &CR);
   /*If Not &threeTier Then
      REM Pick up other environment info;
      %Response.Write(&CR);

      Local Record &recEnv = CreateRecord(Record.GS_SSO_TGT_ENVS);
      Local SQL &sqlEnv = CreateSQL("%SELECTALL(:1)");
      &sqlEnv.Execute(&recEnv);
      While &sqlEnv.Fetch(&recEnv)
         %Response.Write("[" | &recEnv.GetField(Field.DBNAME).Value | "]" | &CR);
         %Response.Write("descrshort=" | &recEnv.GetField(Field.DESCRSHORT).Value | &CR);
         %Response.Write("descrlong=" | &recEnv.GetField(Field.DESCR60).Value | &CR);
         %Response.Write("loginURL=" | &recEnv.GetField(Field.URL).Value | &CR);
         %Response.Write(&CR);
      End-While;
      &sqlEnv.Close();
   End-If;*/

End-Function;

/*
 The Web Libraries listed here handle Excel to CI requests.
 1. iScript_StartSession: performs mapping and verifies the passcode
 2. iScript_GetSession: get user's session to submit Excel to CI requests
 3. iScript_GetTranID: generates Transaction ID and One Time Passcode 
Main Table: GS_SSO_EXCEL
GS_NAMEID_FORMAT = incoming SAML ID from VB
GS_LOG_ID = transaction id generated in PS
GS_OPRID = PS userid when nameid is other than operator id
GS_PASSWORD = passcode
GS_PUSH_STATUS_PB = flag for loggedin condition
GS_LOG_DATA = Session Data
GS_VERIFY_FLG = passcode verification flag
GS_CLIENT_CODE = secret key
GS_DESCRLONG = public key
GS_EXP_DTTM = token expiration
*/
import GS_AUTHENTICATION:Utils:Logger;

Declare Function LogIt PeopleCode FUNCLIB_GS_UTIL.ISCRIPT1 FieldFormula;

Function XORNum(&num1 As number, &num2 As number) Returns number
   If &num1 = &num2 Then
      Return 0;
   Else
      Return 1;
   End-If;
End-Function;

Function XORNumStr(&num1 As string, &num2 As string) Returns string
   Local number &i;
   Local string &retStr = "";

   If Len(&num1) = Len(&num2) Then
      For &i = 1 To Len(&num1)
         If Substring(&num1, &i, 1) = Substring(&num2, &i, 1) Then
            &retStr = &retStr | "0";
         Else
            &retStr = &retStr | "1";
         End-If;
      End-For;
      Return &retStr;
   Else
      Return "Mis-Match bit length. XOR cannot be done";
   End-If;

End-Function;

Function ANDNumStr(&num1 As string, &num2 As string) Returns string
   Local number &i;
   Local string &retStr = "";

   If Len(&num1) = Len(&num2) Then
      For &i = 1 To Len(&num1)
         If Substring(&num1, &i, 1) = Substring(&num2, &i, 1) Then
            &retStr = &retStr | "0";
         Else
            &retStr = &retStr | "1";
         End-If;
      End-For;
      Return &retStr;
   Else
      Return "Mis-Match bit length. XOR cannot be done";
   End-If;

End-Function;

Function NumMapChar(&num As number) Returns string
   Evaluate &num
   When 10
      Return "a";
      Break;
   When 11
      Return "b";
      Break;
   When 12
      Return "c";
      Break;
   When 13
      Return "d";
      Break;
   When 14
      Return "e";
      Break;
   When 15
      Return "f";
      Break;
   When-Other
      Return String(&num);
   End-Evaluate;
End-Function;

Function CharMapNum(&str As string) Returns number
   Evaluate &str
   When "a"
      Return 10;
      Break;
   When "A"
      Return 10;
      Break;
   When "b"
      Return 11;
      Break;
   When "B"
      Return 11;
      Break;
   When "c"
      Return 12;
      Break;
   When "C"
      Return 12;
      Break;
   When "d"
      Return 13;
      Break;
   When "D"
      Return 13;
      Break;
   When "e"
      Return 14;
      Break;
   When "E"
      Return 14;
      Break;
   When "f"
      Return 15;
      Break;
   When "F"
      Return 15;
      Break;
   When-Other
      Return Integer(&str);
   End-Evaluate;
End-Function;

Function Convert10256(&str As string) Returns string
   Return String(Char(Integer(&str)));
End-Function;

Function Convert1610(&str As string) Returns string
   Local number &num = 0;
   Local number &temp;
   Local number &temp2 = 1;
   Local number &i, &j;
   For &i = 1 To Len(&str)
      &temp = CharMapNum(Substring(&str, &i, 1));
      If (Len(&str) - &i) = 0 Then
         &num = &num + &temp
      Else
         &temp2 = 1;
         For &j = (Len(&str) - &i) To 1 Step - 1
            &temp2 = &temp2 * 16;
         End-For;
         &num = &num + (&temp * &temp2);
      End-If;

   End-For;
   Return String(&num);
End-Function;

Function Convert216(&str As string) Returns string
   Local number &i, &j, &s;
   Local number &num = 0;

   For &i = 1 To Len(&str)
      If (&i = Len(&str)) Then
         &j = &i + Len(&str);
      Else
         &j = &i;
      End-If;
      &num = &num + Int(Integer(Substring(&str, &i, 1))) * Int(8 / &j);
   End-For;

   Return String(NumMapChar(&num));
End-Function;

Function Convert216s(&str As string) Returns string
   Local number &i, &j, &s;
   Local number &num = 0;
   Local string &retStr;

   &s = 1;
   For &i = 1 To Len(&str)
      If (&s = 4) Then
         &j = 4 + &s;
      Else
         &j = &s;
      End-If;
      &num = &num + Int(Integer(Substring(&str, &i, 1))) * Int(8 / &j);
      If (&s = 4) Then
         &retStr = &retStr | (NumMapChar(&num));
         &num = 0;
         &s = 1;
      Else
         &s = &s + 1;
      End-If;

   End-For;

   Return String(&retStr);
End-Function;

Function Convert162(&str As string) Returns string

   Evaluate &str
   When "0"
      Return "0000";
      Break;
   When "1"
      Return "0001";
      Break;
   When "2"
      Return "0010";
      Break;
   When "3"
      Return "0011";
      Break;
   When "4"
      Return "0100";
      Break;
   When "5"
      Return "0101";
      Break;
   When "6"
      Return "0110";
      Break;
   When "7"
      Return "0111";
      Break;
   When "8"
      Return "1000";
      Break;
   When "9"
      Return "1001";
      Break;
   When "a"
      Return "1010";
      Break;
   When "b"
      Return "1011";
      Break;
   When "c"
      Return "1100";
      Break;
   When "d"
      Return "1101";
      Break;
   When "e"
      Return "1110";
      Break;
   When "f"
      Return "1111";
      Break;
   When-Other

   End-Evaluate;
End-Function;

Function Convert162s(&str As string) Returns string
   Local string &retStr = "";
   Local number &i;

   For &i = 1 To Len(&str)
      &retStr = &retStr | Convert162(Substring(&str, &i, 1));
   End-For;
   Return &retStr;

End-Function;

Function Convert1016(&str As string) Returns string
   Local number &num = Value(&str);
   Local number &quo;
   Local string &remdr;
   While (&num >= 16)
      &remdr = String(NumMapChar(Mod(&num, 16))) | &remdr;
      &num = Int(&num / 16);
   End-While;

   Return String(NumMapChar(&num)) | &remdr;
End-Function;

Function Convert1016s(&str As string) Returns string
   Local number &num = Value(&str);
   Local number &quo;
   Local string &remdr, &strDecimalNum;

   While (&num >= 16)
      &remdr = String(NumMapChar(Mod(&num, 16))) | &remdr;
      &num = &num / 16;
      If Find(".", String(&num)) <> 0 Then
         &strDecimalNum = Split(String(&num), ".")[1];
         &num = Value(&strDecimalNum);
      End-If;
   End-While;

   Return String(NumMapChar(&num)) | &remdr;
End-Function;

Function Convert25610(&str As string) Returns string
   Return String(Code(&str));
End-Function;

Function Convert2562(&str As string, &delimit As string, &size As number) Returns string
   Local string &retStr = "";
   Local string &temp;
   Local number &currSize = 0;
   Local integer &i, &j;

   For &i = 1 To Len(&str)
      &temp = Convert1016(Convert25610(Substring(&str, &i, 1)));
      For &j = 1 To Len(&temp)
         &retStr = &retStr | Convert162(Substring(&temp, &j, 1));
      End-For;
      &currSize = &currSize + 8;
      If &delimit = "Y" And
            &currSize = &size Then
         If Len(&str) <> &i Then
            &retStr = &retStr | " ";
            &currSize = 0;
         End-If;
      End-If;
   End-For;

   Return &retStr;
End-Function;

Function Convert2256(&str As string) Returns string
   Local string &retStr = "";
   Local string &temp;
   Local string &temp2 = "";
   Local integer &i, &j;

   For &i = 1 To Len(&str)
      &retStr = &retStr | Convert10256(Convert1610(Convert216(Substring(Substring(&str, &i, 8), 1, 4)) | Convert216(Substring(Substring(&str, &i, 8), 5, 8))));
      &i = &i + 7;
   End-For;

   Return &retStr;
End-Function;

Function ECDH_PublicKeyGen(&pkey As array of number) Returns string

   Local array of string &gCurvePoint = CreateArray("5A232150", "2140432B", "242D5051", "2859505F", "53542E3F", "4349442E", "31362130", "3B303D33", "5F3B5333", "51294033", "25583F2D", "21403B53", "54252152", "412B4326", "50262659");
   Local string &pubKey;
   Local integer &i, &temp;
   Local number &curvePoint;

   For &i = 1 To &gCurvePoint.Len
      &curvePoint = Round(Float(Convert1610(&gCurvePoint [&i])), 0);
      &pubKey = &pubKey | String(&curvePoint + &pkey [&i]);
      If &i <> &gCurvePoint.Len Then
         &pubKey = &pubKey | "SpaceDelimiter";
      End-If;
   End-For;

   Return &pubKey;

End-Function;

Function ECDH_SPrivateKeyGen(&publicKey As string, &pKey As array of number) Returns string;
   Local array of string &SPublicKey = Split(&publicKey, "SpaceDelimiter");
   Local integer &i, &j, &currSize, &totalSize;
   Local string &retStr, &retDimitStr;
   Local number &temp;
   &currSize = 0;
   &totalSize = 0;

   For &i = 1 To &pKey.Len
      &temp = Value(&SPublicKey [&i]) + &pKey [&i];
      &retStr = &retStr | Convert1016s(String(&temp));
   End-For;

   Return &retStr;
End-Function;

