Function getConsoleLabel(&product As string) Returns string
   Local string &label = "Unknown";
   Evaluate &product
   When "fw"

      &label = "ASP Console";

      Break;
   When "mob"
      &label = "PUX Console";

      Break;
   When "sso"
      &label = "Single Signon System Console";
      Break;
   When-Other
      Break;
   End-Evaluate;

   Return &label;

End-Function;

Function doConsoleFavorite(&product As string) Returns boolean

   Local ApiObject &portal = OpenPortal(%Portal);
   Local ApiObject &favs = &portal.Favorites;
   Local string &objName; /* portal registry object name */
   Local string &mcm; /* menu.component.market */

   Evaluate &product
   When "fw"
      &objName = "GS_FW_SYS_CONSOLE";
      &mcm = "GS_FW.GS_SYS_CONSOLE.GBL";
      Break;
   When "mob"
      &objName = "GS_MOBL_SYS_CONSOLE";
      &mcm = "GS_MOBL.GS_SYS_CONSOLE.GBL";
      Break;
   When "sso"
      &objName = "GS_SS_SYS_CONSOLE";
      &mcm = "GS_SINGLE_SIGNON.GS_SS_SYSTEM.GBL";
      Break;
   When-Other
      Return False;
      Break;
   End-Evaluate;

   Local string &label = getConsoleLabel(&product);
   Local ApiObject &fav = &favs.ItemByLabel(&label);

   If &fav <> Null Then
      If Not &favs.DeleteItem(&label) Then
         &portal.Close();
         Return False;
      End-If;
   End-If;

   &fav = &favs.InsertItem(&label, &objName);
   If &fav = Null Then
      &portal.Close();
      Return False;
   End-If;

   &fav.URL = "c" | &mcm | "?" | &product | "cmd=help";

   If Not &favs.Save() Then
      &portal.Close();
      Return False;
   End-If;

   &portal.Close();

   Return True;

End-Function;

Function iScript_ConsoleFavorite()

   Local Request &req = %Request;
   Local Response &resp = %Response;
   Local string &product = Unencode(&req.GetParameter("console"));
   Local string &msg = "The " | getConsoleLabel(&product) | " has been saved to your favorites.";
   Local boolean &favResult;

   If All(&product) Then
      &favResult = doConsoleFavorite(&product);
   End-If;

   If Not &favResult Then
      &msg = "The console was not saved as a favorite due to an error.";
   End-If;

   &resp.Write(&msg);

End-Function;

