/* import utilities */
import HMCR_FRAMEWORK:ServiceFramework:Utilities:ServiceManager;
import HMCR_FRAMEWORK:Utilities:wsdlDocument:*;

/* import service */
import HMCR_SERVICES:Registry:GetRegistryElement_v1_0:GetRegistryElement;

/* import types */
import HMCR_TYPES:RegistryTypes:RegistryElementType_v1_0:*;

Function IScript_Discover()

   Local HMCR_FRAMEWORK:Utilities:wsdlDocument:wsdlDocument &wsdlDoc;
   Local string &uuid, &wsdlType, &xmlString;
   Local ApiObject &PortalFolder, &Portal, &Session;

   &uuid = %Request.GetParameter("ID");
   &wsdlType = %Request.GetParameter("TYPE");

   /* Instantiate empty WSDL document */
   If &wsdlType = "2.0" Then
      &wsdlDoc = create HMCR_FRAMEWORK:Utilities:wsdlDocument:wsdlDocument20();
   Else
      &wsdlDoc = create HMCR_FRAMEWORK:Utilities:wsdlDocument:wsdlDocument11();
   End-If;

   &Session = %Session;
   &Portal = &Session.GetportalRegistry();
   &Portal.Open(&wsdlDoc.Common.interfaceRegistry);

   If All(&uuid) Then

      &PortalFolder = &Portal.FindFolderByName(&uuid);
      If &PortalFolder <> Null Then
         /* If Portal Folder Name was supplied - generate WSDL doc for the whole folder */
         &wsdlDoc.AddRegistryFolder(&uuid);
      Else
         /* If cref UUID was supplied - generate WSDL doc for this cref only */
         &wsdlDoc.AddRegistryElementNew(&uuid);
      End-If;

   Else
      /* Generate WSDL doc for the whole registry */
      &wsdlDoc.AddRegistryFolder(&wsdlDoc.Common.interfaceRegistryRootFolder);
   End-If;

   &xmlString = &wsdlDoc.toXMLstring();
   %Response.SetContentType("text/xml");
   %Response.Write(&xmlString);

End-Function;

