/******** WORLD CLOCK PAGELET ********/
Function IScript_WorldClock()

   &date = %Date;
   &Today = Substring(&date, 6, 2) | "/" | Substring(&date, 9, 2) | "/" | Substring(&date, 3, 2);
   &time = %Time;
   &gmt1 = Substring(&time, 1, 2);
   &gmt2 = Value(&gmt1) + 3;
   &gmt_hour = String(&gmt2);
   &rightnow = &gmt_hour | ":" | Substring(&time, 4, 2) | ":" | Substring(&time, 7, 2);

   %Response.Write(GetHTMLText(HTML.PORTAL_HP_DEMO_EBIZ_WORLDCLOCK, &Today, &rightnow));

End-Function;

