/*Global Rowset &gHRCDLastQuickSearchResultsRS;
Global array of any &gHRCDLastSrchResultObjsArray;*/
Global string &gHRCDLastSrchResultHTML;


Function IScript_srchHRCD
   /***************************************************/
   /* CODE TO BE CALLED INSIDE HOME/SEARCH PAGE CONTROLLER */
   /***************************************************/
   Local string &sSearchString = %Request.GetParameter("v");
   Local integer &i;
   Local string &sImgText, &sName, &sPhone, &sEmail;
   Local string &sLastSearchResultsHeaderHTML, &sLastSearchResultsHTML;
   Local string &sCurrentSearchResultHeaderHTML, &sCurrentSearchResultsHTML;
   Local array of string &arrPhone, &arrEmail;

   Local string &browser = %Request.BrowserType;
   Local string &ver = %Request.BrowserVersion;

   %Response.WriteLine("Browser: " | &browser | " (Version=" | &ver | ")<br><br><br>");

   If All(&sSearchString) Then


      /***********  SEARCH RESULTS - BEGIN **************/
      Local HRCD_COMPANY_DIRECTORY:UserSessionBase &oUserSession;
      Local HRCD_COMPANY_DIRECTORY:SEARCH:SearchUtility &oSearch;
      Local array of any &arrReturn;

      &oUserSession = create HRCD_COMPANY_DIRECTORY:UserSessionMOTB("");
      rem &oUserSession = create HRCD_COMPANY_DIRECTORY:UserSessionMOPH("");
      &oUserSession.setPreferences();
      &oUserSession.bAdvSearchAvailable = False;

      &oSearch = create HRCD_COMPANY_DIRECTORY:SEARCH:SearchUtility(&oUserSession);
      &oSearch.nMaxFetch = 101;
      &oSearch.nAbsoluteMaxFetch = &oSearch.nMaxFetch;

      &arrReturn = &oSearch.doQuickSearchRetObj(&sSearchString);

      /* search result labels 
      Local string &sLblName = &oSearch.sLabelName;
      Local string &sLblJobTitle = &oSearch.sLabelJobTitle;
      Local string &sLblDept = &oSearch.sLabelDept;
      Local string &sLblEmail = &oSearch.sLabelEmail;
      Local string &sLblPhone = &oSearch.sLabelPhone;
      Local string &sLblCompany = &oSearch.sLabelCompany;
      Local string &sLblLocation = &oSearch.sLabelLocation;
      Local string &sLblCountry = &oSearch.sLabelCountry;
      Local string &sLblCountryLoc = &oSearch.sLabelCountryLoc;
      Local string &sLblCountryBusn = &oSearch.sLabelCountryBusn;
       search result labels */

      /* Begin - This block is for Bryan's unit testing */
      If &arrReturn = Null Then
         &sCurrentSearchResultHeaderHTML = &sCurrentSearchResultsHTML | "<br>Null - No result for search string = " | &sSearchString | ".";
      Else

         Local integer &nSearchLoop = &arrReturn.Len;
         Local string &sPlusSign;
         If &arrReturn.Len > 0 Then
            If &arrReturn.Len >= &oSearch.nMaxFetch Then
               &nSearchLoop = &oSearch.nMaxFetch - 1;
               &sPlusSign = "+";
            End-If;
         End-If;

         &sCurrentSearchResultHeaderHTML = &sCurrentSearchResultsHTML | "<br>Search results returned: " | String(&nSearchLoop) | &sPlusSign | " people.<br><br>";
         For &i = 1 To &nSearchLoop
            &sName = &arrReturn [&i].getMyName( False)[2];
            &arrPhone = &arrReturn [&i].getMyPhone( True);
            &sPhone = &arrPhone [2];
            &arrEmail = &arrReturn [&i].getMyEmail( True);
            &sEmail = &arrEmail [2];

            &sImgText = "(" | String(&i) | ") " | &sName | ", " | &arrReturn [&i].getMyKeyValue()[2] | ", " | &arrReturn [&i].getMyJobTitle( True)[2] | ", " | &arrReturn [&i].getMyDepartment( True)[2] | ", " | &sPhone | ", " | &arrReturn [&i].getMyLocation( True)[2] | ", " | &sEmail;

            If All(&sImgText) Then
               &sCurrentSearchResultsHTML = &sCurrentSearchResultsHTML | "<img src=" | &arrReturn [&i].getMyPhotoURL() | " alt='" | &sImgText | "'" | " title='" | &sImgText | "'>";
               If Mod(&i, 5) = 0 Then
                  &sCurrentSearchResultsHTML = &sCurrentSearchResultsHTML | "<br>";
               End-If;
            End-If;
         End-For;
      End-If;

      %Response.WriteLine("SEARCH RESULTS:<br>" | &sCurrentSearchResultHeaderHTML | &sCurrentSearchResultsHTML);
      /***********  SEARCH RESULTS - END **************/




      /***********  LAST RESULTS - BEGIN **************/
      %Response.WriteLine("<br><br><br>--------------------------------------------------------------<br>");
      If All(&gHRCDLastSrchResultHTML) Then
         %Response.WriteLine("<br>PREVIOUS SEARCH RESULTS:<br>" | &gHRCDLastSrchResultHTML);
         &gHRCDLastSrchResultHTML = "";
      End-If;

      If All(&sCurrentSearchResultHeaderHTML) Or
            All(&sCurrentSearchResultsHTML) Then
         &gHRCDLastSrchResultHTML = &sCurrentSearchResultHeaderHTML | &sCurrentSearchResultsHTML;
      End-If;

      /***********  LAST RESULTS - END **************/



      /***********  RECENTLY VIEWED - BEGIN **************/
      %Response.WriteLine("<br><br><br>--------------------------------------------------------------<br>");
      %Response.WriteLine("<br>>RECENTLY VIEWED:<br>");
      rem Local Rowset &rsDummy = &oUserSession.getRecentlyViewedRowset();
      Local array of any &arrDummy = &oUserSession.getRecentlyViewedObjects();
