      Local array of any &arrChartFocusRow = &oChartServer.getFocusRowObjects(&sProfileTreeNodeId);


      Local string &sTestFocusNodeId = &oChartServer.sFocusTreeNodeId;
      Local boolean &bTestShowLinks = &oChartServer.bShowMyLinks;
      Local boolean &bTestShowStatement = &oChartServer.bShowMyStatement;

      /***********  CHART SERVER API - END **************/

   End-If;



