Function IScript_NewApplicant
   Local number &regcode;
   Local number &siteid;
   &regcode = Value(%Request.GetParameter("RegCode"));
   Local Record &rec;
   &rec = CreateRecord(Record.HRS_REGCODE_TBL);
   &rec.HRS_REGCODE.Value = &regcode;
   &rec.SelectByKey();
   If &rec.HRS_PERSON_ID.Value > 0 Then
      &postingredirectdata = create HRS_HROI_JOBBOARD:Data:PostingRedirectData();
      &postingredirectdata.PersonId = &rec.HRS_PERSON_ID.Value;
      SQLExec("SELECT HRS_SITE_ID FROM PS_HRS_AL_LOG_RES WHERE HRS_AL_LOG_RES_ID IN (SELECT MIN(A.HRS_AL_LOG_RES_ID) FROM PS_HRS_AL_LOG_RES A, PS_HRS_AL_PERS_VW B WHERE A.HRS_AL_LOG_ID=B.HRS_AL_LOG_ID and B.HRS_PERSON_ID=:1 and A.HRS_SITE_ID<>0)", &postingredirectdata.PersonId, &siteid);
   End-If;
   If None(&siteid) Then
      &siteid = Value(%Request.GetParameter("SiteId"));
      If None(&siteid) Then
         &rec = CreateRecord(Record.HRS_INST_I);
         &rec.SelectByKey();
         &siteid = &rec.HRS_SITE_ID.Value;
      End-If;
   End-If;

   Local string &url = GenerateComponentContentURL(%Portal, %Node, MenuName.HRS_HRAM, "GBL", Component.HRS_APP_SCHJOB, Page.HRS_APP_SCHJOB, "U") | "&FOCUS=Applicant&SiteId=" | &siteid;
   %Response.RedirectURL(&url);
End-Function;

Function GetPersonalizations(&PivotGridName As string, &BindVar As string) Returns string

   /* Retain Personalizations */
   Local Rowset &queryPersonalizations = CreateRowset(Record.PSPGQRYPRMPTPER);
   Local number &nqueryPersonalizations = 0;
   &nqueryPersonalizations = &queryPersonalizations.Fill("where PTPG_PGRIDNAME = :1  and PTPG_VIEWNAME = :2 and USERID = :3 and PTPG_UNIQPROMPFLD = :4", &PivotGridName, &PivotGridName | ".View", %UserId, &BindVar);
   If &nqueryPersonalizations > 0 Then
      Return &queryPersonalizations(1).PSPGQRYPRMPTPER.PTPG_QRYPROMPTVAL.Value;
   Else
      Return "";
   End-If;

End-Function;


Function PSURLtoNewWin(&URL As string) Returns string
   Local number &startPSHome;
   Local number &endPSHome;
   Local number &underscore;
   Local string &psHome;

   &startPSHome = Find("/psc/", &URL, 1);
   If (&startPSHome <= 0) Then
      &startPSHome = Find("/psp/", &URL, 1);
   End-If;

   If (&startPSHome <= 0) Then
      Return &URL;
   End-If;

   &startPSHome = &startPSHome + Len("/psc/");
   &endPSHome = Find("/", &URL, &startPSHome);
   &psHome = Substring(&URL, &startPSHome, &endPSHome - &startPSHome + 1);

   &underscore = 0;

   &PSHomeLen = Len(&psHome);

   For &i = &PSHomeLen To 1 Step - 1
      &underscore = Find("_", &psHome, &i);
      If (&underscore > 0) Then
         &strTest = Substring(&psHome, &underscore + 1, 1);
         If Not IsAlpha(&strTest) Then
            rem remove old newwin marker;
            &newwinHome = Substring(&psHome, 1, &underscore - 1);
            &newwinHome = &newwinHome | "_newwin/";
            Return Replace(&URL, &startPSHome, &PSHomeLen, &newwinHome);
         Else
            Break;
         End-If;
      End-If;
   End-For;

   &newwinHome = Substring(&psHome, 1, &PSHomeLen - 1);
   &newwinHome = &newwinHome | "_newwin/";
   &newwinHome = Substitute(&newwinHome, "_newwin_newwin/", "_newwin/");
   Return Replace(&URL, &startPSHome, &PSHomeLen, &newwinHome);

End-Function;

Function IScript_OverrideTilePrompts()

   /*Get Parameters from Request */
   Local string &mode = %Request.GetParameter("VMODE"); /* View Mode: T -Tile, P - PivotGridViewer */
   Local string &pgrid = %Request.GetParameter("PGRID"); /* Pivot Grid Name */
   Local string &cref = %Request.GetParameter("CREF"); /* Content Reference */

   /* Generate URL */
   Local string &url = GenerateComponentContentURL(%Portal, %Node, MenuName.PTPG_WIZ_MENU, "GBL", Component.PTPG_NUI, "", "");
   &url = PSURLtoNewWin(&url);
   &url = &url | "?pgName=" | &pgrid | "&pgViewName=" | &pgrid | ".View&CrefName=" | &cref;

   Local string &PerFromDate, &PerToDate;

   /* Append Additional Parameters based on individual report*/
   Evaluate &pgrid
   When = "HRS_PG_TTF_MY_ANALYTICS" /* Time to Fill Jobs */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=200&nHeight=165";
      End-If;

      /* Get Personalizations if any */
      &PerFromDate = GetPersonalizations("HRS_PG_TTF_MY_ANALYTICS", "1FROMDATE");
      If None(&PerFromDate) Then
         &PerFromDate = String(AddToDate(%Date, 0, - 3, 0));
      End-If;

      &PerToDate = GetPersonalizations("HRS_PG_TTF_MY_ANALYTICS", "1TODATE");
      If None(&PerToDate) Then
         &PerToDate = String(%Date);
      End-If;

      &url = &url | "&1FROMDATE=" | &PerFromDate | "&1TODATE=" | &PerToDate;
      Break;

   When = "HRS_PG_JO_AGE_MY_ANALYTICS" /* Job Opening Aging */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=200&nHeight=165";
      End-If;

      /* Get Personalizations if any */
      &PerFromDate = GetPersonalizations("HRS_PG_JO_AGE_MY_ANALYTICS", "1FROMDATE");
      If None(&PerFromDate) Then
         &PerFromDate = String(AddToDate(%Date, - 1, 0, 0));
      End-If;

      &url = &url | "&1FROMDATE=" | &PerFromDate;
      Break;

   When = "HRS_PG_INPRC_APPL" /* In Process Applicants */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=250&nHeight=165";
      End-If;
      /* Get Personalizations if any */
      &PerFromDate = GetPersonalizations("HRS_PG_INPRC_APPL", "FROM_DT");
      If None(&PerFromDate) Then
         &PerFromDate = String(AddToDate(%Date, - 1, 0, 0));
      End-If;

      &PerToDate = GetPersonalizations("HRS_PG_INPRC_APPL", "TO_DT");
      If None(&PerToDate) Then
         &PerToDate = String(%Date);
      End-If;

      Local string &IncludeAppliedStatus = GetPersonalizations("HRS_PG_INPRC_APPL", "YES_NO");

      If None(&IncludeAppliedStatus) Then
         &IncludeAppliedStatus = "N";
      End-If;

      &url = &url | "&FROM_DT=" | &PerFromDate | "&TO_DT=" | &PerToDate | "&YES_NO=" | &IncludeAppliedStatus;
      Break;

   When = "HRS_PG_JO_OC" /* Jobs Opened/Closed */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=500&nHeight=330";
      End-If;

      /* Get Personalizations if any */
      &PerFromDate = GetPersonalizations("HRS_PG_JO_OC", "FROM_DT");
      If None(&PerFromDate) Then
         &PerFromDate = String(AddToDate(%Date, - 1, 0, 0));
      End-If;

      &PerToDate = GetPersonalizations("HRS_PG_JO_OC", "TO_DT");
      If None(&PerToDate) Then
         &PerToDate = String(%Date);
      End-If;

      &url = &url | "&FROM_DT=" | &PerFromDate | "&TO_DT=" | &PerToDate;
      Break;

   End-Evaluate;

   %Response.RedirectURL(&url);

End-Function;

