Function IScript_setFolderFromTree
   Local HR_ABN:ABNFolderBase &oController;
   &oController = create HR_ABN:ABNFolderBase();
   Local boolean &bLoadFlyOuts = True;
   Local boolean &bLoadBreadcrumbs = True;
   Local boolean &bLoadOrgChart = True;
   Local boolean &bDisplayActions = False;
   Local boolean &bDisplayFocusSibings = True;
   Local boolean &bOpenWholeTree = True;
   Local boolean &bLoadTreeLeaves = False;
   Local boolean &bAllowDrillUpFromInitialNode = True;

   &oController.setFolderFromTree(&bLoadFlyOuts, &bLoadBreadcrumbs, &bLoadOrgChart, &bDisplayActions, &bDisplayFocusSibings, &bOpenWholeTree, &bLoadTreeLeaves, &bAllowDrillUpFromInitialNode);
End-Function;


Function IScript_setFolderFromRowset
   Local HR_ABN:ABNFolderBase &oController;
   &oController = create HR_ABN:ABNFolderBase();
   Local boolean &bLoadFlyOuts = True;
   Local boolean &bLoadBreadcrumbs = True;
   Local boolean &bLoadOrgChart = True;
   Local boolean &bDisplayActions = False;
   Local boolean &bDisplayFocusSibings = True;
   Local boolean &bOpenWholeTree = True;
   Local boolean &bLoadTreeLeaves = False;
   Local boolean &bAllowDrillUpFromInitialNode = True;
   &oController.setFolderFromRowset(&bLoadFlyOuts, &bLoadBreadcrumbs, &bLoadOrgChart, &bDisplayActions, &bDisplayFocusSibings, &bOpenWholeTree, &bLoadTreeLeaves, &bAllowDrillUpFromInitialNode);
End-Function;

import PTAI_COLLECTION:Collection;
import HR_GUIDED_SELF_SERVICE:Transaction;
import HR_GUIDED_SELF_SERVICE:Utilities:AG;

Declare Function GetText PeopleCode FUNCLIB_EP.HR_SSTEXT_KEY1 FieldFormula;

Function IScript_StartPage
   Local string &EmplID = %Request.GetParameter("EMPLID");
   Local number &EmplRCD = Value(%Request.GetParameter("EMPL_RCD"));
   Local number &EffSeq = Value(%Request.GetParameter("EFFSEQ"));
   Local string &Transaction_Name = %Request.GetParameter("HR_MSS_CT_NAME");
   Local string &RegRegion = %Request.GetParameter("REG_REGION");
   Local string &sAGTemplateID;
   Local Record &recSeq;
   Local integer &iCount, &x;
   Local date &AsOfDate = Date(%Request.GetParameter("ACTION_DT_SS"));


   Local Rowset &crsSeqVw = CreateRowset(Record.HR_MSS_CT_SEQVW);
   Local integer &fill = &crsSeqVw.Fill("WHERE HR_MSS_CT_NAME=:1 AND REG_REGION=:2", &Transaction_Name, &RegRegion);
   Local Rowset &rsQuestions = CreateRowset(Record.HR_MSS_CT_Q_DVW);

   Local Record &cfgRec = CreateRecord(Record.HR_MSS_CT_CFG);
   &cfgRec.HR_MSS_CT_NAME.Value = &Transaction_Name;
   /* Employee Reg Region */
   &cfgRec.REG_REGION.Value = &RegRegion;
   If &cfgRec.SelectByKeyEffDt(%Date) Then
      &sAGTemplateID = &cfgRec.PTAI_LIST_ID.Value;
   Else
      &sAGTemplateID = "GSS_SUOW01";
   End-If;


   &crsSeqVw.Sort(HR_MSS_CT_SEQVW.SEQUENCE, "A");

   For &x = 1 To &fill
      &recSeq = &crsSeqVw(&x).HR_MSS_CT_SEQVW;
      &iCount = &iCount + 1;
      If &iCount > 1 Then
         &rsQuestions.InsertRow(&rsQuestions.ActiveRowCount);
      End-If;
      &rsQuestions(&iCount).HR_MSS_CT_Q_DVW.TEXT_ID.Value = &recSeq.TEXT_ID.Value;
      &rsQuestions(&iCount).HR_MSS_CT_Q_DVW.HR_SSTEXT_TEXT.Value = GetText(&recSeq.TEXT_ID.Value, " ", " ", " ", " ", " ", " ", " ", " ", " ", " ");
      &rsQuestions(&iCount).HR_MSS_CT_Q_DVW.OBJECTOWNERID.Value = &recSeq.OBJECTOWNERID.Value;
      &rsQuestions(&iCount).HR_MSS_CT_Q_DVW.HR_SSTEXT_SUB_ID.Value = &recSeq.HR_SSTEXT_SUB_ID.Value;
      &rsQuestions(&iCount).HR_MSS_CT_Q_DVW.RESPONSE_YN.Value = &recSeq.DEFAULT_FLAG.Value;
      &rsQuestions(&iCount).HR_MSS_CT_Q_DVW.ACTION.Value = &recSeq.ACTION.Value;
      &rsQuestions(&iCount).HR_MSS_CT_Q_DVW.ACTION_REASON_SS.Value = &recSeq.ACTION_REASON.Value;
   End-For;


   /* Save the answers to the questions */
   Local Record &recAnswers = CreateRecord(Record.HR_MSS_CT_Q_ANS);
   For &x = 1 To &rsQuestions.ActiveRowCount
      &recAnswers.EMPLID.Value = &EmplID;
      &recAnswers.EMPL_RCD.Value = &EmplRCD;
      &recAnswers.ACTION_DT_SS.Value = &AsOfDate;
      &recAnswers.EFFSEQ.Value = &EffSeq;
      &recAnswers.REQUEST_DT.Value = %Date;
      &recAnswers.OBJECTOWNERID.Value = &rsQuestions(&x).HR_MSS_CT_Q_DVW.OBJECTOWNERID.Value;
      &recAnswers.HR_SSTEXT_SUB_ID.Value = &rsQuestions(&x).HR_MSS_CT_Q_DVW.HR_SSTEXT_SUB_ID.Value;
      &recAnswers.TEXT_ID.Value = &rsQuestions(&x).HR_MSS_CT_Q_DVW.TEXT_ID.Value;
      &recAnswers.RESPONSE_YN.Value = &rsQuestions(&x).HR_MSS_CT_Q_DVW.RESPONSE_YN.Value;
      &recAnswers.ACTION.Value = &rsQuestions(&x).HR_MSS_CT_Q_DVW.ACTION.Value;
      &recAnswers.ACTION_REASON_SS.Value = &rsQuestions(&x).HR_MSS_CT_Q_DVW.ACTION_REASON_SS.Value;
      &recAnswers.SEQUENCE.Value = &x;
      &recAnswers.PNLNAME.Value = &crsSeqVw(&x).HR_MSS_CT_SEQVW.PNLNAME.Value;
      &recAnswers.Insert();
   End-For;

   Local string &market = %Market;
   If None(&market) Then
      &market = "GBL";
   End-If;

   rem Local array of array of string &qs = CreateArray(CreateArray("TRANS_NAME", &Transaction_Name), CreateArray("HCRCS_MSS", "Y"));
   rem SetTransferAttributes( False, False, "", "", &qs);
   /* Bug 24591815 - change URL generation call to prevent problems exiting activity guide */
   rem Local string &returnUrl = GenerateComponentPortalURL("EMPLOYEE", %Node, MenuName.NUI_FRAMEWORK, &market, Component.PT_AGSTARTPAGE_NUI, Page.PT_AGSTARTPAGE_NUI, "U");
   Local string &returnUrl = GenerateComponentContentURL("EMPLOYEE", %Node, MenuName.NUI_FRAMEWORK, &market, Component.PT_AGSTARTPAGE_NUI, Page.PT_AGSTARTPAGE_NUI, "U");
   /* end Bug 24591815 */
   &returnUrl = &returnUrl | "&CONTEXTIDPARAMS=TEMPLATE_ID:" | &sAGTemplateID | "&CONTEXTIDPARAMS=ACTION_DT_SS:" | DateTimeToLocalizedString(&AsOfDate, "yyyy-MM-dd");
   &returnUrl = &returnUrl | "&CONTEXTIDPARAMS=EMPLID:" | &EmplID;
   &returnUrl = &returnUrl | "&CONTEXTIDPARAMS=EMPL_RCD:" | String(&EmplRCD);
   &returnUrl = &returnUrl | "&CONTEXTIDPARAMS=EFFSEQ:" | String(&EffSeq);
   &returnUrl = &returnUrl | "&CONTEXTIDPARAMS=HR_MSS_CT_NAME:" | &Transaction_Name;
   /* Activity guide cannot accept a blank parameter since its used as context data, thus pass in NONE if using a blank reg region */
   If All(&RegRegion) Then
      &returnUrl = &returnUrl | "&CONTEXTIDPARAMS=REG_REGION:" | &RegRegion;
   Else
      &returnUrl = &returnUrl | "&CONTEXTIDPARAMS=REG_REGION:NONE";
   End-If;

   %Response.RedirectURL(&returnUrl | "&AgInHistory=N"); /*32750398- Suppress the AG as back button*/

End-Function;

import HR_OBD_CONTROLLER:Utility:*;
import PTAI_ACTION_ITEMS:List;
import PTAI_ACTION_ITEMS:ActionItem;
import PTAI_ACTION_ITEMS:Constants;

Global boolean &g_bReturnToOBDDashboard, &g_bOBDReturnToLandingPage;
Global boolean &g_ViewAs_ListView;
Global string &g_OBD_CreateInstance; /* OBD security */

/* This IScript Function is triggered by the OnBoarding Tile selection */

Function IScript_OBDActivityLauncher
   Local string &url, &sMarket;

   Local Rowset &rsAGTemplate, &rsAGInstance, &rsAsgnTemplates;
   Local string &sAGTemplateID, &strID, &emplid, &emplRcd, &parmEmplRcd;
   Local number &Count;
   Local HR_OBD_CONTROLLER:Utility:TemplateAssignment &TemplAssign = create HR_OBD_CONTROLLER:Utility:TemplateAssignment();
   /* For Landing Page enhancement, check if Empl Record is passed in the URL and if so only get templates for that one job */
   &parmEmplRcd = %Request.GetParameter("EMPL_RCD");

   If &parmEmplRcd = "" Then
      &g_bOBDReturnToLandingPage = False; /* bug 38425611 */
      &rsAsgnTemplates = &TemplAssign.GetOBDTemplates(%EmployeeId);
   Else
      &g_bOBDReturnToLandingPage = True; /* bug 38425611 */
      Local number &numEmplRcd = Value(&parmEmplRcd);
      &rsAsgnTemplates = &TemplAssign.GetSingleOBDTemplate(%EmployeeId, &numEmplRcd);
   End-If;

   /* If there is only one template for person, launch the AG directly */
   If &rsAsgnTemplates.ActiveRowCount = 1 And
         All(&rsAsgnTemplates(1).HR_OBD_TMA_WRK.AGC_LIST_ID.Value) Then

      &emplid = &rsAsgnTemplates(1).HR_OBD_TMA_WRK.EMPLID.Value;
      &emplRcd = &rsAsgnTemplates(1).HR_OBD_TMA_WRK.EMPL_RCD.Value;

      &sAGTemplateID = &rsAsgnTemplates(1).HR_OBD_TMA_WRK.AGC_LIST_ID.Value; /* template id */
      rem WriteToLog(1, "&sAGTemplateID:" | &sAGTemplateID | "---" | &rsAsgnTemplates(1).HR_OBD_TMA_WRK.PTAI_LIST_STATUS.Value);
      If ((&rsAsgnTemplates(1).HR_OBD_TMA_WRK.PTAI_LIST_STATUS.Value <> "CP") And
            /* begin bug 28217752 */
            (&rsAsgnTemplates(1).HR_OBD_TMA_WRK.PTAI_LIST_STATUS.Value <> "CA")) Then
         /* end bug 28217752 */
         &g_bReturnToOBDDashboard = True;

         /* PreBoarding: change active setting for steps if EE is current */
         rem SetTracePC(3596);
         If All(&rsAsgnTemplates(1).HR_OBD_TMA_WRK.PTAI_LIST_ID.Value) Then /* instance exists */
            /* EE is current */
            If &rsAsgnTemplates(1).HR_OBD_TMA_WRK.EFFDT.Value <= %Date Then
               Local PTAI_ACTION_ITEMS:List &list;
               Local PTAI_ACTION_ITEMS:ActionItem &item;
               Local PTAI_ACTION_ITEMS:Constants &PTAI_CONSTANTS = create PTAI_ACTION_ITEMS:Constants();
               Local array of string &arrItems;
               Local boolean &bSuccess, &bSetFocus, &bOBDStepsActivated;
               Local string &strListId, &strItemId, &parm, &strParentListId, &strCurrItemId, &strFocusItemId;
               Local Rowset &rsSteps;
               Local Record &recTrigger;
               Local number &i, &j, &cnt;

               &list = create PTAI_ACTION_ITEMS:List();
               &strListId = &rsAsgnTemplates(1).HR_OBD_TMA_WRK.PTAI_LIST_ID.Value;
               &list.open(&strListId);
               rem &strCurrItemId = &list.getCurrentItem();
               &arrItems = &list.getActionItems();

               &strParentListId = &list.ParentTemplate;
               /* get the Category Parms for each step */
               &rsSteps = CreateRowset(Record.HR_OBD_STEPS_VW);
               &cnt = &rsSteps.Fill("where AGC_LIST_ID = :1", &strParentListId);

               If &cnt > 0 Then
                  &bSetFocus = False;
                  &bOBDStepsActivated = False;

                  If &arrItems.Len > 0 Then
                     For &i = 1 To &arrItems.Len
                        &item = create PTAI_ACTION_ITEMS:ActionItem();
                        &item.open(&arrItems [&i]);

                        /* activate Summary step if EE is current */
                        If &item.ServiceId = "HC_AGC_SUMMARY_FL" Then
                           If Not &item.IsActive Then
                              &item.IsActive = True;
                              &bSuccess = &item.save();
                           End-If;
                        Else
                           For &j = 1 To &rsSteps.ActiveRowCount
                              If &item.OriginId = &rsSteps(&j).HR_OBD_STEPS_VW.AGC_ACTION_ITEM_ID.Value Then
                                 If &rsSteps(&j).HR_OBD_STEPS_VW.AGC_PARAM_NAME.Value = "PROCESS_TYPE" Then
                                    &parm = &rsSteps(&j).HR_OBD_STEPS_VW.AGC_PARAM_VALUE.Value;
                                 Else
                                    &parm = "B";
                                 End-If;

                                 Evaluate &parm
                                    /* PROCESS_TYPE=P, complete - inactive */
                                 When "P"
                                    If (&item.Status = &PTAI_CONSTANTS.STATUS_COMPLETED Or
                                          Not &item.Required) And
                                          &item.IsActive Then
                                       &item.IsActive = False;
                                       &bSuccess = &item.save();
                                       &bSetFocus = True;
                                    End-If;
                                    Break;
                                    /* PROCESS_TYPE=O - activate */
                                 When "O"
                                    If Not &item.IsActive Then
                                       &item.IsActive = True;
                                       &bSuccess = &item.save();
                                       &bSetFocus = True;
                                       &bOBDStepsActivated = True;
                                    End-If;
                                    Break;
                                 End-Evaluate;

                                 Break;
                              End-If;
                           End-For; /* AGC configuration */
                        End-If;

                        /* get first active step */
                        If &item.IsActive And
                              None(&strFocusItemId) Then
                           &strFocusItemId = &item.ItemId;
                        End-If;

                     End-For; /* AG items */
                  End-If;

                  /* reset focus to first active step if any steps have been activated/inactivated */
                  If &bSetFocus And
                        All(&strFocusItemId) Then
                     Local HR_OBD_CONTROLLER:Utility:AGLauncher &oLauncher = create HR_OBD_CONTROLLER:Utility:AGLauncher();
                     &oLauncher.setStepFocus(&strListId, &strFocusItemId);

                  End-If;

               End-If; /* OnBoarding-only steps exist */

               /* update trigger for EE that is now current to indicate that notification is not required. */
               If &bOBDStepsActivated Then
                  &recTrigger = CreateRecord(Record.HR_OBD_TRIGGER);
                  &recTrigger.EMPLID.Value = &emplid;
                  &recTrigger.EMPL_RCD.Value = &emplRcd;
                  If &recTrigger.SelectByKey() Then
                     If &recTrigger.HR_OBD_NOTIFY.Value = "Y" Then
                        &recTrigger.HR_OBD_NOTIFY.Value = "N";
                        &recTrigger.Update();
                     End-If;
                  End-If;
               End-If;

               rem SetTracePC(0);
               /* End PreBoarding */

            End-If; /* EE is current */
         End-If; /* all items */

         /* bug 36853072: ensure creation of a new instance is valid */
         /* if an instance does not exist, then set the global */
         If None(&rsAsgnTemplates(1).HR_OBD_TMA_WRK.PTAI_LIST_ID.Value) Then
            &g_OBD_CreateInstance = "Y";
         End-If;

         /* always pass template id - Tools determines the instance id based on template id and context data */
         (create HR_OBD_CONTROLLER:Utility:AGLauncher()).Execute(&sAGTemplateID, &rsAsgnTemplates(1).HR_OBD_TMA_WRK.EMPLID.Value, &rsAsgnTemplates(1).HR_OBD_TMA_WRK.EMPL_RCD.Value);
         Return;

      End-If;
   End-If;

   /* There are multiple templates or instances, launch the Activity page in Card view */
   &g_ViewAs_ListView = False;
   &g_bReturnToOBDDashboard = False;

   &sMarket = %Market;
   If &sMarket = "" Then
      &sMarket = "GBL";
   End-If;

   &url = GenerateComponentContentURL(%Portal, %Node, MenuName.HR_OBD_FL, &sMarket, Component.HR_OBD_ACTIVITY_FL, Page.HR_OBD_ACTIVITY_FL, "U");

   %Response.RedirectURL(&url);

End-Function;

Function GetPersonalizations(&PivotGridName As string, &BindVar As string) Returns string

   /* Retain Personalizations */
   Local Rowset &queryPersonalizations = CreateRowset(Record.PSPGQRYPRMPTPER);
   Local number &nqueryPersonalizations = 0;
   &nqueryPersonalizations = &queryPersonalizations.Fill("where PTPG_PGRIDNAME = :1  and PTPG_VIEWNAME = :2 and USERID = :3 and PTPG_UNIQPROMPFLD = :4", &PivotGridName, &PivotGridName | ".View", %UserId, &BindVar);
   If &nqueryPersonalizations > 0 Then
      Return &queryPersonalizations(1).PSPGQRYPRMPTPER.PTPG_QRYPROMPTVAL.Value;
   Else
      Return "";
   End-If;

End-Function;


Function PSURLtoNewWin(&URL As string) Returns string
   Local number &startPSHome, &endPSHome, &underscore, &PSHomeLen;
   Local integer &i;
   Local string &psHome, &strTest, &newwinHome;

   &startPSHome = Find("/psc/", &URL, 1);
   If (&startPSHome <= 0) Then
      &startPSHome = Find("/psp/", &URL, 1);
   End-If;

   If (&startPSHome <= 0) Then
      Return &URL;
   End-If;

   &startPSHome = &startPSHome + Len("/psc/");
   &endPSHome = Find("/", &URL, &startPSHome);
   &psHome = Substring(&URL, &startPSHome, &endPSHome - &startPSHome + 1);

   &underscore = 0;

   &PSHomeLen = Len(&psHome);

   For &i = &PSHomeLen To 1 Step - 1
      &underscore = Find("_", &psHome, &i);
      If (&underscore > 0) Then
         &strTest = Substring(&psHome, &underscore + 1, 1);
         If Not IsAlpha(&strTest) Then
            rem remove old newwin marker;
            &newwinHome = Substring(&psHome, 1, &underscore - 1);
            &newwinHome = &newwinHome | "_newwin/";
            Return Replace(&URL, &startPSHome, &PSHomeLen, &newwinHome);
         Else
            Break;
         End-If;
      End-If;
   End-For;

   &newwinHome = Substring(&psHome, 1, &PSHomeLen - 1);
   &newwinHome = &newwinHome | "_newwin/";
   &newwinHome = Substitute(&newwinHome, "_newwin_newwin/", "_newwin/");
   Return Replace(&URL, &startPSHome, &PSHomeLen, &newwinHome);

End-Function;

Function IScript_OverrideTilePrompts()

   /* Personalization Variables */
   Local string &FromDate, &ToDate, &RegRegion, &BusnUnit, &Company, &DivType;

   /*Get Parameters from Request */
   Local string &mode = %Request.GetParameter("VMODE"); /* View Mode: T -Tile, P - PivotGridViewer */
   Local string &pgrid = %Request.GetParameter("PGRID"); /* Pivot Grid Name */
   Local string &cref = %Request.GetParameter("CREF"); /* Content Reference */

   /* Generate URL */
   Local string &url = GenerateComponentContentURL(%Portal, %Node, MenuName.PTPG_WIZ_MENU, "GBL", Component.PTPG_NUI, "", "");
   &url = PSURLtoNewWin(&url);
   &url = &url | "?pgName=" | &pgrid | "&pgViewName=" | &pgrid | ".View&CrefName=" | &cref;

   /* Append Additional Parameters based on individual report*/
   Evaluate &pgrid
   When = "HR_PG_HC_CURRNT_ADMIN" /* Current Headcount */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=200&nHeight=165";
      End-If;

      /* Get Personalizations if any */
      &BusnUnit = GetPersonalizations("HR_PG_HC_CURRNT_ADMIN", "1BUSINESS_UNIT");
      If None(&BusnUnit) Then
         /* Check under old bind name */
         &BusnUnit = GetPersonalizations("HR_PG_HC_CURRNT_ADMIN", "BUS_UNIT");
      End-If;
      If None(&BusnUnit) Then
         SQLExec("select A.BUSINESS_UNIT from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &BusnUnit);
      End-If;

      &Company = GetPersonalizations("HR_PG_HC_CURRNT_ADMIN", "2COMPANY");
      If None(&Company) Then
         /* Check under old bind name */
         &Company = GetPersonalizations("HR_PG_HC_CURRNT_ADMIN", "COMPANY");
      End-If;
      If None(&Company) Then
         SQLExec("select A.COMPANY from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &Company);
      End-If;

      &url = &url | "&1BUSINESS_UNIT=" | &BusnUnit | "&2COMPANY=" | &Company;
      Break;

   When = "HR_PG_HC_MOVMNT_ADMIN" /* Headcount Movement */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=200&nHeight=165";
      End-If;

      /* Get Personalizations if any */
      &BusnUnit = GetPersonalizations("HR_PG_HC_MOVMNT_ADMIN", "1BUSINESS_UNIT");
      If None(&BusnUnit) Then
         /* Check under old bind name */
         &BusnUnit = GetPersonalizations("HR_PG_HC_MOVMNT_ADMIN", "BUS_UNIT");
      End-If;
      If None(&BusnUnit) Then
         SQLExec("select A.BUSINESS_UNIT from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &BusnUnit);
      End-If;

      &Company = GetPersonalizations("HR_PG_HC_MOVMNT_ADMIN", "2COMPANY");
      If None(&Company) Then
         /* Check under old bind name */
         &Company = GetPersonalizations("HR_PG_HC_MOVMNT_ADMIN", "COMPANY");
      End-If;
      If None(&Company) Then
         SQLExec("select A.COMPANY from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &Company);
      End-If;

      &FromDate = GetPersonalizations("HR_PG_HC_MOVMNT_ADMIN", "3FROM_DT");
      If None(&FromDate) Then
         /* Check under old bind name */
         &FromDate = GetPersonalizations("HR_PG_HC_MOVMNT_ADMIN", "FROM_DT");
      End-If;
      If None(&FromDate) Then
         &FromDate = String(AddToDate(%Date, - 1, 0, 0));
      End-If;

      &ToDate = GetPersonalizations("HR_PG_HC_MOVMNT_ADMIN", "4TO_DT");
      If None(&ToDate) Then
         /* Check under old bind name */
         &ToDate = GetPersonalizations("HR_PG_HC_MOVMNT_ADMIN", "TO_DT");
      End-If;
      If None(&ToDate) Then
         &ToDate = String(%Date);
      End-If;

      &url = &url | "&1BUSINESS_UNIT=" | &BusnUnit | "&2COMPANY=" | &Company | "&3FROM_DT=" | &FromDate | "&4TO_DT=" | &ToDate;
      Break;

   When = "HR_PG_ED_LVL_ADM" /* Highest Education Level */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=200&nHeight=165";
      End-If;

      /* Get Personalizations if any */
      &RegRegion = GetPersonalizations("HR_PG_ED_LVL_ADM", "1REG_REGION");
      If None(&RegRegion) Then
         SQLExec("select A.REG_REGION from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &RegRegion);
      End-If;

      &BusnUnit = GetPersonalizations("HR_PG_ED_LVL_ADM", "2BUSINESS_UNIT");
      If None(&BusnUnit) Then
         SQLExec("select A.BUSINESS_UNIT from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &BusnUnit);
      End-If;

      &FromDate = GetPersonalizations("HR_PG_ED_LVL_ADM", "3FROM_DT");
      If None(&FromDate) Then
         &FromDate = String(AddToDate(%Date, - 1, 0, 0));
      End-If;

      &ToDate = GetPersonalizations("HR_PG_ED_LVL_ADM", "4TO_DT");
      If None(&ToDate) Then
         &ToDate = String(%Date);
      End-If;

      &url = &url | "&1REG_REGION=" | &RegRegion | "&2BUSINESS_UNIT=" | &BusnUnit | "&3FROM_DT=" | &FromDate | "&4TO_DT=" | &ToDate;
      Break;

   When = "HR_PG_WF_DIV_ADM" /* Diversity Overview */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=500&nHeight=400";
      End-If;

      /* Get Personalizations if any */
      &RegRegion = GetPersonalizations("HR_PG_WF_DIV_ADM", "1REG_REGION");
      If None(&RegRegion) Then
         SQLExec("select A.REG_REGION from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &RegRegion);
      End-If;

      &BusnUnit = GetPersonalizations("HR_PG_WF_DIV_ADM", "2BUSINESS_UNIT");
      If None(&BusnUnit) Then
         SQLExec("select A.BUSINESS_UNIT from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &BusnUnit);
      End-If;

      &FromDate = GetPersonalizations("HR_PG_WF_DIV_ADM", "3FROM_DT");
      If None(&FromDate) Then
         &FromDate = String(AddToDate(%Date, - 1, 0, 0));
      End-If;

      &ToDate = GetPersonalizations("HR_PG_WF_DIV_ADM", "4TO_DT");
      If None(&ToDate) Then
         &ToDate = String(%Date);
      End-If;

      &url = &url | "&1REG_REGION=" | &RegRegion | "&2BUSINESS_UNIT=" | &BusnUnit | "&3FROM_DT=" | &FromDate | "&4TO_DT=" | &ToDate;
      Break;

   When = "HR_PG_WF_DIV_TYPE_ADM" /* Diversity Analysis */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=500&nHeight=165";
      End-If;

      /* Get Personalizations if any */
      &DivType = GetPersonalizations("HR_PG_WF_DIV_TYPE_ADM", "1HR_DIV_TYPE");
      If None(&DivType) Then
         &DivType = "A";
      End-If;

      &RegRegion = GetPersonalizations("HR_PG_WF_DIV_TYPE_ADM", "2REG_REGION");
      If None(&RegRegion) Then
         SQLExec("select A.REG_REGION from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &RegRegion);
      End-If;

      &BusnUnit = GetPersonalizations("HR_PG_WF_DIV_TYPE_ADM", "3BUSINESS_UNIT");
      If None(&BusnUnit) Then
         SQLExec("select A.BUSINESS_UNIT from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &BusnUnit);
      End-If;

      &FromDate = GetPersonalizations("HR_PG_WF_DIV_TYPE_ADM", "4FROM_DT");
      If None(&FromDate) Then
         &FromDate = String(AddToDate(%Date, - 1, 0, 0));
      End-If;

      &ToDate = GetPersonalizations("HR_PG_WF_DIV_TYPE_ADM", "5TO_DT");
      If None(&ToDate) Then
         &ToDate = String(%Date);
      End-If;

      &url = &url | "&1HR_DIV_TYPE=" | &DivType | "&2REG_REGION=" | &RegRegion | "&3BUSINESS_UNIT=" | &BusnUnit | "&4FROM_DT=" | &FromDate | "&5TO_DT=" | &ToDate;
      Break;

   When = "HR_PG_POS_STATUS_ADM" /* Position Status */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=500&nHeight=165";
      End-If;

      /* Get Personalizations if any */
      &BusnUnit = GetPersonalizations("HR_PG_POS_STATUS_ADM", "1BUSINESS_UNIT");
      If None(&BusnUnit) Then
         SQLExec("select A.BUSINESS_UNIT from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &BusnUnit);
      End-If;

      &url = &url | "&1BUSINESS_UNIT=" | &BusnUnit;
      Break;

   When = "HR_PG_WF_TRNOVR_ADM" /* Workforce Turnover Analysis */
      If &mode = "T" Then
         &url = &url | "&PTPPB_GROUPLET_ID=" | &cref | "&tW=2&tH=1&ICDoModal=1&ICGrouplet=1&ICAction=PTS_CHART_GB$hmodal&nWidth=200&nHeight=165";
      End-If;

      /* Get Personalizations if any */
      &BusnUnit = GetPersonalizations("HR_PG_WF_TRNOVR_ADM", "1BUSINESS_UNIT");
      If None(&BusnUnit) Then
         SQLExec("select A.BUSINESS_UNIT from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &BusnUnit);
      End-If;

      &Company = GetPersonalizations("HR_PG_WF_TRNOVR_ADM", "2COMPANY");
      If None(&Company) Then
         SQLExec("select A.COMPANY from PS_OPR_DEF_TBL_HR A, PSOPRDEFN B WHERE A.OPRCLASS = B.OPRCLASS AND B.OPRID =:1", %UserId, &Company);
      End-If;

      &FromDate = GetPersonalizations("HR_PG_WF_TRNOVR_ADM", "3FROM_DT");
      If None(&FromDate) Then
         &FromDate = String(AddToDate(%Date, - 1, 0, 0));
      End-If;

      &ToDate = GetPersonalizations("HR_PG_WF_TRNOVR_ADM", "4TO_DT");
      If None(&ToDate) Then
         &ToDate = String(%Date);
      End-If;

      &url = &url | "&1BUSINESS_UNIT=" | &BusnUnit | "&2COMPANY=" | &Company | "&3FROM_DT=" | &FromDate | "&4TO_DT=" | &ToDate;
      Break;

   End-Evaluate;

   %Response.RedirectURL(&url);

End-Function;

Function IScript_GoToComponent()

   &Response = %Response;
   &Request = %Request;
   &Menu = &Request.GetParameter("Menu");
   &Component = &Request.GetParameter("Component");
   &URI = %Request.RequestURI;
   &QS = %Request.QueryString;

   &TEST = &URI | "?" | &QS;

   /* removed this string from the statement below and added the URI. iclientservlet.jrun*/

   &ComponentUrl = &URI | "?ICType=Panel&Menu=" | &Menu | "&Market=GBL&PanelGroupName=" | &Component;

   %Response.RedirectURL(&ComponentUrl);

End-Function;

