   /* Build Go To URL */
   REM 14279813 &str_URL = GenerateComponentContentURL(%Portal, &CREF.CONTENTPROVIDER, @("MENUNAME." | &str_Menuname), %Market, @("COMPONENT." | &str_Pnlgrpname), @("PAGE." | &str_Pagename), "U") | "&EE=" | &g_strTSEmplID;
