REM ***************************************************************************************;
REM Function:       GetAccessibility                                                        ;
REM Purpose:        Get The accessibility information for the user                         ;
REM Inputs:                                                                                 ;
REM Output:                                                                                 ;
REM ***************************************************************************************;
Function GetAccessibility() Returns integer
   Local integer &ret;
   Local string &MyAccess;
   &MyAccess = GetUserOption("PPTL", "ACCESS");
   &ret = 0;
   If (&MyAccess <> "N") Then
      &ret = 1;
   Else
      &ret = 0;
   End-If;
   Return &ret;
End-Function;

REM ***************************************************************************************;
REM Function:       GetRENJSMSG                                                         ;
REM Purpose:        Get all messages in kn.js                                            ;
REM Inputs:                                                                                 ;
REM Output:                                                                                 ;
REM ***************************************************************************************;
Function GetRENJSMSG() Returns string
   Local string &ret;
   If (All(&msgRENJS)) Then
      Return &msgRENJS;
   End-If;
   Local string &msgRENJS1 = MsgGetExplainText(162, 1810, "Message Not Found");
   Local string &msgRENJS2 = MsgGetExplainText(162, 1811, "Message Not Found");
   Local string &msgRENJS3 = MsgGetExplainText(162, 1812, "Message Not Found");
   Local string &msgRENJS4 = MsgGetExplainText(162, 1813, "Message Not Found");
   &ret = GetHTMLText(HTML.MCF_RENJSMSG, &msgRENJS1, &msgRENJS2, &msgRENJS3, &msgRENJS4);
   &msgRENJS = &ret;
   Return &ret;
End-Function;

REM ***************************************************************************************;
REM Function:       GetStyleSheetName                                                      ;
REM Purpose:        Set the stylesheet local vars                                          ;
REM Inputs:                                                                                ;
REM Output:                                                                                ;
REM ***************************************************************************************;
Function GetStyleSheetName
   Local string &strSheetName;

   rem Default to the PSSTYLEDEF_FMODE stylesheet if it is available;
   SQLExec("SELECT STYLESHEETNAME from PSSTYLSHEETDEFN where STYLESHEETNAME like 'PSSTYLEDEF_FMODE'", &strSheetName);
   If (&strSheetName = "") Then
      SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strSheetName);
   End-If;

   &cssPTMCFDEF = %Response.GetStyleSheetURL(&strSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strSheetName);

End-Function;


REM ***************************************************************************************;
REM Function:       IScript_Main                                  ;
REM Purpose:        Generate HTML page for MCF Console                                     ;
REM Inputs:                                               ;
REM Output:                                                                      ;
REM ***************************************************************************************;
Function IScript_Main()
   Local boolean &isMCFConfigured;
   Local string &TOOLBAR1URL;
   Local string &CTIURL;
   Local string &agentID;
   Local string &agentQueue;
   Local string &agentConfigID;
   Local string &userAgent;
   Local number &findIndex;

   GetStyleSheetName();

   &SQL = CreateSQL("select MCFUQAGENTID from PSMCFUQAGENTQ WHERE MCFUQAGENTID = :1", %UserId);
   If (&SQL.Fetch(&tmpAgentID)) Then
      &isMCFConfigured = True;
   Else
      &isMCFConfigured = False;
   End-If;
   &SQL.Close();
   &titleMCFC = MsgGetText(162, 1166, "Message Not Found");
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &TOOLBAR1URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_Toolbar");
   &CTIURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Extension");

   SQLExec("select PT_CTI_AGENTID, PT_CTI_QUEUE, PT_CTI_CONFIGID from PS_PT_CTI_AGENT A where OPRID = :1 AND EFFDT = (SELECT MAX(EFFDT) FROM PS_PT_CTI_AGENT B WHERE A.OPRID= B.OPRID AND EFFDT <= %CurrentDateIn)", %UserId, &agentID, &agentQueue, &agentConfigID);

   &typeBrowser = %Request.BrowserType;
   If (&agentID = "" And
         Not &isMCFConfigured) Then
      rem neither CTI nor MCF agent;
      &msgTitle = MsgGetText(162, 604, "Message Not Found");
      &msgWarning = MsgGetText(162, 1318, "Message Not Found");
      &OKMessage = MsgGetText(162, 2100, "Message Not Found");
      &HTML = GetHTMLText(HTML.MCF_MESSAGE, &msgTitle, &cssPTMCFDEF, &psDomain, &msgWarning, &OKMessage);
      %Response.Write(&HTML);
      Return;
   End-If;

   If (&agentID = "" And
         &isMCFConfigured) Then
      %Response.RedirectURL(&TOOLBAR1URL);
      Return;
   End-If;

   If ( Not &isMCFConfigured And
         &agentID <> "") Then
      rem CTI only agent;
      %Response.RedirectURL(&CTIURL);
      Return;
   End-If;

   If (&isMCFConfigured And
         &agentID <> "") Then
      rem both MCF and CTI agent;
      &heightCTI = 45;
      If (&typeBrowser = "NETSCAPE") Then
         &userAgent = %Request.GetHeader("User-Agent");
         &findIndex = Find("Netscape", &userAgent);
         If (Find("7.", &userAgent, &findIndex) <> 0) Then
            REM 577575003 - work around Netscape 7 bug on frameset;
            &heightCTI = 94;
         Else
            &heightCTI = 56;
