   GetStyleSheetName();

   &topWindow = 50;
   &leftWindow = 100;
   &widthWindow = 400;
   &heightWindow = 510;

   &SQL = CreateSQL("select MCFUQACTIMOUT_MINS,MCFCHATSESSTO FROM PS_MCFUQTASKCFG WHERE MCFUQTASKTYPE= :1", "CH");
   If (&SQL.Fetch(&tmpActionTimeout, &tmpNoActivity)) Then
      &maxWaitingDuration = &tmpActionTimeout * 60;
      &maxNoActivityDuration = &tmpNoActivity * 60;
   End-If;
   &SQL.Close();

   &SQL = CreateSQL("select MSGNAME, MCFMSGID, MESSAGE_DESCR from PS_MCFAGNTMSG WHERE MCFUQAGENTID = :1", %UserId);
   While &SQL.Fetch(&msgName, &tmpMsgId, &msgDesc)
      &allCannedMessages = &allCannedMessages | GetHTMLText(HTML.MCF_OPTION, &msgDesc, &msgName);
      Evaluate &tmpMsgId
      When = "A"
         &msgAccept = &msgDesc;
