   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");

   &HTML = GetHTMLText(HTML.MCF_A2ACHAT, RTrim(%UserId), &urlRensrv, &psHome, &psDomain, &partyAgentID, &cmd, &cssPTSTYLEDEF, &cssPTMCFDEF, &labelElapse, &labelConversation, &labelInput, &labelButtonSend, &labelButtonClose, &topWindow, &leftWindow, &widthWindow, &heightWindow, &msgAccept, &msgPleaseWait, &msgSessionClosed, &msgEnd, &msgDeny, &msgAbandon, &msgRensrvDown, &msgRensrvUp, &urlCloseSession, &msgMsgOverSize, &msgNoActivityTimeout, &maxNoActivityDuration, &maxWaitingDuration, &msgNoAnswer, &msgInputArea, &urlTracer, &traceLevel, &ps_uniqueid, &msgMSError, &msgBuddyLeft, GetRENJSMSG(), &tooltipsendmsg, &tooltipexitchat);
   %Response.Write(&HTML);
End-Function;

