Function IScript_CustomerChatInput()
   Local string &msgAgentLeft;

   GetStyleSheetName();

   &psHome = GetPSHome();
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   Local number &MCF_CompatabilityMode;

   &sys = GetJavaClass("java.lang.System");
   try
      &MCF_CompatabilityMode = &sys.getProperty("MCF_CompatabilityMode");
   catch Exception &e
      &MCF_CompatabilityMode = 1;
   end-try;
   &urlRen = Unencode(%Request.GetParameter("renurl"));
   &urlRensrv = &urlRen | "/?do_method=lib";
   &labelElapse = MsgGetText(162, 1172, "Message Not Found");
   &labelConversation = MsgGetText(162, 1171, "Message Not Found");
   &labelInput = MsgGetText(162, 1173, "Message Not Found");
