   &msgDomainError = MsgGetText(162, 1247, "Message Not Found");
   &msgShutdown = MsgGetExplainText(162, 1250, "Message Not Found");
   &msgChangeQFailed = MsgGetText(162, 1330, "Message Not Found");
   &txtAssumed = MsgGetExplainText(162, 1255, "Message Not Found");
   &msgMSError = MsgGetText(162, 1700, "Message Not Found");
   &msgLoginFailed2 = MsgGetText(162, 1762, "Message Not Found");
   &titleMCFC = MsgGetText(162, 1166, "Message Not Found");

   &urlAgentMain = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_AgentMain");

   &urlA2A = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_A2AMain");

   &urlCloseSession = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_CloseSession");

   &psHome = GetPSHome();

   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;

   &topWindow = 0;
   &leftWindow = 0;
   &widthWindow = 1020;
   &heightWindow = 130;

   &topWA2C = 10;
   &leftWA2C = 10;
   &widthWA2C = 900;
   &heightWA2C = 640;
   &popModeA2C = "M";
   &acceptModeA2C = "A";

   &topWA2A = 50;
   &leftWA2A = 100;
   &widthWA2A = 400;
   &heightWA2A = 510;
   &popModeA2A = "M";
   &acceptModeA2A = "A";

   &topWAlert = 10;
   &leftWAlert = 10;
   &widthWAlert = 800;
   &heightWAlert = 600;
   &popModeAlert = "M";

   &topWEmail = 10;
   &leftWEmail = 10;
   &widthWEmail = 800;
   &heightWEmail = 600;
   &popModeEmail = "M";

   &topWURLW = 10;
   &leftWURLW = 10;
   &widthWURLW = 800;
   &heightWURLW = 650;

   REM get all customized windows;
   &SQL = CreateSQL("select MCFTYPE, MCFTOP, MCFLEFT, MCFWIDTH, MCFHEIGHT, MCFPOPUP_MODE, MCFACCEPT_MODE from PS_MCFAGENTCUST WHERE MCFUQAGENTID = :1", %UserId);
   While &SQL.Fetch(&wType, &wTop, &wLeft, &wWidth, &wHeight, &wPopMode, &wAcceptMode)
      Evaluate &wType
      When = "M"
         &topWindow = &wTop;
         &leftWindow = &wLeft;
         &widthWindow = &wWidth;
         &heightWindow = &wHeight;
      When = "A"
         &topWA2A = &wTop;
         &leftWA2A = &wLeft;
         &widthWA2A = &wWidth;
         &heightWA2A = &wHeight;
         &popModeA2A = &wPopMode;
         &acceptModeA2A = &wAcceptMode;
      When = "C"
         &topWA2C = &wTop;
         &leftWA2C = &wLeft;
         &widthWA2C = &wWidth;
         &heightWA2C = &wHeight;
         &popModeA2C = &wPopMode;
         &acceptModeA2C = &wAcceptMode;
      When = "E"
         &topWEmail = &wTop;
         &leftWEmail = &wLeft;
         &widthWEmail = &wWidth;
         &heightWEmail = &wHeight;
         &popModeEmail = &wPopMode;
      When = "G"
         &topWAlert = &wTop;
         &leftWAlert = &wLeft;
         &widthWAlert = &wWidth;
         &heightWAlert = &wHeight;
         &popModeAlert = &wPopMode;
      When = "U"
         &topWURLW = &wTop;
         &leftWURLW = &wLeft;
         &widthWURLW = &wWidth;
         &heightWURLW = &wHeight;
      When-Other
      End-Evaluate;

   End-While;
   &SQL.Close();

   REM Get agent name information;
   &screenName = "";
   &SQL = CreateSQL("select MCFUQAGENTID, MCF_NICKNAME, NAME from PSMCFUQAGENTS WHERE MCFUQAGENTID = :1", %UserId);
   If (&SQL.Fetch(&tmpAgentID, &screenName, &tmpNameShort)) Then
   End-If;
   &SQL.Close();

   REM get all queues the agent has;
   &SQL = CreateSQL("select MCFREN_PHYS_RTENT from PSMCFUQAGENTQ WHERE MCFUQAGENTID = :1", %UserId);
   &myQueues = "";
   &myQueuesHash = "";
   While &SQL.Fetch(&tmpphysQiD)
      &qID = &tmpphysQiD;
      &myQueues = &myQueues | GetHTMLText(HTML.MCF_OPTION, &qID, &qID);

      &SQL1 = CreateSQL("select MCFREN_URL_ID, MCFREN_INT_URL, MCFREN_BROWSER_URL, MCFREN_PHYS_RTENT, REN_CLUS_ROOT_PATH from PS_MCFRENMAP_VW WHERE MCFREN_PHYS_RTENT = :1", &qID);
      If (&SQL1.Fetch(&urlID, &intURL, &urlMyRensrv, &qID, &renurlRoot)) Then
      End-If;
      &SQL1.Close();
      &myQueuesHash = &myQueuesHash | GetHTMLText(HTML.MCF_HASHTABLE, "myQueuesRen", &qID, &urlMyRensrv | &renurlRoot);
   End-While;
   &SQL.Close();

   &tmpQID = %Request.GetParameter("ps_qid");
   If (&tmpQID <> "") Then
      &qID = &tmpQID;
   End-If;
   &SQL = CreateSQL("select MCFREN_URL_ID, MCFREN_INT_URL, MCFREN_BROWSER_URL, MCFREN_PHYS_RTENT, REN_CLUS_ROOT_PATH from PS_MCFRENMAP_VW WHERE MCFREN_PHYS_RTENT = :1", &qID);
   If (&SQL.Fetch(&urlID, &intURL, &urlMyRensrv, &qID, &renurlRoot)) Then
   End-If;
   &SQL.Close();

   &urlRensrv = &urlMyRensrv | &renurlRoot | "/?do_method=lib";
   &urlRensrvBlank = &urlMyRensrv | &renurlRoot | "/?do_method=blank";

   &SQL = CreateSQL("Select MCFREN_PHYS_RTENT from PS_MCFRENMAP_VW WHERE MCFREN_URL_ID = :1 GROUP BY MCFREN_PHYS_RTENT", &urlID);
   &allQueues = "";
   While &SQL.Fetch(&tmpQID);
      &allQueues = &allQueues | GetHTMLText(HTML.MCF_OPTION, &tmpQID, &tmpQID);
   End-While;
   &SQL.Close();

   REM Get my buddies;
   &SQL = CreateSQL("SELECT  B.MCFUQAGENTID, B.NAME FROM %Table(MCFAGENTBUDDY) A, %Table(PSMCFUQAGENTS) B WHERE A.MCFUQAGENTID = :1 AND A.MCFBUDDY=B.MCFUQAGENTID ORDER BY B.NAME", %UserId);
   &myBuddies = "";
   While &SQL.Fetch(&buddyAgentID, &buddyName)
      &myBuddies = &myBuddies | GetHTMLText(HTML.MCF_OPTION, &buddyAgentID, &buddyName);
   End-While;
   &SQL.Close();

   REM Get my presences;
   &SQL = CreateSQL("select MCFPRESENCESTATE, MCFPRESENCEDESCR from PS_MCFAGENTPRES WHERE MCFUQAGENTID = :1", %UserId);
   &myPresences = "";
   While &SQL.Fetch(&presenceValue, &presenceText)
      If (&presenceValue = "A") Then
         &presenceValue = "active";
      Else
         &presenceValue = "inactive";
      End-If;
      &myPresences = &myPresences | GetHTMLText(HTML.MCF_OPTION, &presenceValue, &presenceText);
   End-While;
   &SQL.Close();

   REM Get my urls;
   &SQL = CreateSQL("select MCFURLNAME, MCFURL from PS_MCFAGENTURLS WHERE MCFUQAGENTID = :1", %UserId);
   &myURLS = "";
   While &SQL.Fetch(&urlName, &urlValue)
      &myURLS = &myURLS | GetHTMLText(HTML.MCF_OPTION, &urlValue, &urlName);
   End-While;
   &SQL.Close();

   &serverURI = %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort | "/";
   rem get misc configuration;
   &SQL = CreateSQL("SELECT MCF_TRACELEVEL, MCF_UNASSIGNED, PTMCFTUNNELREFRESH FROM PS_MCF_AGENTMISC WHERE MCFUQAGENTID=:1", %UserId);
   If ( Not &SQL.Fetch(&traceLevel, &actionUnassigned, &tunnelRefreshCount)) Then
      &traceLevel = 0;
      &actionUnassigned = 0;
   End-If;
   &SQL.Close();

   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");
   &myQserv = "any";

   Local number &MCF_CompatabilityMode;

   &sys = GetJavaClass("java.lang.System");
   try
      &MCF_CompatabilityMode = &sys.getProperty("MCF_CompatabilityMode");
   catch Exception &e
      &MCF_CompatabilityMode = 1;
   end-try;

   &HTML = GetHTMLText(HTML.MCF_TOOLBAR, RTrim(%UserId), &urlRensrv, &imgFlashAlert, &imgFlashEmail, &imgFlashChat, &imgFlashA2A, &imgNormalAlert, &imgNormalEmail, &imgNormalChat, &imgNormalA2A, &imgSleepingAgent, &imgClear, &labelPresence, &labelQueueStatus, &labelTasks, &labelBuddies, &labelLoggedOn, &labelActiveTask, &labelConsultAgent, &labelLoggedOff, &altTextNewC2A, &altTextNewA2A, &labelA2AChat, &urlAgentMain, &urlA2A, &psHome, &psDomain, &labelChat, &labelEmail, &labelAlert, &labelMyQueue, &cssPTMCFDEF, &cssPTSTYLEDEF, &topWindow, &leftWindow, &widthWindow, &heightWindow, &titleMCFC, &screenName, &myQueues, &allQueues, &urlMyRensrv | &renurlRoot, &topWA2C, &leftWA2C, &widthWA2C, &heightWA2C, &topWA2A, &leftWA2A, &widthWA2A, &heightWA2A, &topWAlert, &leftWAlert, &widthWAlert, &heightWAlert, &topWEmail, &leftWEmail, &widthWEmail, &heightWEmail, &topWURLW, &leftWURLW, &widthWURLW, &heightWURLW, &serverURI, &myBuddies, &myPresences, &urlCloseSession, &popModeA2C, &acceptModeA2C, &popModeA2A, &acceptModeA2A, &popModeEmail, &popModeAlert, &altTextNewEmail, &altTextNewAlert, &altTextNewConf, &altTextSleepAgent, &labelAcceptChat, &myQserv, &msgDblA2A, &msgDblConf, &msgWTT, &msgWTN, &msgWAFC, &msgCRFSA, &msgCRFSC, &msgWAFA, &msgWTTN, &msgWA, &msgWTTG, &msgNoConnection, &myQueuesHash, &msgTaskUnassigned, &msgAccepted, &msgNew, &msgInitial, &msgLoginFailed, &msgKickedOff, &msgConfirmClose, &optLogon, &msgDomainError, &msgShutdown, %Datetime, &urlTracer, &traceLevel, &actionUnassigned, &txtAssumed, &msgChangeQFailed, &msgMSError, &msgLoginFailed2, GetRENJSMSG(), &MCF_CompatabilityMode, &tunnelRefreshCount);

   %Response.Write(&HTML);
   Return;
   &url = "";
   rem   &url = &url | "/?" | "page=" | EncodeURL(&HTML);
   %Response.RedirectURL(&url);
End-Function;

Function IScript_GrabURLMain()
   &psHome = GetPSHome();

   &urlWizard = Unencode(%Request.GetParameter("urlWizard"));
   If (&urlWizard = "") Then
      &urlWizard = GenerateComponentContentRelURL(%Portal, %Node, MenuName.PT_MCF, "GBL", Component.MCF_DEMO_CMP, Page.MCF_URLWIZARD, "");
      &psNewHome = Left(&psHome, Len(&psHome) - 1) | "_newwin/";
      &urlWizard = Substitute(&urlWizard, &psHome, &psNewHome);
   Else
      If (Find("http://", &urlWizard) <= 0) Then
         &urlWizard = %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort | &urlWizard;
      End-If;
   End-If;
   &urlGrabURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_GrabURL");
   &titleGrabURL = MsgGetText(162, 1170, "Message Not Found");
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &HTML = GetHTMLText(HTML.MCF_GRABURLMAIN, &urlWizard, &urlGrabURL, &titleGrabURL, &psDomain);
   %Response.Write(&HTML);
End-Function;

Function IScript_GrabURL()
   Local string &strURLStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strURLStyleSheetName);
   &cssPTMCFDEF = %Response.GetStyleSheetURL(&strURLStyleSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strURLStyleSheetName);
   &titleGrabURL = MsgGetText(162, 1170, "Message Not Found");
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &labelBtPush = MsgGetText(162, 1181, "Message Not Found");
   &labelBtPushClose = MsgGetText(162, 1186, "Message Not Found");
   &HTML = GetHTMLText(HTML.MCF_GRABURL, &titleGrabURL, &cssPTSTYLEDEF, &cssPTMCFDEF, &psDomain, &labelBtPush, &labelBtPushClose);
   %Response.Write(&HTML);
End-Function;

