REM Function:       IScript_CloseSession                                                    ;
REM Purpose:        Close the session for MCF console and chat window                         ;
REM Inputs:                                                                                 ;
REM Output:                                                                                 ;
REM ***************************************************************************************;
Function IScript_CloseSession()
   &psHome = GetPSHome();

   &titleCloseWindow = MsgGetText(162, 1187, "Message Not Found");
   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &cssPTMCFDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &urlRen = Unencode(%Request.GetParameter("urlRen"));
   &urlRensrv = &urlRen | "/?do_method=lib";
   &msgCloseSession = MsgGetExplainText(162, 1187, "Message Not Found");
   &topWindow = 10;
   &leftWindow = 10;
   &widthWindow = 300;
   &heightWindow = 200;
   &HTML = GetHTMLText(HTML.MCF_CLOSESESSION, &titleCloseWindow, &cssPTSTYLEDEF, &cssPTMCFDEF, &psDomain, &urlRensrv, &msgCloseSession, &topWindow, &leftWindow, &widthWindow, &heightWindow, &psHome, GetRENJSMSG());
   %Response.Write(&HTML);
   rem   %Response.Write(&msgCloseSession);
End-Function;

REM ***************************************************************************************;
REM Function:       IScript_CloseJSMCAPISession                                             ;
REM Purpose:        Close the session for JSMCAPI                                           ;
REM Inputs:                                                                                 ;
REM Output:                                                                                 ;
REM ***************************************************************************************;
Function IScript_CloseJSMCAPISession()
   Local string &jsmcapi;
   Local string &sessionId;
   Local string &groupList;
   Local string &userId;
   Local string &agentId;
   Local string &agentPassword;
   Local string &agentQueue;
   Local string &agentConfigId;
   Local string &renClusterId;

   &psHome = GetPSHome();

   &titleCloseWindow = MsgGetText(162, 1187, "Message Not Found");
   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &cssPTMCFDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &traceLevel = Integer(%Request.GetParameter("traceLevel"));
   &sessionId = %Request.GetParameter("sessionId");
   &userId = %Request.GetParameter("userId");
   &groupList = %Request.GetParameter("groupList");
   &extension1 = %Request.GetParameter("extension1");
   &extension2 = %Request.GetParameter("extension2");
   &msgCloseSession = MsgGetExplainText(162, 1187, "Message Not Found");
   &topWindow = 10;
   &leftWindow = 10;
   &widthWindow = 300;
   &heightWindow = 200;


   SQLExec("select PT_CTI_AGENTID, PT_CTI_QUEUE, PT_CTI_CONFIGID,PT_CTI_PASSWORD from PS_PT_CTI_AGENT A where OPRID = :1 AND EFFDT = (SELECT MAX(EFFDT) FROM PS_PT_CTI_AGENT B WHERE A.OPRID= B.OPRID AND EFFDT <= %CurrentDateIn)", &userId, &agentId, &agentQueue, &agentConfigId, &agentPassword);
   SQLExec("SELECT MCFREN_URL_ID FROM PS_CTIREN WHERE PT_CTI_CONFIGID=:1 ", &agentConfigId, &renClusterId);
   &jsmcapi = GetJSMCAPI(&renClusterId);

   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");
   &HTML = GetHTMLText(HTML.MCF_JSMCAPICLOSESESSION, &titleCloseWindow, &cssPTSTYLEDEF, &cssPTMCFDEF, &psDomain, &jsmcapi, &msgCloseSession, &topWindow, &leftWindow, &widthWindow, &heightWindow, &psHome, GetRENJSMSG(), &traceLevel, &urlTracer, &sessionId, &userId, &agentId, &agentPassword, &groupList, &extension1, &extension2);
   %Response.Write(&HTML);
   rem   %Response.Write(&msgCloseSession);
End-Function;



REM ***************************************************************************************;
REM Function:       IScript_ThirdPartyCustomerChat                                     ;
REM Purpose:        Generate chat window for Third Party Routing customer to agent chat;
REM Inputs:                                               ;
REM Output:                                                                      ;
REM ***************************************************************************************;
Function IScript_ThirdPartyCustomerChat()
   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &cssPTMCFDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &typeBrowser = %Request.BrowserType;
   Local number &ver = Value(%Request.BrowserVersion);
   If (&typeBrowser = "NETSCAPE" And
         &ver < 5) Then
      &msgTitle = MsgGetText(162, 1245, "Message Not Found");
      &msgWarning = MsgGetExplainText(162, 1246, "Message Not Found");
      &HTML = GetHTMLText(HTML.MCF_MESSAGE, &msgTitle, &cssPTMCFDEF, &msgWarning);
      %Response.Write(&HTML);
      Return;
   End-If;
   &widthInput = 90;
   If (&typeBrowser = "NETSCAPE") Then
      &widthInput = 105;
   End-If;
   &titleC2A = MsgGetText(162, 1169, "Message Not Found");
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &ChatURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_TPCustomerChatInput");

   &ChatURL = &ChatURL | "?" | %Request.QueryString;
   &urlRen = Unencode(%Request.GetParameter("renurl"));
   &urlRensrvBlank = &urlRen | "/?do_method=blank";
   &URLConversation = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_Conversation");
   &URLTimer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_Timer");

   &nUserType = GetAccessibility();
   If (&nUserType = 1) Then
      &sURLIncomingMsg = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_IncomingMsg");
      &HTML = GetHTMLText(HTML.MCF_CUSTOMERFRAME2, &URLTimer, &ChatURL, &titleC2A, &psDomain, &URLConversation, &widthInput, &sURLIncomingMsg);
   Else
      &HTML = GetHTMLText(HTML.MCF_CUSTOMERFRAME, &URLTimer, &ChatURL, &titleC2A, &psDomain, &URLConversation, &widthInput);
   End-If;

   %Response.Write(&HTML);
End-Function;


