   &cssPTMCFDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strStyleSheetName);

   &psHome = GetPSHome();
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &urlRen = Unencode(%Request.GetParameter("renurl"));
   &urlRensrv = &urlRen | "/?do_method=lib";
   &labelElapse = MsgGetText(162, 1172, "Message Not Found");
   &labelConversation = MsgGetText(162, 1171, "Message Not Found");
   &labelInput = MsgGetText(162, 1173, "Message Not Found");
   &labelButtonSend = MsgGetText(162, 1174, "Message Not Found");
   &labelButtonClose = MsgGetText(162, 1175, "Message Not Found");
   &msgPleaseWait = MsgGetText(162, 1207, "Message Not Found");
   &msgSessionClosed = MsgGetText(162, 1203, "Message Not Found");
   &msgEnd = MsgGetText(162, 1208, "Message Not Found");
   &msgAbandon = MsgGetText(162, 1210, "Message Not Found");
   &msgRensrvDown = MsgGetExplainText(162, 1211, "Message Not Found");
   &msgRensrvUp = MsgGetText(162, 1212, "Message Not Found");
   &msgMsgOverSize = MsgGetText(162, 1213, "Message Not Found");
   &msgNoActivityTimeout = MsgGetText(162, 1214, "Message Not Found");
   &msgNoAnswer = MsgGetText(162, 1215, "Message Not Found");
   &msgNoConnection = MsgGetText(162, 1220, "Message Not Found");
   &msgDomainError = MsgGetText(162, 1247, "Message Not Found");
   &msgInputArea = MsgGetText(162, 1249, "Message Not Found");
   &msgURLPushed = MsgGetText(162, 1252, "Message Not Found");
   &msgGreeting4Waiting = MsgGetText(162, 1610, "Message Not Found");
   &msgChatLogged = MsgGetText(162, 1483, "Message Not Found");
   &msgAgentLeft = MsgGetText(162, 1485, "Message Not Found");
   &msgMSError = MsgGetText(162, 1700, "Message Not Found");
   &tooltipsendmsg = MsgGetText(162, 56, "Message Not Found");
   &tooltipexitchat = MsgGetText(162, 57, "Message Not Found");

   &maxNoActivityDuration = 120;
   &maxWaitingDuration = 60;
   &intervalGreeting = 20;

   &SQL = CreateSQL("select MCFUQACTIMOUT_MINS,MCFCHATSESSTO,MCFGREETINTERVAL FROM PS_MCFUQTASKCFG WHERE MCFUQTASKTYPE = :1", "CH");
   If (&SQL.Fetch(&tmpActionTimeout, &tmpNoActivity, &tmpIntervalGreeting)) Then
      &maxWaitingDuration = &tmpActionTimeout * 60;
      &maxNoActivityDuration = &tmpNoActivity * 60;
      If (&tmpIntervalGreeting <> 0) Then
         &intervalGreeting = &tmpIntervalGreeting;
      End-If;
   End-If;
   &SQL.Close();

   &topWindow = 50;
   &leftWindow = 100;
   &widthWindow = 400;
   &heightWindow = 510;

   &urlCloseSession = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_CloseSession");

   &renClusterId = Unencode(%Request.GetParameter("clusterid"));
   &jsmcapi = GetTPJSMCAPI(&renClusterId);

   &HTML = GetHTMLText(HTML.MCF_TPCUSTOMERCHAT, RTrim(%UserId), &urlRensrv, &psHome, &psDomain, &partyAgentID, &cmd, &cssPTSTYLEDEF, &cssPTMCFDEF, &labelElapse, &labelConversation, &labelInput, &labelButtonSend, &labelButtonClose, &topWindow, &leftWindow, &widthWindow, &heightWindow, &msgPleaseWait, &msgSessionClosed, &urlCloseSession, &msgEnd, &msgAbandon, &msgRensrvDown, &msgRensrvUp, &msgMsgOverSize, &msgNoActivityTimeout, &maxNoActivityDuration, &maxWaitingDuration, &msgNoAnswer, &msgNoConnection, &msgDomainError, &msgInputArea, &msgURLPushed, &intervalGreeting, &msgGreeting4Waiting, &msgChatLogged, &msgMSError, &msgAgentLeft, GetRENJSMSG(), &jsmcapi, &renClusterId, &tooltipsendmsg, &tooltipexitchat);
   %Response.Write(&HTML);
End-Function;

