REM ***************************************************************************************;
REM Function:       IScript_TPAgentChat                                 ;
REM Purpose:        Generate HTML page for input frame of agent to customer chat window   ;
REM Inputs:                                               ;
REM Output:                                                                      ;
REM ***************************************************************************************;
Function IScript_TPAgentChat()
   Local string &msgAgentLeft;
   Local string &msgCustomerLeft;
   Local string &msgAccept2;
   Local string &strSelect;

   &psHome = GetPSHome();

   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &urlRen = Unencode(%Request.GetParameter("urlRen"));

   If (Find("do_method", &urlRen) <= 0) Then
      &urlRensrv = &urlRen | "/?do_method=lib";
   Else
      &urlRensrv = &urlRen;
   End-If;
   &urlGrab = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_GrabURLMain");

   &ps_qid = %Request.GetParameter("ps_qid");
   &myrenClusterId = %Request.GetParameter("renClusterId");

   &labelConsultAgent = MsgGetText(162, 1159, "Message Not Found");
   &labelConversation = MsgGetText(162, 1171, "Message Not Found");
   &labelElapse = MsgGetText(162, 1172, "Message Not Found");
   &labelTemplateMessages = MsgGetText(162, 1176, "Message Not Found");
   &labelInput = MsgGetText(162, 1173, "Message Not Found");
   &labelURL = MsgGetText(162, 1177, "Message Not Found");
   &labelForward2Queue = MsgGetText(162, 1178, "Message Not Found");
   &labelInviteBuddy = MsgGetText(162, 1179, "Message Not Found");
   &labelButtonGo = MsgGetText(162, 1180, "Message Not Found");
   &labelButtonSend = MsgGetText(162, 1174, "Message Not Found");
   &labelButtonClose = MsgGetText(162, 1175, "Message Not Found");
   &labelButtonPush = MsgGetText(162, 1181, "Message Not Found");
   &labelButtonGrab = MsgGetText(162, 1182, "Message Not Found");
   &labelStaticURL = MsgGetText(162, 1183, "Message Not Found");
   &labelSelectMsg = MsgGetText(162, 1184, "Message Not Found");
   &labelSelectURL = MsgGetText(162, 1185, "Message Not Found");
   /*Abhinao :Adding the button Label*/
   /*&labelButtonWrapUp = "WrapUp";*/
   &labelButtonWrapUp = MsgGetText(162, 1193, "Message Not Found");;
   &msgAccept = MsgGetText(162, 1201, "Message Not Found");
   &msgAccept2 = MsgGetText(162, 1257, "Message Not Found");
   &msgEnd = MsgGetText(162, 1202, "Message Not Found");
   &msgSessionClosed = MsgGetText(162, 1203, "Message Not Found");
   &msgForward = MsgGetText(162, 1204, "Message Not Found");
   &msgForward2SameQueue = MsgGetText(162, 1205, "Message Not Found");
   &msgInviteSameAgent = MsgGetText(162, 1206, "Message Not Found");
   &msgRensrvDown = MsgGetExplainText(162, 1211, "Message Not Found");
   &msgRensrvUp = MsgGetText(162, 1212, "Message Not Found");
   &msgMsgOverSize = MsgGetText(162, 1213, "Message Not Found");
   &msgNoActivityTimeout = MsgGetText(162, 1214, "Message Not Found");
   &msgFwdOver2 = MsgGetText(162, 1217, "Message Not Found");
   &msgInputArea = MsgGetText(162, 1249, "Message Not Found");
   &msgURLPushed = MsgGetText(162, 1252, "Message Not Found");
   &msgChatLogged = MsgGetText(162, 1483, "Message Not Found");
   &msgAgentLeft = MsgGetText(162, 1485, "Message Not Found");
   &msgCustomerLeft = MsgGetText(162, 1486, "Message Not Found");
   &msgMSError = MsgGetText(162, 1700, "Message Not Found");
   &tooltipsendmsg = MsgGetText(162, 56, "Message Not Found");
   &tooltipexitchat = MsgGetText(162, 57, "Message Not Found");
   &tooltippushurl = MsgGetText(162, 58, "Message Not Found");
   &tooltiphistory = MsgGetText(162, 64, "Message Not Found");
   &tooltipwrapup = MsgGetText(162, 65, "Message Not Found");
   &strSelect = MsgGetText(162, 1258, "Message Not Found");
   &historyLabel = MsgGetText(162, 2859, "Message Not Found");
   &maxNoActivityDuration = 120;

   &SQL = CreateSQL("select MCFCHATSESSTO FROM PS_MCFUQTASKCFG WHERE MCFUQTASKTYPE = :1", "CH");
   If (&SQL.Fetch(&tmpNoActivity)) Then
      &maxNoActivityDuration = &tmpNoActivity * 60;
   End-If;
   &SQL.Close();

   rem get logical queue and queue server;
   &SQL = CreateSQL("select PSMCFRENURLID.MCFREN_URL_ID, PSMCFRENURLID.MCFREN_INT_URL, PSMCFRENURLID.MCFREN_BROWSER_URL, PSMCFRENURLID.REN_CLUS_ROOT_PATH from PSMCFRENURLID,PSMCFTPCLSTR_Q where PSMCFRENURLID.MCFREN_URL_ID = :1 AND PSMCFRENURLID.MCFREN_URL_ID = PSMCFTPCLSTR_Q.MCFREN_URL_ID AND PSMCFTPCLSTR_Q.ACTIVE_FLAG ='A'", &myrenClusterId);

   If (&SQL.Fetch(&urlID, &intURL, &urlMyRensrv, &renurlRoot)) Then
   End-If;
   &SQL.Close();

   REM get all system messages from the Queue on which the agent login;
   &SQL = CreateSQL("select MSGNAME, MESSAGE_DESCR FROM PSMCFTPSYSMSG WHERE MCFUQQUEUEID = :1 AND MCFCONTACTID=:2", &ps_qid, "C");
   &allCannedMessages = "";
   While &SQL.Fetch(&msgName, &msgDesc)
      &allCannedMessages = &allCannedMessages | GetHTMLText(HTML.MCF_OPTION, &msgDesc, &msgName);
   End-While;
   &SQL.Close();

   REM get all my own messages;

   &SQL = CreateSQL("select MSGNAME, MCFMSGID, MESSAGE_DESCR from PSMCFTPAGNTMSG WHERE MCFUQAGENTID = :1", %UserId);
   While &SQL.Fetch(&msgName, &tmpMsgId, &msgDesc)
      &allCannedMessages = &allCannedMessages | GetHTMLText(HTML.MCF_OPTION, &msgDesc, &msgName);
      Evaluate &tmpMsgId
      When = "A"
         &msgAccept = &msgDesc;
      When = "B"
         &msgAccept2 = &msgDesc;
      When = "D"
         &msgDeny = &msgDesc;
      When = "E"
         &msgEnd = &msgDesc;
      When = "F"
         &msgForward = &msgDesc;
      When = "O"
      When = "Z"
      When-Other
      End-Evaluate;
   End-While;
   &SQL.Close();

   REM get all system URLs from the Queue on which the agent login;
   &SQL = CreateSQL("select MCFURLNAME, MCFURL from PSMCFTPQURLS WHERE MCFUQQUEUEID = :1", &ps_qid);
   &allCannedURLs = "";
   While &SQL.Fetch(&urlName, &urlDesc)
      &allCannedURLs = &allCannedURLs | GetHTMLText(HTML.MCF_OPTION, &urlDesc, &urlName);
   End-While;
   &SQL.Close();

   REM get all my own URLs;
   &SQL = CreateSQL("select MCFURLNAME, MCFURL FROM PSMCFTPAGNTURLS WHERE MCFUQAGENTID = :1", %UserId);
   While &SQL.Fetch(&urlName, &urlDesc)
      &allCannedURLs = &allCannedURLs | GetHTMLText(HTML.MCF_OPTION, &urlDesc, &urlName);
   End-While;
   &SQL.Close();

   REM get all queues the queue server supported;
   &SQL = CreateSQL("SELECT DISTINCT MCFUQQUEUEID FROM PSMCFTPCLSTR_Q WHERE ACTIVE_FLAG = 'A' ");
   &allQueues = "";
   While &SQL.Fetch(&qID);

      &allQueues = &allQueues | GetHTMLText(HTML.MCF_OPTION, &qID, &qID);

   End-While;
   &SQL.Close();
   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &cssPTMCFDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strStyleSheetName);

   &topWindow = 10;
   &leftWindow = 10;
   &widthWindow = 900;
   &heightWindow = 640;

   &urlCloseSession = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_CloseSession");

   &SQL = CreateSQL("SELECT MCF_TRACELEVEL, MCF_UNASSIGNED FROM PS_MCF_AGENTMISC WHERE MCFUQAGENTID=:1", %UserId);
   If ( Not &SQL.Fetch(&traceLevel, &actionUnassigned)) Then
      &traceLevel = 0;
      &actionUnassigned = 0;
   End-If;
   &SQL.Close();

   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");

   &myjsmcapi = GetTPJSMCAPI(&myrenClusterId);
   &HTML = GetHTMLText(HTML.MCF_TPAGENTCHAT, RTrim(%UserId), &urlRensrv, &psHome, &psDomain, &urlRensrv, &urlGrab, &labelElapse, &labelConversation, &labelTemplateMessages, &labelInput, &labelURL, &labelForward2Queue, &labelInviteBuddy, &labelButtonGo, &labelButtonSend, &labelButtonClose, &labelButtonPush, &labelButtonGrab, &cssPTSTYLEDEF, &cssPTMCFDEF, &topWindow, &leftWindow, &widthWindow, &heightWindow, &labelStaticURL, &labelSelectMsg, &labelSelectURL, &msgAccept, &msgEnd, &msgSessionClosed, &allCannedMessages, &allCannedURLs, &msgForward, &msgForward2SameQueue, &msgInviteSameAgent, &msgRensrvDown, &msgRensrvUp, &urlCloseSession, &msgMsgOverSize, &msgNoActivityTimeout, &maxNoActivityDuration, &msgFwdOver2, &allQueues, &msgInputArea, &msgURLPushed, &urlTracer, &traceLevel, &msgChatLogged, &msgMSError, &msgAgentLeft, &msgCustomerLeft, GetRENJSMSG(), &msgAccept2, &strSelect, &labelConsultAgent, &myjsmcapi, &labelButtonWrapUp, &tooltipsendmsg, &tooltipexitchat, &tooltiphistory, &tooltipwrapup, &tooltippushurl, &historyLabel);
   %Response.Write(&HTML);
End-Function;

