   End-If;
   &SQL.Close();

   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");
   &TaskType = %Request.GetParameter("ps_tasktype");
   If (&TaskType = "EMAIL") Then
      &HTML = GetHTMLText(HTML.MCF_EMAILTASK, RTrim(%UserId), &urlRensrv, &psHome, &psDomain, &urlRensrv, &urlGrab, &labelElapse, &labelConversation, &labelTemplateMessages, &labelInput, &labelURL, &labelForward2Queue, &labelInviteBuddy, &labelButtonGo, &labelButtonSend, &labelButtonClose, &labelButtonPush, &labelButtonGrab, &cssPTSTYLEDEF, &cssPTMCFDEF, &topWindow, &leftWindow, &widthWindow, &heightWindow, &labelStaticURL, &labelSelectMsg, &labelSelectURL, &msgAccept, &msgEnd, &msgSessionClosed, &allCannedMessages, &allCannedURLs, &msgForward, &msgForward2SameQueue, &msgInviteSameAgent, &msgRensrvDown, &msgRensrvUp, &urlCloseSession, &msgMsgOverSize, &msgNoActivityTimeout, &maxNoActivityDuration, &msgFwdOver2, &allQueues, &msgInputArea, &msgURLPushed, &urlTracer, &traceLevel, &msgChatLogged, &msgMSError, &msgAgentLeft, &msgCustomerLeft, GetRENJSMSG(), &msgAccept2, &strSelect, &labelConsultAgent, &tooltipforwardtoagent, &tooltipforwardtoqueue, &tooltipabandone, &tooltipcomplete);
