REM ***************************************************************************************;
REM Function:       IScript_TPA2AMain                               ;
REM Purpose:        Generate HTML page for agent to agent chat window                      ;
REM Inputs:                                               ;
REM Output:                                                                      ;
REM ***************************************************************************************;
Function IScript_TPA2AMain()
   &typeBrowser = %Request.BrowserType;
   &widthInput = 90;
   If (&typeBrowser = "NETSCAPE") Then
      &widthInput = 105;
   End-If;

   &titleA2A = MsgGetText(162, 1167, "Message Not Found");
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &ChatURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_TPA2AChat");
   &ChatURL = &ChatURL | "?" | %Request.QueryString;

   &urlRen = Unencode(%Request.GetParameter("urlRen"));
   If (Find("do_method", &urlRen) <= 0) Then
      &urlRensrvBlank = &urlRen | "/?do_method=blank";
   Else
      &urlRensrvBlank = Substring(&urlRen, 0, Find("do_method", &urlRen));
      &urlRensrvBlank = &urlRensrvBlank | "do_method=blank";

   End-If;
   &URLConversation = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_Conversation");
   &URLTimer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_Timer");

   &nUserType = GetAccessibility();
   If (&nUserType = 1) Then
      &sURLIncomingMsg = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_IncomingMsg");
      &HTML = GetHTMLText(HTML.MCF_A2AMAIN2, &URLConversation, &ChatURL, &titleA2A, &psDomain, &URLTimer, &widthInput, &sURLIncomingMsg);
   Else
      &HTML = GetHTMLText(HTML.MCF_A2AMAIN, &URLConversation, &ChatURL, &titleA2A, &psDomain, &URLTimer, &widthInput);

   End-If;
   %Response.Write(&HTML);
End-Function;

REM ***************************************************************************************;
REM Function:       IScript_TPA2AChat                               ;
REM Purpose:        Generate input frame of agent to agent chat window                     ;
REM Inputs:                                               ;
REM Output:                                                                      ;
REM ***************************************************************************************;
Function IScript_TPA2AChat()
   Local string &ps_uniqueid;
   Local string &msgBuddyLeft;
   &psHome = GetPSHome();
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &urlRen = Unencode(%Request.GetParameter("urlRen"));
   If (Find("do_method", &urlRen) <= 0) Then
      &urlRensrv = &urlRen | "/?do_method=lib";
   Else
      &urlRensrv = &urlRen;

   End-If;

   &labelConversation = MsgGetText(162, 1171, "Message Not Found");
   &labelElapse = MsgGetText(162, 1172, "Message Not Found");
   &labelInput = MsgGetText(162, 1173, "Message Not Found");
   &labelButtonSend = MsgGetText(162, 1174, "Message Not Found");
   &labelButtonClose = MsgGetText(162, 1175, "Message Not Found");
   &msgAccept = MsgGetText(162, 1201, "Message Not Found");
   &msgPleaseWait = MsgGetText(162, 1207, "Message Not Found");
   &msgSessionClosed = MsgGetText(162, 1203, "Message Not Found");
   &msgEnd = MsgGetText(162, 1202, "Message Not Found");
   &msgDeny = MsgGetText(162, 1209, "Message Not Found");
   &msgAbandon = MsgGetText(162, 1210, "Message Not Found");
   &msgRensrvDown = MsgGetExplainText(162, 1211, "Message Not Found");
   &msgRensrvUp = MsgGetText(162, 1212, "Message Not Found");
   &msgMsgOverSize = MsgGetText(162, 1213, "Message Not Found");
   &msgNoActivityTimeout = MsgGetText(162, 1214, "Message Not Found");
   &msgNoAnswer = MsgGetText(162, 1215, "Message Not Found");
   &msgInputArea = MsgGetText(162, 1249, "Message Not Found");
   &msgMSError = MsgGetText(162, 1700, "Message Not Found");
   &msgBuddyLeft = MsgGetText(162, 1484, "Message Not Found");
   &maxNoActivityDuration = 120;
   &maxWaitingDuration = 60;

   /* Start of change for 3rd Party A2A functionality */
   &labelForward2Queue = MsgGetText(162, 1178, "Message Not Found");
   &labelInviteBuddy = MsgGetText(162, 1179, "Message Not Found");
   &labelButtonGo = MsgGetText(162, 1180, "Message Not Found");
   &msgForward = MsgGetText(162, 1204, "Message Not Found");
   &msgForward2SameQueue = MsgGetText(162, 1205, "Message Not Found");
   &msgInviteSameAgent = MsgGetText(162, 1206, "Message Not Found");
   &tooltipsendmsg = MsgGetText(162, 56, "Message Not Found");
   &tooltipexitchat = MsgGetText(162, 57, "Message Not Found");
   &tooltipforwardbuddy = MsgGetText(162, 59, "Message Not Found");
   &tooltipInvitebuddy = MsgGetText(162, 60, "Message Not Found");
   &Labelforwardtoagent = MsgGetText(162, 61, "Message Not Found");
   &Labelinviteagent = MsgGetText(162, 62, "Message Not Found");
   &labelConsultAgent = MsgGetText(162, 63, "Message Not Found");
   /* End of change for 3rd Party A2A functionality */


   &partyAgentID = %Request.GetParameter("ps_agentid");
   &cmd = %Request.GetParameter("cmd");
   &ps_uniqueid = %Request.GetParameter("ps_uniqueid");

   rem  &cssPTMCFDEF = %Response.GetStyleSheetURL(StyleSheet.PTMCFDEF);

   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strStyleSheetName);

   &topWindow = 50;
   &leftWindow = 100;
   &widthWindow = 400;
   &heightWindow = 510;

   &SQL = CreateSQL("select MCFUQACTIMOUT_MINS,MCFCHATSESSTO FROM PS_MCFUQTASKCFG WHERE MCFUQTASKTYPE= :1", "CH");
   If (&SQL.Fetch(&tmpActionTimeout, &tmpNoActivity)) Then
      &maxWaitingDuration = &tmpActionTimeout * 60;
      &maxNoActivityDuration = &tmpNoActivity * 60;
   End-If;
   &SQL.Close();

   &SQL = CreateSQL("select MSGNAME, MCFMSGID, MESSAGE_DESCR from PS_MCFAGNTMSG WHERE MCFUQAGENTID = :1", %UserId);
   While &SQL.Fetch(&msgName, &tmpMsgId, &msgDesc)
      &allCannedMessages = &allCannedMessages | GetHTMLText(HTML.MCF_OPTION, &msgDesc, &msgName);
      Evaluate &tmpMsgId
      When = "A"
         &msgAccept = &msgDesc;
      When = "D"
         &msgDeny = &msgDesc;
      When = "E"
         &msgEnd = &msgDesc;
      When = "F"
         &msgForward = &msgDesc;
      When = "O"
      When = "Z"
         &msgAbandon = &msgDesc;
      When-Other
      End-Evaluate;
   End-While;
   &SQL.Close();

   &urlCloseSession = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_CloseSession");

   &SQL = CreateSQL("SELECT MCF_TRACELEVEL, MCF_UNASSIGNED FROM PS_MCF_AGENTMISC WHERE MCFUQAGENTID=:1", %UserId);
   If ( Not &SQL.Fetch(&traceLevel, &actionUnassigned)) Then
      &traceLevel = 0;
      &actionUnassigned = 0;
   End-If;
   &SQL.Close();

   &urlTracer = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Tracer");

   /* Start of change for 3rd Party A2A functionality */
   REM get all queues the queue server supported;
   &SQL = CreateSQL("SELECT DISTINCT MCFUQQUEUEID FROM PSMCFTPCLSTR_Q WHERE ACTIVE_FLAG = 'A' ");
   &allQueues = "";
   While &SQL.Fetch(&qID);
      &allQueues = &allQueues | GetHTMLText(HTML.MCF_OPTION, &qID, &qID);
   End-While;
   &SQL.Close();
   /* End of change for 3rd Party A2A functionality */

   &HTML = GetHTMLText(HTML.MCF_TPA2ACHAT, RTrim(%UserId), &urlRensrv, &psHome, &psDomain, &partyAgentID, &cmd, &cssPTSTYLEDEF, &cssPTMCFDEF, &labelElapse, &labelConversation, &labelInput, &labelButtonSend, &labelButtonClose, &topWindow, &leftWindow, &widthWindow, &heightWindow, &msgAccept, &msgPleaseWait, &msgSessionClosed, &msgEnd, &msgDeny, &msgAbandon, &msgRensrvDown, &msgRensrvUp, &urlCloseSession, &msgMsgOverSize, &msgNoActivityTimeout, &maxNoActivityDuration, &maxWaitingDuration, &msgNoAnswer, &msgInputArea, &urlTracer, &traceLevel, &ps_uniqueid, &msgMSError, &msgBuddyLeft, GetRENJSMSG(), &labelForward2Queue, &labelInviteBuddy, &labelButtonGo, &msgForward, &msgForward2SameQueue, &msgInviteSameAgent, &allQueues, &tooltipsendmsg, &tooltipexitchat, &tooltipforwardbuddy, &tooltipInvitebuddy, &Labelforwardtoagent, &Labelinviteagent, &labelConsultAgent); /* Passing additional parameters after GetRENJSMSG() for 3rd Party A2A functionality */
   %Response.Write(&HTML);
End-Function;

