REM ***************************************************************************************;
REM Function:       IScript_Main                                  ;
REM Purpose:        Generate HTML page for MCF Console                                     ;
REM Inputs:                                               ;
REM Output:                                                                      ;
REM ***************************************************************************************;
Function IScript_Main()
   Local boolean &isMCFConfigured;
   Local string &TOOLBAR1URL;
   Local string &CTIURL;
   Local string &agentID;
   Local string &agentQueue;
   Local string &agentConfigID;
   Local string &userAgent;
   Local number &findIndex;
   Local string &strStyleSheetName;
   SQLExec("SELECT STYLESHEETNAME FROM PSOPTIONS", &strStyleSheetName);
   &cssPTMCFDEF = %Response.GetStyleSheetURL(&strStyleSheetName);
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(&strStyleSheetName);

   &SQL = CreateSQL("select MCFUQAGENTID from PSMCFUQAGENTQ WHERE MCFUQAGENTID = :1", %UserId);
   If (&SQL.Fetch(&tmpAgentID)) Then
      &isMCFConfigured = True;
   Else
      &isMCFConfigured = False;
   End-If;
   &SQL.Close();
   &titleMCFC = MsgGetText(162, 1166, "Message Not Found");
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;
   &TOOLBAR1URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MCF, Field.ISCRIPT1, "FieldFormula", "IScript_Toolbar");
   &CTIURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_CTI, Field.ISCRIPT1, "FieldFormula", "IScript_Extension");

   SQLExec("select PT_CTI_AGENTID, PT_CTI_QUEUE, PT_CTI_CONFIGID from PS_PT_CTI_AGENT A where OPRID = :1 AND EFFDT = (SELECT MAX(EFFDT) FROM PS_PT_CTI_AGENT B WHERE A.OPRID= B.OPRID AND EFFDT <= %CurrentDateIn)", %UserId, &agentID, &agentQueue, &agentConfigID);

   &typeBrowser = %Request.BrowserType;
   If (&agentID = "" And
         Not &isMCFConfigured) Then
      rem neither CTI nor MCF agent;
      &msgTitle = MsgGetText(162, 604, "Message Not Found");
      &msgWarning = MsgGetText(162, 1318, "Message Not Found");
      &OKMessage = MsgGetText(162, 2100, "Message Not Found");
      &HTML = GetHTMLText(HTML.MCF_MESSAGE, &msgTitle, &cssPTMCFDEF, &psDomain, &msgWarning, &OKMessage);
      %Response.Write(&HTML);
      Return;
   End-If;

   If (&agentID = "" And
         &isMCFConfigured) Then
      %Response.RedirectURL(&TOOLBAR1URL);
      Return;
   End-If;

   If ( Not &isMCFConfigured And
         &agentID <> "") Then
      rem CTI only agent;
      %Response.RedirectURL(&CTIURL);
      Return;
   End-If;

   If (&isMCFConfigured And
         &agentID <> "") Then
      rem both MCF and CTI agent;
      &heightCTI = 45;
      If (&typeBrowser = "NETSCAPE") Then
         &userAgent = %Request.GetHeader("User-Agent");
         &findIndex = Find("Netscape", &userAgent);
         If (Find("7.", &userAgent, &findIndex) <> 0) Then
            REM 577575003 - work around Netscape 7 bug on frameset;
            &heightCTI = 94;
         Else
            &heightCTI = 56;
         End-If;
      End-If;
      &HTML = GetHTMLText(HTML.MCF_CONSOLE, &TOOLBAR1URL, &CTIURL, &titleMCFC, &psDomain, &heightCTI);
      %Response.Write(&HTML);
      Return;
   End-If;
End-Function;

Function IScript_LaunchMdfDash()

   Local string &url;
   Local integer &sysCount, &sysId;

   SQLExec("select count(PM_SYSTEMID) from PSPMSYSDEFN", &sysCount);

   If &sysCount > 1 Then
      &url = %IntBroker.GetLayoutURL("PT_MDF_DASH_APPS", 0, 0);
   Else
      SQLExec("select PM_SYSTEMID from PSPMSYSDEFN", &sysId);
      &url = %IntBroker.GetLayoutURL("PT_MDF_DASH_APP", 0, 0) | "/" | &sysId;
   End-If;

   %Response.RedirectURL(&url);

End-Function;

If WEBLIB_MSGWSDL.PT_IBWSDL_EIPTYPE.Value = "N" Then;
   WEBLIB_SOAPTOCI.WSNAME.Enabled = False;
   WEBLIB_SOAPTOCI.DESCR.Enabled = False;
   WEBLIB_SOAPTOCI.MSGNODENAME.Enabled = False;

   WEBLIB_MSGWSDL.MSGNODENAME.Enabled = True;
   WEBLIB_MSGWSDL.RQSTMSGNAME.Enabled = True;
Else
   WEBLIB_SOAPTOCI.WSNAME.Enabled = True;
   WEBLIB_SOAPTOCI.DESCR.Enabled = True;
   WEBLIB_SOAPTOCI.MSGNODENAME.Enabled = True;

   WEBLIB_MSGWSDL.MSGNODENAME.Enabled = False;
   WEBLIB_MSGWSDL.RQSTMSGNAME.Enabled = False;

End-If;
GetLevel0()(1).GetRowset(Scroll.PSNODETRXVW2).HideAllRows();
GetLevel0()(1).GetRowset(Scroll.PSCIWBSRVSVW).HideAllRows();

Local string &sEIPType;
Local Rowset &Level0, &Level1;

&sEIPType = WEBLIB_MSGWSDL.PT_IBWSDL_EIPTYPE.Value;

If &sEIPType = "N" Then;
   Local string &MSGString;

   &Level0 = GetLevel0();
   &Level1 = &Level0(1).GetRowset(Scroll.PSNODETRXVW2);
   &Level1.Flush();
   &Level0(1).GetRowset(Scroll.PSCIWBSRVSVW).HideAllRows();
   &MSGString = "";
   &Where = "Where ";
   &And = "";

   If WEBLIB_MSGWSDL.MSGNODENAME <> "" Then
      &MSGString = "Where MSGNODENAME LIKE '%" | WEBLIB_MSGWSDL.MSGNODENAME | "%'";
      &Where = "";
      &And = " And "
   End-If;

   If WEBLIB_MSGWSDL.RQSTMSGNAME <> "" Then
      &MSGString = &Where | &MSGString | &And | " RQSTMSGNAME LIKE '%" | WEBLIB_MSGWSDL.RQSTMSGNAME | "%'";
   End-If;

   SQLExec("SELECT COUNT(*) FROM PSNODETRXVW2 " | &MSGString, &nReturn);

   If (&nReturn > 0) Then;
      &Level1.ShowAllRows();
      &Level0.Select(Scroll.PSNODETRXVW2, Record.PSNODETRXVW2, &MSGString);
   Else
      &Level1.HideAllRows();
   End-If;

Else
   /* web service to CI */
   Local string &CIString;
   Local ApiObject &oSession, &oCIColl, &oCI;
   Local number &i, &j;
   Local string &sqlStr, &nodeName, &ciDescr;
   Local SQL &sqlObj;


   /* find all external nodes that have a SOAPTOCI message with a */
   /* transaction type of incomingSync. We want to exclude the local */
   /* node from this list. */

   &sqlStr = "SELECT MSGNODENAME FROM PSNODETRXVW2 WHERE RQSTMSGNAME='SOAPTOCI' AND TRXTYPE='IS'";

   Local array of string &nodelist = CreateArrayRept("", 0);

   &sqlObj = CreateSQL(&sqlStr);
   While &sqlObj.Fetch(&nodeName)
      If (&nodeName <> %LocalNode) Then

         rem The user may have entered in a nodeName. If so we need to only return;
         rem that one;
         If (WEBLIB_SOAPTOCI.MSGNODENAME.Value <> "") Then
            If (&nodeName = WEBLIB_SOAPTOCI.MSGNODENAME.Value) Then
               &nodelist.Push(&nodeName);
            End-If;
         Else
            &nodelist.Push(&nodeName);
         End-If;
      End-If;
   End-While;
   &sqlObj.Close();

   Local string &temp = "";

   &Level0 = GetLevel0();
   &Level1 = &Level0(1).GetRowset(Scroll.PSCIWBSRVSVW);
   &Level0(1).GetRowset(Scroll.PSNODETRXVW2).HideAllRows();
   &Level1.Flush();
   &oSession = %Session;

   /* get the list of allowed CIs for this user */
   &oCIColl = &oSession.FindCompIntfcs("%" | WEBLIB_SOAPTOCI.WSNAME | "%");

   If (&oCIColl.Count > 0 And
         &nodelist.Len > 0) Then

      Local number &rowCount = 0;

      /* for every CI available... */
      For &i = 1 To &oCIColl.Count

         &oCI = &oCIColl.Item(&i);

         /* for every external msgnode where there is a valid SOAPTOCI transaction... */
         For &j = 1 To &nodelist.Len

            If (&rowCount <> 0) Then
               &Level1.InsertRow(&rowCount);
            End-If;

            &rowCount = &rowCount + 1;

            &Level1.GetRow(&rowCount).WEBLIB_SOAPTOCI.WSDLHTML.Value = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_SOAPTOCI, Field.WSDLSUMMARY, "FieldFormula", "IScript_WSDLDiscovery") | "?&APIName=" | &oCI.compIntfcName | "&nodeName=" | &nodelist [&j];

            &Level1.GetRow(&rowCount).PSCIWBSRVSVW.BCNAME.Value = &oCI.compIntfcName;
            &Level1.GetRow(&rowCount).PSCIWBSRVSVW.MSGNODENAME.Value = &nodelist [&j];

            /* we may need to hide rows based on description */
            If (WEBLIB_SOAPTOCI.DESCR <> "") Then

               &ciDescr = &Level1.GetRow(&rowCount).PSBCDEFN.DESCR.Value;

               If (Find(WEBLIB_SOAPTOCI.DESCR, &ciDescr) < 1) Then
                  &Level1.GetRow(&rowCount).Visible = False;
               Else
                  &Level1.GetRow(&rowCount).Visible = True;
               End-If;

            End-If;

         End-For;
      End-For;
   Else
      &Level1.HideAllRows();
   End-If;



End-If;

import WEBSERVICES:*;

/* Create the constant object */
Local WEBSERVICES:Constants &WSDLConstant = create WEBSERVICES:Constants();

/* Fire the IScript */
WEBLIB_MSGWSDL.WSDLHTML = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_MSGWSDL, Field.WSDLSUMMARY, "FieldFormula", "IScript_WSDLDiscovery") | "?" | &WSDLConstant.QUERY_PARM_NODE | "=" | PSNODETRXVW2.MSGNODENAME | "&" | &WSDLConstant.QUERY_PARM_EFFDT | "=" | PSNODETRXVW2.EFFDT | "&" | &WSDLConstant.QUERY_PARM_TRXTYPE | "=" | PSNODETRXVW2.TRXTYPE | "&" | &WSDLConstant.QUERY_PARM_REQUEST_MESSAGE_NAME | "=" | PSNODETRXVW2.RQSTMSGNAME | "&" | &WSDLConstant.QUERY_PARM_REQUEST_MESSAGE_VERSION | "=" | PSNODETRXVW2.RQSTMSGVER | "&" | &WSDLConstant.QUERY_PARM_RESPONSE_MESSAGE_NAME | "=" | PSNODETRXVW2.RESPMSGNAME | "&" | &WSDLConstant.QUERY_PARM_RESPONSE_MESSAGE_VERSION | "=" | PSNODETRXVW2.RESPMSGVER;

import WEBSERVICES:*;

Function IScript_WSDLDiscovery()

   try

      /* Create the objects */
      Local WEBSERVICES:Constants &WSDLConstant = create WEBSERVICES:Constants();
      Local WEBSERVICES:ExportUtility &exportUtil = create WEBSERVICES:ExportUtility();

      /* Get the WSDL data */
      Local string &theWSDL = &exportUtil.Export(%Request.GetParameter(&WSDLConstant.QUERY_PARM_NODE), %Request.GetParameter(&WSDLConstant.QUERY_PARM_EFFDT), %Request.GetParameter(&WSDLConstant.QUERY_PARM_TRXTYPE), %Request.GetParameter(&WSDLConstant.QUERY_PARM_REQUEST_MESSAGE_NAME), %Request.GetParameter(&WSDLConstant.QUERY_PARM_REQUEST_MESSAGE_VERSION), %Request.GetParameter(&WSDLConstant.QUERY_PARM_RESPONSE_MESSAGE_NAME), %Request.GetParameter(&WSDLConstant.QUERY_PARM_RESPONSE_MESSAGE_VERSION));

      /* Set the content and write the WSDL */
      %Response.SetContentType("text/xml");
      %Response.Write(&theWSDL);

   catch Exception &e

      /* Write out the error */
      %Response.Write(&e.ToString());

   end-try;

End-Function;

