Function IScript_LoadBread()
   &Response = %Response;
   &Response.Write("<HTML dir='" | %Direction | "'>");
   &Response.Write("<HEAD>");
   Local string &authdomain = SetDocDomainToAuthTokenDomain();
   If &authdomain <> "" Then
      &Response.Write(&authdomain);
   End-If;
   &Response.Write("<SCRIPT Language='javascript'>");
   &Response.Write("parent.LoadBread(parent.treeControl.GetRootNode());");
   &Response.Write("</SCRIPT>");
   &Response.Write("</HEAD>");
   &Response.Write("<BODY>");
   &Response.Write("</BODY>");
   &Response.Write("</HTML>");
End-Function;

