Local string &ps_strTitle;
Local string &ps_strCompleted;
Local string &ps_strSecsRemain;
Local string &ps_strMinsRemain;
Local string &ps_strHrsRemain;
Local string &ps_RenSrv;
Local string &ps_progId;
Local string &cssPTSTYLEDEF;
Local string &HTML;
Local string &ps_pgHeader;
Local string &ps_MsgTxt;
Local string &ps_strCompletedAt;

REM ***************************************************************************************;
REM Function:		IScript_ProgressMeter							  ;
REM Purpose:		Generate HTML page for Report Notification                             ;
REM Inputs:												  ;
REM Output:				                                                         ;
REM ***************************************************************************************;

Function IScript_ProgressMeter()
   &ps_progId = %Request.GetParameter("ProgId");
   &ps_RenSrv = %Request.GetParameter("RenSrv");
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(StyleSheet.PTSTYLEDEF);

   &ps_strTitle = MsgGetText(3, 56, "Progress Meter");
   &ps_strCompleted = MsgGetText(3, 54, "complete");
   &ps_strSecsRemain = MsgGetText(3, 55, "seconds remaining");
   &ps_strMinsRemain = MsgGetText(3, 57, "minutes remaining");
   &ps_strHrsRemain = MsgGetText(3, 58, "hours remaining");
   &ps_strCompletedAt = MsgGetText(3, 52, "Completed at ");

   &ps_MsgTxt = "This windows shows the transaction progress";

   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(StyleSheet.PTSTYLEDEF);
   &HTML = GetHTMLText(HTML.PROGMETER, &ps_strTitle, &cssPTSTYLEDEF, EscapeHTML(&ps_progId), &ps_MsgTxt, &ps_strCompleted, &ps_strSecsRemain, EscapeHTML(&ps_RenSrv), &ps_strMinsRemain, &ps_strHrsRemain, &ps_strCompletedAt);

   %Response.Write(&HTML);
End-Function;

Local SQL &SQL;
Local Record &REC;

Function IScript_View300()
   &REQUEST = %Request;
   &RESPONSE = %Response;

   &RESPONSE.SetContentType("application/msword");
   &RESPONSE.SetHeader("Content-disposition", "attachment; filename=" | &REQUEST.GetParameter("PRCSNAME") | "_" | &REQUEST.GetParameter("RUNCNTLID") | ".doc");
   &REC = CreateRecord(Record.OSHA_300_RUNS);
   &SQL = CreateSQL("%SELECTALL(:1) WHERE OPRID = :2 AND RUNCNTLID = :3 AND DTTM_STAMP = %DATETIMEIN(:4) ORDER BY SEQ_NBR");

   &SQL.Execute(&REC, %UserId, &REQUEST.GetParameter("RUNCNTLID"), &REQUEST.GetParameter("DTTM_STAMP"));
   While &SQL.Fetch(&REC)
      &RESPONSE.write(&REC.FILE_DATA_CHAR.Value);
   End-While;

   &SQL.Close();
   Return;
End-Function;

