Function JSONEscape(&s As string) Returns string
   &s = Substitute(&s, "\", "\\");
   &s = Substitute(&s, """", "\""");
   &s = Substitute(&s, Char(13), "\r");
   &s = Substitute(&s, Char(10), "\n");
   &s = Substitute(&s, Char(9), "\t");
   Return &s;
End-Function;

Function GetRequireConfigJs(&siteBase As string) Returns string
