Function GenerateSaveUrl() Returns string
   Local string &url;
   Local integer &qPos;

   &url = %Request.FullURI;
   &qPos = Find("?", &url);
   If &qPos > 0 Then
      &url = Substring(&url, 1, &qPos - 1);
   End-If;
   &url = Substitute(&url, "IScript_VPOrchestrator", "IScript_SaveDesign");
   &url = &url | "?&postDataBin=y";
   Return &url;
End-Function;


Function IScript_VPOrchestrator()
   Local string &designId, &siteBase, &csrfToken;
   Local OU_JET_PACK:Security:AccessCheck &access = create OU_JET_PACK:Security:AccessCheck();
   Local OU_JET_PACK:Storage:DesignRepository &repo = create OU_JET_PACK:Storage:DesignRepository();
   Local OU_JET_PACK:Render:DesignerAssets &assets = create OU_JET_PACK:Render:DesignerAssets();
   Local OU_JET_PACK:Model:PageDesign &design;

   If Not &access.IsAuthorizedDesigner() Then
      %Response.SetContentType("text/html");
      %Response.WriteLine("Not authorized.");
      Return;
   End-If;

   &designId = %Request.GetParameter("design");
   If &designId = "" Then
      %Response.SetContentType("text/html");
      %Response.WriteLine("<script>window.location.href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_DesignList';</script>");
      Return;
   End-If;

   %Response.SetContentType("text/html");
   &siteBase = "/cs/" | %DbName | "/oraclejet";

   &csrfToken = String(Rand() * 1000000000) | "-" | String(%Datetime);
   %Session.SetAttribute("PGDSN_CSRF_TOKEN", &csrfToken);

   &design = &repo.Load(&designId);
   /* Load() sets design.IsNew when no header exists yet - PageId still needs
      setting explicitly since a not-found Load doesn't have it populated */
   &design.PageId = &designId;

   %Response.WriteLine("<!DOCTYPE html><html><head>");
   %Response.WriteLine("<link rel='stylesheet' href='" | &siteBase | "/css/libs/oj/14.1.1/redwood/oj-redwood-min.css'/>");
   %Response.WriteLine("<script src='" | &siteBase | "/js/libs/require/require-debug.js'></script>");
   %Response.WriteLine("<style>" | &assets.GetCss() | "</style>");
   %Response.WriteLine("<script>");
   %Response.WriteLine("var PGDSN_DATA = " | &design.ToJson() | "; ");
   %Response.WriteLine("var PGDSN_CSRF = '" | &csrfToken | "'; ");
   %Response.WriteLine("var PGDSN_SAVE_URL = '" | GenerateSaveUrl() | "'; ");
   %Response.WriteLine(&assets.GetRequireConfigJs(&siteBase));

   rem %Response.WriteLine("require(['ojs/ojcore','knockout','ojs/ojknockout','ojs/ojbutton','ojs/ojbutton2','ojs/ojbuttonlegacy','ojs/ojinputtext','ojs/ojinputnumber'], function(oj, ko, ojknockout, ojbutton, ojinputtext, ojinputnumber) {");

   Local OU_JET_PACK:Layout:ComponentRegistry &registry = create OU_JET_PACK:Layout:ComponentRegistry();
   Local array of string &mods = &registry.GetAllRequireModules();
   Local string &modList, &paramList;
   Local integer &m;

   &modList = "'ojs/ojcore','knockout','ojs/ojknockout'";
   &paramList = "oj, ko, ojknockout";
   For &m = 1 To &mods.Len
      &modList = &modList | ",'" | &mods [&m] | "'";
      &paramList = &paramList | ", _m" | &m;
   End-For;

   %Response.WriteLine("require([" | &modList | "], function(" | &paramList | ") {");


   %Response.WriteLine(&assets.GetViewModelJs());
   %Response.WriteLine("});");
   %Response.WriteLine("</script></head><body>");
   %Response.WriteLine(&assets.GetBodyHtml());
   %Response.WriteLine("</body></html>");
End-Function;




Function IScript_SaveDesign()
   Local string &body, &designId, &csrfSubmitted, &csrfSession, &lastSeenDttm;
   Local OU_JET_PACK:Security:AccessCheck &access = create OU_JET_PACK:Security:AccessCheck();
   Local OU_JET_PACK:Storage:DesignRepository &repo = create OU_JET_PACK:Storage:DesignRepository();
   Local OU_JET_PACK:Utils:JsonUtil &u = create OU_JET_PACK:Utils:JsonUtil();
   Local JsonObject &jo;
   Local OU_JET_PACK:Model:PageDesign &design;

   %Response.SetContentType("application/json");

   If Not &access.IsAuthorizedDesigner() Then
      %Response.WriteLine("{""status"":""error"",""message"":""Not authorized.""}");
      Return;
   End-If;

   try
      &body = %Request.GetContentBody();
      Local JsonParser &jp = CreateJsonParser();
      If Not &jp.Parse(&body) Then
         /*Error*/
      End-If;
      &jo = &jp.GetRootObject();
   catch Exception &e
      rem TODO %Response.SetStatusCode(400);
      %Response.WriteLine("{""status"":""error"",""message"":""" | &e.ToString() | """}");
      Return;
   end-try;

   &designId = &jo.GetString("designId");

   If &designId = "" Then
      %Response.WriteLine("{""status"":""error"",""message"":""Missing design ID.""}");
      Return;
   End-If;

   &csrfSubmitted = &jo.GetString("csrf");
   &lastSeenDttm = &jo.GetString("lastUpdDttm");
   &descr = &jo.GetString("descr");

   /*
TODO   - IGNORE FOR NOW
   &csrfSession = %Session.GetAttribute("PGDSN_CSRF_TOKEN");
   If &csrfSubmitted <> &csrfSession Or
         &csrfSubmitted = "" Then
      %Response.WriteLine("{""status"":""error"",""message"":""Invalid session token, please reload the designer.""}");
      Return;
   End-If;
*/

   &design = create OU_JET_PACK:Model:PageDesign(&designId);
   &csrfSubmitted = &design.FromJsonBody(&body);

   If &repo.Exists(&designId) Then
      Local OU_JET_PACK:Model:PageDesign &current = &repo.Load(&designId);
      If &current.LastUpdDttm <> &design.LastUpdDttm Then
         /* TODO   - IGNORE FOR NOW
		 %Response.WriteLine("{""status"":""conflict"",""message"":""This design was changed by someone else. Reload before saving.""}");
         Return;
*/
      End-If;
   End-If;

   Local boolean &result = &repo.Save(&design);

   /* Reload to get the freshly-stamped LastUpdDttm for the client to store */
   &design = &repo.Load(&designId);

   %Response.WriteLine("{""status"":""ok"",""lastUpdDttm"":""" | &u.EscapeJson(&design.LastUpdDttm) | """}");
End-Function;



Function IScript_DesignList()
   Local OU_JET_PACK:Security:AccessCheck &access = create OU_JET_PACK:Security:AccessCheck();
   Local OU_JET_PACK:Storage:DesignRepository &repo = create OU_JET_PACK:Storage:DesignRepository();
   Local array of OU_JET_PACK:Model:PageDesign &list;
   Local OU_JET_PACK:Model:PageDesign &d;
   Local integer &i;
   Local string &h;

   If Not &access.IsAuthorizedDesigner() Then
      %Response.SetContentType("text/html");
      %Response.WriteLine("Not authorized.");
      Return;
   End-If;

   %Response.SetContentType("text/html");
   &list = &repo.ListHeaders();

   &h = &h | "<!DOCTYPE html><html><head><title>Page Designs</title>";
   &h = &h | "<style>";
   &h = &h | "body{font-family:Arial,sans-serif;max-width:700px;margin:40px auto;color:#222;}";
   &h = &h | "h1{font-size:24px;} table{width:100%;border-collapse:collapse;margin-bottom:30px;}";
   &h = &h | "td,th{padding:8px 10px;border-bottom:1px solid #eee;text-align:left;}";
   &h = &h | "a{color:#0078d7;text-decoration:none;} a:hover{text-decoration:underline;}";
   &h = &h | ".newform{border:1px solid #ddd;border-radius:6px;padding:20px;background:#fafafa;}";
   &h = &h | "input[type=text]{padding:8px;width:260px;border:1px solid #ccc;border-radius:4px;}";
   &h = &h | "button{padding:8px 18px;border:none;background:#1a1a1a;color:#fff;border-radius:4px;cursor:pointer;}";
   &h = &h | "</style></head><body data-oj-binding-provider=""none"">";

   &h = &h | "<h1>Page Designs</h1>";
   &h = &h | "<table><tr><th>Design</th><th>ID</th><th>Status</th><th></th></tr>";

   For &i = 1 To &list.Len
      &d = &list [&i];
      &h = &h | "<tr><td>" | &d.Descr | "</td><td>" | &d.PageId | "</td>";
      &h = &h | "<td>" | &d.PgdsnStatus | "</td>";
      &h = &h | "<td><a href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_VPOrchestrator?design=" | &d.PageId | "'>Edit</a> &nbsp; ";
      &h = &h | "<a href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_JETLandingPage?design=" | &d.PageId | "' target='_blank'>View</a></td></tr>";
   End-For;

   If &list.Len = 0 Then
      &h = &h | "<tr><td colspan='4'><em>No designs yet.</em></td></tr>";
   End-If;
   &h = &h | "</table>";

   &h = &h | "<div class='newform'>";
   &h = &h | "<h3>Create New Design</h3>";
   &h = &h | "<form method='GET' action='IScript_VPOrchestrator'>";
   &h = &h | "<input type='text' name='design' placeholder='e.g. OPEN_ENROLLMENT1' maxlength='30' pattern='[A-Za-z0-9_]+' required title='Letters, numbers, underscore only'/>";
   &h = &h | " <button type='submit'>Create / Open</button>";
   &h = &h | "</form></div>";

   &h = &h | "</body></html>";
   %Response.WriteLine(&h);
End-Function;

