Function GetLayoutPercentages(&layoutCode As string) Returns array of number
   Local array of number &pcts;

   Evaluate &layoutCode
   When "1COL"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(100);
   When "2COL_5050"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(50);
      &pcts.Push(50);
   When "2COL_7030"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(70);
      &pcts.Push(30);
   When "2COL_3070"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(30);
      &pcts.Push(70);
   When "2COL_6040"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(60);
      &pcts.Push(40);
   When "2COL_4060"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(40);
      &pcts.Push(60);
   When "3COL_333333"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(33.34);
      &pcts.Push(33.33);
      &pcts.Push(33.33);
   When "3COL_502525"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(50);
      &pcts.Push(25);
      &pcts.Push(25);
   When "3COL_255025"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(25);
      &pcts.Push(50);
      &pcts.Push(25);
   When "3COL_252550"
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(25);
      &pcts.Push(25);
      &pcts.Push(50);
   When-Other
      &pcts = CreateArrayRept(0, 0);
      &pcts.Push(100);
   End-Evaluate;

   Return &pcts;
End-Function;


Function RenderPageDesign(&designId As string) Returns string
   Local Rowset &rsRows, &rsCols;
   Local string &out, &style;
   Local integer &r, &c;
   Local array of number &pcts;

   &out = "";
   &rsRows = CreateRowset(Record.OU_JET_PG_ROW);
   &rsRows.Fill("WHERE OU_PAGE_ID = :1 ORDER BY OU_SEQNBR_ROW", &designId);

   For &r = 1 To &rsRows.ActiveRowCount
      Local Record &rowRec = &rsRows(&r).OU_JET_PG_ROW;
      &pcts = GetLayoutPercentages(&rowRec.OU_ROW_LAYOUT.Value);

      &style = "";
      If &rowRec.OU_BGCOLOR.Value <> "" Then
         &style = &style | "background-color:" | &rowRec.OU_BGCOLOR.Value | ";";
      End-If;
      If &rowRec.OU_ROW_BG_IMG_URL.Value <> "" Then
         &style = &style | "background-image:url(" | &rowRec.OU_ROW_BG_IMG_URL.Value | ");background-size:cover;background-position:center;";
      End-If;

      &out = &out | "<div class='oj-flex jet-pg-row' style='" | &style | "'>";

      &rsCols = CreateRowset(Record.OU_JET_PG_COL);
      &rsCols.Fill("WHERE OU_PAGE_ID = :1 AND OU_SEQNBR_ROW = :2 ORDER BY OU_SEQNBR_COL", &designId, &rowRec.OU_SEQNBR_ROW.Value);

      For &c = 1 To &rsCols.ActiveRowCount
         Local Record &colRec = &rsCols(&c).OU_JET_PG_COL;
         Local number &pct;
         If &c <= &pcts.Len Then
            &pct = &pcts [&c];
         Else
            &pct = 100 / &rsCols.ActiveRowCount;
         End-If;

         &out = &out | "<div class='oj-flex-item jet-pg-col' style='flex-basis:" | &pct | "%;'>";

         Evaluate &colRec.CONTENT_TYPE.Value
         When "TEXT"
            &out = &out | "<p>" | &colRec.DESCRLONG.Value | "</p>";
         When "HTML"
            &out = &out | &colRec.DESCRLONG.Value;
         When "IMAGE"
            &out = &out | "<img class='jet-pg-img' src='" | &colRec.IMAGE_URL.Value | "'/>";
         When "LINK"
            &out = &out | "<a class='oj-button jet-pg-link' href='" | &colRec.URL_ADDRESS.Value | "'>" | &colRec.DESCR_LABEL.Value | "</a>";
         End-Evaluate;

         &out = &out | "</div>";
      End-For;

      &out = &out | "</div>";
   End-For;

   Return &out;
End-Function;


Function IScript_JETLandingPage()

   Local string &designId, &siteBase, &bodyHtml;

   &designId = %Request.GetParameter("design");
   If &designId = "" Then
      %Response.WriteLine("No design specified.");
      Return;
   End-If;

   %Response.SetContentType("text/html");
   &siteBase = "/cs/" | %DbName | "/oraclejet";

   &bodyHtml = RenderPageDesign(&designId);

   %Response.WriteLine("<!DOCTYPE html><html><head>");
   %Response.WriteLine("<link rel='stylesheet' href='" | &siteBase | "/css/libs/oj/14.1.1/redwood/oj-redwood-min.css'/>");
   %Response.WriteLine("<style>");
   %Response.WriteLine("body{margin:0;font-family:Arial,sans-serif;}");
   %Response.WriteLine(".jet-pg-row{width:100%;}");
   %Response.WriteLine(".jet-pg-col{padding:24px;box-sizing:border-box;}");
   %Response.WriteLine(".jet-pg-img{max-width:100%;display:block;}");
   %Response.WriteLine("</style>");
   %Response.WriteLine("</head><body>");
   %Response.WriteLine(&bodyHtml);
   %Response.WriteLine("</body></html>");
End-Function;

Function JSONEscape(&s As string) Returns string
   &s = Substitute(&s, "\", "\\");
   &s = Substitute(&s, """", "\""");
   &s = Substitute(&s, Char(13), "\r");
   &s = Substitute(&s, Char(10), "\n");
   &s = Substitute(&s, Char(9), "\t");
   &s = Substitute(&s, "</", "<\/");
   Return &s;
End-Function;


