Function GenerateSaveUrl() Returns string
   Local string &url;
   Local integer &qPos;

   &url = %Request.FullURI;

   /* Strip any existing query string (e.g. ?design=...) before swapping the function name */
   &qPos = Find("?", &url);
   If &qPos > 0 Then
      &url = Substring(&url, 1, &qPos - 1);
   End-If;

   &url = Substitute(&url, "IScript_VPOrchestrator", "IScript_SaveDesign");
   &url = &url | "?&postDataBin=y";
   Return &url;
End-Function;

