Function GetDesignerViewModelJs() Returns string
   Local string &j;

   &j = &j | Char(10) | "var LAYOUT_OPTIONS = [";
   &j = &j | Char(10) | "  { code:'1COL',        label:'100%',              segments:[100] },";
   &j = &j | Char(10) | "  { code:'2COL_5050',   label:'50% / 50%',         segments:[50,50] },";
   &j = &j | Char(10) | "  { code:'2COL_7030',   label:'70% / 30%',         segments:[70,30] },";
   &j = &j | Char(10) | "  { code:'2COL_3070',   label:'30% / 70%',         segments:[30,70] },";
   &j = &j | Char(10) | "  { code:'2COL_6040',   label:'60% / 40%',         segments:[60,40] },";
   &j = &j | Char(10) | "  { code:'2COL_4060',   label:'40% / 60%',         segments:[40,60] },";
   &j = &j | Char(10) | "  { code:'3COL_333333', label:'33% / 33% / 33%',   segments:[33.34,33.33,33.33] },";
   &j = &j | Char(10) | "  { code:'3COL_502525', label:'50% / 25% / 25%',   segments:[50,25,25] },";
   &j = &j | Char(10) | "  { code:'3COL_255025', label:'25% / 50% / 25%',   segments:[25,50,25] },";
   &j = &j | Char(10) | "  { code:'3COL_252550', label:'25% / 25% / 50%',   segments:[25,25,50] }";
   &j = &j | Char(10) | "];";

   &j = &j | Char(10) | "function layoutByCode(code) {";
   &j = &j | Char(10) | "  for (var i=0;i<LAYOUT_OPTIONS.length;i++) { if (LAYOUT_OPTIONS[i].code===code) return LAYOUT_OPTIONS[i]; }";
   &j = &j | Char(10) | "  return LAYOUT_OPTIONS[0];";
   &j = &j | Char(10) | "}";

   /* --- Build a col object from server data + its position within the row's layout --- */
   &j = &j | Char(10) | "function buildCol(colData, segments, idx) {";
   &j = &j | Char(10) | "  return {";
   &j = &j | Char(10) | "    colSeq: colData.colSeq,";
   &j = &j | Char(10) | "    contentType: ko.observable(colData.contentType || 'TEXT'),";
   &j = &j | Char(10) | "    textValue: ko.observable(colData.textValue || ''),";
   &j = &j | Char(10) | "    imageUrl: ko.observable(colData.imageUrl || ''),";
   &j = &j | Char(10) | "    linkUrl: ko.observable(colData.linkUrl || ''),";
   &j = &j | Char(10) | "    linkLabel: ko.observable(colData.linkLabel || ''),";
   &j = &j | Char(10) | "    colWidthPct: ko.observable(segments[idx] || (100/segments.length))";
   &j = &j | Char(10) | "  };";
   &j = &j | Char(10) | "}";

   /* --- Build a row object from server data --- */
   &j = &j | Char(10) | "function buildRow(rowData) {";
   &j = &j | Char(10) | "  var layoutDef = layoutByCode(rowData.layout);";
   &j = &j | Char(10) | "  var row = {";
   &j = &j | Char(10) | "    rowSeq: rowData.rowSeq,";
   &j = &j | Char(10) | "    layout: ko.observable(rowData.layout),";
   &j = &j | Char(10) | "    bgColor: ko.observable(rowData.bgColor || ''),";
   &j = &j | Char(10) | "    bgImage: ko.observable(rowData.bgImage || ''),";
   &j = &j | Char(10) | "    cols: ko.observableArray([])";
   &j = &j | Char(10) | "  };";
   &j = &j | Char(10) | "  row.layoutLabel = ko.computed(function() { return layoutByCode(row.layout()).label; });";
   &j = &j | Char(10) | "  var segs = layoutDef.segments;";
   &j = &j | Char(10) | "  (rowData.cols||[]).forEach(function(c, idx) { row.cols.push(buildCol(c, segs, idx)); });";
   &j = &j | Char(10) | "  return row;";
   &j = &j | Char(10) | "}";

   /* --- The Knockout viewModel --- */
   &j = &j | Char(10) | "var viewModel = {";
   &j = &j | Char(10) | "  pageTitle: ko.observable(PGDSN_DATA.descr || PGDSN_DATA.designId),";
   &j = &j | Char(10) | "  lastUpdDttm: ko.observable(PGDSN_DATA.lastUpdDttm),";
   &j = &j | Char(10) | "  rows: ko.observableArray((PGDSN_DATA.rows||[]).map(buildRow)),";
   &j = &j | Char(10) | "  layoutOptions: LAYOUT_OPTIONS,";
   &j = &j | Char(10) | "  showAddRowPanel: ko.observable(false),";
   &j = &j | Char(10) | "  saving: ko.observable(false)";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.openAddRowPanel = function() { viewModel.showAddRowPanel(true); };";
   &j = &j | Char(10) | "viewModel.closeAddRowPanel = function() { viewModel.showAddRowPanel(false); };";

   &j = &j | Char(10) | "viewModel.selectLayout = function(layoutDef) {";
   &j = &j | Char(10) | "  var maxSeq = 0;";
   &j = &j | Char(10) | "  viewModel.rows().forEach(function(r) { if (r.rowSeq > maxSeq) maxSeq = r.rowSeq; });";
   &j = &j | Char(10) | "  var newRowData = { rowSeq: maxSeq + 10, layout: layoutDef.code, bgColor:'', bgImage:'',";
   &j = &j | Char(10) | "    cols: layoutDef.segments.map(function(pct, i) { return { colSeq: i+1, contentType:'TEXT', textValue:'New content' }; }) };";
   &j = &j | Char(10) | "  viewModel.rows.push(buildRow(newRowData));";
   &j = &j | Char(10) | "  viewModel.closeAddRowPanel();";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.deleteRow = function(row) {";
   &j = &j | Char(10) | "  if (confirm('Delete this row?')) { viewModel.rows.remove(row); }";
   &j = &j | Char(10) | "};";

   /* Placeholder inline editing - simple prompt() until a real editing panel is designed */
   &j = &j | Char(10) | "viewModel.selectCell = function(row, col) {";
   &j = &j | Char(10) | "  var ct = col.contentType();";
   &j = &j | Char(10) | "  if (ct === 'TEXT' || ct === 'HTML') {";
   &j = &j | Char(10) | "    var v = prompt('Edit text:', col.textValue()); if (v !== null) col.textValue(v);";
   &j = &j | Char(10) | "  } else if (ct === 'IMAGE') {";
   &j = &j | Char(10) | "    var v = prompt('Image URL:', col.imageUrl()); if (v !== null) col.imageUrl(v);";
   &j = &j | Char(10) | "  } else if (ct === 'LINK') {";
   &j = &j | Char(10) | "    var u = prompt('Link URL:', col.linkUrl()); if (u !== null) col.linkUrl(u);";
   &j = &j | Char(10) | "    var l = prompt('Link label:', col.linkLabel()); if (l !== null) col.linkLabel(l);";
   &j = &j | Char(10) | "  }";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.openSettings = function() {";
   &j = &j | Char(10) | "  var v = prompt('Page title:', viewModel.pageTitle()); if (v !== null) viewModel.pageTitle(v);";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.togglePreview = function() {";
   &j = &j | Char(10) | "  var url = window.location.pathname.replace('IScript_PageDesigner','IScript_JETLandingPage') + '?design=' + PGDSN_DATA.designId;";
   &j = &j | Char(10) | "  window.open(url, '_blank');";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.closeDesigner = function() {";
   &j = &j | Char(10) | "  if (confirm('Leave designer? Unsaved changes will be lost.')) { window.close(); }";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "viewModel.saveDesign = function() {";
   &j = &j | Char(10) | "  viewModel.saving(true);";
   &j = &j | Char(10) | "  var payload = { designId: PGDSN_DATA.designId, csrf: PGDSN_CSRF, lastUpdDttm: viewModel.lastUpdDttm(),";
   &j = &j | Char(10) | "    descr: viewModel.pageTitle(),";
   &j = &j | Char(10) | "    rows: viewModel.rows().map(function(r) { return { rowSeq: r.rowSeq, layout: r.layout(), bgColor: r.bgColor(), bgImage: r.bgImage(),";
   &j = &j | Char(10) | "      cols: r.cols().map(function(c) { return { colSeq: c.colSeq, contentType: c.contentType(), textValue: c.textValue(), imageUrl: c.imageUrl(), linkUrl: c.linkUrl(), linkLabel: c.linkLabel() }; }) }; })";
   &j = &j | Char(10) | "  };";
   /*
   &j = &j | Char(10) | "  fetch(PGDSN_SAVE_URL, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) })";
   &j = &j | Char(10) | "    .then(function(resp) { return resp.json().then(function(data) { return { status: resp.status, data: data }; }); })";
   &j = &j | Char(10) | "    .then(function(result) {";
   &j = &j | Char(10) | "      viewModel.saving(false);";
   &j = &j | Char(10) | "      if (result.status === 200) { viewModel.lastUpdDttm(result.data.lastUpdDttm); alert('Saved.'); }";
   &j = &j | Char(10) | "      else if (result.status === 409) { alert('This design was changed by someone else. Reload before saving.'); }";
   &j = &j | Char(10) | "      else { alert('Save failed: ' + (result.data.message || result.status)); }";
   &j = &j | Char(10) | "    })";
*/
   &j = &j | Char(10) | "  fetch(PGDSN_SAVE_URL, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(payload) }) ";
   &j = &j | Char(10) | "    .then(function(resp) { return resp.json(); }) ";
   &j = &j | Char(10) | "    .then(function(data) { ";
   &j = &j | Char(10) | "      viewModel.saving(false); ";
   &j = &j | Char(10) | "      if (data.status === 'ok') { viewModel.lastUpdDttm(data.lastUpdDttm); alert('Saved.'); } ";
   &j = &j | Char(10) | "      else if (data.status === 'conflict') { alert('This design was changed by someone else. Reload before saving.'); } ";
   &j = &j | Char(10) | "      else { alert('Save failed: ' + (data.message || 'Unknown error')); } ";
   &j = &j | Char(10) | "    }) ";

   &j = &j | Char(10) | "    .catch(function(err) { viewModel.saving(false); alert('Save failed: ' + err); });";
   &j = &j | Char(10) | "};";

   &j = &j | Char(10) | "ko.applyBindings(viewModel, document.getElementById('designerRoot'));";

   Return &j;
End-Function;


Function IScript_PageDesigner()
   Local string &designId, &siteBase, &json, &csrfToken;
   Local Rowset &rsHdr, &rsRows, &rsCols;
   Local integer &r, &c;

   &designId = %Request.GetParameter("design");

   If &designId = "" Then
      %Response.WriteLine("<script>window.location.href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_DesignList';</script>");
      Return;
   End-If;

   /* 
TODO :
Permission check FIRST, before anything else executes 
   If Not %OperatorId Or Not %AccessProfile.CheckAuthorization("OU_PAGEDESIGNER_ADMIN") Then
      %Response.SetStatusCode(403);
      %Response.WriteLine("Not authorized.");
      Return;
   End-If;
*/

   %Response.SetContentType("text/html");

   /* TODO - Debug Message */
   rem %Response.WriteLine("Full URI: " | %Request.FullURI);

   &siteBase = "/cs/" | %DbName | "/oraclejet"; /* reuse confirmed path */

   /* Generate a CSRF token and stash it in the session for IScript_SaveDesign to check */
   &csrfToken = String(Rand() * 1000000000) | "-" | String(%Datetime);
   %Session.SetAttribute("PGDSN_CSRF_TOKEN", &csrfToken);

   /* Build the current design as JSON to hand to the client-side Knockout viewModel */
   &rsHdr = CreateRowset(Record.OU_JET_PG_HDR);
   &rsHdr.Fill("WHERE OU_PAGE_ID = :1", &designId);

   &json = "{""designId"":""" | &designId | """,";
   If &rsHdr.ActiveRowCount > 0 Then
      &json = &json | """descr"":""" | JSONEscape(&rsHdr(1).OU_JET_PG_HDR.DESCR.Value) | """,";
      &json = &json | """lastUpdDttm"":""" | DateTimeToLocalizedString(&rsHdr(1).OU_JET_PG_HDR.LASTUPDDTTM.Value, "YYYY-MM-DD-HH24.MI.SS.000000") | """,";
   Else
      &json = &json | """descr"":"""",""lastUpdDttm"":"""",";
   End-If;

   &json = &json | """rows"":[";
   &rsRows = CreateRowset(Record.OU_JET_PG_ROW);
   &rsRows.Fill("WHERE OU_PAGE_ID = :1 ORDER BY OU_SEQNBR_ROW", &designId);

   For &r = 1 To &rsRows.ActiveRowCount
      If &r > 1 Then
         &json = &json | ",";
      End-If;
      Local Record &rowRec = &rsRows(&r).OU_JET_PG_ROW;
      &json = &json | "{""rowSeq"":" | &rowRec.OU_SEQNBR_ROW.Value | ",";
      &json = &json | """layout"":""" | JSONEscape(&rowRec.OU_ROW_LAYOUT.Value) | """,";
      &json = &json | """bgColor"":""" | JSONEscape(&rowRec.OU_BGCOLOR.Value) | """,";
      &json = &json | """bgImage"":""" | JSONEscape(&rowRec.OU_ROW_BG_IMG_URL.Value) | """,";
      &json = &json | """cols"":[";

      &rsCols = CreateRowset(Record.OU_JET_PG_COL);
      &rsCols.Fill("WHERE OU_PAGE_ID = :1 AND OU_SEQNBR_ROW = :2 ORDER BY OU_SEQNBR_COL", &designId, &rowRec.OU_SEQNBR_ROW.Value);
      For &c = 1 To &rsCols.ActiveRowCount
         If &c > 1 Then
            &json = &json | ",";
         End-If;
         Local Record &colRec = &rsCols(&c).OU_JET_PG_COL;
         &json = &json | "{""colSeq"":" | &colRec.OU_SEQNBR_COL.Value | ",";
         &json = &json | """contentType"":""" | JSONEscape(&colRec.CONTENT_TYPE.Value) | """,";
         &json = &json | """textValue"":""" | JSONEscape(&colRec.DESCRLONG.Value) | """,";
         &json = &json | """imageUrl"":""" | JSONEscape(&colRec.IMAGE_URL.Value) | """,";
         &json = &json | """linkUrl"":""" | JSONEscape(&colRec.URL_ADDRESS.Value) | """,";
         &json = &json | """linkLabel"":""" | JSONEscape(&colRec.DESCR_LABEL.Value) | """}";
      End-For;
      &json = &json | "]}";
   End-For;
   &json = &json | "]}";



   /* --- Output shell: reuse your already-working RequireJS bootstrap verbatim --- */
   %Response.WriteLine("<!DOCTYPE html><html><head>");
   %Response.WriteLine("<link rel='stylesheet' href='" | &siteBase | "/css/libs/oj/14.1.1/redwood/oj-redwood-min.css'/>");
   %Response.WriteLine("<script src='" | &siteBase | "/js/libs/require/require-debug.js'></script>");
   %Response.WriteLine("<style>" | GetDesignerCss() | "</style>"); /* toolbar, slide-out panel, row badges */
   %Response.WriteLine("<script>");
   %Response.WriteLine("console.log(""JSON:" | &json | """);");
   %Response.WriteLine("var PGDSN_DATA = " | &json | ";");
   %Response.WriteLine("var PGDSN_CSRF = '" | &csrfToken | "';");
   %Response.WriteLine("var PGDSN_SAVE_URL = '" | GenerateSaveUrl() | "';"); /* helper builds the IScript_SaveDesign URL */
   %Response.WriteLine(GetRequireConfigJs(&siteBase)); /* your existing confirmed requirejs.config block, factored into a helper */
   %Response.WriteLine("require(['ojs/ojcore','knockout','ojs/ojknockout','ojs/ojbutton'], function(oj, ko) {");
   %Response.WriteLine(GetDesignerViewModelJs()); /* the Knockout viewModel + templates — see below */
   %Response.WriteLine("});");
   %Response.WriteLine("</script></head><body>");
   %Response.WriteLine(GetDesignerBodyHtml()); /* toolbar, canvas div, add-row panel markup */
   %Response.WriteLine("</body></html>");


End-Function;


Function IScript_SaveDesign()
   Local string &body, &designId, &csrfSubmitted, &csrfSession, &lastSeenDttm, &currentDttm, &descr;
   Local JsonObject &jo, &rowObj, &colObj;
   Local JsonArray &rowsArr, &colsArr;
   Local Record &hdrRec;
   Local integer &r, &c, &rowSeq, &colSeq;
   Local string &layout, &bgColor, &bgImage, &contentType, &textValue, &imageUrl, &linkUrl, &linkLabel;

   /* TODO
   If Not %OperatorId Or Not %AccessProfile.CheckAuthorization("OU_PAGEDESIGNER_ADMIN") Then
      %Response.SetStatusCode(403);
      %Response.SetContentType("application/json");
      %Response.WriteLine("{""status"":""error"",""message"":""Not authorized.""}");
      Return;
   End-If;
*/

   rem %Response.SetContentType("application/json");

   try

      &body = %Request.GetContentBody();
      Local JsonParser &jp = CreateJsonParser();

      If Not &jp.Parse(&body) Then
         /*Error*/

      End-If;

      rem %Response.Write(&jp.ToString());
      &jo = &jp.GetRootObject();

   catch Exception &e
      rem TODO %Response.SetStatusCode(400);

      %Response.WriteLine("{""status"":""error"",""message"":""Malformed JSON.""}");
      Return;
   end-try;

   &designId = &jo.GetString("designId");
   &csrfSubmitted = &jo.GetString("csrf");
   &lastSeenDttm = &jo.GetString("lastUpdDttm");
   &descr = &jo.GetString("descr");

   /* 
   &csrfSession = %Session.GetAttribute("PGDSN_CSRF_TOKEN");
   If &csrfSubmitted <> &csrfSession Or
         &csrfSubmitted = "" Then
      rem TODO %Response.SetStatusCode(403);
      %Response.WriteLine("{""status"":""error"",""message"":""Invalid session token, please reload the designer.""}");
      Return;
   End-If;
*/

   &hdrRec = CreateRecord(Record.OU_JET_PG_HDR);
   &hdrRec.OU_PAGE_ID.Value = &designId;

   Local boolean &isNewDesign;
   &isExistingDesign = &hdrRec.SelectByKey();

   If &isExistingDesign Then
      /* Existing design - enforce the concurrency check */
      &currentDttm = DateTimeToLocalizedString(&hdrRec.LASTUPDDTTM.Value, "YYYY-MM-DD-HH24.MI.SS.000000");
      If &currentDttm <> &lastSeenDttm Then
         rem %Response.WriteLine("{""status"":""conflict"",""message"":""This design was changed by someone else. Reload before saving.""}");
         rem Return;
      End-If;
   End-If;

   /* --- Replace children in a single transaction --- */
   SQLExec("DELETE FROM PS_OU_JET_PG_COL WHERE OU_PAGE_ID = :1", &designId);
   SQLExec("DELETE FROM PS_OU_JET_PG_ROW WHERE OU_PAGE_ID = :1", &designId);

   &rowsArr = &jo.GetJsonArray("rows");
   For &r = 1 To &rowsArr.Length()
      &rowObj = &rowsArr.GetJsonObject(&r);
      &rowSeq = &rowObj.GetNumber("rowSeq");
      &layout = &rowObj.GetString("layout");
      &bgColor = &rowObj.GetString("bgColor");
      &bgImage = &rowObj.GetString("bgImage");

      SQLExec("INSERT INTO PS_OU_JET_PG_ROW (OU_PAGE_ID, OU_SEQNBR_ROW, OU_ROW_LAYOUT, OU_BGCOLOR, OU_ROW_BG_IMG_URL) VALUES (:1,:2,:3,:4,:5)", &designId, &rowSeq, &layout, &bgColor, &bgImage);

      &colsArr = &rowObj.GetJsonArray("cols");
      For &c = 1 To &colsArr.Length()
         &colObj = &colsArr.GetJsonObject(&c);
         &colSeq = &colObj.GetNumber("colSeq");
         &contentType = &colObj.GetString("contentType");
         &textValue = &colObj.GetString("textValue");
         &imageUrl = &colObj.GetString("imageUrl");
         &linkUrl = &colObj.GetString("linkUrl");
         &linkLabel = &colObj.GetString("linkLabel");

         SQLExec("INSERT INTO PS_OU_JET_PG_COL (OU_PAGE_ID, OU_SEQNBR_ROW, OU_SEQNBR_COL, CONTENT_TYPE, DESCRLONG, IMAGE_URL, URL_ADDRESS, DESCR_LABEL) VALUES (:1,:2,:3,:4,:5,:6,:7,:8)", &designId, &rowSeq, &colSeq, &contentType, &textValue, &imageUrl, &linkUrl, &linkLabel);
      End-For;
   End-For;

   &hdrRec.DESCR.Value = &descr;
   &hdrRec.LASTUPDDTTM.Value = %Datetime;

   If &isExistingDesign Then
      &hdrRec.Update();
   Else
      &hdrRec.Insert();
   End-If;


   %Response.WriteLine("{""status"":""ok"",""lastUpdDttm"":""" | DateTimeToLocalizedString(&hdrRec.LASTUPDDTTM.Value, "YYYY-MM-DD-HH24.MI.SS.000000") | """}");

   SQLExec("COMMIT");

End-Function;


Function IScript_DesignList()
   Local Rowset &rsHdr;
   Local integer &i;
   Local string &h;

   /* TODO 
   If Not %OperatorId Or Not %AccessProfile.CheckAuthorization("OU_PAGEDESIGNER_ADMIN") Then
      %Response.WriteLine("Not authorized.");
      Return;
   End-If;
*/

   %Response.SetContentType("text/html");

   &rsHdr = CreateRowset(Record.OU_JET_PG_HDR);
   &rsHdr.Fill("ORDER BY DESCR");

   &h = &h | "<!DOCTYPE html><html><head><title>Page Designs</title>";
   &h = &h | "<style>";
   &h = &h | "body{font-family:Arial,sans-serif;max-width:700px;margin:40px auto;color:#222;}";
   &h = &h | "h1{font-size:24px;} table{width:100%;border-collapse:collapse;margin-bottom:30px;}";
   &h = &h | "td,th{padding:8px 10px;border-bottom:1px solid #eee;text-align:left;}";
   &h = &h | "a{color:#0078d7;text-decoration:none;} a:hover{text-decoration:underline;}";
   &h = &h | ".newform{border:1px solid #ddd;border-radius:6px;padding:20px;background:#fafafa;}";
   &h = &h | "input[type=text]{padding:8px;width:260px;border:1px solid #ccc;border-radius:4px;}";
   &h = &h | "button{padding:8px 18px;border:none;background:#1a1a1a;color:#fff;border-radius:4px;cursor:pointer;}";
   &h = &h | "</style></head><body>";

   &h = &h | "<h1>Page Designs</h1>";
   &h = &h | "<table><tr><th>Design</th><th>ID</th><th>Status</th><th></th></tr>";

   For &i = 1 To &rsHdr.ActiveRowCount
      Local Record &r = &rsHdr(&i).OU_JET_PG_HDR;
      &h = &h | "<tr><td>" | &r.DESCR.Value | "</td><td>" | &r.OU_PAGE_ID.Value | "</td>";
      rem TODO &h = &h | "<td>" | &r.PGDSN_STATUS.Value | "</td>";
      &h = &h | "<td><a href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_PageDesigner?design=" | &r.OU_PAGE_ID.Value | "'>Edit</a> &nbsp; ";
      &h = &h | "<a href='WEBLIB_OU_LP.ISCRIPT2.FieldFormula.IScript_JETLandingPage?design=" | &r.OU_PAGE_ID.Value | "' target='_blank'>View</a></td></tr>";
   End-For;

   If &rsHdr.ActiveRowCount = 0 Then
      &h = &h | "<tr><td colspan='4'><em>No designs yet.</em></td></tr>";
   End-If;
   &h = &h | "</table>";

   &h = &h | "<div class='newform'>";
   &h = &h | "<h3>Create New Design</h3>";
   &h = &h | "<form method='GET' action='IScript_PageDesigner'>";
   &h = &h | "<input type='text' name='design' placeholder='e.g. OPEN_ENROLLMENT1' maxlength='30' pattern='[A-Za-z0-9_]+' required title='Letters, numbers, underscore only'/>";
   &h = &h | " <button type='submit'>Create / Open</button>";
   &h = &h | "</form></div>";

   &h = &h | "</body></html>";
   %Response.WriteLine(&h);
End-Function;

Function iScript_GetUserVars()
   Local string &MFA_User_id, &company;

   /*start comment out following sqlexec. to use common OU_ALL_USERIDS record
   SQLExec("select userid from SYSADM.ps_ou_ad_interface where emplid = :1", %UserId, &MFA_User_id);

   If None(&MFA_User_id) Then
      SQLExec("select username from Person.Name_IDs@OUNOR_LK where emplid = :1", %UserId, &MFA_User_id);
   End-If;
   end */

   /*Get count from ps_ou_all_userids table greater than 1 if exists get primary campus from job indicator cmp6805*/
   SQLExec("select count(emplid) from SYSADM.ps_ou_all_userids where emplid = :1 group by emplid having count(emplid) > 1", %UserId, &cntEmplid);
   If &cntEmplid > 1 Then
      /*start mod  mmalone no devices found when user has Dual campus credentials*/
      If IsNumber(%UserId) Then
         SQLExec("select company from SYSADM.ps_employees where emplid = :1 and job_indicator = 'P'", %UserId, &company);
      End-If;

      SQLExec("select userid from SYSADM.PS_OU_ALL_USERIDS where emplid = :1 and company = :2", %UserId, &company, &MFA_User_id);
      If None(&MFA_User_id) Then
         &MFA_User_id = %UserId;
      End-If;
      /*End mod cmp6701*/
   Else
      SQLExec("select userid from SYSADM.PS_OU_ALL_USERIDS where emplid = :1 ", %UserId, &MFA_User_id);
   End-If;

   rem &MFA_User_id = &MFA_User_id | "-" | %SignonUserId; /*testing what is coming through*/
   %Response.SetHeader("X-GH-MFA-ID", &MFA_User_id);

   Local string &transferURL;
   &transferURL = %Request.QueryString; /*OU MOD CMP6467*/
   rem &transferURL = %Request.GetParameter("returnUrl");
   rem &transferURL = %Request.GetHeader("Referer");

   /* This should be the landing page upon login */
   If None(&transferURL) Then
      &transferURL = GenerateHomepagePortalURL(%Portal, %Node, "DEFAULT");
   End-If;

   /* It’s important to write the response out to ensure the header gets written out. 
     Other redirect methods such as ViewURL() or %response.RedirectURL() don’t work. */
   Local string &resphtml = "<html><body onload='document.location=""" | &transferURL | """;'></body></html>";
   %Response.Write(&resphtml);

End-Function;

Function IScript_SF()
   &TIME = %Time;
   &Time_VAl = Substring(&TIME, 1, 5);

   SQLExec("SELECT A.PIN_NBR, A.EMPLID from PS_PIN@SA_HSC_LK A, PS_OU_AD_INTERFACE B WHERE A.EMPLID = B.EMPLID_OLD AND B.EMPLID = :1", %EmployeeId, &pin_nbr, &EMPLID);
   rem SQLExec("SELECT A.PIN_NBR, A.EMPLID,C.COMPANY from PS_PIN@SA_HSC_LK A, PS_OU_AD_INTERFACE B,PS_JOB C WHERE A.EMPLID = B.EMPLID_OLD AND B.EMPLID = :1 AND b.EMPlID = C.EMPLID    AND C.EFFDT = (  SELECT MAX(C.EffDt)   FROM PS_Job C1  WHERE C1.EmplID = C.EmplID    AND C1.EMPL_RCD = C.EMPL_RCD    AND C1.EffDt <= sysdate)    AND C.EffSeq = (  SELECT MAX(D.EffSeq)   FROM PS_Job D  WHERE D.EmplID = C.EmplID    AND D.EMPL_RCD = C.EMPL_RCD    AND D.EffDt = C.EffDt) AND C.HR_STATUS = 'A'", %EmployeeId, &pin_nbr, &EMPLID, &COMPANY);
   SQLExec("SELECT C.COMPANY from PS_JOB C WHERE C.EMPLID = :1 AND C.EFFDT = (  SELECT MAX(C.EffDt)   FROM PS_Job C1  WHERE C1.EmplID = C.EmplID    AND C1.EMPL_RCD = C.EMPL_RCD    AND C1.EffDt <= sysdate)    AND C.EffSeq = (  SELECT MAX(D.EffSeq)   FROM PS_Job D  WHERE D.EmplID = C.EmplID    AND D.EMPL_RCD = C.EMPL_RCD    AND D.EffDt = C.EffDt) AND C.HR_STATUS = 'A'", %EmployeeId, &COMPANY);

   /* PS_PIN */
   &REQUEST = %Request;
   &RESPONSE = %Response;

   rem &db = Substring(%DbName, 1, 2);

   rem last 3 chars;
   &start_posn = (Len(%DbName) - 2);
   &db = Substring(%DbName, &start_posn, 3);


   Evaluate &db
      /*When = "HT"
   When = "HC"*/
   When = "PRD"
   When = "DEV"
   When = "TST"
      Evaluate &COMPANY
      When "NRM"
         rem &GetHTML = GetHTMLText(HTML.OU_SS_TSN_PROD, &EMPLID, &pin_nbr);
         &GetHTML = GetHTMLText(HTML.OU_SS_NRM_PROD);
         Break;
      When = "HSC"
         &GetHTML = GetHTMLText(HTML.OU_SS_TS_PROD, &EMPLID, &pin_nbr);
         Break;
      End-Evaluate;
      Break;
   When-Other
      &GetHTML = GetHTMLText(HTML.OU_SS_TS_TEST, &EMPLID, &pin_nbr);
      Break;
   End-Evaluate;

   If &Time_VAl >= "16.45" And
         &Time_VAl <= "20.00" Then
      Error MsgGet(30002, 20, "You can not make a payment between ", "4:45pm", "8:00pm");
   Else
      &RESPONSE.Write(&GetHTML);
   End-If;
End-Function;


