REM ********************************************;
REM Portal Administration component code        ;
REM ********************************************;

REM ***************************************************************************************;
REM Function:		CreateFolderListHREF								  ;
REM Purpose:		Creates hyperlinks for the AdminSiblingNav iScript                    ;
REM Inputs:		Folder list page URL, Portal Name, fldr id, link name                 ;
REM Output:		Hyperlink html                                                        ;
REM ***************************************************************************************;
Function CreateFolderListHREF(&FolderListPage As string, &PortalName As string, &FolderObjName As string, &LinkName As string) Returns string

   &URL = &FolderListPage | "?PORTAL_NAME=" | &PortalName;
   &URL = &URL | "&PORTALPARAM_FNAME=" | &FolderObjName;
   &Link = GetHTMLText(HTML.PORTAL_ADMIN_BREADCRUMB_LINK, &URL, &LinkName);
   Return &Link;

End-Function;

REM ********************************************;
REM Portal Administration Breadcrumb component  ;
REM ********************************************;

REM ***************************************************************************************;
REM Function: 	CreateGenericHREF                                                      ;
REM Purpose:		Builds the hyperlink for traversing anywhere	            		  ;
REM Inputs:		Page URL and Link Name							  ;
REM Output:   	The actual hyperlink                                                   ;
REM ***************************************************************************************;

Function CreateGenericHREF(&PageURL As string, &LinkName As string) Returns string

   &Link = GetHTMLText(HTML.PORTAL_ADMIN_BREADCRUMB_LINK2, &PageURL, &LinkName);
   &Link = &Link | "&nbsp>";
   Return &Link;

End-Function;


REM ***************************************************************************************;
REM Function: 	CreateBreadCrumbHREF                                                   ;
REM Purpose:		Builds the hyperlink for traversing the folder list			  ;
REM Inputs:		Folder List page, Portal Name, Folder ID and Folder Name		  ;
REM Output:   	The actual hyperlink                                                   ;
REM ***************************************************************************************;
Function CreateBreadCrumbHREF(&FldrListPage As string, &PortalName As string, &FolderObjName As string, &FolderName As string, &strSaveWarning As string) Returns string

   Local string &strURLHTML = &FldrListPage | "?PORTAL_NAME=" | &PortalName | "&PORTALPARAM_FNAME=" | &FolderObjName;

   If &strSaveWarning = "Y" Then
      &strURLHTML = "javascript:saveWarning('TargetContent',null,'_self','" | &strURLHTML | "');";
   End-If;

   Return GetHTMLText(HTML.PORTAL_ADMIN_BREADCRUMB_LINK2, &strURLHTML, EscapeHTML(&FolderName)) | "<span> > </span>";

End-Function;

REM ***************************************************************************************;
REM Function: 	GetBreadcrumbsFromPath							  ;
REM Purpose:		Builds the breadcrumb html based on the path that was passed it	  ;
REM Inputs:          Hierarchical path generated by the Portal API				  ;
REM Output:		None										  ;
REM ***************************************************************************************;
Function GetBreadcrumbsFromPath(&FldrListPage As string, &Path As string, &PortalName As string) Returns string

   &FolderObjName = EscapeHTML(%Request.GetParameter("PORTALPARAM_FNAME"));

   REM Don't hyperlink the Portal Name when entering the Admin Utility;
   If &Path = "" And
         &FolderObjName = "" Then
      &BCHtml = "<span>" | MsgGetText(95, 5043, "Root") | "</span>";
   Else
      Local string &strSaveWarning = GetUserOption("PPTL", "SWARN");
      &StartPos = 1;
      &LeftParenPos = Find("{", &Path, &StartPos);

      REM Tear down the path to extract the Folder Name and Folder Object Name;
      REM Example: "Root{PORTAL_ROOT_OBJECT}.SA{STUDENT_ADMIN}.Student Records{STUDENT_RECS}";
      While &LeftParenPos <> 0
         &FldrName = Substring(&Path, &StartPos, &LeftParenPos - &StartPos);
         &RightParenPos = Find("}", &Path, &StartPos);
         &FldrObjName = Substring(&Path, &LeftParenPos + 1, &RightParenPos - (&LeftParenPos + 1));
         &StartPos = Find("}.", &Path, &StartPos) + 2;
         &LeftParenPos = Find("{", &Path, &StartPos);

         REM substitute the root folder name with the actual portal name;
         If &FldrName = "Root" Then
            &FldrName = MsgGetText(95, 5043, "Root");
         End-If;

         REM If were in the folderlist and no more folder names exist, don't hyperlink;
         REM the last folder name in the path;
         If &LeftParenPos = 0 And
               &FolderObjName <> "" Then
            &BCHtml = &BCHtml | "<span>" | EscapeHTML(&FldrName) | "</span>";
         Else
            &BCHtml = &BCHtml | CreateBreadCrumbHREF(&FldrListPage, &PortalName, &FldrObjName, &FldrName, &strSaveWarning);
         End-If;

      End-While;
   End-If;

   &BCHtml = GetHTMLText(HTML.HTML_BREADCRUMBS, &BCHtml);
   Return &BCHtml;

End-Function;

REM This variable is used by the AdminBreadcrumbs and AdminSiblingNav;
REM components when the user prompts for a security permission;
Global string &gstrParentObjName;
Global string &gstrPortalObjName;

REM ***************************************************************************************;
REM Function: 	GetFolderPath									  ;
REM Purpose:		Sets up the folder path depending on what action the user is performing;
REM Inputs:          None										   ;
REM Output:		Folder path									   ;
REM ***************************************************************************************;

Local ApiObject &FolderObj;

Function GetFolderPath(&Portal As ApiObject) Returns string

   REM Determine the parent object folder based on the component name and mode;

   REM Structure and Content;
   If %Component = Component.PORTAL_OBJ_LIST Then
      &FolderObjName = EscapeHTML(%Request.GetParameter("PORTALPARAM_FNAME"));
   Else
      If %Mode = "A" Then
         &FolderObjName = EscapeHTML(%Request.GetParameter("PORTALPARAM_PNAME"));
      Else
         If %Component = Component.PORTAL_CREF_ADM Or
               %Component = Component.PORTAL_CREF_LNK Then
            &CRefObjName = EscapeHTML(%Request.GetParameter("PORTALPARAM_CNAME"));
            If All(&CRefObjName) Then
               &CRef = &Portal.FindCRefByName(&CRefObjName);
               If All(&CRef) Then
                  &FolderObjName = &CRef.ParentName;
               End-If;
            End-If;
         Else
            If %Component = Component.PORTAL_FLDR_ADM Then
               &FolderObjName = EscapeHTML(%Request.GetParameter("PORTALPARAM_FNAME"));
               If None(&FolderObjName) Then
                  If All(&gstrPortalObjName) Then
                     &FolderObjName = &gstrPortalObjName;
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;
   End-If;

   REM A global var is set when doing a security lookup on a cref or folder;
   If None(&FolderObjName) Then
      If All(&gstrParentObjName) Then
         &FolderObjName = &gstrParentObjName;
      End-If;
   End-If;

   If All(&FolderObjName) Then
      &FolderObj = &Portal.FindFolderByName(&FolderObjName);
   End-If;

   REM append on the current folder name and id to the path;
   If All(&FolderObj) Then
      &UnparsedPath = &FolderObj.Path;

      REM The path method will return "" if were at ROOT;
      If &UnparsedPath = "" Then
         &Path = "Root{PORTAL_ROOT_OBJECT}.";
      Else
         &Path = &UnparsedPath | "." | &FolderObj.Label | "{" | &FolderObj.Name | "}.";
      End-If;
   End-If;

   Return &Path;

End-Function;

Local ApiObject &Portal, &Session, &TgtCref;

REM ***************************************************************************************;
REM Function: 	PortalAdminBreadcrumbs      						  ;
REM Purpose:		                                                                       ;
REM Inputs:          None										  ;
REM Output:		                                                                       ;
REM ***************************************************************************************;
Function PortalAdminBreadcrumbs() Returns string

   &Portal = PortalOpen();

   &FldrListPageURL = GenerateComponentContentURL(%Portal, %Node, MenuName.PORTAL_ADMIN, "GBL", Component.PORTAL_OBJ_LIST, "", "");

   If %Component = Component.PORTAL_OBJ_LIST Then
      &gstrParentObjName = "";
   End-If;

   &SelectedPath = GetFolderPath(&Portal);
   &BreadCrumbHTML = GetBreadcrumbsFromPath(&FldrListPageURL, &SelectedPath, &Portal.Name);

   &Portal.Close();
   Return &BreadCrumbHTML;

End-Function;



