REM ***************************************************************************************;
REM Function:		CreateFolderEditHREF								  ;
REM Purpose:		Creates hyperlinks for the AdminSiblingNav iScript                    ;
REM Inputs:		Folder edit page URL, Portal Name, ParentID, fldr id,                 ;
REM Output:		Hyperlink html                                                        ;
REM ***************************************************************************************;
Function CreateFolderEditHREF(&FolderEditPage As string, &PortalName As string, &ParentObjName As string, &FolderObjName As string, &LinkName As string) Returns string

   &URL = &FolderEditPage | "?Action=C" | "&PORTAL_NAME=" | &PortalName;
   &URL = &URL | "&PORTALPARAM_PNAME=" | &ParentObjName | "&PORTALPARAM_FNAME=" | &FolderObjName;
   &Link = GetHTMLText(HTML.PORTAL_ADMIN_BREADCRUMB_LINK, &URL, &LinkName);
   Return &Link;

End-Function;

REM ***************************************************************************************;
REM Function:		CreateCRefEditHREF								  ;
REM Purpose:		Creates hyperlinks for the AdminSiblingNav iScript                    ;
REM Inputs:		Cref edit page URL, Portal Name, ParentID, cref id,                   ;
REM                  fully qualified url of the cref to edit                               ;
REM Output:		Hyperlink html                                                        ;
REM ***************************************************************************************;
Function CreateCRefEditHREF(&CRefEditPage As string, &PortalName As string, &ParentObjName As string, &CRefObjName As string, &EditURL As string, &LinkName As string) Returns string

   &URL = &CRefEditPage | "?Action=C" | "&PORTAL_NAME=" | &PortalName;
   &URL = &URL | "&PORTALPARAM_PNAME=" | &ParentObjName | "&PORTALPARAM_CNAME=" | &CRefObjName;
   &URL = &URL | "&PORTALPARAM_QURL=" | EncodeURLForQueryString(&EditURL);
   &Link = GetHTMLText(HTML.PORTAL_ADMIN_BREADCRUMB_LINK, EncodeURL(&URL), &LinkName);

   Return &Link;

End-Function;

REM ***************************************************************************************;
REM Function:		CreateCPEditHREF								  ;
REM Purpose:		Creates hyperlinks for the AdminSiblingNav iScript                    ;
REM Inputs:		ContentProvider edit page URL, Portal Name, Content Provider name     ;
REM Output:		Hyperlink html                                                        ;
REM ***************************************************************************************;
Function CreateCPEditHREF(&CPEditPage As string, &PortalName As string, &CPName As string, &LinkName As string) Returns string

   &URL = &CPEditPage | "?PORTAL_NAME=" | &PortalName | "&PORTALPARAM_CP_NAME=" | EncodeURLForQueryString(&CPName);
   &Link = GetHTMLText(HTML.PORTAL_ADMIN_BREADCRUMB_LINK, &URL, &LinkName);

   Return &Link;

End-Function;

Local ApiObject &CP, &CPColl;

REM ***************************************************************************************;
REM Function:		AdminSiblingNav								  ;
REM Purpose:		Main entry point into the Portal Administration sibling nav component ;
REM Inputs:		None                                                                  ;
REM Output:		None                                                                  ;
REM Design Notes:                                                                          ;
REM ***************************************************************************************;
Function IScript_AdminSiblingNav()

   &FolderEditPage = "c/PORTAL_ADMIN.PORTAL_FLDR_ADM.GBL";
   &FolderLinkEditPage = "c/PORTAL_ADMIN.PORTAL_FLDR_LNK.GBL";
   &FolderListPage = "c/PORTAL_ADMIN.PORTAL_OBJ_LIST.GBL";
   &CRefEditPage = "c/PORTAL_ADMIN.PORTAL_CREF_ADM.GBL";
   &CRefLinkEditPage = "c/PORTAL_ADMIN.PORTAL_CREF_LNK.GBL";

   &Portal = PortalOpen();

   REM find out what the target cref is;
   &TgtCref = &Portal.FindCrefByURL(%Request.GetHeader("PortalContentURL"));
   &TargetCRefURL = &TgtCref.URL;

   REM Make sure the global variable gstrParentObjName is blank when;
   REM the target page is the Structure and Content page;
   If &TargetCRefURL = &FolderListPage Then
      &gstrParentObjName = "";
   End-If;

   REM Find the parent object;
   &FolderObjName = EscapeHTML(%Request.GetParameter("PORTALPARAM_FNAME"));
   If &FolderObjName <> "" Then
      &FolderListObj = &Portal.FindFolderByName(&FolderObjName);

      If &FolderListObj = Null Then
         REM Fatal error if this occurs;
         REM This could occur when a favorite is pointing to the folder's children and;
         REM then the folder is deleted.
         &Portal.Close();
         Error MsgGet(95, 5020, "Error getting folder definition %1. The folder definiton wasn't found in the portal registry.", &FolderListName);
      End-If;

      If &FolderListObj.Name <> "PORTAL_ROOT_OBJECT" Then
         If &FolderListObj.Authorized = True Then
            &ParentObjName = &FolderListObj.ParentName;
         End-If;
      Else
         &ParentObjName = &FolderListObj.Name;
      End-If;
   End-If;

   If &ParentObjName = "" Then
      &ParentObjName = EscapeHTML(%Request.GetParameter("PORTALPARAM_PNAME"));
      If &ParentObjName = "" Then
         If &gstrParentObjName <> "" Then
            REM The user looked for a permission class via search page;
            &ParentObjName = &gstrParentObjName;
         Else
            &FolderListObj = &Portal.RootFolder;
            &ParentObjName = &FolderListObj.Name
         End-If;
      End-If;
   End-If;

   &ParentObj = &Portal.FindFolderByName(&ParentObjName);

   REM Setup the sidebar nav links based on the target content page;
   Evaluate &TargetCRefURL
   When &FolderLinkEditPage
   When &FolderEditPage
      &TgtFldrObjName = %Request.GetParameter("PORTALPARAM_FNAME");
      &TableHeaderTxt = "<h5>" | MsgGetText(95, 52, "Message not found.") | "</h5>";
      &TD = GetHTMLText(HTML.HTML_TABLEDATA, &TableHeaderTxt);
      &FolderColl = &ParentObj.Folders;
      &Folder = &FolderColl.First();

      While All(&Folder)
         If &Folder.Name = &TgtFldrObjName Then
            &Link = "";
         Else
            rem susan;
            &Link = CreateFolderEditHREF(&TgtCref.RelativeURL, &Portal.Name, &ParentObjName, &Folder.Name, &Folder.Label);
         End-If;
         &TD = &TD | GetHTMLText(HTML.HTML_TABLEDATA, &Link);
         &Folder = &FolderColl.Next();
      End-While;
      Break;

   When &FolderListPage
      If &FolderListObj.Name = "PORTAL_ROOT_OBJECT" Then
         &TableHeaderTxt = "<h5>" | MsgGetText(95, 53, "Message not found.") | "</h5>";
         &TD = GetHTMLText(HTML.HTML_TABLEDATA, &TableHeaderTxt);
      Else
         &TableHeaderTxt = "<h5>" | MsgGetText(95, 54, "Message not found.", &FolderListObj.Label) | "</h5>";
         &TD = GetHTMLText(HTML.HTML_TABLEDATA, &TableHeaderTxt);
      End-If;
      &FolderColl = &ParentObj.Folders;
      &Folder = &FolderColl.First();

      While All(&Folder)
         REM don't hyperlink the folder were currently navigating;
         If &Folder.Name = &FolderListObj.Name Then
            &Link = "";
         Else
            rem susan;
            &Link = CreateFolderListHREF(&TgtCref.RelativeURL, &Portal.Name, &Folder.Name, &Folder.Label);
         End-If;
         &TD = &TD | GetHTMLText(HTML.HTML_TABLEDATA, &Link);
         &Folder = &FolderColl.Next();
      End-While;
      &gstrParentObjName = "";
      Break;

   When &CRefEditPage
   When &CRefLinkEditPage
      &TgtCRefObjName = %Request.GetParameter("PORTALPARAM_CNAME");
      &TableHeaderTxt = "<h5>" | MsgGetText(95, 55, "Message not found.") | "</h5>";
      &TD = GetHTMLText(HTML.HTML_TABLEDATA, &TableHeaderTxt);

      REM In case the object was moved, used the parent of the target cref;
      If All(&TgtCRefObjName) Then
         &CRef = &Portal.FindCRefByName(&TgtCRefObjName);
         If &CRef <> Null Then
            If &CRef.Authorized = True Then
               &ParentObj = &Portal.FindFolderByName(&CRef.ParentName);
            End-If;
         End-If
      End-If;

      If &ParentObj <> Null Then
         &CRefColl = &ParentObj.ContentRefs;
         If &CRefColl.Count > 0 Then
            &CRef = &CRefColl.First();

            While All(&CRef)
               If &CRef.Name = &TgtCRefObjName Then
                  &Link = "";
               Else
                  rem susan;
                  &Link = CreateCRefEditHREF(&TgtCref.relativeurl, &PortalName, &ParentObjName, &CRef.Name, &CRef.QualifiedURL, &CRef.Label);
               End-If;
               &TD = &TD | GetHTMLText(HTML.HTML_TABLEDATA, &Link);
               &CRef = &CRefColl.Next();
            End-While;
         End-If;
      End-If;

   End-Evaluate;

   &Portal.Close();

   %Response.Write(GetHTMLText(HTML.HTML_TBLSKEL, &TD, %Response.GetStyleSheetURL(StyleSheet.PSSTYLEDEF)));
End-Function;

