REM ***************************************************************************************;
REM Function: GetPortalURI                                                                      ;
REM Purpose:					                                                  ;
REM Inputs:									                      ;
REM Output:   	                                                                       ;
REM ***************************************************************************************;
Function GetPortalURI(&CProviderName) Returns string
   &TempURI = "";

   &thisPortal = %Session.GetPortalRegistry();
   &portals = &thisPortal.Portals;

   /*   &thePortal = &portals.itembyname(%Portal); */
   &thePortal = &thisPortal.FindPortalByName(%Portal);
   If (&thePortal.HostNodeName = "LOCAL_NODE") Then
      &nodeName = %LocalNode;
   Else
      &nodeName = &thePortal.HostNodeName;
   End-If;
   &nodes = %Session.getNodes();
   &node = &nodes.itembyname(&nodeName);
   &TempURI = &node.PortalURI | %Portal | "/" | &nodeName | "/";

   Return &TempURI;

End-Function;

