Global string &g_strDefaultTab;

REM ***************************************************************************************;
REM Function: GetPortalHomepageURL                                                         ;
REM Purpose:  returns string to be used as the URL of the portal homepage                  ;
REM Inputs:   None                                                                         ;
REM Output:   homepage url                                                                 ;
REM ***************************************************************************************;

Function GetPortalHomepageURL() Returns string

   &g_strDefaultTab = GetDefaultTabName();
   /* In C++, ReturnToPortal param is Encoded */
   &ReturnToPortal = Unencode(%Request.GetParameter("ReturnToPortal"));
   If &ReturnToPortal <> Null And
         &ReturnToPortal <> "" Then
      Return &ReturnToPortal;
   Else
      Return GetPortalURI("PortalServlet") | "h/" | GetHomepageTabQueryString(&g_strDefaultTab);
   End-If;
End-Function;


REM ***************************************************************************************;
REM Function: GetHomepageTabURL                                                            ;
REM Purpose:  returns string to be used as the URL of the portal homepage                  ;
REM Inputs:   Tab Name                                                                     ;
REM Output:   homepage url                                                                 ;
REM ***************************************************************************************;

Function GetHomepageTabURL(&TabName As string) Returns string

   If All(&TabName) Then
      &HPTabURL = GetPortalURI("PortalServlet") | "h/" | GetHomepageTabQueryString(&TabName);
   Else
      &HPTabURL = GetPortalURI("PortalServlet") | "h/" | GetHomepageTabQueryString(&g_strDefaultTab);
   End-If;

   Return &HPTabURL;

End-Function;

Function convertURLforPortal(&URL As string) Returns string

   &LocalNode = %Session.GetLocalNode();
   &PortalURL = &LocalNode.PortalURI;
   &PortalURL = &PortalURL | %Portal | "/" | %Node | "/";
   &PortalURL = &PortalURL | "?url=" | EncodeURLForQueryString(&URL);
   Return &PortalURL;

End-Function;

REM *******************************************************************************;
REM  Build the list of links to display under the Categories menu drop-down in     ;
REM  the header.  Link to the Navigation page.                                     ;
REM *******************************************************************************;
Function GetCategories() Returns string

   &Portal = PortalOpen();

   &Root = &Portal.RootFolder;
   &CategoryColl = &Root.Folders;
   &Category = &CategoryColl.First();
   &CategoryHTML = "";
   While All(&Category)
      If (checkVisible(&Category) = True) Then

         &Link = GenerateScriptRelativeURL(%Portal, %Node, Record.WEBLIB_PORTAL, Field.PORTAL_NAV, "FieldFormula", "IScript_DrillDown") | "?FolderID=" | &Category.Name | "&Level=1&PortalRegistryName=" | &Portal.Name;
         &CategoryHTML = &CategoryHTML | GetHTMLText(HTML.PORTAL_CATEGORY, &Link, &Category.Label);
      End-If;
      &Category = &CategoryColl.Next();
   End-While;

   &CREFColl = &Root.ContentRefs;
   &CRef = &CREFColl.First();

   While All(&CRef)
      REM Build the Content Reference links.  The value needs to be a URL;
      If (checkVisible(&CRef) = True) Then
         If &CRef.UsageType = "TARG" Then
            &URL = &CRef.QualifiedURL;
            &CategoryHTML = &CategoryHTML | GetHTMLText(HTML.PORTAL_CATEGORY, &URL, &CRef.Label);
         End-If;
      End-If;
      &CRef = &CREFColl.Next();
   End-While;

   &Portal.Close();
   Return &CategoryHTML;

End-Function;

