REM ***************************************************************************************;
REM Function: CreateBrandingObject                                                         ;
REM Purpose:	Get Branding class name from PSOPTIONS and create an Object                  ;
REM Inputs:												  ;
REM Output:												  ;
REM ***************************************************************************************;
Function CreateBrandingObject() Returns object;
   SQLExec("SELECT PACKAGEROOT, APPCLASSID FROM PSOPTIONS", &AppPkg, &AppClass);
   If All(&AppPkg) And
         All(&AppClass) Then
      &Obj = CreateObject(&AppPkg | ":" | &AppClass);
   Else
      /*Supply hardcoded default values*/
      &Obj = CreateObject("PT_BRANDING:BrandingBase");
   End-If;
   Return &Obj;
End-Function;

