REM ***************************************************************************************;
REM FUNCTION TO SET PERSONALIZATION OPTION: WARNTRANS                                      ;
REM Disable Pagelet Transfer Confirmation (Accessibility Mode) in User's Personalization   ;
REM Return "True" to indicate success                                                        ;
REM ***************************************************************************************;
Function IScript_PgltWarnOff()
   Local boolean &bSet = SetUserOption("PPTL", "WARNTRANS", "N");
   If (&bSet) Then
