REM ***************************************************************************************;
REM Function:  CreateUserTab()                                                             ;
REM Purpose:  Builds a user tab based on the system tab                                    ;
REM Inputs:  None                                                                          ;
REM Output:  None                                                                          ;
REM Design Notes:                                                                          ;
REM ***************************************************************************************;
Function CreateUserTab(&Portal As ApiObject, &UserTabColl As ApiObject, &Homepage As ApiObject)

   &SysTabColl = &Portal.TabDefinitions;
   &SysTab = &SysTabColl.ItemByName(&TabName);

   &UserTab = &UserTabColl.InsertItem(&SysTab.Name);
   If &UserTab = Null Then
      PortalAPIError(&Portal);
   End-If;

   &UserTab.Label = &SysTab.Label;
   &UserTab.SequenceNumber = &SysTab.SequenceNumber;
   &UserTab.ColumnLayout = &SysTab.ColumnLayout;

   &SelPgltColl = &UserTab.SelectedPagelets;
   &AssignedPgltColl = &SysTab.AssignedPagelets;
   &AssignedPglt = &AssignedPgltColl.First();

   While All(&AssignedPglt)
      REM insert only if LayoutBehavior is not Optional. T-SKANAP-Z98JM;
      If &AssignedPglt.LayoutBehavior <> "4OPT" Then
         &SelPglt = &SelPgltColl.InsertItem(&AssignedPglt.PageletName, &AssignedPglt.Column, &AssignedPglt.Row);
         If &SelPglt = Null Then
            PortalAPIError(&Portal);
         End-If;
         &SelPglt.IsMinimized = False;
      End-If;
      &AssignedPglt = &AssignedPgltColl.Next();
   End-While;

   If Not &Homepage.Save() Then
      PortalAPIError(&Portal);
   End-If;

End-Function;

Local number &CompStartPos, &CompLen, &StartPos, &Len;

REM ***************************************************************************************;
REM Function:  IScript_HPCompRemove()         ;
REM Purpose:  Removes a home page component from a users home page                   ;
REM Inputs:  None            ;
REM Output:  None            ;
REM Design Notes:             ;
REM ***************************************************************************************;

Function IScript_HPCompRemove()

   &Portal = PortalOpen();

   REM Update the user homepage tab template defintion;
   &TabName = EscapeHTML(%Request.GetParameter("tab"));

   &Homepage = &Portal.Homepage;
   &UserTabColl = &Homepage.UserTabs;
   &UserTab = &UserTabColl.ItemByName(&TabName);

   If &UserTab = Null Then
      CreateUserTab(&Portal As ApiObject, &UserTabColl As ApiObject, &Homepage As ApiObject);
   End-If;

   REM Get the pagelet name;
   &PgltName = EscapeHTML(%Request.GetParameter("pageletname"));

   REM Delete the pagelet from the user's tab definition;
   &SelPgltColl = &UserTab.SelectedPagelets;
   If Not &SelPgltColl.DeleteItem(&PgltName) Then
      PortalAPIError(&Portal);
   End-If;

   If Not &Homepage.Save() Then
      PortalAPIError(&Portal);
   End-If;

   &Portal.Close();

   /* New in PT8.51: Check for existance of pgltHPReload session cookie.
   If it exists, remove this cookie from the list held by pgltHPReload cookie */
   Local string &c = %Request.GetCookieValue("pgltHPReload");
   If (All(&c)) Then
      &index = Find(&TabName | "." | &PgltName, &c);
      If (&index > 0) Then
         /* Needs to take this out from the list */
         &c = Replace(&c, &index, Len(&TabName | "." | &PgltName | "|"), "");
         &cookieNew = %Response.CreateCookie("pgltHPReload");
         &cookieNew.Value = &c;
         &authTokenDomain = (%Request.AuthTokenDomain);

         If (All(&authTokenDomain) And
               &authTokenDomain <> "") Then
            &cookieNew.Domain = %Request.AuthTokenDomain;
         End-If;
         &cookieNew.Path = "/";
      End-If;
   End-If;

   Local string &dashboardName = EscapeHTML(%Request.GetParameter("pslnkid"));
   Local string &dashboardParam;
   If All(&dashboardName) Then
      &dashboardParam = "&pslnkid=" | &dashboardName;
   End-If;

   Local string &curHPPortalURL = GenerateHomepagePortalURL(%Portal, %Node, &TabName);
   &urlNodeNameArr = Split(&curHPPortalURL, "/");
   &urlNodeName = &urlNodeNameArr [7];
   &LocalNodeName = %Session.getLocalNode().name;

   &NodeColl = %Session.GetNodes();
   &portalNode = &NodeColl.itembyname(&urlNodeName);

   Local string &sPtalId = "";
   &sPtalId = %Request.GetParameter("PTAL_ID");
   Local string &sPtalTab = "";
   &sPtalTab = %Request.GetParameter("PTAL_TAB");
   /*To identify that the request for the dashboard is from a WC dashboard and not just a plain dashboard*/
   If All(&sPtalTab) And
         All(&sPtalId) Then
      &dashboardParam = &dashboardParam | "&wcdashbd=true";
   End-If;

   If ((&portalNode <> Null And
         Not (&portalNode.IsLocal Or
            &portalNode.name = "LOCAL_NODE")) And
         (&urlNodeName <> &LocalNodeName)) Then

      Local string &qs = %Request.QueryString;
      If Find("PortalHostNode=", &qs) > 0 And
            Find("PortalRegistryName=", &qs) > 0 Then

         &strDummyHPTabName = "REMOTEUNIFIEDDASHBOARD";
         Local string &strUniNavRedirectURL = GenerateHomepagePortalURL(%Portal, %Node, &strDummyHPTabName);
         &curHPPortalURL = Substitute(&curHPPortalURL, &urlNodeName, %Node);
         &strUniNavRedirectURL = &strUniNavRedirectURL | "&unifieddashboard=y&remotedburl=" | &curHPPortalURL | &dashboardParam;
         %Response.RedirectURL(&strUniNavRedirectURL);
      Else /* Remote Workcenter Dashboard*/
         Local string &strRemoteWCDashboardURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_PTAL, Field.ISCRIPT1, "FieldFormula", "IScript_PTAL_DASHBOARD") | "?tab=" | &TabName | &dashboardParam;
         %Response.RedirectURL(&strRemoteWCDashboardURL)
      End-If;
   Else
      %Response.RedirectURL(GenerateHomepagePortalURL(%Portal, %Node, &TabName) | &dashboardParam);
   End-If;

End-Function;

