Function IScript_PT_HomepageDND

   /* Local apiobject &portal; dup */
   /* Local string &tabName;  dup */
   /* Local string &pgltName;  dup */
   Local object &req = %Request;
   /* Local apiobject &homePage;  dup */
   Local ApiObject &userTabs;
   /* Local apiobject &userTab;  dup */
   Local ApiObject &userPglts;
   Local ApiObject &userPglt;
   Local ApiObject &movedPglt;
   Local string &draggedPgltNewCol;
   Local string &draggedPgltNewRow;
   Local string &draggedPgltOrigCol;
   Local string &draggedPgltOrigRow;
   Local boolean &isColumnChange;


   &Portal = %Session.GetPortalRegistry();
   If Not &Portal.Open(%Portal) Then
      Error MsgGet(95, 307, "Unable to open portal.  PortalName = %1", %Portal);
   End-If;

   &TabName = EscapeHTML(&req.GetParameter("tab"));
   &PgltName = EscapeHTML(&req.GetParameter("pgltname"));
   &draggedPgltNewCol = &req.GetParameter("col");
   &draggedPgltNewRow = &req.GetParameter("row");
   /*  D&D check for EP collaborative workspaces */
   If &Portal.Type = "WORKSPACE" Or
         &Portal.Type = "WORKSPACE_TMPL" Then
      &TabDefinitions = &Portal.TabDefinitions;
      &UserTab = &TabDefinitions.ItemByName(&TabName);
   Else
      &Homepage = &Portal.Homepage;
      &userTabs = &Homepage.UserTabs;
      &UserTab = &userTabs.ItemByName(&TabName);
   End-If;
   /* End  Workspace D&D check*/

   REM have to create a user homepage tab if they haven't already personalized;
   If None(&UserTab) Then
      CreateUserTab(&Portal, &userTabs, &Homepage);
   End-If;

   REM get and update the changed pagelets current row and column in the db;
   If &Portal.Type = "WORKSPACE" Or
         &Portal.Type = "WORKSPACE_TMPL" Then
      &userPglts = &UserTab.AssignedPagelets;
   Else
      &userPglts = &UserTab.SelectedPagelets;
   End-If;

   &movedPglt = &userPglts.ItemByName(&PgltName);
   If All(&movedPglt) Then
      &draggedPgltOrigCol = &movedPglt.Column;
      &draggedPgltOrigRow = &movedPglt.Row;

      rem check for a column change;
      If Not &draggedPgltOrigCol = &draggedPgltNewCol Then
         &isColumnChange = True;
         &movedPglt.Column = &draggedPgltNewCol;
      End-If;

      If Not &movedPglt.Row = &draggedPgltNewRow Then
         &movedPglt.Row = &draggedPgltNewRow;
      End-If;
   End-If;

   rem update the rest of pagelet rows in the modified column;
   &userPglt = &userPglts.First();
   While All(&userPglt)

      If Not &userPglt.PageletName = &PgltName Then

         If &isColumnChange Then
            rem any pagelets in the old column that come after where the pagelet used to be;
            rem need to move up in the row order;
            If &userPglt.Column = &draggedPgltOrigCol Then

               If Value(&userPglt.Row) > Value(&draggedPgltOrigRow) Then
                  &userPglt.Row = Value(&userPglt.Row) - 1;
               End-If;
            Else
               rem any pagelets in the new column need to move down in the row order;
               If &userPglt.Column = &draggedPgltNewCol Then
                  If Value(&userPglt.Row) >= Value(&draggedPgltNewRow) Then
                     &userPglt.Row = Value(&userPglt.Row) + 1;
                  End-If;
               End-If;
            End-If;

            rem just a row change occurred;
         Else
            If &userPglt.Column = &draggedPgltOrigCol Then

               rem check if the dragged pagelet was swapped with;
               rem a previous or next pagelet;
               If Value(&userPglt.Row) = Value(&draggedPgltNewRow) Then
                  rem dragged pagelet is below, move up;
                  If Value(&userPglt.Row) > Value(&draggedPgltOrigRow) Then
                     &userPglt.Row = Value(&userPglt.Row) - 1;
                  Else
                     &userPglt.Row = Value(&userPglt.Row) + 1;
                  End-If;
               Else
                  rem only modify stuff below the dragged pagelet if the;
                  rem dragged pagelet was moved to the bottom;
                  If Value(&userPglt.Row) > Value(&draggedPgltOrigRow) And
                        Value(&userPglt.Row) < Value(&draggedPgltNewRow) Then
                     &userPglt.Row = Value(&userPglt.Row) - 1;
                  End-If;
               End-If;
            End-If;
         End-If;
      End-If;
      &userPglt = &userPglts.Next();
   End-While;

   /*  D&D check for EP collaborative workspaces */
   If &Portal.Type = "WORKSPACE" Or
         &Portal.Type = "WORKSPACE_TMPL" Then
      If Not &UserTab.Save() Then
         PortalAPIError(&Portal);
      End-If;
   Else
      If Not &Homepage.Save() Then
         PortalAPIError(&Portal);
      End-If;
   End-If;
   /*End Workspace D&D check */

   /*
    Perform a homepage tab refresh, when the following criteria are met
    - column change occurred
    - 2 column layout
    - PIA component pagelet
    - force pagelet refresh is true (by default, this is not set)

 	A homepage tab refresh is done because some PIA component pagelets
    render themselves differently if they are in a wide or narrow column.
  */

   Local boolean &isHomepageRefresh;
   If &isColumnChange And
         &UserTab.ColumnLayout = "2" Then
      Local ApiObject &pgltDefn = &Portal.FindPgltByName(&PgltName);
      If All(&pgltDefn) And
            &pgltDefn.URLType = "UPGE" And
            &pgltDefn.ForceRefresh Then
         &isHomepageRefresh = True;
      End-If;
   End-If;

   &Portal.Close();

   If &isHomepageRefresh Then
      REM form the refresh URL and send it back to PT_HP2_JS JavaScript;
      Local string &refreshURL = "?tab=" | &TabName | "&pageletname=" | &PgltName | "&cmd=refreshPglt";
      %Response.Write(&refreshURL);
   End-If;

End-Function;

Function IScript_LoadImages()
   &asKeyVal = Split(%Request.QueryString, "&");
   &ImageName = Split(&asKeyVal [1], "=");
   &PgltName = Split(&asKeyVal [2], "=");
