   &ImageURL = &ImageURL | "?pgltName=" | &PgltName [2];


   %Response.Write(&ImageURL);

End-Function;

Function IScript_RemoveRemotePagelet()
   Local ApiObject &UniSysTabColl, &UniUserTabColl, &UniSelPgltColl, &UniAvailCatColl, &UniAvailPgltColl;
   Local ApiObject &UniSysTab, &UniUserTab, &UniAvailCat, &UniAvailPglt, &UniSelPglt, &UniAvailPgltTemp;
   Local string &UnitabName = "";
   Local Request &req = %Request;

   &Portal = PortalOpen();
   &UnitabName = &req.GetParameter("tab");

   If None(&UnitabName) Then
      &UnitabName = &Portal.GetDefaultHPTabOID();
   End-If;

   &UniSysTabColl = &Portal.TabDefinitions;
   &UniSysTab = &UniSysTabColl.ItemByName(&UnitabName);
   &UniUserTabColl = &Portal.Homepage.UserTabs;
   &UniUserTab = &UniUserTabColl.ItemByName(&UnitabName);

   If &UniUserTab <> Null Then
      &UniSelPgltColl = &UniUserTab.SelectedPagelets;
   Else
      &UniSelPgltColl = &UniSysTab.AssignedPagelets;
   End-If;

   &UniAvailCatColl = &UniSysTab.AvailableCategories;
   &UniAvailCat = &UniAvailCatColl.First();
   While &UniAvailCat <> Null

      rem &UniAvailPgltColl = &UniAvailCat.SelectedPagelets;
      &UniAvailPgltColl = &UniSelPgltColl;

      Local SQL &nodesSql = CreateSQL("SELECT MSGNODENAME FROM PSMSGNODEDEFN WHERE NODE_TYPE='PIA' AND ACTIVE_NODE='1' AND LOCALNODE<>1");
      Local string &ExtNodeName, &Nodename, &UNINAVPAGLTID;
      Local number &q;
      Local string &PermittedPagelets = "";
      While (&nodesSql.Fetch(&ExtNodeName)) /*collecting All IB network enabled nodes*/
         Local array of array of string &pageletnamesTemp = CreateArrayRept(CreateArrayRept("", 0), 0);
         Local array of string &pageletnames = CreateArrayRept("", 0);



         &q = 1;

         &UniAvailPglt = &UniAvailPgltColl.First();
         &UniAvailPgltTemp = &UniAvailPgltColl.First();

         For &I = 1 To &UniAvailPgltColl.COUNT /*Gathering pagelets belongs to externel nodes */

            If (&UniAvailPglt <> Null) Then
               Local ApiObject &pgCref = &Portal.findcrefbyname(&UniAvailPglt.Pageletname);
               Local ApiObject &attrib = &pgCref.Attributes;
               &Location = "";
               &Nodename = "";
               If &attrib.itemByName("UNPGLTID") <> Null Then
                  &UNINAVPAGLTID = &attrib.itemByName("UNPGLTID").value;
               End-If;
               If (&attrib.itemByName("NODE") <> Null And
                     &attrib.itemByName("LOCATION") <> Null) Then
                  &Nodename = &attrib.itemByName("NODE").value;
                  &Location = &attrib.itemByName("LOCATION").value;
               End-If;
               If (&Location = "REMOTE" And
                     &Nodename = &ExtNodeName) Then
                  rem &pageletnamesTemp.Push(CreateArray(&UniAvailPglt.Pageletname, &UNINAVPAGLTID));
                  &pageletnamesTemp.Push(&UNINAVPAGLTID);
                  &pageletnamesTemp [&pageletnamesTemp.Len].Push(&UniAvailPglt.Pageletname);
                  rem &pageletnames.Push(&UniAvailPglt.Pageletname);
                  &pageletnames.Push(&UNINAVPAGLTID);

               End-If;

            End-If;
            &UniAvailPglt = &UniAvailPgltColl.Next();
         End-For;
         If &pageletnames.Len > 0 Then
            &pageletnames = HasPageletAccess(&ExtNodeName, &pageletnames); /*Returning all pagelets having access*/

         End-If;

         If &pageletnames <> Null Then
            While (&q <= &pageletnames.Len) /*Pushing valid pagelets to permitted array */

               &PgltName = &pageletnames.Get(&q);
               &keypos = &pageletnamesTemp.Find(&PgltName);
               If &keypos <> 0 Then
                  &pgltNameValue = &pageletnamesTemp [&keypos][2];
                  &PermittedPagelets = &PermittedPagelets | &pgltNameValue;



                  &q = &q + 1;
                  If &q <= &pageletnames.Len Then
                     &PermittedPagelets = &PermittedPagelets | "--";
                  End-If;
               End-If;


            End-While;
         End-If;

         &UniAvailPglt = &UniAvailPgltColl.Next();
      End-While;

      &UniAvailCat = &UniAvailCatColl.Next();
   End-While;


   %Response.Write(&PermittedPagelets);
End-Function;

