Local ApiObject &Portal;
Local ApiObject &Root;
Local ApiObject &FolderColl;
Local ApiObject &Folder;
Local ApiObject &CREFColl;
Local ApiObject &CREF;
Local ApiObject &CREFObj;
Local ApiObject &FolderObj;
Local object &Request;
Local array of string &SelectedLevelId;
Local array of string &CRefUrl;
Local array of string &CRefName;
Local array of string &CRefDescription;

Function checkVisible(&FolderId As ApiObject) Returns boolean
   &date = %Date;
   &display = False;
   &name = &FolderId.Label;
   &VALIDFROM = &FolderId.ValidFrom;
   &VALIDTO = &FolderId.ValidTo;
   &colAttrib = &FolderId.Attributes;

   If (&VALIDFROM = Null And
         None(&VALIDTO)) Then
      &display = True;
   Else
      If (None(&VALIDFROM) And
            &VALIDTO >= &date) Then
         &display = True;
      Else
         If (&VALIDFROM <= &date And
               None(&VALIDTO)) Then
            &display = True;
         Else
            If (&VALIDFROM <= &date And
                  &VALIDTO >= &date) Then
               &display = True;
            End-If;
         End-If;
      End-If;
   End-If;
   If &display = True Then
      If &colAttrib.ItemByName("PORTAL_HIDE_FROM_NAV") <> Null Then
         If &colAttrib.ItemByName("PORTAL_HIDE_FROM_NAV").value = "TRUE" Then
            &display = False;
         End-If;
      End-If;
      If &colAttrib.ItemByName("PORTAL_IS_FOLDER_NAV") <> Null Then
         If &colAttrib.ItemByName("PORTAL_IS_FOLDER_NAV").value = "Y" Then
            &display = False;
         End-If;
      End-If;
      If &colAttrib.ItemByName("PORTAL_FOLDER_NAV_OBJECT") <> Null Then
         If &colAttrib.ItemByName("PORTAL_FOLDER_NAV_OBJECT").value <> "" Then
            &display = False;
         End-If;
      End-If;
   End-If;
   Return &display;
   rem Return True;
End-Function;

REM ***************************************************************************************;
REM Function: CreateBreadCrumbHREF                                                         ;
REM Purpose:                                                                               ;
REM Inputs:                                                                                ;
REM Output:                                                                                ;
REM ***************************************************************************************;
Function CreateBreadCrumbHREF(&FolderID, &FldrName, &CurrentLevel) Returns string
   &FldrDesc = &FldrName;
   &isFrames = "false";
   &isFrames = %Request.GetParameter("isFrame");
   &Link = "";
   &URL = "";

   &URL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_PORTAL, Field.PORTAL_NAV, "FieldFormula", "IScript_DrillDown") | "?FolderID=" | &FolderID;

   If (&CurrentLevel > 1) Then
      &URL = &URL | "&RootFolder=" | &SelectedLevelId [1] | "&Level1FolderID=" | &SelectedLevelId [2];
   End-If;
   If (&CurrentLevel > 2) Then
      &URL = &URL | "&Level2FolderID=" | &SelectedLevelId [3];
   End-If;
   &URL = &URL | "&Level=" | &CurrentLevel | "&PortalRegistryName=" | &Portal.Name;

   If &FolderID = "PORTAL_ROOT_OBJECT" Then
      &FldrDesc = MsgGetText(95, 414, "Menu");
   End-If;

   If (&isFrames = "true") Then
      &URL = convertURLforPortal(&URL);
      &Link = "<a class = ""small"" target=_top href=" | &URL;
   Else
      &Link = "<a class = ""small"" href=" | &URL;
   End-If;

   &Link = &Link | ">";

   &Link = &Link | &FldrDesc | "</a>&nbsp>";

   Return &Link;
End-Function;

REM ***************************************************************************************;
REM Function: GetFolderPath()                                                              ;
REM Purpose:                                                                               ;
REM Inputs:                                                                                ;
REM Output:                                                                                ;
REM ***************************************************************************************;
Function GetFolderPath() Returns string
   &FolderId = "";
   &CrefID = %Request.GetHeader("PORTALCONTENTID");
   &FolderId = EscapeHTML(%Request.GetParameter("FolderID"));
   If &FolderId <> "" Then
      &FolderObj = &Portal.FindFolderByName(&FolderId);
      If (&FolderObj = Null) Then
         &FolderObj = &Portal.RootFolder;
      End-If;
      &ParentID = &FolderObj.ParentName;
      &UnparsedPath = &FolderObj.Path;
      &Path = &UnparsedPath | ".";
   Else
      &tempURL = %Request.GetParameter("PortalActualURL");
      &CREF = &Portal.FindCRefByURL(&tempURL);
      If &tempURL <> "" And
            &CREF <> Null Then
         rem  Actually need to find the grandperson;
         &ParentID = &CREF.ParentName;
         &ParentFolder = &Portal.FindFolderByName(&ParentID);
         &ParentID = &ParentFolder.ParentName;
         &UnparsedPath = &CREF.Path;
         &Path = &UnparsedPath | ".";
      Else
         &Path = "";
      End-If
   End-If;

   Return &Path;
End-Function;


REM ***************************************************************************************;
REM Function: GetBreadcrumbsFromPath                                                       ;
REM Purpose:                                                                               ;
REM Inputs:                                                                                ;
REM Output:                                                                                ;
REM ***************************************************************************************;
Function GetBreadcrumbsFromPath(&Path As string) Returns string
   rem Get the first parent folder of either the CREF or the Folder;
   &SelectedLevelId = CreateArrayRept("", 0);
   &CurrentLevel = 0;
   &StartPos = 1;
   &LeftParenPos = Find("{", &Path, &StartPos);
   &BCHtml = "";

   &HomeURL = GetPortalHomepageURL();

   &BCHtml = "<a class = ""small"" target=_top href=" | &HomeURL;

   &BCHtml = &BCHtml | ">" | MsgGetText(95, 413, "Home") | "</A>&nbsp>";
   While &LeftParenPos <> 0
      &FldrName = Substring(&Path, &StartPos, &LeftParenPos - &StartPos);
      &RightParenPos = Find("}", &Path, &StartPos);
      &FldrID = Substring(&Path, &LeftParenPos + 1, &RightParenPos - (&LeftParenPos + 1));
      &StartPos = &RightParenPos + 2;
      &LeftParenPos = Find("{", &Path, &StartPos);

      REM If were in the folderlist and no more folder names exist, don't hyperlink;
      REM the last folder name in the path;
      If (&CurrentLevel > 0) Then
         &SelectedLevelId [&CurrentLevel] = &FldrID;
      End-If;

      &BCHtml = &BCHtml | CreateBreadCrumbHREF(&FldrID, &FldrName, &CurrentLevel);
      &CurrentLevel = &CurrentLevel + 1;
   End-While;
   If All(&FolderObj) Then
      If (&CurrentLevel > 0) Then
         &SelectedLevelId [&CurrentLevel] = &FolderObj.Name;
      End-If;
      &BCHtml = &BCHtml | CreateBreadCrumbHREF(&FolderObj.Name, &FolderObj.Label, &CurrentLevel);
   Else
      &BCHtml = &BCHtml | &CREF.Label;
   End-If;

   Return &BCHtml;
End-Function;


REM ***************************************************************************************;
REM Function: GetFormatedBreadcrumbs                                                       ;
REM Purpose:                                                                               ;
REM Inputs:                                                                                ;
REM Output:                                                                                ;
REM ***************************************************************************************;
Function GetFormatedBreadcrumbs() Returns string

   &BreadHTML = OverrideBreadcrumbs();

   REM Check if we need to build default breadcrumbs;
   If None(&BreadHTML) Then
      &Portal = PortalOpen();
      &Root = &Portal.RootFolder;
      &FolderColl = &Root.Folders;
      &Folder = &FolderColl.First();
      &SelectedPath = GetFolderPath();
      If (&SelectedPath <> "") Then
         &BreadHTML = GetBreadcrumbsFromPath(&SelectedPath);
      End-If;
      &Portal.Close();
   End-If;
   Return &BreadHTML;
End-Function;


REM ***************************************************************************************;
REM Function: IScript_Breadcrumbs                                                          ;
REM Purpose:                                                                               ;
REM Inputs:                                                                                ;
REM Output:                                                                                ;
REM ***************************************************************************************;
Function IScript_Breadcrumbs()

   %Response.Write(GetHTMLText(HTML.HTML_BREADCRUMBS, GetFormatedBreadcrumbs()));

End-Function;

