/* Return True if the pagelet's CREF AbsoluteContentURL contains "/jsr/" */
Function isJSRPortlet(&crefName As string) Returns boolean

   Local number &x;
   Local boolean &ret = False;
   Local ApiObject &cref;
   Local ApiObject &portal = PortalOpen();

   &cref = &portal.FindCRefByName(&crefName);
   If All(&cref) And
         &cref.Authorized Then
      &x = Find("/jsr/", &cref.AbsoluteContentURL);
      &ret = (&x > 0);
   End-If;
   &portal.close();

   Return &ret;

End-Function;

