Local ApiObject &SearchCollection, &cref, &PORTAL;
Local number &SearchItems;
Local number &SearchLimit;

rem---------------------------------------------------------------------------------------------------;
rem This function gets and validates a Cref.  It first validates it for security, then calls          ;
rem a function to validate it against the Valid From and To dates.                                    ;
rem Input:  Portal object, Content Provider, unqualified URL.                                         ;
rem Output: A cref                                                                                    ;
rem Returns:  True the Cref is valid, False if it isn't.                                              ;
rem---------------------------------------------------------------------------------------------------;
Function ValidateSearchResult(&Portal As ApiObject, &NodeName As string, &QS As string, &cref As ApiObject) Returns boolean
   &RetVal = False;
   &testurl = &Portal.GetQualifiedURL(&NodeName, &QS);
   &cref = &Portal.FindCRefByURL(&testurl);
   If &cref <> Null Then
      If &cref.Authorized = 1 Then
         REM Make sure it's a target cref;
         If &cref.UsageType = "TARG" Then
            &RetVal = True;
         End-If;
      End-If;
   End-If;

   Return &RetVal;

End-Function;

rem---------------------------------------------------------------------------------------------------;
rem This function returns the cref results in json format                                             ;
rem Input:  Valid Cref.                                                                               ;
rem---------------------------------------------------------------------------------------------------;
Function ReturnCrefDetail(&i, &cref) Returns string
   Local string &thisCref;

   &thisCref = "{""id"":""" | &i | """,""value"":""" | EscapeJavascriptString(&cref.Label) | """,""info"":""" | EscapeJavascriptString(&cref.description) | """,""url"":""" | &cref.AbsolutePortalURL | """}";

   Return &thisCref;

End-Function;


rem---------------------------------------------------------------------------------------------------;
rem This function loads a page full of results.                                                       ;
rem Input:  Search View Object, Portal object, result count, starting item                            ;
rem Output: n/a                                                                                       ;
rem Returns:  n/a                                                                                     ;
rem---------------------------------------------------------------------------------------------------;
Function LoadSearchResults(&SearchCollection As ApiObject, &Portal As ApiObject, &ValidHitNum As number, &HitCount)
   Local number &SrchCollIdx;
   &SrchCollIdx = 0;
   While ((&SrchCollIdx < &SearchCollection.Count) And
         (&ValidHitNum < &SearchLimit) And
         ((&SrchCollIdx + 1) <= &HitCount))
      &SrchCollIdx = &SrchCollIdx + 1;
      REM Get the Key and parse it to get the content provider and unqualified URL;
      &SearchResult = &SearchCollection.Item(&SrchCollIdx);
      &VeggieKey = &SearchResult.Key;
      &StartPos = 2;
      &RightBracketPos = Find("}", &VeggieKey, &StartPos);
      &ContentProvider = Substring(&VeggieKey, 2, &RightBracketPos - &StartPos);
      &URL = Substring(&VeggieKey, &RightBracketPos + 1, Len(&VeggieKey) - &RightBracketPos);
      If ValidateSearchResult(&Portal, &ContentProvider, &URL, &cref) Then
         If (&ValidHitNum >= 1) Then
            %Response.Write(",");
         End-If;
         %Response.Write(ReturnCrefDetail(&ValidHitNum, &cref));
         &ValidHitNum = &ValidHitNum + 1;
      End-If;
   End-While;
   REM Update the total searches we've done;
   &SearchItems = &SearchItems + &SrchCollIdx;
End-Function;


rem---------------------------------------------------------------------------------------------------;
rem  Get the parameter from the URL.  If a parameter was passed (from the portal header), then        ;
rem  execute the query and display the results                                                        ;
rem---------------------------------------------------------------------------------------------------;
Function ISCRIPT_PortalSearch()
   &SearchLimit = 300; /* default value */
   &PORTAL_SEARCH_KEY = %Request.GetParameter("SEARCH_TEXT");
   If (%Request.GetParameter("LIMIT") <> "") Then
      &SearchLimit = Value(%Request.GetParameter("LIMIT"));
   End-If;
   If All(&PORTAL_SEARCH_KEY) Then
      &WKey = Upper(&PORTAL_SEARCH_KEY);
      %Response.Write("{ptSearchResults:[]}");
      /**
      &PORTAL = PortalOpen();
      &StartPosition = 1;
      &ValidHitNum = 0;
      REM &WKey = Substitute(&WKey, "\", "\\");

      If ExecuteSearch(&PORTAL, &WKey, &StartPosition, &SearchCollection, &HitCount) Then
         %Response.Write("{ptSearchResults:[");
         LoadSearchResults(&SearchCollection, &PORTAL, &ValidHitNum, &HitCount);
         While ((&ValidHitNum < &SearchLimit) And
               (&SearchItems < &HitCount))
            &StartPosition = &SearchItems + 1;
            &RetVal = ExecuteSearch(&PORTAL, &WKey, &StartPosition, &SearchCollection, &HitCount);
            LoadSearchResults(&SearchCollection, &PORTAL, &ValidHitNum, &HitCount);
         End-While;
         %Response.Write("]}");
      Else
         If (&HitCount = 0) Then
            %Response.Write("{ptSearchResults:[]}");
         End-If;
      End-If;

      &PORTAL.Close();
   */
   End-If;
End-Function;

/****** SES START ******/

Function ReturnResultDetail(&i, &cref, &drillURL) Returns string
   Local string &thisCref;
   Local string &thisDescr = "";

   Local PT_SEARCH:SearchFieldCollection &customs = &cref.GetCustomAttributes();
   If (&customs <> Null) Then
      &thisDescr = &customs.Item(1).Value; /*only requested 1 which is DESCR254 */
   End-If;

   &thisCref = "{""id"":""" | &i | """,""value"":""" | EscapeJavascriptString(&cref.GetTitle()) | """,""info"":""" | EscapeJavascriptString(&thisDescr) | """,""url"":""" | &drillURL | """}";
   Return &thisCref;

End-Function;

Function DisplayResults(&res As PT_SEARCH:SearchResultCollection)
   Local number &PTSF_SEARCH_HITCNT = &res.GetDocumentCount();
   Local number &PTSF_SEARCH_ESTHIT = &res.GetEstimatedHitCount();
   Local integer &j, &i;
   Local PT_SEARCH:SearchResult &cur;

   Local string &drillURL = "";
   Local number &indxPos = 0;
   Local number &endsitePos = 0;
   Local string &currBase = "";

   %Response.Write("{ptSearchResults:[");
   For &i = 1 To &res.GetDocumentCount()
      &cur = &res.Item(&i);
      If (&i = 1) Then
         Local string &orgDrill = &cur.GetUrlLink();
         &indxPos = Find("/psp/", &orgDrill);
         If (&indxPos > 1) Then
            &endsitePos = Find("/", &orgDrill, &indxPos + 5); /* pos end of siteName */
            &currBase = Substitute(%Request.ContentURI, "/psc/", "/psp/");
         End-If;
      End-If;
      If &currBase <> "" Then
         &drillURL = &currBase | Substring(&cur.GetUrlLink(), &endsitePos + 1, Len(&cur.GetUrlLink()));
      Else
         &drillURL = &cur.GetUrlLink();
      End-If;
      If (&i > 1) Then
         %Response.Write(",");
      End-If;
      %Response.Write(ReturnResultDetail(&i - 1, &cur, &drillURL));

   End-For;
   %Response.Write("]}");

End-Function;


Function IScript_SESFilterNavMode(&fg As PT_SEARCH:SearchFilterGenerator);
   /* Return the Search Filter Modes based on UI Modes. Return everything in Fluid & SFF Mode.
      Return only Classic PIA pages when Peoplesoft is in Classic Mode 
   */
   Local integer &mode = UIDisplayMode();
   If (&mode = 1) Then
      /* Display PIA in Classic Mode=1 */
      &fg.MatchAny();
      &fg.EqualsString("PTSF_NAV_MODE", "1"); /* =CLASSIC */
      &fg.NotEqualsString("PTSF_NAV_MODE", "2"); /* !=FLUID */
      &fg.EndMatchAny();
   End-If;
End-Function;

Function IScript_SESPortalQry()
   &SearchLimit = 300; /* default value */
   &PORTAL_SEARCH_KEY = %Request.GetParameter("SEARCH_TEXT");
   If (%Request.GetParameter("LIMIT") <> "") Then
      &SearchLimit = Value(%Request.GetParameter("LIMIT"));
   End-If;

   If All(&PORTAL_SEARCH_KEY) Then
      Local PT_SEARCH:SearchFactory &factory = create PT_SEARCH:SearchFactory();
      Local PT_SEARCH:SearchQueryService &svc = &factory.CreateQueryService("default");
      Local PT_SEARCH:SearchQuery &qry = &svc.CreateQuery();
      Local PT_SEARCH:SearchFilterGenerator &fg = create PT_SEARCH:SearchFilterGenerator();

      &fg.MatchAll();
      &fg.EqualsString("PORTAL_NAME", %Portal);
      &fg.ContainsPartialWord("PORTAL_LABEL", &PORTAL_SEARCH_KEY);
      IScript_SESFilterNavMode(&fg);
      &fg.EndMatchAll();
      &fg.SetQueryFilter(&qry);
      &qry.StartIndex = 1;
      &qry.RequestedFields.Push(create PT_SEARCH:SearchField("DESCR254"));
      &qry.DocsRequested = &SearchLimit; /* AutoSuggest Limit */
      &qry.RemoveDuplicates = True;
      &qry.MarkDuplicates = False;
      &qry.Language = %Language_User;
      &qry.FilterConnector = "";
      &qry.GroupingSpec = Null;
      &qry.FacetFilters = Null;
      &qry.ReturnFacetValueCounts = True;
      &qry.MinimumDocumentsPerFacetValue = 0;
      &qry.MaximumNumberOfFacetValues = 0;
      &qry.SortFacetValuesBy = "COUNT_DES";
      &qry.Controls = "";
      &qry.TopN = 0;
      &qry.Categories = CreateArray(create PT_SEARCH:SearchCategory("PTPORTALREGISTRY"));
      &qry.bHighlight = False;

      try
         &SESresults = &qry.Execute(1, &qry.DocsRequested);
         If (&SESresults.GetDocumentCount() > 0) Then
            DisplayResults(&SESresults);
         Else
            REM Try with no wildcard to see if we have a hit, for Unicode search texts;
            &fg = create PT_SEARCH:SearchFilterGenerator();
            &fg.MatchAll();
            &fg.EqualsString("PORTAL_NAME", %Portal);
            &fg.ContainsPhrase("PORTAL_LABEL", &PORTAL_SEARCH_KEY);
            IScript_SESFilterNavMode(&fg);
            &fg.EndMatchAll();
            &fg.SetQueryFilter(&qry);
            &SESresults = &qry.Execute(1, &qry.DocsRequested);
            DisplayResults(&SESresults);

         End-If;
      catch PT_SEARCH:SESIMPL:EXCEPTION:SESQueryServiceException &sqe
         &sqe.Output();
      end-try
   End-If;
End-Function;

