Global string &g_sTraceName;
Global string &g_sFilter;
Global string &g_sCommand;

REM ***************************************************************************************;
REM Function:		IsTraceEnabled   									                   ;
REM Purpose:		Check if the User Trace Enabled of not			                        ;
REM Inputs:												                                   ;
REM Output:				                                                                   ;
REM ***************************************************************************************;

Function IsTraceEnabled() Returns boolean

   Local boolean &bRet;
   &bRet = False;
   If (%Request.GetHeader("PerfTraceEnabled") = "true") Then
      &bRet = True;
   End-If;
   rem   &bRet = true;
   Return &bRet;
End-Function;

REM ***************************************************************************************;
REM Function:		IScript_Main        								                   ;
REM Purpose:		Generate HTML page For Peopformance Monitor User Trace                 ;
REM Inputs:												                                   ;
REM Output:				                                                                   ;
REM ***************************************************************************************;
Function IScript_Main()
   Local string &HTML;
   Local string &sTitle;
   Local string &cssPTSTYLEDEF;
   Local string &psDomain;
   Local string &sCommand;
   Local string &sMyURL;
   Local string &sTraceName;
   Local string &sFilter;

   Local string &sLabelTraceName;
   Local string &sSetFilters;
   Local string &sStandard;
   Local string &sVerbose;
   Local string &sDebug;
   Local string &sNoChange;
   Local string &sStartTrace;
   Local string &sStopTrace;
   Local string &sErrorNoTraceName;
   Local string &sHideUserId1;
   Local string &sHideUserId2;
   Local string &sType;
   Local string &sUserIdTraced;
   /*   
   &S = %Request.GetParameterNames();
   For &i = 1 To &S.len
      &meme = &meme | "+" | &S.get(&i);
   End-For;
   %Response.Write(&meme);
*/
   &sType = %Request.GetParameter("type");
   If (&sType = "Administrator") Then
      &sUserIdTraced = %Request.GetParameter("user");
      &sUserIdTraced = EscapeHTML(&sUserIdTraced);
   Else
      &sHideUserId1 = "<!--";
      &sHideUserId2 = "-->";
   End-If;


   If ( Not All(&g_sCommand)) Then
      &g_sCommand = "0";
   End-If;

   &sCommand = %Request.GetParameter("PPMHCOMMAND");
   If (&g_sCommand = "0") Or
         (&sCommand = "1") Then
      If Not IsTraceEnabled() Then
         &sMyURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_PPM, Field.ISCRIPT1, "FieldFormula", "IScript_NoUserTrace");
         %Response.RedirectURL(&sMyURL);
         Return;
      End-If;
   Else
   End-If;

   If ( Not All(&g_sCommand)) And
         ( Not All(&sCommand)) Then
      &g_sCommand = "0";
      &sCommand = "0";
   End-If;
   If (&g_sCommand = "0") And
         ( Not All(&sCommand)) Then
      &sCommand = &g_sCommand;
   End-If;
   If (&g_sCommand = "0") And
         (&sCommand = "1") Then
      &g_sCommand = &sCommand;
   End-If;
   If (&g_sCommand = "1") And
         ( Not All(&sCommand)) Then
      &sCommand = &g_sCommand;
   End-If;
   If (&g_sCommand = "1") And
         (&sCommand = "2") Then
      &g_sCommand = "0";
   End-If;

   /* Appending date/time to default trace name. */
   &sTraceName = %Request.GetParameter("PPMHTRACENAME");
   &sTraceName = EscapeHTML(&sTraceName);
   If (All(&sTraceName)) Then
      &g_sTraceName = &sTraceName;
   Else
      If (All(&g_sTraceName)) Then
         &sTraceName = &g_sTraceName;
      Else
         If (All(&sUserIdTraced)) Then
            &sTraceName = &sUserIdTraced;
         Else
            /*ICE 1121046000 where TraceName can be 30 chars) */
            &sTraceName = %UserId;
            If Len(&sTraceName) > 30 Then
               &sTraceName = Substring(&sTraceName, 1, 30);
            End-If;
            /* Removed per ICE 657119000
            &sTraceName = &sTraceName | ": " | DateTimeToLocalizedString(%Datetime, "yyyy-MM-dd HH:mm:ss");
*/
         End-If;
         &g_sTraceName = &sTraceName;
      End-If;
   End-If;

   &sFilter = %Request.GetParameter("PPMHFILTER");
   &sFilter = EscapeHTML(&sFilter);
   If (All(&sFilter)) Then
      &g_sFilter = &sFilter;
   Else
      If (All(&g_sFilter)) Then
         &sFilter = &g_sFilter;
      Else
         &sFilter = "0";
         &g_sFilter = &sFilter;
      End-If;
   End-If;

   &sTitle = MsgGetText(209, 401, "Message Not Found");
   &cssPTSTYLEDEF = PTGetStyleSheetURL();
   &psDomain = SetDocDomainForPortal();
   If (&psDomain = "") Then
      &psDomain = SetDocDomainToAuthTokenDomain();
   End-If;

   &sMyURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_PPM, Field.ISCRIPT1, "FieldFormula", "IScript_Main");

   &sLabelTraceName = MsgGetText(209, 402, "Message Not Found");
   &sSetFilters = MsgGetText(209, 403, "Message Not Found");
   &sStandard = MsgGetText(209, 404, "Message Not Found");
   &sVerbose = MsgGetText(209, 405, "Message Not Found");
   &sDebug = MsgGetText(209, 406, "Message Not Found");
   &sNoChange = MsgGetText(209, 407, "Message Not Found");
   &sStartTrace = MsgGetText(209, 408, "Message Not Found");
   &sStopTrace = MsgGetText(209, 409, "Message Not Found");
   &sOverrideWith = MsgGetText(209, 412, "Message Not Found");

   &sErrorNoTraceName = MsgGetText(209, 410, "Message Not Found");

   If ((&sFilter = "0" Or
         &sFilter = "4" Or
         &sFilter = "5" Or
         &sFilter = "6") And
         (&sCommand = "0" Or
            &sCommand = "1" Or
            &sCommand = "2")) Then
      &HTML = GetHTMLText(HTML.PPM_USERTRACE, &sTitle, &cssPTSTYLEDEF, &psDomain, &sCommand, &sMyURL, &sTraceName, &sFilter, &sLabelTraceName, &sSetFilters, &sStandard, &sVerbose, &sDebug, &sNoChange, &sStartTrace, &sStopTrace, &sErrorNoTraceName, &sHideUserId1, &sHideUserId2, &sOverrideWith);
   Else
      &sInvalidParam = MsgGetText(257, 297, "Message Not Found", "Input for Performanace Trace ");
      &HTML = &sInvalidParam;
   End-If;
   %Response.Write(&HTML);
End-Function;

