import PTAI_ACTION_ITEMS:*;
import PTCS_SRVDEFN:*;
import PTAI_COLLECTION:*;

Declare Function URLforAWEaprchain PeopleCode FUNCLIB_PTAI.FUNCLIB FieldFormula;

/***********************************************
Performs following tasks via Ajax request
1. Sets the Current Item flag in ITEM table while clicking an AItem on pagelet

	This function is not called after post processing since we are reloading the
	pagelet after post processing. 
***********************************************/
Function IScript_GetItemStatus
   Local string &strAGItemId, &strAction, &strIsRequired;

   &strAGItemId = Unencode(%Request.GetParameter("PTAI_ITEM_ID"));
   &strAction = Unencode(%Request.GetParameter("PTAI_ACTION"));
   Local PTAI_ACTION_ITEMS:ActionItem &ObjAItem = create PTAI_ACTION_ITEMS:ActionItem();
   Local datetime &DtStartDttm;
   try
      &ObjAItem.open(&strAGItemId);

      Evaluate &strAction
      When = "save"
         /* This is not used since we are reloading the whole pagelet after post processing */
         %Response.Write(EscapeHTML(&ObjAItem.ItemId | "," | &ObjAItem.Status));
         Break;

      When = "click"
         Local string &listId, &actionId;
         &listId = &ObjAItem.ListId;

         &ObjAItem.open(&strAGItemId);
         &ObjAItem.CurrentStep = True;
         /* Set the non required item status to In Progress when user visits */
         If ( Not &ObjAItem.Required) Then
            &strIsRequired = "N";
            Local PTAI_ACTION_ITEMS:Constants &AIConstants = create PTAI_ACTION_ITEMS:Constants();
            If &ObjAItem.Status = &AIConstants.STATUS_ASSIGNED Then
               &ObjAItem.Status = &AIConstants.STATUS_IN_PROGRESS;
            End-If;
         Else
            &strIsRequired = "Y";
         End-If;
         /* When a User Lands on a Step - Increment the StepCount property. Assign the StartDttm property for the first visit only */
         &ObjAItem.CountNum = &ObjAItem.CountNum + 1;
         &DtStartDttm = &ObjAItem.StartDttm;
         If None(&DtStartDttm) Then
            &ObjAItem.StartDttm = %Datetime;
         End-If;

         Local boolean &bSave = &ObjAItem.save();

         <* 
		 If &bSave Then
            /* Collect Usage Statistics if Step is enabled for Usage collection*/
            If &ObjAItem.EnableUsageStats Then
               Local Record &recUsgStats;
               &recUsgStats = CreateRecord(Record.PTAI_USGE_STATS);
               &recUsgStats.PTAI_ITEM_ID.Value = &strAGItemId;
               &recUsgStats.PTAI_LIST_ID.Value = &listId;
               &recUsgStats.PTAI_START_DTTM.Value = %Datetime;

               &recUsgStats.Insert();
            End-If;
         End-If; 
		 *>
         Break;
      End-Evaluate;
      %Response.Write(EscapeHTML(&ObjAItem.ListId | "," | &ObjAItem.ItemId | "," | &ObjAItem.Status | "," | &strIsRequired));
   catch Exception &e
      %Response.Write(EscapeHTML(&e.ToString()));
   end-try;
End-Function;

/***********************************************
This returns currect selected Action item of the given Action item list
***********************************************/

Function IScript_GetCurrentAction
   Local string &strListID, &strActionItem;
   Local PTAI_ACTION_ITEMS:List &currentList;

   &strListID = Unencode(%Request.GetParameter("PTAI_LISTID"));
   &currentList = create PTAI_ACTION_ITEMS:List();
   try
      &currentList.open(&strListID);
      &strActionItem = &currentList.getCurrentItem();
      %Response.Write(EscapeHTML(&strActionItem));
   catch Exception &e
      %Response.Write(EscapeHTML(&e.ToString()));
   end-try;

End-Function;

/***********************************************
Performs AG preprocessing for items
***********************************************/
Function IScript_AIPreProcessing
   Local string &strServiceID, &strParameters, &strPackage, &strPath, &strAppClassId, &strObjClass;
   Local PTAI_ACTION_ITEMS:ActionItem &ObjAItem;
   Local PTCS_SRVDEFN:RCServiceDefinition &srvdefn;

   &strServiceID = Unencode(%Request.GetParameter("SERVICEID"));
   &strParameters = Unencode(%Request.GetParameter("PARAMETERS"));
   &ObjAItem = create PTAI_ACTION_ITEMS:ActionItem();

   try
      &srvdefn = create PTCS_SRVDEFN:RCServiceDefinition(&strServiceID, %Language);
      &strPackage = &srvdefn.PackageRoot;
      &strPath = &srvdefn.QualifyPath;
      &strAppClassId = &srvdefn.AppclassId;
      If All(&strPackage) And
            All(&strPath) And
            All(&strAppClassId) Then
         If &strPath <> ":" Then
            &strObjClass = &strPackage | ":" | &strPath | ":" | &strAppClassId;
         Else
            &strObjClass = &strPackage | ":" | &strAppClassId;
         End-If;
      End-If;

      Local object &Obj = CreateObject(&strObjClass);
      ObjectDoMethod(&Obj, "ExecuteHelper", &strParameters);
      ObjectDoMethod(&Obj, "execute");
      &ObjAItem.open(&Obj.StrActionItemId);
      Local string &isRequired = "N";
      If (&ObjAItem.Required) Then
         &isRequired = "Y";
      End-If;

      If (&Obj.StrRedirectUrl <> "") Then
         %Response.Write(EscapeHTML(&ObjAItem.ItemId | "," | &ObjAItem.Status) | ",Y," | &Obj.StrRedirectUrl | "," | &isRequired);
      Else
         %Response.Write(EscapeHTML(&ObjAItem.ItemId | "," | &ObjAItem.Status) | ",N," | " ," | &isRequired);
      End-If;

   catch Exception &exp
      %Response.Write(EscapeHTML(&exp.ToString()));
   end-try;
End-Function;



/***********************************************
Loads AG subpage buttons in WC template
***********************************************/

Function IScript_LoadSubpageButtons
   Local string &list_id, &item_id, &strHtml, &strBind1, &strBind2, &strBind3, &strPrevBtnStyle, &strNextBtnStyle, &strPkg, &strPath, &strClass, &strAppClass, &strHiddenFld, &strMarkCompleteStyle, &strMarkCompleteAnchorStyle, &strConfirmMsg, &strMsgBoxTitle, &strViewApprovalStyle;
   Local string &strBind6, &strBind7, &saveAI, &save_NextAI, &save_PrevAI, &ViewApprURL, &viewappr_link;
   Local string &strField1, &strField2, &strField3, &strField4, &strField5, &strSaveBtnField;
   Local number &i;
   Local PTAI_ACTION_ITEMS:List &currentList;
   Local PTAI_ACTION_ITEMS:ActionItem &ObjCurAItem;
   Local PTAI_COLLECTION:Collection &buttons, &itemButtons;
   Local PTAI_COLLECTION:Collectable &buttonAsCollectable;
   Local PTAI_ACTION_ITEMS:PgltButtons &pgltButtons, &matchingItemButton;
   Local PTAI_ACTION_ITEMS:Constants &AIConstants;
   Local PTCS_SRVDEFN:RCServiceDefinition &srvdefn;

   &list_id = Unencode(%Request.GetParameter("PTAI_LIST_ID"));

   &currentList = create PTAI_ACTION_ITEMS:List();
   &AIConstants = create PTAI_ACTION_ITEMS:Constants();

   try
      &currentList.open(&list_id);

      &buttons = &currentList.GetPgltBtn();


      &item_id = &currentList.getCurrentItem();
      If All(&item_id) Then
         &ObjCurAItem = create PTAI_ACTION_ITEMS:ActionItem();
         &ObjCurAItem.open(&item_id);
         &itemButtons = &ObjCurAItem.GetPgltBtn();
      End-If;

      /** Display List buttons only if its not defined at item.	**/
      /**  Display Items Buttons if its defined and is active at item. 	**/

      For &i = 1 To &itemButtons.Count

         &pgltButtons = &itemButtons.Item(&i) As PTAI_ACTION_ITEMS:PgltButtons;

         If &pgltButtons.btnIsActive Then

            If &pgltButtons.btnMsgSetNbr = 0 And
                  &pgltButtons.btnMsgNbr = 0 Then
               &strConfirmMsg = "F";
            Else
               &strConfirmMsg = MsgGetExplainText(&pgltButtons.btnMsgSetNbr, &pgltButtons.btnMsgNbr, " ");
               &strMsgBoxTitle = &pgltButtons.btnLabel | " - " | MsgGetText(263, 306, "Message Not Found");
               If None(&strConfirmMsg) Then
                  &strConfirmMsg = MsgGetText(&pgltButtons.btnMsgSetNbr, &pgltButtons.btnMsgNbr, "Message Not Found");
               End-If;
            End-If;


            Evaluate &pgltButtons.btnMethod
            When = "MarkComplete"
               If &ObjCurAItem.Status = &AIConstants.STATUS_COMPLETED Then
                  &strMarkCompleteStyle = " class='PSPUSHBUTTONDISABLED' disabled=true ";
                  &strMarkCompleteAnchorStyle = "class='PSPUSHBUTTONDISABLED Left' disabled=true ";
               Else
                  &strMarkCompleteStyle = "class='PSPUSHBUTTON'";
                  &strMarkCompleteAnchorStyle = "class='PSPUSHBUTTON Left'";
               End-If;
