            When = "PTAI_NAV_SAVE_PREV" /* at list level only component save ICSave is possible since other button IDs can be stored only at item level*/
               SQLExec("SELECT PTAI_FIELD1_LBL, PTAI_FIELD2_LBL, PTAI_FIELD3_LBL, PTAI_FIELD4_LBL, PTAI_FIELD5_LBL FROM %Table(PTAI_LIST) WHERE PTAI_LIST_ID=:1 AND PTAI_IS_TMPL='Y' ", &currentList.ParentTemplate, &strField1, &strField2, &strField3, &strField4, &strField5);
               &strSaveBtnField = "PTAI_NAV_SAVE";
               Evaluate &strSaveBtnField
