      %Response.Write(&strHtml);
   catch Exception &e
      %Response.Write(EscapeHTML(&e.ToString()));
   end-try;

End-Function;


/***********************************************
Performs actions on clicking custom AG subpage buttons like Exit/Cancel etc using ajax
***********************************************/

Function IScript_SubpageActions
   Local string &list_id, &strBtnLabel, &pkg, &path, &class, &strUrl, &strBtnMethod, &item_id, &srcButtonSrc;
   Local PTAI_ACTION_ITEMS:List &currentList;
   Local PTAI_ACTION_ITEMS:ActionItem &currentItem;
   Local PTAI_COLLECTION:Collection &buttons;
   Local PTAI_ACTION_ITEMS:PgltButtons &pgltButtons;
   Local object &obj;
   Local number &i;

   &list_id = Unencode(%Request.GetParameter("PTAI_LIST_ID"));
   &strBtnMethod = Unencode(%Request.GetParameter("PTAI_BTN_METHOD"));
   &srcButtonSrc = Unencode(%Request.GetParameter("PTAI_BTN_SRC"));

   &currentList = create PTAI_ACTION_ITEMS:List();
   try
      &currentList.open(&list_id);
      &item_id = &currentList.getCurrentItem();

      &strUrl = "";
      Evaluate &srcButtonSrc
      When = "ITEMBTN"
         &currentItem = create PTAI_ACTION_ITEMS:ActionItem();
         &currentItem.open(&item_id);
         If &currentItem <> Null Then
            &pkg = &currentItem.PackageRoot;
            &path = &currentItem.QualifyPath;
            &class = &currentItem.AppClassID;
            If All(&pkg) And
                  All(&path) And
                  All(&class) Then
               If &path <> ":" Then
                  &obj = CreateObject(&pkg | ":" | &path | ":" | &class);
               Else
                  &obj = CreateObject(&pkg | ":" | &class);
               End-If;
            End-If;

            &buttons = &currentItem.GetPgltBtn();
            For &i = 1 To &buttons.Count
               &pgltButtons = &buttons.Item(&i) As PTAI_ACTION_ITEMS:PgltButtons;
               If &strBtnMethod = &pgltButtons.btnMethod Then
                  &strUrl = ObjectDoMethod(&obj, &pgltButtons.btnMethod, &list_id);
               End-If;
            End-For;
         End-If;
         Break;

      When = "LISTBTN"

         &pkg = &currentList.pgltPackageRoot;
         &path = &currentList.pgltQualifyPath;
         &class = &currentList.pgltAppClass;

         If All(&pkg) And
               All(&path) And
               All(&class) Then
            If &path <> ":" Then
               &obj = CreateObject(&pkg | ":" | &path | ":" | &class);
            Else
               &obj = CreateObject(&pkg | ":" | &class);
            End-If;
         End-If;

         &buttons = &currentList.GetPgltBtn();
         For &i = 1 To &buttons.Count
            &pgltButtons = &buttons.Item(&i) As PTAI_ACTION_ITEMS:PgltButtons;
            If &strBtnMethod = &pgltButtons.btnMethod Then
               &strUrl = ObjectDoMethod(&obj, &pgltButtons.btnMethod, &list_id);
            End-If;
         End-For;
         Break;
      End-Evaluate;

      If &strBtnMethod = "MarkComplete" Then
         %Response.Write(&strBtnMethod | &item_id);
      Else
         %Response.Write(EncodeURL(&strUrl));
      End-If;
   catch Exception &e
      rem %Response.Write(EscapeHTML(&e.ToString()));
      %Response.Write("");
   end-try;

End-Function;

/***********************************************
Get parent item status
***********************************************/

Function IScript_CurrentParentStatus
   Local string &strParentActionItem, &childActionItemId;
   Local PTAI_ACTION_ITEMS:ActionItem &ObjAItem;
   &childActionItemId = Unencode(%Request.GetParameter("childActionItemId"));
   &ObjAItem = create PTAI_ACTION_ITEMS:ActionItem();
   try
      &ObjAItem.open(&childActionItemId);
      &strParentActionItem = &ObjAItem.ParentId;
      If &strParentActionItem <> "ROOT" Then
         &ObjAItem.open(&strParentActionItem);
         Local string &isRequired = "N";
         If (&ObjAItem.Required) Then
            &isRequired = "Y";
         End-If;
         %Response.Write(EscapeHTML(&ObjAItem.ItemId | "," | &ObjAItem.Status | "," | &isRequired));
      Else
         %Response.Write("");
      End-If;
   catch Exception &exp
      %Response.Write(EscapeHTML(&exp.ToString()));
   end-try
End-Function;

