/*************************
This function will return distinct IB nodes 
*************************/
Function getDistinctIBNodesList Returns array of string
   Local SQL &nodeListSQL = CreateSQL("select distinct(A.MSGNODENAME) from PSMSGNODEDEFN A where  A.IB_NETWORK='1' and A.LOCALNODE not in ('1')");
   Local array of string &Nodes, &NodeURIs;
   Local boolean &found;

   &NodeURIs = CreateArrayRept("", 0);
   &Nodes = CreateArrayRept("", 0);
   &NodeColl = %Session.GetNodes();

   While &nodeListSQL.Fetch(&msgnodename)
      &Node = &NodeColl.ItemByName("" | &msgnodename | "");
      If &Node <> Null Then
         If All(&Node.ContentURI) Then
            &found = False;
            If All(&NodeURIs) Then
               For &j = 1 To &NodeURIs.Len
                  If &NodeURIs [&j] = &Node.ContentURI Then
                     &found = True;
                     &Nodes [&j] = &Nodes [&j] | "," | &Node.name;
                     Break;
                  End-If;
               End-For;
            End-If;
            If &found = False Then
               &Nodes.Push(&Node.name | "," | &Node.ContentURI);
               &NodeURIs.Push(&Node.ContentURI);
            End-If;
         End-If;
      End-If;
   End-While;
   Return &Nodes;
End-Function;


/************************
For Activity Guide In Progress Pagelet html
************************/
Function IScript_InProcessActivityGuide
   Local string &remoteCall = %Request.GetParameter("remoteCall");
   Local string &ReturnHTML = "";
   Local number &remoteActGuideCounter = 0;
   Local number &localActGuideCounter = 0;
   Local string &Html, &onclickJs, &strMessage;
   &Html = "";
   &bulletImageUrl = %Response.GetImageURL(Image.PTPP_BULLET);
   &onclickJs = "return true;";
   Local Rowset &MyIPActivityGuide = CreateRowset(Record.PTAI_IPPGLT_SVW);
   &MyIPActivityGuide.Fill("where PORTAL_NAME = :1 AND PTAI_LIST_STATUS IN ('IP',' ') AND OPRID = :2 AND PTAI_IS_TMPL = 'N'", %Portal, %UserId);

   If All(&MyIPActivityGuide.GetRow(1).GetRecord(Record.PTAI_IPPGLT_SVW).GetField(Field.PTAI_LIST_ID).Value) Then
      &localActGuideCounter = &MyIPActivityGuide.ActiveRowCount;
      For &i = 1 To &MyIPActivityGuide.ActiveRowCount
         Local Field &Label = &MyIPActivityGuide.GetRow(&i).GetRecord(Record.PTAI_IPPGLT_SVW).GetField(Field.PTAI_LABEL);
         Local Field &Url = &MyIPActivityGuide.GetRow(&i).GetRecord(Record.PTAI_IPPGLT_SVW).GetField(Field.URL);
         Local Field &TmplId = &MyIPActivityGuide.GetRow(&i).GetRecord(Record.PTAI_IPPGLT_SVW).GetField(Field.PTAI_PARENT_TMPL);
         Local Field &ListId = &MyIPActivityGuide.GetRow(&i).GetRecord(Record.PTAI_IPPGLT_SVW).GetField(Field.PTAI_LIST_ID);
         Local string &StrUrl;
         Local string &contextParams = "";

         Local PTAI_ACTION_ITEMS:List &oList = create PTAI_ACTION_ITEMS:List();
         Local PTAI_COLLECTION:Collection &oCtxt = create PTAI_COLLECTION:Collection();
         &oList.open(&ListId.Value);
         &oCtxt = &oList.GetContext();
         Local number &contextCount = 1;

         &contextParams = "&CONTEXTIDPARAMS=TEMPLATE_ID:" | &TmplId.Value;
         While &contextCount <= &oCtxt.Count
            Local PTAI_ACTION_ITEMS:ContextData &ContextObject = (&oCtxt.Item(&contextCount) As PTAI_ACTION_ITEMS:ContextData);
            &contextParams = &contextParams | "&CONTEXTIDPARAMS=" | &ContextObject.fieldname | ":" | &ContextObject.keyValue;
            &contextCount = &contextCount + 1;
         End-While;
         Local string &PTAINodeUriRequest = %Request.GetParameter("PTAINodeUri");
         If All(&PTAINodeUriRequest) Then
            &StrUrl = &PTAINodeUriRequest | &Url.Value;
         Else
            &PTAINodeUriRequest = %Request.ContentURI;
            &PTAINodeUriRequest = Substitute(&PTAINodeUriRequest, "/psc/", "/psp/");
            &StrUrl = &PTAINodeUriRequest | &Url.Value;
         End-If;


         If Find("?", &StrUrl) > 0 Then
            &contextParams = Replace(&contextParams, 1, 1, "");
            &StrUrl = &StrUrl | "&" | &contextParams;
         Else
            &contextParams = Replace(&contextParams, 1, 1, "");
            &StrUrl = &StrUrl | "?" | &contextParams;
         End-If;


         &strMessage = MsgGetText(263, 151, "Message Not Found - No Target URL set for this List.");
         If None(&Url.Value) Then
            &onclickJs = "alert('" | EscapeHTML(&strMessage) | "');return false;"
         Else
            &onclickJs = "return true;";
         End-If;
         &Html = &Html | GetHTMLText(HTML.PTAI_INPROG_PGLT, &StrUrl, &Label.Value, &onclickJs);
      End-For;
   End-If;

   If Exact(&remoteCall, "Y") Then
      &ReturnHTML = &Html;
      %Response.WriteLine(&ReturnHTML);
   Else
      Local string &remoteHTML;
      Local array of string &nodeArray;
      &nodeArray = getDistinctIBNodesList();
      Local number &nodeCounter = 0;
      While (&nodeCounter < &nodeArray.Len)
         &nodeCounter = &nodeCounter + 1;
         Local string &nodeName = &nodeArray [&nodeCounter];
         Local array of string &nodeDataArray = Split(&nodeName, ",");
         Local string &CurrNodeContentURI = &nodeDataArray [2];
         Local string &PTAINodeUri = %Request.ContentURI;
         &PTAINodeUri = Substitute(&PTAINodeUri, "/psc/", "/psp/");
         Local string &FullURL = &CurrNodeContentURI | %Portal | "/" | &nodeDataArray [1] | "/s/WEBLIB_PTAI.ISCRIPT2.FieldFormula.IScript_InProcessActivityGuide?remoteCall=Y&PTAINodeUri=" | &PTAINodeUri;
         Local string &remoteHTMLTemp;
         try
            &remoteHTMLTemp = UniNavMessage(&nodeDataArray [1], &FullURL);
         catch Exception &e
         end-try;
         If Find("<tr>", &remoteHTMLTemp) > 0 Then
            &remoteHTML = &remoteHTML | &remoteHTMLTemp;
            &remoteActGuideCounter = &remoteActGuideCounter + 1;
         End-If;
      End-While;
      If &localActGuideCounter = 0 And
            &remoteActGuideCounter = 0 Then
         &ReturnHTML = EscapeHTML(MsgGetText(263, 155, "Message Not Found - There are no Activity Guides assigned to you"));
      Else
         &ReturnHTML = &Html | &remoteHTML;
         &ReturnHTML = GetHTMLText(HTML.PTAI_INPROG_TABLE, &ReturnHTML);
      End-If;
      %Response.WriteLine(&ReturnHTML);
   End-If;
End-Function;

import PTAI_ACTION_ITEMS:*;
import PTPPB_PAGELET:DataSource:ActivityGuideDataSource:*;
import PTAI_COLLECTION:Collection;

Declare Function genReloadAGGroupletsScript PeopleCode FUNCLIB_PTAI.PTAI_NUI FieldFormula;
Declare Function genReloadGroupletsScript PeopleCode FUNCLIB_PTGP.FUNCLIB FieldFormula;
Declare Function genOpenUrlScript PeopleCode FUNCLIB_PTGP.FUNCLIB FieldFormula;
Declare Function getTemplateId PeopleCode FUNCLIB_PTAI.PTAI_NUI FieldFormula;
Declare Function removeICQueryParams PeopleCode FUNCLIB_PTAI.PTAI_NUI FieldFormula;
Declare Function IsCustomDataType PeopleCode FUNCLIB_PTAI.PTAI_NUI FieldFormula;

Function IScript_FluidAGPreLoad

   Local string &Template_id, &strQuestionnaireUrl, &onLoadScript, &html;
   Local PTAI_ACTION_ITEMS:List &objTemplate;
   Local PTAI_COLLECTION:Collection &objCtxt;
   Local array of string &as_KeyVal = CreateArrayRept("", 0);
   Local array of array of string &aas_KeyVal = CreateArrayRept(CreateArrayRept("", 0), 0);
   Local number &i;
   Local PTPPB_PAGELET:DataSource:ActivityGuideDataSource &agDS;
   Local string &strTemp;
   Local boolean &bTemplateIdAvail, &bInstanceAvail;

   &bInstanceAvail = False;
   try
      &Template_id = getTemplateId();
      If Not IsCustomDataType(&Template_id) Then
         If All(&Template_id) Then
            &objTemplate = create PTAI_ACTION_ITEMS:List();
            &objTemplate.open(&Template_id);

            If &objTemplate <> Null Then
               /* generate questionnaire url. Need not pass unnecessary query params */
               &strQuestionnaireUrl = GenerateComponentContentURL(%Portal, %Node, MenuName.PTAI_MENU, "GBL", Component.PTAI_QSTNAIRE_NUI, "", "U") | "&" | removeICQueryParams();
               /* Check if template has any questions assigned */
               SQLExec(SQL.PTAI_QSTNNRECNT_FOR_ITEM, &Template_id, &exist);
               &objTemplate.HasQuestionnaire = All(&exist);

               &objCtxt = &objTemplate.GetContext();
               &as_KeyVal = Split(%Request.QueryString, "&");
               For &i = 1 To &as_KeyVal.Len
                  &aas_KeyVal [&i] = Split(&as_KeyVal [&i], "=");
               End-For;

               &agDS = create PTPPB_PAGELET:DataSource:ActivityGuideDataSource("");
               &agDS.bIsFluid = True;
               /* AGComp=I - Init */
               &agDS.AGComp = "I";
               &agDS.InstanceId = "";
               &bInstanceAvail = &agDS.isInstIdAvailInReqOrDSParam();
               If Not &bInstanceAvail Then
                  &bTemplateIdAvail = &agDS.isTemplateIdAvail();
                  &agDS.oCtxt = &objCtxt;
                  &agDS.aasKeyVal = &aas_KeyVal;
                  &bContextDataAvail = &agDS.isContextDataAvail( Null);
                  &bInstanceAvail = &agDS.canLoadInstFromContext();
               End-If;

               /* Override Security for delete if RestartAG flag is set or this is SUoW AG or Single Comp AG */
               &objTemplate.IsOverrideSecurity = (&objTemplate.bSUOW Or
                  (&objTemplate.IsSingleComponent And
                     &objTemplate.RestartAG) Or
                  &objTemplate.RestartAG);

               Local boolean &bLaunchQuestionnaire = False;
               If &bInstanceAvail Then
                  &objInstance = create PTAI_ACTION_ITEMS:List();
                  &objInstance.open(&agDS.InstanceId);
                  &objInstance.IsOverrideSecurity = &objTemplate.IsOverrideSecurity;

                  If &objTemplate.IsOverrideSecurity Then
                     &objInstance.delete();
                     /* Get new instance id since earlier one is deleted */
                     &agDS.InstanceId = "";
                  End-If;
                  &bLaunchQuestionnaire = (&objTemplate.RestartAG And
                     &objTemplate.HasQuestionnaire And
                     All(&strQuestionnaireUrl));
               Else
                  &bLaunchQuestionnaire = (&objTemplate.HasQuestionnaire And
                     All(&strQuestionnaireUrl));
               End-If;

               If &bLaunchQuestionnaire Then
                  &onLoadScript = genOpenUrlScript(&strQuestionnaireUrl, "", True);
               Else
                  &agDS.executeInit();
                  &onLoadScript = genReloadAGGroupletsScript(&agDS.InstanceId);
               End-If;
            End-If;
         End-If;
      Else /* custom data type */
         &onLoadScript = genReloadGroupletsScript();
      End-If;
   catch Exception &exp

      Local string &errorDetails, &errorMessage, &subst10, &subst9, &subst8, &subst7, &subst6, &subst5, &subst4, &subst3, &subst2, &subst1;

      Evaluate &exp.SubstitutionCount
      When > 9
         &subst10 = &exp.GetSubstitution(10);
      When > 8
         &subst9 = &exp.GetSubstitution(9);
      When > 7
         &subst8 = &exp.GetSubstitution(8);
      When > 6
         &subst7 = &exp.GetSubstitution(7);
      When > 5
         &subst6 = &exp.GetSubstitution(6);
      When > 4
         &subst5 = &exp.GetSubstitution(5);
      When > 3
         &subst4 = &exp.GetSubstitution(4);
      When > 2
         &subst3 = &exp.GetSubstitution(3);
      When > 1
         &subst2 = &exp.GetSubstitution(2);
      When > 0
         &subst1 = &exp.GetSubstitution(1);
      End-Evaluate;

      /* Using AGDEFAULTMSG as default text in the built-in function MsgGetExplainText below so we can skip it when there is no explain text in the message catalog */
      &errorMessage = MsgGetText(&exp.MessageSetNumber, &exp.MessageNumber, "(Message Not Found)", &subst1, &subst2, &subst3, &subst4, &subst5, &subst6, &subst7, &subst8, &subst9, &subst10);
      &errorDetails = MsgGetExplainText(&exp.MessageSetNumber, &exp.MessageNumber, "AGDEFAULTMSG", &subst1, &subst2, &subst3, &subst4, &subst5, &subst6, &subst7, &subst8, &subst9, &subst10);

      If Exact(&errorDetails, "AGDEFAULTMSG") Then
         &errorDetails = "";
      End-If;
      Local string &strMsgTitle;
      Evaluate &exp.MessageSeverity
      When = %MsgSeverity_Error
         &strMsgTitle = MsgGetText(263, 348, "Message Not found - Error");
         Break;
      When = %MsgSeverity_Warning
         &strMsgTitle = MsgGetText(263, 349, "Message Not found - Warning");
         Break;
      When-Other
         &strMsgTitle = MsgGetText(263, 340, "Message Not found - Message");
      End-Evaluate;

      &onLoadScript = "ptgpPage.showMessage('" | &strMsgTitle | "', '" | EscapeJavascriptString(&errorMessage) | "', '" | EscapeJavascriptString(&errorDetails) | "');";
   end-try;

   &html = GetHTMLText(HTML.PTGP_INCLUDE_SCRIPTS, &onLoadScript);
   %Response.Write(&html);
End-Function;




/***********************************************
Performs actions on clicking Fluid AG header action bar actions like Exit/Cancel etc using ajax
***********************************************/

Function IScript_SubpageActions
   Local string &list_id, &strBtnLabel, &pkg, &path, &class, &strUrl, &strBtnMethod, &item_id, &srcButtonSrc;
   Local PTAI_ACTION_ITEMS:List &currentList;
   Local PTAI_ACTION_ITEMS:ActionItem &currentItem;
   Local PTAI_COLLECTION:Collection &buttons;
   Local PTAI_ACTION_ITEMS:PgltButtons &pgltButtons;
   Local object &obj;
   Local number &i;

   &list_id = Unencode(%Request.GetParameter("PTAI_LIST_ID"));
   &strBtnMethod = Unencode(%Request.GetParameter("PTAI_BTN_METHOD"));
   &srcButtonSrc = Unencode(%Request.GetParameter("PTAI_BTN_SRC"));

   &currentList = create PTAI_ACTION_ITEMS:List();
   try
      &currentList.open(&list_id);
      &item_id = &currentList.getCurrentItem();

      &strUrl = "";
      Evaluate &srcButtonSrc
      When = "ITEMBTN"
         &currentItem = create PTAI_ACTION_ITEMS:ActionItem();
         &currentItem.open(&item_id);
         If &currentItem <> Null Then
            &pkg = &currentItem.PackageRoot;
            &path = &currentItem.QualifyPath;
            &class = &currentItem.AppClassID;
            If All(&pkg) And
                  All(&path) And
                  All(&class) Then
               If &path <> ":" Then
                  &obj = CreateObject(&pkg | ":" | &path | ":" | &class);
               Else
                  &obj = CreateObject(&pkg | ":" | &class);
               End-If;
            End-If;

            &buttons = &currentItem.GetPgltBtn();
            For &i = 1 To &buttons.Count
               &pgltButtons = &buttons.Item(&i) As PTAI_ACTION_ITEMS:PgltButtons;
               If &strBtnMethod = &pgltButtons.btnMethod Then
                  &strUrl = ObjectDoMethod(&obj, &pgltButtons.btnMethod, &list_id);
               End-If;
            End-For;
         End-If;
         Break;

      When = "LISTBTN"
         &pkg = &currentList.pgltPackageRoot;
         &path = &currentList.pgltQualifyPath;
         &class = &currentList.pgltAppClass;

         If All(&pkg) And
               All(&path) And
               All(&class) Then
            If &path <> ":" Then
               &obj = CreateObject(&pkg | ":" | &path | ":" | &class);
            Else
               &obj = CreateObject(&pkg | ":" | &class);
            End-If;
         End-If;

         &buttons = &currentList.GetPgltBtn();
         For &i = 1 To &buttons.Count
            &pgltButtons = &buttons.Item(&i) As PTAI_ACTION_ITEMS:PgltButtons;
            If &strBtnMethod = &pgltButtons.btnMethod Then
               &strUrl = ObjectDoMethod(&obj, &pgltButtons.btnMethod, &list_id);
            End-If;
         End-For;
         Break;
      End-Evaluate;

      Evaluate &strBtnMethod
      When = "MarkComplete"
         &currentItem = create PTAI_ACTION_ITEMS:ActionItem();
         &currentItem.open(&item_id);
         If &currentItem.bLockAfterCompletion Then
            %Response.Write("5" | "#");
         Else
            %Response.Write("0" | "#");
         End-If;
         Break;

      When = "SubmitAGProcess"
         %Response.Write("1" | "#" | EncodeURL(&strUrl));
         Break;

      When = "ReturnToQuestionnaire"
         %Response.Write("2" | "#" | EncodeURL(&strUrl));
         Break;

      When = "ExitAGProcess"
         %Response.Write("3" | "#" | EncodeURL(&strUrl));
         Break;

      When = "ExitAGNoDelete"
         %Response.Write("6" | "#" | EncodeURL(&strUrl));
         Break;

      When-Other
         %Response.Write("4" | "#" | EncodeURL(&strUrl));
      End-Evaluate;
   catch Exception &e
      %Response.Write("");
   end-try;

End-Function;

