/**
  * Get the request url include query strings
  *
  */
Function getRequestUrl() Returns string

   Local string &url = %Request.QueryString;
   If All(&url) Then
      &url = "?" | &url;
   End-If;
   &url = %Request.FullURI | &url;

   Return &url;

End-Function;



/**
  * Application Landing Page template with drop-down navigation
  * In the portal registry, this cref is located in:
  * Root >> Portal Objects >> Templates >> Application Landing Page (PTAL_APP_LANDING_PAGE_TEMPLATE)
  *
  */
Function IScript_PTAL_TPL

   Local PTAL_PAGE:PageFactory &pageFactory;
   Local PTAL_PAGE:Page &thisPage;
   Local PTAL_PAGE:PageTemplate:PageTemplate &thisPageTemplate;
   Local PTAL_PAGE:UTILITY:Utility &utility;

   Local string &finalHtml, &pageId;
   Local array of string &ContextParam;
   Local string &ContextParams;
   Local integer &i;

   &pageFactory = create PTAL_PAGE:PageFactory();
   &utility = &pageFactory.Utility;

   /* Get the page id */
   &pageId = %Request.GetParameter(&utility.QUERYPARAMETER_PTAL_ID);
   &ContextParam = %Request.GetParameterValues(&utility.QUERYPARAMETER_PTAL_CONTEXTID);

   If &ContextParam.Len < 1 Then
      &ContextParams = "";
   End-If;

   For &i = 1 To &ContextParam.Len

      If (&i = 1) Then
         &ContextParams = EscapeHTML(Substitute(&ContextParam [&i], ":", "="));

      Else
         &ContextParams = &ContextParams | "&" | EscapeHTML(Substitute(&ContextParam [&i], ":", "="));

      End-If;
   End-For;


   If None(&pageId) Then
      &pageId = %Request.GetParameter("PortalObjectName");
   End-If;

   try
      /* Get the page object */
      &thisPage = &pageFactory.getPageById(&pageId);
      &thisPage.ContextidParams = &ContextParams;

      /* the page template object */
      &thisPageTemplate = &thisPage.PageTemplate;

      /* Assemble the HTML */
      &finalHtml = &thisPageTemplate.genPageTemplateHtml();

   catch PTPP_PORTAL:EXCEPTION:NotFoundException &e1
      &finalHtml = &utility.getErrorPage(MsgGetText(240, 4041, "message not found"), MsgGetExplainText(240, 4041, "message not found", EscapeHTML(getRequestUrl())), "", "", "");

   catch Exception &e
      &finalHtml = &utility.getErrorPage(MsgGetText(240, 4162, "message not found"), MsgGetExplainText(240, 4162, "message not found"), &utility.getExceptionText(&e), &e.StackTrace, "");

   end-try;

   %Response.Write(&finalHtml);

End-Function;



