/**
  * WorkCenter Dashboard Launcher Page
  * No default cref in the portal registry.
  *
  */
Function IScript_PTAL_DASHBOARD

   Local string &html = "";
   Local string &tab, &url;
   Local ApiObject &portalObject, &tabCollObject, &dashboardObject;

   &tab = %Request.GetParameter("tab");
   If None(&tab) Then
      Error MsgGetExplainText(240, 4077, "<message not found>");
   End-If;

   &portalObject = openPortalRegistry(%Portal);
   &tabCollObject = &portalObject.TabDefinitions;
   &dashboardObject = &tabCollObject.ItemByName(&tab);

   If &dashboardObject <> Null Then
      &url = GenerateHomepagePortalURL(%Portal, %Node, &tab) | "&" | %Request.QueryString;
   Else
      Error MsgGetExplainText(240, 4077, "<message not found>");
   End-If;


   &url = GenerateHomepagePortalURL(%Portal, %Node, &tab) | "&" | %Request.QueryString;

   If (Find("contentNode", &url) > 0) Then
      &html = GetHTMLText(HTML.PTAL_DASHBOARD_LAUNCHER, &url | "&remwcdb=true");
   Else
      &html = GetHTMLText(HTML.PTAL_DASHBOARD_LAUNCHER, &url);
   End-If;

   %Response.Write(&html);

End-Function;



/**
  * WorkCenter Dashboard Header Pagelet
  * No default cref in the portal registry.
  *
  */
Function IScript_PTAL_DASHBOARD_HEADER

   Local string &html = "&nbsp;";
   Local string &tab, &market, &headerLinks;
   Local string &persText, &refreshHomepageJS, &perfHtml, &modifySysTabHtml, &helpLinkHtml, &dashboardTitle, &persLinksStyleClass;
   Local string &contentText, &contentUrl, &contentOnClick;
   Local string &layoutText, &layoutUrl, &layoutOnClick;
   Local string &helpId, &helpText, &helpAltText;
   Local boolean &isAccessibilityMode, &isInAppLandingPage;

   Local ApiObject &portalObj, &tabCollObj, &dashboardObj, &userTabObj, &perfObj;


   &tab = %Request.GetParameter("tab");
   If None(&tab) Then
      %Response.Write(&html);
      Return;
   End-If;


   &perfHtml = "";
   &modifySysTabHtml = "";
   &helpLinkHtml = "";
   &dashboardTitle = "";
   &persLinksStyleClass = "ptdboardlinks";


   &market = %Market;
   If None(&market) Then
      &market = "GBL";
   End-If;


   /* Flags */
   &isAccessibilityMode = (GetUserOption("PPTL", "ACCESS") <> "N");
   &isInAppLandingPage = isInAppLandingPage();


   /* Open the Portal objects */
   &portalObj = openPortalRegistry(%Portal);
   &tabCollObj = &portalObj.TabDefinitions;
   &dashboardObj = &tabCollObj.ItemByName(&tab);
   If (None(&dashboardObj) Or
         Not &dashboardObj.Authorized Or
         Not IsValidDate(&dashboardObj)) Then
      %Response.Write(&html);
      Return;
   End-If;


   /* Generate Personalization Links */
   &perfObj = &portalObj.FindCRefByName("PT_PORTAL_HOMEPAGE_GBL");
   If (All(&perfObj) And
         &perfObj.Authorized) Then

      &persText = MsgGetText(95, 58, "<message not found>");
      &refreshHomepageJS = GetRefreshHPJS(&tab);

      &layoutText = MsgGetText(95, 59, "<message not found>");
      &contentText = MsgGetText(95, 60, "<message not found>");

      &contentUrl = GenerateComponentContentURL(%Portal, %Node, MenuName.PORTAL_PERS_HOMEPAGE, &market, Component.PORTAL_HOMEPAGE, Page.PORTAL_HPCOMP, "") | "&tab=" | &tab;
      &layoutUrl = GenerateComponentContentURL(%Portal, %Node, MenuName.PORTAL_PERS_HOMEPAGE, &market, Component.PORTAL_HOMEPAGE, Page.PORTAL_HPLAYOUT, "") | "&tab=" | &tab;

      &contentOnClick = &refreshHomepageJS | ";";
      &layoutOnClick = &contentOnClick;
      If (&isAccessibilityMode) Then
         /* Open in target content */
         If (&isInAppLandingPage) Then
            &contentOnClick = &contentOnClick | genOpenInTargetScript(&contentUrl, &contentText);
            &layoutOnClick = &layoutOnClick | genOpenInTargetScript(&layoutUrl, &layoutText);
         End-If;
      Else
         /* Open in modal */
         If (&isInAppLandingPage) Then
            &contentOnClick = &contentOnClick | genOpenInModalScript(&contentUrl, "", 0, 0, "");
            &layoutOnClick = &layoutOnClick | genOpenInModalScript(&layoutUrl, "", 0, 0, "");
         Else
            &contentOnClick = &contentOnClick | " showModal('" | &contentUrl | "&ICModalJS=1', window,null,null,null,false,true); return false;";
            &layoutOnClick = &layoutOnClick | " showModal('" | &layoutUrl | "&ICModalJS=1', window,null,null,null,false,true); return false;";
         End-If;
      End-If;

      &perfHtml = GetHTMLText(HTML.PT_PORTAL_PERS_LINKS_MODAL, &persText, &contentUrl, &contentText, &layoutUrl, &layoutText, &contentOnClick, &layoutOnClick);

   End-If;


   /* Get the help link */
   &helpId = &dashboardObj.HelpID;
   If All(&helpId) Then

      &helpText = MsgGetText(95, 410, "Message not found.");

      If (&isAccessibilityMode) Then
         &helpAltText = "";
      Else
         &helpAltText = &helpText;
      End-If;

      &helpLinkHtml = GetHTMLText(HTML.PT_PORTAL_HPTAB_HELP_LINK_SWAN, %Request.GetHelpURL(&helpId), %Response.GetImageURL(Image.PT_HELP), &helpAltText, &helpText);

   End-If;


   /* Get the dashboard label */
   If (&dashboardObj.IsRenameable) Then

      &userTabObj = &portalObj.Homepage.UserTabs.ItemByName(&tab);

      If (All(&userTabObj)) Then
         &dashboardTitle = &userTabObj.Label;
      End-If;

   End-If;

   If None(&dashboardTitle) Then
      &dashboardTitle = &dashboardObj.Label;
   End-If;


   /* Close the Portal Object */
   &portalObj.close();


   /* Assemble the final HTML */
   &headerLinks = GetHTMLText(HTML.PORTAL_HP_LINKS, &perfHtml, &modifySysTabHtml, &helpLinkHtml, EscapeHTML(&dashboardTitle), &persLinksStyleClass);
   &headerLinks = GetHTMLText(HTML.PORTAL_HP_PERSONALIZE_LINKS, &headerLinks);


   /* Assemble the final HTML */
   &html = GetHTMLText(HTML.PTAL_DASHBOARD_HEADER, &headerLinks);

   %Response.Write(&html);

End-Function;

import PTAL_PAGE:*;
import PTAL_PAGE:UTILITY:*;
import PTPP_PORTAL:EXCEPTION:*;



Constant &YES = "Y";
Constant &NO = "N";



/**
  * Application Landing Page AJAX functions
  *
  */
Function IScript_PTAL_AJAX

   Local string &succeed = "true";
   Local string &type, &pageId, &portalName, &pageName, &pageletGroup, &pageletType, &pageletName, &minimized, &docked, &temp;
   Local boolean &found;
   Local array of string &arr;
   Local Record &rec, &rec1;

   Local PTAL_PAGE:PageFactory &pageFactory;
   Local PTAL_PAGE:UTILITY:Utility &utility;

   &pageFactory = create PTAL_PAGE:PageFactory();
   &utility = &pageFactory.Utility;

   &type = %Request.GetParameter(&utility.QUERYPARAMETER_AJAX_TYPE);
   &pageId = %Request.GetParameter(&utility.QUERYPARAMETER_PTAL_ID);

   &arr = &utility.pageIdToPageKeys(&pageId);
   &portalName = &arr [1];
   &pageName = &arr [2];

   &pageletGroup = %Request.GetParameter(&utility.QUERYPARAMETER_PAGELET_GROUP);
   &pageletType = %Request.GetParameter(&utility.QUERYPARAMETER_PAGELET_TYPE);
   &pageletName = %Request.GetParameter(&utility.QUERYPARAMETER_PAGELET_OBJNAME);
   &minimized = %Request.GetParameter(&utility.QUERYPARAMETER_MINIMIZED);
   &docked = %Request.GetParameter(&utility.QUERYPARAMETER_DOCKED);

   &temp = "";
   SQLExec(SQL.PTAL_CHECK_BY_PAGE_KEYS, &portalName, &pageName, &temp);
   If None(&temp) Then
      /* Page definition not found */
      &succeed = "false";

   Else
      /* save the information as user personalization data */
      Evaluate &type
      When &utility.QUERYPARAMETER_AJAX_TYPE_PAGE

         /* Page personalization data */
         &rec = CreateRecord(Record.PTAL_UP_PAGE);
         &rec.PORTAL_NAME.Value = &portalName;
         &rec.PORTAL_OBJNAME.Value = &pageName;
         &rec.OPRID.Value = %UserId;

         &found = &rec.SelectByKey();

         /* Fill in the data */
         &rec.PORTAL_NAME.Value = &portalName;
         &rec.PORTAL_OBJNAME.Value = &pageName;
         &rec.OPRID.Value = %UserId;

         Evaluate &minimized
         When "1"
            &rec.PTAL_MINIMIZED.Value = &YES;
            Break;

         When "0"
            &rec.PTAL_MINIMIZED.Value = &NO;
            Break;

         End-Evaluate;

         Evaluate &docked
         When "1"
            &rec.PTAL_DOCKED.Value = &YES;
            Break;

         When "0"
            &rec.PTAL_DOCKED.Value = &NO;
            Break;
         End-Evaluate;

         /* Save the data */
         If &found Then
            &rec.Update();
         Else
            &rec.Insert();
         End-If;

         Break;
         /* End of Page personalization data */


      When &utility.QUERYPARAMETER_AJAX_TYPE_PAGELET

         /* Pagelet personalization data */

         /* Get pagelet data */
         &rec1 = CreateRecord(Record.PTAL_PAGELET);
         &rec1.PORTAL_NAME.Value = &portalName;
         &rec1.PORTAL_OBJNAME.Value = &pageName;
         &rec1.PTAL_PGLT_GROUPID.Value = &pageletGroup;
         &rec1.PTAL_PGLT_TYPE.Value = &pageletType;
         &rec1.PTAL_PGLT_OBJNAME.Value = &pageletName;

         If (&rec1.SelectByKey()) Then

            /* Get personalization data */
            &rec = CreateRecord(Record.PTAL_UP_PAGELET);
            &rec.PORTAL_NAME.Value = &portalName;
            &rec.PORTAL_OBJNAME.Value = &pageName;
            &rec.PTAL_PGLT_GROUPID.Value = &pageletGroup;
            &rec.PTAL_PGLT_TYPE.Value = &pageletType;
            &rec.PTAL_PGLT_OBJNAME.Value = &pageletName;
            &rec.OPRID.Value = %UserId;

            &found = &rec.SelectByKey();

            /* Fill in the data */
            &rec.PORTAL_NAME.Value = &portalName;
            &rec.PORTAL_OBJNAME.Value = &pageName;
            &rec.PTAL_PGLT_GROUPID.Value = &pageletGroup;
            &rec.PTAL_PGLT_TYPE.Value = &pageletType;
            &rec.PTAL_PGLT_OBJNAME.Value = &pageletName;
            &rec.OPRID.Value = %UserId;

            If Not &found Then
               &rec.PTAL_SELECTED.Value = &YES;
               &rec.DISPLAY_ORDER.Value = &rec1.DISPLAY_ORDER.Value;
            End-If;

            Evaluate &minimized
            When "1"
               &rec.PTAL_MINIMIZED.Value = &YES;
               Break;

            When "0"
               &rec.PTAL_MINIMIZED.Value = &NO;
               Break;

            End-Evaluate;

            /* Save the data */
            If &found Then
               &rec.Update();
            Else
               &rec.Insert();
            End-If;

         End-If;

         Break;
         /* End of Pagelet personalization data */

      When-Other;
         &succeed = "false";
         Break;

      End-Evaluate;
   End-If;

   %Response.Write(&succeed);

End-Function;

