Constant &QUERYPARAMETER_MODE_TILE = "tile";



/**
  * Get the HTML Object as JavaScript file
  *
  */
Function IScript_GET_JS

   Local string &url, &content, &Id;

   /* Get the id */
   &Id = %Request.GetParameter(&QUERYPARAMETER_ID);

   If All(&Id) Then
      &url = %Response.GetJavaScriptURL(@("HTML." | &Id));
      If All(&url) Then
         %Response.SetContentType("text/javascript");
         %Response.RedirectURL(&url);
      End-If;
      <*
      &content = GetHTMLText(@("HTML." | &Id));
      %Response.SetContentType("text/javascript");
      %Response.Write(&content);
      *>
   End-If;

End-Function;



/**
  * Get the Style Sheet file
  *
  */
Function IScript_GET_CSS

   Local string &url, &content, &Id;
   Local boolean &result;
   rem Local PT_METADATA:StylesheetDefn &objStyleDefn;

   /* Get the id */
   &Id = %Request.GetParameter(&QUERYPARAMETER_ID);

   If All(&Id) Then
      &url = %Response.GetStyleSheetURL(@("StyleSheet." | &Id));
      If All(&url) Then
         %Response.SetContentType("text/css");
         %Response.RedirectURL(&url);
      End-If;
      <*
      try
         &objStyleDefn = create PT_METADATA:StylesheetDefn(&Id);
         &result = &objStyleDefn.Open();
         If (&result) Then
            &content = &objStyleDefn.ExtStyleSheetStr;
            %Response.SetContentType("text/css");
            %Response.Write(&content);
         End-If;
      catch Exception &e;
      end-try;
      *>
   End-If;

End-Function;



/**
  * Generate the URL to show remote images
  *
  */
Function generateImageUrl(&pNodeName As string, &pPortalName As string, &pImageName As string) Returns string

   Local string &url;

   &url = GenerateScriptContentURL(&pPortalName, &pNodeName, Record.WEBLIB_PTBR, Field.ISCRIPT1, "FieldFormula", "IScript_GET_IMAGE");
   If (Find("?", &url) > 0) Then
      &url = &url | "&";
   Else
      &url = &url | "?";
   End-If;
   &url = &url | &QUERYPARAMETER_ID | "=" | EscapeHTML(&pImageName);

   Return &url;

End-Function;



/**
  * Generate the URL to show custom pre-loading images for remote tiles
  *
  */
Function generateTileImageUrl(&pNodeName As string, &pPortalName As string, &pImageName As string, &pImageAltText As string) Returns string

   Local string &url;

   &url = generateImageUrl(&pNodeName, &pPortalName, &pImageName);
   &url = &url | "&" | &QUERYPARAMETER_MODE | "=" | &QUERYPARAMETER_MODE_TILE;
   &url = &url | "&" | &QUERYPARAMETER_ALT_TEXT | "=" | /*EscapeHTML(&pImageAltText)*/&pImageAltText; /* when there ' in tile label image is not fetched on portal*/

   Return &url;

End-Function;



/**
  * Get the Image file
  *
  */
Function IScript_GET_IMAGE

   Local string &url, &Id;
   Local string &mode, &alt, &html;

   /* Get the id */
   &Id = %Request.GetParameter(&QUERYPARAMETER_ID);
   &mode = %Request.GetParameter(&QUERYPARAMETER_MODE);
   &alt = %Request.GetParameter(&QUERYPARAMETER_ALT_TEXT);

   &html = "";

   If All(&Id) Then
      &url = %Response.GetImageURL(@("Image." | &Id));
      If All(&url) Then

         Evaluate &mode
         When &QUERYPARAMETER_MODE_TILE
            &html = GetHTMLText(HTML.PTBR_ELM_IMAGE, EscapeHTML(&Id), "ps_process", EscapeHTML(&alt), EscapeHTML(&url));
            Break;

         When-Other
            %Response.RedirectURL(&url);

         End-Evaluate;

      End-If;
   End-If;

   %Response.Write(&html);

End-Function;



