/**
  * Get the Theme Style Sheet
  *
  */
Function IScript_ThemeStyleSheet

   Local string &content, &themeCSS, &themeCSSURL, &themeCSSContent, &skinCSS, &skinCSSURL, &skinCSSContent;
   Local boolean &result;

   Local PT_METADATA:StylesheetDefn &themeStyleDefnObj, &skinStyleDefnObj;

   Local PTBR_BRANDING:BrandingManager &mgrObj;
   Local PTBR_BRANDING:Themes:ThemeAssignment &taObj;
   Local PTBR_BRANDING:Themes:ThemeTemplate &themeObj;


   /* Get the current theme assignment data */
   &mgrObj = getBrandingManager();
   &taObj = &mgrObj.getCurrentThemeAssignmentForPortal(%Portal);
   &themeObj = &taObj.getThemeObject();

   &themeCSS = &themeObj.ThemeStyleSheetName;
   If All(&themeCSS) Then
      &themeCSSURL = %Response.GetStyleSheetURL(@("StyleSheet." | &themeCSS));
   End-If;

   &skinCSS = &taObj.SkinStyleSheetName;
   If All(&skinCSS) Then
      &skinCSSURL = %Response.GetStyleSheetURL(@("StyleSheet." | &skinCSS));
   End-If;

   %Response.SetContentType("text/css");

   /* Check the styles */
   If (All(&themeCSS) And
         None(&skinCSS)) Then
      %Response.RedirectURL(&themeCSSURL);
      Return;
   End-If;


   If (None(&themeCSS) And
         All(&skinCSS)) Then
      %Response.RedirectURL(&skinCSSURL);
      Return;
   End-If;


   If All(&themeCSS) Then
      try
         &themeStyleDefnObj = create PT_METADATA:StylesheetDefn(&themeCSS);
         &result = &themeStyleDefnObj.OpenReadOnly();
         If (&result) Then
            &themeCSSContent = &themeStyleDefnObj.ExtStyleSheetStr;
         End-If;
      catch Exception &e1;
         &themeCSSContent = &e1.ToString( False);
      end-try;
   End-If;

   If All(&skinCSS) Then
      try
         &skinStyleDefnObj = create PT_METADATA:StylesheetDefn(&skinCSS);
         &result = &skinStyleDefnObj.OpenReadOnly();
         If (&result) Then
            &skinCSSContent = &skinStyleDefnObj.ExtStyleSheetStr;
         End-If;
      catch Exception &e2;
         &skinCSSContent = &e2.ToString( False);
      end-try;
   End-If;

   &content = GetHTMLText(HTML.PTBR_THEME_CSS_CONTENTS, &themeCSS, &themeCSSContent, &skinCSS, &skinCSSContent);

   %Response.Write(&content);

End-Function;



/**
  * Get the Start Page to show to users upon login
  *
  */
Function IScript_StartPage

   Local boolean &isOldFramework;
   Local string &url, &mode, &appPkg;

   Local PTBR_BRANDING:UTILITY:ThemeAssignmentCookie &tacObj;

   /* Check whether the old framework is in use */
   SQLExec("SELECT PACKAGEROOT FROM PSOPTIONS", &appPkg);
   &isOldFramework = (&appPkg = "PT_BRANDING");

   If ( Not &isOldFramework) Then
      /* set the theme assignment cookie */
      &tacObj = setThemeCookieForPortal(%Portal);
   End-If;

   /* Get the URL */
   &url = Unencode(%Request.GetParameter(&QUERYPARAMETER_URL));
   &mode = %Request.GetParameter(&QUERYPARAMETER_HP_MODE);


   If (All(&url)) Then
      /* Check that redirected URL is too the same server*/
      Local string &ServerName;
      Local number &serverNameURL, &portNum, &serverNamePSPURL, &serverNamePSCURL;
      &serverNamePSCURL = Find("/psc/", &url, 1);
      &serverNamePSPURL = Find("/psp/", &url, 1);

      If (&serverNamePSCURL > 0) Then
         &serverNameURL = &serverNamePSCURL;
      End-If;

      If (&serverNamePSPURL > 0) Then
         &serverNameURL = &serverNamePSPURL;
      End-If;
      If (&serverNamePSPURL > 0 And
            &serverNamePSCURL > 0) Then
         If (&serverNamePSCURL > &serverNamePSPURL) Then
            &serverNameURL = &serverNamePSPURL;
         Else
            &serverNameURL = &serverNamePSCURL;
         End-If;
      End-If;


      If (&serverNameURL > 0) Then
         &ServerName = Substring(&url, 0, &serverNameURL);
         rem Remove http:// or https://;
         &portNum = Find("://", &ServerName, 1);
         If (&portNum > 0) Then
            rem Extract the Servername;
            &ServerName = Substring(&ServerName, &portNum + 3, Len(&ServerName));
            rem Get the Port number;
            &portNum = Find(":", &ServerName, 1);
            If (&portNum > 0) Then
               &ServerName = Substring(&ServerName, 0, &portNum - 1);
            Else
               &slashNum = Find("/", &ServerName, 1);
               If (&slashNum > 0) Then
                  &ServerName = Substring(&ServerName, 0, &slashNum - 1);
               End-If;
            End-If;
         End-If;
      End-If;

      Local string &CalledServerName = %Request.ServerName;
      If &ServerName <> &CalledServerName Then
         &url = "";
      End-If;
   End-If;

   &PTNUI_CurrentTab = "";

   If None(&url) Then
      If (&isOldFramework) Then
         &url = GetPortalHomepageURL();
      Else
         Evaluate &mode
         When &QUERYPARAMETERVALUE_HP_MODE_CLASSIC
            &url = getClassicHomepageURLForPortal(%Portal);
            Break;
         When &QUERYPARAMETERVALUE_HP_MODE_FLUID
            &url = getFluidHomepageURLForPortal(%Portal);
            Break;
         When-Other
            &url = getHomepageURLForPortal(%Portal);
         End-Evaluate;
      End-If;
   End-If;

   If (All(&url)) Then
      /* enforce a HTTP 302 redirect */
      If (Find("?", &url) = 0) Then
         &url = &url | "?";
      Else
         &url = &url | "&";
      End-If;
      &url = &url | "httpredirect=true";

      %Response.RedirectURL(&url);
   Else
      Error MsgGet(219, 7438, "No start page found");
   End-If;

End-Function;

