/*Dynamic template html for frame based CXM template*/
Function IScript_PTCXM_TPL_FRAME
   Local string &LNSrcURL, &params, &pourl, &navTitleText, &contentTitleText, &headerTitleText;
   Local string &encryptedUserId = EncodeURLForQueryString(Encrypt("", %UserId | %Language));

   &LNSrcURL = LNSrcInFrame();
   If Find("?", &LNSrcURL) = 0 Then
      &LNSrcURL = &LNSrcURL | "?";
   Else
      &LNSrcURL = &LNSrcURL | "&";
   End-If;

   &params = "&PortalKeyStruct=yes";
   &pourl = %Request.GetHeader("portalactualurl");
   If All(&pourl) Then
      &params = "";
   End-If;

   &navTitleText = MsgGetText(240, 10, "Message not Found");
   &contentTitleText = MsgGetText(240, 11, "Message not Found");
   &headerTitleText = MsgGetText(240, 12, "Message not Found");

   &Access = GetUserOption("PPTL", "ACCESS");
   &HideNav = %Request.GetParameter("h");
   If (&HideNav = "") Then
      &HideNav = GetUserOption("PPTL", "AUTOMENU");
   End-If;
   Local string &ptcxmStylesheet = %Response.GetStyleSheetURL(StyleSheet.PTCXMSTYLEDEF);
   &navPortal = create PT_NAV:NavPortal("IScript_UniHeader_Frame");
   &navTheme = create PT_NAV:NavTheme(&navPortal);
   &rows = &navPortal.GetHeaderFrameRows();

   If %Request.BrowserType = "IE" Then
      If (&HideNav = "Y") Then
         If (&Access = "A") Then
            %Response.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_COLLAPSE_ACC, &encryptedUserId, &params, &headerTitleText, &contentTitleText, &rows));
         Else
            %Response.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_COLLAPSE, &LNSrcURL, &params, &encryptedUserId, "", &navTitleText, &contentTitleText, &headerTitleText, &rows));
         End-If;
      Else
         %Response.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_EXPAND, &LNSrcURL, &params, &encryptedUserId, "", &navTitleText, &contentTitleText, &headerTitleText, &rows, &ptcxmStylesheet));
      End-If;
   Else
      If (&HideNav = "Y") Then
         If (&Access = "A") Then
            %Response.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_COLLAPSE_ACC, &encryptedUserId, &params, &headerTitleText, &contentTitleText, &rows));
         Else
            %Response.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_COLLAPSE, &LNSrcURL, &params, &encryptedUserId, "", &navTitleText, &contentTitleText, &headerTitleText, &rows));
         End-If;
      Else
         Local string &navExpandJS = %Response.GetJavaScriptURL(HTML.PTCXM_NAVEXPAND_JS);
         %Response.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_EXPAND_NS, &LNSrcURL, &params, &encryptedUserId, "", &navTitleText, &contentTitleText, &headerTitleText, &rows, &ptcxmStylesheet, &navExpandJS));
      End-If;
   End-If;
End-Function;

