Function CallAppClass(&CLASS_STR As string) Returns boolean;
   Local object &cobject;
   Local string &PACKAGENAME, &CLASSNAME, &CLASSPARM, &METHODNAME, &METHODPARM;
   Local string &WRK1, &WRK2;
   Local number &Sep1, &Sep2;
   Local number &ClassParmsStart = 0;
   Local number &ClassParmsEnd = 0;
   Local number &MethodParmsStart = 0;
   Local number &MethodParmsEnd = 0;

   &Sep1 = Find(":", &CLASS_STR);
   &Sep2 = Find(":", &CLASS_STR, &Sep1 + 1);
   If (&Sep1 = 0 Or
         &Sep2 = 0) Then
      Return False; /* Invalid */
   End-If;

   &ClassParmsStart = Find("(""", &CLASS_STR, &Sep1);
   If &ClassParmsStart > 0 And
         &ClassParmsStart < &Sep2 Then
      &ClassParmsStart = &ClassParmsStart + 2;
      &ClassParmsEnd = Find(""")", &CLASS_STR, &ClassParmsStart);
      If &ClassParmsEnd > 0 Then
         &ClassParmsEnd = &ClassParmsEnd - 1;
         If &ClassParmsEnd > &Sep2 Then
            &Sep2 = Find(":", &CLASS_STR, &ClassParmsEnd);
            If &Sep2 = 0 Then
               Return False; /* invalid - no sep 2 found after class parms */
            End-If;
         End-If;
      Else
         Return False; /* invalid - no end quote for classparms */
      End-If;
   Else
      &ClassParmsStart = 0;
   End-If;

   &MethodParmsStart = Find("(""", &CLASS_STR, &Sep2);
   If &MethodParmsStart > 0 Then
      &MethodParmsStart = &MethodParmsStart + 2;
      &MethodParmsEnd = Find(""")", &CLASS_STR, &MethodParmsStart);
      If &MethodParmsEnd > 0 Then
         &MethodParmsEnd = &MethodParmsEnd - 1;
      Else
         Return False; /* invalid - no end quote for methodparms */
      End-If;
   Else
      &MethodParmsStart = 0;
   End-If;

   &PACKAGENAME = Substring(&CLASS_STR, 1, &Sep1 - 1);
   If &ClassParmsStart > 0 Then
      &CLASSNAME = Substring(&CLASS_STR, &Sep1 + 1, &ClassParmsStart - &Sep1 - 3);
      &CLASSPARM = Substring(&CLASS_STR, &ClassParmsStart, &ClassParmsEnd - &ClassParmsStart + 1)
   Else
      &CLASSNAME = Substring(&CLASS_STR, &Sep1 + 1, &Sep2 - &Sep1 - 1);
      &CLASSPARM = "";
   End-If;
   If &MethodParmsStart > 0 Then
      &METHODNAME = Substring(&CLASS_STR, &Sep2 + 1, &MethodParmsStart - &Sep2 - 3);
      &METHODPARM = Substring(&CLASS_STR, &MethodParmsStart, &MethodParmsEnd - &MethodParmsStart + 1)
   Else
      &METHODNAME = Substring(&CLASS_STR, &Sep2 + 1, Len(&CLASS_STR) - &Sep2);
      &METHODPARM = "";
   End-If;

   If &CLASSPARM = "" Then
      &cobject = CreateObject(&PACKAGENAME | ":" | &CLASSNAME);
   Else
      &cobject = CreateObject(&PACKAGENAME | ":" | &CLASSNAME, &CLASSPARM);
   End-If;

   If &METHODPARM = "" Then
      ObjectDoMethod(&cobject, &METHODNAME);
   Else
      ObjectDoMethod(&cobject, &METHODNAME, &METHODPARM);
   End-If;
   Return True;

End-Function;

rem  --- PA89 separate processing for menu pagelet;
Function GetMenuParameters(&MenuObj As ApiObject, &MenuUrl As string) Returns string;
   Local array of string &AllParms, &ParmValues;
   Local boolean &firstParm;
   Local string &paramName, &separator, &tempCrefurl;
   Local number &k, &j;

   &AllParms = %Request.GetParameterNames();
   &firstParm = True;

   For &j = 1 To &AllParms.Len
      &paramName = EscapeHTML(&AllParms [&j]);
      &ParmValues = %Request.GetParameterValues(&AllParms [&j]);

      rem  --- PRJ129169  Related Links Fix, PortalContentURL problem;
      If Left(&paramName, 16) = "PortalContentURL" Then
         For &k = 1 To &ParmValues.Len

            rem &tempCrefurl = &MenuObj.AbsolutePortalURL;
            &tempCrefurl = &MenuObj.AbsoluteContentURL;

            If (&firstParm) Then
               &separator = "?";
               &firstParm = False;
            Else
               &separator = "&";
            End-If;
            &MenuUrl = &MenuUrl | &separator | &paramName | "=" | EncodeURLForQueryString(&tempCrefurl);
         End-For;
      Else
         rem  --- do not append ptcxm params;
         If (0 = Find("PTCXM", &paramName)) And
               (0 = Find("PS.", &paramName)) Then
            For &k = 1 To &ParmValues.Len
               If (&firstParm) Then
                  &separator = "?";
                  &firstParm = False;
               Else
                  &separator = "&";
               End-If;
               &MenuUrl = &MenuUrl | &separator | &paramName | "=" | EncodeURLForQueryString(EscapeHTML(&ParmValues [&k]));
            End-For;
         End-If;

      End-If;
   End-For;

   Return &MenuUrl;

End-Function;

/* PA89 - Check to see if a tp's url is in the login list */
Function isURLinLoginList(&url As string) Returns boolean

   /* Split the url on "/" */
   Local array of string &urlarray = Split(&url, "/");

   /* Now assemble the url as it would appear in the PS_LOGINLIST */
   Local string &urltofind = &urlarray [1] | "//" | &urlarray [3] | "/" | &urlarray [5];

   /* Now see if the url is in the PS_LOGINLIST */
   If Find(Upper(&urltofind), Upper(%Request.GetCookieValue("PS_LOGINLIST"))) > 0 Then
      Return True;
   End-If;

   Return False;
End-Function;

Function Iscript_MinMax()
   Local string &PSMIN, &PSMAX;
   Local number &TESTPOS;
   rem  --- carry pagelet min/max flag;
   &PSMIN = %Request.GetParameter("PS.MIN");
   &PSMAX = %Request.GetParameter("PS.MAX");
   If All(&PSMIN) Then
      If Find(&PSMIN | ";", &PTCXM_MIN) = 0 Then
         &PTCXM_MIN = &PTCXM_MIN | &PSMIN | ";";
      End-If;
      &TESTPOS = Find(&PSMIN | ";", &PTCXM_MAX);
      If &TESTPOS <> 0 Then
         &PTCXM_MAX = Left(&PTCXM_MAX, &TESTPOS - 1) | Right(&PTCXM_MAX, (Len(&PTCXM_MAX) - Len(&PSMIN | ";") - &TESTPOS + 1));
      End-If;
   End-If;
   If All(&PSMAX) Then
      If Find(&PSMAX | ";", &PTCXM_MAX) = 0 Then
         &PTCXM_MAX = &PTCXM_MAX | &PSMAX | ";";
      End-If;
      &TESTPOS = Find(&PSMAX | ";", &PTCXM_MIN);
      If &TESTPOS <> 0 Then
         &PTCXM_MIN = Left(&PTCXM_MIN, &TESTPOS - 1) | Right(&PTCXM_MIN, (Len(&PTCXM_MIN) - Len(&PSMAX | ";") - &TESTPOS + 1));
      End-If;
   End-If;

End-Function;

/* Context Manager */
Function IScript_PTCXM_Manager()

   Local ApiObject &MyPortal, &CREF, &CrefForPermTest, &TP_CREF, &TP_ATTRCOL, &TP_ATTR;
   Local object &BrandingObj;
   Local Rowset &RS1, &RS2;
   Local boolean &Checkflag, &ret;
   Local array of string &KEYLIST, &aTemplate, &AllParms, &ParmValues;
   Local boolean &TPValid, &MINIMIZED, &INVIS, &firstParm;
   Local string &PSMIN, &PSMAX, &PtcxmCref, &PortalContentUrl, &sLinkForPermTest, &ccurl, &paramTemp, &tempCrefurl;
   Local string &add_remove_text, &sHasContentFlag, &add_remove_link, &add_remove_html, &KeyParams;
   Local string &TCURL, &START, &JSHTML, &LN_OBJLABEL, &LN_OBJNAME, &CLASS_STR, &pageletXml;
   Local string &PgltStyleSheetURL, &temp, &ptcxmStylesheetURL;
   Local number &TESTPOS, &TABLEWIDTH, &i, &k, &j;
   Local string &ptcxmReqKeys, &paramName;
   Local string &ptcxmNewFolderURL, &ptcxmLnParams, &jsdomain;
   Local string &ptcxmXferStopFlag = "Y";
   Local boolean &is850Menu = False; /* special onload handling for the 8.50 nav */

   %Response.UseSimpleURL( True);
   &temp = %Request.GetParameter("mode");
   &MyPortal = PortalOpen();
   &TPResponse = create PTCXM_TEMPLATE_PAGELET:TPResponse();

   rem  --- carry pagelet min/max flag;
   &PSMIN = %Request.GetParameter("PS.MIN");
   &PSMAX = %Request.GetParameter("PS.MAX");
   If All(&PSMIN) Then
      If Find(&PSMIN | ";", &PTCXM_MIN) = 0 Then
         &PTCXM_MIN = &PTCXM_MIN | &PSMIN | ";";
      End-If;
      &TESTPOS = Find(&PSMIN | ";", &PTCXM_MAX);
      If &TESTPOS <> 0 Then
         &PTCXM_MAX = Left(&PTCXM_MAX, &TESTPOS - 1) | Right(&PTCXM_MAX, (Len(&PTCXM_MAX) - Len(&PSMIN | ";") - &TESTPOS + 1));
      End-If;
   End-If;
   If All(&PSMAX) Then
      If Find(&PSMAX | ";", &PTCXM_MAX) = 0 Then
         &PTCXM_MAX = &PTCXM_MAX | &PSMAX | ";";
      End-If;
      &TESTPOS = Find(&PSMAX | ";", &PTCXM_MIN);
      If &TESTPOS <> 0 Then
         &PTCXM_MIN = Left(&PTCXM_MIN, &TESTPOS - 1) | Right(&PTCXM_MIN, (Len(&PTCXM_MIN) - Len(&PSMAX | ";") - &TESTPOS + 1));
      End-If;
   End-If;

   If &TPResponse.isNS4x() Then
      &TABLEWIDTH = 172;
   Else
      &TABLEWIDTH = 178;
   End-If;

   &PtcxmCref = %Request.GetParameter("PTCXM.TCCREF");
   If All(&PtcxmCref) Then
      &CREF = &MyPortal.FindCREFByName(&PtcxmCref);
   End-If;

   If None(&CREF) Then
      &PortalContentUrl = %Request.GetParameter("PortalContentURL");
      If All(&PortalContentUrl) Then
         &CREF = &MyPortal.FindCREFByurl(&PortalContentUrl);
      End-If;
   End-If;

   If None(&CREF) Then
      &CREF = &MyPortal.RootFolder;
   End-If;

   rem  --- generate administer pagelets link;
   &sLinkForPermTest = GenerateComponentPortalURL(%Portal, %Node, MenuName.PTCXM_PORTAL_ADMIN, "GBL", Component.PTCXM_DISPLAY, "", "");
   &CrefForPermTest = &MyPortal.FindCREFByURL(&sLinkForPermTest);
   If (&CrefForPermTest.Authorized) And
         &CREF.NAME <> &MyPortal.RootFolder.NAME Then
      &add_remove_text = MsgGetText(240, 8, "Message not Found");
      SQLExec(SQL.PTCXM_HAS_LN_CONTENT, Record.PTCXM_DISPLAY, &MyPortal.Name, &CREF.Name, &sHasContentFlag);
      If All(&sHasContentFlag) Then
         &add_remove_link = GenerateComponentPortalURL(%Portal, %Node, MenuName.PTCXM_PORTAL_ADMIN, "GBL", Component.PTCXM_DISPLAY, Page.PTCXM_DISPLAY, "") | "&PORTAL_NAME=" | &MyPortal.Name | "&PORTAL_OBJNAME=" | &CREF.Name | &KeyParams;
      Else
         &add_remove_link = GenerateComponentPortalURL(%Portal, %Node, MenuName.PTCXM_PORTAL_ADMIN, "GBL", Component.PTCXM_DISPLAY, Page.PTCXM_DISPLAY, "a") | "&PORTAL_NAME=" | &MyPortal.Name | "&PORTAL_OBJNAME=" | &CREF.Name | &KeyParams;
      End-If;
      &add_remove_html = GetHTMLText(HTML.PTCXM_ADD_REMOVE, &add_remove_link, &add_remove_text, &TABLEWIDTH);
   Else
      &add_remove_html = "";
   End-If;

   rem  --- find template pagelets/keys;
   &aTemplate = CreateArrayRept("", 0);
   &RS1 = CreateRowset(Record.PTCXM_DISPLAY);
   &RS2 = CreateRowset(Record.PTCXM_KEYSTRUCT);
   &KEYLIST = CreateArrayRept("", 0);
   &RS1.Flush();
   &RS1.Fill("WHERE PORTAL_NAME=:1 AND PORTAL_OBJNAME=:2", &MyPortal.name, &CREF.name);
   &RS1.Sort(PTCXM_DISPLAY.SEQNUM, "A");
   If (&RS1.GetRow(1).PTCXM_DISPLAY.PTCXM_OBJNAME.Value = "") Then
      &RS1.Flush();
      &RS1.Fill("WHERE PORTAL_NAME=:1 AND PORTAL_OBJNAME=:2", &MyPortal.name, &MyPortal.RootFolder.name);
      &RS1.Sort(PTCXM_DISPLAY.SEQNUM, "A");
   End-If;

   rem --- Modification for CXM Transfer post 8.8;
   If (&RS1(1).PTCXM_DISPLAY.PTCXM_TRANS_ATTR.Value = "Y") Then
      &ptcxmXferStopFlag = "N";
   End-If;

   If &TPResponse.isNS6x() Then
      Local string &CrossDomainJavascriptUrl = %Response.GetJavaScriptURL("PT_ISCROSSDOMAINNS6");
   Else
      &CrossDomainJavascriptUrl = %Response.GetJavaScriptURL("PT_ISCROSSDOMAIN");
   End-If;

   &jsdomain = SetDocDomainToAuthTokenDomain();

   If &RS1.GetRow(1).PTCXM_DISPLAY.PTCXM_OBJNAME.Value <> "" Then
      For &i = 1 To &RS1.ActiveRowCount
         &LN_OBJNAME = &RS1.GetRow(&i).PTCXM_DISPLAY.PTCXM_OBJNAME.Value;
         &TP_CREF = &MyPortal.FindCREFByName(&LN_OBJNAME);
         If &TP_CREF.Authorized Then
            rem  --- Check ValidFrom and ToDate;
            &TPValid = False;
            If All(&TP_CREF) Then
               If &TP_CREF.ValidFrom <= %Date And
                     (&TP_CREF.ValidTo = "" Or
                        &TP_CREF.ValidTo >= %Date) Then
                  &TPValid = True;
               End-If;
            End-If;

            /* Check attributes */
            If &TPValid Then
               &INVIS = False;
               &CLASS_STR = "";
               &TP_ATTRCOL = &TP_CREF.ATTRIBUTES;
               If All(&TP_ATTRCOL) Then
                  If (&TP_ATTRCOL.COUNT > 0) Then
                     /* Check Invisibility */
                     &TP_ATTR = &TP_ATTRCOL.ITEMBYNAME("CANBEINVISIBLE");
                     If All(&TP_ATTR) Then
                        If (&TP_ATTR.VALUE = "TRUE") Then
                           &INVIS = True;
                        End-If;
                     End-If;
                     /* Check for direct app class call */
                     &TP_ATTR = &TP_ATTRCOL.ITEMBYNAME("CLASS_STR");
                     If All(&TP_ATTR) Then
                        &CLASS_STR = &TP_ATTR.value;
                     End-If;
                  End-If;
               End-If;

               REM Check for 8.50 menu pagelet for special onload handling;
               If &TP_CREF.Name = "AJAX_MENU_TEMPLATE_PGLT" Then
                  &is850Menu = True;
               End-If;

               /* Generate the template pagelet URL */
               &ccurl = "";
               If &TP_CREF.URLType = "UEXT" Then
                  &ccurl = &TP_CREF.URL;
               Else
                  rem  --- PA89 update;
                  rem  --- &ccurl = &TP_CREF.QualifiedURL;
                  &ccurl = &TP_CREF.AbsoluteContentURL;
               End-If;

               REM --- PA89 handle single signon race condition;
               If %Request.GetParameter("PTCXMReload") <> "true" Then
                  If &CREF.urltype <> "UEXT" Then
                     If &CREF.contentprovider = &TP_CREF.contentprovider And
                           &CREF.contentprovider <> "" Then
                        If Not isURLinLoginList(&ccurl) Then
                           /* pagelet is from same node as TC, and signon has not occurred.  stop processing
                        prematurely and write out code to wait on the target page */
                           &JSHTML = GetHTMLText(HTML.PTCXM_MGR_JS, %Response.GetJavaScriptURL(HTML.PTCXM_MANAGER_JS_WAIT), &CrossDomainJavascriptUrl, %Response.GetJavaScriptURL(HTML.PT_SAVEWARNINGSCRIPT), %Response.GetJavaScriptURL(HTML.PT_NAV_KEYHANDLER), %Response.GetJavaScriptURL(HTML.PT_NAV_SCRIPT), %Response.GetJavaScriptURL(HTML.PT_NAV_INFRAME_SCRIPT));
                           If ((%Request.BrowserType = "IE") Or
                                 (%Request.BrowserType = "OPERA")) And
                                 (Substring(%Request.BrowserPlatform, 1, 3) = "MAC") Then;
                              %Response.Write(GetHTMLText(HTML.PTCXM_MGR_TEMPLATE_START_NO, "", "", "JavaScript:start_ptcxm()", &JSHTML, &jsdomain));
                           Else
                              %Response.Write(GetHTMLText(HTML.PTCXM_MGR_TEMPLATE_START, "", "", "JavaScript:start_ptcxm()", &JSHTML, &jsdomain));
                           End-If;
                           %Response.Write(GetHTMLText(HTML.PTCXM_MGR_TEMPLATE_END));
                           Return;
                        End-If;
                     End-If;
                  End-If;
               End-If;

               rem  --- PA89 separate processing for menu pagelet;
               If &TPResponse.isMenu(&LN_OBJNAME) Then
                  &ccurl = GetMenuParameters(&CREF, &ccurl);
               Else
                  &AllParms = %Request.GetParameterNames();

                  If Find("?", &ccurl) = 0 Then
                     &ccurl = &ccurl | "?target=" | &LN_OBJNAME;
                  Else
                     &ccurl = &ccurl | "&target=" | &LN_OBJNAME;
                  End-If;

                  &paramTemp = EscapeHTML(%Request.GetParameter("PortalRegistryName"));
                  If All(&paramTemp) Then
                     &ccurl = &ccurl | "&PortalRegistryName=" | &paramTemp;
                  End-If;

                  &ccurl = &ccurl | "&PTCXM.TPCREF=" | &LN_OBJNAME | "&PTCXM.TCCREF=" | &CREF.name;

                  For &j = 1 To &AllParms.Len
                     &paramName = EscapeHTML(&AllParms [&j]);
                     &ParmValues = %Request.GetParameterValues(&AllParms [&j]);
                     If Left(&paramName, 11) = "PortalPTCXM" Then
                        For &k = 1 To &ParmValues.Len
                           &ccurl = &ccurl | "&" | &paramName | "=" | EncodeURLForQueryString(EscapeHTML(&ParmValues [&k]));
                        End-For;
                     Else
                        rem  --- PRJ129169  Related Links Fix, PortalContentURL problem;
                        If Left(&paramName, 16) = "PortalContentURL" Then
                           For &k = 1 To &ParmValues.Len
                              rem &tempCrefurl = &CREF.AbsolutePortalURL;
                              &tempCrefurl = &CREF.AbsoluteContentURL;
                              &ccurl = &ccurl | "&" | &paramName | "=" | EncodeURLForQueryString(&tempCrefurl);
                           End-For;
                        End-If;
                     End-If;
                  End-For;

                  &ccurl = &ccurl | "&PortalIsPagelet=true#";

               End-If /* end of pagelet params */;

               /* Check minimization */
               &MINIMIZED = &TPResponse.isPageletMinimized(&LN_OBJNAME);

               /* Now generate the XML for page assembly and append to templatehtml*/
               &LN_OBJLABEL = &TP_CREF.Label;
               If (&MINIMIZED = True) Then
                  &divstring = "class=""ptcxmminpglt""";
               Else
                  &divstring = "class=""ptcxmmaxpglt""";
               End-If;
               &pageletXml = GetHTMLText(HTML.PTCXM_TEMPLATEXML, &LN_OBJLABEL, &ccurl, &LN_OBJNAME, &divstring);

               If (&INVIS) Then
                  If &CLASS_STR = "" Then
                     &aTemplate.Push(&pageletXml);
                  Else
                     &aTemplate.Push("<CLASS>" | &CLASS_STR);
                     &aTemplate.Push("");
                     &aTemplate.Push(&LN_OBJNAME);
                  End-If;
               Else
                  If &CLASS_STR = "" Or
                        &MINIMIZED Then
                     &aTemplate.Push(&TPResponse.GetPageletHTML(&pageletXml, &LN_OBJLABEL, &LN_OBJNAME, &MINIMIZED));
                  Else
                     &aTemplate.Push("<CLASS>" | &CLASS_STR);
                     &aTemplate.Push(&LN_OBJLABEL);
                     &aTemplate.Push(&LN_OBJNAME);
                  End-If;
               End-If;

               /* Now look for any keys assigned - if not minimized */
               rem If &MINIMIZED = False Then;
               &RS2.Flush();
               &RS2.Fill("WHERE PORTAL_NAME=:1 AND PORTAL_OBJNAME=:2 AND PTCXM_OBJNAME=:3", &MyPortal.Name, &CREF.Name, &LN_OBJNAME);
               If &RS2.ActiveRowCount > 0 And
                     &RS2.GetRow(1).PTCXM_KEYSTRUCT.PTCXM_FIELDNAME0.Value <> "" Then
                  For &j = 1 To &RS2.ActiveRowCount
                     If &KEYLIST.Find(&RS2.GetRow(&j).PTCXM_KEYSTRUCT.PTCXM_FIELDNAME0.Value) = 0 Then
                        &KEYLIST.Push(&RS2.GetRow(&j).PTCXM_KEYSTRUCT.PTCXM_FIELDNAME0.Value);
                     End-If;
                  End-For;
               End-If;
               rem End-If;
            End-If;
         End-If;
      End-For;
   End-If;


   rem  --- PA89: remove setAnchor for CM;

   /* Assemble all javascript objects and script references */
   If &KEYLIST.Len > 0 Then
      &ptcxmReqKeys = """" | &KEYLIST [1] | """";
      For &i = 2 To &KEYLIST.Len
         &ptcxmReqKeys = &ptcxmReqKeys | ",""" | &KEYLIST [&i] | """";
      End-For;
   End-If;

   &TCURL = Substitute(&CREF.QualifiedURL, "/", "\/");
   &TCURL = Substitute(&TCURL, ".", "\.");

   /* PRJ121042 : Fix to CXM parentheses problem*/
   &TCURL = Substitute(&TCURL, "(", "\(");
   &TCURL = Substitute(&TCURL, ")", "\)");
   /* PRJ121042 End */

   &TESTPOS = Find("?", &TCURL);
   If &TESTPOS > 0 Then
      &TCURL = Left(&TCURL, &TESTPOS - 1);
   End-If;

   rem Modification for CXM Transfer post 8.8;
   rem PA89 use PT nav_script and navinframe in JS;

   If (&temp <> "x") Then
      rem for old menu;
      &ptcxmNewFolderURL = GenerateScriptPortalURL(%Portal, %Node, Record.WEBLIB_PTCXM, Field.ISCRIPT1, "FieldFormula", "IScript_PTCXM_INFRAME");
   Else
      rem for Ajax menu;
      &ptcxmNewFolderURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_PTCXM, Field.ISCRIPT1, "FieldFormula", "IScript_PTCXM_INFRAME");
   End-If;

   Local Response &resp = %Response;
   Local string &ptCommonJS = &resp.GetJavaScriptURL(HTML.PT_COMMON);

   &JSHTML = GetHTMLText(HTML.PTCXM_MGR_JS, &CrossDomainJavascriptUrl, %Response.GetJavaScriptURL(HTML.PT_SAVEWARNINGSCRIPT), &ptCommonJS, %Response.GetJavaScriptURL(HTML.PTCXM_MANAGER_JS), %Response.GetJavaScriptURL(HTML.PT_NAV_INFRAME_SCRIPT), %Response.GetJavaScriptURL(HTML.PT_NAV_SCRIPT), %Response.GetJavaScriptURL(HTML.PTCXM_AJAX_JS));

   &ptcxmLnParams = &TPResponse.PortalParmsForLN("?", False);

   &JSHTML = &JSHTML | GetHTMLText(HTML.PTCXM_MGR_VAR_JS, &TCURL, &ptcxmReqKeys, &CREF.Name, &ptcxmXferStopFlag, &ptcxmNewFolderURL, &ptcxmLnParams);

   REM If the 8.50 menu pagelet is found, add for onload processing;
   If &START = "" Then
      /* &START = "JavaScript:start_ptcxm()"; */
      If &is850Menu Then
         &START = "ptNav2.init(); start_ptcxm()";
      Else
         &START = "start_ptcxm()";
      End-If;
   Else
      &START = &START | "start_ptcxm()";
   End-If;

   /* Write the beginning of the HTML template */

   REM PRJ122285 fix for Context Manager not picking up Branding style sheet;
   &BrandingObj = CreateBrandingObject();
   If (&TPResponse.isIE() Or
         &TPResponse.isNS6x()) Then
      &PgltStyleSheetURL = &BrandingObj.GetNavstyleSheetURL();
   Else
      &PgltStyleSheetURL = &BrandingObj.GetNavstyleSheetURLAlt();
   End-If;
   rem context manager custom styles;
   &ptcxmStylesheetURL = &resp.GetStyleSheetURL(StyleSheet.PTCXMSTYLEDEF);

   REM Macintosh-specific code to remove onLoad event from nav;
   REM if the browser is IE or Opera;

   If ((%Request.BrowserType = "IE") Or
         (%Request.BrowserType = "OPERA")) And
         (Substring(%Request.BrowserPlatform, 1, 3) = "MAC") Then;
      %Response.Write(GetHTMLText(HTML.PTCXM_MGR_TEMPLATE_START_NO, &PgltStyleSheetURL, &add_remove_html, &START, &JSHTML, &jsdomain, &ptcxmStylesheetURL));
   Else
      Local string &hdrBarJS = %Response.GetJavaScriptURL(HTML.PTCXM_HEADERBAR);
      %Response.Write(GetHTMLText(HTML.PTCXM_MGR_TEMPLATE_START, &PgltStyleSheetURL, &add_remove_html, &START, &JSHTML, &jsdomain, &hdrBarJS, &ptcxmStylesheetURL));
   End-If;

   REM PRJ122285 end fix ;
   /* Loop through the template array writing template code or HTML as we go  */
   For &i = 1 To &aTemplate.Len
      If Left(&aTemplate [&i], 7) = "<CLASS>" Then
         If &aTemplate [&i + 1] <> "" Then
            %Response.Write(&TPResponse.GetPageletHTMLStart(&aTemplate [&i + 1], &aTemplate [&i + 2], False) | "<div class=""ptcxmmaxpglt"" id='" | &aTemplate [&i + 2] | "'>");
         End-If;
         setTP_CREFName(&aTemplate [&i + 2]);
         &ret = CallAppClass(Substring(&aTemplate [&i], 8, Len(&aTemplate [&i])));
         If Not &ret Then
            %Response.Write("<!--" | Substring(&aTemplate [&i], 8, Len(&aTemplate [&i])) | " could not be called -->");

         End-If;
         If &aTemplate [&i + 1] <> "" Then
            %Response.Write("</div>" | &TPResponse.GetPageletHTMLEnd(&aTemplate [&i + 1]));
         End-If;
         &i = &i + 2
      Else
         %Response.Write(&aTemplate [&i]);
      End-If;
   End-For;

   /* Write the end of the HTML template */
   %Response.Write(GetHTMLText(HTML.PTCXM_MGR_TEMPLATE_END));
End-Function;

/* ******************************************************************
***  IScript launch points for Demo Pagelets                      ***
***  Note: It is highly recommended that template pagelets be     ***
***    written as app classes, and accessed directly.             ***
***    These methods are provided here to demonstrate the         ***
***    difference.                                                ***
****************************************************************** */

Function IScript_TPDEMO
   &democlass = create PTCXM_TEMPLATE_PAGELET:DemoPagelets();
   &democlass.TemplatePageletDemo();
   Return;

End-Function;

Function IScript_TPDEMO_INVIS
   &democlass = create PTCXM_TEMPLATE_PAGELET:DemoPagelets();
   &democlass.InvisTemplatePageletDemo();
   Return;
End-Function;

import PT_NAV:*;
import PT_NAV2:NavTree;

Declare Function SetDocDomainToAuthTokenDomain PeopleCode FUNCLIB_PORTAL.TEMPLATE_FUNC FieldFormula;
Declare Function isNS7x PeopleCode FUNCLIB_PTCXM.FUNCLIB FieldFormula;

/* Change TESTING to return True to generate code to workaround ROBOT bug */
Function TESTING() Returns boolean
   Return True;
End-Function;

Function IScript_PTCXM_NAV_PAGELET()

   rem  -- PA89: use PT_NAV instead of EPPLN_NAV;
   Local PT_NAV:NavPagelet &navPagelet = create PT_NAV:NavPagelet("IScript_PT_NAV_PAGELET");
   &navPagelet.SetNavTitle();
   &navPagelet.GeneratePageletHTML();

End-Function;

Function IScript_PTCXM_NAV_INFRAME()

   rem  -- PA89: use PT_NAV instead of EPPLN_NAV;
   rem  -- Local EPPLN_NAV:NavPagelet &navPagelet = create EPPLN_NAV:NavPagelet("IScript_PTCXM_INFRAME:True");
   Local Response &resp = %Response;

   REM ajax event from the new left nav;
   Local string &temp = %Request.GetParameter("mode");
   If &temp = "x" Then
      Local PT_NAV2:NavTree &navTree = create PT_NAV2:NavTree();
      &resp.Write(&navTree.HTML);
   Else
      Local PT_NAV:NavPagelet &navPagelet = create PT_NAV:NavPagelet("IScript_PT_NAV_INFRAME");
      &navPagelet.GenerateInFrameHTML();
   End-If;

End-Function;

Function IScript_UniHeader_Frame()

   rem  -- PA89: use PT_NAV instead of EPPLN_NAV;
   Local PT_NAV:NavPagelet &navPagelet = create PT_NAV:NavPagelet("IScript_UniHeader_Frame");
   &navPagelet.GenerateHeaderHTML();

End-Function;

Function IScript_PTCXM_NAV_TPL_FRAME

   Local string &encryptedUserId = EncodeURLForQueryString(Encrypt("", %UserId | %Language));

   REM Set frame titles;
   &navTitleText = MsgGetText(240, 10, "Message not Found");
   &contentTitleText = MsgGetText(240, 11, "Message not Found");
   &headerTitleText = MsgGetText(240, 12, "Message not Found");

   REM Target content query string parameters;
   &params = "&PortalKeyStruct=yes";
   &pourl = %Request.GetHeader("portalactualurl");
   If All(&pourl) Then
      &params = "";
   End-If;

   &Access = GetUserOption("PPTL", "ACCESS");
   &HideNav = %Request.GetParameter("h");
   If (&HideNav = "") Then
      &HideNav = GetUserOption("PPTL", "AUTOMENU");
   End-If;

   REM Point to the location for the 8.4x menu pagelet with a title;
   Local string &pre850NavURL = "s/WEBLIB_PT_NAV.ISCRIPT2.FieldFormula.IScript_PT_NAV_INFRAME_TITLE?";
   Local Response &resp = %Response;

   If (%Request.BrowserType = "IE" Or
         isNS7x()) Then
      If (&Access = "A") Then
         If (&HideNav = "Y") Then
            &resp.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_COLLAPSE_ACC, &encryptedUserId, &params, &headerTitleText, &contentTitleText));
         Else
            &resp.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_EXPAND, &pre850NavURL, &params, &encryptedUserId, "LOCAL_NODE", &navTitleText, &contentTitleText, &headerTitleText));
         End-If;
      Else
         &resp.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_EXPAND, &pre850NavURL, &params, &encryptedUserId, "LOCAL_NODE", &navTitleText, &contentTitleText, &headerTitleText));
      End-If;
   Else
      If (&HideNav = "Y") Then
         If (&Access = "A") Then
            &resp.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_COLLAPSE_ACC, &encryptedUserId, &params, &headerTitleText, &contentTitleText));
         Else
            &resp.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_COLLAPSE, &pre850NavURL, &params, &encryptedUserId, "LOCAL_NODE", &navTitleText, &contentTitleText, &headerTitleText));
         End-If;
      Else
         &resp.Write(GetHTMLText(HTML.PTCXM_TPL_FRAME_EXPAND, &pre850NavURL, &params, &encryptedUserId, "LOCAL_NODE", &navTitleText, &contentTitleText, &headerTitleText));
      End-If;
   End-If;
End-Function;

Function IScript_EmptyFile()

   Local string &authdomain = SetDocDomainToAuthTokenDomain();

   Local number &nMetaXp = Value(GetUserOption("PPTL", "METAXP"));
   Local string &sGMT = DateTimeToHTTP(AddToDateTime(%Datetime, 0, 0, 0, 0, &nMetaXp, 0));
   If (&sGMT <> "") Then
      %Response.SetHeader("expires", &sGMT);
      %Response.SetHeader("last-modified", &sGMT);
   End-If;

   %Response.Write("<HTML dir='" | %Direction | "'><HEAD>" | &authdomain | "</HEAD></HTML>");

End-Function;

import PT_DIAGNOSTICS:*;
import PT_DIAGNOSTICS:Collections:*;

/* Cant pass component var Component oList &oolist; Workaround with Table */
Component PT_DIAGNOSTICS:Collections:oList &oolist;
Component string &createDate;

/* 
**********************************************************************
Function: IScript_PTdiagnostics
Purpose:  Instantiate Application Class and Generate HTML/XML Layout
**********************************************************************
*/
Function IScript_PTdiagnostics()

   Local Rowset &rDiagPackageReg, &rAppClass, &rRowset1, &rRowset2;
   Local string &pkg, &clsName, &plugInDescr, &Header1, &Header2, &Header3, &Header4, &Header5, &Header6, &PeopleToolVersion, &AppsRelease;
   Local string &sHTMLarea, &sXMLarea;
   Local PT_DIAGNOSTICS:PTDiagnostics &ptDiag;
   Local number &i, &j;
   Local array of string &parameter_values;
   Local boolean &xmlType, &Found;
   Local PT_DIAGNOSTICS:Collections:qList &qList;
   Local Record &recdata1, &recdata2;
   Local PT_DIAGNOSTICS:Collections:aList &PkgAll;
   Local datetime &ProcessDate;
   Local string &OperID;
   Local boolean &eMailEnable;
   Local SQL &Sql1, &Sql2, &sqlPeopletoolVer, &sqlReleaseVer;
   Local PT_DIAGNOSTICS:Collections:oList &olist;
   Local string &MAIL_TEXT, &MAIL_FILES, &MAIL_TILTLES, &MAIL_SENDER, &MAIL_FROM, &sMAIL_TO, &MAIL_TO, &MAIL_CC, &MAIL_BCC, &MAIL_SUBJECT, &MAIL_TITLES;
   Local string &filename1, &filename2;
   Local number &MAIL_FLAGS;
   Local string &strTmp;

   Local number &startRow, &maxRow;

   SQLExec("SELECT MAX(RELEASELABEL) FROM PS_MAINTENANCE_LOG WHERE RELEASELABEL LIKE 'PeopleTool%'", &PeopleToolVersion);
   SQLExec("select RELEASELABEL from PSRELEASE where RELEASEDTTM = (select max(RELEASEDTTM) from PSRELEASE)", &AppsRelease);


   &reqPara = %Request.GetParameterNames();
   &parameter_values = CreateArrayRept("", 0);
   &rDiagPackageReg = CreateRowset(Record.PSDIAGPKGVW);
   &ptDiag = create PT_DIAGNOSTICS:PTDiagnostics();
   &PkgAll = create PT_DIAGNOSTICS:Collections:aList();
   &oolist = create PT_DIAGNOSTICS:Collections:oList();
   &olist = create PT_DIAGNOSTICS:Collections:oList();
   &startRow = 1;
   &maxRow = 25;

   /* Extract all the package name from parameter values */
   For &i = 1 To &reqPara.len
      &pkg = &reqPara [&i];
      &reqVals = %Request.GetParameterValues(&reqPara [&i]);
      For &j = 1 To &reqVals.len
         Evaluate &reqPara [&i]
         When "pkg"
            /* Extract Package Name */
            &parameter_values.Push(&reqVals [&j]);
            Break;
         When "xml"
            /* Extract printlayout type */
            If &reqVals [&j] = "true" Then
               &xmlType = True;
            Else
               &xmlType = False;
            End-If;
            Break;
         When "OPR"
            &OperID = &reqVals [&j];
            Break;
         When "Date"
            &ProcessDate = DateTimeValue(&reqVals [&j]);
            &createDate = String(DateTimeToLocalizedString(&ProcessDate, "MM/dd/yyyy HH:mm:ss.SSSSSS"));
            Break;

         When "eMail1"
            If &reqVals [&j] = "Y" Then
               &eMailEnable = True;
            Else
               &eMailEnable = False;
            End-If;
         When "eMailFrom"
            &MAIL_FROM = &reqVals [&j];
            &MAIL_SENDER = &reqVals [&j];
            Break;
         When "eMailTo"
            &MAIL_TO = &reqVals [&j];
            Break;
         When "eMailCC"
            &MAIL_CC = &reqVals [&j];
            Break;
         When "eMailSubject"
            &MAIL_SUBJECT = &reqVals [&j];
            Break;
         When "startRow"
            &startRow = &reqVals [&j];
            Break;
         When "maxRow"
            &maxRow = &reqVals [&j];
            Break;
         End-Evaluate;
      End-For;
   End-For;

   /* Gathering pkg to generate oolist */
   &recdata1 = CreateRecord(Record.PSDIAGQRYVW1);
   &Sql1 = CreateSQL("%SELECTALL(:1) WHERE OPRID = :2 AND PSSYSCREATEDTTM = %DateTimeIn(:3)");
   &Sql1.Execute(&recdata1, &OperID, &ProcessDate);
   While &Sql1.Fetch(&recdata1) = True
      &PkgAll.AddItem(&recdata1.GetField(Field.PACKAGEID).Value);
   End-While;
   &recdata2 = CreateRecord(Record.PSDIAGQRYVW2);
   &Sql1.Execute(&recdata2, &OperID, &ProcessDate);
   While &Sql1.Fetch(&recdata2) = True
      &indxexist = &PkgAll.IndexOf(&recdata2.GetField(Field.PACKAGEID).Value);
      If &indxexist = 0 Then
         &PkgAll.AddItem(&recdata2.GetField(Field.PACKAGEID).Value);
      End-If;
   End-While;

   /* Create oolist */
   If &PkgAll.len > 0 Then
      &rRowset1 = CreateRowset(Record.PSDIAGQRY1);
      &rRowset2 = CreateRowset(Record.PSDIAGQRY2);
      &rAppClass = CreateRowset(Record.PSDIAGQRYVW);

      For &i = 1 To &PkgAll.len
         &pkgName = &PkgAll.Get(&i);
         &Found = False;
         &rcRowset1 = &rRowset1.Fill("WHERE PACKAGEID = :1 ", &pgkname);
         If &rcRowset1 > 0 Then
            /* find from Global */
            &Found = True;
            &qList = CreateObject("PT_DIAGNOSTICS:Collections:qList");
         Else
            /* find from Class */
            &rcRowset2 = &rRowset2.Fill("WHERE PACKAGEID = :1 ", &pkgName);
            If &rcRowset2 > 0 Then
               &Found = True;
               &qList = CreateObject("PT_DIAGNOSTICS:Collections:qList");
            End-If;
         End-If;

         If &Found Then
            /* Populate Global Level */
            &qList.classID = &clsName;
            &recdata1 = CreateRecord(Record.PSDIAGQRY1);
            &Sql2 = CreateSQL("%SELECTALL(:1) WHERE OPRID = :2 AND PSSYSCREATEDTTM = %DateTimeIn(:3) AND PACKAGEID = :4 ");
            &Sql2.Execute(&recdata1, &OperID, &ProcessDate, &pkgName);
            While &Sql2.Fetch(&recdata1) = True
               Evaluate &recdata1.GetField(Field.FLDFORMAT).Value
               When &qList.dateType
                  &stat = &qList.AddAll(&recdata1.GetField(Field.KEYVALUE).Value, &recdata1.GetField(Field.DESCR50).Value, &recdata1.GetField(Field.FLDFORMAT).Value, &recdata1.GetField(Field.ROW_NUM).Value, &recdata1.GetField(Field.FIELD_DATE).Value, True);
                  Break;
               When &qList.boolType
                  &stat = &qList.AddAll(&recdata1.GetField(Field.KEYVALUE).Value, &recdata1.GetField(Field.DESCR50).Value, &recdata1.GetField(Field.FLDFORMAT).Value, &recdata1.GetField(Field.ROW_NUM).Value, &recdata1.GetField(Field.FIELD_BOOL).Value, True);
                  Break;
               When-Other
                  &stat = &qList.AddAll(&recdata1.GetField(Field.KEYVALUE).Value, &recdata1.GetField(Field.DESCR50).Value, &recdata1.GetField(Field.FLDFORMAT).Value, &recdata1.GetField(Field.ROW_NUM).Value, &recdata1.GetField(Field.FIELD_CHAR).Value, True);
                  Break;
               End-Evaluate;
            End-While;

            /* Populate Class Level per class */
            &rcAppClass = &rAppClass.Fill("WHERE PACKAGEID = :1 ", &pkgName);
            For &j = 1 To &rcAppClass
               &clsName = &rAppClass(&j).PSDIAGQRYVW.APPCLASSID.Value;
               If &Found Then
                  &qList.classID = &clsName;
                  &recdata1 = CreateRecord(Record.PSDIAGQRY2);
                  &Sql2 = CreateSQL("%SELECTALL(:1) WHERE OPRID = :2 AND PSSYSCREATEDTTM = %DateTimeIn(:3) AND APPCLASSID = :4 AND PACKAGEID = :5 ");
                  &Sql2.Execute(&recdata1, &OperID, &ProcessDate, &clsName, &pkgName);
                  While &Sql2.Fetch(&recdata1) = True
                     Evaluate &recdata1.GetField(Field.FLDFORMAT).Value
                     When &qList.dateType
                        &stat = &qList.AddAll(&recdata1.GetField(Field.KEYVALUE).Value, &recdata1.GetField(Field.DESCR50).Value, &recdata1.GetField(Field.FLDFORMAT).Value, &recdata1.GetField(Field.ROW_NUM).Value, &recdata1.GetField(Field.FIELD_DATE).Value, True);
                        Break;
                     When &qList.boolType
                        &stat = &qList.AddAll(&recdata1.GetField(Field.KEYVALUE).Value, &recdata1.GetField(Field.DESCR50).Value, &recdata1.GetField(Field.FLDFORMAT).Value, &recdata1.GetField(Field.ROW_NUM).Value, &recdata1.GetField(Field.FIELD_BOOL).Value, True);
                        Break;
                     When-Other
                        &stat = &qList.AddAll(&recdata1.GetField(Field.KEYVALUE).Value, &recdata1.GetField(Field.DESCR50).Value, &recdata1.GetField(Field.FLDFORMAT).Value, &recdata1.GetField(Field.ROW_NUM).Value, &recdata1.GetField(Field.FIELD_CHAR).Value, True);
                        Break;
                     End-Evaluate;
                  End-While;

               End-If;

            End-For;
            &stat = &olist.AddObject(&qList, &pkgName);
         End-If;
      End-For;

      /* Clean up record for oolist */
      /*&recdata1 = CreateRecord(Record.PSDIAGQRY1);
      &recdata2 = CreateRecord(Record.PSDIAGQRY2);
      For &i = 1 To &PkgAll.len
         &pkgName = &PkgAll.Get(&i);
         &recdata1.OPRID.Value = &OperID;
         &recdata1.PSSYSCREATEDTTM.Value = &ProcessDate;
         &recdata1.PACKAGEID.Value = &pkgName;
         &recdata1.Delete();
         &recdata2.OPRID.Value = &OperID;
         &recdata2.PSSYSCREATEDTTM.Value = &ProcessDate;
         &recdata2.PACKAGEID.Value = &pkgName;
         &recdata2.Delete();

         /* temporary delete by sqlexec */
      REM SQLExec("DELETE FROM PSDIAGQRY1 WHERE OPRID = :1 AND PACKAGEID = :2 AND PSSYSCREATEDTTM = %DATETIMEIN(:3)", &OperID, &pkgName, &ProcessDate);
      REM SQLExec("DELETE FROM PSDIAGQRY2 WHERE OPRID = :1 AND PACKAGEID = :2 AND PSSYSCREATEDTTM = %DATETIMEIN(:3)", &OperID, &pkgName, &ProcessDate);
      REM End-For;
   End-If;

   If &parameter_values.Len > 0 Then
      &rAppClass = CreateRowset(Record.PSAPPCLASSDEFN);
      For &i = 1 To &parameter_values.Len
         &pkgName = &parameter_values [&i];
         &rcAppClass = &rAppClass.Fill("WHERE PACKAGEROOT = :1", &pkgName);
         If None(&rcAppClass) Then
            /* invalid package name, do not output anything, continue to next app package */
            Continue;
         End-If;
         &rcDiagPackageReg = &rDiagPackageReg.Fill("WHERE PACKAGEID = :1", &pkgName);
         If &rcDiagPackageReg > 0 Then
            &plugInDescr = &rDiagPackageReg(1).PSDIAGPKGVW.DESCR.Value;
         Else
            &plugInDescr = " ";
         End-If;
         /* Get Object */
         &CleanUp = &oolist.DeleteObject();
         If &CleanUp Then
            &stat = &oolist.AddObject(&olist.GetObjectByPackage(&pkgName), &pkgName);
         End-If;
         If &xmlType Then
            /* Set Package Header for XML */
            &sHTMLarea = &sHTMLarea | Char(13) | " <" | &pkgName | ">";
         End-If;
         For &j = 1 To &rcAppClass
            &clsName = &rAppClass(&j).PSAPPCLASSDEFN.APPCLASSID.Value;
            If All(&clsName) Then
               try
                  /* Instantiate AppClass */
                  &DiagnosticObj = CreateObject(&pkgName | ":" | &clsName);

                  /* Call GetDiagnosticInfo */
                  (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).PackageName = &pkgName;
                  (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).ClassName = &clsName;
                  &tempDescr = (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).PackageDescr;
                  If None(&tempDescr) Then
                     (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).PackageDescr = &plugInDescr;
                  End-If;
                  If Not &xmlType Then
                     (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).DisplayHTML = True;
                  Else
                     (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).DisplayHTML = False;
                  End-If;
                  &DiagnosticObj.getdiagnosticinfo();
                  /* Get Output */
                  If Not &xmlType Then
                     &sHTMLarea = &sHTMLarea | (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).ToHTML(&startRow, &maxRow);
                     &sHTMLarea = &sHTMLarea | "<BR><BR>";
                  Else
                     &sHTMLarea = &sHTMLarea | (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).ToXML();
                  End-If;
               catch Exception &Err1
                  /* on exception send message to base class with failure message */
                  &Msg = "Exception on Package: " | &pkgName | ", Class: " | &clsName;
                  %Response.Write(&Msg | Char(13));
                  &Msg = "Error:" | &Err1.ToString();
                  %Response.Write(&Msg);
               end-try;
            End-If;
         End-For;
         If &xmlType Then
            /* Set Package Tail for XML */
            &sHTMLarea = &sHTMLarea | Char(13) | " </" | &pkgName | ">";
         End-If;
      End-For;
   End-If;

   If Not &xmlType Then
      &Header1 = MsgGetText(210, 12, "Message not found") | ": <B>" | %DbName | "</B>";
      &Header2 = MsgGetText(210, 13, "Message not found") | ": <B>" | %OperatorId | "</B>";
      &Header3 = MsgGetText(210, 14, "Message not found") | ": <B>" | %Datetime | "</B>";
      &Header4 = MsgGetText(210, 26, "Message not found") | ": <B>" | %DbType | "</B>";
      &Header5 = MsgGetText(210, 47, "Message not found") | ": <B>" | &PeopleToolVersion | "</B>";
      &Header6 = MsgGetText(210, 48, "Message not found") | ": <B>" | &AppsRelease | "</B>";

      &output = GetHTMLText(HTML.PT_DIAGNOSTICS, MsgGetText(210, 27, "Message not found"), &Header1, &Header2, &Header3, &Header4, &Header5, &Header6, &sHTMLarea);
   Else
      &strTmp = Substitute(MsgGetText(210, 12, "Message not found"), " ", "_");
      &Header1 = "<" | &strTmp | ">" | %DbName | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 13, "Message not found"), " ", "_");
      &Header2 = "<" | &strTmp | ">" | %OperatorId | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 14, "Message not found"), " ", "_");
      &Header3 = "<" | &strTmp | ">" | %Datetime | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 26, "Message not found"), " ", "_");
      &Header4 = "<" | &strTmp | ">" | %DbType | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 47, "Message not found"), " ", "_");
      &Header5 = "<" | &strTmp | ">" | &PeopleToolVersion | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 48, "Message not found"), " ", "_");
      &Header6 = "<" | &strTmp | ">" | &AppsRelease | "</" | &strTmp | ">";

      &output = GetHTMLText(HTML.PT_DIAGNOSTICS_XML, &Header1, &Header2, &Header3, &Header4, &Header5, &Header6, &sHTMLarea);
   End-If;
   If &eMailEnable Then

      &sMAIL_TO = EscapeHTML(&MAIL_TO);
      /* Create attachment */
      &filename1 = GetCwd() | "\" | %OperatorId | ".html";

      /* File name need to be scrambled */
      Local File &MyFile;
      &MyFile = GetFile(&filename1, "W", %FilePath_Absolute);
      &filename1 = &MyFile.Name;
      &MyFile.WriteString(&output);
      &MyFile.Close();

      /* do email processing */
      &MAIL_FLAGS = 0;
      &MAIL_BCC = "";

      &MAIL_SUBJECT = &MAIL_SUBJECT | " - " | MsgGetText(210, 39, "Message not found") | " " | String(&ProcessDate);
      &MAIL_TEXT = MsgGetExplainText(210, 38, "Message not found") | Char(13) | Char(13);
      &MAIL_TEXT = &MAIL_TEXT | MsgGetText(210, 12, "Message not found") | ": " | %DbName | Char(13);
      &MAIL_TEXT = &MAIL_TEXT | MsgGetText(210, 13, "Message not found") | ": " | %OperatorId | Char(13);
      &MAIL_TEXT = &MAIL_TEXT | MsgGetText(210, 14, "Message not found") | ": " | %Datetime | Char(13);
      &MAIL_TEXT = &MAIL_TEXT | MsgGetText(210, 26, "Message not found") | ": " | %DbType | Char(13) | Char(13);
      &MAIL_TEXT = &MAIL_TEXT | MsgGetText(210, 47, "Message not found") | ": " | &PeopleToolVersion | Char(23);
      &MAIL_TEXT = &MAIL_TEXT | MsgGetText(210, 48, "Message not found") | ": " | &AppsRelease | Char(26);

      &MAIL_FILES = &filename1;

      If Not &xmlType Then
         &MAIL_TITLES = Substitute(MsgGetText(210, 27, "Message not found"), " ", "_") | "_" | %OperatorId | ".html";
      Else
         &MAIL_TITLES = Substitute(MsgGetText(210, 27, "Message not found"), " ", "_") | "_" | %OperatorId | ".xml";
      End-If;

      /* now compose the XML file */

      If &parameter_values.Len > 0 Then
         &rAppClass = CreateRowset(Record.PSAPPCLASSDEFN);
         For &i = 1 To &parameter_values.Len
            &pkgName = &parameter_values [&i];
            &rcAppClass = &rAppClass.Fill("WHERE PACKAGEROOT = :1", &pkgName);
            If None(&rcAppClass) Then
               /* invalid package name, do not output anything, continue to next app package */
               Continue;
            End-If;
            &rcDiagPackageReg = &rDiagPackageReg.Fill("WHERE PACKAGEID = :1", &pkgName);
            If &rcDiagPackageReg > 0 Then
               &plugInDescr = &rDiagPackageReg(1).PSDIAGPKGVW.DESCR.Value;
            Else
               &plugInDescr = " ";
            End-If;
            /* Get Object */
            &CleanUp = &oolist.DeleteObject();
            If &CleanUp Then
               &stat = &oolist.AddObject(&olist.GetObjectByPackage(&pkgName), &pkgName);
            End-If;
            &sXMLarea = &sXMLarea | Char(13) | " <" | &pkgName | ">";
            For &j = 1 To &rcAppClass
               &clsName = &rAppClass(&j).PSAPPCLASSDEFN.APPCLASSID.Value;
               If All(&clsName) Then
                  try
                     /* Instantiate AppClass */
                     &DiagnosticObj = CreateObject(&pkgName | ":" | &clsName);

                     /* Call GetDiagnosticInfo */
                     (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).PackageName = &pkgName;
                     (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).ClassName = &clsName;
                     &tempDescr = (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).PackageDescr;
                     If None(&tempDescr) Then
                        (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).PackageDescr = &plugInDescr;
                     End-If;
                     (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).DisplayHTML = False;
                     &DiagnosticObj.getdiagnosticinfo();
                     /* Get Output */
                     &sXMLarea = &sXMLarea | (&DiagnosticObj As PT_DIAGNOSTICS:PTDiagnostics).ToXML();
                  catch Exception &ErrXML
                     /* on exception send message to base class with failure message */
                     &Msg = "Exception on Package: " | &pkgName | ", Class: " | &clsName;
                     %Response.Write(&Msg | Char(13));
                     &Msg = "Error:" | &ErrXML.ToString();
                     %Response.Write(&Msg);
                  end-try;
               End-If;
            End-For;
            /* Set Package Tail for XML */
            &sXMLarea = &sXMLarea | Char(13) | " </" | &pkgName | ">";
         End-For;
      End-If;

      &strTmp = Substitute(MsgGetText(210, 12, "Message not found"), " ", "_");
      &Header1 = "<" | &strTmp | ">" | %DbName | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 13, "Message not found"), " ", "_");
      &Header2 = "<" | &strTmp | ">" | %OperatorId | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 14, "Message not found"), " ", "_");
      &Header3 = "<" | &strTmp | ">" | %Datetime | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 26, "Message not found"), " ", "_");
      &Header4 = "<" | &strTmp | ">" | %DbType | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 47, "Message not found"), " ", "_");
      &Header5 = "<" | &strTmp | ">" | &PeopleToolVersion | "</" | &strTmp | ">";
      &strTmp = Substitute(MsgGetText(210, 48, "Message not found"), " ", "_");
      &Header6 = "<" | &strTmp | ">" | &AppsRelease | "</" | &strTmp | ">";
      &output = GetHTMLText(HTML.PT_DIAGNOSTICS_XML, &Header1, &Header2, &Header3, &Header4, &Header5, &Header6, &sXMLarea);

      &filename2 = GetCwd() | "\" | %OperatorId | ".xml";

      /* File name need to be scrambled */
      &MyFile = GetFile(&filename2, "W", %FilePath_Absolute);
      &filename2 = &MyFile.Name;
      &MyFile.WriteString(&output);
      &MyFile.Close();

      /* end composing XML file */

      &MAIL_FILES = &MAIL_FILES | ";" | &filename2;
      &MAIL_TITLES = &MAIL_TITLES | ";" | Substitute(MsgGetText(210, 27, "Message not found"), " ", "_") | "_" | %OperatorId | ".xml";


      &RET = 0;
      &RET = SendMail(&MAIL_FLAGS, &MAIL_TO, &MAIL_CC, &MAIL_BCC, &MAIL_SUBJECT, &MAIL_TEXT, &MAIL_FILES, &MAIL_TITLES, &MAIL_SENDER);

      &output = "";
      If Not (&RET = 0) Then
         /* failed */
         &output = &output | GetHTMLText(HTML.PT_DIAGNOSTICS, MsgGetText(210, 27, "Message not found"), " ", MsgGetText(210, 29, "Message Not Found"), &sMAIL_TO, MsgGetText(210, 30, "Message Not Found") | &RET, MsgGetText(210, 31, "Message Not Found"));
      Else
         /* success */
         &output = &output | GetHTMLText(HTML.PT_DIAGNOSTICS, MsgGetText(210, 27, "Message not found"), " ", MsgGetText(210, 28, "Message Not Found"), &sMAIL_TO, " ", " ");
      End-If;
      /* clean up email files */
      &MyFile = GetFile(&filename1, "W", %FilePath_Absolute);
      &MyFile.Delete();
      &MyFile = GetFile(&filename2, "W", %FilePath_Absolute);
      &MyFile.Delete();

   End-If;

   /* set content type to xml if request is for xml */
   If &xmlType Then
      %Response.SetContentType("text/xml");
   End-If;

   %Response.Write(&output);

End-Function;

Declare Function genReloadGroupletsScript PeopleCode FUNCLIB_PTGP.FUNCLIB FieldFormula;



/**
  * Initialization grouplet for User Preferences.
  *
  */
Function IScript_UserPreference

   Local string &html, &script;

   &script = genReloadGroupletsScript();

   &html = GetHTMLText(HTML.PTGP_INCLUDE_SCRIPTS, &script);

   %Response.Write(&html);

End-Function;

/**************************************************************************************
 NOTE:  The code in this record (WEBLIB_PTGPLT) should not be modified unless absolutely
         necessary.  This code must remain in sync with the code that will be delivered 
         through enterprise componenets.  If it is absolutely necessary to update this
         record, the same code must be put into the enterprise components codeline.
 **************************************************************************************/

import PTPPB_GROUPLET:*;
import PTPPB_GROUPLET:UTILITY:*;
import PTPPB_GROUPLET:EXCEPTION:*;

Declare Function CheckRenderType PeopleCode WEBLIB_PTPP_SC.HOMEPAGE FieldFormula;
Declare Function CheckGpltEnabled PeopleCode FUNCLIB_PTGPLT.HOMEPAGE FieldFormula;
