/************************************************/
/* Determine the Grouplet Personalization URL (SearchInit) */
/************************************************/
Function GetGpltPrefURL(&CheckType) Returns string;
   Local string &GroupletID, &PTPPRecExists, &EOPPRecExists, &EOPPTestValue, &HTML;
   Local object &Utility;
   Local string &PrefURL, &GoToMenuName, &GoToComponent, &GoToPage, &GoToQString;

   /* Get the Grouplet ID from the QueryString */
   &GroupletID = %Request.GetParameter("PTPPB_GROUPLET_ID");
   If None(&GroupletID) Then
      &GroupletID = %Request.GetParameter("EOPPB_GROUPLET_ID");
   End-If;

   If &CheckType = "PTPP" Then
      &GoToMenuName = "PTPPB_GROUPLET_WIZARD";
      &GoToComponent = "PTPPB_USER_PREF";
      &GoToPage = "PTPPB_USER_PREF";
      &GoToQString = "&PTPPB_GROUPLET_ID="
   Else
      &GoToMenuName = "EOPPB_GROUPLET_WIZARD";
      &GoToComponent = "EOPPB_USER_PREF";
      &GoToPage = "EOPPB_USER_PREF";
      &GoToQString = "&EOPPB_GROUPLET_ID="
   End-If;

   &PrefURL = GenerateComponentContentURL(%Portal, %Node, @("Menuname." | &GoToMenuName), %Market, @("Component." | &GoToComponent), @("Page." | &GoToPage), "") | &GoToQString | &GroupletID;

   Return &PrefURL;
End-Function;

/************************************************/
/* Determine which HTML to render (Cref Iscript)*/
/************************************************/
Function RenderGpltWiz(&GroupletType As string) Returns string;
   Local string &GroupletID, &HTML;
   Local object &Utility;

   /* Get the Grouplet ID from the QueryString */
   &GroupletID = %Request.GetParameter("PTPPB_GROUPLET_ID");


   &Utility = CreateObject("PTPPB_GROUPLET:UTILITY:Utility");
   &HTML = ObjectDoMethod(&Utility, "GetGpltHTML", &GroupletID, &GroupletType);

   Return &HTML;
End-Function;

/**********************************************************************/
/** WSRP Support for Grouplet Wizard                                  **/
/** This code supports WSRP production of Grouplet Wizard Grouplets    **/
/**********************************************************************/
/** NOT CURRENTLY USED                                               **/
/**********************************************************************/
Function createWSRPResponseWrapper(&mode As string, &windowState As string, &renderCallback As boolean, &portletTitle As string, &markup As string) Returns string

   Local XmlNode &thisnode;

   Local XmlDoc &xmldoc = CreateXmlDoc("");
   Local XmlNode &docnode = &xmldoc.CreateDocumentElement("portlet-response");
   If Not None(&mode, &windowState) Then
      Local XmlNode &statenode = &docnode.AddElement("portlet-state");
      If All(&mode) Then
         &thisnode = &statenode.AddElement("portlet-mode");
         &thisnode.NodeValue = &mode;
      End-If;
      If All(&windowState) Then
         &thisnode = &statenode.AddElement("portlet-window-state");
         &thisnode.NodeValue = &windowState;
      End-If;
      &thisnode = &statenode.AddElement("render-callback");
      &thisnode.NodeValue = String(&renderCallback);
   End-If;
   If Not None(&portletTitle, &markup) Then
      Local XmlNode &markupnode = &docnode.AddElement("portlet-markup");
      If All(&portletTitle) Then
         &thisnode = &markupnode.AddElement("portlet-title");
         &thisnode.NodeValue = &portletTitle;
      End-If;
      If All(&markup) Then
         &thisnode = &markupnode.AddCDataSection(&markup);
      End-If;
   End-If;
   Return &xmldoc.GenXmlString();
End-Function;

/*****************************************************************/
/* Iscript for Rendering the Grouplet Wizard Homepage Grouplet     */
/*****************************************************************/
Function IScript_GroupletBuilder

   %Response.Write(RenderGpltWiz("HMPG"));

End-Function;

/*****************************************************************/
/* Iscript for Rendering the Grouplet Wizard Embeddable Grouplet in Related Content frame*/
/*****************************************************************/
Function IScript_EmbedGrpletBuilder
   Local string &ParmValue, &GroupletID, &GpltHTML;
   Local string &GroupletErrorTitle, &DetailedErrorDesc, &ErrorDetails, &subst1, &subst2, &subst3, &subst4, &subst5;
   Local PTPPB_GROUPLET:UTILITY:Collection &paramColl;
   Local PTPPB_GROUPLET:GroupletWizard &PWAPI;
   Local PTPPB_GROUPLET:Grouplet &Grouplet;

   /* Set to True to include the PeopleCode location/trance info for GroupletExceptions */
   Local boolean &ShowExceptionLocation = False;

   /* First check for Portal Pack installation */
   &GpltHTML = CheckGpltEnabled();
   If CheckGpltEnabled() <> "" Then
      %Response.Write(&GpltHTML);
   End-If;


   /* Create the Grouplet Wizard application pakage and assign the grouplet ID*/
   try
      &GroupletID = %Request.GetParameter("GROUPLETID");
      SetLogger(&GroupletID);

      &PWAPI = create PTPPB_GROUPLET:GroupletWizard();
      &Grouplet = &PWAPI.getGroupletByID(&GroupletID, True);
      &Grouplet.PSGeneratedLinkTarget = "_parent";
      &Grouplet.CxMExecute = True;

      /* Force a full DataSource Load - required for prompt validation */
      &Grouplet.fullDataSourceLoad();

      /* Set the grouplet parameters to default values*/
      &Grouplet.PopulateInputsWithDefaults();


      /* Override the grouplet parameter default values by reading the request object*/
      &paramColl = &Grouplet.DataSource.getParameterCollection();

      For &i = 1 To &paramColl.Count
         &thisParameter = &paramColl.getItem(&i);
         If &thisParameter.UsageType = &thisParameter.USAGETYPE_USERSPECIFIED Or
               &thisParameter.UsageType = &thisParameter.USAGETYPE_CONTEXTUAL Then
            &ParmValue = %Request.GetParameter(&thisParameter.Name);
            If (&ParmValue <> "") Then
               &thisParameter.value = &ParmValue;
            End-If;
         End-If;
      End-For;

      /* Get the Embeddable Grouplet HTML */
      &GpltHTML = &Grouplet.Execute();

   catch PTPPB_GROUPLET:EXCEPTION:GroupletException &ex

      &GroupletErrorTitle = MsgGetText(219, 350, "(Message Not Found) Error executing grouplet.");
      &DetailedErrorDesc = MsgGetText(219, 351, "(Message Not Found) Detailed error description:");

      Evaluate &ex.SubstitutionCount
      When > 4
         &subst5 = &ex.GetSubstitution(5);
      When > 3
         &subst4 = &ex.GetSubstitution(4);
      When > 2
         &subst3 = &ex.GetSubstitution(3);
      When > 1
         &subst2 = &ex.GetSubstitution(2);
      When > 0
         &subst1 = &ex.GetSubstitution(1);
      End-Evaluate;
      &ErrorDetails = MsgGetExplainText(&ex.MessageSetNumber, &ex.MessageNumber, "", &subst1, &subst2, &subst3, &subst4, &subst5);

      If &ShowExceptionLocation Then
         &GpltHTML = GetHTMLText(HTML.PTPPB_GROUPLET_RUNTIME_ERROR, EscapeHTML(&GroupletErrorTitle), EscapeHTML(&DetailedErrorDesc), EscapeHTML(&ex.ToString()), EscapeHTML(&ErrorDetails));
      Else
         &GpltHTML = GetHTMLText(HTML.PTPPB_GROUPLET_RUNTIME_ERROR, EscapeHTML(&GroupletErrorTitle), EscapeHTML(&DetailedErrorDesc), "", EscapeHTML(&ErrorDetails));
      End-If;

   end-try;

   %Response.Write("<div class='PSTEXT'>" | &GpltHTML | "</div>");

End-Function;

