/* Function for generating/handling WSRP edit mode (aka grouplet personalization) */
Function WSRPEdit Returns string

   Local PTPPB_GROUPLET:GroupletWizard &PWAPI;
   Local PTPPB_GROUPLET:Grouplet &thisGrouplet;
   Local PTPPB_GROUPLET:DataSource:DataSourceParameter &thisParameter, &thisParameterDefault;
   Local boolean &ShowExceptionLocation, &isSaveOK, &isDefault, &RET;
   Local string &GroupletID, &GpltHTML, &NameSpaceID, &formAction, &formValue, &errMsg, &paramVal, &actionURL;
   Local string &ParamRow, &formRows, &optionRows;
   Local number &i, &j, &pos, &errIndex;
   Local array of array of string &pageParameters;
   Local Record &REC_PTPPB_USER_PRMS;

   If Upper(%Request.GetParameter("PIAPortletWindowState")) = "MINIMIZED" Then
      Return createWSRPResponseWrapper("", "", False, "", "");
   Else

      /* Tell grouplet wizard to go ahead and throw exceptions */
      &PTPPB_THROWGROUPLETEXCEPTIONS = True;

      &REC_PTPPB_USER_PRMS = CreateRecord(Record.PTPPB_USER_PRMS);

      /* First check for Portal Pack installation */
      &GpltHTML = CheckGpltEnabled();
      If CheckGpltEnabled() <> "" Then
         Return &GpltHTML;
      End-If;

      If %Request.GetParameter("save") <> "" Then
         &formAction = "save"
      End-If;
      If %Request.GetParameter("reset") <> "" Then
         &formAction = "reset"
      End-If;
      If %Request.GetParameter("cancel") <> "" Then
         &formAction = "cancel"
      End-If;

      If &formAction = "cancel" Then
         /* Now return back the mode shift to "view" */
         Return createWSRPResponseWrapper("view", "", True, "", "");
      Else

         &GroupletID = %Request.GetParameter("PTPPB_GROUPLET_ID");
         &PWAPI = create PTPPB_GROUPLET:GroupletWizard();
         &thisGrouplet = &PWAPI.getGroupletByID(&GroupletID, False);

         /* Generate the array of parameters to show for this grouplet */
         /* The array has the shape [paramName,paramValue,isValid] where paramValue is the
         value as it should currently be shown on the page */
         &pageParameters = CreateArrayRept(CreateArray("", "", ""), 0);
         For &i = 1 To &thisGrouplet.DataSource.ParameterCollection.Count
            &thisParameter = &thisGrouplet.DataSource.ParameterCollection.getItem(&i);
            If &thisParameter.UsageType = &thisParameter.USAGETYPE_USERSPECIFIED Then
               &formValue = %Request.GetParameter(&thisParameter.Name);
               If &formValue <> "" Then
                  &pageParameters.Push(CreateArray(&thisParameter.Name, &formValue, ""));
               Else
                  /* Parameter not found on query string, look for an already saved user value */
                  &REC_PTPPB_USER_PRMS.PTPPB_GROUPLET_ID.Value = &GroupletID;
                  &REC_PTPPB_USER_PRMS.PTPPB_FIELDNAME.Value = &thisParameter.Name;
                  &REC_PTPPB_USER_PRMS.OPRID.Value = %UserId;
                  &REC_PTPPB_USER_PRMS.SelectByKey();
                  If &REC_PTPPB_USER_PRMS.PTPPB_VALUE.Value <> "" Then
                     &pageParameters.Push(CreateArray(&thisParameter.Name, &REC_PTPPB_USER_PRMS.PTPPB_VALUE.Value, "true"));
                  Else
                     /* No saved user value - just get default */
                     &pageParameters.Push(CreateArray(&thisParameter.Name, &thisParameter.evaluatedValue(), "true"));
                  End-If;
               End-If;
            End-If;
         End-For;

         /* Note - the pageParameters array may have invalid values... those will be checked prior to save */

         &isDefault = True;

         If Upper(%Request.GetParameter("PIAPortletURLType")) = "ACTIONURL" Then

            Evaluate &formAction
            When = "save"
               &isSaveOK = True;

               /* Check the current page parameters for validity */
               For &i = 1 To &thisGrouplet.DataSource.ParameterCollection.Count
                  &thisParameter = &thisGrouplet.DataSource.ParameterCollection.getItem(&i);
                  If &thisParameter.UsageType = &thisParameter.USAGETYPE_USERSPECIFIED Then
                     &pos = &pageParameters.Find(&thisParameter.Name);
                     &formValue = &pageParameters [&pos, 2];

                     /* Check to see if we have a default value  */
                     /* Set isDefault to false if we do not */
                     If &isDefault Then
                        &thisParameterDefault = &thisParameter.clone();
                        &thisParameterDefault.Value = &thisParameterDefault.DefaultValue;
                        If &formValue <> &thisParameterDefault.evaluatedValue() Then
                           /* This does not look like the default value - so set isDefault to false */
                           &isDefault = False;
                        End-If;
                     End-If;

                     /* Check the formValue to see if it would be an acceptable value for this field */
                     try
                        &RET = &thisParameter.setValueWithPromptValidation(&formValue, &GroupletID);
                     catch Exception &ex
                        &RET = False;
                     end-try;
                     If &RET Then
                        /* Mark the parameter as valid */
                        &pageParameters [&pos, 3] = "true";
                     Else
                        /* Mark the parameter as invalid */
                        &isSaveOK = False;
                        &pageParameters [&pos, 3] = "false";
                     End-If;

                  End-If;
               End-For;

               If &isSaveOK Then
                  /* All parameters look ok - save the parameter values, and trigger a switch over to view mode */
                  For &i = 1 To &thisGrouplet.DataSource.ParameterCollection.Count
                     &thisParameter = &thisGrouplet.DataSource.ParameterCollection.getItem(&i);
                     If &thisParameter.UsageType = &thisParameter.USAGETYPE_USERSPECIFIED Then
                        &pos = &pageParameters.Find(&thisParameter.Name);
                        &formValue = &pageParameters [&pos, 2];

                        &REC_PTPPB_USER_PRMS.PTPPB_GROUPLET_ID.Value = &GroupletID;
                        &REC_PTPPB_USER_PRMS.PTPPB_FIELDNAME.Value = &thisParameter.Name;
                        &REC_PTPPB_USER_PRMS.OPRID.Value = %UserId;
                        &REC_PTPPB_USER_PRMS.SelectByKey();
                        If &REC_PTPPB_USER_PRMS.PTPPB_VALUE.Value <> "" Then
                           &REC_PTPPB_USER_PRMS.Delete();
                        End-If;
                        If Not &isDefault Then
                           &REC_PTPPB_USER_PRMS.PTPPB_GROUPLET_ID.Value = &GroupletID;
                           &REC_PTPPB_USER_PRMS.PTPPB_FIELDNAME.Value = &thisParameter.Name;
                           &REC_PTPPB_USER_PRMS.OPRID.Value = %UserId;
                           &REC_PTPPB_USER_PRMS.PTPPB_VALUE.Value = &formValue;
                           &REC_PTPPB_USER_PRMS.Insert();
                        End-If;
                     End-If;
                  End-For;
                  &thisGrouplet = Null;
                  /* Now return back the mode shift to "view" */
                  Return createWSRPResponseWrapper("view", "", True, "", "");
               End-If;
               Break;
            When = "reset"
               /* Reset the parameters to their default values for this user */
               &isDefault = True;
               For &i = 1 To &thisGrouplet.DataSource.ParameterCollection.Count
                  &thisParameter = &thisGrouplet.DataSource.ParameterCollection.getItem(&i);
                  If &thisParameter.UsageType = &thisParameter.USAGETYPE_USERSPECIFIED Then
                     &pos = &pageParameters.Find(&thisParameter.Name);
                     &pageParameters [&pos, 2] = &thisParameter.DefaultValue;
                     &pageParameters [&pos, 3] = "true";
                  End-If;
               End-For;
               Break;
            When-Other
               /* formAction was not set, or value as not understood - simply display the current values */
               Break;
            End-Evaluate;

         End-If;

         /* Generate and render the edit page.  Add in errors as appropriate */
         &formRows = "";

         For &i = 1 To &thisGrouplet.DataSource.ParameterCollection.Count
            &thisParameter = &thisGrouplet.DataSource.ParameterCollection.getItem(&i);
            If &thisParameter.UsageType = &thisParameter.USAGETYPE_USERSPECIFIED Then
               &pos = &pageParameters.Find(&thisParameter.Name);

               &errMsg = "";
               If &pageParameters [&pos, 3] = "false" Then
                  &errMsg = GetHTMLText(HTML.PTPPB_EDIT_ERROR, MsgGetText(219, 380, "(Message Not Found) ""%1"" is not a valid value", &pageParameters [&pos, 2]));
               End-If;

               If &thisParameter.EditType = &thisParameter.EDITTYPE_TRANSLATETABLE Or
                     &thisParameter.EditType = &thisParameter.EDITTYPE_YESNO Then

                  /* first populate the option list, then the row */
                  &optionRows = "";
                  For &j = 1 To &thisParameter.Range.Len
                     If &pageParameters [&pos, 2] = &thisParameter.Range [&j, 1] Then
                        &optionRows = &optionRows | GetHTMLText(HTML.PTPPB_EDIT_OPTION_SELECTED, &thisParameter.Range [&j, 1], &thisParameter.Range [&j, 2]);
                     Else
                        &optionRows = &optionRows | GetHTMLText(HTML.PTPPB_EDIT_OPTION, &thisParameter.Range [&j, 1], &thisParameter.Range [&j, 2]);
                     End-If;
                  End-For;
                  &ParamRow = GetHTMLText(HTML.PTPPB_EDIT_ROW_DROPDOWN, &thisParameter.LongName, &thisParameter.Name, &optionRows, &errMsg);

               Else

                  /* No option list - just a simple form field entry */
                  &ParamRow = GetHTMLText(HTML.PTPPB_EDIT_ROW, &thisParameter.LongName, &thisParameter.Name, &pageParameters [&pos, 2], &errMsg);

               End-If;

               &formRows = &formRows | &ParamRow;
            End-If;
         End-For;

         &actionURL = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_PTGPLT, Field.ISCRIPT1, "FieldFormula", "IScript_GroupletBuilder");
         &actionURL = &actionURL | "?PTPPB_GROUPLET_ID=" | &GroupletID;
         &actionURL = SetActionURL(&actionURL, "edit", "", "");

         &NameSpaceID = %Request.GetParameter("PIAPortletNamespace");
         If &NameSpaceID = "" Then
            &NameSpaceID = "{piaportlet-namespace/}";
         End-If;

         &GpltHTML = GetHTMLText(HTML.PTPPB_EDIT_BASE, &actionURL, &NameSpaceID, &formRows, MsgGetText(219, 381, "(Message Not Found) Personalize %1", &thisGrouplet.Title), MsgGetText(219, 382, "(Message Not Found) Select options to personalize this portlet"), MsgGetText(219, 383, "(Message Not Found) Save"), MsgGetText(219, 384, "(Message Not Found) Cancel"), MsgGetText(219, 385, "(Message Not Found) Reset to Defaults"));

         Return createWSRPResponseWrapper("", "", True, "", &GpltHTML);
      End-If;
   End-If;
End-Function;

/* Function for Rendering a Grouplet Wizard Grouplet via JPDK */
/* Renders a grouplet using the pre-8.48 method of rendering for WSRP */
/* Only valid for JPDK requests - WSRP is now handled the same as any other homepage grouplet */
Function RenderGroupletJPDK
   Local string &PIAPortletMode, &ErrMsg;
   If Upper(%Request.GetParameter("PIAPortletWindowState")) <> "MINIMIZED" Then
      %Response.SetContentType("text/xml");
      &PIAPortletMode = Upper(%Request.GetParameter("PIAPortletMode"));
      Evaluate &PIAPortletMode
      When = "VIEW"
         If Upper(%Request.GetParameter("PIAPortletURLType")) <> "ACTIONURL" Then
            &PTPPB_THROWGROUPLETEXCEPTIONS = False;
            %Response.Write(createWSRPResponseWrapper("", "", False, "", RenderGpltWiz("WSRP")));
            Return;
         End-If;
         Break;
      When = "EDIT"
         %Response.Write(WSRPEdit());
         Return;
         Break;
      End-Evaluate;

      /* The mode/render/action is not supported. */
      &ErrMsg = MsgGetText(219, 334, "(Message not found) Unsupported request type.", &PIAPortletMode, %Request.GetParameter("PIAPortletURLType"));
      %Response.Write(createWSRPResponseWrapper("", "", False, "", &ErrMsg));

   End-If;
End-Function;


/* Iscript for Rendering the Grouplet Wizard Grouplet */
