      /* The mode/render/action is not supported. */
      &ErrMsg = MsgGetText(219, 334, "(Message not found) Unsupported request type.", &PIAPortletMode, %Request.GetParameter("PIAPortletURLType"));
      %Response.Write(createWSRPResponseWrapper("", "", False, "", &ErrMsg));

   End-If;


End-Function;

Declare Function PTGetStyleSheetURL PeopleCode FUNCLIB_PORTAL.PORTAL_GEN_FUNC FieldFormula;

Local array of string &jsArray;
Local array of string &cssArray;

Function getRequiredSystemJavaScripts() Returns string

   &jsArray.Push("'" | %Response.GetJavaScriptURL(HTML.PT_COMMON) | "'");
   &jsArray.Push("'" | %Response.GetJavaScriptURL(HTML.PT_AJAX_NET) | "'");
   &jsArray.Push("'" | %Response.GetJavaScriptURL(HTML.PT_ISCROSSDOMAINNS6) | "'");
   &jsArray.Push("'" | %Response.GetJavaScriptURL(HTML.PT_SAVEWARNINGSCRIPT) | "'");
   &jsArray.Push("'" | %Response.GetJavaScriptURL(HTML.PT_IFRAME_HDR_JS) | "'");

   &jsArray.Push("'" | %Response.GetJavaScriptURL(HTML.PT_RC_SERVICE_JS) | "'");
   &jsArray.Push("'" | %Response.GetJavaScriptURL(HTML.PT_RC_MENU_JS) | "'");
   &jsArray.Push("'" | %Response.GetJavaScriptURL(HTML.PT_RC_JS) | "'");
   Return &jsArray.Join(",", "[", "]");
End-Function;

Function getRequiredSystemStyleSheets() Returns string
   Local string &retHTML = "";

   &cssArray.Push("'" | %Response.GetStyleSheetURL(StyleSheet.PSSTYLEREQ) | "'");
   &cssArray.Push("'" | PTGetStyleSheetURL() | "'");

   Return &cssArray.Join(",", "[", "]");
End-Function;

Function IScript_GET_PORTAL_JS()
   &jsArray = CreateArrayRept("", 0);
   &cssArray = CreateArrayRept("", 0);
   Local string &jsHTML = getRequiredSystemJavaScripts();
   Local string &cssHTML = getRequiredSystemStyleSheets();
   &retHTML = GetHTMLText(HTML.WEBLIB_PTHDR, &jsHTML, &cssHTML);
   %Response.Write(&retHTML);
End-Function;

