Function IScript_PT_Popup()

   Local Request &req = %Request;

   REM example of an app package path is PT_FAV:AddToFav;
   Local string &contentAppPkgPath = &req.GetParameter("apppkgpath");
   Local string &params = EscapeHTML(&req.GetParameter("params"));
   Local string &title = EscapeHTML(&req.GetParameter("title"));
   Local string &btnType = &req.GetParameter("btntype");
   Local string &customTitleBarButtons = &req.GetParameter("customtitlebtns");

