/**
  * Called when a new PIA page is returned to get a list of search groups
  * available for current target content in the Global Search
  * 
*/
Function IScript_PT_GetSrchGrp()

   Local string &listHTML = "<ul id='ipthdr2srchlist' aria-expanded='true' role='listbox' aria-describedby='selsrchgrpspan'>";
   &listHTML = "<ul id='ipthdr2srchlist' aria-expanded='true' role='listbox' aria-describedby='selsrchgrp'>";
   Local string &OptionHTML = "<select id='srchgrplist' name='srchgrplist' style='display:none' aria-describedby='selsrchgrpspan'>";
   &OptionHTML = "<select id='srchgrplist' name='srchgrplist' style='display:none' aria-describedby='selsrchgrp'>";
   Local string &ctxtTypeHTML;
   Local number &i;
   Local object &ptusUtil = CreateObject("PTUS:Util");
   Local string &OptionTitle = "";
   Local string &sSelected = "";
   Local array of PTUS:SearchGroup &srchGrp;
   Local boolean &done = True;
   Local string &SelectedSrchGrp = Unencode(%Request.GetParameter("SEARCH_GROUP"));
   Local PTUS:SearchGroup &dfltSrchGrp;
   Local string &srcGrpName, &customURL;
   Local string &componentParm = "";
   Local string &componentCatParm = "";
   Local string &srchCtxtType;

   &componentParm = Unencode(%Request.GetParameter("PTUS_COMPONENT"));
   &componentCatParm = Unencode(%Request.GetParameter("PTUS_COMPONENTCAT"));

   Rem max length for searchcat is 65 and for it's description max length is 100;
   If (Len(&componentParm) > 100) Or
         (Len(&componentCatParm) > 65) Or
         (Find("<", &componentParm) > 0) Or
         (Find(">", &componentParm) > 0) Or
         (Find("=", &componentParm) > 0) Or
         (Find("=", &componentCatParm) > 0) Or
         (Find("""", &componentCatParm) > 0) Or
         (Find("<", &componentCatParm) > 0) Or
         (Find(">", &componentCatParm) > 0) Then
      &componentParm = "";
      &componentCatParm = "";
   End-If;

   &srchGrp = &ptusUtil.GetContextSearchGroups("H", "");
   &dfltSrchGrp = &ptusUtil.GetDefaultContextGroup("H", "");

   If &srchGrp <> Null Or
         &componentParm <> "" Then
      try
         /* set default search group */
         If &SelectedSrchGrp = "" Or
               &SelectedSrchGrp = "PTUS_ALL" Then
            If &componentCatParm <> "" Then
               &SelectedSrchGrp = &componentCatParm;
            Else
               If &dfltSrchGrp <> Null Then
                  &SelectedSrchGrp = &dfltSrchGrp.SearchGroupName;
               End-If;
            End-If;
         Else
            If &SelectedSrchGrp <> &componentCatParm Then
               /* default to current component search group if it is indexed */
               If &componentParm <> "" And
                     &componentCatParm <> "" Then
                  &SelectedSrchGrp = &componentCatParm;
               Else
                  Local boolean &foundDefault = False;
                  /* check if selected search group is in the list */
                  For &i = 1 To &srchGrp.Len
                     If &srchGrp [&i].SearchGroupName = &SelectedSrchGrp Then
                        &foundDefault = True;
                     End-If;
                  End-For;
                  If Not &foundDefault And
                        &dfltSrchGrp <> Null Then
                     &SelectedSrchGrp = &dfltSrchGrp.SearchGroupName;
                  End-If;
               End-If;
            End-If;
         End-If;

         /* populate the drop down list */
         For &i = 1 To &srchGrp.Len
            /* remove the search group if it is the same as component search category */
            If &componentParm <> "" And
                  &componentCatParm <> "" And
                  ((&componentCatParm = &srchGrp [&i].SearchGroupName) Or
                     (Find(&componentCatParm | "_", &srchGrp [&i].SearchGroupName) = 1)) And
                  (&componentParm = &srchGrp [&i].Decription) Then
               Continue;
            End-If;

            If &srchGrp [&i].SearchGroupName = &SelectedSrchGrp Then
               &sSelected = "selected = 'selected'";
            Else
               &sSelected = "";
            End-If;

            &listHTML = &listHTML | GetHTMLText(HTML.PTUS_HTML_LIST, &srchGrp [&i].SearchGroupName, &srchGrp [&i].Decription);

            /* populate hidden dropdown including url in the option text */
            &customURL = &srchGrp [&i].GetBasicSearchPageURL() | "," | &srchGrp [&i].GetAdvancedSearchPageURL();
            &OptionHTML = &OptionHTML | GetHTMLText(HTML.PTUS_HTML_DROPDOWN2, &srchGrp [&i].SearchGroupName, &sSelected, &OptionTitle, &customURL);

         End-For;

         /* add component only if it is indexed */
         If &componentParm <> "" And
               &componentCatParm <> "" Then

            If &SelectedSrchGrp = &componentCatParm Then
               &sSelected = "selected = 'selected'";
            Else
               &sSelected = "";
            End-If;
            &listHTML = &listHTML | GetHTMLText(HTML.PTUS_HTML_LIST, &componentCatParm, &componentParm);
            &OptionHTML = &OptionHTML | GetHTMLText(HTML.PTUS_HTML_DROPDOWN2, &componentCatParm, &sSelected, &OptionTitle, ","); /* set blank in custom URL */

         End-If;
      catch Exception &e

      end-try;

      &listHTML = &listHTML | "</ul>";
      &OptionHTML = &OptionHTML | "</select>";
      &srchCtxtType = &ptusUtil.GetCurrentContextType();
      &ctxtTypeHTML = "<input type='hidden' id='ptus_searchctxttype'  name='ptus_searchctxttype' value='" | &srchCtxtType | "'>";
      &listHTML = &listHTML | &OptionHTML | &ctxtTypeHTML;

      %Response.Write(&listHTML);
   Else
      %Response.Write("");
   End-If;

End-Function;

/**
  * Called when a new PIA page is returned to get a list of search groups
  * available for current target content in the Global Search
  * 
*/
Function IScript_PT_GetSrchGrpsList()

   Local string &listHTML;
   Local number &i;
   Local object &ptusUtil = CreateObject("PTUS:Util");
   Local string &sSelected = "";
   Local array of PTUS:SearchGroup &srchGrp;
   Local boolean &done = True;
   Local string &SelectedSrchGrp;
   Local PTUS:SearchGroup &dfltSrchGrp;
   Local string &srcGrpName, &customURL;

   Local array of PTUS:SearchGroup &allSrchGrp = &ptusUtil.GetAllSearchGroups();
   If ((&allSrchGrp <> Null) And
         (&allSrchGrp.Len > 1)) Then
      &srchGrp = &ptusUtil.GetContextSearchGroups("H", "");
      &dfltSrchGrp = &ptusUtil.GetDefaultContextGroup("H", "");
   End-If;

   If &srchGrp <> Null Then
      try
         /* set default search group */
         If &dfltSrchGrp <> Null Then
            &SelectedSrchGrp = &dfltSrchGrp.SearchGroupName;
         Else
            &SelectedSrchGrp = "PTUS_ALL";
         End-If;


         /* populate the drop down list */
         For &i = 1 To &srchGrp.Len
            If &srchGrp [&i].SearchGroupName = &SelectedSrchGrp Then
               &sSelected = "1";
            Else
               &sSelected = "0";
            End-If;

            &customURL = &srchGrp [&i].GetBasicSearchPageURL();

            &listHTML = &listHTML | &srchGrp [&i].SearchGroupName | "_:," | &sSelected | "_:," | &srchGrp [&i].Decription | "_:," | &customURL | "_:_END,";
         End-For;
      catch Exception &e
      end-try;

      %Response.Write(&listHTML);
   Else
      %Response.Write("");
   End-If;
End-Function;

