Function CheckPinToPermission(&loc As string) Returns boolean
   If (&loc = "") Then
      Return False;
   End-If;

   Evaluate &loc
   When "LP"
      If (IsMenuItemAuthorized(MenuName.PORTAL_PERS_HOMEPAGE, BarName.USE, ItemName.HOME_PAGE, Page.PORTAL_HPCOMP, %Action_UpdateDisplay) = True) And
            (IsUserInRole(&cstDISABLE_ADDTOLP_ROLE) = False) Then
         Return True;
      End-If;
      Break;

   When "NB"
      If (IsMenuItemAuthorized(MenuName.NUI_FRAMEWORK, BarName.USE, ItemName.PT_NAVBAR, Page.PTNUI_NAVBAR_PERS, %Action_UpdateDisplay) = True) And
            (IsUserInRole(&cstDISABLE_ADDTONB_ROLE) = False) Then
         Return True;
      End-If;
      Break;

   When "FAV"
      If (IsMenuItemAuthorized(MenuName.NUI_FRAMEWORK, BarName.USE, ItemName.PTNUI_MYFAV, Page.PTNUI_MYFAV_PG, %Action_UpdateDisplay) = True) And
            (IsUserInRole(&cstDISABLE_ADDTOFAV_ROLE) = False) Then
         Return True;
      End-If;
      Break;

   When "DBRD"
      If (IsMenuItemAuthorized(MenuName.PORTAL_PERS_HOMEPAGE, BarName.USE, ItemName.HOME_PAGE, Page.PORTAL_HPCOMP, %Action_UpdateDisplay) = True) Then
         Return True;
      End-If;
      Break;

   When-Other
      Return False;

   End-Evaluate;

   Return False;

End-Function;

Function IsPinToLocationAuth(&loc As string) Returns boolean
   <* Checks all the necessary permissions if the user is allowed to pin to or "add to" the given location (&loc). 
   Returns True if user is allowed to pin in the given location. Otherwise, return False *>

   If (IsIScriptAuthorized("WEBLIB_PTNUI", "PT_BUTTON_PIN", "FieldFormula", "IScript_SavePin", %Action_UpdateDisplay) = False) Then
      Return False;
   End-If;

   Return CheckPinToPermission(&loc);
End-Function;


Function CheckPinToRoleExclude() Returns array of string;
   /* Check if user is assigned a role excluding them from the pin to functions */
   /* Used by Fluid Header Page and Classic Portal Header */
   Local array of string &arrExclude = CreateArray("", 0);

   If (IsMenuItemAuthorized(MenuName.PORTAL_PERS_HOMEPAGE, BarName.USE, ItemName.HOME_PAGE, Page.PORTAL_HPCOMP, %Action_UpdateDisplay) = False Or
         IsUserInRole(&cstDISABLE_ADDTOLP_ROLE) = True) Then
      &arrExclude.Push("LP");
   End-If;
   If (IsMenuItemAuthorized(MenuName.NUI_FRAMEWORK, BarName.USE, ItemName.PT_NAVBAR, Page.PTNUI_NAVBAR_PERS, %Action_UpdateDisplay) = False Or
         IsUserInRole(&cstDISABLE_ADDTONB_ROLE) = True) Then
      &arrExclude.Push("NB");
   End-If;
   If (IsMenuItemAuthorized(MenuName.NUI_FRAMEWORK, BarName.USE, ItemName.PTNUI_MYFAV, Page.PTNUI_MYFAV_PG, %Action_UpdateDisplay) = False Or
         IsUserInRole(&cstDISABLE_ADDTOFAV_ROLE) = True) Then
      &arrExclude.Push("FAV");
   End-If;

   Return &arrExclude;
End-Function;

/*
*  Get URL node
*/
Function GetURLNode(&pUrl As string) Returns string
   /* Process the URL */
   Local string &urlNode;
   Local array of string &urlParts;
   &urlParts = Split(&pUrl, "/");
   Local integer &arrIdxSrvlt = 0;
   Local integer &i;
   For &i = 1 To &urlParts.Len
      If (&urlParts [&i] = "psc") Or
            (&urlParts [&i] = "psp") Then
         &arrIdxSrvlt = &i;
         Break;
      End-If;
   End-For;
   If (&arrIdxSrvlt <> 0) Then
      /* this is a peoplesoft URL */
      /* Get the node name from URL */
      &urlNode = &urlParts [&arrIdxSrvlt + 3];
   End-If;

   Return &urlNode;
End-Function;

Function FindPinnedObj(&pLoc As string, &pUrl As string, &bDelete As boolean) Returns boolean
   /* Used by PINTO API */
   Local integer &i, &j;
   Local boolean &found = False;

   Local PTNUI:Model:LandingPageTab &lpt;
   Local array of PTNUI:Model:LandingPageTab &lptList, &lpDelList;
   Local PTNUI:Model:Tile &tile;
   Local array of PTNUI:Model:Tile &tileList;
   Local string &npUrl;

   /* Check permission first before doing any delete action in homepage or dashboard */
   If (&bDelete And
         ((&pLoc = "LP") Or
            (&pLoc = "DBRD"))) Then
      If (IsMenuItemAuthorized(MenuName.PORTAL_PERS_HOMEPAGE, BarName.USE, ItemName.HOME_PAGE, Page.PORTAL_HPCOMP, %Action_UpdateDisplay) = False) Then
         /* Delete not allowed if user has no permission to personalize homepage or dashboard */
         If (&pLoc = "LP") Then
            MessageBox(0, "", 95, 10251, "Fail: User not allowed to personalize %1", MsgGetText(95, 10001, "Homepage"));
            Return False;
         End-If;
         If (&pLoc = "DBRD") Then
            MessageBox(0, "", 95, 10251, "Fail: User not allowed to personalize %1", MsgGetText(240, 1035, "Dashboard"));
            Return False;
         End-If;
      End-If;
   End-If;

   ResetUniNavLandingPageHandler(); /* to get latest view of LPs, needed to catch newly created LPs at current session */
   &npUrl = StripSiteNewWin("psc|psp", &pUrl);
   &npUrl = EncodeURL(Unencode(&npUrl)); /* double-check */
   &lpDelList = CreateArrayRept(&lpt, 0);

   Evaluate &pLoc
   When "LP"
      &lptList = GetAllLandingPageTabListForPortal(%Portal);
      Break;
   When "DBRD"
      Local string &node = GetURLNode(&npUrl);
      &lptList = GetDashboardListForPortal(%Portal, &node);
      Break;
   End-Evaluate;

   For &i = 1 To &lptList.Len
      &lpt = &lptList [&i];
      If (&lpt.IsSysTab Or
            &lpt.HasUserData) Then
         &tileList = &lpt.GetTiles();
         For &j = 1 To &tileList.Len
            &tile = &tileList [&j];
            If &tile.IsPinnedTile And
                  ((&tile.GltContentActionUrl = &npUrl) Or
                     (&tile.GltPortalActionUrl = &npUrl)) Then
               &found = True;
               If (&bDelete) Then
                  &lpt.DeleteTileById(&tile.ID);
                  &lpDelList.Push(&lpt);
                  &lpt.IsChanged = True;
               End-If;
               Break;
            End-If;
         End-For;
      End-If;
   End-For;

   If &bDelete And
         (&lpDelList.Len > 0) Then
      SaveLandingPageTabListForPortal(%Portal, &lpDelList);
   End-If;
   Return &found;

End-Function;

Function DeleteLPPinned(&pUrl As string) Returns boolean
   /* API that will called and used by Apps and other Tools team */
   /* Will delete given pinned URL from all fluid homepages including cluster environment. 
      Will return true if pinned url is found and deleted, else return false when not found.
   */
   Return FindPinnedObj("LP", &pUrl, True);
End-Function;

Function IsThisLPPinned(&pUrl As string) Returns boolean
   /* API that will be called and used by Apps and other Tools team */
   /* Will check if given pinned URL  is found from any fluid homepages including those in cluster environment.
      Will return true if pinned url is found, else return false when not found.
   */
   Return FindPinnedObj("LP", &pUrl, False);
End-Function;

Function IScript_DeleteLPPinned()
   Local string &pinURL = %Request.GetParameter("url");
   Local boolean &ret = DeleteLPPinned(&pinURL);
   %Response.Write(String(&ret));
End-Function;

Function GetUnifiedLandingPageListJSON(&pPortalReg As ApiObject, &pUrl As string, &pLoc As string) Returns string

   Local integer &i, &j;
   Local string &outStr, &found;

   Local PTNUI:Model:LandingPageTab &lpt;
   Local array of PTNUI:Model:LandingPageTab &lptList;
   Local PTNUI:Model:Tile &tile;
   Local array of PTNUI:Model:Tile &tileList;

   ResetUniNavLandingPageHandler(); /* to get latest view of LPs */

   Evaluate &pLoc
   When "LP"
      &lptList = GetLandingPageTabListForPortal(&pPortalReg.Name);
      Break;
   When "DBRD"
      Local string &urlNode = GetURLNode(&pUrl);
      &lptList = GetDashboardListForPortal(&pPortalReg.Name, &urlNode);
   End-Evaluate;

   &outStr = "";

   &pUrl = Unencode(&pUrl);
   For &i = 1 To &lptList.Len
      &lpt = &lptList [&i];
      /* 861-Lock */
      If &lpt.IsPersonalizable Then
         If (&lpt.IsSysTab Or
               &lpt.HasUserData) Then

            &found = "n";
            &tileList = &lpt.GetTiles();
            For &j = 1 To &tileList.Len
               &tile = &tileList [&j];
               If (Unencode(&tile.GltContentActionUrl) = &pUrl) Or
                     (Unencode(&tile.GltPortalActionUrl) = &pUrl) Then
                  &found = "y";
                  Break;
               End-If;
            End-For;

            &outStr = &outStr | " { ""name"": """ | EscapeHTML(&lpt.ID) | """, ""label"": """ | EscapeHTML(&lpt.Label) | """, ""exists"": """ | &found | """ }" | ", ";

         End-If;
      End-If;
   End-For;

   If All(&outStr) Then
      &outStr = "[" | RTrim(&outStr, ", ") | "]";
   End-If;

   Return &outStr;

End-Function;


Function PinToLandingPageObject(&pLandingPageTab As PTNUI:Model:LandingPageTab, &crefLabel As string, &crefURL As string, &crefNode As string, &crefName As string, &tileParam As string) Returns boolean

   Local string &tileName;

   Local Record &rec;

   Local PTNUI:Model:Tile &tile;

   If None(&pLandingPageTab) Then
      Return False;
   End-If;

   /* Put the data in the record first */
   &rec = CreateRecord(Record.PT_PORTAL_PINTO);
   &rec.PORTAL_LABEL.Value = Unencode(&crefLabel);
   &rec.PORTAL_SEQ_NUM.Value = 9999;
   &rec.PORTAL_HOSTNODENAM.Value = &crefNode;
   &rec.PORTAL_CREF_NAME.Value = &crefName;
   &rec.PORTAL_URLTEXT.Value = Unencode(&crefURL);
   &rec.PTTILEURLPARAM.Value = Unencode(&tileParam);
   /* Create the tile object and add to the tab */
   &tileName = "TILE_" | Substitute((String(%PerfTime) | String(Int(Rand() * 100000))), ".", "");

   &tile = create PTNUI:Model:Tile(&pLandingPageTab.NodeName, &pLandingPageTab.PortalName, &tileName, "");
   &tile.SetPropertiesFromPinnedPglt(&rec);
   /* Required in cluster env */
   &tile.GltContentActionUrl = &rec.PORTAL_URLTEXT.Value;
   &tile.GltPortalActionUrl = &rec.PORTAL_URLTEXT.Value;

   If Not &pLandingPageTab.HasUserData Then
      &pLandingPageTab.MarkOptionalTilesForDelete();
   End-If;
   &pLandingPageTab.AddTile(&tile);
   &pLandingPageTab.IsChanged = True;

   /* Save the tab */
   SaveLandingPageTabListForPortal(&pLandingPageTab.PortalName, CreateArray(&pLandingPageTab));

   ResetUniNavLandingPageHandler();

   Return True;

End-Function;


Function PinToLandingPage(&pPortalReg As ApiObject, &lpId As string, &crefLabel As string, &crefURL As string, &crefNode As string, &crefName As string, &tileParam As string, &pLoc As string) Returns boolean

   Local integer &i;

   Local PTNUI:Model:LandingPageTab &lpt;
   Local array of PTNUI:Model:LandingPageTab &lptList;

   Evaluate &pLoc
   When "LP"
      &lptList = GetLandingPageTabListForPortal(&pPortalReg.Name);
      Break;
   When "DBRD"
      Local string &urlNode = GetURLNode(&crefURL);
      &lptList = GetDashboardListForPortal(&pPortalReg.Name, &urlNode);
      Break;
   End-Evaluate;


   For &i = 1 To &lptList.Len
      &lpt = &lptList [&i];
      If (&lpt.ID = &lpId) Then
         Return PinToLandingPageObject(&lpt, &crefLabel, &crefURL, &crefNode, &crefName, &tileParam);
      End-If;
   End-For;

   Return False;

End-Function;

Function getMainPartURL(&sURL As string) Returns string
   /* Function that parses Peoplesoft type URL to return just the last main part of the url after the site name part */
   Local integer &i = 0;
   Local string &lastPartURL = "";

   &i = Find("/psc/", &sURL);
   If (&i <= 0) Then
      &i = Find("/psp/", &sURL);
   End-If;
   If (&i > 0) Then
      REM Parse peoplesoft type URL;
      &lastPartURL = Substring(&sURL, &i + 5, Len(&sURL));
      &i = Find("/", &lastPartURL); /* go past sitename, and get index of the portal name */
      &lastPartURL = Substring(&lastPartURL, &i, Len(&sURL)); /* /portal/node/.... */
      Return &lastPartURL;
   Else
      Return &sURL; /* Just return the same URL back in-case this is non-peoplesoft type URL */
   End-If;
End-Function;

Function getTileFromNavBar(&lpt As PTNUI:Model:LandingPageTab, &crefURL As string) Returns PTNUI:Model:Tile
   /* Finds the tile fron the NavBar given the URL. Returns Null if not found */

   Local string &lastPartURL = "";
   Local string &lastPartCrefURL = "";
   Local array of PTNUI:Model:Tile &tileList;
   Local integer &j = 1;

   &lastPartCrefURL = Unencode(getMainPartURL(&crefURL));
   &tileList = &lpt.GetTiles();
   For &j = 1 To &tileList.Len
      &lastPartURL = Unencode(getMainPartURL(&tileList [&j].GltContentActionUrl));
      If (&lastPartURL = &lastPartCrefURL) Then
         Return &tileList [&j];
         Break;
      End-If;
   End-For;
   Return Null;
End-Function;

Function PinToNavBar(&pPortalReg As ApiObject, &crefLabel As string, &crefURL As string, &crefNode As string, &crefName As string, &errorMsg As string, &tileParam As string) Returns boolean
   Local PTNUI:Model:Tile &testTile;
   Local PTNUI:Model:LandingPageTab &lpt;

   If (&crefLabel = "" And
         &crefName = "") Then
      &errorMsg = MsgGetText(95, 10106, "Missing Label and crefID. Fail to Add To ", MsgGetText(219, 7478, "NavBar"));
      Return False;
   End-If;

   &lpt = GetNavBarForPortal(&pPortalReg.Name);
   If ((&crefURL = "") Or
         None(&lpt)) Then
      &errorMsg = ""; /*Leave errorMsg as blank and calling function will display default error response */
      Return False;
   End-If;
   &testTile = getTileFromNavBar(&lpt, &crefURL);
   If (&testTile <> Null) Then
      &errorMsg = MsgGetText(95, 10128, "This has already been added as ", EscapeHTML(&testTile.Label));
      Return False;
   End-If;
   Return PinToLandingPageObject(&lpt, &crefLabel, &crefURL, &crefNode, &crefName, &tileParam);

End-Function;


Function PinToUserLandingPage(&pPortalReg As ApiObject, &lpLabel As string, &crefLabel As string, &crefURL As string, &crefNode As string, &crefName As string, &tileParam As string) Returns boolean

   Local integer &i;

   Local string &lpname;
   Local ApiObject &userTab, &sysTab;

   Local PTNUI:Model:LandingPageTab &lpt, &lptab;
   Local array of PTNUI:Model:LandingPageTab &lptList;

   For &i = 1 To 10
      &lpname = "USERDEFINEDLP" | &i;
      &userTab = &pPortalReg.LandingPage.UserTabs.ItemByName(&lpname);
      If None(&userTab) Then
         &lpt = create PTNUI:Model:LandingPageTab(%Node, %Portal, &lpname);
         &lpt.Label = &lpLabel;
         Break;
      End-If;
   End-For;

   /* set tab sequence number */
   If &lpt <> Null Then
      Local number &maxSeq = 0;
      &lptList = GetLandingPageTabListForPortal(&pPortalReg.Name);
      If &lptList <> Null Then
         For &i = 1 To &lptList.Len
            &lptab = &lptList [&i];
            If (&lptab.HasUserData Or
                  (&lptab.LayoutBehavior = "3DEF" And
                     &lptab.ActiveFlag <> "N") Or
                  &lptab.LayoutBehavior = "2REQ" Or
                  &lptab.LayoutBehavior = "1FIX") Then
               If &lptab.SeqNum > &maxSeq Then
                  &maxSeq = &lptab.SeqNum;
               End-If;
            End-If;
         End-For;
         &lpt.SeqNum = &maxSeq + 1;
      End-If;
   End-If;

   Return PinToLandingPageObject(&lpt, &crefLabel, &crefURL, &crefNode, &crefName, &tileParam);

End-Function;


Function IScript_ShowPinMenu()

   Local string &url = "PTPinTo.SavePin";
   Local string &url_lp = &url | "('LP')";
   Local string &url_nb = &url | "('NB')";
   Local string &url_fav = &url | "('FAV')";

   Local string &link_lp = "";
   Local string &link_nb = "";
   Local string &link_fav = "";
   Local string &menu, &html;

   Local string &theme = %Request.GetParameter("setClassicFluidHeaderFlag");
   Local string &iscript_sid = (create PTNUI:NavBarContentArea:Security("ptnbsid")).getSSIDLocal;

   Local boolean &bAuthPinLP = True;
   Local boolean &bAuthPinNB = True;
   Local boolean &bAuthPinFav = True;

   Local array of string &arrExclude = CheckPinToRoleExclude();
   If &arrExclude.Len > 0 Then
      If &arrExclude.Find("LP") > 0 Then
         &bAuthPinLP = False;
      End-If;
      If &arrExclude.Find("NB") > 0 Then
         &bAuthPinNB = False;
      End-If;
      If &arrExclude.Find("FAV") > 0 Then
         &bAuthPinFav = False;
      End-If;
   End-If;

   If Find("true", &theme) > 0 Then
      If (&bAuthPinLP) Then
         &link_lp = GetHTMLText(HTML.PTNUI_PINTO_LINK_FLUIDHDR, &url_lp, EscapeHTML(MsgGetText(95, 10103, "Add To Homepage")), "addToHomepageId");
      End-If;
      If (&bAuthPinNB) Then
         &link_nb = GetHTMLText(HTML.PTNUI_PINTO_LINK_FLUIDHDR, &url_nb, EscapeHTML(MsgGetExplainText(95, 10102, "Add To NavBar")), "addToNavbarId");
      End-If;
      If (&bAuthPinFav) Then
         &link_fav = GetHTMLText(HTML.PTNUI_PINTO_LINK_FLUIDHDR, &url_fav, EscapeHTML(MsgGetText(95, 10101, "Add To Favorites")), "addToFavoritesId");
      End-If;
      &html = "PTNUI_PINTO_HTML_FLUIDHDR";
   Else
      If (&bAuthPinLP) Then
         &link_lp = GetHTMLText(HTML.PTNUI_PINTO_LINK, &url_lp, MsgGetText(95, 10001, "Homepage"));
      End-If;
      If (&bAuthPinNB) Then
         &link_nb = GetHTMLText(HTML.PTNUI_PINTO_LINK, &url_nb, MsgGetText(95, 10000, "NavBar"));
      End-If;
      If (&bAuthPinFav) Then
         &link_fav = GetHTMLText(HTML.PTNUI_PINTO_LINK, &url_fav, MsgGetText(95, 405, "Favorites"));
      End-If;
      &html = "PTNUI_PINTO_HTML";
   End-If;

   &menu = GetHTMLText(@("HTML." | &html), &link_lp, &link_nb, &link_fav, &iscript_sid);

   %Response.Write(&menu);

End-Function;


Function GetThemeCookieNode Returns string
   Local string &cookieValue = %Request.GetCookieValue("ps_theme");
   Local integer &i;
   Local array of string &values, &thisPair;
   Local string &CookieSeperator = " ";

   &values = Split(RTrim(&cookieValue, " " | &CookieSeperator), &CookieSeperator);

   For &i = 1 To &values.Len
      &thisPair = Split(&values [&i], ":");
      If ((&thisPair.Len = 2) And
            (&thisPair [1] = "node")) Then
         Return &thisPair [2];
      End-If;
   End-For;
   Return "";
End-Function;


Function PinToCSRFTest(&ptpinsid As string, &randInput As string, &hashOutput As string) Returns boolean
   Local boolean &bSIDTest = False;
   Local PTNUI:NavBarContentArea:Security &sidNUI = create PTNUI:NavBarContentArea:Security("ptnbsid");

   /* Case when the Pin Request maybe a local request, do the simple test */
   If (&sidNUI.sidPassTest) Then
      &bSIDTest = True;
   Else
      If (&ptpinsid = "") Then
         WriteToLog(%ApplicationLogFence_Error, MsgGetText(95, 10155, "First Pass of AddTo SID Test Failed. Missing ptnbsid value"));
      End-If;
   End-If;

   /* Second Test:Check case when the Pin Request is remote and we are in a Cluster Environment */
   If (&bSIDTest = False) Then
      Local string &nodeCheckToken = "";
      Local string &errStr = MsgGetText(95, 10150, "AddTo Hashed SID Test Failed");
      Local string &tokenVal = %Request.GetCookieValue("PS_TOKEN");
      If ((&randInput <> "") And
            (&hashOutput <> "") And
            (&tokenVal <> "")) Then
         Local PT_IB_NODE:NodeDefinition &localNodeDefn = create PT_IB_NODE:NodeDefinition(%LocalNode);
         &nodeCheckToken = &localNodeDefn.checkTokenID;
         Local string &secToken = &nodeCheckToken | "|" | &tokenVal;
         Local string &myHash = HashWithSalt(&secToken, &randInput);
         If VerifyHash(&secToken, &randInput, &hashOutput) Then
            &bSIDTest = True;
         Else
            &errStr = &errStr | MsgGetText(95, 10151, "Received values to test:%1", "ptpinrand=" | &randInput | "&ptpinhash=" | &hashOutput);
            WriteToLog(%ApplicationLogFence_Error, &errStr);
         End-If;
      Else
         If ((&randInput = "") Or
               (&hashOutput = "")) Then
            &errStr = &errStr | MsgGetText(95, 10152, "Missing required values from request. Requesting Application must be at PT8.56.xx or higher");
            &errStr = &errStr | MsgGetText(95, 10153, "See documentation on AddTo Security. To disable security check, see documentation.");
            WriteToLog(%ApplicationLogFence_Error, &errStr);
         End-If;
         If (&tokenVal = "") Then
            &errStr = MsgGetText(95, 10154, "AddTo Hashed SID Test Failed. Missing PS_TOKEN cookie value.");
            WriteToLog(%ApplicationLogFence_Error, &errStr);
         End-If;
      End-If;
   End-If;

   Return &bSIDTest;
End-Function;

Function IScript_SavePin()

   Local Request &r = %Request;

   Local integer &i;
   Local string &loc;
   Local string &lpName, &lpLabel, &newLpLabel;
   Local string &crefLabel, &crefURL, &crefNode, &crefName;
   Local string &siteName, &stateNumber;
   Local array of string &urlParts, &siteNameParts;
   Local string &targURLParam, &tileURLParam;

   Local ApiObject &p;
   Local ApiObject &cref;
   Local string &resp;
   Local string &errorMsg = "";
   Local string &apiCall = &r.GetParameter("apiCall"); /* identify if called via apiCall or Tools call */

   /* SID TEST */
   If (%AddToSidTest <> "N") And
         (%AddToSidTest <> "n") Then
      Local boolean &bSIDTestResult = PinToCSRFTest(&r.GetParameter("ptnbsid"), &r.GetParameter("ptpinrand"), &r.GetParameter("ptpinhash"));
      If (&bSIDTestResult = False) Then
         &errorMsg = MsgGetText(95, 10139, "Fail:Unauthorized Request.");
         &resp = "[ { ""ERROR"": ""SID"", ""ERRTEXT"": """ | &errorMsg | """ } ]";
         %Response.Write(&resp);
         Return; /* Quit as security test failed */
      End-If;
   End-If;
   /* END OF SID TEST */

   &loc = &r.GetParameter("loc");

   &lpName = &r.GetParameter("lp");
   &newLpLabel = &r.GetParameter("newlp");
   &lpLabel = &r.GetParameter("label");
   If &lpLabel = "" Then
      &lpLabel = &lpName;
   End-If;
   &targURLParam = &r.GetParameter("targParam");
   &tileURLParam = &r.GetParameter("tileParam");
   &crefURL = &r.GetParameter("url");

   /* Check if user is allowed to pin in the given location */
   If (CheckPinToPermission(&loc) = False) Then
      &errorMsg = MsgGetText(95, 10250, "User not allowed to add to this location.");
      &resp = "[ { ""ERROR"": """ | &loc | """, ""ERRTEXT"": """ | &errorMsg | """ } ]";
      %Response.Write(&resp);
      Return;
   End-If;

   /* Verify the url to pin is from a registered node */
   If ((&loc = "LP" Or
         &loc = "DBRD" Or
         &loc = "NB") And
         (IsURLFromCurrServer(&crefURL) = False) And
         (IsFromRegisteredNode(&crefURL) = False)) Then
      /* Reject request*/
      &errorMsg = MsgGetText(95, 10138, "Fail:This URL is not allowed to be added.");
      &resp = "[ { ""ERROR"": """ | &loc | """, ""ERRTEXT"": """ | &errorMsg | """ } ]";
      %Response.Write(&resp);
      Return;
   End-If;

   /* See if this is from an apiCall. If yes, ensure passed URL params are encoded */
   /* Tools will always pass URL as encoded but cannot rely on other non-Tools teams to always do so, so make sure it's encoded properly */
   If (&apiCall = "1") Then
      &targURLParam = EncodeURL(Unencode(&targURLParam));
      &tileURLParam = EncodeURL(Unencode(&tileURLParam));
      &crefURL = EncodeURL(Unencode(&crefURL));
   End-If;

   &crefNode = %Node;
   rem &crefNode = &r.GetParameter("crefNode");
   &crefName = &r.GetParameter("crefName");
   &crefLabel = &r.GetParameter("crefLabel");

   /* Process the URL */
   &urlParts = Split(&crefURL, "/");
   Local integer &arrIdxSrvlt = 0;
   Local integer &j;
   For &j = 1 To &urlParts.Len
      If (&urlParts [&j] = "psc") Or
            (&urlParts [&j] = "psp") Then
         &arrIdxSrvlt = &j;
         Break;
      End-If;
   End-For;
   If (&arrIdxSrvlt <> 0) Then
      /* this is a peoplesoft URL */
      /* Get the node name from URL */
      &crefNode = &urlParts [&arrIdxSrvlt + 3];

      /* Remove the state number from URL, if any */
      &siteName = &urlParts [&arrIdxSrvlt + 1];
      &siteNameParts = Split(&siteName, "_");
      &stateNumber = &siteNameParts [&siteNameParts.Len];
      If IsDigits(&stateNumber) Then
         &urlParts [&arrIdxSrvlt + 1] = Left(&siteName, Len(&siteName) - Len(&stateNumber) - 1);
         &crefURL = &urlParts.Join("/", "", "");
      End-If;
   End-If;
   /* end of process url */

   &p = PortalOpen();

   /* Try find a CRef first */
   &cref = Null;
   If All(&crefName) Then
      &cref = &p.FindCrefByName(&crefName);
   End-If;

   If None(&cref) Then
      &cref = &p.FindCrefByURL(&crefURL);
      If None(&cref) Then
         &cref = &p.FindCrefForURL(&crefURL);
      End-If;
   End-If;

   If None(&cref) Then
      Local array of string &arrTemp = Split(&crefURL, "/e/?url=");
      If &arrTemp.Len > 1 Then
         Local string &strExtUrl = &arrTemp [2];
         &cref = &p.FindCRefByURL(Unencode(&strExtUrl));

         If All(&cref) Then
            &crefName = &cref.name;
         End-If;

      End-If;
   End-If;

   If All(&cref) And
         None(&crefLabel) Then
      &crefName = &cref.name;
      Local string &addto_title = GetAttribute(&cref, "ADDTO_TITLE");
      If All(&addto_title) Then
         &crefLabel = &addto_title;
      End-If;

      If None(&crefLabel) Then
         &crefLabel = &cref.label;
      End-If;

   End-If;

   &resp = MsgGetText(95, 10032, "MNF-Added %1 to", EscapeHTML(&crefLabel)) | " ";

   If (&targURLParam <> "") Then
      If (Find("?", &crefURL) <= 0) Then
         &crefURL = &crefURL | "?";
      Else
         If (Right(&crefURL, 1) <> "&") Then
            &crefURL = &crefURL | "&";
         End-If;
      End-If;
      &crefURL = &crefURL | &targURLParam;
   End-If;

   Evaluate &loc
   When "LP"
      If (&crefLabel = "" And
            &crefName = "") Then
         Local string &errTxt = MsgGetText(95, 10106, "Missing Label and crefID. Failed to Add to %1.", MsgGetText(95, 10001, "Homepage"));
         &resp = "[ { ""ERROR"": ""LP"", ""ERRTEXT"": """ | &errTxt | """ } ]";
         Break;
      End-If;
      If None(&lpName) Then
         If &newLpLabel <> "" Then
            rem create a new user defined landing page;
            If PinToUserLandingPage(&p, &newLpLabel, &crefLabel, &crefURL, &crefNode, &crefName, &tileURLParam) Then
               &resp = &resp | EscapeHTML(&newLpLabel) | " " | MsgGetText(95, 10001, "Homepage");
            Else
               &resp = MsgGetText(95, 10025, "MNF-Unable to add '%1' to '%2'", EscapeHTML(&crefLabel), EscapeHTML(&newLpLabel) | " " | MsgGetText(95, 10001, "Homepage"));
            End-If;
         Else
            rem get list of lp and return to browser for selection;
            &resp = GetUnifiedLandingPageListJSON(&p, &crefURL, &loc);
         End-If;
      Else
         If PinToLandingPage(&p, &lpName, &crefLabel, &crefURL, &crefNode, &crefName, &tileURLParam, &loc) Then
            &resp = &resp | UnEscapeHTML(EscapeHTML(&lpLabel)) | " " | MsgGetText(95, 10001, "Homepage");
         Else
            &resp = MsgGetText(95, 10025, "MNF-Unable to add '%1' to '%2'", EscapeHTML(&crefLabel), EscapeHTML(&lpLabel) | " " | MsgGetText(95, 10001, "Homepage"));
         End-If;
      End-If;
      Break;

   When "NB"
      If PinToNavBar(&p, &crefLabel, &crefURL, &crefNode, &crefName, &errorMsg, &tileURLParam) Then
         &resp = &resp | MsgGetText(95, 10000, "NavBar");
      Else
         If (&errorMsg <> "") Then
            &resp = &errorMsg; /* reply via returned &errorMsg */
         Else
            &resp = MsgGetText(95, 10025, "MNF-Unable to add '%1' to '%2'", EscapeHTML(&crefLabel), MsgGetText(95, 10000, "NavBar")); /* default */
         End-If;
      End-If;
      Break;

   When "FAV"
      If None(&cref) And
            Not IsRemotePIANode(&crefNode) Then
         rem do additional checking here for uninav tiles;
         &resp = MsgGetText(95, 5500, "This page can't be added as a favorite, because it is not registered in this portal.");
      Else
         If IsRemotePIANode(&crefNode) Then
            &crefName = "PTUN_DUMMYFAV";
         End-If;
         Local ApiObject &favs = &p.Favorites;
         Local ApiObject &fav = &favs.insertitem(UnEscapeHTML(&crefLabel), &crefName); /* Un-escaped label saved in DB */

         If &fav = Null Then
            rem check if favorite already exists. and inform user if it does;
            &resp = MsgGetText(95, 10105, "%1 is already added to '%2'", EscapeHTML(&crefLabel), MsgGetText(95, 405, "Favorites"));
         Else
            REM  Check if it is Activity Guide.If so, URL might contain paramters;
            REM  So take the &crefURL ;
            Local number &pos_AG = Find("NUI_FRAMEWORK.PT_AGSTARTPAGE_NUI", &fav.URL);
            If IsRemotePIANode(&crefNode) Or
                  &pos_AG <> 0 Then
               &fav.URL = &crefURL;
            Else
               REM code added to add fan page folder in fav. working in older release.Stop working from 8.57;
               If Find("WEBLIB_PTPP_SC.HOMEPAGE.FieldFormula.IScript_AppHP", &crefURL) > 0 Then
                  Local number &pos = Find("pt_fname=", &crefURL);
                  If (&pos <> 0) Then
                     &ptfname = Substring(&crefURL, &pos, 1 + Len(&crefURL));
                     If All(&ptfname) Then
                        &fav.URL = &cref.URL | "?favkeys=start&" | &ptfname;
                     End-If;
                  End-If;
               End-If;
            End-If;
            &favs.save();
            &resp = &resp | MsgGetText(95, 405, "Favorites");
         End-If;
      End-If;
      Break;

   When "DBRD"
      If (&crefLabel = "" And
            &crefName = "") Then
         &errTxt = MsgGetText(95, 10106, "Missing Label and crefID. Failed to Add to %1.", MsgGetText(240, 1035, "Dashboard"));
         &resp = "[ { ""ERROR"": ""DBRD"", ""ERRTEXT"": """ | &errTxt | """ } ]";
         Break;
      End-If;

      If None(&lpName) Then
         rem get list of dashboards and return to browser for selection;
         &resp = GetUnifiedLandingPageListJSON(&p, &crefURL, &loc);
         If &resp = "" Then
            &errTxt = MsgGetText(95, 10137, "No authorized %1.", MsgGetText(240, 1035, "Dashboard"));
            &resp = "[ { ""ERROR"": ""DBRD"", ""ERRTEXT"": """ | &errTxt | """ } ]";
         End-If;

      Else
         If PinToLandingPage(&p, &lpName, &crefLabel, &crefURL, &crefNode, &crefName, &tileURLParam, &loc) Then
            &resp = &resp | UnEscapeHTML(EscapeHTML(&lpLabel)) | " " | MsgGetText(240, 1035, "Dashboard");
         Else
            &resp = MsgGetText(95, 10025, "MNF-Unable to add '%1' to '%2'", EscapeHTML(&crefLabel), EscapeHTML(&lpLabel) | " " | MsgGetText(240, 1035, "Dashboard"));
         End-If;
      End-If;
      Break;

   End-Evaluate;

   &p.close();
   %Response.Write(&resp);

End-Function;


Function DeleteDBRDPinned(&pUrl As string) Returns boolean
   /* API that will called and used by Apps and other Tools team */
   /* Will delete given pinned URL from all fluid dashboards within the url node, whether local or from a cluster environment. 
      Will return true if pinned url is found and deleted, else return false when not found.
   */
   Return FindPinnedObj("DBRD", &pUrl, True);
End-Function;


Function IsThisDBRDPinned(&pUrl As string) Returns boolean
   /* API that will be called and used by Apps and other Tools team */
   /* Will check if given pinned URL  is found from any fluid dashboards within the url node, whether local or from a cluster environment.
      Will return true if pinned url is found, else return false when not found.
   */
   Return FindPinnedObj("DBRD", &pUrl, False);
End-Function;


Function IScript_DeleteDBRDPinned()
   Local string &pinURL = %Request.GetParameter("url");
   Local boolean &ret = DeleteDBRDPinned(&pinURL);
   %Response.Write(String(&ret));
End-Function;


Function AddToDashboardCount(&pPortal As string, &node As string) Returns number
   Local array of PTNUI:Model:LandingPageTab &tabList;
   /* get the list */
   If None(&node) Then
      &node = %Node;
   End-If;

   &tabList = GetDashboardListForPortal(&pPortal, &node);

   Return &tabList.Len;
End-Function;

Declare Function OBIEESyncMessage PeopleCode FUNCLIB_PTOBIEE.FUNCLIB FieldFormula;
Declare Function EscapeXML PeopleCode FUNCLIB_PTOBIEE.FUNCLIB FieldFormula;
Declare Function GetRandomNumber PeopleCode FUNCLIB_PTOBIEE.FUNCLIB FieldFormula;
Declare Function PSURLtoNewWin PeopleCode FUNCLIB_PTCXM.FUNCLIB FieldFormula;
Declare Function PingOBIEE PeopleCode FUNCLIB_PTOBIEE.FUNCLIB FieldFormula;

Global array of string &OBIEEServerSession;


Function IScript_ParseXml(&currentNode As XmlNode, &stringXML As string, &nmbr As number, &nmbrns As number)
   Local XmlNode &parentNode, &removenode;
   Local number &childcount, &attr;
   Local string &promtnode, &attrName, &attrvalue;

   &promtnode = "NO";
   &parentNode = &currentNode;
   If (&currentNode.ChildNodeCount > 0) And
         None(&parentNode.NodeValue) Then
      For &childcount = 1 To &parentNode.ChildNodeCount
         &currentNode = &parentNode.GetChildNode(&childcount);
         &promtnode = "NO";
         &stringXML = &stringXML | "<" | &currentNode.NodeName;
         For &attr = 1 To &currentNode.AttributesCount
            &attrName = &currentNode.GetAttributeName(&attr);
            &attrvalue = &currentNode.GetAttributeValue(&attrName);
            If (&attrName = "op" And
                  &attrvalue = "prompted") Then
               &promtnode = "YES";
               &stringXML = &stringXML | " " | &attrName | "='equal' ";
            Else
               If (&attrName = "xsi:type" And
                     &attrvalue = "sawx:special") Then
                  &stringXML = &stringXML | " " | &attrName | "='sawx:comparison' ";
               Else
                  &stringXML = &stringXML | " " | &attrName | "='" | &attrvalue | "' ";
               End-If;
            End-If;
            If (&attr = &currentNode.AttributesCount) Then
               If &nmbrns = 1 Then
                  &stringXML = &stringXML | " xmlns:saw='com.siebel.analytics.web/report/v1' xmlns:sawx='com.siebel.analytics.web/expression/v1' xmlns:xsi='http://www.w3.org/2001/XMLSchema-instance' xmlns:xsd='http://www.w3.org/2001/XMLSchema'>";
                  &nmbrns = 0;
               Else
                  &stringXML = &stringXML | ">";
               End-If;
            End-If;
         End-For;
         Local XmlNode &currentNode_xml = &currentNode;
         IScript_ParseXml(&currentNode_xml, &stringXML, &nmbr, &nmbrns);
         If (&promtnode = "YES") Then
            &stringXML = &stringXML | "<sawx:expr xsi:type='xsd:string'>%Bind(:" | &nmbr | ")</sawx:expr>";
            &nmbr = &nmbr + 1;
         End-If;
         &stringXML = &stringXML | &currentNode.NodeValue | "</" | &currentNode.NodeName | ">";
      End-For;
   End-If;

End-Function;



Function IScript_OBIEEDashboard

   Local SQL &SqlObj;

   &Report_id = EscapeXML(Unencode(%Request.GetParameter("ReportID")));

   If All(&Report_id) Then
      &SqlObj = GetSQL(SQL.PTOBI_RPTXML, &Report_id);
      If (&SqlObj.Fetch(&Report_Path, &Report_Name, &ServerName, &Report_Owner, &PTOBI_RPT_XML_DEFN, &AnalyticsURL)) Then

         &Return = PingOBIEE(&ServerName, "#BIDASH");
         &SessionNQID = Split(&Return, "###");
         If (&SessionNQID [1] = "TRUE") Then
            &NQID = &SessionNQID [2];

            &SiteArr = Split(PSURLtoNewWin(%Request.RequestURI), "/");
            If (&SiteArr.len >= 3 And
                  &SiteArr [3] <> "") Then
               &SiteNameArr = Split(&SiteArr [3], "_newwin");
               &SiteName = &SiteNameArr [1];
            End-If;

            Local string &temp = EncodeURL(%Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort | "/sawbridge?SAWServer=") | EncodeURLForQueryString(&AnalyticsURL | "/") | "&amp;ORA_BIPS_NQID=" | &NQID | "&amp;PS_SITE=" | &SiteName;
            &SetBridge = "<?xml version='1.0' encoding='UTF-8' ?><setBridgeURL xmlns='com.siebel.analytics.web/soap/v4'><bridgeURL>" | &temp | "</bridgeURL><staticFilesRoot>" | &AnalyticsURL | "</staticFilesRoot><sessionID>" | &NQID | "</sessionID></setBridgeURL>";
            &Req_Msgg = CreateMessage(@("Operation.GETHTMLFORPAGEWITHONEREPORT"), %IntBroker_Request);
            &requestDocc = CreateXmlDoc(&SetBridge);
            &Req_Msgg.SetXmlDoc(&requestDocc);
            &Responsee = OBIEESyncMessage(&Req_Msgg, &AnalyticsURL | "/saw.dll?SoapImpl=htmlViewService", "GETHTMLFORPAGEWITHONEREPORT");
            &PSFTUrl = %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort | "/sawbridge?SAWServer=" | EncodeURLForQueryString(&AnalyticsURL | "/") | "&PS_SITE=" | &SiteName | "&RedirectURL=" | EncodeURLForQueryString("saw.dll?SyndicatePages&PortalPath=" | &Report_Path | "&Page=" | &Report_Name | "&NQID=" | &NQID);
            %Response.RedirectURL(&PSFTUrl);
         Else
            %Response.Write(&Return);
         End-If;
      Else
         Error MsgGetText(240, 1001, "Report ID is not valid or empty, please contact your administrator.");
      End-If;
   Else
      Error MsgGetText(240, 1001, "Report ID is not valid or empty, please contact your administrator.");
   End-If;


End-Function;



Function IScript_REPORT_RENDER
   Local Message &Req_Msg, &Response;
   Local XmlDoc &requestDoc;
   Local SQL &SqlObj;
   Local string &stringXML, &SessionValue, &Server, &Operation;
   Local array of string &ReturnArray;
   Local string &isAutosize;

   &FilterArray = %Request.GetParameterValues("FilterArray");
   &Report_id = EscapeXML(Unencode(%Request.GetParameter("RepID")));
   &View = EscapeXML(Unencode(%Request.GetParameter("ViewName")));
   &Operation = "GETHTMLFORPAGEWITHONEREPORT";
   &isAutosize = %Request.GetParameter("Autosize");

   If All(&Report_id) Then
      &SqlObj = GetSQL(SQL.PTOBI_RPTXML, &Report_id);
      If (&SqlObj.Fetch(&Report_Path, &Report_Name, &Server, &Report_Owner, &PTOBI_RPT_XML_DEFN, &AnalyticsURL)) Then
         &REPORTPATH = &Report_Path | "/" | &Report_Name;
      Else
         Error MsgGetText(240, 1001, "Report ID is not valid or empty, please contact your administrator.");
      End-If;
   Else
      Error MsgGetText(240, 1001, "Report ID is not valid or empty, please contact your administrator.");
   End-If;

   &stringXML = "";
   &TransformedDoc = CreateXmlDoc(&PTOBI_RPT_XML_DEFN);
   &field1List = &TransformedDoc.DocumentElement.FindNodes("saw:criteria/saw:filter");
   For &count = 1 To &field1List.Len
      &currentNode = &field1List [&count];
      &nmbr = 1;
      &nmbrns = 1;
      IScript_ParseXml(&currentNode, &stringXML, &nmbr, &nmbrns);
   End-For;
   &startpos = 1;

   If &FilterArray.Len > 0 Then
      For &i = 1 To &FilterArray.Len
         &Values = Unencode(&FilterArray [&i]);
         rem EscapeXML(Unencode(&FilterArray [&i]));
         rem 1896520004;
         &ValuesArr = Split(&Values, "###");
         &curpos = Find(&ValuesArr [1], &stringXML, &startpos);
         If &curpos > 0 Then
            &replpos1 = Find("%Bind(:", &stringXML, &curpos);
            &replpos2 = Find(")", &stringXML, &replpos1);
            &stringXML = Replace(&stringXML, &replpos1, (&replpos2 + 1) - &replpos1, EscapeXML(&ValuesArr [2]));
            rem &stringXML = Substitute(&stringXML, "%Bind(:" | &i | ")", &Values);
         End-If;
      End-For;
   End-If;

   If None(&OBIEEServerSession) Then
      &Return1 = PingOBIEE(&Server, "");
      &ReturnArray1 = Split(&Return1, "###");
      If (&ReturnArray1 [1] <> "TRUE") Then
         Error &ReturnArray1 [2];
      End-If;
   End-If;

   If &OBIEEServerSession.Len > 0 Then
      For &i = 1 To &OBIEEServerSession.Len
         &ReturnArray = Split(&OBIEEServerSession [&i], "###");
         For &j = 1 To &ReturnArray.Len
            If (&ReturnArray [&j] = &Server) Then
               &SessionValue = &ReturnArray [2];
            End-If;
         End-For;
      End-For;
   End-If;

   &RandomNumber = GetRandomNumber(10000000, 99999999) + &Report_id;
   &stringXML = EscapeXML(&stringXML);

   &SiteArr = Split(PSURLtoNewWin(%Request.RequestURI), "/");
   If (&SiteArr.len >= 3 And
         &SiteArr [3] <> "") Then
      &SiteNameArr = Split(&SiteArr [3], "_newwin");
      &SiteName = &SiteNameArr [1];
   End-If;

   Local string &OBI_VER;
   SQLExec(SQL.PTOBI_OBIEE_GETVER, &AnalyticsURL, &OBI_VER);
   /*  The SetBridge method sets the Bridge servlet path for the report. */
   If &OBI_VER = "10G" Then
      &SetBridge = "<?xml version='1.0' encoding='UTF-8' Content-type:text/xml; charset='utf-8'?><setBridge xmlns='com.siebel.analytics.web/soap/v4'><bridge>" | EncodeURL(%Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort | "/sawbridge?SAWServer=") | EncodeURLForQueryString(&AnalyticsURL | "/") | "&amp;PS_SITE=" | &SiteName | "</bridge><sessionID>" | &SessionValue | "</sessionID></setBridge>";
   Else
      Local string &temp = EncodeURL(%Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort | "/sawbridge?SAWServer=") | EncodeURLForQueryString(&AnalyticsURL | "/") | "&amp;ORA_BIPS_NQID=" | &SessionValue | "&amp;PS_SITE=" | &SiteName;
      &SetBridge = "<?xml version='1.0' encoding='UTF-8' ?><setBridgeURL xmlns='com.siebel.analytics.web/soap/v4'><bridgeURL>" | &temp | "</bridgeURL><staticFilesRoot>" | &AnalyticsURL | "</staticFilesRoot><sessionID>" | &SessionValue | "</sessionID></setBridgeURL>";
   End-If;
   try
      &Req_Msg = CreateMessage(@("Operation." | &Operation), %IntBroker_Request);
      &requestDoc = CreateXmlDoc(&SetBridge);
      &AnalyticsURL1 = &AnalyticsURL;
      &AnalyticsURL = &AnalyticsURL | "/saw.dll?SoapImpl=htmlViewService";
      &Req_Msg.SetXmlDoc(&requestDoc);
      &Response = OBIEESyncMessage(&Req_Msg, &AnalyticsURL, &Operation);

   catch Exception &expc
      If (&Req_Msg = Null) Then
         Error MsgGetText(240, 1003, "Service Operation '%1' does not exist or not configured, please contact your administrator. Error detail: %2", "SETBRIDGE", &expc.ToString());
      End-If;
      If (&Response = Null) Then
         Error MsgGetText(240, 1002, "Integration Broker Gateway or Analytic Servlet is not configured, please contact your administrator. Error Detail: %1", &expc.ToString());
      Else
         Error MsgGetText(240, 1000, "Message not found", &expc.ToString());
      End-If;
   end-try;


   /*  The getHtmlForPageWithOneReport method gets OBIEE Report HTML. */
   try
      &Req_Msg = CreateMessage(@("Operation." | "GETHTMLFORPAGEWITHONEREPORT"), %IntBroker_Request);
      &requestDoc = CreateXmlDoc(GetHTMLText(HTML.PTOBI_GETPAGEHTML, &RandomNumber, &REPORTPATH, &View, &stringXML, &SessionValue));

      &Req_Msg.SetXmlDoc(&requestDoc);
      &Response = OBIEESyncMessage(&Req_Msg, &AnalyticsURL, "GETHTMLFORPAGEWITHONEREPORT");

      &TransformedDoc = CreateSOAPDoc(&Response.GenXMLString());
      For &i = 1 To &TransformedDoc.ParmCount
         &ParmName = &TransformedDoc.GetParmName(&i);
         If &ParmName = "sawsoap:return" Then
            &HtmlContent = &TransformedDoc.GetParmValue(&i);
         End-If;
      End-For;
   catch Exception &exp
      If (&Req_Msg = Null) Then
         Error MsgGetText(240, 1003, "Service Operation '%1' does not exist or not configured, please contact your administrator. Error detail: %2", "GETHTMLFORPAGEWITHONEREPORT", &exp.ToString());
      End-If;
      If (&Response = Null) Then
         Error MsgGetText(240, 1002, "Integration Broker Gateway or Analytic Servlet is not configured, please contact your administrator. Error Detail: %1", &exp.ToString());
      Else
         Error MsgGetText(240, 1000, "Message not found", &exp.ToString());
      End-If;
   end-try;

   /* Refresh OBIEE Report Script */
   /*&FrameObj = "top.frames['ifrm_" | &Report_id | "'].refresh()";
   &FrameLoc = "top.frames['ifrm_" | &Report_id | "'].location";
   &RefreshScript = "<script type='text/javascript'>function refresh () {var Loc = " | &FrameLoc | "; " | &FrameLoc | " = Loc; } </script>";*/

   rem %Response.Write(&HtmlContent |  &RefreshScript | "<a href='javascript:void(null)' onclick=""" | &FrameObj | """>" | MsgGetText(95, 429, "Message not found") | "</a>");
   &HtmlContet1 = "<script type='text/javascript' src=""" | &AnalyticsURL1 | "/res/b_mozilla/common/obips.biadf.js""></script>";
   &HtmlContent = Substitute(&HtmlContent, "saw.doFrameBust(1)", "saw.doFrameBust(0)");
   If &isAutosize = "1" Then
      Local string &psInfo = GetHTMLText(HTML.PT_POSTDOCSIZE_JS, LTrim(%Request.AuthTokenDomain, "."), %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort);
      &HtmlContent = &HtmlContent | &psInfo;
   End-If;
   %Response.Write(&HtmlContet1 | &HtmlContent);
   rem  |  &RefreshScript | "<a href='javascript:void(null)' onclick=""" | &FrameObj | """>" | MsgGetText(95, 429, "Message not found") | "</a>");

End-Function;

Declare Function getPortalContextNode PeopleCode FUNCLIB_PTUN.FUNCLIB FieldFormula;
Declare Function GetPortalNode PeopleCode PTPN_NOTIFY_WRK.FUNCLIB FieldFormula;

Function IScript_Notification_Count()
   Local string &portalurl = getPortalContextNode();
   Local string &ptlnd = GetPortalNode(&portalurl);

   If &ptlnd = "false" Or
         &ptlnd = %LocalNode Then
      Local Rowset &UserConfigCat = CreateRowset(Record.PSPTPN_USER_CFG);
      &UserConfigCat.Flush();
      &strWhere = " WHERE OPRID=:1";
      &UserConfigCat_Count = &UserConfigCat.Fill(&strWhere, %UserId);
      Local array of string &CategoryName = Split(&UserConfigCat.GetRow(1).PSPTPN_USER_CFG.PTPN_CATEGORY_NAME.Value, ";");
      If &CategoryName.Len > 0 Then
         For &i = 1 To &CategoryName.Len

            If &i <> &CategoryName.Len Then
               &wherecriteria = &wherecriteria | "ptpn_category_name!='" | &CategoryName [&i] | "' AND ";
            Else
               &wherecriteria = &wherecriteria | "ptpn_category_name!='" | &CategoryName [&i] | "'";
            End-If;

         End-For;
         &strWhere = "WHERE " | &wherecriteria | " AND PTPN_MSG_STATE='New' AND OPRID=:1";

      Else
         &strWhere = " where PTPN_MSG_STATE='New' AND OPRID=:1";

      End-If;

      SQLExec("select COUNT(*) from  PSPTPN_MSG_TBL" | " " | &strWhere, %UserId, &checkifrowexists);

      Local string &param1 = %Request.GetParameter("name");
      If &param1 = "MAP" Then
         %Response.SetContentType("application/javascript");
         Local string &rsps = "MapResponse(" | String(&checkifrowexists) | ")";
         %Response.Write(&rsps);
      Else
         %Response.Write(String(&checkifrowexists));


      End-If;

   Else

      Local string &Url = "Portal_URL;;" | &portalurl;
      %Response.Write(String(&Url));
   End-If;

End-Function;

Function IScript_PortalContextNode()
   Local string &portalurl = getPortalContextNode();
   %Response.Write(String(&portalurl));

End-Function;

Function IScript_Get_Portal_Count()

   Local Rowset &UserConfigCat = CreateRowset(Record.PSPTPN_USER_CFG);
   &UserConfigCat.Flush();
   &strWhere = " WHERE OPRID=:1";
   &UserConfigCat_Count = &UserConfigCat.Fill(&strWhere, %UserId);
   Local array of string &CategoryName = Split(&UserConfigCat.GetRow(1).PSPTPN_USER_CFG.PTPN_CATEGORY_NAME.Value, ";");
   If &CategoryName.Len > 0 Then
      For &i = 1 To &CategoryName.Len

         If &i <> &CategoryName.Len Then
            &wherecriteria = &wherecriteria | "ptpn_category_name!='" | &CategoryName [&i] | "' AND ";
         Else
            &wherecriteria = &wherecriteria | "ptpn_category_name!='" | &CategoryName [&i] | "'";
         End-If;

      End-For;
      &strWhere = "WHERE " | &wherecriteria | " AND PTPN_MSG_STATE='New' AND OPRID=:1";

   Else
      &strWhere = " where PTPN_MSG_STATE='New' AND OPRID=:1";

   End-If;

   SQLExec("select COUNT(*) from  PSPTPN_MSG_TBL" | " " | &strWhere, %UserId, &checkifrowexists);

   %Response.Write(String(&checkifrowexists));
End-Function;



Function IScript_StateChange()

   SQLExec("select COUNT(*) from  PSPTPN_MSG_TBL where PTPN_MSG_STATE='New' AND OPRID=:1", %UserId, &checkifrowexists);
   If &checkifrowexists > 0 Then
      SQLExec("update PSPTPN_MSG_TBL set PTPN_MSG_STATE='Unread' where PTPN_MSG_STATE='New' AND OPRID=:1", %UserId);
   End-If;

   %Response.Write("Read");
End-Function;

Function IScript_FYI_StateChange()
   Local string &param1 = %Request.GetParameter("name");
   SQLExec("select COUNT(*) from  PSPTPN_MSG_TBL where PTPN_CAT_DATA_KEY = :1 AND OPRID=:2", &param1, %UserId, &checkifrowexists);
   If &checkifrowexists > 0 Then
      SQLExec("update PSPTPN_MSG_TBL set PTPN_MSG_STATE='Read' where PTPN_CAT_DATA_KEY=:1 AND OPRID=:2", &param1, %UserId);
   End-If;


   %Response.Write("Read");
End-Function;

import PTPN_PUBLISH:PublishToWindow;

ComponentLife PTPN_PUBLISH:PublishToWindow &wlSrch;

Function IScript_getRequestUrl_Ack()
   Local JavaObject &oRandom;
   Local integer &iNumber, &iMaxInt;

   &iMaxInt = 100000;
   &oRandom = CreateJavaObject("java.util.Random");
   &iNumber = &oRandom.nextInt(&iMaxInt) + 1;



   Local string &param1 = %Request.GetParameter("name");
   Local Rowset &rs = CreateRowset(Record.PSPTPN_MSG_TBL);
   &strWhere = " WHERE ptpn_cat_data_key =:1 AND OPRID=:2";
   Local string &X = "";
   &rs.Fill(&strWhere, &param1);
   &wlSrch = create PTPN_PUBLISH:PublishToWindow("SENDNOTE", "SendNote");

   &wlSrch.SetCategoryAlias("SendNote");
   &wlSrch.SetCategoryTypeAck();
   &wlSrch.AddRecepient(%UserId, 1);
   &wlSrch.SetMsgKey(&param1);
   &wlSrch.SetMsgInfo("Expense Report IDCWC" | &iNumber | " is Approved by User  " | %UserId);
   &wlSrch.SetMsgStateUnread();
   &wlSrch.Publish("");
   %Response.Write(&param1);

End-Function;


Function IScript_InlineActions()



   Local string &AppPackageName, &AppClassName, &MethodName, &Parameters;
   Local any &ObjectAppClass;
   Local array of string &arrayParams;
   Local array of any &arrayAny;

   Local number &idx;
   &AppPackageName = %Request.GetParameter("AppPackageName");
   &AppClassName = %Request.GetParameter("AppClassName");
   &MethodName = %Request.GetParameter("MethodName");
   &Parameters = %Request.GetParameter("Parameters");

   &ObjectAppClass = CreateObject(&AppPackageName | ":" | &AppClassName);

   If (&Parameters = "") Then

      &TEST = ObjectDoMethod(&ObjectAppClass, &MethodName);

   Else
      &arrayAny = CreateArray();
      &arrayParams = Split(&Parameters, ":");
      For &idx = 1 To &arrayParams.Len
         &arrayAny.Push(&arrayParams.Get(&idx));
      End-For;


      &TEST = ObjectDoMethodArray(&ObjectAppClass, &MethodName, &arrayAny);

   End-If;
   %Response.Write(&TEST);

End-Function;

import PTPP_PORTAL:PortalRegistry:PortalRegistry;
