/************************************************/
/* Get pagelet information of the given portal  */
/************************************************/
Function IScript_PageletList

   Local string &portalName, &temp;
   Local boolean &succeeded;

   Local PTPP_PORTAL:PortalRegistry:PortalRegistry &objPortalRegistry;

   &portalName = %Request.GetParameter("PORTAL_NAME");
   If None(&portalName) Then
      &portalName = %Portal;
   End-If;

   &objPortalRegistry = create PTPP_PORTAL:PortalRegistry:PortalRegistry(&portalName);
   &succeeded = &objPortalRegistry.loadPageletList();
   &temp = &objPortalRegistry.GenFormattedXmlString();

   %Response.Write(&temp);

End-Function;



/************************************************/
/* Get folder information of the given portal   */
/************************************************/
Function IScript_FolderList


   Local string &portalName, &temp;
   Local array of string &folderNames;
   Local boolean &includeSubFolders;
   Local boolean &succeeded;

   Local PTPP_PORTAL:PortalRegistry:PortalRegistry &objPortalRegistry;

   &portalName = %Request.GetParameter("PORTAL_NAME");
   If None(&portalName) Then
      &portalName = %Portal;
   End-If;

   &folderNames = %Request.GetParameterValues("FOLDER_NAME");

   &objPortalRegistry = create PTPP_PORTAL:PortalRegistry:PortalRegistry(&portalName);
   &succeeded = &objPortalRegistry.loadFolderList(&folderNames);


   &temp = &objPortalRegistry.GenFormattedXmlString();

   %Response.Write(&temp);

End-Function;


/************************************************/
/* Get CrefObject information of the given portal   */
/************************************************/
Function IScript_CrefObj


   Local string &portalName, &temp;
   Local array of string &folderNames;
   Local boolean &includeSubFolders;
   Local boolean &succeeded;

   Local PTPP_PORTAL:PortalRegistry:PortalRegistry &objPortalRegistry;

   &portalName = %Request.GetParameter("PORTAL_NAME");
   If None(&portalName) Then
      &portalName = %Portal;
   End-If;

   &CrefName = %Request.GetParameter("CREFNAME");
   If (&CrefName <> "") Then
      &objPortalRegistry = create PTPP_PORTAL:PortalRegistry:PortalRegistry(&portalName);
      &succeeded = &objPortalRegistry.loadCrefObject(&CrefName);

      &temp = &objPortalRegistry.GenFormattedXmlString();
   End-If;
   %Response.Write(&temp);

End-Function;

