/****************************************************************************/
/* Read MAF Device Token and Register the device for the Push Notification  */
/****************************************************************************/

Function IScript_RegisterMAFDevice

   Local string &DeviceToken = %Request.GetParameter("dtoken");
   Local string &DeviceName = EscapeHTML(%Request.GetParameter("dname"));
   Local string &AppID = EscapeHTML(%Request.GetParameter("dappid"));
   Local string &AppName = EscapeHTML(%Request.GetParameter("dappname"));
   Local string &UUID = EscapeHTML(%Request.GetParameter("duuid"));

   Local string &UseName = %UserId;
   Local string &Provider = "";
   &Result = "FALSE";
   &DeviceStatusVal = "Y";

   Local string &WHERE = " PTMAF_DEVICE_NAME = '" | &DeviceName | "'  AND PTMAF_APP_ID = '" | &AppID | "'  AND PTMAF_USER_NAME = '" | &UseName | "' AND PTMAF_DEVICE_TOKEN LIKE '" | &DeviceToken | "'";
   SQLExec("SELECT COUNT(*) FROM %Table(PTMAF_REGISTER) WHERE " | &WHERE, &COUNT);

   Local string &DeviceTokenExists = " PTMAF_DEVICE_TOKEN LIKE '" | &DeviceToken | "'";
   SQLExec("SELECT COUNT(*) FROM %Table(PTMAF_REGISTER) WHERE " | &DeviceTokenExists, &COUNTDeviceToken);

   If (&COUNT = 0) Then
      If (&COUNTDeviceToken = 1) Then
         &Result = SQLExec("UPDATE %Table(PTMAF_REGISTER) SET PTMAF_USER_NAME = :1 WHERE PTMAF_DEVICE_TOKEN LIKE :2 ", &UseName, &DeviceToken);
      Else
         &Result = SQLExec("INSERT INTO %Table(PTMAF_REGISTER)(PTMAF_DEVICE_NAME, PTMAF_APP_ID, PTMAF_APP_NAME, PTMAF_USER_NAME, PTMAF_PROVIDER, PTMAF_DEVICE_UUID, PTMAF_DEVICE_TOKEN, PTMAF_DEV_STATUS) VALUES (:1, :2, :3, :4, :5, :6, :7, :8)", &DeviceName, &AppID, &AppName, &UseName, &Provider, &UUID, &DeviceToken, &DeviceStatusVal);
      End-If;
   End-If;

   %Response.Write(&Result);

End-Function;


/****************************************************************************/
/* Read MAF Push Notification details and add them to the configuration		*/
/****************************************************************************/

Function IScript_RegisterMAFDevicePushData



   Local string &AppName = EscapeHTML(%Request.GetParameter("dappname"));
   Local string &GoogleProjectID = EscapeHTML(%Request.GetParameter("googleProjectID"));
   Local string &GcmApiKey = EscapeHTML(%Request.GetParameter("gkey"));
   Local string &APNBundleID = EscapeHTML(%Request.GetParameter("abid"));
   Local string &APNKeyFile = EscapeHTML(%Request.GetParameter("akfile"));
   Local string &ApnKeyPass = EscapeHTML(%Request.GetParameter("akpass"));


   Local JavaObject &pscipher;
   &pscipher = GetJavaClass("psft.pt8.pshttp.PSCipher");
   &ApnKeyPass = &pscipher.encodePassword(&ApnKeyPass);

   &Result = SQLExec("INSERT INTO %Table(PSPTPNMOBCONF)(PTPNMAFAPPNAME, PTPNGCMSENDERID, PTPNGCMAPIKEY, PTPNAPNBUNDLEID, PTPNAPNSSLPVTK, PTPNAPNSSLPVTKP, ENABLED) VALUES (:1, :2, :3, :4, :5, :6, :7)", &AppName, &GoogleProjectID, &GcmApiKey, &APNBundleID, &APNKeyFile, &ApnKeyPass, "1");

   %Response.Write(&Result);



End-Function;

/**************************************************************************/
/* DeRegister the device from receiving Push Notification when signed out */
/**************************************************************************/

Function IScript_DeRegisterMAFDevice

   Local string &DeviceToken = %Request.GetParameter("dtoken");

   &Result = SQLExec("DELETE FROM %Table(PTMAF_REGISTER) WHERE PTMAF_DEVICE_TOKEN LIKE :1 ", &DeviceToken);

   %Response.Write(&Result);

End-Function;

/**************************************************************************/
/* GET Storage group information by storage group name */
/**************************************************************************/

Function IScript_GetStorageGroupInfo
   Local string &sgName;
   Local string &sgFolderName;
   Local string &AuthorizeClass;
   Local string &PackageRoot, &QualifyPath, &AppClassID;

   /* Get SG Name */
   &sgName = %Request.GetParameter("SGNAME");

   If All(&sgName) Then
      /* Get app class name from database */
      SQLExec("select ptpp_sg_foldername, packageroot, qualifypath, appclassid from psptsg_adm where ptpp_sg_name=:1", &sgName, &sgFolderName, &PackageRoot, &QualifyPath, &AppClassID);
   Else
      &AuthorizeClass = "Please specify storage group name."
   End-If;

   &AuthorizeClass = &PackageRoot | &QualifyPath | &AppClassID;

   If All(&AuthorizeClass) Then
      &TheClass = CreateObject(&AuthorizeClass);
      ObjectDoMethod(&TheClass, "Process", &sgFolderName);
   Else
      %Response.Write("{""cmd"":""" | "ALLOW_SUBDIR" | """,""sg_folder"":""" | &sgFolderName | """,""valid_duration"":""" | "0" | """}");
   End-If;

End-Function;

