/************************************************/
/* Determine the Pagelet Personalization URL (SearchInit) */
/************************************************/
Function GetPgltPrefURL(&CheckType) Returns string;
   Local string &PageletID, &PTPPRecExists, &EOPPRecExists, &EOPPTestValue, &HTML;
   Local object &Utility;
   Local string &PrefURL, &GoToMenuName, &GoToComponent, &GoToPage, &GoToQString;

   /* Get the Pagelet ID from the QueryString */
   &PageletID = %Request.GetParameter("PTPPB_PAGELET_ID");
   If None(&PageletID) Then
      &PageletID = %Request.GetParameter("EOPPB_PAGELET_ID");
   End-If;

   If &CheckType = "PTPP" Then
      &GoToMenuName = "PTPPB_PAGELET_WIZARD";
      &GoToComponent = "PTPPB_USER_PREF";
      &GoToPage = "PTPPB_USER_PREF";
      &GoToQString = "&PTPPB_PAGELET_ID="
   Else
      &GoToMenuName = "EOPPB_PAGELET_WIZARD";
      &GoToComponent = "EOPPB_USER_PREF";
      &GoToPage = "EOPPB_USER_PREF";
      &GoToQString = "&EOPPB_PAGELET_ID="
   End-If;

   &PrefURL = GenerateComponentContentURL(%Portal, %Node, @("Menuname." | &GoToMenuName), %Market, @("Component." | &GoToComponent), @("Page." | &GoToPage), "") | &GoToQString | &PageletID;

   Return &PrefURL;
End-Function;

/************************************************/
/* Determine which HTML to render (Cref Iscript)*/
/************************************************/
Function RenderPgltWiz(&PageletType As string) Returns string;
   Local string &PageletID, &HTML;
   Local object &Utility;

   /* Get the Pagelet ID from the QueryString */
   &PageletID = %Request.GetParameter("PTPPB_PAGELET_ID");
   If None(&PageletID) Then
      &PageletID = %Request.GetParameter("EOPPB_PAGELET_ID");
   End-If;

   If CheckRenderType() = "PTPP" Then
      &Utility = CreateObject("PTPPB_PAGELET:UTILITY:Utility");
      &HTML = ObjectDoMethod(&Utility, "GetPgltHTML", &PageletID, &PageletType);
   Else
      &Utility = CreateObject("EOPPB_PAGELET:UTILITY:Utility");
      &HTML = ObjectDoMethod(&Utility, "GetPgltHTML", &PageletID, &PageletType);
   End-If;

   Return &HTML;
End-Function;

/**********************************************************************/
/** WSRP Support for Pagelet Wizard                                  **/
/** This code supports WSRP production of Pagelet Wizard Pagelets    **/
/**********************************************************************/
/** NOT CURRENTLY USED                                               **/
/**********************************************************************/
Function createWSRPResponseWrapper(&mode As string, &windowState As string, &renderCallback As boolean, &portletTitle As string, &markup As string) Returns string

   Local XmlNode &thisnode;

   Local XmlDoc &xmldoc = CreateXmlDoc("");
   Local XmlNode &docnode = &xmldoc.CreateDocumentElement("portlet-response");
   If Not None(&mode, &windowState) Then
      Local XmlNode &statenode = &docnode.AddElement("portlet-state");
      If All(&mode) Then
         &thisnode = &statenode.AddElement("portlet-mode");
         &thisnode.NodeValue = &mode;
      End-If;
      If All(&windowState) Then
         &thisnode = &statenode.AddElement("portlet-window-state");
         &thisnode.NodeValue = &windowState;
      End-If;
      &thisnode = &statenode.AddElement("render-callback");
      &thisnode.NodeValue = String(&renderCallback);
   End-If;
   If Not None(&portletTitle, &markup) Then
      Local XmlNode &markupnode = &docnode.AddElement("portlet-markup");
      If All(&portletTitle) Then
         &thisnode = &markupnode.AddElement("portlet-title");
         &thisnode.NodeValue = &portletTitle;
      End-If;
      If All(&markup) Then
         &thisnode = &markupnode.AddCDataSection(&markup);
      End-If;
   End-If;
   Return &xmldoc.GenXmlString();
End-Function;

/*****************************************************************/
/* Iscript for Rendering the Pagelet Wizard Homepage Pagelet     */
/*****************************************************************/
Function IScript_PageletBuilder
   Local string &PIAPortletMode, &ErrMsg, &PortletTech;

   REM &PortletTech = %Request.GetParameter("PIAPortletMode");
   &PIAPortletMode = Upper(%Request.GetParameter("PIAPortletMode"));
   &PortletTechnology = Upper(%Request.GetParameter("PortletTechnology"));

   If All(&PIAPortletMode) Then
      If &PortletTechnology = "WSRP" Then
         If Upper(%Request.GetParameter("PIAPortletWindowState")) <> "MINIMIZED" Then
            REM %Response.SetContentType("text/xml");
            If &PIAPortletMode = "VIEW" Then
               If Upper(%Request.GetParameter("PIAPortletURLType")) <> "ACTIONURL" Then
                  &PTPPB_THROWPAGELETEXCEPTIONS = False;
                  %Response.Write(RenderPgltWiz("WSRP"));
               End-If;
            End-If;
         End-If;
      Else
         /* Assume JPDK if we have a PIAPortletMode and PortletTechology wasn't WSRP */
         RenderPageletJPDK();
      End-If;
   Else
      %Response.Write(RenderPgltWiz("HMPG"));
   End-If;
End-Function;

/*****************************************************************/
/* Iscript for Rendering the Pagelet Wizard Embeddable Pagelet in Related Content frame*/
/*****************************************************************/
Function IScript_EmbeddedPageletBuilder
   Local string &ParmValue, &PageletID, &PgltHTML;
   Local string &PageletErrorTitle, &DetailedErrorDesc, &ErrorDetails, &subst1, &subst2, &subst3, &subst4, &subst5;
   Local PTPPB_PAGELET:UTILITY:Collection &paramColl;
   Local PTPPB_PAGELET:PageletWizard &PWAPI;
   Local PTPPB_PAGELET:Pagelet &Pagelet;

   /* Set to True to include the PeopleCode location/trance info for PageletExceptions */
   Local boolean &ShowExceptionLocation = False;

   /* First check for Portal Pack installation */
   &PgltHTML = CheckPgltEnabled();
   If CheckPgltEnabled() <> "" Then
      %Response.Write(&PgltHTML);
   End-If;


   /* Create the Pagelet Wizard application pakage and assign the pagelet ID*/
   try
      &PageletID = %Request.GetParameter("PAGELETID");
      SetLogger(&PageletID);

      &PWAPI = create PTPPB_PAGELET:PageletWizard();
      &Pagelet = &PWAPI.getPageletByID(&PageletID, True);
      &Pagelet.PSGeneratedLinkTarget = "_parent";
      &Pagelet.CxMExecute = True;

      /* Force a full DataSource Load - required for prompt validation */
      &Pagelet.fullDataSourceLoad();

      /* Set the pagelet parameters to default values*/
      &Pagelet.PopulateInputsWithDefaults();


      /* Override the pagelet parameter default values by reading the request object*/
      &paramColl = &Pagelet.DataSource.getParameterCollection();

      For &i = 1 To &paramColl.Count
         &thisParameter = &paramColl.getItem(&i);
         If &thisParameter.UsageType = &thisParameter.USAGETYPE_USERSPECIFIED Or
               &thisParameter.UsageType = &thisParameter.USAGETYPE_CONTEXTUAL Then
            &ParmValue = %Request.GetParameter(&thisParameter.Name);
            If (&ParmValue <> "") Then
               &thisParameter.value = &ParmValue;
            End-If;
         End-If;
      End-For;

      /* Get the Embeddable Pagelet HTML */
      &PgltHTML = &Pagelet.Execute();

   catch PTPPB_PAGELET:EXCEPTION:PageletException &ex

      &PageletErrorTitle = MsgGetText(219, 350, "(Message Not Found) Error executing pagelet.");
      &DetailedErrorDesc = MsgGetText(219, 351, "(Message Not Found) Detailed error description:");

      Evaluate &ex.SubstitutionCount
      When > 4
         &subst5 = &ex.GetSubstitution(5);
      When > 3
         &subst4 = &ex.GetSubstitution(4);
      When > 2
         &subst3 = &ex.GetSubstitution(3);
      When > 1
         &subst2 = &ex.GetSubstitution(2);
      When > 0
         &subst1 = &ex.GetSubstitution(1);
      End-Evaluate;
      &ErrorDetails = MsgGetExplainText(&ex.MessageSetNumber, &ex.MessageNumber, "", &subst1, &subst2, &subst3, &subst4, &subst5);

      If &ShowExceptionLocation Then
         &PgltHTML = GetHTMLText(HTML.PTPPB_PAGELET_RUNTIME_ERROR, EscapeHTML(&PageletErrorTitle), EscapeHTML(&DetailedErrorDesc), EscapeHTML(&ex.ToString()), EscapeHTML(&ErrorDetails));
      Else
         &PgltHTML = GetHTMLText(HTML.PTPPB_PAGELET_RUNTIME_ERROR, EscapeHTML(&PageletErrorTitle), EscapeHTML(&DetailedErrorDesc), "", EscapeHTML(&ErrorDetails));
      End-If;

   end-try;

   %Response.Write("<div class='PSTEXT'>" | &PgltHTML | "</div>");

End-Function;

