            &PTPPB_THROWPAGELETEXCEPTIONS = False;
            %Response.Write(createWSRPResponseWrapper("", "", False, "", RenderPgltWiz("WSRP")));
            Return;
         End-If;
         Break;
      When = "EDIT"
         %Response.Write(WSRPEdit());
         Return;
         Break;
      End-Evaluate;

      /* The mode/render/action is not supported. */
      &ErrMsg = MsgGetText(219, 334, "(Message not found) Unsupported request type.", &PIAPortletMode, %Request.GetParameter("PIAPortletURLType"));
      %Response.Write(createWSRPResponseWrapper("", "", False, "", &ErrMsg));

   End-If;


End-Function;

Component string &CurrentTP_CREFName;

Function getTP_CREFName() Returns string
