Declare Function RenderAppNav PeopleCode WEBLIB_PTPP_SC.HOMEPAGE FieldFormula;

/************************************************/
/* Render Navigation Pagelet - links are to IScript_AppHP */
/************************************************/
Function IScript_SCPagelet
   Local string &compWidth;
   Local number &numCols = 1; /* Default for narrow view */

   &compWidth = %Request.GetParameter("PORTALPARAM_COMPWIDTH");

   If &compWidth = "Wide" Then
      &numCols = 3;
   End-If;

   %Response.Write(RenderAppNav(&numCols, "PAGELET"));
End-Function;

/************************************************/
/* Check which Render Type to call              */
/************************************************/
Function CheckRenderType() Returns string;
   Local string &CheckType, &PTPPRecExists, &EOPPRecExists, &EOPPTestValue;

   /* Render EOPP if the only one available */
   /* Render EOPP if is in tester mode */
   &EOPPTestValue = "";
   SQLExec("SELECT 'X' FROM PSRECDEFN WHERE RECNAME = 'PTPP_PUB_OPT'", &PTPPRecExists);
   SQLExec("SELECT 'X' FROM PSRECDEFN WHERE RECNAME = 'EOPP_PUB_OPT'", &EOPPRecExists);

   If All(&PTPPRecExists) Then
      If All(&EOPPRecExists) Then
         SQLExec("SELECT EOPP_ATTRVAL FROM PS_EOPP_PUB_OPT WHERE EOPP_PUB_TYPE = 'NPGT' AND EOPP_ATTRNAME = 'EOPPTEST'", &EOPPTestValue);
         If &EOPPTestValue = "Y" Then
            &CheckType = "EOPP";
         Else
            &CheckType = "PTPP";
         End-If;
      Else
         &CheckType = "PTPP";
      End-If;
   Else
      &CheckType = "EOPP";
   End-If;

   Return &CheckType;
End-Function;

/************************************************/
/* Determine which Render HTML to call */
/************************************************/
Function RenderAppNav(&NumberColumns As number, &RenderType As string) Returns string;
   Local string &PTPPRecExists, &EOPPRecExists, &EOPPTestValue, &HTML;
   Local object &Utility;

   /* Render EOPP if the only one available */
   /* Render EOPP if is in tester mode */
   &EOPPTestValue = "";
   SQLExec("SELECT 'X' FROM PSRECDEFN WHERE RECNAME = 'PTPP_PUB_OPT'", &PTPPRecExists);
   SQLExec("SELECT 'X' FROM PSRECDEFN WHERE RECNAME = 'EOPP_PUB_OPT'", &EOPPRecExists);

   If All(&PTPPRecExists) Then
      If All(&EOPPRecExists) Then
         SQLExec("SELECT EOPP_ATTRVAL FROM PS_EOPP_PUB_OPT WHERE EOPP_PUB_TYPE = 'NPGT' AND EOPP_ATTRNAME = 'EOPPTEST'", &EOPPTestValue);
         If &EOPPTestValue = "Y" Then
            &Utility = CreateObject("EOPP_SC_UTILITIES:Utilities");
            &HTML = ObjectDoMethod(&Utility, "GetNavHTML", &NumberColumns, &RenderType);
         Else
            &Utility = CreateObject("PTPP_SC_UTILITIES:Utilities");
            &HTML = ObjectDoMethod(&Utility, "GetNavHTML", &NumberColumns, &RenderType);
         End-If;
      Else
         &Utility = CreateObject("PTPP_SC_UTILITIES:Utilities");
         &HTML = ObjectDoMethod(&Utility, "GetNavHTML", &NumberColumns, &RenderType);
      End-If;
   Else
      &Utility = CreateObject("EOPP_SC_UTILITIES:Utilities");
      &HTML = ObjectDoMethod(&Utility, "GetNavHTML", &NumberColumns, &RenderType);
   End-If;

   /* set js variable 'bLoadCompleted=true' in FAN page html response when it is configured inside fluid nav collection. */
   /* if this variable is not set, side1 pane of fluid nav collection becomes inoperative after accessing FAN page */
   If &RenderType = "TARGET_CONTENT" Then
      &HTML = &HTML | GetHTMLText(HTML.PTPP_SETBLOADCOMPLETED);
   End-If;

   Return &HTML;
End-Function;

/************************************************/
/* Render Navigation Page in target frame */
/************************************************/
Function IScript_AppHP
   %Response.Write(RenderAppNav(0, "TARGET_CONTENT"));
End-Function;

/************************************************/
/* Render Navigation Pagelet - links are to IScript_AppHP */
/************************************************/
Function IScript_SCPagelet
   Local string &compWidth;
   Local number &numCols = 1; /* Default for narrow view */

   Local File &output;
   Local time &startTime, &endTime;

   &compWidth = %Request.GetParameter("PORTALPARAM_COMPWIDTH");

   If &compWidth = "Wide" Then
      &numCols = 3;
   End-If;

   %Response.Write(RenderAppNav(&numCols, "PAGELET"));
End-Function;

/************************************************/
/* Render Navigation Page in HTML template */
/************************************************/
Function IScript_AppHtml
   /* Stay /psp/ */
   %Response.Write(RenderAppNav(0, "HTML"));
End-Function;

