/* Ajax request to save min/max settings */
Function IScript_MinMaxState()
   /* expected params: "?instID=<serviceInstanceID>&max=<Y|N>&cref=<crefName>&page=<pageName>*/
   Local string &serviceNo = %Request.GetParameter("instID");
   Local string &max = %Request.GetParameter("max");
   Local string &crefName = %Request.GetParameter("cref");
   Local string &pageName = %Request.GetParameter("page");

   Local Record &rec;
   Local boolean &found;
   Local string &list = &serviceNo | ":" | &max | ",";

   /* Page personalization data */
   &rec = CreateRecord(Record.PTRC_UP_SIDEFRA);
   &rec.OPRID.Value = %UserId;
   &rec.PORTAL_NAME.Value = %Portal;
   &rec.PORTAL_OBJNAME.Value = &crefName;
   &rec.PNLNAME.Value = &pageName;
   &found = &rec.SelectByKey();

   &rec.OPRID.Value = %UserId;
   &rec.PORTAL_NAME.Value = %Portal;
   &rec.PORTAL_OBJNAME.Value = &crefName;
   &rec.PNLNAME.Value = &pageName;
   If &found Then
      /* Save the setting */
      Local string &res = &rec.SERVICEID_LIST.Value;
      Local number &idx = 0;
      Local string &state;
      &idx = Find("," | &serviceNo | ":", &res);
      If (&idx > 0) Then
         /* this service in DB already */
         &state = Substring(&res, &idx + Len("," | &serviceNo | ":"), 1);
         &state = "," | &serviceNo | ":" | &state | ",";
         &res = Substitute(&rec.SERVICEID_LIST.Value, &state, "," | &list);
         &rec.SERVICEID_LIST.Value = &res;
      Else
         &rec.SERVICEID_LIST.Value = &rec.SERVICEID_LIST.Value | &list;
      End-If;
      &rec.Update();
   Else
      &rec.SERVICEID_LIST.Value = "," | &list;
      &rec.Insert();
   End-If;
End-Function;

