Function IScript_RTE_IMAGE_ATTACH

   Local Rowset &rsImageUpld;
   Local integer &k, &pos;
   Local string &RecordName, &RealRecordName, &URLId, &ImgExt, &ImageURL;
   Local array of string &Images;

   &RecordName = Unencode(%Request.GetParameter("URL"));
   &Images = %Request.GetParameterValues("Params");

   If None(&RecordName) Then
      &URLId = Unencode(%Request.GetParameter("URLID"));
      SQLExec("SELECT URL FROM PSURLDEFN WHERE URL_ID=:1", &URLId, &RecordName);
      If (Find("record://", Lower(&RecordName)) = 1) Then
         &RecordName = Substring(&RecordName, 10, Len(&RecordName));
      Else
         &RecordName = "";
      End-If;
   End-If;

   If All(&RecordName) Then
      For &k = 1 To &Images.Len
         &pos = Find(".", Unencode(&Images [&k]));
         &ImgExt = Substring(&Images [&k], (&pos + 1), 3);

         &RealRecordName = "Record." | &RecordName | "_" | Upper(&ImgExt);
         &rsImageUpld = CreateRowset(@(&RealRecordName));
         &rsImageUpld.Fill("WHERE ATTACHSYSFILENAME =:1", &Images [&k]);
         &ImageURL = %Response.GetImageURL(&rsImageUpld.GetRow(1).GetRecord(@(&RealRecordName)));
      End-For;
   End-If;

End-Function;



/*************************************************************
* Function: GenRTEHTMLId()
* Purpose:  Generate an ID
* Inputs:   None
* Output:   ID
*************************************************************/
Function GenRTEHTMLId() Returns string;

   Return "RTEDiv" | String(Int(Rand() * 1000));

End-Function;



/*************************************************************
* Function: GetRTEHTMLProcessingScript()
* Purpose:  Get the RTE HTML Processing script
* Inputs:   &pUrlID - The image location URL ID.  "" if default
*           &pElementId - The ID of the element to check.  "" full page search
* Output:   Script HTML
*************************************************************/
Function GetRTEHTMLProcessingScript(&pUrlID As string, &pElementId As string) Returns string;

   Local string &GetRTEHTMLProcessingScript = "";
   Local string &url = "";

   If (%Request <> Null) Then
      &url = %Request.FullURI;
   End-If;

   &GetRTEHTMLProcessingScript = GetHTMLText(HTML.PTRTE_CHECKIMAGES, EscapeHTML(&url), EscapeHTML(&pUrlID), EscapeHTML(&pElementId));

   Return &GetRTEHTMLProcessingScript;

End-Function;



/*************************************************************
* Function: WrapRTEHTMLWithID()
* Purpose:  Wrap RTE HTML in DIV element of specific ID
* Inputs:   &pId - ID of the Element
*           &pHtmlData - Html Data
* Output:   Result HTML
*************************************************************/
Function WrapRTEHTMLWithID(&pId As string, &pHtmlData As string) Returns string;

   Local string &WrapRTEHTMLWithID = "";
   Local string &style = "PT_RTE_DISPLAYONLY";
   Local string &divID = &pId;

   If All(&pHtmlData) Then
      If None(&pId) Then
         &divID = GenRTEHTMLId();
      End-If;
      &WrapRTEHTMLWithID = GetHTMLText(HTML.PTRTE_HTML_CONTAINER, &divID, &style, &pHtmlData);
   End-If;

   Return &WrapRTEHTMLWithID;

End-Function;



/*************************************************************
* Function: WrapRTEHTML()
* Purpose:  Wrap RTE HTML in DIV element
* Inputs:   &pHtmlData - Html Data
* Output:   Result HTML
*************************************************************/
Function WrapRTEHTML(&pHtmlData As string) Returns string;

   Local string &WrapRTEHTML = "";

   If All(&pHtmlData) Then
      &WrapRTEHTML = WrapRTEHTMLWithID(GenRTEHTMLId(), &pHtmlData);
   End-If;

   Return &WrapRTEHTML;

End-Function;



/*************************************************************
* Function: ProcessRTEHTML()
* Purpose:  Process RTE HTML that use non default image location
* Inputs:   &pUrlID - The image location URL ID.  "" if default
*           &pHtmlData - The HTML data to check.  "" only script to check full page will be returned
* Output:   Result HTML
*************************************************************/
Function ProcessRTEHTML(&pUrlID As string, &pHtmlData As string) Returns string;

   Local string &ProcessRTEHTML = "";
   Local string &divID;

   If All(&pHtmlData) Then
      &divID = GenRTEHTMLId();
      &ProcessRTEHTML = GetRTEHTMLProcessingScript(&pUrlID, &divID);
      &ProcessRTEHTML = WrapRTEHTMLWithID(&divID, &pHtmlData | &ProcessRTEHTML);
   Else
      &ProcessRTEHTML = GetRTEHTMLProcessingScript(&pUrlID, "");
   End-If;

   Return &ProcessRTEHTML;

End-Function;

