Function IScript_GetFile()
   Local PT_SEARCH:SESIMPL:AdminService &admService;
   Local PT_SEARCH:SESIMPL:QueryService &qryService;
   Local string &sesIns, &qryUrl;
   Local string &docID = %Request.GetParameter("DocID");
   Local string &fedID = %Request.GetParameter("fid");

   &factory = create PT_SEARCH:SearchFactory();
   SQLExec("Select PTSF_SRCH_ENG_INS,PTSF_QRY_SERV_URL from PS_PTSF_SRCH_ENGN where ptsf_srch_provider = 'SES'", &sesIns, &qryUrl);
   &admService = &factory.CreateAdminService(&sesIns);

   If &admService <> Null Then
      &qryService = &admService.GetDefaultQueryService();
      Local PT_SEARCH:SESIMPL:MESSAGE:QueryRequest &request = create PT_SEARCH:SESIMPL:MESSAGE:QueryRequest("getCachedPage", &qryService);

      &request.AddSimpleElement("query", "");
      &request.AddSimpleElement("docID", &docID);
      &request.AddSimpleElement("fedID", &fedID);

      Local IBInfo &info = &request.GetIBInfo();
      Local boolean &bool = &info.LoadConnectorProp("HTTPTARGET");
      &info.ConnectorOverride = True;
      &bool = &info.IBConnectorInfo.AddConnectorProperties("Content-Type", "text/xml", %HttpHeader);
      &bool = &info.IBConnectorInfo.DeleteConnectorProperties("URL");
      &bool = &info.IBConnectorInfo.AddConnectorProperties("URL", &qryUrl, %HttpProperty);
      &bool = &info.IBConnectorInfo.AddConnectorProperties("SOAPUpContent", "Y", %HttpProperty);
      Local PT_SEARCH:SESIMPL:MESSAGE:QueryResponse &response = create PT_SEARCH:SESIMPL:MESSAGE:QueryResponse(&request.Send());
      Local XmlNode &returnNode = &response.GetBody().GetChildNode(1).GetChildNode(1);
      Local object &oDecoder = CreateJavaObject("sun.misc.BASE64Decoder");
      Local object &dOut = &oDecoder.decodeBuffer(&returnNode.NodeValue);
      Local object &oDecoded = CreateJavaObject("java.lang.String", &dOut, 0, &dOut.length, "UTF8");
      &DecodeResult = &oDecoded.toString();
      %Response.Write(&DecodeResult);
   End-If;
   Return;
End-Function;

Function IScript_GetEsFileContent()
   Local string &index, &type, &id, &language, &contentname, &srchIns;
   Local string &content = "";
   &index = %Request.GetParameter("index");
   &type = %Request.GetParameter("type");
   &id = %Request.GetParameter("id");
   &language = %Request.GetParameter("language");
   &srchIns = %Request.GetParameter("srchIns");
   SQLExec("SELECT PTSF_QRY_SERV_URL from PS_PTSF_SRCH_ENGN WHERE PTSF_SRCH_ENG_INS = :1", &srchIns, &qryUrl);
   rem &qryUrl = &qryUrl | &index | "/" | &type | "/_search";
   &qryUrl = &qryUrl | &index | "/_search";

   Local JsonBuilder &requestBldr = CreateJsonBuilder();
   If &requestBldr.StartObjectReturnsTrue("") Then


      If &requestBldr.StartArrayReturnsTrue("_source") Then
         /*If &language <> "" And
               &language <> %Language_Base Then
            &contentname = "CONTENT_ORCL_ES_" | &language;
         Else
            &contentname = "CONTENT";
         End-If;*/
         &contentname = "CONTENT_ORCL_ES_" | &language;
         &requestBldr.AddElement(&contentname);
         &requestBldr.EndArray("_source");
      End-If;
      If &requestBldr.StartObjectReturnsTrue("query") Then
         If &requestBldr.StartObjectReturnsTrue("match") Then
            &id = Substitute(&id, "\", "\\");
            &requestBldr.AddProperty("_id", &id);
            &requestBldr.EndObject("match");
         End-If;
         &requestBldr.EndObject("query");
      End-If;
      &requestBldr.EndObject("");
   End-If;
   Local PTSF_ES:ESIMPL:JsonService &jSvc;
   &jSvc = create PTSF_ES:ESIMPL:JsonService();


   Local PTSF_ES:ESIMPL:ResultCollection &rc;
   Local JsonObject &resp = &jSvc.doServiceString(&srchIns, &qryUrl, "POST", &requestBldr.ToString());
   If &resp.IsExist("error") Then
      Local string &sError = &resp.GetString("error");
      throw CreateException(262, 2018, "Search Exception: %1 ", &sError);
   Else
      Local JsonObject &jo;
      If &resp.IsExist("hits") Then
         &jo = &resp.GetJsonObject("hits");
         If &jo.IsExist("hits") Then
            Local JsonArray &jArray = &jo.GetJsonArray("hits");
            Local JsonObject &jObject, &fields;
            Local integer &i;
            For &i = 1 To &jArray.Length()
               &jObject = &jArray.GetJsonObject(&i);
               &fields = &jObject.GetJsonObject("_source");
               &content = &fields.GetString(&contentname);
            End-For;
         End-If;
      End-If;
   End-If;

   %Response.Write(&content);
End-Function;

