Function IScript_StoreContentKeyword()
   If &sRecentDeployed = "" Then
      SQLExec("select ptsf_rti from PS_PTSF_INDEX where PTSF_INDEX_NAME='PTSF_RECENT_KW'", &sRecentDeployed);
   End-If;
   If &sRecentDeployed = "Y" Then
      Local string &data = %Request.GetParameter("requestJson");
      &ret = storeContentKeyword(&data);
      %Response.Write(EscapeHTML(&ret));
   End-If;
End-Function;

