Constant &cstQUERYPARAMETER_LANGUAGE_CD = "languageCd";
Constant &cstQUERYPARAMETER_MODE = "mode";

Constant &cstMODE_CLASSIC = "classic";



Function IScript_SetLanguage()

   Local string &lang;

   /* Check the language */
   &lang = %Request.GetParameter(&cstQUERYPARAMETER_LANGUAGE_CD);
   If (All(&lang) And
         (&lang <> %Language)) Then
      SetLanguage(&lang);
      resetBrandingManager();
      ResetUniNavLandingPageHandler();
      ForceRefreshAllHPTabs();
   End-If;

   %Response.Write(%Language);

End-Function;



Function IScript_SignIn()

   Local string &html;

   Local integer &i, &count;
   Local boolean &isClassic;

   Local string &bind1, &bind2, &bind3, &bind4, &bind5;
   Local string &bind6, &bind7, &bind8, &bind9, &bind10, &bind11, &bind12, &bind13;

   Local string &lang, &label, &hoverText, &selected;

   Local Rowset &rs;
   Local Record &rec;


   /* Check the mode */
   &isClassic = (%Request.GetParameter(&cstQUERYPARAMETER_MODE) = &cstMODE_CLASSIC);


   /* Page title style */
   &bind1 = "psc_hidden-readable";


   /* View port etting */
   &bind2 = GetDefaultViewportSetting();


   /* psp servlet URL */
   &bind3 = Substitute(%Request.ContentURI, "/psc/", "/psp/") | %Portal | "/" | %Node;

   /* Header includes */
   If (&isClassic) Then
      &bind4 = "";
   Else
      &bind4 = getRequiredFluidSystemStyleSheets();
      &bind4 = &bind4 | getFluidThemeStyleSheets();
      &bind4 = &bind4 | SetDocDomainForPortal() | Char(13);
      &bind4 = &bind4 | %Request.ExpireMeta | Char(13);
      &bind4 = &bind4 | GetHTMLText(HTML.PTBR_INCLUDE_JS, %Response.GetJavaScriptURL(HTML.PT_COMMON)) | Char(13);
      &bind4 = &bind4 | GetHTMLText(HTML.PTBR_INCLUDE_JS, %Response.GetJavaScriptURL(HTML.PT_AJAX_NET)) | Char(13);
      rem &bind4 = &bind4 | GetHTMLText(HTML.PTBR_INCLUDE_JS, %Response.GetJavaScriptURL(HTML.PT_ISCROSSDOMAINNS6)) | Char(13);
      &bind4 = &bind4 | GetHTMLText(HTML.PTBR_INCLUDE_JS, %Response.GetJavaScriptURL(HTML.PT_SAVEWARNINGSCRIPT)) | Char(13);
      &bind4 = &bind4 | GetHTMLText(HTML.PTBR_INCLUDE_SCRIPTS, "ptEvent.load(function(){setupTimeout2();});") | Char(13);
   End-If;


   /* Mode flag */
   &bind5 = "";
   If (&isClassic) Then
      &bind5 = &cstMODE_CLASSIC;
   End-If;


   /* Current language code */
   &bind6 = %Language;


   /* Load the language drop down list */
   &bind7 = "";

   &rs = CreateRowset(Record.PSXLATITEM);
   &count = &rs.Fill(" where (FILL.fieldname=:1) and (FILL.eff_status='A') and (FILL.fieldvalue in (select LANGUAGE_CD from %Table(pslanguages) where (installed=1))) and %EffDtCheck(PSXLATITEM, FILL, %CurrentDateIn)", Field.LANGUAGE_CD);

   For &i = 1 To &count;

      &lang = &rs(&i).PSXLATITEM.FIELDVALUE.Value;
      &label = "";
      &hoverText = &rs(&i).PSXLATITEM.XLATLONGNAME.Value;

      SQLExec("select xlatlongname from psxlatitemlang where (fieldname=:1) and (fieldvalue=:2) and (effdt=:3) and (language_cd=:2);", Field.LANGUAGE_CD, &lang, &rs(&i).PSXLATITEM.EFFDT.Value, &label);
      If (None(&label)) Then
         &label = &hoverText;
      End-If;

      If (&lang = %Language) Then
         &selected = "selected=""selected""";
      Else
         &selected = "";
      End-If;

      &bind7 = &bind7 | "<option value=""" | &lang | """ title=""" | EscapeHTML(&hoverText) | """ " | &selected | ">" | EscapeHTML(&label) | "</option>";

   End-For;


   /* Only show the language drop down list when there are more than one choices */
   If (&count > 1) Then
      &bind8 = "";
   Else
      &bind8 = "psc_hidden";
   End-If;


   /* Set Language iScript */
   &bind9 = GenerateScriptContentURL(%Portal, %Node, Record.WEBLIB_PTSIGNIN, Field.ISCRIPT1, "FieldFormula", "IScript_SetLanguage");;


   /* Only show the forgot password link when user has access to the component */
   If (IsMenuItemAuthorized(MenuName.MAINTAIN_SECURITY, BarName.USE, ItemName.EMAIL_PSWD, Page.EMAIL_PSWD, %Action_UpdateDisplay)) Then
      &bind10 = "";
   Else
      &bind10 = "psc_hidden";
   End-If;

   &bind11 = "CSRF" | Int(Rand() * 1000000);

   /* Only show the forgot user ID link when user has access to the component */
   If (IsMenuItemAuthorized(MenuName.MAINTAIN_SECURITY, BarName.USE, ItemName.EMAIL_OPRID, Page.EMAIL_OPRID, %Action_UpdateDisplay)) Then
      &bind12 = "";
   Else
      &bind12 = "psc_hidden";
   End-If;

   /* pass the psc based content URI */
   &bind13 = %Request.ContentURI | %Portal | "/" | %Node;

   /* Assemble the final HTML */
   &html = GetHTMLText(HTML.PTPP_SIGNIN, &bind1, &bind2, &bind3, &bind4, &bind5, &bind6, &bind7, &bind8, &bind9, &bind10, &bind11, &bind12, &bind13);

   Local object &Response = %Response;
   Local object &CSRFCookie;
   &CSRFCookie = &Response.CreateCookie("lcsrftoken");
   &CSRFCookie.Domain = %Request.AuthTokenDomain;
   &CSRFCookie.MaxAge = - 1;
   &CSRFCookie.Path = "/";
   &CSRFCookie.Value = &bind11;

   %Response.Write(&html);

End-Function;

import PTGP_APPCLASS_TILE:API:*;

Constant &QUERYPARAMETER_ID = "ID";
Constant &QUERYPARAMETER_HP = "HP";

Function IScript_FetchTilesDisplay()
   Local string &ID, &HP, &tileName, &fullAppClassPath, &funcParams;
   Local PTGP_APPCLASS_TILE:API:TileController &controller;
   Local JsonBuilder &jBldr = CreateJsonBuilder();
   Local number &I, &J;
   Local boolean &isDisplay, &isRSync;
   Local array of string &tiles;
   Local Rowset &rsDispCtrl = CreateRowset(Record.PTTILE_DISPCTRL);

   &ID = %Request.GetParameter(&QUERYPARAMETER_ID);
   &HP = %Request.GetParameter(&QUERYPARAMETER_HP);

   &rsDispCtrl.Fill("WHERE PTTILE_HOMEPAGE = %Upper(:1)", &HP);

   &tiles = Split(&ID, ",");
   &jBldr.StartObject("hpTiles");
   &jBldr.AddProperty("hpID", &HP);
   &jBldr.StartObject("tiles");
   For &I = 1 To &tiles.Len;
      &isDisplay = True;
      &isRSync = False;
      &tileName = &tiles.Get(&I);
      For &J = 1 To &rsDispCtrl.ActiveRowCount
         Local Record &item = &rsDispCtrl.GetRow(&J).PTTILE_DISPCTRL;
         If &item.PTTILE_TILENAME.Value = &tiles [&I] Then
            /* Create Application Class Path */
            If &item.PTTILE_REALTIMSYNC.Value = "Y" Then
               &isRSync = True;
            End-If;

            If &item.QUALIFYPATH.Value = "" Then
               &fullAppClassPath = &item.PACKAGEROOT.Value | ":" | &item.APPCLASSID.Value;
            Else
               &fullAppClassPath = &item.PACKAGEROOT.Value | ":" | &item.QUALIFYPATH.Value | ":" | &item.APPCLASSID.Value;
            End-If;

            try
               &controller = CreateObject(&fullAppClassPath, &tileName, &HP);

               &isDisplay = &controller.IsDisplay();
            catch Exception &E
               WriteToLog(%ApplicationLogFence_Warning, "There is an exception when execute control tile display application class: " | &E.ToString());
            end-try;
            Break;
         End-If;

      End-For;
      &jBldr.StartObject(&tileName);
      &jBldr.AddProperty("isDisp", &isDisplay);
      &jBldr.AddProperty("isRSyn", &isRSync);
      &jBldr.EndObject(&tileName);
   End-For;
   &jBldr.EndObject("tiles");
   &jBldr.EndObject("hpTiles");
   &funcParams = &jBldr.ToString();
   %Response.SetContentType("applicaiton/json");
   %Response.Write(&funcParams);
End-Function;

