Constant &cstPARA_PTCS_NODENAME = "PTCS_NODENAME";
Constant &cstPARA_PTCS_PORTALNAME = "PTCS_PORTALNAME";
Constant &cstPARA_PTCS_CREFNAME = "PTCS_CREFNAME";
Constant &cstPARA_PTCS_CREFLABEL = "PTCS_CREFLABEL";
Constant &cstPARA_PTCS_SERVICEID = "PTCS_SERVICEID";
Constant &cstPARA_PTCS_KEYFIELD = "PTCS_KEYFIELD";
Constant &cstPARA_PTCS_CONTEXTFIELD = "PTCS_CONTEXTFIELD";
Constant &cstPARA_PTWC_REUSEGS = "PTWC_REUSEGS";

Constant &cstSERVICETYPE_BLOGS = "PTWC_BLOGS";
Constant &cstSERVICETYPE_DISCUSSIONS = "PTWC_DISCUSSIONS";
Constant &cstSERVICETYPE_DOCUMENTS = "PTWC_DOCUMENTS";
Constant &cstSERVICETYPE_WIKIS = "PTWC_WIKIS";
Constant &cstSERVICETYPE_LINKS = "PTWC_LINKS";



/*************************************************
 * Generate the Transaction Permission Request String
 *************************************************/
Function generateTransactionPermissionRequest(&pRequest As PTWC_WEBCENTER:UTILITY:RelatedContentsRequest) Returns string

   Local integer &i;
   Local string &requestString;

   /* Generate the request string */
   &requestString = "";
   For &i = 1 To &pRequest.Keys.Len
      &requestString = &requestString | "<NAME>" | &pRequest.Keys [&i][1] | "</NAME><VALUE>" | &pRequest.Keys [&i][2] | "</VALUE>";
   End-For;

   &requestString = "<PARAMS><SERVICEID>" | &pRequest.ServiceId | "</SERVICEID><NODE>" | &pRequest.NodeName | "</NODE><PORTAL>" | &pRequest.PortalName | "</PORTAL><CREFID>" | &pRequest.TransactionName | "</CREFID>" | &requestString | "</PARAMS>";

   Return &requestString;

End-Function;



/*************************************************
 * Check the Content Reference Permission
 *************************************************/
Function checkContentReferencePermission(&pRequest As PTWC_WEBCENTER:UTILITY:RelatedContentsRequest) Returns boolean

   Local boolean &noAccess;

   Local ApiObject &portalObj, &crefObj;

   &portalObj = %Session.GetPortalRegistry();
   If Not &portalObj.Open(&pRequest.PortalName) Then
      Return False;
   End-If;

   &crefObj = &portalObj.FindCRefByName(&pRequest.TransactionName);

   &noAccess = ((&crefObj = Null) Or
      ( Not &crefObj.Authorized) Or
      ((&crefObj.ValidFrom <> "") And
         (&crefObj.ValidFrom > %Date)) Or
      ((&crefObj.ValidTo <> "") And
         (&crefObj.ValidTo < %Date)));

   &portalObj.Close();

   Return ( Not &noAccess);

End-Function;



/*************************************************
 * Check the Related Content Permission
 *************************************************/
Function checkRelatedContentPermission(&pRequest As PTWC_WEBCENTER:UTILITY:RelatedContentsRequest) Returns boolean

   Local boolean &noAccess;
   Local string &requestString, &response;

   Local Message &msg;

   Local PTCS_HANDLER:DefaultSecurityHandler &handler;

   /* Generate the request string */
   &requestString = generateTransactionPermissionRequest(&pRequest);


   /* Create the message object */
   &msg = CreateMessage(@("Operation." | "PTCS_GETACCESS"), %IntBroker_Request);
   &msg.SetXmlDoc(CreateXmlDoc(GetHTMLText(HTML.PTWC_FIND_CREFS_ACCESS, %UserId, &requestString)));
   &msg.IBInfo.ExternalUserName = %UserId;


   /* Invoke the handler */
   &handler = create PTCS_HANDLER:DefaultSecurityHandler();
   &msg = &handler.onAccessRequest(&msg);
   &response = &msg.GenXMLString();


   /* Check Return values */
   &noAccess = True;
   If (Find("<ACCESSTYPE>Public</ACCESSTYPE>", &response) > 0) Then
      &noAccess = False;
   End-If;

   If (Find("<ACCESSTYPE>RelatedContent</ACCESSTYPE>", &response) > 0) Then
      &noAccess = False;
   End-If;

   If (Find("<ACCESSTYPE>Transaction</ACCESSTYPE>", &response) > 0) Then
      &noAccess = (Find("<ACCESS>NO</ACCESS>", &response) > 0);
   End-If;


   Return ( Not &noAccess);

End-Function;



/*************************************************
 * Get Related Contents Request Objects
 *************************************************/
Function getRelatedContentsRequest() Returns array of PTWC_WEBCENTER:UTILITY:RelatedContentsRequest

   Local integer &i;
   Local boolean &hasAccess;

   Local string &temp, &keys;
   Local array of string &paraValues;

   Local PTWC_WEBCENTER:UTILITY:RelatedContentsRequest &sharedRequest, &privateRequest;


   /* Create the object first */
   &sharedRequest = create PTWC_WEBCENTER:UTILITY:RelatedContentsRequest("SharedRequest");
   &privateRequest = create PTWC_WEBCENTER:UTILITY:RelatedContentsRequest("InstanceSpecificRequest");


   /* Get Required Parameters */
   &temp = Unencode(%Request.GetParameter(&cstPARA_PTCS_NODENAME));
   If None(&temp) Then
      Error MsgGetExplainText(219, 6040, "(Message not found) Missing Node Name");
   End-If;
   &sharedRequest.NodeName = &temp;
   &privateRequest.NodeName = &temp;

   &temp = Unencode(%Request.GetParameter(&cstPARA_PTCS_PORTALNAME));
   If None(&temp) Then
      Error MsgGetExplainText(219, 6041, "(Message not found) Missing Portal Name");
   End-If;
   &sharedRequest.PortalName = &temp;
   &privateRequest.PortalName = &temp;

   &temp = Unencode(%Request.GetParameter(&cstPARA_PTCS_CREFNAME));
   If None(&temp) Then
      Error MsgGetExplainText(219, 6042, "(Message not found) Missing CRef Name");
   End-If;
   &sharedRequest.TransactionName = &temp;
   &privateRequest.TransactionName = &temp;

   &temp = Unencode(%Request.GetParameter(&cstPARA_PTCS_CREFLABEL));
   If None(&temp) Then
      Error MsgGetExplainText(219, 6043, "(Message not found) Missing CRef Label");
   End-If;
   &sharedRequest.TransactionLabel = &temp;
   &privateRequest.TransactionLabel = &temp;
   &sharedRequest.GroupSpaceKeywords = &temp;
   &privateRequest.GroupSpaceKeywords = &temp;

   &temp = Unencode(%Request.GetParameter(&cstPARA_PTCS_SERVICEID));
   If None(&temp) Then
      Error MsgGetExplainText(219, 6044, "(Message not found) Missing Service ID");
   End-If;
   &sharedRequest.ServiceId = &temp;
   &privateRequest.ServiceId = &temp;

   &temp = Upper(%Request.GetParameter(&cstPARA_PTWC_REUSEGS));
   If All(&temp) Then
      &sharedRequest.ReuseGroupSpace = (&temp = "Y");
      &privateRequest.ReuseGroupSpace = (&temp = "Y");
   End-If;


   /* Keys */
   &keys = "";
   For &i = 1 To 5
      &paraValues = %Request.GetParameterValues(&cstPARA_PTCS_KEYFIELD | &i);
      If ((&paraValues.Len = 2) And
            All(&paraValues [1])) Then
         /* Add attribute */
         &privateRequest.Keys.Push(&paraValues);

         /* Add keyword  */
         If All(&paraValues [2]) Then
            &keys = &keys | ", " | &paraValues [2];
            &privateRequest.GroupSpaceKeywords = &privateRequest.GroupSpaceKeywords | ", " | &paraValues [2];
         End-If;
      End-If;
   End-For;
   If All(&keys) Then
      &privateRequest.GroupSpaceDisplayName = LTrim(&keys, ", ");
   End-If;


   /* Context keys */
   For &i = 1 To 5
      &paraValues = %Request.GetParameterValues(&cstPARA_PTCS_CONTEXTFIELD | &i);
      If ((&paraValues.Len = 2) And
            All(&paraValues [1])) Then
         /* Add attribute */
         &privateRequest.ContextKeys.Push(&paraValues);

         /* Add keyword  */
         If All(&paraValues [2]) Then
            &privateRequest.GroupSpaceKeywords = &privateRequest.GroupSpaceKeywords | ", " | &paraValues [2];
         End-If;
      End-If;
   End-For;


   /* Check permission */
   If (checkContentReferencePermission(&privateRequest) = False) Then
      Error MsgGetText(219, 6045, "(Message not found) Not authorized");
   End-If;
   If (checkRelatedContentPermission(&privateRequest) = False) Then
      Error MsgGetText(219, 6045, "(Message not found) Not authorized");
   End-If;

   Return CreateArray(&sharedRequest, &privateRequest);

End-Function;



/*************************************************
 * Related Group Space Service
 *************************************************/
Function relatedGroupSpaceService(&pServiceId As string)

   Local string &temp, &keys;

   Local string &sharedTabLabel, &privateTabLabel, &sharedTabUrl, &privateTabUrl;
   Local string &tabsHtml, &pageHtml, &selectedTab, &gsUrl;
   Local string &bind1, &bind2, &bind3, &bind4, &bind5;
   Local string &bind6, &bind7, &bind8, &bind9, &bind10;

   Local PTWC_WEBCENTER:GroupSpaceManager &gsManager = create PTWC_WEBCENTER:GroupSpaceManager();
   Local PTPP_PORTAL:UTILITY:Collection &gsColl;
   Local PTWC_WEBCENTER:RelatedContent:RelatedGroupSpace &gsPrivate, &gsShared;
   Local PTWC_WEBCENTER:UTILITY:RelatedContentsRequest &gsRequestShared, &gsRequestPrivate;
   Local array of PTWC_WEBCENTER:UTILITY:RelatedContentsRequest &gsRequests;


   /* Get the Request objects */
   &gsRequests = getRelatedContentsRequest();
   &gsRequestShared = &gsRequests [1];
   &gsRequestPrivate = &gsRequests [2];


   /* Fill in the labels */
   &keys = &gsRequestPrivate.GroupSpaceDisplayName;

   Evaluate &pServiceId
   When &cstSERVICETYPE_BLOGS
      &gsRequestShared.GroupSpaceDisplayName = MsgGetText(219, 6050, "(Message not found) %1 Blogs", &gsRequestShared.TransactionLabel);
      &gsRequestShared.GroupSpaceDescription = MsgGetExplainText(219, 6051, "(Message not found) Shared blogs of %1", &gsRequestShared.TransactionLabel);
      &gsRequestShared.ContentType = &gsManager.CONTENTTYPE_GROUPSPACEBLOGS;
      &sharedTabLabel = MsgGetText(219, 6051, "(Message not found) Shared Blogs");

      &gsRequestPrivate.GroupSpaceDisplayName = MsgGetText(219, 6050, "(Message not found) %1 Blogs", &gsRequestPrivate.TransactionLabel);
      &gsRequestPrivate.GroupSpaceDescription = MsgGetExplainText(219, 6052, "(Message not found) Instance specific blogs of %1", &gsRequestPrivate.TransactionLabel);
      &gsRequestPrivate.ContentType = &gsManager.CONTENTTYPE_GROUPSPACEBLOGS;
      &privateTabLabel = MsgGetText(219, 6052, "(Message not found) Instance Specific Blogs");

      Break;

   When &cstSERVICETYPE_DISCUSSIONS
      &gsRequestShared.GroupSpaceDisplayName = MsgGetText(219, 6053, "(Message not found) %1 Discussions", &gsRequestShared.TransactionLabel);
      &gsRequestShared.GroupSpaceDescription = MsgGetExplainText(219, 6054, "(Message not found) Shared discussions of %1", &gsRequestShared.TransactionLabel);
      &gsRequestShared.ContentType = &gsManager.CONTENTTYPE_GROUPSPACEDISCUSSIONS;
      &sharedTabLabel = MsgGetText(219, 6054, "(Message not found) Shared Discussions");

      &gsRequestPrivate.GroupSpaceDisplayName = MsgGetText(219, 6053, "(Message not found) %1 Discussions", &gsRequestPrivate.TransactionLabel);
      &gsRequestPrivate.GroupSpaceDescription = MsgGetExplainText(219, 6055, "(Message not found) Instance specific discussions of %1", &gsRequestPrivate.TransactionLabel);
      &gsRequestPrivate.ContentType = &gsManager.CONTENTTYPE_GROUPSPACEDISCUSSIONS;
      &privateTabLabel = MsgGetText(219, 6055, "(Message not found) Instance Specific Discussions");

      Break;

   When &cstSERVICETYPE_DOCUMENTS
      &gsRequestShared.GroupSpaceDisplayName = MsgGetText(219, 6056, "(Message not found) %1 Documents", &gsRequestShared.TransactionLabel);
      &gsRequestShared.GroupSpaceDescription = MsgGetExplainText(219, 6057, "(Message not found) Shared documents of %1", &gsRequestShared.TransactionLabel);
      &gsRequestShared.ContentType = &gsManager.CONTENTTYPE_GROUPSPACEDOCUMENTS;
      &sharedTabLabel = MsgGetText(219, 6057, "(Message not found) Shared Documents");

      &gsRequestPrivate.GroupSpaceDisplayName = MsgGetText(219, 6056, "(Message not found) %1 Documents", &gsRequestPrivate.TransactionLabel);
      &gsRequestPrivate.GroupSpaceDescription = MsgGetExplainText(219, 6058, "(Message not found) Instance specific documents of %1", &gsRequestPrivate.TransactionLabel);
      &gsRequestPrivate.ContentType = &gsManager.CONTENTTYPE_GROUPSPACEDOCUMENTS;
      &privateTabLabel = MsgGetText(219, 6058, "(Message not found) Instance Specific Documents");

      Break;

   When &cstSERVICETYPE_WIKIS
      &gsRequestShared.GroupSpaceDisplayName = MsgGetText(219, 6059, "(Message not found) %1 Wikis", &gsRequestShared.TransactionLabel);
      &gsRequestShared.GroupSpaceDescription = MsgGetExplainText(219, 6060, "(Message not found) Shared wikis of %1", &gsRequestShared.TransactionLabel);
      &gsRequestShared.ContentType = &gsManager.CONTENTTYPE_GROUPSPACEWIKIS;
      &sharedTabLabel = MsgGetText(219, 6060, "(Message not found) Shared Wikis");

      &gsRequestPrivate.GroupSpaceDisplayName = MsgGetText(219, 6059, "(Message not found) %1 Wikis", &gsRequestPrivate.TransactionLabel);
      &gsRequestPrivate.GroupSpaceDescription = MsgGetExplainText(219, 6061, "(Message not found) Instance specific wikis of %1", &gsRequestPrivate.TransactionLabel);
      &gsRequestPrivate.ContentType = &gsManager.CONTENTTYPE_GROUPSPACEWIKIS;
      &privateTabLabel = MsgGetText(219, 6061, "(Message not found) Instance Specific Wikis");

      Break;

   When-Other
      Return;

   End-Evaluate;


   If &gsRequestShared.ReuseGroupSpace Then
      &gsRequestShared.GroupSpaceDisplayName = &gsRequestShared.TransactionLabel;
      &gsRequestShared.GroupSpaceDescription = MsgGetExplainText(219, 6063, "(Message not found) Shared group space of %1", &gsRequestShared.TransactionLabel);
   End-If;

   If &gsRequestPrivate.ReuseGroupSpace Then
      &gsRequestPrivate.GroupSpaceDisplayName = &gsRequestPrivate.TransactionLabel;
      &gsRequestPrivate.GroupSpaceDescription = MsgGetExplainText(219, 6064, "(Message not found) Instance specific group space of %1", &gsRequestPrivate.TransactionLabel);
   End-If;


   If All(&keys) Then
      &gsRequestPrivate.GroupSpaceDisplayName = &gsRequestPrivate.GroupSpaceDisplayName | " - " | &keys;
   End-If;

   &gsRequestShared.GroupSpaceName = &gsRequestShared.GroupSpaceDisplayName;
   &gsRequestPrivate.GroupSpaceName = &gsRequestPrivate.GroupSpaceDisplayName;
   &gsRequestShared.CreateWhenNotFound = True;
   &gsRequestPrivate.CreateWhenNotFound = True;


   try

      /* Get the Shared Group Space object */
      &gsColl = &gsManager.getRelatedContents(&gsRequestShared);
      If (&gsColl.Count > 0) Then
         &gsShared = &gsColl.get(1);
      End-If;


      /* Get the Private Group Space object only if there is at lease one key present */
      If (&gsRequestPrivate.Keys.Len > 0) Then
         &gsColl = &gsManager.getRelatedContents(&gsRequestPrivate);
         If (&gsColl.Count > 0) Then
            &gsPrivate = &gsColl.get(1);
         End-If;
      End-If;

   catch PTPP_PORTAL:EXCEPTION:PortalException &e
      showErrorFromException(&e);

   end-try;


   /* Assemble the tabs HTML */
   &tabsHtml = "";
   &gsUrl = "javascript:void(0)";
   &selectedTab = "";

   If ((&gsPrivate <> Null) And
         &gsPrivate.isAuthorized()) Then
      &bind1 = "PrivateContent";
      &bind2 = EscapeHTML(&privateTabLabel);
      &bind3 = EscapeHTML(&gsPrivate.getDescription());
      &bind4 = EscapeHTML(&gsPrivate.getContentUrl());
      &bind5 = "";
      &tabsHtml = &tabsHtml | GetHTMLText(HTML.PTWC_RELATED_CONTENT_PAGETAB, &bind1, &bind2, &bind3, &bind4, &bind5);

      If None(&selectedTab) Then
         &gsUrl = &gsPrivate.getGroupSpaceUrl();
         &selectedTab = &bind1;
      End-If;
   End-If;

   If ((&gsShared <> Null) And
         &gsShared.isAuthorized()) Then
      &bind1 = "SharedContent";
      &bind2 = EscapeHTML(&sharedTabLabel);
      &bind3 = EscapeHTML(&gsShared.getDescription());
      &bind4 = EscapeHTML(&gsShared.getContentUrl());
      &bind5 = "";
      &tabsHtml = &tabsHtml | GetHTMLText(HTML.PTWC_RELATED_CONTENT_PAGETAB, &bind1, &bind2, &bind3, &bind4, &bind5);

      If None(&selectedTab) Then
         &gsUrl = &gsShared.getGroupSpaceUrl();
         &selectedTab = &bind1;
      End-If;
   End-If;

   If None(&selectedTab) Then
      Error MsgGetText(219, 6046, "(Message not found) Not authorized");
   End-If;


   /* Assemble the page HTML */
   &bind1 = %Request.CharSet;

   &bind2 = EscapeHTML(&gsRequestShared.GroupSpaceDisplayName);

   &bind3 = GetHTMLText(HTML.PTAL_INCLUDE_CSS, %Response.GetStyleSheetURL(StyleSheet.PSSTYLEREQ));
   &bind3 = &bind3 | Char(13) | GetHTMLText(HTML.PTAL_INCLUDE_CSS, PTGetStyleSheetURL());
   &bind3 = &bind3 | Char(13) | GetHTMLText(HTML.PTAL_INCLUDE_JS, %Response.GetJavaScriptURL(HTML.PT_COMMON));
   &bind3 = &bind3 | Char(13) | SetDocDomainToAuthTokenDomain();

   &bind4 = EscapeHTML(MsgGetText(124, 173, "(msg not found) Processing"));

   &bind5 = &tabsHtml;

   &bind6 = EscapeHTML(&gsUrl);

   &bind7 = EscapeJavascriptString(&selectedTab);

   &pageHtml = GetHTMLText(HTML.PTWC_RELATED_CONTENT_PAGE, &bind1, &bind2, &bind3, &bind4, &bind5, &bind6, &bind7);

   %Response.Write(&pageHtml);

End-Function;



