   Return &branding.getIframeHeaderHTML("");

End-Function;

/**
  * builds the drop-down navigation for an iframe template
  *
*/
Function buildDropDownNav() Returns string

   Local PT_NAV2:NavHover &navHover = create PT_NAV2:NavHover();
   Return &navHover.HTML;

End-Function;


/**
  * 8.4x delivered iScripts
  * Most of these iScripts have been modified for PT 8.50. The original PT 8.4x 
  * versions are now located in WEBLIB_PT_NAV.ISCRIPT2.FieldFormula
*/


/**
  * 8.50 default template 
  * This iScript is called from the 8.50 default template cref (DEFAULT_TEMPLATE)
  * In the portal registry, this cref is located in Root->Portal Objects->Templates->8.50 default template
  * 
*/
Function IScript_PT_NAV_TPL_FRAME

   Local string &templateHTML, &tgtQSparams, &navType;

   Local ApiObject &portal = PortalOpen();
   Local PT_NAV2:NavOptions &navOptions = create PT_NAV2:NavOptions(&portal, True);

   REM get any additional target Content query string parameters;
   &tgtQSparams = &navOptions.targetQSParams;

   REM generate the appropriate navigation iframe template, based on the nav type attribute stored in the portal profile;
   &navType = &navOptions.navType;
   &portal.Close();

   If (&navType = "L") Then
      REM classic left nav iframe template;
      &templateHTML = buildLNavIframeTemplate( True, &tgtQSparams);
   Else
      REM drop-down navigation iframe template;
      &templateHTML = buildIframeTemplate("PT_HNAV_TEMPLATE", "D", True, &tgtQSparams);
   End-If;

   %Response.Write(&templateHTML);

End-Function;

/**
  * 8.50 Header processing code for the frames and iframe template
  * For the frames template, this iScript is located in the PT_DEFAULT_FRAME_TEMPLATE object. 
  * For the iframe template, this iScript is located in the PT_IFRAME_TEMPLATE object.
  * 
*/
Function IScript_UniHeader_Frame()
   Local string &loadingHTML = GetHTMLText(HTML.PT_LOADINGSTATUS, %Response.GetImageURL(Image.PT_PROCESSING), MsgGetText(124, 173, "Processing, please wait"));
   &loadingHTML = &loadingHTML | "<script>if (/\/c\/\PORTAL_ADMIN\.PTSF_GLOBAL_SEARCH\.GBL/.test(top.location))searchProcessing(1);</script>";
   If %Request.GetHeader("PortalAppliedTemplateType") = "IFRM" Then
      %Response.Write(buildIframeHeader() | &loadingHTML);
   Else
      Local PT_NAV2:NavHeader &navHeader = create PT_NAV2:NavHeader("");
      %Response.Write(&navHeader.HTML | &loadingHTML);
   End-If;

End-Function;

/**
  * 8.50 Left Nav processing code for the default frame template and homepage pagelet.
  * This iScript is located in the PT_DEFAULT_FRAME_TEMPLATE HTML object.
  * This iScript is also called when the Menu 2.0 (MENU) pagelet is invoked.
  *
*/
Function IScript_PT_NAV_INFRAME()

   Local Request &req = %Request;
   Local string &HTML;
   Local string &Accessibility = GetUserOption("PPTL", "ACCESS");

   If (&req.GetParameter("navtype") = "dropdown") Then
      &HTML = buildDropDownNav();
   Else
      Local PT_NAV2:NavTree &navTree = create PT_NAV2:NavTree();
      &HTML = &navTree.HTML;
   End-If;

   %Response.Write(&HTML);

End-Function;

/**
  * generates pagelet version of the left nav or builds the drop-down nav. 
  * the drop-down nav iScript version is invoked from the HTML object PORTAL_HP_USER_TEMPLATE
  * 
*/
Function IScript_PT_NAV_PAGELET()

   Local string &HTML;

   If (%Request.GetParameter("navtype") = "dropdown") Then
      Local ApiObject &portal = PortalOpen();
      Local PT_NAV2:NavOptions &navOptions = create PT_NAV2:NavOptions(&portal, True);
      Local string &navType = &navOptions.navType;
      &portal.Close();
      REM generate the drop-down/top nav;
      If &navType = "D" Then
         &HTML = buildDropDownNav();
      Else
         &HTML = " ";
      End-If;
   Else
      Local PT_NAV2:NavTree &navTree = create PT_NAV2:NavTree();
      &HTML = &navTree.HTML;
   End-If;

   %Response.Write(&HTML);

End-Function;

/**
  * This iScript still exists here for backward compatibility. The 8.50 left nav will be displayed.
  * This iScript was created in 8.46 for Enterprise Portal/Tools nav integration
*/
Function IScript_PT_NAV_INFRAME_TITLE()

   Local PT_NAV2:NavTree &navTree = create PT_NAV2:NavTree();
   %Response.Write(&navTree.HTML);

End-Function;

/**
  * This iScript is only called from the PT_NAV:NavTheme app class when in testing mode.
  * The testing mode code in PT_NAV:NavTheme is commented out by default
  *
*/
Function IScript_EmptyFile()

   Local string &authdomain = SetDocDomainToAuthTokenDomain();

   Local number &nMetaXp = Value(GetUserOption("PPTL", "METAXP"));
   Local string &sGMT = DateTimeToHTTP(AddToDateTime(%Datetime, 0, 0, 0, 0, &nMetaXp, 0));
   If (&sGMT <> "") Then
      %Response.SetHeader("expires", &sGMT);
      %Response.SetHeader("last-modified", &sGMT);
   End-If;

   %Response.Write("<HTML dir='" | %Direction | "'><HEAD>" | &authdomain | "</HEAD></HTML>");

End-Function;

/**
  * This iScript is called by the PTNAVFRAMETPL template for timeout processing. 
  * The PTNAVFRAMETPL template is used with the 8.4x menu pagelet in non IE browsers
  * on the homepage
  *
*/
Function IScript_TimeOutDrillDown()
   %Response.Write(GetHTMLText(HTML.PT_NAV_INFRAME_TIMEOUT, %Request.ExpireMeta, %Response.GetJavaScriptURL(HTML.PT_SAVEWARNINGSCRIPT), SetDocDomainToAuthTokenDomain()));
