/**
  * updates the Recently Used data for the drop-down navigation  
  * This iScript is called in HTML object PT_HNAV_JS, pthNav.mruSave(), when the drop-down navigation is used, the user clicks
  * a link in the header and the Recently Used functionality is enabled
  * The pthNav.mruSave() call is done in HTML object PT_IFRAME_HDR_JS
  *
*/
Function IScript_PT_NAV_MRU_Update()
   Local string &mruAction = %Request.GetParameter("mruAction");
   Local string &s_maxMRU = %Request.GetParameter("maxMRU");
   Local string &nbsid = %Request.GetParameter("ptnbsid");
   Local string &mruParam = %Request.GetParameter("mrulist");
   Local string &unmruCref = %Request.GetParameter("unmruCref");
   Local string &unmruCrefhref = Unencode(%Request.GetParameter("unmruCrefhref"));
   Local string &unmruCrefLbl = "";
   Local number &UniNav = Find("cmd=uninav", &unmruCrefhref);
   Local number &UniNavDashboard = Find("unifieddashboard=y", &unmruCrefhref);
   Local string &unfromNavBar = %Request.GetParameter("unfromNavBar");
   Local integer &totalMRUCount = 0;
   /*If None(&mruParam) Or
         (%Request.GetParameter("ptnbsid") = "") And
            (%Request.GetParameter("pthnavsid") = "") Then
      Return;
   End-If;*/

   If None(&mruParam) Then
      Return;
   End-If;


   If ((%Request.GetParameter("ptnbsid") = "") And
         (%Request.GetParameter("pthnavsid") = "")) Then
      Return;
   End-If;



   If (&mruAction <> "ptmruinst") Then
      REM Assume action from PTHNAV -- check pthnavsid ;
      If Not (create PT_NAV2:Security()).sidPassTest Then
         Return;
      End-If;
   End-If;


   If (&mruAction = "ptmruinst") Then
      If Not (create PTNUI:NavBarContentArea:Security("ptnbsid")).sidPassTest Then
         Return;
      End-If;
   End-If;

   If All(&s_maxMRU) Then
      &maxMRUNum = Value(&s_maxMRU);
   End-If;


   Local array of string &mruData = Split(&mruParam, "|");
   Local array of string &unmruCrefArr = Split(&unmruCref, "$$$");
   If (&unmruCrefArr.Len > 1) Then
      &unmruCref = &unmruCrefArr [1];
      &unmruCrefLbl = &unmruCrefArr [2];
   End-If;
   If &mruData.Len = 0 Then
      Return;
   End-If;

   Local number &i, &paramIdx;
   Local Record &rec;
   Local SQL &delete, &UnSQL;
   Local number &count = 0;

   <*  If None(&mruAction) Or
         (&mruAction <> "ptmruinst") Then
      &UnSQL = CreateSQL("SELECT PORTAL_OBJNAME, PORTAL_URLTEXT FROM PS_PT_PORTAL_MRU WHERE OPRID = :1 AND PORTAL_NAME = :2", %UserId, %Portal);

      Local array &AAny = CreateArrayAny();
      While &UnSQL.Fetch(&AAny)
         Local number &index = 0;
         Local array of string &ActmruData = Split(&AAny [2], "$$$");
         If (&ActmruData.Len > 1) Then
            &index = &mruData.Find(&ActmruData [1]);
         End-If;
         If (&index <> 0 And
               &AAny [2] <> " ") Then
            &mruData [&index] = &AAny [2];
         End-If;
      End-While;

      REM delete the existing data;
      &delete = CreateSQL("DELETE FROM PS_PT_PORTAL_MRU WHERE OPRID = :1 AND PORTAL_NAME = :2");
      &delete.Execute(%UserId, %Portal);
      &delete.Close();
   Else*>
   REM This is from NavBar, insert 1 row only;

   REM handle Remote Pages;
   Local string &portalURLText = "";
   Local SQL &anSQL;

   REM PORTAL_URLTEXT for remote pages will be in the format <CREFID>_PTUN_<NUMBER>$$$<CREFLABEL>$$$<URL> ;
   <* &anSQL = CreateSQL("SELECT PORTAL_URLTEXT FROM PS_PT_PORTAL_MRU WHERE OPRID=:1 AND PORTAL_NAME=:2 ", %UserId, %Portal);
   While &anSQL.Fetch(&portalURLText)
      If &portalURLText <> "" Then
         Local array of string &remotemruData = Split(&portalURLText, "$$$");
         If (&remotemruData.Len > 1) Then
            If (&remotemruData [1] = &unmruCref) Then
               Return;
            End-If;
         End-If;
      End-If;
   End-While;*>

   Local ApiObject &p = PortalOpen();
   For &i = &mruData.Len To 1
      Local array of string &UnCrefObj = Split(&mruData [&i], "$$$");
      If (&UnCrefObj.Len > 1) Then
         rem &objname = &UnCrefObj [1] | "_" | &i;
         &objname = &UnCrefObj [1];
         &urltext = &mruData [&i];
         &UniNav = 2;
      Else
         REM If this is a uninav cref clicked from the Navigator? We will form the PORTAL_URLTEXT like below;
         REM "PORTAL_OBJ_NAME$$$CREF_LABEL$$$URL_TEXT;
         If (&unfromNavBar <> "" And
               &unfromNavBar = "true") Then
            Local string &fullURL = %Request.GetParameter("unnavbarUrl");
            Local string &uninavCref = %Request.GetParameter("unmruCref");

            If (&fullURL <> "" And
                  &uninavCref <> "") Then
               &objname = &uninavCref;
               &urltext = &uninavCref | "$$$" | &uninavCref | "$$$" | &fullURL;
            Else
               &objname = &UnCrefObj [1];
               &urltext = " ";
            End-If;
         Else
            &objname = &UnCrefObj [1];
            &urltext = " ";
         End-If;

      End-If;

      If &UniNav > 0 Or
            &UniNavDashboard > 0 Then
         If (&unmruCref = &UnCrefObj [1]) Then
            &urltext = &UnCrefObj [1] | "$$$" | &unmruCrefLbl | "$$$" | &unmruCrefhref;
         End-If;
      End-If;
      If LTrim(&urltext) = "" Then
         Local ApiObject &c = &p.findcrefbyname(&objname);
         &urltext = &c.URL;
      End-If;
      rem This Sql query is to fetch the max PT_PORTAL _MRU_ID and is used to update MRU ids in insert case;
      SQLExec("SELECT MAX(CAST(PT_PORTAL_MRU_ID AS INTEGER)) FROM PS_PT_PORTAL_MRU WHERE PORTAL_NAME = :1 AND OPRID = :2", %Portal, %UserId, &maxmruInDB);

      rem This Sql query is to fetch the total entries present in thePS_PT_PORTAL_MRU;
      SQLExec("select count(*) FROM PS_PT_PORTAL_MRU WHERE PORTAL_NAME = :1 AND OPRID = :2", %Portal, %UserId, &totalMRUCount);

      REM insert the new data;
      &rec = CreateRecord(Record.PT_PORTAL_MRU);
      &rec.OPRID.Value = %UserId;
      &rec.PORTAL_NAME.Value = %Portal;
      &rec.PORTAL_OBJNAME.Value = &objname;
      &rec.PTSF_NAV_FROM.Value = "";
      If Not &rec.SelectByKey() Then
         &insert = True;
         &rec.OPRID.Value = %UserId;
         &rec.PORTAL_NAME.Value = %Portal;
         &rec.PORTAL_OBJNAME.Value = &objname;
         &rec.PORTAL_URLTEXT.Value = &urltext;
         &rec.PT_PORTAL_MRU_ID.Value = (&maxmruInDB + 1);
         If %Language_User = %Language_Base Then
            SQLExec("SELECT DISTINCT(PORTAL_LABEL) FROM PSPRSMDEFN WHERE PORTAL_OBJNAME=:1 AND PORTAL_NAME = :2", &rec.PORTAL_OBJNAME.Value, %Portal, &portal_label);
         Else
            SQLExec("SELECT DISTINCT(PORTAL_LABEL) FROM PSPRSMDEFNLANG WHERE PORTAL_OBJNAME=:1 AND PORTAL_NAME = :2 AND LANGUAGE_CD = :3", &rec.PORTAL_OBJNAME.Value, %Portal, %Language_User, &portal_label);
         End-If;
         &rec.PORTAL_LABEL.Value = &portal_label;
         &rec.LANGUAGE_CD.Value = %Language_User;
         &navfrom = "";
      Else
         &navfrom = &rec.PTSF_NAV_FROM.Value;
         If (&navfrom = "B") Then
            rem do nothing;
         Else
            If &navfrom = "P" Then
               &navfrom = "B";
            Else
               &navfrom = "";
            End-If;
         End-If;
         &insert = False;
      End-If;

      &rec.LASTUPDDTTM.Value = AddToDateTime(%Datetime, 0, 0, 0, 0, 0, &i);
      &rec.PTSF_NAV_FROM.Value = &navfrom;

      If &insert Then
         &rec.USECOUNT.Value = 1;
         &rec.Insert();
      Else
         If &rec.USECOUNT.Value < 999 Then;
            &rec.USECOUNT.Value = &rec.USECOUNT.Value + 1;
         End-If;
         &rec.Update();
      End-If;
   End-For;
   /* Do not Delete - Needed for triaging - gets the output in appserver files - Start */
   <*Local File &f1 = GetFile("mru_add_" | %UserId | "_" | %Language_User | ".txt", "W");
   &f1.WriteLine(&objname);
   &f1.WriteLine(&urltext);
   &f1.WriteLine(&portal_label);
   &f1.Close();*>
   /* Do not Delete - Needed for triaging - End */

   rem if remote cref send the objname to content system to update;
   If Find("$$$", &urltext) > 0 Then
      &ptunstart_pos = Find("_PTUN_", &urltext);
      &ptunend_pos = Find("$", &urltext, &ptunstart_pos);
      &ptun_id = Substring(&urltext, &ptunstart_pos + 1, &ptunend_pos - &ptunstart_pos - 1);

      &ptunstart_pos = Find("_PTUN_", &objname);
      &objname = Substring(&objname, 1, &ptunstart_pos - 1);
      SQLExec("SELECT A.NETWORKNODENAME FROM PSMSGNODEDEFN A, PS_PTUN_DDMENUCFG B WHERE A.MSGNODENAME = B.MSGNODENAME AND B.PORTAL_OBJNAME=:1", &ptun_id, &nodename);
      If &nodename <> "" Then
         &ret = StoreRemoteMenuKeyword(&objname, &nodename);
      End-If;
   End-If;

   If &maxMRUNum > 0 And
         &totalMRUCount >= &maxMRUNum And
         &insert <> False Then
      Local string &sLastUpdDtTm;
      SQLExec("SELECT MIN(LASTUPDDTTM) FROM PS_PT_PORTAL_MRU WHERE PORTAL_NAME = :1 AND OPRID = :2", %Portal, %UserId, &sLastUpdDtTm);
      SQLExec("DELETE FROM PS_PT_PORTAL_MRU WHERE LASTUPDDTTM = %DATETIMEIN(:1) AND PORTAL_NAME = :2 AND OPRID = :3", &sLastUpdDtTm, %Portal, %UserId);
   End-If;
End-Function;

