/**
  * 8.4x Default frame template. Called from template cref PT_84X_DEFAULT_TEMPLATE
*/
Function IScript_PT_NAV_TPL_FRAME

   Local string &encryptedUserId = EncodeURLForQueryString(Encrypt("", %UserId | %Language));
   &navPortal = create PT_NAV:NavPortal("IScript_UniHeader_Frame");
   &navTheme = create PT_NAV:NavTheme(&navPortal);

   REM Set frame titles;
   &navTitleText = MsgGetText(95, 139, "Navigational Links"); /* ICE 1470953006 */
   &contentTitleText = MsgGetText(95, 147, "Main Content");
   &headerTitleText = MsgGetText(95, 148, "Portal Header");

   REM Frame rows;
   &rows = &navPortal.GetHeaderFrameRows();

   REM Target content query string parameters;
   &params = &navPortal.GetTargetQSParams();
   &pourl = %Request.GetHeader("portalactualurl");
   If All(&pourl) Then
      &params = "";
   End-If;

   Local Response &resp = %Response;
   Local Request &req = %Request;

   REM Automatic Menu Collapse feature works for Win IE, Win/Mac NetScape 7.x, Firefox, and Safari 1.2x;
   REM Disable Automatic Menu Collapse feature for Safari 1.3 and 2.0 because of browser bug;
   If &req.BrowserType = "IE" Or
         &navTheme.isNS7x() Or
         &navTheme.isSafari() Then /* reverting to isSafari() from isSafariV12 */
      &Access = GetUserOption("PPTL", "ACCESS");
      If &Access = "A" Then
         Local string &HideNav = &req.GetParameter("h");
         If &HideNav = "" Then
            &HideNav = GetUserOption("PPTL", "AUTOMENU");
         End-If;
         If &HideNav = "Y" Then
            &resp.Write(GetHTMLText(HTML.PT_NAV_TPL_FRAME_COLLAPSE_ACC, &rows, &encryptedUserId, &params, &headerTitleText, &contentTitleText));
         Else
            &resp.Write(GetHTMLText(HTML.PT_NAV_TPL_FRAME_EXPAND, &rows, &encryptedUserId, &params, &headerTitleText, &navTitleText, &contentTitleText)); /* ICE 1470953006 */
         End-If;
      Else
         &resp.Write(GetHTMLText(HTML.PT_NAV_TPL_FRAME_EXPAND, &rows, &encryptedUserId, &params, &headerTitleText, &navTitleText, &contentTitleText)); /* ICE 1470953006 */
      End-If;
   Else
      &HideNav = &req.GetParameter("h");
      If &HideNav = "" Then
         &HideNav = GetUserOption("PPTL", "AUTOMENU");
      End-If;
      If &HideNav = "Y" Then
         &Access = GetUserOption("PPTL", "ACCESS");
         If &Access = "A" Then
            &resp.Write(GetHTMLText(HTML.PT_NAV_TPL_FRAME_COLLAPSE_ACC, &rows, &encryptedUserId, &params, &headerTitleText, &contentTitleText));
         Else
            &resp.Write(GetHTMLText(HTML.PT_NAV_TPL_FRAME_COLLAPSE, &rows, &encryptedUserId, &params, &headerTitleText, &navTitleText, &contentTitleText)); /* ICE 1470953006 */
         End-If;
      Else
         &resp.Write(GetHTMLText(HTML.PT_NAV_TPL_FRAME_EXPAND, &rows, &encryptedUserId, &params, &headerTitleText, &navTitleText, &contentTitleText)); /* ICE 1470953006 */
      End-If;
   End-If;

End-Function;

Function IScript_GetBcUpdateParams()

   /***
   Response format is the following:
	crefId,isRegistered,isVisible,Label
	crefId == the cref's id
	isRegistered == T component is a registered cref
	isRegistered == F component is not a registered cref
	isVisible == T component is hidden or contained in a hidden folder
	isVisible == F component is not hidden and not contained in a hidden folder
	Label == Either the Cref label if available or the comopnent label, not sure about how to get the component label for remote vs local???
   **/

   Local Request &req = %Request;
   Local ApiObject &portal, &currentCref, &parentFolder;
   Local string &contentURL, &portalID, &updateParams;
   Local number &pos;

   &contentURL = &req.GetParameter("crefUrl");
   &portalID = &req.GetParameter("prtl");

   &portal = %Session.GetPortalRegistry();
   &portal.Open(&portalID);

   rem find the cref;
   &currentCref = &portal.FindCRefForURL(&contentURL);

   If All(&currentCref) Then
      rem registered;

      rem CREF ID;
      &updateParams = EscapeHTML(&currentCref.Name);

      &updateParams = &updateParams | ",";

      rem CREF Registered;
      &updateParams = &updateParams | "T";
      &updateParams = &updateParams | ",";

      rem CREF Visible;
      &parentFolder = &portal.FindFolderByName(&currentCref.ParentName);
      If &currentCref.IsVisible And
            &parentFolder.IsVisible Then
         &updateParams = &updateParams | "T";
      Else
         &updateParams = &updateParams | "F";
      End-If;
      &updateParams = &updateParams | ",";

      rem CREF label;
      &updateParams = &updateParams | EscapeHTML(&currentCref.Label);

   Else
      rem not registered;
      &updateParams = "yyy,F,F,zzz";
   End-If;

   &portal.Close();

   %Response.Write(&updateParams);

End-Function;

Declare Function OpenQueryObj PeopleCode QRY_VIEWER_WRK.FUNCLIB FieldFormula;
Declare Function IsBiffEnabled PeopleCode QRYFUNCTIONS.QRYQUERYFUNCS FieldFormula;

Global Record &gQueryRec;
Global Rowset &gQueryRowset;
Global Rowset &gLevelList;
Global number &gURLINDEX;
Local array of string &hdrs;


Function IScript_ToExcel();
   Local string &s;
   Local string &QryName, &QryDescr, &PrivateFlag;
   Local ApiObject &QryObj;
   Local Rowset &rsURLList;
   Local Record &rRecordExpr;
   Local string &sTempString;

   /* 18132040 */
   Local boolean &bPublic = False;
   Local integer &nUnionCount;
   /* 18132040 */

   /* 1453405000 - 9th oct 2006 - start*/
   Local string &sPromptString;
   &sPromptString = &gQueryRec.GetField(Field.EXPRESSIONTEXT).Value;
   /* 1453405000 - 9th oct 2006 - end*/

   &QryName = &gQueryRec.GetField(Field.QRYNAME).Value;

   If IsBiffEnabled() = True Then
      %Response.SetContentType("application/vnd.ms-excel;");
   Else
      %Response.SetContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;");
   End-If;

   If &QryName = "" Then
      &QryName = "New_Unsaved_Query";
   End-If;
   If IsBiffEnabled() = True Then
      &sTempString = "attachment; filename=" | EncodeURL(&QryName) | "_" | Int(Rand() * 10000) | ".xls"; /*33109313*/
   Else
      &sTempString = "attachment; filename=" | EncodeURL(&QryName) | "_" | Int(Rand() * 10000) | ".xlsx"; /*33109313*/
   End-If;

   %Response.SetHeader("Content-Disposition", &sTempString);

   If %Response.CharSet = "UTF-8" Then
      %Response.Write("<head><meta http-equiv=""content-type"" content=""text/html;charset=UTF-8"" />");
   End-If;
   %Response.Write("<title>" | &QryName | "</title>");
   /*1817336006 */
   %Response.Write("<STYLE type=""text/css"">");
   %Response.Write("h3.Qry { text-align: center}  </STYLE></head>");


   &QryDescr = &gQueryRec.GetField(Field.DESCR).Value;
   If All(&QryDescr) Then
      %Response.Write("<h3 class=""Qry"">" | &QryDescr | "</h3><br>");
   Else
      %Response.Write("<h3 class=""Qry"">" | &QryName | "</h3><br>");
   End-If;
   %Response.Write("<h3>" | &gQueryRec.GetField(Field.EXPRESSIONTEXT).Value | "</h3><br>");

   &QryObj = %Session.GetQuery();
   &QryObj.AddQueryName(&QryName);
   /* 1384908000 - 9th oct 2006 - end*/
   /* 1453405000 - 9th oct 2006 */
   &QryObj.AddPromptDesc(&sPromptString);
   /* 1453405000 - 9th oct 2006 - end*/

   /* 18132040 */
   If &gQueryRec.GetField(Field.PRIVATE_QUERY_FLAG).Value = "N" Then
      &bPublic = True;
   Else
      &bPublic = False;
   End-If;
   /* 18132040 */
   /* 1718360000 */
   If &QryObj.Open(&QryName, &bPublic, False) = 0 Then
      If &gLevelList <> Null Then
         For &nUnionCount = 1 To &gLevelList.ActiveRowCount;
            rem &rsURLList = &gLevelList(1).GetRowset(&gURLINDEX);
            &rsURLList = &gLevelList(&nUnionCount).GetRowset(&gURLINDEX);
            If &rsURLList <> Null And
                  &rsURLList.ActiveRowCount >= 1 And
                  All(&rsURLList(1).QRY_URL_WRK.QRYCRIT1EXPRTEXT.Value) Then
               For &nCount = 1 To &rsURLList.ActiveRowCount;
                  &rRecordExpr = &rsURLList(&nCount).QRY_URL_WRK;
                  &QryObj.SetTrackingURL(&rRecordExpr.QRYCRIT1EXPRTEXT.Value, &rRecordExpr.QRYCRIT1EXPRNUM.Value);
               End-For;
            End-If;
         End-For;
      Else
         /* 15928109 */
         /* when not running query from query manager edit mode run button*/
         Local Rowset &rsExpr = CreateRowset(Record.PSQRYEXPR);
         &rsExpr.Fill("WHERE QRYNAME = :1 AND FIELDTYPE = 11", &QryName);
         If &rsExpr(1).IsNew = False Then
            For &i = 1 To &rsExpr.ActiveRowCount
               &rRecordExpr = &rsExpr(&i).PSQRYEXPR;
               &QryObj.SetTrackingURL(&rRecordExpr.EXPRESSIONTEXT.Value, &rRecordExpr.EXPNUM.Value);
            End-For;
         End-If;
         /* 15928109 */
      End-If;
      /* 1718360000 */
   End-If;

   %Response.WriteBinary(&QryObj.FormatBinaryResultString(&gQueryRowset, %Query_XLS, 0, 0));
   If IsBiffEnabled() = True And
         &gQueryRowset.ActiveRowCount > 65536 Then
      %Response.SetContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;");
      &sTempString = "attachment; filename=" | &QryName | "_" | Int(Rand() * 10000) | ".xlsx";
      %Response.SetHeader("Content-Disposition", &sTempString);
   End-If;

   &QryObj.close();
   &QryObj = Null;
   rem &gQueryRowset.Flush(); /* No longer need global reference */
   &gQueryRowset = Null;

   Return;

End-Function;

/* 1746200000 */
Function IScript_ToXML();
   Local string &s;
   Local string &QryName, &QryDescr, &PrivateFlag;
   Local ApiObject &QryObj;
   Local Rowset &rsURLList;
   Local Record &rRecordExpr;
   Local string &sTempString;
   /* 18132040 */
   Local boolean &bPublic = False;
   Local integer &nUnionCount;
   /* 18132040 */

   /* 1453405000 - 9th oct 2006 - start*/
   Local string &sPromptString;
   &sPromptString = &gQueryRec.GetField(Field.EXPRESSIONTEXT).Value;
   /* 1453405000 - 9th oct 2006 - end*/

   &QryName = &gQueryRec.GetField(Field.QRYNAME).Value;
   If Not &QryName = "" Then
      %Response.SetContentType("application/download;");
      &sTempString = "attachment; filename=" | EncodeURL(&QryName) | ".xml"; /*33109313*/
   Else
      %Response.SetContentType("application/xml;");
      &sTempString = "attachment;";
   End-If;
   %Response.SetHeader("Content-Disposition", &sTempString);
   &QryObj = %Session.GetQuery();
   /* 1384908000 - 9th oct 2006 */
   If (&QryName = "") Then
      &QryName = "New Unsaved Query";
   End-If;
   &QryObj.AddQueryName(&QryName);
   /* 1384908000 - 9th oct 2006 - end*/
   /* 1453405000 - 9th oct 2006 */
   &QryObj.AddPromptDesc(&sPromptString);
   /* 1453405000 - 9th oct 2006 - end*/

   /* 1718360000 */

   /* 18132040 */
   If &gQueryRec.GetField(Field.PRIVATE_QUERY_FLAG).Value = "N" Then
      &bPublic = True;
   Else
      &bPublic = False;
   End-If;
   /* 18132040 */
   If &QryObj.Open(&QryName, &bPublic, False) = 0 Then
      If &gLevelList <> Null Then
         For &nUnionCount = 1 To &gLevelList.ActiveRowCount;
            &rsURLList = &gLevelList(&nUnionCount).GetRowset(&gURLINDEX);
            If &rsURLList <> Null And
                  &rsURLList.ActiveRowCount >= 1 And
                  All(&rsURLList(1).QRY_URL_WRK.QRYCRIT1EXPRTEXT.Value) Then
               For &nCount = 1 To &rsURLList.ActiveRowCount;
                  &rRecordExpr = &rsURLList(&nCount).QRY_URL_WRK;
                  &QryObj.SetTrackingURL(&rRecordExpr.QRYCRIT1EXPRTEXT.Value, &rRecordExpr.QRYCRIT1EXPRNUM.Value);

               End-For;
            End-If;
         End-For;
      End-If;
      /* 1718360000 */
   End-If;
   %Response.WriteLine("<?xml version='1.0'?>");
   &sTempString = "<query numrows=""" | String(&gQueryRowset.ActiveRowCount) | """ queryname=""" | &QryName | """ xmlns:xsi=""http://www.w3.org/2001/XMLSchema-instance"" xsi:noNamespaceSchemaLocation="""">";
   %Response.WriteLine(&sTempString);
   %Response.Write(&QryObj.FormatResultString(&gQueryRowset, %Query_XML_XmlP, 1, &gQueryRowset.ActiveRowCount));
   %Response.WriteLine("</query>");
   &QryObj.close();
   &QryObj = Null;
   &gQueryRowset = Null;

   Return;

End-Function;

/* 1746200000 */

Function IScript_GetCrystalURL()

   Local string &sURL, &sPublic, &sQRY, &sError;
   Local number &iErrorCount = 0;

   &sQRY = Unencode(%Request.GetParameter("Qry"));
   &sPublic = %Request.GetParameter("Public");
   /*1942924007*/
   &sPublic = EscapeHTML(&sPublic);
   &CESessionMngr = CreateJavaObject("com.peoplesoft.pt.crystalenterprise.CESessionManager");

   &CESessionMngr.logOn();
   &CESession = &CESessionMngr.getCESession();

   rem %Response.Write("<HTML><BODY>" | &CESession.toString() | "<BR><BR></BODY></HTML>");

   If (&CESession.errorCount() <= 0) Then
      &CEReport = &CESessionMngr.createReport();
   End-If;

   If (&CESession.errorCount() <= 0) Then
      &CEReport.createFromQuery(&sQRY | &sPublic, &sQRY | %Datetime);
   End-If;

   If (&CESession.errorCount() <= 0) Then
      &sURL = &CEReport.getAdhocURL();
   End-If;


   If (&CESession.errorCount() > 0) Then
      &CEException = CreateJavaObject("com.peoplesoft.pt.crystalenterprise.CEException");

      &iErrorCount = &CESession.errorCount();

      For &i = 1 To &iErrorCount;
         &CEException = &CESession.popError();
         &sError = &sError | "Exception [" | &iErrorCount | "] " | &CEException.getDefaultTextHTML();
         rem &sError = &sError | "Trace [" | &iErrorCount | "] " | &CEException.getStackTraceHTML();
      End-For;


   End-If;

   &CESession.logOff();



   &CEReport = Null;
   &CESessionMngr = Null;
   &CESession = Null;

   If (&iErrorCount > 0) Then
      %Response.Write("<HTML><BODY>" | &sError | "</BODY></HTML>");
   Else
      %Response.RedirectURL(&sURL);
   End-If;


End-Function;

Function GetRTEURL() Returns string

   Local string &strLogoutURL = &Request.LogoutURL;
   Local integer &POS, &POS1;

   &POS = (Find("/psp/", &strLogoutURL) + 5);
   &POS2 = (Find("/", &strLogoutURL, &POS));

   /* needs to return /ps/ */
   Return Substring(&strLogoutURL, &POS - 1, &POS2 - &POS + 2);

End-Function;

Function IScript_QueryFeed_RtPopup()
   &Request = %Request;
   &Response = %Response;
   Local string &qryname = &Request.GetParameter("queryname");
   Local string &conn_qry_name = &Request.GetParameter("conn_qry_name");
   Local string &qrycolumns = "";
   Local string &sysvars = "";
   Local string &NEWLINE = Char(13) | Char(10);

   /*1942924007*/
   &qryname = EscapeHTML(&qryname);

   If All(&conn_qry_name) Then
      &conn_qry_name = EscapeHTML(&conn_qry_name);
   Else
      &conn_qry_name = "";
   End-If;

   &qrycolumns = "items :" | &NEWLINE | "[" | &NEWLINE;
   If All(&qryname) Then
      Local ApiObject &qry = %Session.getquery();
      Local integer &colcount;
      Local ApiObject &coll;
      Local ApiObject &fld;
      Local string &qrycolumn;

      If &qry.open(&qryname, False, False) = 0 Then
         &coll = &qry.QuerySelect.QueryOutputFields;
         For &colcount = 1 To &coll.count
            &fld = &coll.item(&colcount);
            If None(&fld.recordalias) Then
               &qrycolumn = &fld.name;
            Else
               &qrycolumn = &fld.recordalias | "." | &fld.name;
            End-If;
            &qrycolumns = &qrycolumns | "[ '" | &qrycolumn | "' , '" | &qrycolumn | "' ]," | &NEWLINE;
         End-For;
      End-If;
   End-If;

   &qrycolumns = &qrycolumns | &NEWLINE | "[ 'GUID', 'GUID' ]" | &NEWLINE | "]";

   Local SQL &sqlSysVar;
   Local string &sVar;
   &sqlSysVar = CreateSQL("SELECT PTFP_VALUE FROM PS_PTFP_SYSVAR ");

   &sysvars = "items :" | &NEWLINE | "[" | &NEWLINE;
   &sysvars = &sysvars | &NEWLINE | "[ '%DateTime', '%DateTime' ]" | &NEWLINE;
   While &sqlSysVar.Fetch(&sVar);
      If Not &sVar = "%DateTime" Then
         &sysvars = &sysvars | "," | &NEWLINE | "[ '" | &sVar | "' , '" | &sVar | "' ]" | &NEWLINE;
      End-If;
   End-While;
   &sqlSysVar.Close();
   &sysvars = &sysvars | &NEWLINE | "]";



   /*Start get locale specific strings*/
   Local string &lblQryFld;
   Local string &lblSysVar;
   Local string &lblTmpl;
   Local string &lblMsgCatTxt;
   Local string &lblMsgCatExpl;


   Local string &lblMsgSet;
   Local string &lblMsgId;

   Local string &lblMsgCat;
   Local string &errMsgSet;
   Local string &errMsgId;

   Local integer &mapcnt;
   Local Rowset &rs = CreateRowset(Record.PSXLATITEM);
   &rs.Fill("WHERE FIELDNAME = :1", "PTPSQRY_EMT_TYPE");
   For &mapcnt = 1 To &rs.ActiveRowCount
      Local string &key = &rs.GetRow(&mapcnt).GetRecord(Record.PSXLATITEM).GetField(Field.FIELDVALUE).Value;
      Local string &value = &rs.GetRow(&mapcnt).GetRecord(Record.PSXLATITEM).GetField(Field.XLATLONGNAME).Value;
      Evaluate &key
      When "MSGE"
         &lblMsgCatExpl = &value;
         Break;
      When "MSGT"
         &lblMsgCatTxt = &value;
         Break;
      When "SYSV"
         &lblSysVar = &value;
         Break;
      When "QUER"
         &lblQryFld = &value;
         Break;
      When "TMPL"
         &lblTmpl = &value;
         Break;
      End-Evaluate;
   End-For;

   &lblMsgCat = MsgGetText(139, 552, "Message not found: Message Catalog");
   &lblMsgId = MsgGetText(139, 553, "Message not found: Message Number");
   &lblMsgSet = MsgGetText(139, 554, "Message not found: Message Set");
   &errMsgSet = MsgGetText(139, 583, "Message not found: Invalid Input for Message Set or Message Number");
   &errMsgId = MsgGetText(139, 583, "Message not found: Invalid Input for Message Set or Message Number");

   Local string &dailogLabel = MsgGetText(139, 551, "Message not found: Insert Bind Variables");


   &HTML = GetHTMLText(HTML.PT_QRY_BIND_VARS, &qrycolumns, &sysvars, &lblQryFld, &lblMsgCat, &lblSysVar, &lblTmpl, &lblMsgCatTxt, &lblMsgCatExpl, &lblMsgSet, &lblMsgId, &errMsgSet, &errMsgId, &dailogLabel, &qryname, &conn_qry_name);
   &Response.Write(&HTML);
End-Function;

