/********************************************************************************
* Function CreateIScriptURL
*    Creates  URL for calling IScript
********************************************************************************/

Function CreateIScriptURL(&sURL) Returns string
   Local string &url;
   &url = "";
   &obj = %Request;
   If All(&obj) Then
      &portal = %Portal;
      &Node = %Node;
      rem currently in not in Portal, %PORTAL doesn't return anything;
      rem putting dummy name in for &PORTAL so the URL doesn't break;
      If &portal = "" Then
         &portal = "PORTAL";
         &Node = %LocalNode;
      End-If;
      /* Backing out the change for ICE 101832000 because it is no longer needed */
      &url = GenerateComponentContentURL(&portal, &Node, MenuName.MAINTAIN_SECURITY, "GBL", Component.USERMAINT, "", "");
      &Find = Find("/", &url);
      While &Find <> 0
         &pos = &Find;
         &Find = Find("/", &url, &Find + 1);
      End-While;
      rem add one to &find;
      &pos = &pos - 2;
      &url = Left(&url, &pos);
      &url = &url | "s/" | &sURL;
   End-If;
   Return &url;
End-Function; /* CreateIScriptURL */

