********************************************************************************/
Function CreateQueryCrystalURL(&sQueryName As string, &isPublic As boolean) Returns string
   Local string &sUrl, &sPublic;
   Local number &nPos;

   &obj = %Request;
   If All(&obj) Then

      &portal = %Portal;
      &Node = %Node;

      If &portal = "" Then
         &portal = "PORTAL";
         &Node = %LocalNode;
      End-If;

      If (&isPublic = True) Then
         &sPublic = "&Public=";
      Else
         &sPublic = "&Public=*";
      End-If;

      &sUrl = GenerateScriptContentURL(&portal, &Node, Record.WEBLIB_QUERY, Field.ISCRIPT2, "FieldFormula", "IScript_GetCrystalURL");

      &sUrl = &sUrl | "?Qry=" | EncodeURLForQueryString(&sQueryName) | &sPublic;

      &sUrl = "javascript:void window.open('" | &sUrl | "','u','scrollbars=yes,status=no,location=yes,resizable=yes,width=700,height=500,left=150,top=100')";

   End-If;

   Return &sUrl;

End-Function; /* CreateQueryCrystalURL */

