Function IScript_execute

   &GblFilterRec = CreateRecord(Record.HRRC_GBL_FILTER);

   &MENUNAME = "HRRC_MANAGER_FL";
   &sURL = GenerateComponentContentRelURL(%Portal, %Node, @("MenuName." | &MENUNAME), %Market, Component.HRRC_MSS_RECOG_FL, Page.HRRC_MSS_RECOG_FL, "U");

