Global Record &GblFilterRec;
Global array of number &GblNewRecogArray;
Local string &MENUNAME, &sURL;
Local Record &recRecipient;
Local number &i, &id;
Local SQL &sqlNew;

Function IScript_execute

   &GblFilterRec = CreateRecord(Record.HRRC_GBL_FILTER);


   /* save "new" recognitions in an array */
   &GblNewRecogArray = CreateArrayRept(0, 0);
   &sqlNew = CreateSQL("Select RC_RECOG_ID from PS_HRRC_RECOG_RECP where RC_EMPLID_RECEIVED = :1 and RC_EE_VIEWED_YN = 'N'", %EmployeeId);
   While &sqlNew.Fetch(&id)
      &GblNewRecogArray.Push(&id);
   End-While;

   If &GblNewRecogArray.Len > 0 Then
      For &i = 1 To &GblNewRecogArray.Len
         &recRecipient = CreateRecord(Record.HRRC_RECOG_RECP);
         &recRecipient.RC_RECOG_ID.Value = &GblNewRecogArray [&i];
         &recRecipient.RC_EMPLID_RECEIVED.Value = %EmployeeId;
         If &recRecipient.SelectByKey() Then
            &recRecipient.RC_EE_VIEWED_YN.Value = "Y";
            &recRecipient.Update();
         End-If;
      End-For;

   End-If;

   &MENUNAME = "HRRC_EMPLOYEE_FL";
   &sURL = GenerateComponentContentRelURL(%Portal, %Node, @("MenuName." | &MENUNAME), %Market, Component.HRRC_ESS_RECOG_FL, Page.HRRC_ESS_RECOG_FL, "U");

   %Response.RedirectURL(&sURL);

End-Function;

