REM ***************************************************************************************;
REM Function:		IScript_GetReport								  ;
REM Purpose:		Generate HTML page for Report Notification                             ;
REM Inputs:												  ;
REM Output:				                                                         ;
REM ***************************************************************************************;

Function IScript_GetReport()
   &ps_RenSrv = EscapeHTML(%Request.GetParameter("RenSrv"));
   If (All(&ps_RenSrv)) Then
      ValidateRenServer(&ps_RenSrv);
   End-If;

   &ps_prcsID = EscapeHTML(%Request.GetParameter("PrcsInst"));
   &ps_MsgNum = EscapeHTML(%Request.GetParameter("MsgNum"));
   &ps_MsgSet = EscapeHTML(%Request.GetParameter("MsgSet"));
   &ps_status = EscapeHTML(%Request.GetParameter("ps_status"));
   &ps_msg = EscapeHTML(%Request.GetParameter("ps_msg"));

   If All(&ps_MsgSet, &ps_MsgNum) Then
      &ps_MsgTxt = MsgGetExplainText(&ps_MsgSet, &ps_MsgNum, "This window will show your report when it has completed.");
      If None(&ps_MsgTxt) Then
         &ps_MsgTxt = MsgGetText(&ps_MsgSet, &ps_MsgNum, "This window will show your report when it has completed.");
      End-If;
   Else
      &ps_MsgTxt = "";
   End-If;

   If (&ps_MsgTxt <> "") Then
      &ps_MsgTxt = "<p>" | &ps_MsgTxt | "</p>";
   End-If;

   &sRptItems = CreateRowset(Record.PMN_PRCSLIST);
   &sRptItems.Fill("where PRCSINSTANCE= :1", Value(&ps_prcsID));

   &prcsName = &sRptItems.GetRow(1).GetRecord(1).PRCSNAME.Value;
   &prcsType = &sRptItems.GetRow(1).GetRecord(1).PRCSTYPE.Value;
   &runID = &sRptItems.GetRow(1).GetRecord(1).RUNCNTLID.Value;

   SQLExec(" select LANGUAGE_CD from PSOPTIONS", &ps_langCd);
   /*-------------------------*/
   /* Get Process Description */
   If %Language = &ps_langCd Then
      /* base language */
      SQLExec("SELECT DESCR FROM PS_PRCSDEFN WHERE PRCSTYPE = :1 AND PRCSNAME = :2", &prcsType, &prcsName, &ps_descr);
   Else
      /* non-base language */
      SQLExec("SELECT COUNT(*) FROM PS_PRCSDEFNLANG WHERE PRCSTYPE = :1 AND PRCSNAME = :2 AND LANGUAGE_CD = :3 ", &prcsType, &prcsName, %Language, &rowCnt);
      If &rowCnt > 0 Then
         SQLExec("SELECT DESCR FROM PS_PRCSDEFNLANG WHERE PRCSTYPE = :1 AND PRCSNAME = :2 AND LANGUAGE_CD = :3 ", &prcsType, &prcsName, %Language, &ps_descr);
      Else
         /* no related language, use base language */
         /* ICE 1312619000 - fixed mistype variable name */
         SQLExec("SELECT DESCR FROM PS_PRCSDEFN WHERE PRCSTYPE = :1 AND PRCSNAME = :2", &prcsType, &prcsName, &ps_descr);
      End-If;
   End-If;

   /*-------------------------*/
   SQLExec(" select CONTENTID from PS_CDM_LIST WHERE PRCSINSTANCE = :1 AND LOGFILEONLY_FLAG = '0' ", Value(&ps_prcsID), &cntID);

   &PMNURL = GenerateComponentContentURL(%Portal, %Node, MenuName.PROCESSMONITOR, %Market, Component.PROCESSMONITOR, Page.PMN_PRCSLIST, "U");
   &cssPTSTYLEDEF = %Response.GetStyleSheetURL(StyleSheet.PTSTYLEDEF);

   &rec = CreateRecord(Record.PMN_RUNSTATUS);

   If All(&ps_status) Then
      &rec.RUNSTATUS.Value = &ps_status;
   Else
      &rec.RUNSTATUS.Value = "5";
   End-If;
   If All(&cntID) Then
      &HTML = GetHTMLText(HTML.PRCS_PSGETREPORTS, &prcsType | " - " | &prcsName, &ps_prcsID, &prcsName, &cssPTSTYLEDEF, &cntID, %DbName, &ps_RenSrv, &prcsType, MsgGetText(65, 229, "Report ID:"), MsgGetText(65, 230, "Process Instance:"), MsgGetText(65, 227, "Process Name:"), MsgGetText(65, 228, "Process Type:"), MsgGetText(65, 236, "Unable to connect to RenServer"), &ps_MsgTxt, &PMNURL, &ps_descr, &rec.RUNSTATUS.shorttranslatevalue, &ps_msg);
   Else
      &HTML = GetHTMLText(HTML.PRCS_PSGETREPORTS, &prcsType | " - " | &prcsName, &ps_prcsID, &prcsName, &cssPTSTYLEDEF, "", %DbName, &ps_RenSrv, &prcsType, "", MsgGetText(65, 230, "Process Instance:"), MsgGetText(65, 227, "Process Name:"), MsgGetText(65, 228, "Process Type:"), MsgGetText(65, 236, "Unable to connect to RenServer"), &ps_MsgTxt, &PMNURL, &ps_descr, &rec.RUNSTATUS.shorttranslatevalue, &ps_msg);
   End-If;

   %Response.Write(&HTML);
End-Function;

