/* ===> Declare and instantiate: */
Local Interlink &SDK_AMORTIZAT_1;
Local BIDocs &inDoc;
Local BIDocs &outDoc;
Local boolean &RSLT;
Local number &EXECRSLT;

/*
 * This pagelet displays mortgage calculations for either payment (when principal, etc. are provided)
 * or for principal (when payment, etc. are provided).  The variables can be set on the 
 * personalization page (Page.SDK_AMORT_PREF).  
 *
 * This pagelet demonstrates using a Business Interlink that calls PSHttpEnable.  
 * It invokes a servlet (PSUBITester.class) to perform the mortgage calculation.
 * This file needs to be installed in your local web server servlets directory.
 */
Function IScript_Amortization()

   /* ===>
    * Much of this code is a dynamically generated PeopleCode template created when 
    * dragging a Business Interlink object into this PeopleCode editor.
    * Any initial references to '<*>' OR default values with need to be replaced with
    * references to PeopleCode variables and/or a Rec.Fields.
    * Additional code was also added for processing specific to this mortgage calculator.
    */

   &SDK_AMORTIZAT_1 = GetInterlink(Interlink.SDK_AMORTIZATION);

   /* ===> You can use the following assignments to set the configuration parameters.
*/
   rem &SDK_AMORTIZAT_1.MerchantURL = "http://localhost/servlets/PSUBITester";
   rem &SDK_AMORTIZAT_1.Simulated_Response_File_Name = <*>;
   rem &SDK_AMORTIZAT_1.Request_File_Name = "c:\temp\DebugAmortizationRequest.txt";
   rem &SDK_AMORTIZAT_1.Response_File_Name = "c:\temp\DebugAmortizationResponse.txt";


   /* Get the inputs from the personalization table (or use default values)
*/
   SQLExec(SQL.SDK_AMORT_GET_PREFS, %OperatorId, &calculate, &origPrincipal, &regularPayment, &interest, &years, &frequency, &showSchedule);
   If None(&calculate) Then
      &calculate = "01";
      &origPrincipal = 100000;
      &interest = 7;
      &years = 30;
      &frequency = 12;
      &showSchedule = "N";
   End-If;
   If &calculate = "01" Then
      &calculate = "Payment";
      &regularPaymentStr = "";
      &origPrincipalStr = String(&origPrincipal);
      &principalStyle = "";
      &principalEndStyle = "";
      &paymentStyle = "<b>";
      &paymentEndStyle = "</b>";
   Else
      &calculate = "Principal";
      &regularPaymentStr = String(&regularPayment);
      &origPrincipalStr = "";
      &principalStyle = "<b>";
      &principalEndStyle = "</b>";
      &paymentStyle = "";
      &paymentEndStyle = "";
   End-If;
   If &showSchedule = "N" Then
      &showSchedule = "No";
   Else
      &showSchedule = "Yes";
   End-If;

   /* ===> Add inputs: */
   &inDoc = &SDK_AMORTIZAT_1.GetInputDocs("");
   &ret = &inDoc.AddValue("principal", &origPrincipalStr);
   &ret = &inDoc.AddValue("payment", &regularPaymentStr);
   &ret = &inDoc.AddValue("interest", String(&interest));
   &ret = &inDoc.AddValue("years", String(&years));
   &ret = &inDoc.AddValue("freq", String(&frequency));
   &ret = &inDoc.AddValue("schedule", &showSchedule);
   &ret = &inDoc.AddValue("calculate", &calculate);

   /* ===> The following statement executes this instance: */
   &EXECRSLT = &SDK_AMORTIZAT_1.Execute();
   If (&EXECRSLT <> 1) Then
      /* The instance failed to execute */
   Else
      &outDoc = &SDK_AMORTIZAT_1.GetOutputDocs("");
      &ret = &outDoc.GetValue("return_status", &retStatus);
      &ret = &outDoc.GetValue("return_status_msg", &retStatusMsg);
      If (&retStatus = 200 And
            &retStatusMsg = "OK") Then

         &AmortPlannerDoc = &outDoc.GetDoc("AmortizationPlanner");
         &errorDoc = &AmortPlannerDoc.GetDoc("error");
         &ret = &errorDoc.GetValue("errorcode", &errCode);
         &ret = &errorDoc.GetValue("errormessage", &errMsg);

         /*
	   * Extract the calculated value and display a summary of the mortgage.
	   */
         &ret = &AmortPlannerDoc.GetValue("payment", &regularPayment);
         &ret = &AmortPlannerDoc.GetValue("principal", &origPrincipal);
         &summary1 = &principalStyle | MsgGetText(95, 6041, "MESSAGE NOT FOUND: Principal") | " = " | String(Round(&origPrincipal, 2)) | &principalEndStyle | "<br>" | &paymentStyle | MsgGetText(95, 6042, "MESSAGE NOT FOUND: Payment") | " = " | String(Round(&regularPayment, 2)) | &paymentEndStyle;
         &summary2 = String(Round(&interest, 3)) | "% " | MsgGetText(95, 6043, "MESSAGE NOT FOUND: Interest") | "<br>" | String(&years) | " " | MsgGetText(95, 6044, "MESSAGE NOT FOUND: Years") | "<br>" | String(&frequency) | " " | MsgGetText(95, 6045, "MESSAGE NOT FOUND: Frequency");
         &summaryText = GetHTMLText(HTML.SDK_AMORTIZATION_SUMMARY, &summary1, &summary2);

         &TableDoc = &AmortPlannerDoc.GetDoc("Table");
         &PaymentNumberDoc = &TableDoc.GetDoc("PaymentNumber");
         &itemcnt = &PaymentNumberDoc.GetCount("PaymentNumber");
         &ret = &PaymentNumberDoc.GetValue("period", &period);

         /*
	   * If the mortgage schedule was requested & sent, print out the data.
	   */
         If &itemcnt >= 1 And
               All(&period) Then
            For &i = 1 To &itemcnt
               &ret = &PaymentNumberDoc.GetValue("InterestPaid", &intPaid);
               &ret = &PaymentNumberDoc.GetValue("PrincipalPaid", &prinPaid);
               &ret = &PaymentNumberDoc.GetValue("PrincipalToBePaid", &prinRemaining);

               &remainder = Mod(&i, 2);
               If (&remainder = 0) Then
                  &rowStyle = "PSLEVEL1GRIDEVENROW";
               Else
                  &rowStyle = "PSLEVEL1GRIDODDROW";
               End-If;

               &paymentRowsText = &paymentRowsText | GetHTMLText(HTML.SDK_AMORTIZATION_PYMT_ROW, &period, String(Round(&intPaid, 2)), String(Round(&prinPaid, 2)), String(Round(&prinRemaining, 2)), &rowStyle);
               If &itemcnt > 1 Then
                  &paymentHdrText = GetHTMLText(HTML.SDK_AMORTIZATION_PYMT_HDR);
               End-If;
               &ret = &PaymentNumberDoc.GetNextDoc();
               &ret = &PaymentNumberDoc.GetValue("period", &period);
            End-For;
         End-If;
      Else
         /* Invalid response */
      End-If;

      %Response.WriteLine(GetHTMLText(HTML.SDK_AMORTIZATION_TABLE, &summaryText, &paymentHdrText, &paymentRowsText));
   End-If; /* If NOT &RSLT ... */

End-Function;

