/* ===> DeclaSELECT * from PS_SDK_STK_LKP_Dre and instantiate: */
Local Interlink &STOCKQUOTE_1;
Local BIDocs &inDoc;
Local BIDocs &outDoc;
Local boolean &RSLT;
Local number &EXECRSLT;
Local ApiObject &Session;
Local ApiObject &SDK_STOCK_DATA;
Local ApiObject &PSMessages;
Local string &ErrorText, &ErrorType, &TEMP;
Local number &ErrorCount;
Local boolean &Error;
Local array of string &to_download;
Local array of string &to_retrieve;
Local datetime &thedatetime;
Local string &response_string;
Local time &the_time;
Local boolean &military_time;

Function contains_mixed_case(&str_candidate) Returns boolean
   If (Upper(&str_candidate) = &str_candidate) Or
         (Lower(&str_candidate) = &str_candidate) Then
      Return False;
   Else
      Return True;
   End-If;
End-Function;


Function format2decs(&dec) Returns string
   &str = String(&dec);
   If Len(&str) = 1 Then
      &str = "0" | &str;
   End-If;
   Return &str;
End-Function;

Function format_time(&the_time, &military_time, &show_seconds) Returns string
   &temp_hr = Hour(&the_time);
   &temp_min = Minute(&the_time);
   &temp_sec = Second(&the_time);
   If &military_time = False Then

      Evaluate &temp_hr
      When > 12
         &temp_hr = Value(&temp_hr - 12);
         &ampm = "PM";
         Break;
      When = 12
         &ampm = "PM";
         Break;
      When = 0
         &temp_hr = 12;
         &ampm = "AM";
         Break;
      When-Other
         &ampm = "AM";
         Break;
      End-Evaluate;

      If &show_seconds = True Then
         &return_time = String(&temp_hr) | ":" | format2decs(&temp_min) | ":" | format2decs(&temp_sec) | " " | &ampm;
      Else
         &return_time = String(&temp_hr) | ":" | format2decs(&temp_min) | " " | &ampm;
      End-If;

   Else

      &return_time = format2decs(&temp_hr) | ":" | format2decs(&temp_min) | ":" | format2decs(&temp_sec);
   End-If;
   Return &return_time;
End-Function;

Function CheckErrorCodes()
   /* Disabled because first line causing Internal Server Error in portal.
   &PSMessages = &Session.PSMessages;
   &ErrorCount = &PSMessages.Count;
   For &i = 1 To &ErrorCount
      &ErrorText = &PSMessages.Item(&i).Text;
      &ErrorType = &PSMessages.Item(&i).Type;
   End-For;
   */
End-Function;

Function AccessStockCI(&tsymbol, &price, &change, &lastTime, &size, &volume, &open, &high, &low, &close, &bid, &ask, &bidAskSize, &exchange, &name, &yrhigh, &yrlow, &divfreq, &dividend, &earnings, &shares, &peratio, &divdate, &volatility, &yeild)

   REM Initialize Variables --;
   &Error = False;
   REM  Get Session and Connect ;
   &Session = GetSession();
   &Connect = &Session.Connect(1, "EXISTING", "", "", 0);

   If Not &Connect Then
      CheckErrorCodes();
      REM  *** Application Specific Error Processing ;
   Else
      &SDK_STOCK_DATA = &Session.GetCompIntfc(CompIntfc.SDK_STOCK_DATA);

      If &SDK_STOCK_DATA = Null Then
         CheckErrorCodes();
         /* *** Application Specific Error Processing */
      Else
         /* Set Component Interface Standard Properties */
         &SDK_STOCK_DATA.InteractiveMode = False;
         &SDK_STOCK_DATA.GetHistoryItems = True;

         /* See if already exists */
         &SDK_STOCK_DATA.SDK_STOCK_TICKER = &tsymbol;
         &SDK_STOCK_DATA.SDK_STOCK_EXCHANGE = &exchange;
         If Not &SDK_STOCK_DATA.Get() Then
            /* Set Component Interface Create Keys */
            &SDK_STOCK_DATA.Cancel();
            &SDK_STOCK_DATA.SDK_STOCK_TICKER = &tsymbol;
            &SDK_STOCK_DATA.SDK_STOCK_EXCHANGE = &exchange;
            If Not &SDK_STOCK_DATA.Create() Then
               CheckErrorCodes();
               &Error = True;
               /* Application Specific Error Processing */
            End-If;
         End-If;

         If Not &Error Then
            /* Set Level 0 Field Properties */
            &SDK_STOCK_DATA.sdk_STOCK_TICKER = &tsymbol;
            &SDK_STOCK_DATA.sdk_STOCK_EXCHANGE = &exchange;
            &SDK_STOCK_DATA.sdk_DESCR = "Retrieved From pcquote.com.";
            &SDK_STOCK_DATA.sdk_LAST_TRADE = &price;
            &SDK_STOCK_DATA.sdk_LAST_TRADE_SIZ = &size;
            &SDK_STOCK_DATA.sdk_LAST_TRADE_DT = %Datetime;
            &SDK_STOCK_DATA.sdk_LAST_TRADE_TME = &lastTime;
            &SDK_STOCK_DATA.sdk_TOTAL_SHARES = &volume;
            &SDK_STOCK_DATA.sdk_STOCK_NET_CHG = &change;
            &SDK_STOCK_DATA.sdk_OPENING_TRADE = &open;
            &SDK_STOCK_DATA.sdk_CLOSING_TRADE = &close;
            &SDK_STOCK_DATA.sdk_BID_PRICE = &bid;
            &SDK_STOCK_DATA.sdk_ASK_PRICE = &ask;
            &SDK_STOCK_DATA.sdk_BID_X_ASK_SIZE = &bidAskSize;
            &SDK_STOCK_DATA.sdk_HIGH_TRADE = &high;
            &SDK_STOCK_DATA.sdk_LOW_TRADE = &low;
            &SDK_STOCK_DATA.sdk_LASTUPDDTTM = %Datetime;
            &SDK_STOCK_DATA.sdk_STOCKCOMP_NAME = &name;
            &SDK_STOCK_DATA.sdk_YEAR_HIGH = &yrhigh;
            &SDK_STOCK_DATA.sdk_YEAR_LOW = &yrlow;
            &SDK_STOCK_DATA.sdk_STK_DIVID_FREQ = &divfreq;
            &SDK_STOCK_DATA.sdk_DIVIDEND_AMT = &dividend;
            &SDK_STOCK_DATA.sdk_EARNINGS_SHARE = &earnings;
            &SDK_STOCK_DATA.sdk_SHARE_OUTSTAND = &shares;
            &SDK_STOCK_DATA.sdk_PE_RATIO = &peratio;
            &SDK_STOCK_DATA.sdk_EX_DIVIDEND_DT = &divdate;
            &SDK_STOCK_DATA.sdk_VOLATILITY = &volatility;
            &SDK_STOCK_DATA.sdk_YIELD = &yield;

            /* Save Instance of Component Interface */
            If Not &SDK_STOCK_DATA.Save() Then
               CheckErrorCodes();
               REM Application Specific Error Processing --;
            End-If;
         End-If;
         /* End: Set Component Interface Properties */

         /* Cancel Instance of Component Interface */
         &SDK_STOCK_DATA.Cancel();
      End-If;
   End-If;
   &Session.disconnect();
End-Function;

Function IScript_Stock()
   &response_string = "";
   &to_download = CreateArrayRept("empty", 0);
   &to_retrieve = CreateArrayRept("empty", 0);

   SQLExec("SELECT SDK_PORTFOLIO_NAME, SDK_TICKER_SYMBOLS FROM PS_SDK_STOCK_PRF WHERE SDK_OPRID=:1", %OperatorId, &port_name, &tickers);

   &user_ticker_list = Split(&tickers, ",");
   If &user_ticker_list.len = 0 Then
      &response_string = &response_string | ("<font class=""PAADDITIONALINSTRUCTIONS"">" | MsgGetText(18025, 945, "MESSAGE NOT FOUND" | "</font>"));

      &user_ticker_list.push("PSFT");
      &user_ticker_list.push("AAPL");
      &user_ticker_list.push("NKE");
      &user_ticker_list.push("TWX");
      &user_ticker_list.push("DIS");
   End-If;


   /* Convert any non-mixed case symbols to all uppercase. */

   For &i = 1 To &user_ticker_list.len
      If (contains_mixed_case(&user_ticker_list [&i])) = False Then
         &user_ticker_list [&i] = Upper(&user_ticker_list [&i]);
      End-If;
   End-For;

   For &i = 1 To &user_ticker_list.len
      &lastUpdate = Null;
      SQLExec("SELECT %DATETIMEOUT(SDK_LASTUPDDTTM) FROM PS_SDK_STOCK WHERE SDK_STOCK_TICKER=:1", &user_ticker_list [&i], &lastUpdate);

      If None(&lastUpdate) Or
            AddToDateTime(%Datetime, 0, 0, 0, 0, - 15, 0) > &lastUpdate Then
         &to_download.Push(&user_ticker_list [&i]);
      Else
         &to_retrieve.Push(&user_ticker_list [&i]);
      End-If;
   End-For;

   /* At this point, it is known which stocks should be downloaded, and which should be retrieved from cache */

   /* Write Header Info */

   &response_string = &response_string | ("<table border=""0"" cellpadding=""1"" cellspacing=""0"" width=""100%""><tr><td bgcolor=""#EEEEEE"">");
   &response_string = &response_string | ("<table border=""0"" width=""100%"" cellspacing=""1"" cellpadding=""1"">");
   If &port_name <> "" Then

      &response_string = &response_string | (" <tr><td colspan=5 bgcolor=""#ffffff"" align=""CENTER"" nowrap><font class=""PABOLDTEXT"">");
      &response_string = &response_string | (&port_name);
      &response_string = &response_string | ("<br></font></td></tr>");

   End-If;

   &response_string = &response_string | ("<tr><td width=""20%"" nowrap><font class=""PSTCONTENTDESCR"">Symbol</font></td> <td width=""20%"" align=""" | %AlignEnd | """ nowrap><font class=""PSTCONTENTDESCR"">Last Trade</font></td><td width=""20%"" align=""" | %AlignEnd | """ nowrap><font class=""PSTCONTENTDESCR"">Change</font></td> <td width=""20%"" align=""" | %AlignEnd | """ nowrap><font class=""PSTCONTENTDESCR"">Low</font></td><td width=""20%"" align=""" | %AlignEnd | """ nowrap><font class=""PSTCONTENTDESCR"">High</font></td></tr>");

   /* Download appropriate stocks and populate database. */

   If &to_download.Len > 0 Then
      &STOCKQUOTE_1 = GetInterlink(Interlink.SDK_MYQUOTE_BI);
      &inDoc = &STOCKQUOTE_1.GetInputDocs("");
      &downloadtickers = "";

      For &j = 1 To &to_download.Len
         &downloadtickers = &downloadtickers | &to_download [&j];
         /* add comma if not on last symbol */
         If &j <> &to_download.Len Then
            &downloadtickers = &downloadtickers | ",";
         End-If;
      End-For;

      &ret = &inDoc.AddValue("TICKER", &downloadtickers);
      &ret = &inDoc.AddValue("SHOWSTATUS", "1");
      &ret = &inDoc.AddValue("FORMAT", "DECIMAL");
      &ret = &inDoc.AddValue("PACKAGE", "CUSTOM");
      /* Name must be last, because it may contain commas, and is stripped based on its fieldsize */
      &ret = &inDoc.AddValue("FIELDS", "TICK,LAST,NET,TIME,SIZE,VOLUME,OPEN,HIGH,LOW,CLOSE,BID,ASK,BIDASKSIZE,EXCHANGE,YRHIGH,YRLOW,DIVFREQ,DIVIDEND,EARNINGS,SHARES,PERATIO,DIVDATE,VOLATILITY,YIELD,NAME");

      &EXECRSLT = &STOCKQUOTE_1.Execute();

      If (&EXECRSLT <> 1) Then
         /* The instance failed to execute */
      Else
         /* &outDoc = &STOCKQUOTE_1.GetOutputDocs(""); */

         &RSLT = &STOCKQUOTE_1.FetchNextRow("Response", &stockHTML, "return_status", &RSLT, "return_status_msg", &RSLT_MSG);
         &split_lines = Split(&stockHTML, Char(10));

         For &count = 3 To &split_lines.LEN
            /* The last field in line, name, may contain commas,strip fixed length field before proceeding. */
            If Len(&split_lines [&count]) > 36 Then
               &name = Right(&split_lines [&count], 36);
               /* Strip out last portion including the comma and space (36+1+1) */
               &split_lines [&count] = Left(&split_lines [&count], (Len(&split_lines [&count]) - 38));
               &split_pieces = Split(&split_lines [&count], ",");
               If &split_pieces.LEN = 24 Then /* HANDLE INVALID TICKER SYMBOLS */
                  &tsymbol = LTrim(RTrim(&split_pieces [1]));
                  &price = Value(LTrim(RTrim(&split_pieces [2])));
                  &change = Value(LTrim(RTrim(&split_pieces [3])));
                  &lastTime = TimeValue(LTrim(RTrim(&split_pieces [4])));
                  &size = Value(LTrim(RTrim(&split_pieces [5])));
                  &volume = Value(LTrim(RTrim(&split_pieces [6])));
                  &OPEN = Value(LTrim(RTrim(&split_pieces [7])));
                  &high = Value(LTrim(RTrim(&split_pieces [8])));
                  &low = Value(LTrim(RTrim(&split_pieces [9])));
                  &close = Value(LTrim(RTrim(&split_pieces [10])));
                  &bid = Value(LTrim(RTrim(&split_pieces [11])));
                  &ask = Value(LTrim(RTrim(&split_pieces [12])));
                  &bidAskSize = LTrim(RTrim(&split_pieces [13]));
                  &exchange = LTrim(RTrim(&split_pieces [14]));
                  &yrhigh = Value(LTrim(RTrim(&split_pieces [15])));
                  &yrlow = Value(LTrim(RTrim(&split_pieces [16])));
                  &divfreq = LTrim(RTrim(&split_pieces [17]));
                  &dividend = Value(LTrim(RTrim(&split_pieces [18])));
                  &earnings = Value(LTrim(RTrim(&split_pieces [19])));
                  &shares = Value(LTrim(RTrim(&split_pieces [20])));
                  &peratio = Value(LTrim(RTrim(&split_pieces [21])));
                  If LTrim(RTrim(&split_pieces [22])) <> "00/00/00" Then
                     &divdate = DateValue(LTrim(RTrim(&split_pieces [22])));
                  Else
                     &divdate = %Date;
                  End-If;

                  &volatility = Value(LTrim(RTrim(&split_pieces [23])));
                  &yield = Value(LTrim(RTrim(&split_pieces [24])));


                  AccessStockCI(&tsymbol, &price, &change, &lastTime, &size, &volume, &OPEN, &high, &low, &close, &bid, &ask, &bidAskSize, &exchange, &name, &yrhigh, &yrlow, &divfreq, &dividend, &earnings, &shares, &peratio, &divdate, &volatility, &yield);
               End-If;
            End-If;
         End-For;
      End-If;

   End-If;

   For &K = 1 To &user_ticker_list.len
      /*  &response_string=&response_string | (&user_ticker_list[&K]); */
      &TEMP = &user_ticker_list [&K];

      SQLExec("SELECT SDK_STOCK_TICKER, SDK_STOCK_EXCHANGE, SDK_LAST_TRADE, %DATETIMEOUT(SDK_LASTUPDDTTM), SDK_STOCK_NET_CHG, SDK_LOW_TRADE, SDK_HIGH_TRADE, SDK_STOCKCOMP_NAME FROM PS_SDK_STOCK WHERE SDK_STOCK_TICKER = :1", &TEMP, &tsymbol, &exchange, &price, &thedatetime, &change, &low, &high, &name);


      If (All(&tsymbol) And
            (&price <> 0)) Then
         &response_string = &response_string | ("<tr><td BGCOLOR=""#FFFFFF"" width=""20%"" nowrap> <font class=""PSHYPERLINK"">");

         rem &TMP_URL = Unencode(%Request.RequestURI) | "?ICType=Panel&Menu=PORTAL_COMPONENTS&Market=GBL&PanelGroupName=SDK_STOCK_QUOTE&STOCK_TICKER=" | &tsymbol | "&STOCK_EXCHANGE=" | Substitute(String(&exchange), " ", "%20");
         &TMP_URL = GenerateComponentContentURL(%Portal, %Node, MenuName.SDK_PORTAL_COMPONENTS, "GBL", Component.SDK_STOCK_QUOTE, "", "U") | "&STOCK_TICKER=" | &tsymbol | "&STOCK_EXCHANGE=" | Substitute(String(&exchange), " ", "%20");

         &hoverText = &name | ": Updated " | format2decs(Month(DatePart(&thedatetime))) | "/" | format2decs(Day(DatePart(&thedatetime))) | " at " | format_time(TimePart(&thedatetime), False, False) | " " | %ServerTimeZone;
         &response_string = &response_string | (GetHTMLText(HTML.SDK_HYPERLINK, &TMP_URL, &hoverText, &tsymbol));

         &response_string = &response_string | ("</font></td><td BGCOLOR=""#FFFFFF"" width=""20%"" align=""" | %AlignEnd | """ nowrap>");
         &response_string = &response_string | ("<font CLASS=""PSTCONTENTDESCR"">");
         &response_string = &response_string | (&price);
         &response_string = &response_string | ("</font>");
         &response_string = &response_string | ("</td><td BGCOLOR=""#FFFFFF"" width=""20%"" align=""" | %AlignEnd | """ nowrap>");
         If &change > 0 Then
            &response_string = &response_string | ("<span class=""PSTCONTENTDESCR""> <font color='#008000'>");
         Else
            If &change < 0 Then
               &response_string = &response_string | ("<span class=""PSTCONTENTDESCR""> <font color='#FF0000'>");
            Else
               &response_string = &response_string | ("<span class=""PSTCONTENTDESCR""> <font color='#000000'>");
            End-If;
         End-If;
         &response_string = &response_string | (&change);

         &response_string = &response_string | ("</font></span></td><td BGCOLOR=""#FFFFFF"" width=""20%"" align=""" | %AlignEnd | """ nowrap>");
         &response_string = &response_string | ("<font class=""PSTCONTENTDESCR"">");
         &response_string = &response_string | (&low);

         &response_string = &response_string | ("</font></td><td BGCOLOR=""#FFFFFF"" width=""20%"" align=""" | %AlignEnd | """ nowrap>");
         &response_string = &response_string | ("<font class=""PSTCONTENTDESCR"">");
         &response_string = &response_string | (&high);

         &response_string = &response_string | ("</font></td></tr>");
      End-If;
   End-For;

   /* Write Footer */

   &response_string = &response_string | ("<TR><TD width=""100%"" colspan=""5""><center><font class=""PSTCONTENTDESCR"">Last updated " | format_time(%Time, False, False) | " " | %ServerTimeZone | "." | "</font></center></TD></TR></table></TD></TR></TABLE>");



   &response_string = &response_string | ("<CENTER><font class=""PSTCONTENTDESCR"">" | MsgGetText(18025, 941, "MESSAGE NOT FOUND") | "<br><a href='http://www.myquote.com' target='_top'>Provided by MyQuote.com</a></font></CENTER>");

   %Response.Write(&response_string);

End-Function;

Local ApiObject &oSession, &oCIColl, &oCI;

/*!@brief 
 * Function    : IScript_CIList()
 * Description : Return List of authorized CIs in XMLDoc
 * Input       : Nothing
 * Returns     : Nothing
 */
Function IScript_CIList()
   Local XmlDoc &xDocRoot;
   Local XmlNode &xNodeDocRoot, &xNodeElement;
   Local number &i;

   /*!@brief Get the PeopleSoft session
   */;
   &oSession = %Session;
   &xDocRoot = CreateXmlDoc("");
   &xNodeDocRoot = &xDocRoot.CreateDocumentElement("CI_List");
   &oCIColl = &oSession.FindCompIntfcs("");
   For &i = 1 To &oCIColl.Count
      &oCI = &oCIColl.Item(&i);
      &xNodeElement = &xNodeDocRoot.AddElement(&oCI.compIntfcName);
   End-For;
   /*!@brief Write the Generated XML string to the Response Object
    */
   %Response.Write(&xDocRoot.GenXmlString());
End-Function;

Local SQL &sqlPermList;
Local string &CIMethod, &CIMethods;
Local string &strClassIDList, &CLASSID;
Local boolean &bFirst;
Local number &AMCounter, &j;
Local SQL &sqlCIMethod;
Local array of string &MethodArray, &SOAPMethodArray;

&sqlPermList = GetSQL("SELECT DISTINCT BCMETHOD FROM PSAUTHBUSCOMP WHERE BCNAME = :1 AND CLASSID IN (SELECT CLASSID FROM PS_USERCLASS_VW WHERE OPRID = :2) ORDER BY BCMETHOD ASC ", PSCIWBSRVSVW.BCNAME, %UserId);
&AMCounter = 1;
&MethodArray = CreateArray("", 0);
While &sqlPermList.Fetch(&CIMethod)
   &MethodArray [&AMCounter] = &CIMethod;
   &AMCounter = &AMCounter + 1;
End-While;

&CIMethods = "";
&SOAPMethodArray = CreateArrayRept("", 0);
For &j = 1 To &MethodArray.Len;
   Evaluate &MethodArray [&j]
   When "Create"
      &SOAPMethodArray.Push(&MethodArray [&j]);
      &CIMethods = &CIMethods | "Create,";
   When "Find"
      &SOAPMethodArray.Push(&MethodArray [&j]);
      &CIMethods = &CIMethods | "Find,";
   When "Get"
      If &MethodArray.Find("Save") > 0 Then;
         &SOAPMethodArray.Push("Get");
         &SOAPMethodArray.Push("Update");
         &SOAPMethodArray.Push("UpdateData");
         &CIMethods = &CIMethods | "Get,Update,UpdateData,";
      Else
         &SOAPMethodArray.Push("Get");
         &CIMethods = &CIMethods | "Get,";
      End-If;
   When "Cancel"
      Break;
   When "Save"
      Break;
   When-Other;
      rem *******************************************************************;
      rem * Custom methods are not supported in this release                *;
      rem *******************************************************************;
      Break;
   End-Evaluate;
End-For;
WEBLIB_SOAPTOCI.CIMETHODS = RTrim(&CIMethods, ",");

Local Rowset &Level0, &Level1;
Local string &CIString;
Local ApiObject &oSession, &oCIColl, &oCI;
Local number &i;

&Level0 = GetLevel0();
&Level1 = &Level0(1).GetRowset(Scroll.PSBCDEFN);
&Level1.Flush();
&oSession = %Session;

&oCIColl = &oSession.FindCompIntfcs("%" | WEBLIB_SOAPTOCI.WSNAME | "%");
If &oCIColl.Count > 0 Then
   &CIString = "WHERE BCNAME IN (";
   For &i = 1 To &oCIColl.Count
      &oCI = &oCIColl.Item(&i);
      &CIString = &CIString | "'" | &oCI.compIntfcName | "'" | ",";
   End-For;
   &CIString = RTrim(&CIString, ",") | ")";
   If WEBLIB_SOAPTOCI.DESCR <> "" Then
      &CIString = &CIString | " AND DESCR LIKE '%" | WEBLIB_SOAPTOCI.DESCR | "%'";
   End-If;
   &Level0.Select(Scroll.PSBCDEFN, Record.PSBCDEFN, &CIString);
End-If;

import SOAPTOCI:*;

/*!@brief 
 * Function    : iScript_SOAPToCI
 * Description : Main entry point for IScript
 * Input       : Nothing
 * Returns     : Nothing
 */
Function IScript_SOAPToCI()
   Local string &sXMLIn, &sXMLOut, &sUserID, &sPassword;
   Local SOAPDoc &soapReq;
   Local boolean &bReturn, &bResult;
   Local SOAPTOCI:ExcelToCI &oExcelToCI;
   Local string &sLogoutURL;

   /*!@brief Get the XML from the Request object. Process the XML to create
    * a SOAPDoc. Get the SOAP body and process it
    */
   &sXMLIn = %Request.GetContentBody();
   &sLogoutURL = %Request.LogoutURL;
   If &sXMLIn = "" Then
      &sXMLOut = MsgGetText(91, 71, "No content provided.", "");
   Else
      /*!@brief Create the SOAP Document using the XML from Request
      */
      &soapReq = CreateSOAPDoc();
      &bReturn = &soapReq.ParseXmlString(&sXMLIn);

      /*!@brief Send the SOAP document for processing
       */
      &oExcelToCI = create SOAPTOCI:ExcelToCI();
      &oExcelToCI.processSOAPRequest(&soapReq.BodyNode);
      &sXMLOut = &oExcelToCI.xmlStringResponse;
   End-If;

   /*!@brief Get XML from Response SOAP Doc & return it to Response Object
    */
   %Response.Write(&sXMLOut);
   Return;
End-Function;

import SOAPTOCI:*;

/*!@brief 
 * Description: Creates a WSDL descriptor for SOAP Documents called
 *              through the Integration Broker.
 * Standards  : WSDL: http://www.w3.org/TR/wsdl
 *              SOAP: http://www.w3.org/TR/SOAP
 * Invocation : To be used as a Iscript function called from Browser
 *              see IScript function to see necessary query string
 *              parameters
 */
Local array of string &ParameterArray;
Local array of string &AuthorizedMethods;
Local string &sAPIName, &sNodeName;
Local ApiObject &oSession, &oCIColl, &oCI;
Local number &paramcounter, &j, &k, &h;
Local XmlNode &Debugnode;
Local SOAPTOCI:Utilities &Util;



/*!@brief 
 * Function    : QueryParameterTest()
 * Description : Takes query string parameters to get essential
 *               information 
 * Input       : Parameter array
 *               debug: (not required)
 *                   Values: "yes" - enable debugging information
 *                           "no" - (default)
 *               APIName: (required)
 *                   Values: name of Component Interface
 *               nodeName: (required)
 *                   Values: name of node with SOAPTOCI incoming sync transaction
 *               method: (not required)
 *                   FUTURE, NOT YET IMPLEMENTED
 *               PSFTNamespace:  (not required)
 *                   FUTURE, NOT YET IMPLEMENTED
 *                   (to create WSDL for non-CI API's)
 *               MsgName:  (not required)
 *                   FUTURE, NOT YET IMPLEMENTED
 *                   (to override the SOAPTOCI msg)
 *               RequestingNode:  (not required)
 *                   FUTURE, NOT YET IMPLEMENTED
 *                   (to set the requesting node)
 *               WSDLVersion:  (not required)
 *                   FUTURE, NOT YET IMPLEMENTED
 *                   (for future W3 versions on WSDL)
 * Returns     : True if APIName is found, false otherwise
 */
Function QueryParameterTest(&ParameterArray As array of string) Returns boolean
   If &ParameterArray.Find("debug") > 0 Then;
      /*!@brief Open the Log File
       */
      &Util.Debug = True;
      &Util.openLog("WSDLGenerator");
   End-If;

   /*!@ Test for required parameters and output html error message if
    * required parameters are not there.
    */
   If &ParameterArray.Find("APIName") = 0 Then;
      %Response.Write("APIName is missing: [" | %Request.GetParameter("APIName") | "]");
      Return False;
   End-If;

   If &ParameterArray.Find("nodeName") = 0 Then;
      %Response.Write("nodeName is missing: [" | %Request.GetParameter("nodeName") | "]");
      Return False;
   End-If;

   &sAPIName = %Request.GetParameter("APIName");
   &sNodeName = %Request.GetParameter("nodeName");
   Return True;
End-Function;


/*!@brief
 * Function    : GenerateWSDL()
 * Description : This function creates WSDL descriptions of CI
 *               SOAP documents
 *               Standards used - WSDL 1.1
 * Input       : Name of CI (as String)
 * Returns     : WSDL is an Xml Document
 */
Function GenerateWSDL(&sAPIName As string, &sNodename As string) Returns XmlDoc
   &Util.writeLog("Begin GenerateWSDL(" | &sAPIName | ")");

   Local SOAPTOCI:WSDLSummary &oSummary;

   &oSummary = create SOAPTOCI:WSDLSummary();

   &WSDLDoc = &oSummary.GenerateSummary(&sAPIName, &sNodename);

   Return &WSDLDoc;
End-Function;


/*!@brief 
  * Function    : IScript_WSDLDiscovery()
  * Description : Takes query string parameters to get essential
  *               information
  * Input       : Nothing
  * Returns     : Nothing
  */
Function IScript_WSDLDiscovery()
   /*!@brief Instantiate the Utilities object
    */
   Local XmlDoc &xGeneratedWSDL;

   &Util = create SOAPTOCI:Utilities();

   &ParameterArray = %Request.GetParameterNames();
   If QueryParameterTest(&ParameterArray) Then;

      /*!@Brief 65832600 Empty WSDL is generated for CIs that have no authorized methods.  		Check to see if the WSDL is empty if it is, then throw a message back to the user.*/
      &xGeneratedWSDL = GenerateWSDL(&sAPIName, &sNodeName);
      If Not &xGeneratedWSDL.IsNull Then
         %Response.SetContentType("text/xml");
         %Response.Write(&xGeneratedWSDL.GenFormattedXmlString());
      End-If;
   End-If;


End-Function;

Function IScript_GetExcelFile();
   Local string &sTempString;

   Local string &inFileName = %Request.GetParameter("InputFile");
   Local string &outFileName = %Request.GetParameter("OutputFile");
   Local integer &EnableRowset = Value(%Request.GetParameter("EnableRowset"));

   If %Response.CharSet = "UTF-8" Then
      %Response.Write("<head><meta http-equiv=""content-type"" content=""text/html;charset=UTF-8"" />");
   End-If;
   %Response.Write("<title>" | "Title" | "</title>");
   %Response.Write("<STYLE type=""text/css"">");
   %Response.Write("h3.ss { text-align: center}  </STYLE></head>");

   try
      Local object &ss;
      &ss = CreateObject("PSSpreadsheet");
      If All(&inFileName) And
            All(&outFileName) Then
         If (&EnableRowset = 1) Then
            &ss.Open(&inFileName, True);
         Else
            &ss.Open(&inFileName, False);
         End-If;
         &ss.SaveAs(&outFileName);
      Else
         If (&EnableRowset = 1) Then
            &ss.Open(&outFileName, True);
         Else
            &ss.Open(&outFileName, False);
         End-If;
      End-If;
   catch Exception &e
      Error (MsgGetText(&e.MessageSetNumber, &e.MessageNumber, "Message Not Found %1", &outFileName));
   end-try;

   &qSQL = CreateSQL("SELECT PT_SSAPI_ROWNUM, PT_SSAPI_COLNUM, PT_SSAPI_CELLTYPE, PT_SSAPI_CELLDATA FROM PS_PT_SSAPITST_TBL");
   Local number &idx = 1;

   Local Rowset &rs;
   &rs = CreateRowset(Record.PT_SSAPITST_TBL);
   Local integer &rowNum, &colNum, &cellType;
   Local string &cellData;

   While (&qSQL.Fetch(&rowNum, &colNum, &cellType, &cellData))

      If (&EnableRowset = 1) Then
         If &idx <> 1 Then
            &rs.InsertRow(&rs.ActiveRowCount);
         End-If;

         &rs(&idx).PT_SSAPITST_TBL.PT_SSAPI_ROWNUM.Value = &rowNum;
         &rs(&idx).PT_SSAPITST_TBL.PT_SSAPI_COLNUM.Value = &colNum;
         &rs(&idx).PT_SSAPITST_TBL.PT_SSAPI_CELLDATA.Value = &cellData;
         &rs(&idx).PT_SSAPITST_TBL.PT_SSAPI_CELLTYPE.Value = &cellType;
         &idx = &idx + 1;

      Else

         If (&cellType = 0) Then
            &ss.SetCellNumber(&rowNum, &colNum, Value(&cellData), "0.00");
         End-If;

         If (&cellType = 1) Then
            &ss.SetCellString(&rowNum, &colNum, &cellData);
         End-If;

         If (&cellType = 2) Then
            &ss.SetCellFormula(&rowNum, &colNum, &cellData);
         End-If;

         If (&cellType = 4) Then
            &ss.SetCellHyperlink(&rowNum, &colNum, "http://www.oracle.com");
         End-If;

         /* ICE : 935482 Updated to call SetCellDate() for cell type 6 */

         If (&cellType = 6) Then
            &ss.SetCellDate(&rowNum, &colNum, &cellData, "EN", "UTC", "m/d/yy h:mm:ss AM/PM");
         End-If;

      End-If;

   End-While;

   If (&EnableRowset = 1) Then
      &ss.SetRowSetData(&rs);
   End-If;
   &ss.Save();

   try
      %Response.WriteBinary(&ss.GetFileContent(&outFileName));
   catch Exception &e1
      Error (MsgGetText(&e1.MessageSetNumber, &e1.MessageNumber, "Message Not Found %1", &outFileName));
   end-try;

   %Response.SetContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;");
   Local array of string &arrTemp = Split(&outFileName, "\");
   Local integer &arrLen = &arrTemp.Len;

   &sTempString = "attachment; filename=" | &arrTemp [&arrLen];
   %Response.SetHeader("Content-Disposition", &sTempString);

   Return;

End-Function;

REM ***************************************************************************************;
REM Function:		IScript_OpenSmartView                                   			   ;
REM Purpose:		Opens Oracle Hyperion Smart View in Excel using SSO Token              ;
REM Inputs:												                                   ;
REM Output:				                                                                   ;
REM ***************************************************************************************;

Function IScript_OpenSmartView()
   Local array of string &DimId;
   Local SQL &SQL;

   rem get Run Control Id;
   If %Request.GetParameter("runctl") <> "" Then
      &RunCtl = %Request.GetParameter("runctl");
   End-If;

   rem get outline name;
   If %Request.GetParameter("OtlnId") <> "" Then
      &OtlnId = %Request.GetParameter("OtlnId");
   End-If;

   rem get connection name;
   If %Request.GetParameter("ConnId") <> "" Then
      &ConnId = %Request.GetParameter("ConnId");
   End-If;

   rem get connection settings for run control;
   &SqlStm = "select A.ANALYSIS_DB_SERVER, A.ANL_DB_LOGON_ID, A.CUB_ESSPWD, B.ANALYSIS_DB_APP, B.ANALYSIS_DB_NAME from PSCUBCONNECTID A, PSCUBRUNCNTL B WHERE A.CUB_CONNECTID = B.CUB_CONNECTID AND B.RUN_CNTL_ID = :1 AND B.OPRID = :2 AND B.CUB_OUTLINEID = :3 AND B.CUB_CONNECTID =:4";
   SQLExec(&SqlStm, &RunCtl, %UserId, &OtlnId, &ConnId, &Server, &User, &EncPassword, &ESS_APP, &ESS_DB);
   &Password = Decrypt("PS2Essbase850", &EncPassword);

   rem obtain Single Sign On token via Hyperion Shared Services;
   rem   &CSSConnect_Class = CreateJavaObject("CSSConnect");
   rem  &CSSToken = &CSSConnect_Class.getCSSToken(&User, &Password, &Server);
   rem   &CSSConnect_Class = Null;

   rem get Dimension names for outline to include them in XHTML response;
   &SqlStm2 = "select CUB_DIMENSIONID from PSCUBDIMLIST where CUB_OUTLINEID = :1";
   &SQL = CreateSQL(&SqlStm2, &OtlnId);

   &DimId = CreateArrayRept("", 0); /* creates an empty array of string */
   While &SQL.Fetch(&DimSql)
      &DimId.Push(&DimSql);
   End-While;


   rem *************send XHTML response to browser *****************;

   %Response.Write(GetHTMLText(HTML.SMART_VIEW_HEADER));
   rem   %Response.WriteLine("<SSOToken>" | &CSSToken | "</SSOToken>");
   %Response.WriteLine("<dataSource type=""essbase"" srv=""" | &Server | """ url="""" app=""" | &ESS_APP | """ cube=""" | &ESS_DB | """ form="""" usr=""" | &User | """/>");
   %Response.Write(GetHTMLText(HTML.SMART_VIEW_PREFERENCES));
   %Response.WriteLine("<dim id=""0"" name=""" | &DimId [1] | """ row=""0"" hidden=""0"" expand=""1""/>");
   %Response.WriteLine("<dim id=""1"" name=""" | &DimId [2] | """ col=""0"" hidden=""0"" expand=""1""/>");

   For &i = 3 To &DimId.Len
      %Response.WriteLine("<dim id=""" | (&i - 1) | """ name=""" | &DimId [&i] | """ pov=""" | &DimId [&i] | """ display=""" | &DimId [&i] | """ hidden=""0"" expand=""1""/>");
   End-For;

   %Response.Write(GetHTMLText(HTML.SMART_VIEW_SLICES));
   %Response.WriteLine("<vals>|" | &DimId [1] | "|" | &DimId [2] | "|</vals>");
   %Response.Write(GetHTMLText(HTML.SMART_VIEW_BODY_END));

   Return;
End-Function;

