/*  Get landing page tab list for Unified Navigation   */
/*******************************************************/

Function IScript_RemoteLPTabList

   Local XmlDoc &RemoteTabListDoc = CreateXmlDoc("<?xml version='1.0'?><RemoteLandingPageTabList/>");
   Local XmlNode &rootTabListNode = &RemoteTabListDoc.DocumentElement.AddElement("Tabs");

   Local ApiObject &Portal = %Session.GetPortalRegistry();
   If Not &Portal.Open(%Portal) Then
      Error MsgGet(95, 5021, "Error opening portal: %1.", %Portal);
   End-If;

   Local ApiObject &TabList = &Portal.LandingPage.UserTabs;
   Local ApiObject &TabObj = &TabList.First();
   Local string &url = GenerateComponentContentURL(%Portal, %Node, MenuName.NUI_FRAMEWORK, "GBL", Component.PT_LANDINGPAGE, Page.PT_LANDINGPAGE, "U");

   While &TabObj <> Null
      If &TabObj.TabName = "NAVBAR" Or
            &TabObj.UsageType <> "GRPT" Then
         &TabObj = &TabList.next();
         Continue;
      End-If;
      &url = &url | "&LP=" | &TabObj.TabName;
      &TabNode = &rootTabListNode.AddElement("Tab");
      &TabNode.AddAttribute("name", &TabObj.TabName);
      &TabNode.AddAttribute("label", &TabObj.Label);
      &TabNode.AddAttribute("url", &url);
      &TabObj = &TabList.Next();
   End-While;

   &Portal.close();

   %Response.Write(&RemoteTabListDoc.GenFormattedXmlString());
End-Function;


/************************************************/
/* Get folder/cref information of the given portal   */
/************************************************/

Function IScript_RemoteRegistry

   Local string &UnFolders = Unencode(%Request.GetParameter("UNFLDRS"));
   Local string &UnCrefs = Unencode(%Request.GetParameter("UNCREFS"));
   Local string &UnNodeName = Unencode(%Request.GetParameter("UNNODE"));
   Local string &FldrXML, &CrefXML;

   Local XmlDoc &RemRegistry = CreateXmlDoc("<?xml version='1.0'?><RemotePortalRegistry/>");
   Local XmlNode &rootFldrNode = &RemRegistry.DocumentElement.AddElement("Folders");
   Local XmlNode &rootCrefNode = &RemRegistry.DocumentElement.AddElement("Crefs");

   Local ApiObject &Portal = %Session.GetPortalRegistry();
   If Not &Portal.Open(%Portal) Then
      Error MsgGet(95, 5021, "Error opening portal: %1.", %Portal);
   End-If;

   &FolderList = Split(&UnFolders, ",");
   For &j = 1 To &FolderList.len
      &folderName = Split(&FolderList [&j], ":");
      If (&folderName.len >= 1) Then
         If &UnNodeName = &folderName [1] Then
            If Find(&FolderList [&j], &UnCrefs) = 0 Then
               Local ApiObject &RootFolder = &Portal.FindFolderByName(&folderName [2]);
               Local ApiObject &folders = &RootFolder.Folders;
               Local ApiObject &folder = &folders.first();
               While &folder <> Null
                  If &folder.Authorized And
                        &folder.IsVisible Then
                     &candidatesNode = &rootFldrNode.AddElement("Folder");
                     &candidatesNode.AddAttribute("name", &folder.Name);
                     &candidatesNode.AddAttribute("label", &folder.Label);
                     &candidatesNode.AddAttribute("contentProvider", &UnNodeName);
                     &candidatesNode.AddAttribute("parentName", &folder.ParentName);
                     If (&folder.ParentName <> Null And
                           &folder.ParentName <> "PORTAL_ROOT_OBJECT") Then
                        Local ApiObject &GPFolder1 = &Portal.FindFolderByName(&folder.ParentName);
                        &candidatesNode.AddAttribute("gParentName", &GPFolder1.ParentName);
                        &candidatesNode.AddAttribute("gParentLbl", &GPFolder1.Label);
                     Else
                        &candidatesNode.AddAttribute("gParentName", "");
                        &candidatesNode.AddAttribute("gParentLbl", "");
                     End-If;
                  End-If;

                  &folder = &folders.next();
               End-While;
               Local ApiObject &crefs = &RootFolder.ContentRefs;
               Local ApiObject &cref = &crefs.first();
               While &cref <> Null
                  If &cref.Authorized And
                        &cref.IsVisible Then
                     rem  &CrefXML = &CrefXML | GetHTMLText(HTML.PTUN_REMCREFXML, &cref.Name, &cref.Label, &cref.AbsolutePortalURL, &cref.AbsoluteContentURL);
                     &candidatesNode1 = &rootCrefNode.AddElement("ContentRef");
                     &candidatesNode1.AddAttribute("absoluteContentURL", &cref.AbsoluteContentURL);
                     &candidatesNode1.AddAttribute("absolutePortalURL", &cref.AbsolutePortalURL);
                     &candidatesNode1.AddAttribute("label", &cref.Label);
                     &candidatesNode1.AddAttribute("name", &cref.Name);
                     &candidatesNode1.AddAttribute("contentProvider", &UnNodeName);
                     &candidatesNode1.AddAttribute("parentName", &cref.ParentName);
                     If (&cref.ParentName <> Null And
                           &cref.ParentName <> "PORTAL_ROOT_OBJECT") Then
                        Local ApiObject &GPFolder2 = &Portal.FindFolderByName(&cref.ParentName);
                        &candidatesNode1.AddAttribute("gParentName", &GPFolder2.ParentName);
                        &candidatesNode1.AddAttribute("gParentLbl", &GPFolder2.Label);

                     Else
                        &candidatesNode1.AddAttribute("gParentName", "");
                        &candidatesNode1.AddAttribute("gParentLbl", "");
                     End-If;
                  End-If;
                  &cref = &crefs.next();
               End-While;
            End-If;
         End-If;
      End-If;
   End-For;

   &CrefList = Split(&UnCrefs, ",");
   For &jj = 1 To &CrefList.len
      &CrefName = Split(&CrefList [&jj], ":");
      If (&CrefName.len >= 1) Then
         If &UnNodeName = &CrefName [1] Then
            Local ApiObject &CrefObject = &Portal.FindCrefByName(&CrefName [3]);
            If &CrefObject.Authorized And
                  &CrefObject.IsVisible Then
               rem  &CrefXML = &CrefXML | GetHTMLText(HTML.PTUN_REMCREFXML, &CrefObject.Name, &CrefObject.Label, &CrefObject.AbsolutePortalURL, &CrefObject.AbsoluteContentURL);
               &candidatesNode2 = &rootCrefNode.AddElement("ContentRef");
               &candidatesNode2.AddAttribute("absoluteContentURL", &CrefObject.AbsoluteContentURL);
               &candidatesNode2.AddAttribute("absolutePortalURL", &CrefObject.AbsolutePortalURL);
               &candidatesNode2.AddAttribute("label", &CrefObject.Label);
               &candidatesNode2.AddAttribute("name", &CrefObject.Name);
               &candidatesNode2.AddAttribute("contentProvider", &UnNodeName);
               &candidatesNode2.AddAttribute("parentName", &CrefObject.ParentName);

               If (&CrefObject.ParentName <> Null) And
                     (&CrefObject.ParentName <> "PORTAL_ROOT_OBJECT") Then
                  Local ApiObject &GPFolder3 = &Portal.FindFolderByName(&CrefObject.ParentName);
                  &candidatesNode2.AddAttribute("gParentName", &GPFolder3.ParentName);
                  &candidatesNode2.AddAttribute("gParentLbl", &GPFolder3.Label);

               Else
                  &candidatesNode2.AddAttribute("gParentName", "");
                  &candidatesNode2.AddAttribute("gParentLbl", "");
               End-If;

            End-If;
         End-If;
      End-If;
   End-For;

   rem  &RemRegistry = CreateXmlDoc(GetHTMLText(HTML.PTUN_REGISTRYXML, %Portal, &FldrXML, &CrefXML));
   &Portal.close();

   %Response.Write(&RemRegistry.GenFormattedXmlString());
End-Function;

Declare Function PortalOpen PeopleCode FUNCLIB_PORTAL.PORTAL_GEN_FUNC FieldFormula;

Function IScript_RemoteCref


   &SEARCH_KEYWORD = EscapeHTML(%Request.GetParameter("key"));
   &SearchCateg = EscapeHTML(%Request.GetParameter("categ"));
   &PGLTYPE = "'PORTAL_GROUPLETS'";
   &PORTAL = %Portal;
   &Where = "";
   If (&SearchCateg <> "CE") Then
      If All(&SEARCH_KEYWORD) Then
         &SEARCH_KEYWORD = "%" | Upper(&SEARCH_KEYWORD) | "%";
      Else
         &SEARCH_KEYWORD = "%";
      End-If;
   End-If;

   If (&SearchCateg = "C") Then
      If (%Language_Base = %Language) Then
         &Where = "WHERE PORTAL_PRNTOBJNAME IN (SELECT PORTAL_OBJNAME FROM PSPRSMDEFN WHERE upper(PORTAL_LABEL) LIKE :1 AND PORTAL_NAME = :2 AND PORTAL_REFTYPE='F' AND PORTAL_PRNTOBJNAME = 'PORTAL_GROUPLETS') AND PORTAL_REFTYPE='C' AND (PORTAL_CREF_USGT = 'TARG' OR PORTAL_CREF_USGT = 'LINK')  AND PORTAL_NAME  = :2";
      Else
         &Where = "WHERE PORTAL_PRNTOBJNAME IN (SELECT PORTAL_OBJNAME FROM PSPRSMDEFNLANG WHERE upper(PORTAL_LABEL) LIKE :1 AND PORTAL_NAME = :2 AND PORTAL_REFTYPE='F') AND PORTAL_REFTYPE='C' AND (PORTAL_CREF_USGT = 'TARG' OR PORTAL_CREF_USGT = 'LINK') AND PORTAL_NAME  = :2";
      End-If;
   Else
      If (&SearchCateg = "L") Then
         &Where = "WHERE PORTAL_PRNTOBJNAME IN (SELECT PORTAL_OBJNAME FROM PSPRSMDEFN WHERE PORTAL_NAME = :2 AND PORTAL_REFTYPE='F' AND PORTAL_PRNTOBJNAME = 'PORTAL_GROUPLETS') AND PORTAL_REFTYPE='C' AND (PORTAL_CREF_USGT = 'TARG' OR PORTAL_CREF_USGT = 'LINK') AND PORTAL_NAME  = :2 AND upper(PORTAL_LABEL) LIKE :1";
      End-If;
   End-If;

   If (&SearchCateg = "CL") Then
      &Where = "WHERE PORTAL_PRNTOBJNAME = 'PORTAL_GROUPLETS' AND PORTAL_REFTYPE='F' AND PORTAL_NAME  = :1";
   End-If;

   If (&SearchCateg = "CE") Then
      &Where = "WHERE PORTAL_PRNTOBJNAME = :1 AND PORTAL_REFTYPE='C' AND PORTAL_CREF_USGT = 'TARG' AND PORTAL_NAME  = :2";
   End-If;


   If (&SearchCateg = "C") Then
      &rsPageletList = CreateRowset(Record.PTUN_GRPLTSRCH);
      &rsPageletList.Flush();
      If (%Language_Base = %Language) Then
         &REC = &rsPageletList.fill(&Where, &SEARCH_KEYWORD, &PORTAL);
      End-If;
   Else
      If (&SearchCateg = "L") Then
         &rsPageletList = CreateRowset(Record.PTUN_GRPLTSRCH);
         &rsPageletList.Flush();
         &REC = &rsPageletList.fill(&Where, &SEARCH_KEYWORD, &PORTAL);
      Else
         If (&SearchCateg = "CL") Then
            &rsPageletList = CreateRowset(Record.PTUN_GRPLTSRCH);
            &rsPageletList.Flush();
            &REC = &rsPageletList.fill(&Where, &PORTAL);
         Else
            If (&SearchCateg = "CE") Then
               &rsPageletList = CreateRowset(Record.PTUN_GRPLTSRCH);
               &rsPageletList.Flush();
               &REC = &rsPageletList.fill(&Where, &SEARCH_KEYWORD, &PORTAL);
            End-If;
         End-If;
      End-If;
   End-If;

   Local XmlDoc &RemRegistry = CreateXmlDoc("<?xml version='1.0'?><RemotePortalRegistry/>");
   Local XmlNode &rootCrefNode;

   If (&SearchCateg = "CL") Then
      &rootCrefNode = &RemRegistry.DocumentElement.AddElement("CategoryList");
   Else
      &rootCrefNode = &RemRegistry.DocumentElement.AddElement("Crefs");
   End-If;
   &PortalObj = PortalOpen();

   For &j = 1 To &rsPageletList.ActiveRowCount
      &row = &rsPageletList.GetRow(&j);
      &REC = &row.GetRecord(1);

      If All(&REC.PORTAL_OBJNAME.Value) Then

         If (&SearchCateg = "CL") Then
            &candidatesNode = &rootCrefNode.AddElement("Category");
            &candidatesNode.AddAttribute("name", &REC.PORTAL_OBJNAME.Value);
            &candidatesNode.AddAttribute("label", &REC.PORTAL_LABEL.Value);
         Else
            &CRef = &PortalObj.FindCrefByName(&REC.PORTAL_OBJNAME.Value);

            If &CRef.Authorized Or
                  &CRef.AuthorAccess Then
               &candidatesNode = &rootCrefNode.AddElement("ContentRef");
               &candidatesNode.AddAttribute("name", &REC.PORTAL_OBJNAME.Value);
               &candidatesNode.AddAttribute("label", &REC.PORTAL_LABEL.Value);
               &candidatesNode.AddAttribute("contentProvider", &REC.PORTAL_CNTPRV_NAM.Value);
               &candidatesNode.AddAttribute("parentName", &REC.PORTAL_PRNTOBJNAME.Value);
               &candidatesNode.AddAttribute("parentLabel", &REC.PORTAL_LABEL1.Value);
            End-If;
         End-If;
      End-If;

   End-For;
   &PortalObj.Close();
   %Response.Write(&RemRegistry.GenFormattedXmlString());

End-Function;

import WS_INTERFACE:FieldMapping:IndvToPSMapping;
import WS_INTERFACE:FieldMapping:IndvToTNMapping;
import WS_INTERFACE:FieldMapping:PayToPSMapping;
import WS_INTERFACE:FieldMapping:PayToTNMapping;
import WS_INTERFACE:FieldMapping:VisaToPSMapping;
import WS_INTERFACE:FieldMapping:VisaToTNMapping;
import WS_INTERFACE:FieldMapping:FicaToPSMapping;
import WS_INTERFACE:FieldMapping:BaseFieldMapping;
import WS_INTERFACE:Messaging:Request;
import WS_INTERFACE:Messaging:Response;
import WS_INTERFACE:Messaging:Session;
import WS_INTERFACE:Messaging:ReadRows;
import WS_INTERFACE:Messaging:SendRows;
import WS_INTERFACE:Messaging:Export;

Function IScript_Import
   Local Record &versionRec;
   Local string &company;
   Local string &accessDBName;
   Local string &fileLayoutType;
   Local SQL &sql;
   Local XmlNode &nodeCompany;
   Local number &rowcount;
   Local number &x;
   Local number &y;
   Local boolean &dbUpdateResult;
   Local WS_INTERFACE:Messaging:Request &req = create WS_INTERFACE:Messaging:Request();
   Local WS_INTERFACE:Messaging:Response &response = create WS_INTERFACE:Messaging:Response();
   Local WS_INTERFACE:Messaging:Session &session;
   Local WS_INTERFACE:Messaging:ReadRows &readRows;
   Local WS_INTERFACE:Messaging:SendRows &sendRows;
   Local WS_INTERFACE:Messaging:Export &export;

   try;
      /* Read the request XML document into an XML object */
      &req.loadRequest(%Request.GetContentBody());
      If Not &req.isXMLValid Then;
         &response.SendError("Invalid request document: " | &req.RawRequest);
         Return;
      End-If;

      If Not &req.isActionFound Then;
         &response.SendError("Action not found in document");
         Return;
      End-If;

   catch Exception &parseException;
      /* Handle the special case that the client didn't send XML or sent invalid XML */
      &response.SendError(&parseException.ToString());
      Return;
   end-try;

   try;
      /* Report the action back for debugging purposes */
      &response.RequestAction = &req.Action;
      Evaluate Upper(&req.Action)
         /*
          Handle the Ping action
         */
      When = "PING"
         &versionRec = CreateRecord(Record.WS_INTRFC_VER);
         /* generates a Select statement and reads the data for one row into this object */
         &versionRec.SelectByKey();
         /* copy the data from the object into nodes in the XML document */
         &response.Version = &versionRec.WS_INTRFC_VERSION.Value | "." | &versionRec.WS_BUILD_NUM.Value;
         &versionRec = CreateRecord(Record.PSOPTIONS);
         &versionRec.SelectByKey();
         &response.Longname = &versionRec.LONGNAME.Value;
         &response.Shortname = &versionRec.SHORTNAME.Value;
         &response.SystemType = &versionRec.SYSTEMTYPE.Value;
         &sql = CreateSQL("SELECT COMPANY, WS_TN_DB_NAME, WS_FILE_LAYOUT FROM %Table(:1)", Record.WS_INSTALLATION);
         While &sql.Fetch(&company, &accessDBName, &fileLayoutType)
            &response.AddCompany(&company, &accessDBName, &fileLayoutType);
         End-While;
         &sql.Close();
         Break;
      When = "CHECK"
         SQLExec("SELECT COUNT(*) FROM %Table(:1) WHERE WS_IMP_PROCESS = 'R'", Record.WS_INDV_EXP_TAO, &rowcount);
         &response.IndvExportCount = String(&rowcount);
         SQLExec("SELECT COUNT(*) FROM %Table(:1) WHERE WS_IMP_PROCESS = 'R'", Record.WS_1042_EXP_TAO, &rowcount);
         &response.PayExportCount = String(&rowcount);
         SQLExec("SELECT COUNT(*) FROM %Table(:1) WHERE WS_IMP_PROCESS = 'R'", Record.WS_VISA_EXP_TAO, &rowcount);
         &response.VisaExportCount = String(&rowcount);
         /* Added the Companies so that we know what databases to check on the TN side */
         &sql = CreateSQL("SELECT COMPANY, WS_TN_DB_NAME, WS_FILE_LAYOUT FROM %Table(:1)", Record.WS_INSTALLATION);
         While &sql.Fetch(&company, &accessDBName, &fileLayoutType)
            &response.AddCompany(&company, &accessDBName, &fileLayoutType);
         End-While;
         &sql.Close();
         Break;
      When = "READROWS"
         &readRows = create WS_INTERFACE:Messaging:ReadRows();
         If &req.IsIndividualData Then;
            &response.map = create WS_INTERFACE:FieldMapping:IndvToTNMapping();
            &readRows.RecordName = Record.WS_INDV_EXP_TAO;
         End-If;
         If &req.IsPaymentData Then;
            &response.map = create WS_INTERFACE:FieldMapping:PayToTNMapping();
            &readRows.RecordName = Record.WS_1042_EXP_TAO;
         End-If;
         If &req.IsVisaData Then;
            &response.map = create WS_INTERFACE:FieldMapping:VisaToTNMapping();
            &readRows.RecordName = Record.WS_VISA_EXP_TAO;
         End-If;
         &readRows.request = &req;
         &readRows.response = &response;
         &readRows.run();
         Break;
      When = "SENDROWS"
         If Not &req.ContainsRows Then;
            &response.SendError("Rows not found in document");
            Return;
         End-If;
         If Not &req.ContainsDataType Then;
            &response.SendError("Data Type not found in document -- add the dataType element");
            Return;
         End-If;
         &sendRows = create WS_INTERFACE:Messaging:SendRows();
         If &req.IsIndividualData Then;
            &sendRows.recName = Record.WS_INDV_IMPORT;
            &sendRows.map = create WS_INTERFACE:FieldMapping:IndvToPSMapping();
         End-If;
         If &req.IsPaymentData Then;
            &sendRows.recName = Record.WS_1042_IMPORT;
            &sendRows.map = create WS_INTERFACE:FieldMapping:PayToPSMapping();
         End-If;
         If &req.IsVisaData Then;
            &sendRows.recName = Record.WS_VISA_IMPORT;
            &sendRows.map = create WS_INTERFACE:FieldMapping:VisaToPSMapping();
         End-If;
         If &req.IsFicaData Then;
            &sendRows.recName = Record.WS_FICA_IMPORT;
            &sendRows.map = create WS_INTERFACE:FieldMapping:FicaToPSMapping();
         End-If;
         &sendRows.req = &req;
         &sendRows.Send();
      When = "PREPARE"
         &session = create WS_INTERFACE:Messaging:Session();
         &session.Company = &req.GetCompany();
         &session.prepare();
         &response.SessionNumber = &session.SessionNumber;
      When = "PROCESS"
         &session = create WS_INTERFACE:Messaging:Session();
         &session.SessionNumber = &req.SessionNumber;
         &session.setDataType(&req);
         &session.process();
         &response.ProcessInstance = &session.ProcessInstance;
      When = "EXPORT"
         &export = create WS_INTERFACE:Messaging:Export();
         &export.Company = &req.CompanyForExport;
         &export.TaxNavDBName = &req.TaxNavDBName;
         &export.setDataType(&req);
         &export.scheduleExport();
         &response.ProcessInstance = &export.ProcessInstance;
         &response.NextCompanyToExport = &export.getNextCompany();
         SQLExec("SELECT WS_FILE_LAYOUT FROM %Table(:1) WHERE COMPANY = :2", Record.WS_INSTALLATION, &export.Company, &fileLayoutType);
         &response.layoutType = &fileLayoutType;
      When = "EXPORT_STATUS"
         &export = create WS_INTERFACE:Messaging:Export();
         &export.ProcessInstance = &req.ProcessInstance;
         &response.ProcessStatus = &export.ProcessStatus;
         &response.IsProcessComplete = &export.IsProcessComplete;
         &response.IsProcessErred = &export.IsProcessErred;
      When-Other;
         &response.SendError("Invalid Action: " | &req.Action);
         Return;
      End-Evaluate;
   catch Exception &processException;
      /* report any error that may have occurred */
      &response.SendError(&processException.ToString());
      Return;
   end-try;

   &response.Send();
End-Function;

Local string &xmlString;
Local SQL &GetServiceInfo;

Function IScript_GetServiceInfo

   &CRLF = Char(13) | Char(10);
   &TAB = Char(9);

   &service = EscapeHTML(%Request.GetParameter("service"));
   /* Get all services when none is given by user */
   If &service = "" Then
      &GetServiceInfo = CreateSQL("SELECT SERVICENAME, VERSION_CHAR FROM PS_XMLSERVICEINFO ORDER BY SERVICENAME");
      While (&GetServiceInfo.Fetch(&servicename, &version))
         %Response.Write(&servicename | &CRLF);
      End-While;
   Else
      &GetServiceInfo = CreateSQL("SELECT XMLLINKDTD FROM PS_XMLSERVICEINFO WHERE SERVICENAME=:1 ", &service);
      &ret = &GetServiceInfo.Fetch(&xmldtd);
      If &xmldtd = "" Then
         &str = "DTD for service " | &service | " is not provided";
         %Response.Write(&str);
      Else
         %Response.Write(&xmldtd);
      End-If;
   End-If;
   &GetServiceInfo.Close();
End-Function;


Function IScript_GetpCodeFunctionInfo
   &CRLF = Char(13) | Char(10);
   &TAB = Char(9);
   &GetServiceInfo = CreateSQL("SELECT SERVICENAME,RECORDNAME,RECFIELDNAME,EVENT_XMLFUNC,PCODEFUNCTIONNAME , ACCESS_ST FROM PS_XMLSERVICEINFO ORDER BY SERVICENAME");
   While (&GetServiceInfo.Fetch(&servicename, &recordname, &fieldname, &eventname, &pcodename, &access))
      &pcodemapstring = &recordname | "." | &fieldname | "." | &eventname | "." | &pcodename;
      %Response.Write(&servicename | &TAB | &pcodemapstring | &TAB | &access | &CRLF);
   End-While;
   &GetServiceInfo.Close();

End-Function;

REM ***************************************************************************************;
REM Function:		IScript_GetReport								  ;
REM Purpose:		Generate HTML page for Report Notification                             ;
REM Inputs:												  ;
REM Output:				                                                         ;
REM ***************************************************************************************;

Function IScript_LauchXslMapper()
   &XsltName = %Request.GetParameter("XsltName");
   &EffDt = %Request.GetParameter("EffDt");
   &HomeUrl = %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort;
   &XsltUrl = %Request.GetParameter("XsltUrl");
   /* get gateway connect url */
   SQLExec("select CONNURL from psgateway where conngatewayid = :1", "LOCAL", &sGW_URL);
   &sConnUrl = Substitute(&sGW_URL, "PeopleSoftListeningConnector", "HttpListeningConnector");

   If All(&XsltUrl) Then
      &XsltUrl = &sConnUrl | "?Operation=PSXP_GETXSLT&TmplID=" | %Request.GetParameter("XsltUrl") | "&EffDate=" | &EffDt;
   Else
      &XsltUrl = "?";
   End-If;

   &SrcXSD = &sConnUrl | "?Operation=PSXP_GETSRCSCHEMA&RptID=" | %Request.GetParameter("SrcXSD");
   &TgtXSD = &sConnUrl | "?Operation=PSXP_GETSCHEMA&TmplID=" | %Request.GetParameter("TgtXSD") | "&EffDate=" | &EffDt;
   &SaveXSL = &sConnUrl | "?Operation=PSXP_SAVEXSLT&TmplID=" | %Request.GetParameter("SaveXSLT") | "&EffDate=" | &EffDt;


   /* Get SiteName*/
   &siteName = Substring(%Request.PathInfo, 1, Find("/", %Request.PathInfo, 2) - 1);

   &sUrl = &HomeUrl | &siteName;
   %Response.SetContentType("application/x-java-jnlp-file");
   &HTML = GetHTMLText(HTML.PTXMLPJNLP, MsgGetText(235, 3285, "Launch Oracle XSL Mapper"), MsgGetText(235, 3286, "PeopleSoft PeopleTools"), &sUrl, &XsltName, &XsltUrl, &SrcXSD, &TgtXSD, &SaveXSL);
   %Response.Write(&HTML);

End-Function;

REM ***************************************************************************************;
REM Function:		IScript_GetReport								                       ;
REM Purpose:		Generate HTML page for the XSLT Builder                                ;
REM Inputs:												                                   ;
REM Output:				                                                                   ;
REM ***************************************************************************************;

Function IScript_LaunchXslMapper()
   &XsltName = %Request.GetParameter("XsltName");
   &HomeUrl = %Request.Scheme | "://" | %Request.ServerName | ":" | %Request.ServerPort;
   &inXSLT = %Request.GetParameter("InXSLT");

   /* get gateway connect url */
   SQLExec("select CONNURL from psgateway where conngatewayid = :1", "LOCAL", &sGW_URL);
   &sServUrl = Substitute(&sGW_URL, "PeopleSoftListeningConnector", "PeopleSoftServiceListeningConnector");
   &sHttpUrl = Substitute(&sGW_URL, "PeopleSoftListeningConnector", "HttpListeningConnector");

   If All(&inXSLT) Then
      &XsltUrl = &sHttpUrl | "?Operation=GETXSLT&program=" | %Request.GetParameter("InXSLT");
   Else
      &XsltUrl = "?";
   End-If;
   &SrcXSD = &sServUrl | "/" | %Request.GetParameter("SrcXSD");
   &TgtXSD = &sServUrl | "/" | %Request.GetParameter("TgtXSD");
   &SaveXSL = &sHttpUrl | "?Operation=SAVEXSLT&program=" | %Request.GetParameter("OutXSLT");


   /* Get SiteName*/
   &siteName = Substring(%Request.PathInfo, 1, Find("/", %Request.PathInfo, 2) - 1);

   &sUrl = &HomeUrl | &siteName;
   %Response.SetContentType("application/x-java-jnlp-file");
   &HTML = GetHTMLText(HTML.PTXSLTMAPPER, MsgGetText(235, 3285, "Launch Oracle XSL Mapper"), MsgGetText(235, 3286, "PeopleSoft PeopleTools"), &sUrl, &XsltName, &XsltUrl, &SrcXSD, &TgtXSD, &SaveXSL);
   %Response.Write(&HTML);
End-Function;
